INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'the eight levels of faith', 'pp. 5-10', '["The Chapter of Faith", "The Book of Guardianship", "A mention of the distinction between faith and Islam, and what falls under each, and a mention of otherwise."]');
