INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'parents, kin, and the neighbor at your side', 'pp. 25-30', '["Mentioning the affection of the believers for one another and related matters.", "Mentioning the righteousness owed to spiritual and physical parents, and related matters.", "Mentioning the affection owed to religious and worldly relatives and related matters.", "Mentioning the affection owed to religious and worldly neighbors, what is prohibited, and related matters.", "These are the deeds of a people whose hearts Allah has tested with piety."]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'what must be learned, what must be concealed', 'pp. 30-34', '["He mentioned the desires, the pursuit of knowledge, the Qur''an, and related matters.", "Mention of what must be learned, what one desires to know, what one refuses to articulate, and related matters.", "Mention of the prohibition of analogy in religion", "Mention of the command to conceal knowledge, secrets, religion, and piety."]');
