INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'major impurity and the cleanliness of things', 'pp. 49-58', '["Mentioning ghusl from janabah", "Mentioning the purity of bodies, garments, the earth, carpets, and the like"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'tooth-stick, dust, and the purity of food', 'pp. 58-66', '["Mention of Siwak", "Remembrance of Tayammum", "All who could not find soil —", "Even if nothing visible clings to them, whatever dust may be present suffices for the purpose.", "On the Purity of Foods and Drinks"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'bodies, hair, and the reform of custom', 'pp. 66-77', '["On the Matters of Natural Cleanliness and Purity", "It is never permissible to transgress it, for it is within the limits of God Almighty — the Arbitrator, blessed"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'skins, blood, and waiting periods', 'pp. 77-87', '["Mentioning the purity of skin, bones, hair, and wool", "Menstruation and Postpartum", "The woman in her postpartum period sits for as long as her menstruation", "If her blood goes on too long", "I have been waiting for the equivalent of two months", "Then she continued as things were during those two times", "A wall was cleansed, greeting", "From prayer and fasting after"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'the pillar of religion and its appointed hours', 'pp. 87-102', '["The Book of Prayer", "On the Virtues of Prayer, What Is Forbidden in It, and Related Matters", "On the Mention of Prayer Times and Related Matters"]');
