INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'what the worshipper wears and stands upon', 'pp. 157-162', '["Mentioning dress in prayer and what the worshipper prostrates upon"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'friday and the two festivals', 'pp. 162-170', '["On the Friday Prayer", "Mention of the Two Eid Prayers"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'forgetting, doubting, and beginning again', 'pp. 170-181', '["Mention of the Prayer of Omission", "Scanned with CamScanner", "Scanned with CamScanner", "Scanned with CamScanner", "Scanned with CamScanner", "Mention of What Interrupts Prayer", "Scanned with CamScanner", "Mention of the Prayer of One Who Has Been Preceded in Some Rakʿahs"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'children, travelers, and the sick', 'pp. 181-193', '["Mention of the Age at Which Boys Are Commanded to Pray", "Mention of the Traveller''s Prayer", "Scanned with CamScanner", "On the Prayer of the Sick"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'eclipse, fear, rain, and the night vigil', 'pp. 193-206', '["On the Eclipse Prayer", "On the Prayer of Fear", "On the Istisqāʾ Prayer", "On the Prayers of al-Witr and Fajr and the Qunūt", "The thread of prayer may be broken by the salutation", "Without any actions or words.", "If one must speak, there is no harm in that, unless the speech is prolonged.", "Remembrance of Sunnah and Nafl Prayers"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'the sickbed and the sound of mourning', 'pp. 206-213', '["Mention of the Command to Remember Death and Related Matters", "Some of you have read in the book *Arkān al-Islām* the words of its author,"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'washing, shrouding, carrying, burying', 'pp. 214-224', '["On the washing of the dead and related matters", "On mummification and the shroud", "On the funeral procession", "On the funeral prayer", "Dhikr al-Dafn wa''l-Qubūr"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'the wealth that is not yours', 'pp. 224-228', '["Book of Zakāt", "Mentioning the intentions in giving zakāt and related matters", "Mentioning the hardening and the making of zakāt"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'gold, herds, and harvest', 'pp. 228-239', '["Mentioning Zakāt on Gold, Silver, and Jewels", "Mentioning Zakat on Livestock", "Mentioning Zakat on Grains, Fruits, and Plants"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'the charity of the head', 'pp. 239-243', '["Mention of Zakat al-Fitr"]');
