INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'the quarrel over the crescent', 'pp. 246-256', '["On the sighting of the crescent moon — what has been said about it and its established course", "It is established that Sha''ban had passed and the month of Ramadan had not yet begun, and the book aligns with this."]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'two kinds of sight', 'pp. 256-271', '["In the name of God, the Merciful, the Compassionate — and in Him I place my trust.", "Straight Line Breaker", "Medium of poison", "For the Meridian Line", "Cut it off", "Tangent line of a straight", "Circle for Straight Line", "Straight Line Sections"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('isaf-al-talib', 'the sun, the moon, and the order of obedience', 'pp. 271-289', '["This being so, and since the pillars of Islam are entrusted to those who preserve them,"]');
