INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'blurb', NULL, 'Is''af al-Talib fi Jami'' al-Matalib', 0, NULL, 'Isaf al-Talib fi Jami al-Matalib is a work of religious instruction, written as a continuous treatise in the voice of its author, who addresses the reader directly as one who seeks and who speaks as one who has gathered. No name for that author is recorded here, and this edition does not supply one.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib', 'isaf al talib fi jami al matalib is a work of religious instruction written as a continuous treatise in the voice of its author who addresses the reader directly as one who seeks and who speaks as one who has gathered no name for that author is recorded here and this edition does not supply one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'introduction to the book', 'Introduction to the Book', 0, NULL, 'Isaf al-Talib fi Jami al-Matalib is a work of religious instruction, written as a continuous treatise in the voice of its author, who addresses the reader directly as one who seeks and who speaks as one who has gathered. No name for that author is recorded here, and this edition does not supply one.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib introduction to the book', 'isaf al talib fi jami al matalib is a work of religious instruction written as a continuous treatise in the voice of its author who addresses the reader directly as one who seeks and who speaks as one who has gathered no name for that author is recorded here and this edition does not supply one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'introduction to the book', 'Introduction to the Book', 1, NULL, 'The book begins where belief begins, with the eight levels of faith, and with three questions put by the King of Rum. From there it turns to the conduct that faith requires: the greeting of peace and its grammar, the standing of guardians and the limits of praise, the claims of parents, of kin, and of the neighbor at one''s side, and what a person must learn and what a person must conceal. The larger part of the book is then given to practice. Purification comes first — water, intention, the washing place, major ritual impurity, the cleanliness of bodies and things — and after it prayer, in its hours, its call, its place, its leader, its shape, its lapses, and its forms for the sick, the traveler, the eclipse, and the night vigil. Burial follows, then the wealth that is not yours, then fasting and the quarrel over the crescent.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib introduction to the book', 'the book begins where belief begins with the eight levels of faith and with three questions put by the king of rum from there it turns to the conduct that faith requires the greeting of peace and its grammar the standing of guardians and the limits of praise the claims of parents of kin and of the neighbor at ones side and what a person must learn and what a person must conceal the larger part of the book is then given to practice purification comes first water intention the washing place major ritual impurity the cleanliness of bodies and things and after it prayer in its hours its call its place its leader its shape its lapses and its forms for the sick the traveler the eclipse and the night vigil burial follows then the wealth that is not yours then fasting and the quarrel over the crescent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'introduction to the book', 'Introduction to the Book', 2, NULL, 'The text cites earlier books by short names, and the reader should note that the same short name may serve more than one work: Mukhtasar stands for both Mukhtasar al-Musannaf and Mukhtasar al-Athar, and al-Daaim for Daaim al-Islam, which is not Tawil al-Daaim.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib introduction to the book', 'the text cites earlier books by short names and the reader should note that the same short name may serve more than one work mukhtasar stands for both mukhtasar al musannaf and mukhtasar al athar and al daaim for daaim al islam which is not tawil al daaim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 0, NULL, 'Through Him I seek help, upon Him I rely, and He is sufficient for me.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'through him i seek help upon him i rely and he is sufficient for me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 1, NULL, 'Sayingوَبِهِ نَسْتَعِينُ وَعَلَيْهِ أَتَوَكَّلُ وَهُوَ حَسْبِي وَكَفَى وَمَا تَوْفِيقِي إِلَّا بِاللَّهِ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ وَأُفَوِّضُ أَمْرِي إِلَى اللَّهِ إِنَّ اللَّهَ بَصِيرٌ بِالْعِبَادِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ', '', 'وَبِهِ نَسْتَعِينُ وَعَلَيْهِ أَتَوَكَّلُ وَهُوَ حَسْبِي وَكَفَى وَمَا تَوْفِيقِي إِلَّا بِاللَّهِ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ وَأُفَوِّضُ أَمْرِي إِلَى اللَّهِ إِنَّ اللَّهَ بَصِيرٌ بِالْعِبَادِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'sayingوبه نستعين وعليه اتوكل وهو حسبي وكفي وما توفيقي الا بالله عليه توكلت واليه انيب وافوض امري الي الله ان الله بصير بالعباد ولا حول ولا قوه الا بالله العلي العظيم', 'وبه نستعين وعليه اتوكل وهو حسبي وكفي وما توفيقي الا بالله عليه توكلت واليه انيب وافوض امري الي الله ان الله بصير بالعباد ولا حول ولا قوه الا بالله العلي العظيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 2, NULL, 'Praise belongs to God — who fulfills the hope of every seeker of truth, guidance, and certainty; who makes the features of religion clear to those He has guided; who has made His saints into ladders of salvation for all who aspire to climb toward true life. I praise Him and bear witness that there is no god but He, before whose greatness all creation stands humbled. And I bear witness that Muhammad is His servant and His messenger, sent with the finest of laws and creeds, whose noble character encompassed every means by which innovations are expelled.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'praise belongs to god who fulfills the hope of every seeker of truth guidance and certainty who makes the features of religion clear to those he has guided who has made his saints into ladders of salvation for all who aspire to climb toward true life i praise him and bear witness that there is no god but he before whose greatness all creation stands humbled and i bear witness that muhammad is his servant and his messenger sent with the finest of laws and creeds whose noble character encompassed every means by which innovations are expelled', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 3, NULL, 'I send blessings upon his brother, his appointed guardian, and the Commander of the Faithful, Ali (عَلَيْهِ السَّلَامُ) — who descends from the line of the sacrifice, Ismail ibn Ibrahim al-Khalil — and who, through his interpretation, dispels the doubts that gather over the outward revelation.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'i send blessings upon his brother his appointed guardian and the commander of the faithful ali عليه السلام who descends from the line of the sacrifice ismail ibn ibrahim al khalil and who through his interpretation dispels the doubts that gather over the outward revelation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 4, NULL, 'And upon the niche of his light, the locus of his secret and his manifestation, Fatima al-Batul, daughter of Muhammad the Messenger. And upon her eldest son, Abu Muhammad al-Hasan al-Mutahhar; and upon her second son, Abu Abdullah al-Husayn — who grasps the meaning of what lies within the seven oft-repeated verses (السَّبْعُ الْمَثَانِي) of the great Quran — the foremost among those versed in the knowledge of the two paths.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'and upon the niche of his light the locus of his secret and his manifestation fatima al batul daughter of muhammad the messenger and upon her eldest son abu muhammad al hasan al mutahhar and upon her second son abu abdullah al husayn who grasps the meaning of what lies within the seven oft repeated verses السبع المثاني of the great quran the foremost among those versed in the knowledge of the two paths', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 5, NULL, 'And upon the pure Imams of his descendants and the righteous guides of his lineage — the Princes of the Faithful, the family of Taha and Yasin, virtuous and noble, God''s trustees over His revelation through the turning of all ages and eras, the suns of souls and the seas of the great sciences. And upon the one who upholds their command and makes their secret plain — the Imam of Imams, the revealer of what is obscure, the Commander of the Faithful, the firm rope of God, heir of his forefathers and the one who raises up His saints. And upon their chosen callers — the full moons amid darkness — and their chosen trustees, those rivers of knowledge that can never be overcome.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'and upon the pure imams of his descendants and the righteous guides of his lineage the princes of the faithful the family of taha and yasin virtuous and noble gods trustees over his revelation through the turning of all ages and eras the suns of souls and the seas of the great sciences and upon the one who upholds their command and makes their secret plain the imam of imams the revealer of what is obscure the commander of the faithful the firm rope of god heir of his forefathers and the one who raises up his saints and upon their chosen callers the full moons amid darkness and their chosen trustees those rivers of knowledge that can never be overcome', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 6, NULL, 'And upon the caller of this age and time from among them — the one who, in his own hour, gave shape to the forms of the people of faith: Jafar (جَعْفَر) ibn Sulayman (سُلَيْمَان) ibn al-Hasan ibn Yusuf (يُوسُف) ibn Sulayman, who stands in the station of his fathers and of the illustrious callers before them, in the Tayyibi cycle, in service to his master Mawlana the Imam al-Tayyib and his pure sons, in the station of Ishaq and his children and of Ismail and his children, upon all of whom be the prayers of the Most Gracious, the Most Merciful. And upon his trusted successor, who was first among them, and upon his deputy, who was second — the dearest and most glorious father, the caller Muhammad ibn al-Fahd. And (عَلَيْهِمُ السَّلَامُ) until the Day of Judgment.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'and upon the caller of this age and time from among them the one who in his own hour gave shape to the forms of the people of faith jafar جعفر ibn sulayman سليمان ibn al hasan ibn yusuf يوسف ibn sulayman who stands in the station of his fathers and of the illustrious callers before them in the tayyibi cycle in service to his master mawlana the imam al tayyib and his pure sons in the station of ishaq and his children and of ismail and his children upon all of whom be the prayers of the most gracious the most merciful and upon his trusted successor who was first among them and upon his deputy who was second the dearest and most glorious father the caller muhammad ibn al fahd and عليهم السلام until the day of judgment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 7, NULL, 'Now, after this praise of God, glorified be He, these thanks to Him, and these prayers upon His messenger, his family, and those who call to them and to Him: a guardian of religion''s great boundaries and a firm pillar of the believers — steadfast in his loyalty to the radiant Imams and to those who call to them — did not cease to press his request upon me, day after day, without relenting. I belong to our lord, our master, our father, and our refuge: the most exalted and singular caller, the unmatched and glorious chief, the luminous Sheikh — the holy and dear soul who has no equal in his age, who labored morning and evening to revive the religion of God, glorified be He — the honor of this world and of religion, the successor of his trustworthy father, the proof of Mawlana the Commander of the Faithful, and his overseer over all the people of his dawa: our master Jafar, son of our master Sulayman. May God raise his sanctity in the high chambers of the gardens, grant us his mercy, his intercession, and his approval, extend to us his secret, and pour upon us his favors and his gifts.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'now after this praise of god glorified be he these thanks to him and these prayers upon his messenger his family and those who call to them and to him a guardian of religions great boundaries and a firm pillar of the believers steadfast in his loyalty to the radiant imams and to those who call to them did not cease to press his request upon me day after day without relenting i belong to our lord our master our father and our refuge the most exalted and singular caller the unmatched and glorious chief the luminous sheikh the holy and dear soul who has no equal in his age who labored morning and evening to revive the religion of god glorified be he the honor of this world and of religion the successor of his trustworthy father the proof of mawlana the commander of the faithful and his overseer over all the people of his dawa our master jafar son of our master sulayman may god raise his sanctity in the high chambers of the gardens grant us his mercy his intercession and his approval extend to us his secret and pour upon us his favors and his gifts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 8, NULL, 'And upon the servant of his faithful successor — second to him in the high and firm station, the sword of his father''s dawa and that dawa''s blade upon the crown of its opponent''s head — our lord, our master, our father, and our deliverance: the illustrious caller and noble Sheikh, the reviver of religion and the destroyer of all its enemies, the shining Sheikh and the weighty form, our master the caller Muhammad ibn al-Fahd. May God raise his sanctity in the most glorious station and grant us his mercy, his approval, and his intercession with his guardian and his master.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'and upon the servant of his faithful successor second to him in the high and firm station the sword of his fathers dawa and that dawas blade upon the crown of its opponents head our lord our master our father and our deliverance the illustrious caller and noble sheikh the reviver of religion and the destroyer of all its enemies the shining sheikh and the weighty form our master the caller muhammad ibn al fahd may god raise his sanctity in the most glorious station and grant us his mercy his approval and his intercession with his guardian and his master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 9, NULL, 'His request was this: that I gather — for himself and for every believer who seeks religion and desires understanding in the school of the Household of the Messenger of the Lord of the Worlds — what lies scattered through the books of the saints of God (عَلَيْهِمُ السَّلَامُ) and of their learned and illustrious callers. Specifically:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'his request was this that i gather for himself and for every believer who seeks religion and desires understanding in the school of the household of the messenger of the lord of the worlds what lies scattered through the books of the saints of god عليهم السلام and of their learned and illustrious callers specifically', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 10, NULL, 'the paired and authoritative books the brief and abridged compositions on matters of the Sharia works of similar kind among the expansive treatments of juristic paths and legal opinions', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'the paired and authoritative books the brief and abridged compositions on matters of the sharia works of similar kind among the expansive treatments of juristic paths and legal opinions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 11, NULL, 'so that what is transmitted in them might be brought near and those paths made easier to travel.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'so that what is transmitted in them might be brought near and those paths made easier to travel', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 12, NULL, 'So I sought the good of God, glorified be He, the Most High, the All-Knowing, and of His guardian (ع) and His caller — the guardian of my favor named above, may God raise his sanctity in the chambers of light — and of the guardian of my favor who was his trusted successor and surety, may God raise his sanctity in the illustrious station. I answered his request, gathered what he sought, and began this work to the measure of my effort, my strength, my diligence, and my capacity, alongside the service I owe to those who have granted me their hands and their favors.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'so i sought the good of god glorified be he the most high the all knowing and of his guardian ع and his caller the guardian of my favor named above may god raise his sanctity in the chambers of light and of the guardian of my favor who was his trusted successor and surety may god raise his sanctity in the illustrious station i answered his request gathered what he sought and began this work to the measure of my effort my strength my diligence and my capacity alongside the service i owe to those who have granted me their hands and their favors', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 13, NULL, 'Whatever is correct in it comes from the substance of the guardian of my favor, who opens for me the doors that are closed against me, and from the substance of his successor, the guardian of my favor and the owner of my neck. I claim none of it as my own, and I pass each morning and evening in that anxiety. Whatever in it is a slip or an error comes from the shortness of my reach and from my own straying. I entrust my affair to them both and rely upon them in all things, for they are my sufficiency and my surety, and they are the ones who grant me healing from my spiritual ailments.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'whatever is correct in it comes from the substance of the guardian of my favor who opens for me the doors that are closed against me and from the substance of his successor the guardian of my favor and the owner of my neck i claim none of it as my own and i pass each morning and evening in that anxiety whatever in it is a slip or an error comes from the shortness of my reach and from my own straying i entrust my affair to them both and rely upon them in all things for they are my sufficiency and my surety and they are the ones who grant me healing from my spiritual ailments', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 14, NULL, 'The composition began on the seventh day of the month of Rajab al-Asabb — which is likewise the seventh among the months of the year, the month that rouses from heedlessness and slumber — in the fifty-first year after the great thousand of the pure Prophetic migration, upon its author be the finest prayers and the purest greeting.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'the composition began on the seventh day of the month of rajab al asabb which is likewise the seventh among the months of the year the month that rouses from heedlessness and slumber in the fifty first year after the great thousand of the pure prophetic migration upon its author be the finest prayers and the purest greeting', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 15, NULL, 'I named this book — which gathers all that has been described above — إِسْعَافُ الطَّالِبِ فِي جَمِيعِ الْمَطَالِبِ: The Student''s Aid in All Demands, for that is its scope and its design, just as it is its name. And I plead with the guardian of my favor named above, and with his successor, the guardian of my gratitude, that they set right for me all my affairs, in this path and in every other; that they accept my work through their generosity; that they bring me by their nobility to the good I hope for; that they seal my life with their approval; and that they make my resting place with them good through their bounty and their kindness, by the right of our master Muhammad and his pure family, upon whom be the prayers of God.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'i named this book which gathers all that has been described above اسعاف الطالب في جميع المطالب the students aid in all demands for that is its scope and its design just as it is its name and i plead with the guardian of my favor named above and with his successor the guardian of my gratitude that they set right for me all my affairs in this path and in every other that they accept my work through their generosity that they bring me by their nobility to the good i hope for that they seal my life with their approval and that they make my resting place with them good through their bounty and their kindness by the right of our master muhammad and his pure family upon whom be the prayers of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 16, NULL, 'Sayingوَاللَّهَ اَعْبُدُ وَبِهِ اَسْتَعِينُ وَهُوَ سُبْحَانَهُ نِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ وَنِعْمَ الْمُعِينُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ وَاللَّهُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ', '', 'وَاللَّهَ اَعْبُدُ وَبِهِ اَسْتَعِينُ وَهُوَ سُبْحَانَهُ نِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ وَنِعْمَ الْمُعِينُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ وَاللَّهُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'sayingوالله اعبد وبه استعين وهو سبحانه نعم المولي ونعم النصير ونعم المعين ولا حول ولا قوه الا بالله العلي العظيم والله يهدي من يشاء الي صراط مستقيم', 'والله اعبد وبه استعين وهو سبحانه نعم المولي ونعم النصير ونعم المعين ولا حول ولا قوه الا بالله العلي العظيم والله يهدي من يشاء الي صراط مستقيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 17, NULL, 'God alone do I worship, and from Him do I seek help. He, glorified be He, is the best of masters, the best of defenders, and the best of helpers. There is no power and no strength except through God, the Most High, the Most Great, and God guides whomever He wills to a straight path.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'god alone do i worship and from him do i seek help he glorified be he is the best of masters the best of defenders and the best of helpers there is no power and no strength except through god the most high the most great and god guides whomever he wills to a straight path', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 18, NULL, 'I turn now to the mention of faith as it is set down in the Book of Guardianship (كِتَابُ الْوِلَايَةِ).', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'i turn now to the mention of faith as it is set down in the book of guardianship كتاب الولايه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 19, NULL, 'I find it stated in some of the noble books:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'i find it stated in some of the noble books', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 20, NULL, 'Sayingاِعْلَمْ يَا أَخِي إِنَّ الْإِيمَانَ ثَمَانُ مَرَاتِبَ"Know, my brother, that faith has eight levels."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'sayingاعلم يا اخي ان الايمان ثمان مراتب know my brother that faith has eight levels', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 21, NULL, 'The first of those levels is named in these words:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'the first of those levels is named in these words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 22, NULL, 'Sayingأَوَّلُهَا الْإِحْسَانُ بِالْوَالِدَيْنِ ، وَبِذِي الْقُرْبَى ، وَالْيَتَامَى ، وَالْمَسَاكِينِ ، وَالْجَارِ ذِي الْقُرْبَى ، وَالْجَارِ الْجُنُبِ ، وَالصَّاحِبِ ذِي الْجَنْبِ ، وَابْنِ السَّبِيلِ وَمَا مَلَكَتْ أَيْمَانُكُمْ"The first of them is charity toward parents, toward relatives, toward orphans and toward the needy, toward the neighbor who is a relative and the neighbor who is nearby, toward the companion at one''s side, toward the traveler, and toward those whom your faith obligates you to care for."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'sayingاولها الاحسان بالوالدين وبذي القربي واليتامي والمساكين والجار ذي القربي والجار الجنب والصاحب ذي الجنب وابن السبيل وما ملكت ايمانكم the first of them is charity toward parents toward relatives toward orphans and toward the needy toward the neighbor who is a relative and the neighbor who is nearby toward the companion at ones side toward the traveler and toward those whom your faith obligates you to care for', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 23, NULL, 'This is established in the Book of God, the Exalted.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'this is established in the book of god the exalted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 24, NULL, 'He then said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'he then said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 25, NULL, 'Sayingوَلَيْسَ مَنْ تَقَلَّدَ عِبَادَةَ اللهِ وَدَعْوَةَ أَهْلِ الْبَيْتِ عَلَيْهِمُ السَّلَامُ بِغَيْرِ عِلْمٍ وَلَا عَمَلٍ يَقَعُ عَلَيْهِ اسْمُ الْإِيمَانِ وَلَا لَهُ عِنْدَ اللهِ ذِمَامٌ وَلَا عِنْدَ وَلِيِّهِ عَلَيْهِ السَّلَامُ عَهْدٌ وَلَا إِكْرَامٌ لِأَنَّهُ قَدْ خَرَجَ مِنْهُ', '', 'وَلَيْسَ مَنْ تَقَلَّدَ عِبَادَةَ اللهِ وَدَعْوَةَ أَهْلِ الْبَيْتِ عَلَيْهِمُ السَّلَامُ بِغَيْرِ عِلْمٍ وَلَا عَمَلٍ يَقَعُ عَلَيْهِ اسْمُ الْإِيمَانِ وَلَا لَهُ عِنْدَ اللهِ ذِمَامٌ وَلَا عِنْدَ وَلِيِّهِ عَلَيْهِ السَّلَامُ عَهْدٌ وَلَا إِكْرَامٌ لِأَنَّهُ قَدْ خَرَجَ مِنْهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'sayingوليس من تقلد عباده الله ودعوه اهل البيت عليهم السلام بغير علم ولا عمل يقع عليه اسم الايمان ولا له عند الله ذمام ولا عند وليه عليه السلام عهد ولا اكرام لانه قد خرج منه', 'وليس من تقلد عباده الله ودعوه اهل البيت عليهم السلام بغير علم ولا عمل يقع عليه اسم الايمان ولا له عند الله ذمام ولا عند وليه عليه السلام عهد ولا اكرام لانه قد خرج منه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 26, NULL, 'Whoever takes upon himself the worship of God and the call of the People of the House (عَلَيْهِمُ السَّلَامُ) without knowledge and without action cannot rightly bear the name of faith. He has no bond with God, and with His guardian (ع) he holds neither covenant nor honor, for he has departed from it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'whoever takes upon himself the worship of god and the call of the people of the house عليهم السلام without knowledge and without action cannot rightly bear the name of faith he has no bond with god and with his guardian ع he holds neither covenant nor honor for he has departed from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 27, NULL, 'I turn now to the distinction between faith and Islam — what each of them encompasses, and to a mention of what lies beyond.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'i turn now to the distinction between faith and islam what each of them encompasses and to a mention of what lies beyond', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 28, NULL, 'Our lord and master, the trust of the Imam, the banner of Islam — may God exalt his sanctity and grant us his intercession and his company — said, in the fourth of his noble councils known as the Mustansiriyya Councils — designated the Councils of Exposition and the Councils of Wisdom, may the peace of God be upon their author:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'our lord and master the trust of the imam the banner of islam may god exalt his sanctity and grant us his intercession and his company said in the fourth of his noble councils known as the mustansiriyya councils designated the councils of exposition and the councils of wisdom may the peace of god be upon their author', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 29, NULL, 'Sayingوَقَدْ تَقَدَّمَ الْقَوْلُ إِنَّ أَئِمَّةَ الدِّينِ عَلَيْهِمُ السَّلَامُ سَبْعَةٌ يَتَرَدَّدُونَ فِي الْعَالَمِ كَأَيَّامِ الْجُمُعَةِ إِلَى حِينِ قِيَامِ الْقَائِمِ وَالْحُجَجُ الْاِثْنَى عَشَرَ مُنْبَثَّةٌ فِي الْعَالَمِ فَهَذِهِ مَعْرِفَةُ جُمْلَةِ حُدُودِهَا', '', 'وَقَدْ تَقَدَّمَ الْقَوْلُ إِنَّ أَئِمَّةَ الدِّينِ عَلَيْهِمُ السَّلَامُ سَبْعَةٌ يَتَرَدَّدُونَ فِي الْعَالَمِ كَأَيَّامِ الْجُمُعَةِ إِلَى حِينِ قِيَامِ الْقَائِمِ وَالْحُجَجُ الْاِثْنَى عَشَرَ مُنْبَثَّةٌ فِي الْعَالَمِ فَهَذِهِ مَعْرِفَةُ جُمْلَةِ حُدُودِهَا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'sayingوقد تقدم القول ان ايمه الدين عليهم السلام سبعه يترددون في العالم كايام الجمعه الي حين قيام القايم والحجج الاثني عشر منبثه في العالم فهذه معرفه جمله حدودها', 'وقد تقدم القول ان ايمه الدين عليهم السلام سبعه يترددون في العالم كايام الجمعه الي حين قيام القايم والحجج الاثني عشر منبثه في العالم فهذه معرفه جمله حدودها');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 30, NULL, 'It has already been said that the Imams of religion (عَلَيْهِمُ السَّلَامُ) are seven, recurring in the world as the days of the week recur, until the rising of the one who will arise, while the twelve proofs are spread throughout the world. This is the knowledge of the sum of its limits.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'it has already been said that the imams of religion عليهم السلام are seven recurring in the world as the days of the week recur until the rising of the one who will arise while the twelve proofs are spread throughout the world this is the knowledge of the sum of its limits', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 31, NULL, 'By this he meant — may God exalt his sanctity — the limits of the testimony. As for fulfilling the rights owed to those limits, that consists of upholding seven obligations of religion and twelve practices incumbent upon the God-fearing.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'by this he meant may god exalt his sanctity the limits of the testimony as for fulfilling the rights owed to those limits that consists of upholding seven obligations of religion and twelve practices incumbent upon the god fearing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 32, NULL, 'The seven obligations are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'the seven obligations are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 33, NULL, 'Guardianship (الْوِلَايَة) Purity (اَلطَّهَارَة) Prayer (الصَّلَاة) Almsgiving (اَلزَّكَاة) Fasting (اَلصَّوْم) Pilgrimage (الْحَجّ) Struggle (اَلْجِهَاد)', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'guardianship الولايه purity الطهاره prayer الصلاه almsgiving الزكاه fasting الصوم pilgrimage الحج struggle الجهاد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 34, NULL, 'The twelve practices are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'the twelve practices are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 35, NULL, 'Honoring parents Maintaining the ties of kinship Protecting the neighbor Enjoining what is good Forbidding what is wrong Truthfulness in one''s home Good conduct with one''s spouse Kindness to those in one''s care Spreading the greeting of peace Feeding others Keeping the bond among the brethren Visiting the sick', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'honoring parents maintaining the ties of kinship protecting the neighbor enjoining what is good forbidding what is wrong truthfulness in ones home good conduct with ones spouse kindness to those in ones care spreading the greeting of peace feeding others keeping the bond among the brethren visiting the sick', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 36, NULL, 'These twelve are not obligatory upon women.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'these twelve are not obligatory upon women', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 37, NULL, 'Our master the Commander of the Faithful, Ali ibn Abi Talib (ع), said in his four hundred precepts:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'our master the commander of the faithful ali ibn abi talib ع said in his four hundred precepts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the eight levels of faith', '1. The Eight Levels of Faith', 38, NULL, 'Sayingاِفْتَرَقَ بَنُو إِسْرَائِيلَ عَلَى اثْنَتَيْنِ وَسَبْعِينَ فِرْقَةً وَسَتَفْتَرِقُ هَذِهِ الْأُمَّةُ عَلَى ثَلَاثٍ وَسَبْعِينَ فِرْقَةً وَاحِدَةٌ فِي الْجَنَّةِ وَسَايِرُهَا فِي النَّارِ"The Children of Israel divided into seventy-two sects, and this community will divide into seventy-three sects. One of them is in the Garden, and the rest of them are in the Fire."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 1 the eight levels of faith', 'sayingافترق بنو اسراييل علي اثنتين وسبعين فرقه وستفترق هذه الامه علي ثلاث وسبعين فرقه واحده في الجنه وسايرها في النار the children of israel divided into seventy two sects and this community will divide into seventy three sects one of them is in the garden and the rest of them are in the fire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 0, NULL, 'I turn now to the guardianship of the Commander of the Faithful, Ali ibn Abi Talib (ع), and to his love and his station.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'i turn now to the guardianship of the commander of the faithful ali ibn abi talib ع and to his love and his station', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 1, NULL, 'Our master and Mawlana, the long-serving preacher Jafar ibn Mansur al-Yaman — may God exalt him, sanctify him, and grant us his intercession and his blessing — said in the Book of the Foster-Suckling that Muhammad is His prophet, and that God says of him:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'our master and mawlana the long serving preacher jafar ibn mansur al yaman may god exalt him sanctify him and grant us his intercession and his blessing said in the book of the foster suckling that muhammad is his prophet and that god says of him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 2, NULL, 'At-Tahrim: 4فَإِنَّ ٱللَّهَ هُوَ مَوْلَىٰهُ وَجِبْرِيلُ وَصَلِحُ ٱلْمُؤْمِنِينَ"Indeed God is his master, and Gabriel, and the righteous of the believers."', '', NULL, 'At-Tahrim: 4', NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'at tahrim 4فان الله هو مولاه وجبريل وصلح المومنين indeed god is his master and gabriel and the righteous of the believers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 3, NULL, 'By this is meant the Imam of the believers, who is Ali ibn Abi Talib, the Imam of every believing man and every believing woman. And His words:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'by this is meant the imam of the believers who is ali ibn abi talib the imam of every believing man and every believing woman and his words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 4, NULL, 'Al-Kahf: 82وَكَانَ أَبُوهُمَا صَلِحًۭا"And their father was righteous."', '', NULL, 'Al-Kahf: 82', NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'al kahf 82وكان ابوهما صلحا and their father was righteous', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 5, NULL, 'By this is meant an Imam. And His words:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'by this is meant an imam and his words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 6, NULL, 'Al-Anbiya: 105أَنَّ ٱلْأَرْضَ يَرِثُهَا عِبَادِىَ ٱلصَّلِحُونَ"The earth is inherited by My righteous servants."', '', NULL, 'Al-Anbiya: 105', NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'al anbiya 105ان الارض يرثها عبادي الصلحون the earth is inherited by my righteous servants', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 7, NULL, 'By this are meant the Imams from among His servants.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'by this are meant the imams from among his servants', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 8, NULL, 'Mawlana the Imam al-Muizz li-Din Allah (ع) said in the Friday sermon, likening himself in the physical world to a pen in the spiritual world. He set four ranks beneath it, each one preceded by a spiritual rank that guides it toward the rank beyond. In this way he established the foundation facing the tablet, engraving into it what he derived from the spiritual world, just as a pen engraves upon a tablet.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'mawlana the imam al muizz li din allah ع said in the friday sermon likening himself in the physical world to a pen in the spiritual world he set four ranks beneath it each one preceded by a spiritual rank that guides it toward the rank beyond in this way he established the foundation facing the tablet engraving into it what he derived from the spiritual world just as a pen engraves upon a tablet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 9, NULL, 'I now record the answers given by the Commander of the Faithful, Ali ibn Abi Talib (ع), to questions he was asked, and what followed from them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'i now record the answers given by the commander of the faithful ali ibn abi talib ع to questions he was asked and what followed from them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 10, NULL, 'It is stated in the book Uns al-Afidah al-Muniba, in the account of some of the cases of the Commander of the Faithful Ali ibn Abi Talib (ع) and his remarkable rulings:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'it is stated in the book uns al afidah al muniba in the account of some of the cases of the commander of the faithful ali ibn abi talib ع and his remarkable rulings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 11, NULL, 'The king of Rum sent a messenger to Medina with a sum of money and instructed him: "Go to Muhammad. If he does not agree with you, then ask about his successor, and put to him proof." The messenger was to ask three questions, and if he received answers, he was to hand over the money.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'the king of rum sent a messenger to medina with a sum of money and instructed him go to muhammad if he does not agree with you then ask about his successor and put to him proof the messenger was to ask three questions and if he received answers he was to hand over the money', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 12, NULL, 'The man arrived in Medina and was brought before the Messenger of God (ع). He asked about his successor and was directed to Abu Bakr. Abu Bakr was brought forward, and the man asked him: "Tell me what is not God, what is not with God, and what God does not know." Abu Bakr grew angry and said to him: "Woe to you. By saying this you have added to your disbelief." The man left his presence. He was then directed to Umar, who responded in much the same way.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'the man arrived in medina and was brought before the messenger of god ع he asked about his successor and was directed to abu bakr abu bakr was brought forward and the man asked him tell me what is not god what is not with god and what god does not know abu bakr grew angry and said to him woe to you by saying this you have added to your disbelief the man left his presence he was then directed to umar who responded in much the same way', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 13, NULL, 'Then Abdullah ibn Abbas said: "What kind of men are these? They could not answer his questions, and yet they did not simply say, We do not know. Instead they accused him of knowing falsehood. I know who knows the answer." He was asked, "Who is he?" He said, "Ali ibn Abi Talib." They said, "Take us to him," and they all set out together with the man and knocked on his door.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'then abdullah ibn abbas said what kind of men are these they could not answer his questions and yet they did not simply say we do not know instead they accused him of knowing falsehood i know who knows the answer he was asked who is he he said ali ibn abi talib they said take us to him and they all set out together with the man and knocked on his door', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 14, NULL, 'The Commander of the Faithful (ع) came out to them with a pen behind his ear and his finger stained with ink. Abdullah ibn Abbas told him the story, and he (ع) said to the man: "Ask what you wish." The man said: "Tell me what is not God''s." He said: "God has no partner." He said: "Tell me what is not with God." He said: "Injustice." He said: "Tell me what God does not know." He said: "That the Messiah is the son of God. For God Almighty, glorified and exalted be His name, has said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'the commander of the faithful ع came out to them with a pen behind his ear and his finger stained with ink abdullah ibn abbas told him the story and he ع said to the man ask what you wish the man said tell me what is not gods he said god has no partner he said tell me what is not with god he said injustice he said tell me what god does not know he said that the messiah is the son of god for god almighty glorified and exalted be his name has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 15, NULL, 'Yunus: 18أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعْلَمُ', '', 'أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعْلَمُ', 'Yunus: 18', 10, 18, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'yunus 18اتنبون الله بما لا يعلم', 'اتنبون الله بما لا يعلم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 16, NULL, 'Do you inform God of what He does not know?"', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'do you inform god of what he does not know', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 17, NULL, 'The meaning is that it does not exist, and God has no knowledge of what does not exist.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'the meaning is that it does not exist and god has no knowledge of what does not exist', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 18, NULL, 'The man said: "I bear witness that there is no god but God, that Muhammad is the Messenger of God, and that you are his guardian." He then handed over the money, and Ali (ع) gave it to al-Hasan and al-Husayn (عَلَيْهِمُ السَّلَامُ) and told them: "Go and distribute it among the Muslims," and they did as he commanded.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'the man said i bear witness that there is no god but god that muhammad is the messenger of god and that you are his guardian he then handed over the money and ali ع gave it to al hasan and al husayn عليهم السلام and told them go and distribute it among the muslims and they did as he commanded', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 19, NULL, 'It is also narrated from Abu al-Jarud, from al-Harith al-Awar, that while the Commander of the Faithful (ع) was in al-Rahba with the people pressing around him — some seeking a ruling, others seeking help — a man stood and addressed him: "Peace be upon you, O Commander of the Faithful, and the mercy and blessings of God." The Commander of the Faithful (ع) looked at him and said: "And upon you peace, and the mercy and blessings of God. Who are you?" He said: "A man from your flock and from the people of your country."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'it is also narrated from abu al jarud from al harith al awar that while the commander of the faithful ع was in al rahba with the people pressing around him some seeking a ruling others seeking help a man stood and addressed him peace be upon you o commander of the faithful and the mercy and blessings of god the commander of the faithful ع looked at him and said and upon you peace and the mercy and blessings of god who are you he said a man from your flock and from the people of your country', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 20, NULL, 'He said to him, "Are you from my flock or from the people of my country? If you had greeted me for a single day, you would not be hidden from me." Then he said to those around him: "Do you know this man?" No one knew him. So he said to the man, "These are the people of your country, and they do not know you. Had I seen you for a single day, you would not be hidden from me." The man said, "Safety, O Commander of the Faithful." He said, "Have you committed any transgression in this land of mine since you entered it?" He said, "No." He said, "Perhaps during the days of war?" He said, "Yes." He said, "When war lays down its burdens, there is no harm in it."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'he said to him are you from my flock or from the people of my country if you had greeted me for a single day you would not be hidden from me then he said to those around him do you know this man no one knew him so he said to the man these are the people of your country and they do not know you had i seen you for a single day you would not be hidden from me the man said safety o commander of the faithful he said have you committed any transgression in this land of mine since you entered it he said no he said perhaps during the days of war he said yes he said when war lays down its burdens there is no harm in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 21, NULL, 'The man said: "Muawiya sent me to you and commanded me to come to you unannounced, to ask you about things that Ibn al-Asfar sent to him to inquire about. He says to him: if you are the rightful guardian of this matter and the claimant of the caliphate after Muhammad, then answer me these things, for if you answer me I will follow you and send you the tribute. And when the messenger saw that he had no answer to them, he sent me to you to ask you about them."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'the man said muawiya sent me to you and commanded me to come to you unannounced to ask you about things that ibn al asfar sent to him to inquire about he says to him if you are the rightful guardian of this matter and the claimant of the caliphate after muhammad then answer me these things for if you answer me i will follow you and send you the tribute and when the messenger saw that he had no answer to them he sent me to you to ask you about them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 22, NULL, 'He said, "And what are they?" The man said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'he said and what are they the man said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 23, NULL, 'How great is the distance between truth and falsehood? How great is the distance between heaven and earth? How great is the distance between east and west? What is this galaxy? What is the rainbow? What is the darkening in the moon? What is the first thing that appeared on the face of the earth? What is the first thing that stirred upon it? What is the spring to which the souls of the polytheists flee? What is the hermaphrodite? What are the ten things, each harder than the last?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'how great is the distance between truth and falsehood how great is the distance between heaven and earth how great is the distance between east and west what is this galaxy what is the rainbow what is the darkening in the moon what is the first thing that appeared on the face of the earth what is the first thing that stirred upon it what is the spring to which the souls of the polytheists flee what is the hermaphrodite what are the ten things each harder than the last', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 24, NULL, 'The Commander of the Faithful (ع) said to him: "God has destroyed the son of the liver-eater. How astray he is, and how astray are those with him. By God, he freed his slave girl and did not do well to marry her. God judge between me and this nation, who severed my ties of kinship, wasted my days, denied me my right, diminished the greatness of my station, and joined together in contending against me."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'the commander of the faithful ع said to him god has destroyed the son of the liver eater how astray he is and how astray are those with him by god he freed his slave girl and did not do well to marry her god judge between me and this nation who severed my ties of kinship wasted my days denied me my right diminished the greatness of my station and joined together in contending against me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 25, NULL, 'Then he said, "Bring me al-Hasan, al-Husayn, and Muhammad." They came to him. He said to the man, "O brother of the people of Syria, these are the sons of the Messenger of God (ع)," and he gestured toward al-Hasan and al-Husayn (عَلَيْهِمُ السَّلَامُ), "and this is my son," and he gestured toward Muhammad (رَضِيَ اللَّهُ عَنْه), "so ask whichever of them you wish." The Syrian said he wished to ask al-Hasan (ع). The Commander of the Faithful (ع) said to him, "Ask him," and he asked him all of those questions.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'then he said bring me al hasan al husayn and muhammad they came to him he said to the man o brother of the people of syria these are the sons of the messenger of god ع and he gestured toward al hasan and al husayn عليهم السلام and this is my son and he gestured toward muhammad رضي الله عنه so ask whichever of them you wish the syrian said he wished to ask al hasan ع the commander of the faithful ع said to him ask him and he asked him all of those questions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 26, NULL, 'Al-Hasan (ع) said: "O brother of the people of Syria, the distance between truth and falsehood is four fingers. What your eyes see is truth, and with your ears you may hear a great deal of falsehood." The Syrian said, "You have spoken truly, may God set you aright."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'al hasan ع said o brother of the people of syria the distance between truth and falsehood is four fingers what your eyes see is truth and with your ears you may hear a great deal of falsehood the syrian said you have spoken truly may god set you aright', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 27, NULL, 'He said: "Between heaven and earth lies the prayer of the oppressed and the reach of sight. Whoever says otherwise has lied." He said, "You have spoken truly."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'he said between heaven and earth lies the prayer of the oppressed and the reach of sight whoever says otherwise has lied he said you have spoken truly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 28, NULL, 'He said: "Between east and west lies the sun''s course in a single day. You look at it as it rises and you look at it as it sets. Whoever says otherwise has lied." He said, "You have spoken truly."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'he said between east and west lies the suns course in a single day you look at it as it rises and you look at it as it sets whoever says otherwise has lied he said you have spoken truly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 29, NULL, 'He said: "As for this galaxy, it is the lamps of the sky, and from it the pouring water descends. As for the rainbow, it is the bow of God and a safeguard from drowning. As for the darkening in the moon: the moon''s light was once like the light of the sun, but God blotted it out. God, mighty and majestic, said regarding that:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'he said as for this galaxy it is the lamps of the sky and from it the pouring water descends as for the rainbow it is the bow of god and a safeguard from drowning as for the darkening in the moon the moons light was once like the light of the sun but god blotted it out god mighty and majestic said regarding that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 30, NULL, 'Sayingوَجَعَلْنَا اللَّيْلَ وَالنَّهَارَ آيَتَيْنِ فَمَحَوْنَا آيَةَ اللَّيْلِ وَجَعَلْنَا آيَةَ النَّهَارِ مُبْصِرَةً', '', 'وَجَعَلْنَا اللَّيْلَ وَالنَّهَارَ آيَتَيْنِ فَمَحَوْنَا آيَةَ اللَّيْلِ وَجَعَلْنَا آيَةَ النَّهَارِ مُبْصِرَةً', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'sayingوجعلنا الليل والنهار ايتين فمحونا ايه الليل وجعلنا ايه النهار مبصره', 'وجعلنا الليل والنهار ايتين فمحونا ايه الليل وجعلنا ايه النهار مبصره');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 31, NULL, 'And We made the night and the day two signs, and We erased the sign of the night and made the sign of the day visible.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'and we made the night and the day two signs and we erased the sign of the night and made the sign of the day visible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 32, NULL, 'As for the first thing that appeared on the face of the earth, it is the valley of Dab. As for the first thing that stirred upon the face of the earth, it is the palm tree. As for the spring to which the souls of the polytheists flee, it is a spring called Salma. As for the hermaphrodite, it is a human being of whom it is not known whether the person is a woman or a man; so the person is examined: if a man, he has the emission of a man; and if a woman, she menstruates or her breasts develop. Otherwise the person is told to urinate against a wall: if the urine strikes the wall, it is a man, and if it falls back as the urine of a camel falls back, it is a woman. As for the ten things, each harder than the last: the hardest thing God created is stone; harder than stone is iron, by which stone is cut; stronger than iron is fire; stronger than fire is water; stronger than water is cloud; stronger than cloud is wind; stronger than wind is the angel; stronger than the angel is the Angel of Death; more severe than the Angel of Death is death itself; and more severe than death is the command of God, Lord of all worlds."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'as for the first thing that appeared on the face of the earth it is the valley of dab as for the first thing that stirred upon the face of the earth it is the palm tree as for the spring to which the souls of the polytheists flee it is a spring called salma as for the hermaphrodite it is a human being of whom it is not known whether the person is a woman or a man so the person is examined if a man he has the emission of a man and if a woman she menstruates or her breasts develop otherwise the person is told to urinate against a wall if the urine strikes the wall it is a man and if it falls back as the urine of a camel falls back it is a woman as for the ten things each harder than the last the hardest thing god created is stone harder than stone is iron by which stone is cut stronger than iron is fire stronger than fire is water stronger than water is cloud stronger than cloud is wind stronger than wind is the angel stronger than the angel is the angel of death more severe than the angel of death is death itself and more severe than death is the command of god lord of all worlds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 33, NULL, 'Then the Syrian said, "I bear witness that you are the son of the Messenger of God (ع), and that Ali (ع) is the guardian of Muhammad (ع), and that he has more right to this affair than Muawiya." He wrote these things down and carried them to Muawiya, and Muawiya sent them to Ibn al-Asfar. Ibn al-Asfar said: "I bear witness that these are not from you, and that they come only from the mine of prophecy and the seat of the message. As for you, were you to ask me for a single dirham, I would not give it to you."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'then the syrian said i bear witness that you are the son of the messenger of god ع and that ali ع is the guardian of muhammad ع and that he has more right to this affair than muawiya he wrote these things down and carried them to muawiya and muawiya sent them to ibn al asfar ibn al asfar said i bear witness that these are not from you and that they come only from the mine of prophecy and the seat of the message as for you were you to ask me for a single dirham i would not give it to you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 34, NULL, 'It is also narrated from him that he said: Umar ibn al-Khattab came to the Commander of the Faithful (ع) and said to him, "O Abu al-Hasan, there are matters I neglected to ask the Messenger of God (ع) about. Do you have anything concerning them?"', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'it is also narrated from him that he said umar ibn al khattab came to the commander of the faithful ع and said to him o abu al hasan there are matters i neglected to ask the messenger of god ع about do you have anything concerning them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 35, NULL, 'He said, "And what are they?" He said: "A man lies down and sees something in his sleep, and when he awakens it is as though he had taken it in his hand; yet he may see something that turns out to be nothing at all. And a man meets another man and loves him without knowing him. And a man meets another man and hates him without knowing him. And a man sees a thing with his eye or hears it and remembers it for a long age, then forgets it at the moment he needs it, then recalls it when he has no need of it."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'he said and what are they he said a man lies down and sees something in his sleep and when he awakens it is as though he had taken it in his hand yet he may see something that turns out to be nothing at all and a man meets another man and loves him without knowing him and a man meets another man and hates him without knowing him and a man sees a thing with his eye or hears it and remembers it for a long age then forgets it at the moment he needs it then recalls it when he has no need of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 36, NULL, 'The Commander of the Faithful (ع) said to him concerning that: "As for what you say about the thing a man sees in his sleep, God, blessed and exalted, said in His noble Book:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'the commander of the faithful ع said to him concerning that as for what you say about the thing a man sees in his sleep god blessed and exalted said in his noble book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 37, NULL, 'Az-Zumar: 42اللَّهُ يَتَوَفَّى الْأَنفُسَ حِينَ مَوْتِهَا وَالَّتِي لَمْ تَمُتْ فِي مَنَامِهَا فَيُمْسِكُ الَّتِي قَضَىٰ عَلَيْهَا الْمَوْتَ وَيُرْسِلُ الْأُخْرَىٰ إِلَىٰ أَجَلٍ مُّسَمًّى', '', 'اللَّهُ يَتَوَفَّى الْأَنفُسَ حِينَ مَوْتِهَا وَالَّتِي لَمْ تَمُتْ فِي مَنَامِهَا فَيُمْسِكُ الَّتِي قَضَىٰ عَلَيْهَا الْمَوْتَ وَيُرْسِلُ الْأُخْرَىٰ إِلَىٰ أَجَلٍ مُّسَمًّى', 'Az-Zumar: 42', 39, 42, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'az zumar 42الله يتوفي الانفس حين موتها والتي لم تمت في منامها فيمسك التي قضي عليها الموت ويرسل الاخري الي اجل مسمي', 'الله يتوفي الانفس حين موتها والتي لم تمت في منامها فيمسك التي قضي عليها الموت ويرسل الاخري الي اجل مسمي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 38, NULL, 'God takes the souls at the time of their death, and those that have not died, during their sleep. He keeps those for whom He has decreed death and releases the others until an appointed term.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'god takes the souls at the time of their death and those that have not died during their sleep he keeps those for whom he has decreed death and releases the others until an appointed term', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 39, NULL, 'Every servant who lies down to sleep carries within him a likeness of death. Whatever he sees while resting, with his soul loosened from his body, is true — he is in the kingdom. Whatever he sees as his soul returns is false; that is the delusion of Shaytan. As for what you say about a man seeing another and loving him without knowing him, or hating him without knowing him — God, mighty and majestic, created the souls two thousand years before the bodies, settled them in the air, and they would meet and scent one another as horses scent one another. Whatever souls came to know one another on that day are joined together today and love; whatever souls rejected one another on that day are divided today and hate. As for what you say about a man seeing something with his eye or hearing it, then forgetting it, then recalling it, then forgetting it once more — there is no heart that does not have a film over it, like the film of the moon. When that film passes through the heart, the servant forgets what he has seen and heard."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'every servant who lies down to sleep carries within him a likeness of death whatever he sees while resting with his soul loosened from his body is true he is in the kingdom whatever he sees as his soul returns is false that is the delusion of shaytan as for what you say about a man seeing another and loving him without knowing him or hating him without knowing him god mighty and majestic created the souls two thousand years before the bodies settled them in the air and they would meet and scent one another as horses scent one another whatever souls came to know one another on that day are joined together today and love whatever souls rejected one another on that day are divided today and hate as for what you say about a man seeing something with his eye or hearing it then forgetting it then recalling it then forgetting it once more there is no heart that does not have a film over it like the film of the moon when that film passes through the heart the servant forgets what he has seen and heard', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'three questions from the king of rum', '2. Three Questions from the King of Rum', 40, NULL, 'At that, Umar said, "You have spoken truly, O Abu al-Hasan. May God not keep me alive after you, and may I never be in a land where you are not."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 2 three questions from the king of rum', 'at that umar said you have spoken truly o abu al hasan may god not keep me alive after you and may i never be in a land where you are not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 0, NULL, 'I turn now to the guardianship of the Imams from the family of the Messenger of Allah (ع), and to the obligation of praying for Muhammad and the family of Muhammad (عَلَيْهِمُ السَّلَامُ) — together with what pertains to that prayer: the good proclaimers, the righteous borders, their stations, the command to return peace, and the reply to the greeting of the book.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'i turn now to the guardianship of the imams from the family of the messenger of allah ع and to the obligation of praying for muhammad and the family of muhammad عليهم السلام together with what pertains to that prayer the good proclaimers the righteous borders their stations the command to return peace and the reply to the greeting of the book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 1, NULL, 'In the twenty-third council of the Mustansiriya councils — may God''s peace be upon the author of the book — he said: he had finished treating the Sunnah that we had set out to discuss, namely the revelation of peace. Above, it divides into seven sections — those that came from God and from His angels; below, it divides into twelve sections — those that came from human beings.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'in the twenty third council of the mustansiriya councils may gods peace be upon the author of the book he said he had finished treating the sunnah that we had set out to discuss namely the revelation of peace above it divides into seven sections those that came from god and from his angels below it divides into twelve sections those that came from human beings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 2, NULL, 'The first — the highest, the most particular, the most exalted, and the most sincere — is the word of God Almighty:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the first the highest the most particular the most exalted and the most sincere is the word of god almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 3, NULL, 'Saying⟪سَلَامٌ عَلَيْكُمْ⟫"Peace be upon you."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'saying سلام عليكم peace be upon you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 4, NULL, 'The second, which carries a figurative quality, is His saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the second which carries a figurative quality is his saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 5, NULL, 'Saying⟪يَا نُوحُ اهْبِطْ بِسَلَامٍ مِّنَّا⟫"O Noah, descend in peace from Us."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'saying يا نوح اهبط بسلام منا o noah descend in peace from us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 6, NULL, 'The third, which is more suggestive, is His saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the third which is more suggestive is his saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 7, NULL, 'Saying⟪تَحِيَّتُهُمْ يَوْمَ يَلْقَوْنَهُۥ سَلَمٌۭۚ⟫"Their greeting on the day they meet Him is peace."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'saying تحيتهم يوم يلقونه سلم their greeting on the day they meet him is peace', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 8, NULL, 'The fourth is His saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the fourth is his saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 9, NULL, 'Saying⟪وَيُلَقَّوْنَ فِيهَا تَحِيَّةًۭ وَسَلَمًا⟫"And they will be met therein with greeting and peace."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'saying ويلقون فيها تحيه وسلما and they will be met therein with greeting and peace', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 10, NULL, 'The fifth expresses that it is from the angels in particular:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the fifth expresses that it is from the angels in particular', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 11, NULL, 'Saying⟪وَالْمَلَائِكَةُ يَدْخُلُونَ عَلَيْهِم مِّن كُلِّ بَابٍ سَلَامٌ عَلَيْكُم⟫"And the angels enter upon them from every gate: peace be upon you."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'saying والملايكه يدخلون عليهم من كل باب سلام عليكم and the angels enter upon them from every gate peace be upon you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 12, NULL, 'The sixth is that God and His angels pray for the Prophet (ع):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the sixth is that god and his angels pray for the prophet ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 13, NULL, 'Saying⟪يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا⟫"O you who believe, pray for him and submit to him in full submission."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'saying يا ايها الذين امنوا صلوا عليه وسلموا تسليما o you who believe pray for him and submit to him in full submission', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 14, NULL, 'The seventh is the word of the Almighty:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the seventh is the word of the almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 15, NULL, 'Saying⟪سَلَامٌ عَلَىٰ آلِ يَاسِينَ⟫"Peace be upon the family of Ya Sin."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'saying سلام علي ال ياسين peace be upon the family of ya sin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 16, NULL, 'And ياسين is our Prophet Muhammad (ع), and the family of ياسين is the family of Muhammad — آل على (عَلَيْهِمُ السَّلَامُ).', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'and ياسين is our prophet muhammad ع and the family of ياسين is the family of muhammad ال علي عليهم السلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 17, NULL, 'He said in the twenty-fourth assembly of it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'he said in the twenty fourth assembly of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 18, NULL, 'Know that the revelation of peace is an obligatory Sunnah of Islam, one that speaks of affection and submission, and Salam is one of the names of the One possessed of majesty and honor. You have heard what we have read to you from what it contains regarding the seven sections, and this is followed by the twelve divisions, which concern the greeting exchanged between human beings.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'know that the revelation of peace is an obligatory sunnah of islam one that speaks of affection and submission and salam is one of the names of the one possessed of majesty and honor you have heard what we have read to you from what it contains regarding the seven sections and this is followed by the twelve divisions which concern the greeting exchanged between human beings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 19, NULL, 'The first of these is the greeting of the people of the right hand to the faithful prophet (ع) and his noble family. He says, and He is the most truthful of speakers:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the first of these is the greeting of the people of the right hand to the faithful prophet ع and his noble family he says and he is the most truthful of speakers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 20, NULL, 'Saying⟪سَلَامٌ عَلَيْكُم بِمَا صَبَرْتُمْ⟫"Peace be upon you for your patience."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'saying سلام عليكم بما صبرتم peace be upon you for your patience', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 21, NULL, 'For if they are among the people of the right hand, then (عَلَيْهِمُ السَّلَامُ) from the people of the right hand.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'for if they are among the people of the right hand then عليهم السلام from the people of the right hand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 22, NULL, 'The second is the greeting upon entering the mosque with peace, for the Almighty says:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the second is the greeting upon entering the mosque with peace for the almighty says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 23, NULL, 'Saying⟪فَإِذَا دَخَلْتُم بُيُوتًا فَسَلِّمُوا عَلَىٰ أَنفُسِكُمْ تَحِيَّةً مِّنْ عِندِ اللَّهِ مُبَارَكَةً طَيِّبَةً⟫"When you enter houses, greet one another with a greeting from God, blessed and good."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'saying فاذا دخلتم بيوتا فسلموا علي انفسكم تحيه من عند الله مباركه طيبه when you enter houses greet one another with a greeting from god blessed and good', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 24, NULL, 'The third is the peace of one who concludes the prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the third is the peace of one who concludes the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 25, NULL, 'The fourth is the peace of the believer in the face of the ignorant. He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the fourth is the peace of the believer in the face of the ignorant he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 26, NULL, 'Saying⟪وَإِذَا خَاطَبَهُمُ الْجَاهِلُونَ قَالُوا سَلَامًا⟫"And when the ignorant address them, they say: peace."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'saying واذا خاطبهم الجاهلون قالوا سلاما and when the ignorant address them they say peace', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 27, NULL, 'The fifth through the ninth, as the Sunnah specifies, concern the order of precedence in initiating the greeting:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the fifth through the ninth as the sunnah specifies concern the order of precedence in initiating the greeting', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 28, NULL, 'The rider on a camel initiates to the rider on a horse. The rider on a horse initiates to the rider on a donkey. The rider on a donkey initiates to the one walking. The one walking initiates to the one standing. The one standing initiates the greeting and then returns it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the rider on a camel initiates to the rider on a horse the rider on a horse initiates to the rider on a donkey the rider on a donkey initiates to the one walking the one walking initiates to the one standing the one standing initiates the greeting and then returns it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 29, NULL, 'The return of the greeting falls into three kinds: the virtuous reply, the complete reply, and the just reply. The virtuous reply is to greet whoever initiates with something better than what they offered. The complete reply is to respond in kind, as God Almighty said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the return of the greeting falls into three kinds the virtuous reply the complete reply and the just reply the virtuous reply is to greet whoever initiates with something better than what they offered the complete reply is to respond in kind as god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 30, NULL, 'Saying⟪وَإِذَا حُيِّيتُم بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا⟫"And when you are greeted with a greeting, return it with something better, or return it as it is."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'saying واذا حييتم بتحيه فحيوا باحسن منها او ردوها and when you are greeted with a greeting return it with something better or return it as it is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 31, NULL, 'The just reply applies when responding to dhimmis, for they do not initiate the greeting. If one of them does, however, the response is "And upon you." The reason is that some of them were reported to deceive Muslims in their greetings by saying ⟪السَّامُ عَلَيْكُم⟫ — "Death be upon you" — in place of ⟪السَّلَامُ عَلَيْكُم⟫. The Sunnah therefore prescribed responding with "And upon you," which is a just reply: whoever said something good received its like, and whoever said something bad received its like.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the just reply applies when responding to dhimmis for they do not initiate the greeting if one of them does however the response is and upon you the reason is that some of them were reported to deceive muslims in their greetings by saying السام عليكم death be upon you in place of السلام عليكم the sunnah therefore prescribed responding with and upon you which is a just reply whoever said something good received its like and whoever said something bad received its like', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 32, NULL, 'Our master Amir al-Muminin, the Imam al-Muizz li-Din Allah (ع), said in his prayer on Sunday, after praying for the higher borders: "O God, reach the lower borders, the five — the spokesman, the foundation, the culmination, the successor, and the wing." And he said (ع) in his prayer on Saturday: "O God, upon the seven days and the twelve months, send the purest, most honorable, and most noble of prayers."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'our master amir al muminin the imam al muizz li din allah ع said in his prayer on sunday after praying for the higher borders o god reach the lower borders the five the spokesman the foundation the culmination the successor and the wing and he said ع in his prayer on saturday o god upon the seven days and the twelve months send the purest most honorable and most noble of prayers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 33, NULL, 'Some of the saints of the religion, may God sanctify their souls, said in praying for the borders, in his prayer on Sunday: "O God, reach the proclaimers and their gates, the imams of their stations, their proofs, and their preachers." And he said in his supplication on Monday: "O Allah, pray for the seven proclaimers, the seven culminations, the seven caliphs, and the twelve successors — the purest prayer, the most growing, the most honorable, and the highest. And admit us into all the good into which You have admitted them, and spare us from every evil from which You have spared them." And he said in his supplication on Tuesday: "Reach Your manifest borders and Your righteous guardians — the spokesmen who call to Your light, the proven foundations of the truth of Your religion, the culmination, the successor, and the wing, through whom the gates of Your mercy were opened." And he said in his prayer on Wednesday: "O God, upon them and upon their gates, their proofs, and their preachers, send the best of Your holy prayers." And he said in his prayer on Thursday: "O God, bless the days and months, the hours of the day and the hours of the night, both the manifest and the hidden." And he said in his prayer on the Sabbath: "Dedicate to Muhammad, O God, and to the Imams of his station and the proofs of their ages, many times over what You have prayed for them all."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'some of the saints of the religion may god sanctify their souls said in praying for the borders in his prayer on sunday o god reach the proclaimers and their gates the imams of their stations their proofs and their preachers and he said in his supplication on monday o allah pray for the seven proclaimers the seven culminations the seven caliphs and the twelve successors the purest prayer the most growing the most honorable and the highest and admit us into all the good into which you have admitted them and spare us from every evil from which you have spared them and he said in his supplication on tuesday reach your manifest borders and your righteous guardians the spokesmen who call to your light the proven foundations of the truth of your religion the culmination the successor and the wing through whom the gates of your mercy were opened and he said in his prayer on wednesday o god upon them and upon their gates their proofs and their preachers send the best of your holy prayers and he said in his prayer on thursday o god bless the days and months the hours of the day and the hours of the night both the manifest and the hidden and he said in his prayer on the sabbath dedicate to muhammad o god and to the imams of his station and the proofs of their ages many times over what you have prayed for them all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 34, NULL, 'And our master Amir al-Muminin (ع) said in his Four Hundred Counsels: "When someone greets you, return the greeting with something better than it, or return it in kind. Shake hands with your enemy if he dislikes it, for God has commanded His servants to do so, as the Almighty says:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'and our master amir al muminin ع said in his four hundred counsels when someone greets you return the greeting with something better than it or return it in kind shake hands with your enemy if he dislikes it for god has commanded his servants to do so as the almighty says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'the grammar of peace', '3. The Grammar of Peace', 35, NULL, 'Saying⟪ادْفَعْ بِالَّتِي هِيَ أَحْسَنُ فَإِذَا الَّذِي بَيْنَكَ وَبَيْنَهُ عَدَاوَةٌ كَأَنَّهُ وَلِيٌّ حَمِيمٌ⟫', '', '⟪ ادْفَعْ بِالَّتِي هِيَ أَحْسَنُ فَإِذَا الَّذِي بَيْنَكَ وَبَيْنَهُ عَدَاوَةٌ كَأَنَّهُ وَلِيٌّ حَمِيمٌ⟫', 'Saying', 41, 34, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'saying ادفع بالتي هي احسن فاذا الذي بينك وبينه عداوه كانه ولي حميم', 'ادفع بالتي هي احسن فاذا الذي بينك وبينه عداوه كانه ولي حميم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 36, NULL, 'Repel with that which is better, and then the one between whom and you there was enmity will become as though he were a close friend. And he said therein: If your brother says, "May God greet you with peace," then say: You are the peace of God, and the finest of abodes and stations."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'repel with that which is better and then the one between whom and you there was enmity will become as though he were a close friend and he said therein if your brother says may god greet you with peace then say you are the peace of god and the finest of abodes and stations', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 37, NULL, 'I cite here from the book of questions — composed by the late Sheikh Shamoun ibn Muhammad Ghori al-Hindi (رض) — and of answers, which are from our master Badr al-Din, our master Hasan (حَسَن) ibn our master Idris ibn Sayyidna al-Hasan ibn Sayyidna Abdullah al-Alaf, may God sanctify him and grant us his intercession and his companionship.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'i cite here from the book of questions composed by the late sheikh shamoun ibn muhammad ghori al hindi رض and of answers which are from our master badr al din our master hasan حسن ibn our master idris ibn sayyidna al hasan ibn sayyidna abdullah al alaf may god sanctify him and grant us his intercession and his companionship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 38, NULL, 'The question: "What do you say — you who purify our souls of the whispering of Shaytan that clings to them — regarding the offering of peace to sheikhs, teachers, and those close to them? Most of the people of India do not proclaim peace aloud in their presence; instead, they bow or lower their heads, intending thereby to greet them. Some say this resembles the practice of unbelievers. O our master, favor us with an answer in this matter that leaves the objectors with nothing to say."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the question what do you say you who purify our souls of the whispering of shaytan that clings to them regarding the offering of peace to sheikhs teachers and those close to them most of the people of india do not proclaim peace aloud in their presence instead they bow or lower their heads intending thereby to greet them some say this resembles the practice of unbelievers o our master favor us with an answer in this matter that leaves the objectors with nothing to say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 39, NULL, 'The answer: "Let peace be proclaimed aloud, for that is better."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the answer let peace be proclaimed aloud for that is better', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 40, NULL, 'I also find therein the following question: "What do you say, O you who have illuminated the jewels of our souls with the light of knowledge, regarding the returning of a greeting to a Muslim — must it be in a measure that he hears it, or not? And is it obligatory upon the one returning the greeting to reply when he hears the Muslim''s salutation, or not? As for sneezing: is the blessing obligatory upon the one who blesses when he hears the sneezer say Praise be to God, or merely upon hearing the sneeze itself? And must the blessing be loud enough that the sneezer hears it, or not?"', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'i also find therein the following question what do you say o you who have illuminated the jewels of our souls with the light of knowledge regarding the returning of a greeting to a muslim must it be in a measure that he hears it or not and is it obligatory upon the one returning the greeting to reply when he hears the muslims salutation or not as for sneezing is the blessing obligatory upon the one who blesses when he hears the sneezer say praise be to god or merely upon hearing the sneeze itself and must the blessing be loud enough that the sneezer hears it or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the grammar of peace', '3. The Grammar of Peace', 41, NULL, 'The answer: "This is a courtesy and not an obligation. One may do it as one wishes, and there is no fault upon him if he does not — except in returning a greeting in general, whether aloud or silently."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 3 the grammar of peace', 'the answer this is a courtesy and not an obligation one may do it as one wishes and there is no fault upon him if he does not except in returning a greeting in general whether aloud or silently', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 0, NULL, 'I turn now to what has been transmitted from the Imams of the family of Muhammad (ع). Our master Jafar bin Mansour al-Yemen (رض) said, in the book of the Esoteric Nursing, commenting on the words of God:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'i turn now to what has been transmitted from the imams of the family of muhammad ع our master jafar bin mansour al yemen رض said in the book of the esoteric nursing commenting on the words of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 1, NULL, 'Al-Anbiya: 105أَنَّ ٱلْأَرْضَ يَرِثُهَا عِبَادِىَ ٱلصَّلِحُونَ', '', 'أَنَّ ٱلْأَرْضَ يَرِثُهَا عِبَادِىَ ٱلصَّلِحُونَ', 'Al-Anbiya: 105', 21, 105, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'al anbiya 105ان الارض يرثها عبادي الصلحون', 'ان الارض يرثها عبادي الصلحون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 2, NULL, 'The earth is inherited by My righteous servants.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'the earth is inherited by my righteous servants', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 3, NULL, 'By this, he taught, are meant the Imams among His servants. He said likewise concerning the words of God:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'by this he taught are meant the imams among his servants he said likewise concerning the words of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 4, NULL, 'Al-Qasas: 5وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسْتُضْعِفُوا۟ فِى ٱلْأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةًۭ وَنَجْعَلَهُمُ ٱلْوَرِثِينَ', '', 'وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسْتُضْعِفُوا۟ فِى ٱلْأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةًۭ وَنَجْعَلَهُمُ ٱلْوَرِثِينَ', 'Al-Qasas: 5', 28, 5, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'al qasas 5ونريد ان نمن علي الذين استضعفوا في الارض ونجعلهم ايمه ونجعلهم الورثين', 'ونريد ان نمن علي الذين استضعفوا في الارض ونجعلهم ايمه ونجعلهم الورثين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 5, NULL, 'And We wished to be gracious to those who were made weak in the land, and to make them Imams, and to make them the heirs.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and we wished to be gracious to those who were made weak in the land and to make them imams and to make them the heirs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 6, NULL, 'By "those who were made weak" he means the descendants of Ali ibn Abi Talib. They were made weak in the land — that is, in the very person of Ali ibn Abi Talib himself — for he is the proof of Muhammad, and the earth is his likeness. And our master al-Muizz li Din Allah (ع) said in his supplication of Sunday:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'by those who were made weak he means the descendants of ali ibn abi talib they were made weak in the land that is in the very person of ali ibn abi talib himself for he is the proof of muhammad and the earth is his likeness and our master al muizz li din allah ع said in his supplication of sunday', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 7, NULL, 'Sayingثُمَّ نَصَبَ مِنْ دُونِ الْأَسَاسِ الْمُتِمِّ بِاِزَاءِ اِسْرَافِيلَ', '', 'ثُمَّ نَصَبَ مِنْ دُونِ الْأَسَاسِ الْمُتِمِّ بِاِزَاءِ اِسْرَافِيلَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingثم نصب من دون الاساس المتم بازاء اسرافيل', 'ثم نصب من دون الاساس المتم بازاء اسرافيل');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 8, NULL, 'Then he appointed, beneath the Foundation, the Terminus, set facing اسرافيل.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'then he appointed beneath the foundation the terminus set facing اسرافيل', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 9, NULL, 'I mention next the stations of the Imams (عَلَيْهِمُ السَّلَامُ), their conditions, their innocence of whoever sets them in a place other than their own place, and the charge of unbelief against whoever transgresses the bounds concerning them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'i mention next the stations of the imams عليهم السلام their conditions their innocence of whoever sets them in a place other than their own place and the charge of unbelief against whoever transgresses the bounds concerning them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 10, NULL, 'Maulana Imam al-Muizz li Din Allah (ع) spoke in his supplication of Sunday the words already cited, appointing beneath الأساس the Terminus — المتم — set facing اسرافيل. And Maulana Ali ibn Abi Talib (ع) said in his supplication known as the supplication of victory and awe:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'maulana imam al muizz li din allah ع spoke in his supplication of sunday the words already cited appointing beneath الاساس the terminus المتم set facing اسرافيل and maulana ali ibn abi talib ع said in his supplication known as the supplication of victory and awe', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 11, NULL, 'Sayingوَبِالسِّتَّةِ الْمَأْثُورَةِ وَبِالسَّبْعَةِ الْمَنْظُورَةِ', '', 'وَبِالسِّتَّةِ الْمَأْثُورَةِ وَبِالسَّبْعَةِ الْمَنْظُورَةِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingوبالسته الماثوره وبالسبعه المنظوره', 'وبالسته الماثوره وبالسبعه المنظوره');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 12, NULL, 'And by the six that are transmitted, and by the seven that are beheld.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and by the six that are transmitted and by the seven that are beheld', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 13, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 14, NULL, 'Sayingوَبِالتِّسْعِ الْآيَاتِ وَبِالْعَشْرِ الْكَلِمَاتِ', '', 'وَبِالتِّسْعِ الْآيَاتِ وَبِالْعَشْرِ الْكَلِمَاتِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingوبالتسع الايات وبالعشر الكلمات', 'وبالتسع الايات وبالعشر الكلمات');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 15, NULL, 'And by the nine signs, and by the ten words.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and by the nine signs and by the ten words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 16, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 17, NULL, 'Sayingوَبِالْإِحْدَى وَالْعِشْرِينَ', '', 'وَبِالْإِحْدَى وَالْعِشْرِينَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingوبالاحدي والعشرين', 'وبالاحدي والعشرين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 18, NULL, 'And by the twenty-one.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and by the twenty one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 19, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 20, NULL, 'And by the seven Imams, and the seven successors, and the seven witnesses, and the seven substitutes.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and by the seven imams and the seven successors and the seven witnesses and the seven substitutes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 21, NULL, 'And he (ع) said in his Four Hundred Manners:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and he ع said in his four hundred manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 22, NULL, 'Sayingوَبِالسَّبْعَةِ الْأُمَّاءِ وَالسَّبْعَةِ الْخُلَفَاءِ وَبِالسَّبْعَةِ الْأَشْهَادِ وَبِالسَّبْعَةِ الْأَبْدَالِ', '', 'وَبِالسَّبْعَةِ الْأُمَّاءِ وَالسَّبْعَةِ الْخُلَفَاءِ وَبِالسَّبْعَةِ الْأَشْهَادِ وَبِالسَّبْعَةِ الْأَبْدَالِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingوبالسبعه الاماء والسبعه الخلفاء وبالسبعه الاشهاد وبالسبعه الابدال', 'وبالسبعه الاماء والسبعه الخلفاء وبالسبعه الاشهاد وبالسبعه الابدال');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 23, NULL, 'Sayingمَنْ تَمَسَّكَ بِنَا لَحِقَ وَمَنْ تَمَسَّكَ غَيْرَ طَرِيقِنَا مُحِقَ', '', 'مَنْ تَمَسَّكَ بِنَا لَحِقَ وَمَنْ تَمَسَّكَ غَيْرَ طَرِيقِنَا مُحِقَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingمن تمسك بنا لحق ومن تمسك غير طريقنا محق', 'من تمسك بنا لحق ومن تمسك غير طريقنا محق');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 24, NULL, 'Whoever holds fast to us has joined the truth, and whoever holds fast to a way other than ours is undone.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'whoever holds fast to us has joined the truth and whoever holds fast to a way other than ours is undone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 25, NULL, 'I mention next the stations of the proofs of the Imams (عَلَيْهِمُ السَّلَامُ), their preachers, their hudud, and their followers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'i mention next the stations of the proofs of the imams عليهم السلام their preachers their hudud and their followers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 26, NULL, 'Maulana Imam al-Muizz li Din Allah (ع) said in his supplication of Sunday:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'maulana imam al muizz li din allah ع said in his supplication of sunday', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 27, NULL, 'Sayingوَنَصَبَ مِنْ دُونِ الْمُتِمِّ اللَّاحِقَ بِاِزَاءِ مِيكَائِيلَ وَنَصَبَ مِنْ دُونِ اللَّاحِقِ الْجَنَاحَ بِاِزَاءِ جِبْرَئِيلَ', '', 'وَنَصَبَ مِنْ دُونِ الْمُتِمِّ اللَّاحِقَ بِاِزَاءِ مِيكَائِيلَ وَنَصَبَ مِنْ دُونِ اللَّاحِقِ الْجَنَاحَ بِاِزَاءِ جِبْرَئِيلَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingونصب من دون المتم اللاحق بازاء ميكاييل ونصب من دون اللاحق الجناح بازاء جبرييل', 'ونصب من دون المتم اللاحق بازاء ميكاييل ونصب من دون اللاحق الجناح بازاء جبرييل');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 28, NULL, 'And he appointed beneath the Terminus the After, set facing Michael, and he appointed beneath the After the Wing, set facing Gabriel.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and he appointed beneath the terminus the after set facing michael and he appointed beneath the after the wing set facing gabriel', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 29, NULL, 'Then he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'then he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 30, NULL, 'Sayingفَكَانَ هَؤُلَاءِ الثَّلَاثَةُ فِي الْأَدَاءِ إِلَى الْمُسْتَجِيبِينَ عَنِ النَّاطِقِ وَالْأَسَاسِ فِي الْعَالَمِ الْجِسْمَانِيِّ كَمَا كَانَتِ الثَّلَاثَةُ فِي الْأَدَاءِ عَنِ الْأَصْلَيْنِ الَّذِينَ هُمَا الْقَلَمُ وَاللَّوْحُ فِي الْعَالَمِ الرُّوحَانِيِّ', '', 'فَكَانَ هَؤُلَاءِ الثَّلَاثَةُ فِي الْأَدَاءِ إِلَى الْمُسْتَجِيبِينَ عَنِ النَّاطِقِ وَالْأَسَاسِ فِي الْعَالَمِ الْجِسْمَانِيِّ كَمَا كَانَتِ الثَّلَاثَةُ فِي الْأَدَاءِ عَنِ الْأَصْلَيْنِ الَّذِينَ هُمَا الْقَلَمُ وَاللَّوْحُ فِي الْعَالَمِ الرُّوحَانِيِّ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingفكان هولاء الثلاثه في الاداء الي المستجيبين عن الناطق والاساس في العالم الجسماني كما كانت الثلاثه في الاداء عن الاصلين الذين هما القلم واللوح في العالم الروحاني', 'فكان هولاء الثلاثه في الاداء الي المستجيبين عن الناطق والاساس في العالم الجسماني كما كانت الثلاثه في الاداء عن الاصلين الذين هما القلم واللوح في العالم الروحاني');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 31, NULL, 'By this he (ع) means the Grandfather (الْجَدّ), the Opener (الْفَتْح), and the Imagination (اَلْخَيَال) — that is, Israfil, Michael, and Gabriel. He (ع) also said in his supplication of Friday:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'by this he ع means the grandfather الجد the opener الفتح and the imagination الخيال that is israfil michael and gabriel he ع also said in his supplication of friday', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 32, NULL, 'Sayingوَبِالْحُدُودِ الَّتِي هِيَ النَّاطِقُ وَالْأَسَاسُ وَالْمُتِمُّ وَاللَّاحِقُ وَالْجَنَاحُ وَالْمَأْذُونُ وَالْمُسْتَجِيبُ وَالْحُجَجِ الْأَثْنَىْ عَشَرَ الْمُرَتَّبَةِ فِي الْجَزَائِرِ الِاثْنَىْ عَشَرَ', '', 'وَبِالْحُدُودِ الَّتِي هِيَ النَّاطِقُ وَالْأَسَاسُ وَالْمُتِمُّ وَاللَّاحِقُ وَالْجَنَاحُ وَالْمَأْذُونُ وَالْمُسْتَجِيبُ وَالْحُجَجِ الْأَثْنَىْ عَشَرَ الْمُرَتَّبَةِ فِي الْجَزَائِرِ الِاثْنَىْ عَشَرَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingوبالحدود التي هي الناطق والاساس والمتم واللاحق والجناح والماذون والمستجيب والحجج الاثني عشر المرتبه في الجزاير الاثني عشر', 'وبالحدود التي هي الناطق والاساس والمتم واللاحق والجناح والماذون والمستجيب والحجج الاثني عشر المرتبه في الجزاير الاثني عشر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 33, NULL, 'And by the hudud — which are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and by the hudud which are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 34, NULL, 'the Speaker the Foundation the Terminus the After the Wing the Authorized the Respondent', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'the speaker the foundation the terminus the after the wing the authorized the respondent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 35, NULL, '— and the twelve proofs ranked across the twelve regions.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and the twelve proofs ranked across the twelve regions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 36, NULL, 'This is as God Almighty has said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'this is as god almighty has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 37, NULL, 'Sayingلوّاحة للبشر عليها تسعة عشر', '', 'لوّاحة للبشر عليها تسعة عشر', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingلواحه للبشر عليها تسعه عشر', 'لواحه للبشر عليها تسعه عشر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 38, NULL, 'لَوَّاحَةٌ لِّلْبَشَرِ عَلَيْهَا تِسْعَةَ عَشَرَ — Searing to mankind; over it are nineteen.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'لواحه للبشر عليها تسعه عشر searing to mankind over it are nineteen', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 39, NULL, 'And Maulana Amir al-Muminin (ع) said in the supplication of victory and awe:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and maulana amir al muminin ع said in the supplication of victory and awe', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 40, NULL, 'Sayingوَبِالثَّمَانِيَةِ الْحَافِّينَ بِعَرْشِكَ يَا رَبَّ الْعَالَمِينَ', '', 'وَبِالثَّمَانِيَةِ الْحَافِّينَ بِعَرْشِكَ يَا رَبَّ الْعَالَمِينَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingوبالثمانيه الحافين بعرشك يا رب العالمين', 'وبالثمانيه الحافين بعرشك يا رب العالمين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 41, NULL, 'And by the eight who encircle Your Throne, O Lord of the worlds.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and by the eight who encircle your throne o lord of the worlds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 42, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 43, NULL, 'Sayingوَبِالْإِحْدَى عَشَرَ السَّاجِدِينَ وَبِالِاثْنَى عَشَرَ الْمَعْدُودِينَ الرَّاكِعِينَ', '', 'وَبِالْإِحْدَى عَشَرَ السَّاجِدِينَ وَبِالِاثْنَى عَشَرَ الْمَعْدُودِينَ الرَّاكِعِينَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingوبالاحدي عشر الساجدين وبالاثني عشر المعدودين الراكعين', 'وبالاحدي عشر الساجدين وبالاثني عشر المعدودين الراكعين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 44, NULL, 'And by the eleven who prostrate, and by the twelve counted ones who bow.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and by the eleven who prostrate and by the twelve counted ones who bow', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 45, NULL, 'And our master Muhammad bin Tahir (رض) said in a great supplication of his:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and our master muhammad bin tahir رض said in a great supplication of his', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 46, NULL, 'Sayingوَأَتَوَسَّلُ إِلَيْكَ اللَّهُمَّ بِأَبْوَابِهِمْ وَحُجَجِهِمْ وَدُعَاتِهِمْ وَمَأْذُونِيهِمْ وَمُسْتَجِيبِي أَدْوَارِهِمْ وَمَنْ يَنْحُو نَحْوَهُمْ وَيَلُوذُ مَلَاذَهُمْ وَيَأْتَمُّ بِهِمْ وَبِتَابِعِيهِمْ أَجْمَعِينَ', '', 'وَأَتَوَسَّلُ إِلَيْكَ اللَّهُمَّ بِأَبْوَابِهِمْ وَحُجَجِهِمْ وَدُعَاتِهِمْ وَمَأْذُونِيهِمْ وَمُسْتَجِيبِي أَدْوَارِهِمْ وَمَنْ يَنْحُو نَحْوَهُمْ وَيَلُوذُ مَلَاذَهُمْ وَيَأْتَمُّ بِهِمْ وَبِتَابِعِيهِمْ أَجْمَعِينَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingواتوسل اليك اللهم بابوابهم وحججهم ودعاتهم وماذونيهم ومستجيبي ادوارهم ومن ينحو نحوهم ويلوذ ملاذهم وياتم بهم وبتابعيهم اجمعين', 'واتوسل اليك اللهم بابوابهم وحججهم ودعاتهم وماذونيهم ومستجيبي ادوارهم ومن ينحو نحوهم ويلوذ ملاذهم وياتم بهم وبتابعيهم اجمعين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 47, NULL, 'I seek nearness to You, O God, through their gates, their proofs, their preachers, their authorized ones, the respondents of their cycles, all who incline toward them, all who take shelter in their shelter, all who take them as guides, and all their followers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'i seek nearness to you o god through their gates their proofs their preachers their authorized ones the respondents of their cycles all who incline toward them all who take shelter in their shelter all who take them as guides and all their followers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 48, NULL, 'And Maulana the Commander of the Believers, Ali ibn Abi Talib (ع), said in his Four Hundred Manners:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and maulana the commander of the believers ali ibn abi talib ع said in his four hundred manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 49, NULL, 'Sayingمن أراد منكم أن يعلم کیف منزلته عند الله تعالى فلينظر کیف منزلة الله منه عند الذنوب', '', 'من أراد منكم أن يعلم کیف منزلته عند الله تعالى فلينظر کیف منزلة الله منه عند الذنوب', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingمن اراد منكم ان يعلم كيف منزلته عند الله تعالي فلينظر كيف منزله الله منه عند الذنوب', 'من اراد منكم ان يعلم كيف منزلته عند الله تعالي فلينظر كيف منزله الله منه عند الذنوب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 50, NULL, 'Whoever among you wishes to know his station with God Almighty, let him look at what station God holds with him at the moment of sin.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'whoever among you wishes to know his station with god almighty let him look at what station god holds with him at the moment of sin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 51, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 52, NULL, 'Sayingاَلْمُؤْمِنُ نَفْسُهُ مِنْهُ فِي تَعَبٍ وَالنَّاسُ مِنْهُ فِي رَاحَةٍ', '', 'اَلْمُؤْمِنُ نَفْسُهُ مِنْهُ فِي تَعَبٍ وَالنَّاسُ مِنْهُ فِي رَاحَةٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingالمومن نفسه منه في تعب والناس منه في راحه', 'المومن نفسه منه في تعب والناس منه في راحه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 53, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 54, NULL, 'Sayingأَنَّ أَهْلَ الْجَنَّةِ لَيَنْظُرُونَ إِلَىٰ مَنَازِلِ شِيعَتِنَا كَمَا يَنْظُرُ أَحَدُكُمْ إِلَىٰ الْكَوْكَبِ الدُّرِّيِّ فِي السَّمَاءِ', '', 'أَنَّ أَهْلَ الْجَنَّةِ لَيَنْظُرُونَ إِلَىٰ مَنَازِلِ شِيعَتِنَا كَمَا يَنْظُرُ أَحَدُكُمْ إِلَىٰ الْكَوْكَبِ الدُّرِّيِّ فِي السَّمَاءِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingان اهل الجنه لينظرون الي منازل شيعتنا كما ينظر احدكم الي الكوكب الدري في السماء', 'ان اهل الجنه لينظرون الي منازل شيعتنا كما ينظر احدكم الي الكوكب الدري في السماء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 55, NULL, 'I turn now to the prohibition of exaggeration, of falling short, and of what resembles these two.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'i turn now to the prohibition of exaggeration of falling short and of what resembles these two', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 56, NULL, 'Maulana Amir al-Muminin Ali ibn Abi Talib (ع) said in his Four Hundred Manners:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'maulana amir al muminin ali ibn abi talib ع said in his four hundred manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 57, NULL, 'Sayingإِيَّاكُمْ وَالْغُلُوَّ فِينَا قُولُوا إِنَّا عِبَادٌ مَرْبُوبُونَ وَقُولُوا فِي فَضْلِنَا مَا شِئْتُمْ', '', 'إِيَّاكُمْ وَالْغُلُوَّ فِينَا قُولُوا إِنَّا عِبَادٌ مَرْبُوبُونَ وَقُولُوا فِي فَضْلِنَا مَا شِئْتُمْ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingاياكم والغلو فينا قولوا انا عباد مربوبون وقولوا في فضلنا ما شيتم', 'اياكم والغلو فينا قولوا انا عباد مربوبون وقولوا في فضلنا ما شيتم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 58, NULL, 'Beware of exaggeration concerning us. Say that we are servants under a Lord, and say of our excellence whatever you wish.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'beware of exaggeration concerning us say that we are servants under a lord and say of our excellence whatever you wish', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 59, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 60, NULL, 'Sayingإِذَا تَبَيَّنَ بِكُمُ الْحَقُّ فَلَا تَكُونُوا مَدَافِعَ عَجَالَى فَإِلَيْنَا يَرْجِعُ الْغَالِي وَبِنَا يَلْحَقُ الْمُقَصِّرُ', '', 'إِذَا تَبَيَّنَ بِكُمُ الْحَقُّ فَلَا تَكُونُوا مَدَافِعَ عَجَالَى فَإِلَيْنَا يَرْجِعُ الْغَالِي وَبِنَا يَلْحَقُ الْمُقَصِّرُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingاذا تبين بكم الحق فلا تكونوا مدافع عجالي فالينا يرجع الغالي وبنا يلحق المقصر', 'اذا تبين بكم الحق فلا تكونوا مدافع عجالي فالينا يرجع الغالي وبنا يلحق المقصر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 61, NULL, 'When the truth has been made plain through you, do not be rash in defending it, for the one who exaggerates will return to us, and we ourselves will raise up the one who falls short.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'when the truth has been made plain through you do not be rash in defending it for the one who exaggerates will return to us and we ourselves will raise up the one who falls short', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 62, NULL, 'Next, I record the commandments of the Imams (عَلَيْهِمُ السَّلَامُ) to their guardians, and the commandments of their preachers to the Shia.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'next i record the commandments of the imams عليهم السلام to their guardians and the commandments of their preachers to the shia', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 63, NULL, 'Maulana Amir al-Muminin Ali ibn Abi Talib (ع) said in his Four Hundred Manners:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'maulana amir al muminin ali ibn abi talib ع said in his four hundred manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 64, NULL, 'Sayingمن احبنا فليعمل عملنا ويستعين بالورع فانه أفضل ما يُستعان به في الدنيا والآخرة ولا تجالسوا لنا عايبا ولا تمدحوننا معلنين عند عدوّنا فيظهر حبنا ويستر بغضنا وتذلوا انفسكم عند سلطانهم ألزموا الصّدق فانه منجاة ارغبوا فيما عند الله وأطلبوا مرضاته وطاعته واصبروا عليها ما اقبح بالمؤمن أن يدخل الجنّة وهو مهنوك الستر لا تعبونا بالطلب والشفاعة لكم يوم القيامة بسبب ما قدمتم ولا تفضحوا أنفسكم عند عدؤكم يوم القيامة ولا تجعلوا أنفسكم عندهم في منزلتهم عند الله بالحقير من الدنيا تمسّكوا بما أمركم الله تعالى به فما بين أحدكم وبين أن يغتبط ويرى ما يحب الآ أن يحضره رسول الله صلى الله عليه وعلى آله وما عند الله خير وأبقى وتأتيه البشارة والله لتقرّن عينه وليحينّ لقاء الله', '', 'من احبنا فليعمل عملنا ويستعين بالورع فانه أفضل ما يُستعان به في الدنيا والآخرة ولا تجالسوا لنا عايبا ولا تمدحوننا معلنين عند عدوّنا فيظهر حبنا ويستر بغضنا وتذلوا انفسكم عند سلطانهم ألزموا الصّدق فانه منجاة ارغبوا فيما عند الله وأطلبوا مرضاته وطاعته واصبروا عليها ما اقبح بالمؤمن أن يدخل الجنّة وهو مهنوك الستر لا تعبونا بالطلب والشفاعة لكم يوم القيامة بسبب ما قدمتم ولا تفضحوا أنفسكم عند عدؤكم يوم القيامة ولا تجعلوا أنفسكم عندهم في منزلتهم عند الله بالحقير من الدنيا تمسّكوا بما أمركم الله تعالى به فما بين أحدكم وبين أن يغتبط ويرى ما يحب الآ أن يحضره رسول الله صلى الله عليه وعلى آله وما عند الله خير وأبقى وتأتيه البشارة والله لتقرّن عينه وليحينّ لقاء الله', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingمن احبنا فليعمل عملنا ويستعين بالورع فانه افضل ما يستعان به في الدنيا والاخره ولا تجالسوا لنا عايبا ولا تمدحوننا معلنين عند عدونا فيظهر حبنا ويستر بغضنا وتذلوا انفسكم عند سلطانهم الزموا الصدق فانه منجاه ارغبوا فيما عند الله واطلبوا مرضاته وطاعته واصبروا عليها ما اقبح بالمومن ان يدخل الجنه وهو مهنوك الستر لا تعبونا بالطلب والشفاعه لكم يوم القيامه بسبب ما قدمتم ولا تفضحوا انفسكم عند عدوكم يوم القيامه ولا تجعلوا انفسكم عندهم في منزلتهم عند الله بالحقير من الدنيا تمسكوا بما امركم الله تعالي به فما بين احدكم وبين ان يغتبط ويري ما يحب الا ان يحضره رسول الله صلي الله عليه وعلي اله وما عند الله خير وابقي وتاتيه البشاره والله لتقرن عينه وليحين لقاء الله', 'من احبنا فليعمل عملنا ويستعين بالورع فانه افضل ما يستعان به في الدنيا والاخره ولا تجالسوا لنا عايبا ولا تمدحوننا معلنين عند عدونا فيظهر حبنا ويستر بغضنا وتذلوا انفسكم عند سلطانهم الزموا الصدق فانه منجاه ارغبوا فيما عند الله واطلبوا مرضاته وطاعته واصبروا عليها ما اقبح بالمومن ان يدخل الجنه وهو مهنوك الستر لا تعبونا بالطلب والشفاعه لكم يوم القيامه بسبب ما قدمتم ولا تفضحوا انفسكم عند عدوكم يوم القيامه ولا تجعلوا انفسكم عندهم في منزلتهم عند الله بالحقير من الدنيا تمسكوا بما امركم الله تعالي به فما بين احدكم وبين ان يغتبط ويري ما يحب الا ان يحضره رسول الله صلي الله عليه وعلي اله وما عند الله خير وابقي وتاتيه البشاره والله لتقرن عينه وليحين لقاء الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 65, NULL, 'Whoever loves us, let him do our work and seek help through God-fearing restraint, for it is the finest means by which help can be sought, in this world and the next. Do not sit with anyone who reviles us, and do not praise us openly before our enemy — so that our love may be made plain and hatred of us concealed, and so that you may humble yourselves before their authority. Cling to truthfulness, for it is deliverance. Desire what is with God, seek His good pleasure and His obedience, and be patient in that. How ugly it is for a believer to enter Paradise with his covering torn away. Do not burden us with having to plead and intercede for you on the Day of Resurrection because of what you have sent forward. Do not disgrace yourselves before your enemy on the Day of Resurrection, and do not place yourselves — in their sight — at their own station before God for the sake of some paltry thing of this world. Hold fast to what God Almighty has commanded you. Nothing stands between any one of you and his rejoicing and seeing what he loves except that the Messenger of God should come to him. What is with God is better and more lasting, and the glad tidings will reach him. By God, his eye shall be gladdened, and the meeting with God shall surely come.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'whoever loves us let him do our work and seek help through god fearing restraint for it is the finest means by which help can be sought in this world and the next do not sit with anyone who reviles us and do not praise us openly before our enemy so that our love may be made plain and hatred of us concealed and so that you may humble yourselves before their authority cling to truthfulness for it is deliverance desire what is with god seek his good pleasure and his obedience and be patient in that how ugly it is for a believer to enter paradise with his covering torn away do not burden us with having to plead and intercede for you on the day of resurrection because of what you have sent forward do not disgrace yourselves before your enemy on the day of resurrection and do not place yourselves in their sight at their own station before god for the sake of some paltry thing of this world hold fast to what god almighty has commanded you nothing stands between any one of you and his rejoicing and seeing what he loves except that the messenger of god should come to him what is with god is better and more lasting and the glad tidings will reach him by god his eye shall be gladdened and the meeting with god shall surely come', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 66, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 67, NULL, 'Sayingإِيَّاكُمْ وَالْجِدَالِ فَأِنَّهُ يُورِثُ الشَّكَّ', '', 'إِيَّاكُمْ وَالْجِدَالِ فَأِنَّهُ يُورِثُ الشَّكَّ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingاياكم والجدال فانه يورث الشك', 'اياكم والجدال فانه يورث الشك');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 68, NULL, 'Beware of disputation, for it bequeaths doubt.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'beware of disputation for it bequeaths doubt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 69, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 70, NULL, 'Sayingاِحْسِبُوا كَلَامَكُمْ مِنْ أَعْمَالِكُمْ يَقِلَّ كَلَامُكُمْ اِلَّا فِي الْخَيْرِ', '', 'اِحْسِبُوا كَلَامَكُمْ مِنْ أَعْمَالِكُمْ يَقِلَّ كَلَامُكُمْ اِلَّا فِي الْخَيْرِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingاحسبوا كلامكم من اعمالكم يقل كلامكم الا في الخير', 'احسبوا كلامكم من اعمالكم يقل كلامكم الا في الخير');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 71, NULL, 'Reckon your speech as part of your deeds, and your speech will become little save what is good.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'reckon your speech as part of your deeds and your speech will become little save what is good', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 72, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 73, NULL, 'Sayingبَادِرُوا بِعَمَلِ الْخَيْرِ قَبْلَ أَنْ تُشْغَلُوا عَنْهُ بِغَيْرِهِ لِيَكُنْ جُلُّ كَلَامِكُمْ ذِكْرَ اللَّهِ عَزَّ وَجَلَّ اِحْذَرُوا الذُّنُوبَ فَأِنَّ الْعَبْدَ يُذْنِبُ الذَّنْبَ فَيُحْبَسُ عَنْهُ الرِّزْقُ', '', 'بَادِرُوا بِعَمَلِ الْخَيْرِ قَبْلَ أَنْ تُشْغَلُوا عَنْهُ بِغَيْرِهِ لِيَكُنْ جُلُّ كَلَامِكُمْ ذِكْرَ اللَّهِ عَزَّ وَجَلَّ اِحْذَرُوا الذُّنُوبَ فَأِنَّ الْعَبْدَ يُذْنِبُ الذَّنْبَ فَيُحْبَسُ عَنْهُ الرِّزْقُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingبادروا بعمل الخير قبل ان تشغلوا عنه بغيره ليكن جل كلامكم ذكر الله عز وجل احذروا الذنوب فان العبد يذنب الذنب فيحبس عنه الرزق', 'بادروا بعمل الخير قبل ان تشغلوا عنه بغيره ليكن جل كلامكم ذكر الله عز وجل احذروا الذنوب فان العبد يذنب الذنب فيحبس عنه الرزق');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 74, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 75, NULL, 'Sayingأَفْضَلُ عَمَلِ الْمُؤْمِنِ انْتِظَارُ الْفَرَجِ', '', 'أَفْضَلُ عَمَلِ الْمُؤْمِنِ انْتِظَارُ الْفَرَجِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingافضل عمل المومن انتظار الفرج', 'افضل عمل المومن انتظار الفرج');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 76, NULL, 'The best deed of the believer is awaiting the relief.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'the best deed of the believer is awaiting the relief', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 77, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 78, NULL, 'Sayingاَلسَّعِيدُ مَنْ وُعِظَ بِغَيْرِهِ فَاتَّعَظَ', '', 'اَلسَّعِيدُ مَنْ وُعِظَ بِغَيْرِهِ فَاتَّعَظَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingالسعيد من وعظ بغيره فاتعظ', 'السعيد من وعظ بغيره فاتعظ');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 79, NULL, 'Blessed is the one who is admonished by the case of another and takes the admonition.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'blessed is the one who is admonished by the case of another and takes the admonition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 80, NULL, 'I turn next to the affection owed to the Imams of the family of Muhammad (ع), the desires bound up with loyalty to them, and loyalty to their preachers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'i turn next to the affection owed to the imams of the family of muhammad ع the desires bound up with loyalty to them and loyalty to their preachers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 81, NULL, 'It was said in the nineteenth council of the Mustansiriya councils, may God''s peace be upon its author:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'it was said in the nineteenth council of the mustansiriya councils may gods peace be upon its author', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 82, NULL, 'Sayingفاستمعوا الآن ما نذكره مما أمر الله به من صلة القرابة وفيها سبعة واثنى عشر فأمّا السبعة فصلة من أمر الله بصلته من قرابةٍ رسول الله صلى الله عليه وآله لقوله تعالى قل لا أسألكم عليه أجراً الا المودة في القربى وهم أئمة الدين صلوات الله عليهم وعدّتهم سبعة يترددون كأيام الجمعة', '', 'فاستمعوا الآن ما نذكره مما أمر الله به من صلة القرابة وفيها سبعة واثنى عشر فأمّا السبعة فصلة من أمر الله بصلته من قرابةٍ رسول الله صلى الله عليه وآله لقوله تعالى قل لا أسألكم عليه أجراً الا المودة في القربى وهم أئمة الدين صلوات الله عليهم وعدّتهم سبعة يترددون كأيام الجمعة', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'sayingفاستمعوا الان ما نذكره مما امر الله به من صله القرابه وفيها سبعه واثني عشر فاما السبعه فصله من امر الله بصلته من قرابه رسول الله صلي الله عليه واله لقوله تعالي قل لا اسالكم عليه اجرا الا الموده في القربي وهم ايمه الدين صلوات الله عليهم وعدتهم سبعه يترددون كايام الجمعه', 'فاستمعوا الان ما نذكره مما امر الله به من صله القرابه وفيها سبعه واثني عشر فاما السبعه فصله من امر الله بصلته من قرابه رسول الله صلي الله عليه واله لقوله تعالي قل لا اسالكم عليه اجرا الا الموده في القربي وهم ايمه الدين صلوات الله عليهم وعدتهم سبعه يترددون كايام الجمعه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'guardians, proofs, and the limits of praise', '4. Guardians, Proofs, and the Limits of Praise', 83, NULL, 'Now listen to what we recount of what God has commanded regarding the ties of kinship — within which there are seven and twelve. As for the seven: this is the tie with those whom God commanded to be joined, from among the kin of the Messenger of God, as God says: "Say, I ask you no reward for it except affection toward my kin." These are the Imams of the religion, and their number is seven, recurring like the days of Friday.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 4 guardians proofs and the limits of praise', 'now listen to what we recount of what god has commanded regarding the ties of kinship within which there are seven and twelve as for the seven this is the tie with those whom god commanded to be joined from among the kin of the messenger of god as god says say i ask you no reward for it except affection toward my kin these are the imams of the religion and their number is seven recurring like the days of friday', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 0, NULL, 'I turn now to the affection believers owe one another, and to what follows from it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'i turn now to the affection believers owe one another and to what follows from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 1, NULL, 'Maulana Amir al-Muminin Ali ibn Abi Talib (ع) said in his four hundred manners:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'maulana amir al muminin ali ibn abi talib ع said in his four hundred manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 2, NULL, 'Sayingلَا تَحْقِرُوا ضُعَفَاءَ إِخْوَانِكُمْ فَإِنَّهُ مَنِ اِحْتَقَرَ مُؤْمِنًا حَقَّرَهُ اَللَّهُ وَمَقَتَهُ وَلَمْ يَجْمَعْ بَيْنَهُمَا يَوْمَ اَلْقِيَامَةِ إِلَّا أَنْ يَتُوبَ، وَلَا يُكَلِّفُ أَحَدُكُمْ أَخَاهُ اَلطَّلَبَ إِلَيْهِ إِذَا عَرَفَ حَاجَتَهُ، تَزَاوَرُوا وَتَعَاطَفُوا وَتَبَاذَلُوا، وَلَا تَكُونُوا بِمَنْزِلَةِ اَلْمُنَافِقِ اَلَّذِي يَصِفُ مَا لَا يَفْعَلُ.', '', 'لَا تَحْقِرُوا ضُعَفَاءَ إِخْوَانِكُمْ فَإِنَّهُ مَنِ اِحْتَقَرَ مُؤْمِنًا حَقَّرَهُ اَللَّهُ وَمَقَتَهُ وَلَمْ يَجْمَعْ بَيْنَهُمَا يَوْمَ اَلْقِيَامَةِ إِلَّا أَنْ يَتُوبَ، وَلَا يُكَلِّفُ أَحَدُكُمْ أَخَاهُ اَلطَّلَبَ إِلَيْهِ إِذَا عَرَفَ حَاجَتَهُ، تَزَاوَرُوا وَتَعَاطَفُوا وَتَبَاذَلُوا، وَلَا تَكُونُوا بِمَنْزِلَةِ اَلْمُنَافِقِ اَلَّذِي يَصِفُ مَا لَا يَفْعَلُ.', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'sayingلا تحقروا ضعفاء اخوانكم فانه من احتقر مومنا حقره الله ومقته ولم يجمع بينهما يوم القيامه الا ان يتوب ولا يكلف احدكم اخاه الطلب اليه اذا عرف حاجته تزاوروا وتعاطفوا وتباذلوا ولا تكونوا بمنزله المنافق الذي يصف ما لا يفعل', 'لا تحقروا ضعفاء اخوانكم فانه من احتقر مومنا حقره الله ومقته ولم يجمع بينهما يوم القيامه الا ان يتوب ولا يكلف احدكم اخاه الطلب اليه اذا عرف حاجته تزاوروا وتعاطفوا وتباذلوا ولا تكونوا بمنزله المنافق الذي يصف ما لا يفعل');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 3, NULL, 'Do not despise the weak among your brothers, for whoever despises a believer is belittled and detested by God, and the two will not be brought together on the Day of Resurrection unless he repents. Let none of you force his brother to ask when he already knows his need. Visit one another, be tender with one another, and give freely to one another. Do not be like the hypocrite, who describes what he does not do.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'do not despise the weak among your brothers for whoever despises a believer is belittled and detested by god and the two will not be brought together on the day of resurrection unless he repents let none of you force his brother to ask when he already knows his need visit one another be tender with one another and give freely to one another do not be like the hypocrite who describes what he does not do', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 4, NULL, 'He said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 5, NULL, 'Sayingالْمُسْلِمُ مِرْآةُ أَخِيهِ الْمُسْلِمِ، فَإِنْ رَأَيْتُمْ مِنْ أَخِيكُمْ هَفْوَةً فَلَا تَكُونُوا عَلَيْهِ أَلْبًا وَأَرْشِدُوهُ وَانْصَحُوا لَهُ وَتَرَفَّقُوا بِهِ.', '', 'الْمُسْلِمُ مِرْآةُ أَخِيهِ الْمُسْلِمِ، فَإِنْ رَأَيْتُمْ مِنْ أَخِيكُمْ هَفْوَةً فَلَا تَكُونُوا عَلَيْهِ أَلْبًا وَأَرْشِدُوهُ وَانْصَحُوا لَهُ وَتَرَفَّقُوا بِهِ.', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'sayingالمسلم مراه اخيه المسلم فان رايتم من اخيكم هفوه فلا تكونوا عليه البا وارشدوه وانصحوا له وترفقوا به', 'المسلم مراه اخيه المسلم فان رايتم من اخيكم هفوه فلا تكونوا عليه البا وارشدوه وانصحوا له وترفقوا به');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 6, NULL, 'Sayingإِيَّاكُمْ وَالْخِلَافَ فَإِنَّهُ مَرُوقٌ، وَعَلَيْكُمْ بِالْفَضْلِ، تَرَافَقُوا وَتَرَاحَمُوا.', '', 'إِيَّاكُمْ وَالْخِلَافَ فَإِنَّهُ مَرُوقٌ، وَعَلَيْكُمْ بِالْفَضْلِ، تَرَافَقُوا وَتَرَاحَمُوا.', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'sayingاياكم والخلاف فانه مروق وعليكم بالفضل ترافقوا وتراحموا', 'اياكم والخلاف فانه مروق وعليكم بالفضل ترافقوا وتراحموا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 7, NULL, 'The Muslim is the mirror of his Muslim brother. If you see a slip in your brother, do not band together against him; guide him, counsel him, and deal gently with him. Beware of discord, for it leads a person away from the path. Hold fast to generous conduct, keep company with kindness, and show mercy to one another.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'the muslim is the mirror of his muslim brother if you see a slip in your brother do not band together against him guide him counsel him and deal gently with him beware of discord for it leads a person away from the path hold fast to generous conduct keep company with kindness and show mercy to one another', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 8, NULL, 'He said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 9, NULL, 'Sayingإِيَّاكُمْ وَالْغِيبَةَ فَإِنَّ الْمُسْلِمَ لَا يَغْتَابُ أَخَاهُ، وَقَدْ نَهَى اللَّهُ عَزَّ وَجَلَّ عَنْ ذَلِكَ فَقَالَ: أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًۭا فَكَرِهْتُمُوهُ.', '', 'إِيَّاكُمْ وَالْغِيبَةَ فَإِنَّ الْمُسْلِمَ لَا يَغْتَابُ أَخَاهُ، وَقَدْ نَهَى اللَّهُ عَزَّ وَجَلَّ عَنْ ذَلِكَ فَقَالَ: أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًۭا فَكَرِهْتُمُوهُ.', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'sayingاياكم والغيبه فان المسلم لا يغتاب اخاه وقد نهي الله عز وجل عن ذلك فقال ايحب احدكم ان ياكل لحم اخيه ميتا فكرهتموه', 'اياكم والغيبه فان المسلم لا يغتاب اخاه وقد نهي الله عز وجل عن ذلك فقال ايحب احدكم ان ياكل لحم اخيه ميتا فكرهتموه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 10, NULL, 'Beware of backbiting, for a Muslim does not speak ill of his brother behind his back. God, mighty and majestic, has forbidden it, saying: Would any of you like to eat the flesh of his dead brother? You would hate it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'beware of backbiting for a muslim does not speak ill of his brother behind his back god mighty and majestic has forbidden it saying would any of you like to eat the flesh of his dead brother you would hate it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 11, NULL, 'He said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 12, NULL, 'Sayingإِذَا لَقِيتُمْ إِخْوَانَكُمُ الْمُؤْمِنِينَ فَصَافِحُوهُمْ وَأَظْهِرُوا لَهُمُ الْبَشَاشَةَ وَالْبِشْرَ، تَفْتَرِقُوا وَمَا عَلَيْكُمْ مِنَ الْأَوْزَارِ قَدْ ذَهَبَتْ.', '', 'إِذَا لَقِيتُمْ إِخْوَانَكُمُ الْمُؤْمِنِينَ فَصَافِحُوهُمْ وَأَظْهِرُوا لَهُمُ الْبَشَاشَةَ وَالْبِشْرَ، تَفْتَرِقُوا وَمَا عَلَيْكُمْ مِنَ الْأَوْزَارِ قَدْ ذَهَبَتْ.', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'sayingاذا لقيتم اخوانكم المومنين فصافحوهم واظهروا لهم البشاشه والبشر تفترقوا وما عليكم من الاوزار قد ذهبت', 'اذا لقيتم اخوانكم المومنين فصافحوهم واظهروا لهم البشاشه والبشر تفترقوا وما عليكم من الاوزار قد ذهبت');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 13, NULL, 'When you meet your believing brothers, greet them with a handshake and a bright, welcoming face. By the time you part, whatever burdens you each carried will have lifted.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'when you meet your believing brothers greet them with a handshake and a bright welcoming face by the time you part whatever burdens you each carried will have lifted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 14, NULL, 'I also present here the book of questions — the question from the venerable Shaykh Shimon bin Muhammad al-Ghuri al-Hindi (رض), and the answer from our master Badr al-Din, Sayyidina Hassan bin Sayyidina Idris bin Sayyidina al-Hassan bin Sayyidina Abdullah al-Ala. The question concerned a custom widespread among the people of India: some of them ask their neighbors for water, salt, food, and similar provisions, and this is done freely on both sides, each considering it permissible. Those who ask are not unable to purchase such things; they simply do not have them at that moment, and so they turn to whoever does. The question was whether such asking is permitted to them or not. The answer was:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'i also present here the book of questions the question from the venerable shaykh shimon bin muhammad al ghuri al hindi رض and the answer from our master badr al din sayyidina hassan bin sayyidina idris bin sayyidina al hassan bin sayyidina abdullah al ala the question concerned a custom widespread among the people of india some of them ask their neighbors for water salt food and similar provisions and this is done freely on both sides each considering it permissible those who ask are not unable to purchase such things they simply do not have them at that moment and so they turn to whoever does the question was whether such asking is permitted to them or not the answer was', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 15, NULL, 'Sayingلَا بَأْسَ بِهِ، هَذَا لِصَفْوِّ الْمَوَدَّةِ وَحُسْنِ الْأُخُوَّةِ.', '', 'لَا بَأْسَ بِهِ، هَذَا لِصَفْوِّ الْمَوَدَّةِ وَحُسْنِ الْأُخُوَّةِ.', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'sayingلا باس به هذا لصفو الموده وحسن الاخوه', 'لا باس به هذا لصفو الموده وحسن الاخوه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 16, NULL, 'There is no harm in it. This belongs to the purity of affection and the excellence of brotherhood.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'there is no harm in it this belongs to the purity of affection and the excellence of brotherhood', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 17, NULL, 'I turn now to the righteousness owed to parents — both the spiritual and the bodily.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'i turn now to the righteousness owed to parents both the spiritual and the bodily', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 18, NULL, 'He said in the seventeenth council of the Mustansiriya councils, may God''s peace be upon its author: the explanation of the seven obligatory rights we mentioned has now been completed. By that is meant the seven that correspond to the seven clauses of the testimony, matching the number of its clauses, which are not subject to dispute. There remain still the twelve practices, corresponding to the number of its letters, in the manner we already defined. The first of these is righteousness toward parents. God Almighty said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'he said in the seventeenth council of the mustansiriya councils may gods peace be upon its author the explanation of the seven obligatory rights we mentioned has now been completed by that is meant the seven that correspond to the seven clauses of the testimony matching the number of its clauses which are not subject to dispute there remain still the twelve practices corresponding to the number of its letters in the manner we already defined the first of these is righteousness toward parents god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 19, NULL, 'Al-Ahqaf: 15وَوَصَّيْنَا ٱلْإِنسَنَ بِوَلِدَيْهِ إِحْسَنًا حَمَلَتْهُ أُمُّهُۥ كُرْهًۭا وَوَضَعَتْهُ كُرْهًۭا', '', 'وَوَصَّيْنَا ٱلْإِنسَنَ بِوَلِدَيْهِ إِحْسَنًا حَمَلَتْهُ أُمُّهُۥ كُرْهًۭا وَوَضَعَتْهُ كُرْهًۭا', 'Al-Ahqaf: 15', 46, 15, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'al ahqaf 15ووصينا الانسن بولديه احسنا حملته امه كرها ووضعته كرها', 'ووصينا الانسن بولديه احسنا حملته امه كرها ووضعته كرها');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 20, NULL, 'And We have enjoined upon man goodness toward his parents; his mother carried him with hardship and gave birth to him with hardship.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'and we have enjoined upon man goodness toward his parents his mother carried him with hardship and gave birth to him with hardship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 21, NULL, 'He thus enjoined goodness toward both parents together, yet He laid the mother''s deed to the child''s account and not the father''s. And He said in another place:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'he thus enjoined goodness toward both parents together yet he laid the mothers deed to the childs account and not the fathers and he said in another place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 22, NULL, 'Luqman: 14وَوَصَّيْنَا ٱلْإِنسَنَ بِوَلِدَيْهِ حَمَلَتْهُ أُمُّهُۥ وَهْنًا عَلَىٰ وَهْنٍۢ', '', 'وَوَصَّيْنَا ٱلْإِنسَنَ بِوَلِدَيْهِ حَمَلَتْهُ أُمُّهُۥ وَهْنًا عَلَىٰ وَهْنٍۢ', 'Luqman: 14', 31, 14, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'luqman 14ووصينا الانسن بولديه حملته امه وهنا علي وهن', 'ووصينا الانسن بولديه حملته امه وهنا علي وهن');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 23, NULL, 'And We have enjoined upon man goodness toward his parents; his mother carried him in weakness upon weakness.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'and we have enjoined upon man goodness toward his parents his mother carried him in weakness upon weakness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 24, NULL, 'In both these places, it is the mother''s deed that is counted upon the child. Whoever God has distinguished by mention must be distinguished with honor and righteousness.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'in both these places it is the mothers deed that is counted upon the child whoever god has distinguished by mention must be distinguished with honor and righteousness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 25, NULL, 'He said in the eighteenth council of them: We had reached, in the matter of righteousness toward parents, what God counted upon the child from the deed of the mother — a deed that earns her an added rank in righteousness and in dignity. So listen now to what is recited to you: in righteousness toward parents there are seven obligatory parts and twelve manners.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'he said in the eighteenth council of them we had reached in the matter of righteousness toward parents what god counted upon the child from the deed of the mother a deed that earns her an added rank in righteousness and in dignity so listen now to what is recited to you in righteousness toward parents there are seven obligatory parts and twelve manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 26, NULL, 'The believer must show righteousness to his father and mother, who are the cause of his bodily form coming into being, and who labored to nourish him with the most beneficial and pleasing of foods until he attained the fullness of what they hoped for him. He must show righteousness to his two parents in religion, who are the cause of his form coming into being in knowledge — they are the Imam of the age (ع) and his proof. And he must show righteousness to the two fathers of this community, who convey to them the divine sciences — they are the Prophet and the legatee, and the Imams from their progeny. It is related from the Messenger of God that he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'the believer must show righteousness to his father and mother who are the cause of his bodily form coming into being and who labored to nourish him with the most beneficial and pleasing of foods until he attained the fullness of what they hoped for him he must show righteousness to his two parents in religion who are the cause of his form coming into being in knowledge they are the imam of the age ع and his proof and he must show righteousness to the two fathers of this community who convey to them the divine sciences they are the prophet and the legatee and the imams from their progeny it is related from the messenger of god that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 27, NULL, 'Sayingأَنَا وَأَنْتَ يَا عَلِيُّ أَبَوَا هَذِهِ الْأُمَّةِ', '', 'أَنَا وَأَنْتَ يَا عَلِيُّ أَبَوَا هَذِهِ الْأُمَّةِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'sayingانا وانت يا علي ابوا هذه الامه', 'انا وانت يا علي ابوا هذه الامه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 28, NULL, 'I and you, O Ali, are the two fathers of this community.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'i and you o ali are the two fathers of this community', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 29, NULL, 'The seal of this righteousness is a person''s righteousness toward his own soul: that he make the truth plain to it and establish it therein, that he magnify it for the soul and so awaken its longing, that he place fear in it, deal gently with it, deliver it from what would destroy it, and rescue it from what has bound it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'the seal of this righteousness is a persons righteousness toward his own soul that he make the truth plain to it and establish it therein that he magnify it for the soul and so awaken its longing that he place fear in it deal gently with it deliver it from what would destroy it and rescue it from what has bound it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 30, NULL, 'As for the twelve manners in righteousness toward parents, they are that he honor their dwelling place, that he rise for them when he sees them, that he answer their call, that he lower his voice in their presence, that he magnify them and not rebuke them, that he lower to them the wing of humility out of mercy, that he not walk ahead of them in light nor ahead of them in darkness, that he not show any opposition to their command, that he not say to either of them a word of complaint, that he desire life for them in their old age as they desired life for him in his childhood, and that he provide for the needs of each of them when they have need of him, just as they provided for him when he had need of them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'as for the twelve manners in righteousness toward parents they are that he honor their dwelling place that he rise for them when he sees them that he answer their call that he lower his voice in their presence that he magnify them and not rebuke them that he lower to them the wing of humility out of mercy that he not walk ahead of them in light nor ahead of them in darkness that he not show any opposition to their command that he not say to either of them a word of complaint that he desire life for them in their old age as they desired life for him in his childhood and that he provide for the needs of each of them when they have need of him just as they provided for him when he had need of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 31, NULL, 'He said in the twenty-fourth council of them: among the obligatory rights there are three rights.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'he said in the twenty fourth council of them among the obligatory rights there are three rights', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 32, NULL, 'The right of God. The right of parents. The right of the child.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'the right of god the right of parents the right of the child', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 33, NULL, 'God has commanded that they be discharged, and He will not accept them unless they are discharged in full. The right of God is to come out from what God has forbidden and to enter into what God has commanded. The right of parents is thankfulness for what has passed and obedience in what remains. The right of the child is that he be raised with tenderness, nourished with food, and taught the Book and wisdom.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'god has commanded that they be discharged and he will not accept them unless they are discharged in full the right of god is to come out from what god has forbidden and to enter into what god has commanded the right of parents is thankfulness for what has passed and obedience in what remains the right of the child is that he be raised with tenderness nourished with food and taught the book and wisdom', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 34, NULL, 'Maulana Amir al-Muminin Ali ibn Abi Talib (ع) said in his four hundred manners:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'maulana amir al muminin ali ibn abi talib ع said in his four hundred manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 35, NULL, 'Sayingمَنْ خَالَفَ وَالِدَيْهِ عَقَّهُمَا', '', 'مَنْ خَالَفَ وَالِدَيْهِ عَقَّهُمَا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'sayingمن خالف والديه عقهما', 'من خالف والديه عقهما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 36, NULL, 'Whoever goes against his parents has been undutiful to them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'whoever goes against his parents has been undutiful to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 37, NULL, 'I mention next the affection owed to relatives — those of religion and those of the world.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'i mention next the affection owed to relatives those of religion and those of the world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 38, NULL, 'He said in the nineteenth council of the Mustansiriya councils: as for a person''s relatives, they are divided into twelve categories, the first of them being:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'he said in the nineteenth council of the mustansiriya councils as for a persons relatives they are divided into twelve categories the first of them being', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 39, NULL, 'The children, male and female. Then the children of the father by the same mother, who are the brothers of one stock, called الأشقاء (full brothers). And the children of the father by another mother, who are بَنُو الْعَلَّاتِ (بَنُوا الْعَلَّاتِ). And the children of the mother by another father, who are الأخياف (maternal half-brothers), called brothers through the mother. and 6. The grandfathers and grandmothers on the father''s side. and 8. The grandfathers and grandmothers on the mother''s side. The paternal uncles. The paternal aunts. The maternal uncles. The maternal aunts.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'the children male and female then the children of the father by the same mother who are the brothers of one stock called الاشقاء full brothers and the children of the father by another mother who are بنو العلات بنوا العلات and the children of the mother by another father who are الاخياف maternal half brothers called brothers through the mother and 6 the grandfathers and grandmothers on the fathers side and 8 the grandfathers and grandmothers on the mothers side the paternal uncles the paternal aunts the maternal uncles the maternal aunts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 40, NULL, 'Whoever is related through one of these takes that one''s ruling. As for the tie with them that has been commanded, it belongs to those who do good that they keep the tie with them even if the relatives cut them off, that they give to them even if the relatives withhold from them, that they draw near to them even if the relatives push them away, and that they love them even if the relatives abandon them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'whoever is related through one of these takes that ones ruling as for the tie with them that has been commanded it belongs to those who do good that they keep the tie with them even if the relatives cut them off that they give to them even if the relatives withhold from them that they draw near to them even if the relatives push them away and that they love them even if the relatives abandon them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 41, NULL, 'Maulana Amir al-Muminin Ali ibn Abi Talib (ع) said in his four hundred manners:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'maulana amir al muminin ali ibn abi talib ع said in his four hundred manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 42, NULL, 'Sayingولا يمين في قطيعة رحم', '', 'ولا يمين في قطيعة رحم', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'sayingولا يمين في قطيعه رحم', 'ولا يمين في قطيعه رحم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 43, NULL, 'لا يمين في قطيعة رحم — there is no binding oath in the severing of kinship.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'لا يمين في قطيعه رحم there is no binding oath in the severing of kinship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 44, NULL, 'I turn now to the affection owed to neighbors — both those of religion and those of the world — and to all that follows from it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'i turn now to the affection owed to neighbors both those of religion and those of the world and to all that follows from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 45, NULL, 'I said in the twentieth council of the Mustansiriya councils: building upon what I mentioned of righteousness toward parents and the ties of kinship, among the religious practices set forth earlier, comes the safeguarding of the neighbor. God Almighty said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'i said in the twentieth council of the mustansiriya councils building upon what i mentioned of righteousness toward parents and the ties of kinship among the religious practices set forth earlier comes the safeguarding of the neighbor god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 46, NULL, 'An-Nisa: 36وَٱلْجَارِ ذِى ٱلْقُرْبَىٰ وَٱلْجَارِ ٱلْجُنُبِ وَٱلصَّاحِبِ بِٱلْجَنۢبِ', '', 'وَٱلْجَارِ ذِى ٱلْقُرْبَىٰ وَٱلْجَارِ ٱلْجُنُبِ وَٱلصَّاحِبِ بِٱلْجَنۢبِ', 'An-Nisa: 36', 4, 36, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'an nisa 36والجار ذي القربي والجار الجنب والصاحب بالجنب', 'والجار ذي القربي والجار الجنب والصاحب بالجنب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 47, NULL, 'And the neighbor who is kin, and the neighbor who is a stranger, and the companion at your side.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'and the neighbor who is kin and the neighbor who is a stranger and the companion at your side', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 48, NULL, 'This subject is divided into seven parts and twelve manners. The first of them:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'this subject is divided into seven parts and twelve manners the first of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 49, NULL, 'Safeguarding the believing neighbor between whom and you there is kinship; he holds three rights — the right of neighborliness, the right of kinship, and the right of faith. The second is the one between whom and you there is both neighborliness and lineage, but no bond of faith between you; he holds two rights — the right of neighborliness and the right of kinship. The third is the neighbor who is a stranger — that is, the believing neighbor between whom and you there is no kinship; he holds the right of neighborliness and the right of faith. The fourth is the companion at your side — that is, the neighbor who differs from you in religion and creed; he holds the right of neighborliness. The fifth is the companion aboard the ship — the one who sits beside you for the length of your journey; he holds the right of nearness. The sixth is the one who shares your litter. The seventh is the one who sits with you to receive wisdom; his is the most binding sanctity and the most obligatory claim upon you.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'safeguarding the believing neighbor between whom and you there is kinship he holds three rights the right of neighborliness the right of kinship and the right of faith the second is the one between whom and you there is both neighborliness and lineage but no bond of faith between you he holds two rights the right of neighborliness and the right of kinship the third is the neighbor who is a stranger that is the believing neighbor between whom and you there is no kinship he holds the right of neighborliness and the right of faith the fourth is the companion at your side that is the neighbor who differs from you in religion and creed he holds the right of neighborliness the fifth is the companion aboard the ship the one who sits beside you for the length of your journey he holds the right of nearness the sixth is the one who shares your litter the seventh is the one who sits with you to receive wisdom his is the most binding sanctity and the most obligatory claim upon you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 50, NULL, 'As for the twelve manners of neighborliness, they are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'as for the twelve manners of neighborliness they are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 51, NULL, 'That the neighbor not peer into his neighbor''s house. That he not listen in on his neighbor''s speech within his dwelling. That he not disclose any matter of his neighbor''s that comes to his knowledge. That he not let his neighbor hear from his house what his neighbor would hate to hear. That he not show his neighbor what his neighbor would hate to see. That he not withhold a household implement from his neighbor when asked for it. That he not act haughtily toward his neighbor when he himself is of higher station. That he not envy his neighbor when his neighbor is above him. That he help his neighbor when his neighbor seeks his help. That he cover his neighbor''s awrah (that which should remain concealed) if it becomes exposed. That he cause his neighbor no injury of any kind. That he bear his neighbor''s injury with patience.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'that the neighbor not peer into his neighbors house that he not listen in on his neighbors speech within his dwelling that he not disclose any matter of his neighbors that comes to his knowledge that he not let his neighbor hear from his house what his neighbor would hate to hear that he not show his neighbor what his neighbor would hate to see that he not withhold a household implement from his neighbor when asked for it that he not act haughtily toward his neighbor when he himself is of higher station that he not envy his neighbor when his neighbor is above him that he help his neighbor when his neighbor seeks his help that he cover his neighbors awrah that which should remain concealed if it becomes exposed that he cause his neighbor no injury of any kind that he bear his neighbors injury with patience', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 52, NULL, 'Sayingفَهَذِهِ أَفْعَالُ قَوْمٍ قَدِ امْتَحَنَ اللَّهُ قُلُوبَهُمُ التَّقْوَى', '', 'فَهَذِهِ أَفْعَالُ قَوْمٍ قَدِ امْتَحَنَ اللَّهُ قُلُوبَهُمُ التَّقْوَى', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'sayingفهذه افعال قوم قد امتحن الله قلوبهم التقوي', 'فهذه افعال قوم قد امتحن الله قلوبهم التقوي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'parents, kin, and the neighbor at your side', '5. Parents, Kin, and the Neighbor at Your Side', 53, NULL, 'These are the deeds of a people whose hearts God has tested for piety.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 5 parents kin and the neighbor at your side', 'these are the deeds of a people whose hearts god has tested for piety', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 0, NULL, 'I turn now to what is sought in the pursuit of knowledge, in the Quran, and in what belongs with them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'i turn now to what is sought in the pursuit of knowledge in the quran and in what belongs with them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 1, NULL, 'Mawlana Amir al-Muminin Ali ibn Abi Talib (ع) said in his four hundred maxims of conduct:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'mawlana amir al muminin ali ibn abi talib ع said in his four hundred maxims of conduct', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 2, NULL, 'Sayingلَا صَمْتَ إِلَى اللَّيْلِ اِلَّا فِي ذِكْرِ اللَّهِ ، لَا تَعَرَّبْ بَعْدَ الْهِجْرَةِ', '', 'لَا صَمْتَ إِلَى اللَّيْلِ اِلَّا فِي ذِكْرِ اللَّهِ ، لَا تَعَرَّبْ بَعْدَ الْهِجْرَةِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingلا صمت الي الليل الا في ذكر الله لا تعرب بعد الهجره', 'لا صمت الي الليل الا في ذكر الله لا تعرب بعد الهجره');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 3, NULL, 'There is no silence until nightfall except in the remembrance of God; and do not turn back to the desert after the migration.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'there is no silence until nightfall except in the remembrance of god and do not turn back to the desert after the migration', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 4, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 5, NULL, 'Sayingلَا يَقْرَأُ الْعَاقِلُ الْقُرْآنَ إِذَا كَانَ عَلَى غَيْرِ وُضُوءٍ حَتَّى يَتَطَهَّرَ لَهُ', '', 'لَا يَقْرَأُ الْعَاقِلُ الْقُرْآنَ إِذَا كَانَ عَلَى غَيْرِ وُضُوءٍ حَتَّى يَتَطَهَّرَ لَهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingلا يقرا العاقل القران اذا كان علي غير وضوء حتي يتطهر له', 'لا يقرا العاقل القران اذا كان علي غير وضوء حتي يتطهر له');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 6, NULL, 'The man of sound mind does not recite the Quran while in a state of ritual impurity — not until he has purified himself for it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'the man of sound mind does not recite the quran while in a state of ritual impurity not until he has purified himself for it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 7, NULL, 'I turn now to the one from whom knowledge must be taken, and to the one who must be shunned and whose word refused, and all that belongs with that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'i turn now to the one from whom knowledge must be taken and to the one who must be shunned and whose word refused and all that belongs with that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 8, NULL, 'Mawlana Amir al-Muminin Ali ibn Abi Talib (ع) said in his four hundred maxims of conduct:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'mawlana amir al muminin ali ibn abi talib ع said in his four hundred maxims of conduct', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 9, NULL, 'Sayingلَا يَغْلِبُ عَلَيْكُمُ الْمُرْجِئَةُ بِرَأْيِهَا', '', 'لَا يَغْلِبُ عَلَيْكُمُ الْمُرْجِئَةُ بِرَأْيِهَا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingلا يغلب عليكم المرجيه برايها', 'لا يغلب عليكم المرجيه برايها');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 10, NULL, 'Let not the Murjiah overcome you with their opinion.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'let not the murjiah overcome you with their opinion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 11, NULL, 'It is said in the book of questions — which comes from the most exalted Sheikh Shamoun ibn Muhammad Ghori al-Hindi (رض), together with the answers of our master Badr al-Din, Sayyidina Hasan ibn Sayyidina Idris ibn Sayyidina al-Hasan ibn Sayyidina Abdullah al-Anf — as follows.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'it is said in the book of questions which comes from the most exalted sheikh shamoun ibn muhammad ghori al hindi رض together with the answers of our master badr al din sayyidina hasan ibn sayyidina idris ibn sayyidina al hasan ibn sayyidina abdullah al anf as follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 12, NULL, 'The question: What do you say, O illuminator of truths for those who deserve them, concerning this matter? Our master Hamid al-Din mentioned in the book al-Hadi wal-Mustahdi, with conclusive proofs; and likewise our master al-Numan mentioned in the book al-Daaim; and the most exalted and most excellent Dai, most perfect in composition, Sayyidina Idris ibn al-Hasan, stated in the book Zahr al-Maani that al-Sadiq (ع) had granted al-Shafii license while he kept it concealed. So, our master, did his condition change as the conditions of al-Mughirah and Abu al-Khattab and their like changed? Or did the ignorant invent a falsehood in claiming his school, as one faction claimed the Imamate of Muhammad ibn al-Hanafiyya and Abdullah ibn Muawiyah, when neither of those two ever claimed it for himself? Be gracious with an answer — brief and sufficient for those who possess insight in religion.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'the question what do you say o illuminator of truths for those who deserve them concerning this matter our master hamid al din mentioned in the book al hadi wal mustahdi with conclusive proofs and likewise our master al numan mentioned in the book al daaim and the most exalted and most excellent dai most perfect in composition sayyidina idris ibn al hasan stated in the book zahr al maani that al sadiq ع had granted al shafii license while he kept it concealed so our master did his condition change as the conditions of al mughirah and abu al khattab and their like changed or did the ignorant invent a falsehood in claiming his school as one faction claimed the imamate of muhammad ibn al hanafiyya and abdullah ibn muawiyah when neither of those two ever claimed it for himself be gracious with an answer brief and sufficient for those who possess insight in religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 13, NULL, 'The answer:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'the answer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 14, NULL, 'Sayingنعم قد كان أطلق له لاقراره فضل أهل البيت عَلَيْهِمُ السَّلَامُ لا غير', '', 'نعم قد كان أطلق له لاقراره فضل أهل البيت عَلَيْهِمُ السَّلَامُ لا غير', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingنعم قد كان اطلق له لاقراره فضل اهل البيت عليهم السلام لا غير', 'نعم قد كان اطلق له لاقراره فضل اهل البيت عليهم السلام لا غير');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 15, NULL, 'Yes, he had granted him license, but only because of his acknowledgment of the excellence of the Ahl al-Bayt, and for nothing else.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'yes he had granted him license but only because of his acknowledgment of the excellence of the ahl al bayt and for nothing else', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 16, NULL, 'It is said in the same book of questions.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'it is said in the same book of questions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 17, NULL, 'The question: What do you say, O school of insights and of the inmost thoughts, concerning the saying of the Prophet:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'the question what do you say o school of insights and of the inmost thoughts concerning the saying of the prophet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 18, NULL, 'Sayingمَنْ نَظَرَ فِي كِتَابِ أَخِيهِ بِغَيْرِ أِذْنِهِ فَكَأَنَّمَا يَنْظُرُ فِي النَّارِ', '', 'مَنْ نَظَرَ فِي كِتَابِ أَخِيهِ بِغَيْرِ أِذْنِهِ فَكَأَنَّمَا يَنْظُرُ فِي النَّارِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingمن نظر في كتاب اخيه بغير اذنه فكانما ينظر في النار', 'من نظر في كتاب اخيه بغير اذنه فكانما ينظر في النار');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 19, NULL, 'Whoever looks into the book of his brother without his permission is as one who looks into the Fire.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'whoever looks into the book of his brother without his permission is as one who looks into the fire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 20, NULL, 'Our master: when the people of a school gather together, each freely looks into the others'' books without asking permission. What, then, does this saying mean?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'our master when the people of a school gather together each freely looks into the others books without asking permission what then does this saying mean', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 21, NULL, 'The answer:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'the answer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 22, NULL, 'Sayingهَذَا فِي كِتَابِ الْحَقِيقَةِ لَا يَنْظُرُ الْإِنْسَانُ اِلَّا بِأِذْنِ مَنْ أَطْلَقَ لَهُ ذَلِكَ وَأَمَّا فِي غَيْرِهَا فَأَدَبٌ وَلَيْسَ بِلَازِمٍ', '', 'هَذَا فِي كِتَابِ الْحَقِيقَةِ لَا يَنْظُرُ الْإِنْسَانُ اِلَّا بِأِذْنِ مَنْ أَطْلَقَ لَهُ ذَلِكَ وَأَمَّا فِي غَيْرِهَا فَأَدَبٌ وَلَيْسَ بِلَازِمٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingهذا في كتاب الحقيقه لا ينظر الانسان الا باذن من اطلق له ذلك واما في غيرها فادب وليس بلازم', 'هذا في كتاب الحقيقه لا ينظر الانسان الا باذن من اطلق له ذلك واما في غيرها فادب وليس بلازم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 23, NULL, 'This concerns the book of inner truth — أُطْلِقَ الْإِنْسَانُ — into which no one may look except by the permission of the one who granted him access to it. For all other books, the matter rests on good manners alone and carries no binding obligation.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'this concerns the book of inner truth اطلق الانسان into which no one may look except by the permission of the one who granted him access to it for all other books the matter rests on good manners alone and carries no binding obligation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 24, NULL, 'And it is said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'and it is said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 25, NULL, 'The question: What do you say, O comfort of our eyes, about a man who borrows the Quran or another book from someone and finds in it damage and disorder? Is it permitted for him — or for anyone الا who notices this — to cut away the disorder and set it right without the owner''s permission, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'the question what do you say o comfort of our eyes about a man who borrows the quran or another book from someone and finds in it damage and disorder is it permitted for him or for anyone الا who notices this to cut away the disorder and set it right without the owners permission or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 26, NULL, 'The answer:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'the answer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 27, NULL, 'Sayingلَا بَأْسَ بِأَنْ يُصْلِحَهُ وَلَيْسَ لَهُ لَازِمٌ', '', 'لَا بَأْسَ بِأَنْ يُصْلِحَهُ وَلَيْسَ لَهُ لَازِمٌ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingلا باس بان يصلحه وليس له لازم', 'لا باس بان يصلحه وليس له لازم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 28, NULL, 'There is no بأس in his correcting it, and it is not لازم upon him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'there is no باس in his correcting it and it is not لازم upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 29, NULL, 'And it is said in it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'and it is said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 30, NULL, 'The question: What do you say, O gate of our sought goal — which none may reach except through it — concerning a man who has died leaving behind books of the dawah and other goods, and who owed a debt to people that the value of those goods is insufficient to discharge? Are the books to be held in the dawah''s treasury, or may they be used to settle his debt?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'the question what do you say o gate of our sought goal which none may reach except through it concerning a man who has died leaving behind books of the dawah and other goods and who owed a debt to people that the value of those goods is insufficient to discharge are the books to be held in the dawahs treasury or may they be used to settle his debt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 31, NULL, 'The answer:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'the answer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 32, NULL, 'Sayingإِنْ كَانَتِ الْكُتُبُ مِنْ كُتُبِ الدَّعْوَةِ فَلَيْسَ لَهُ ذَلِكَ لِأَنَّهَا لِلدَّعْوَةِ لَا تُورَثُ', '', 'إِنْ كَانَتِ الْكُتُبُ مِنْ كُتُبِ الدَّعْوَةِ فَلَيْسَ لَهُ ذَلِكَ لِأَنَّهَا لِلدَّعْوَةِ لَا تُورَثُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingان كانت الكتب من كتب الدعوه فليس له ذلك لانها للدعوه لا تورث', 'ان كانت الكتب من كتب الدعوه فليس له ذلك لانها للدعوه لا تورث');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 33, NULL, 'If the books are among the books of the dawah, that is not permitted to him, because they belong to the dawah and are not inherited.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'if the books are among the books of the dawah that is not permitted to him because they belong to the dawah and are not inherited', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 34, NULL, 'And it is said in the questions that come from certain of the sheikhs of India, with the answers from certain of our masters, the callers of Yemen.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'and it is said in the questions that come from certain of the sheikhs of india with the answers from certain of our masters the callers of yemen', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 35, NULL, 'The question: Is it permitted for those who have been granted license (الْمَفْسُوحِينَ) to read the benefits of the religion to women who are close kin and to others in a single gathering?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'the question is it permitted for those who have been granted license المفسوحين to read the benefits of the religion to women who are close kin and to others in a single gathering', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 36, NULL, 'The answer:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'the answer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 37, NULL, 'Sayingإذا كان بين الرجل والمرأة سترة قراء عليها بحيث تسمع قوله ولا يراها ولا يخلو رجل بامرأة الاّ أن يكون معها غيرها أو معه غيره', '', 'إذا كان بين الرجل والمرأة سترة قراء عليها بحيث تسمع قوله ولا يراها ولا يخلو رجل بامرأة الاّ أن يكون معها غيرها أو معه غيره', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingاذا كان بين الرجل والمراه ستره قراء عليها بحيث تسمع قوله ولا يراها ولا يخلو رجل بامراه الا ان يكون معها غيرها او معه غيره', 'اذا كان بين الرجل والمراه ستره قراء عليها بحيث تسمع قوله ولا يراها ولا يخلو رجل بامراه الا ان يكون معها غيرها او معه غيره');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 38, NULL, 'If a screen stands between the man and the woman, he may read to her so that she can hear his words, even though he cannot see her. No man may be alone with a woman unless another woman is present with her, or another man is present with him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'if a screen stands between the man and the woman he may read to her so that she can hear his words even though he cannot see her no man may be alone with a woman unless another woman is present with her or another man is present with him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 39, NULL, 'Among the questions I have already mentioned, it is said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'among the questions i have already mentioned it is said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 40, NULL, 'Sayingوأمّا ما سألت من العلم الواجب الذي لا يسع جهله فهو ما تعهّد الله عزّ وجل العباد به من معرفته وتوحيده وتنزيهه عن التشبيه والتعطيل والعدم ثم الإقرار برسله أوّلهم وآخرهم والشهادة بالبلاغ لهم والإقرار بمحمد خاتم النبيين وسيد المرسلين والتصديق بما جاء به والإقرار بالأئمة من ذريته الذين أمر الله عزّ وجل بتوليهم وردّ المسألة إليهم ووصل في كتابه طاعته وطاعة رسوله بطاعتهم فقال عزّ وجل أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم ومعرفة إمام الزمان واعتقاد إمامته وولايته والتسليم لأمره والأخذ عنه وأن الله عزّ وجل لم يخل الأرض من حجة له على عباده وإمام يدعوهم إلى طاعته لقوله لا شريك له يوم ندعوا كلّ أناس بإمامهم وقال لمحمد صلى الله عليه وآله إنما أنت منذر ولكل قوم هاد فمن علم هذا وأعتقده وأقرّ به وصدّقه وجب علينا اتباع الدليل واقتفاء اثار الرسول وسؤالهم والأخذ عنهم قال الله أصدق القائلين فاسألوا أهل الذكر إن كنتم لا تعلمون فبقدر ما يعلم المؤمن بعد الإقرار والتصديق ترفع درجّه وتعلو منزلّه قال الله تعالى يرفع الله الذين آمنوا منكم والذين أتوا العلم درجات', '', 'وأمّا ما سألت من العلم الواجب الذي لا يسع جهله فهو ما تعهّد الله عزّ وجل العباد به من معرفته وتوحيده وتنزيهه عن التشبيه والتعطيل والعدم ثم الإقرار برسله أوّلهم وآخرهم والشهادة بالبلاغ لهم والإقرار بمحمد خاتم النبيين وسيد المرسلين والتصديق بما جاء به والإقرار بالأئمة من ذريته الذين أمر الله عزّ وجل بتوليهم وردّ المسألة إليهم ووصل في كتابه طاعته وطاعة رسوله بطاعتهم فقال عزّ وجل أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم ومعرفة إمام الزمان واعتقاد إمامته وولايته والتسليم لأمره والأخذ عنه وأن الله عزّ وجل لم يخل الأرض من حجة له على عباده وإمام يدعوهم إلى طاعته لقوله لا شريك له يوم ندعوا كلّ أناس بإمامهم وقال لمحمد صلى الله عليه وآله إنما أنت منذر ولكل قوم هاد فمن علم هذا وأعتقده وأقرّ به وصدّقه وجب علينا اتباع الدليل واقتفاء اثار الرسول وسؤالهم والأخذ عنهم قال الله أصدق القائلين فاسألوا أهل الذكر إن كنتم لا تعلمون فبقدر ما يعلم المؤمن بعد الإقرار والتصديق ترفع درجّه وتعلو منزلّه قال الله تعالى يرفع الله الذين آمنوا منكم والذين أتوا العلم درجات', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingواما ما سالت من العلم الواجب الذي لا يسع جهله فهو ما تعهد الله عز وجل العباد به من معرفته وتوحيده وتنزيهه عن التشبيه والتعطيل والعدم ثم الاقرار برسله اولهم واخرهم والشهاده بالبلاغ لهم والاقرار بمحمد خاتم النبيين وسيد المرسلين والتصديق بما جاء به والاقرار بالايمه من ذريته الذين امر الله عز وجل بتوليهم ورد المساله اليهم ووصل في كتابه طاعته وطاعه رسوله بطاعتهم فقال عز وجل اطيعوا الله واطيعوا الرسول واولي الامر منكم ومعرفه امام الزمان واعتقاد امامته وولايته والتسليم لامره والاخذ عنه وان الله عز وجل لم يخل الارض من حجه له علي عباده وامام يدعوهم الي طاعته لقوله لا شريك له يوم ندعوا كل اناس بامامهم وقال لمحمد صلي الله عليه واله انما انت منذر ولكل قوم هاد فمن علم هذا واعتقده واقر به وصدقه وجب علينا اتباع الدليل واقتفاء اثار الرسول وسوالهم والاخذ عنهم قال الله اصدق القايلين فاسالوا اهل الذكر ان كنتم لا تعلمون فبقدر ما يعلم المومن بعد الاقرار والتصديق ترفع درجه وتعلو منزله قال الله تعالي يرفع الله الذين امنوا منكم والذين اتوا العلم درجات', 'واما ما سالت من العلم الواجب الذي لا يسع جهله فهو ما تعهد الله عز وجل العباد به من معرفته وتوحيده وتنزيهه عن التشبيه والتعطيل والعدم ثم الاقرار برسله اولهم واخرهم والشهاده بالبلاغ لهم والاقرار بمحمد خاتم النبيين وسيد المرسلين والتصديق بما جاء به والاقرار بالايمه من ذريته الذين امر الله عز وجل بتوليهم ورد المساله اليهم ووصل في كتابه طاعته وطاعه رسوله بطاعتهم فقال عز وجل اطيعوا الله واطيعوا الرسول واولي الامر منكم ومعرفه امام الزمان واعتقاد امامته وولايته والتسليم لامره والاخذ عنه وان الله عز وجل لم يخل الارض من حجه له علي عباده وامام يدعوهم الي طاعته لقوله لا شريك له يوم ندعوا كل اناس بامامهم وقال لمحمد صلي الله عليه واله انما انت منذر ولكل قوم هاد فمن علم هذا واعتقده واقر به وصدقه وجب علينا اتباع الدليل واقتفاء اثار الرسول وسوالهم والاخذ عنهم قال الله اصدق القايلين فاسالوا اهل الذكر ان كنتم لا تعلمون فبقدر ما يعلم المومن بعد الاقرار والتصديق ترفع درجه وتعلو منزله قال الله تعالي يرفع الله الذين امنوا منكم والذين اتوا العلم درجات');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 41, NULL, 'You asked about the knowledge that is obligatory — the knowledge no believer may leave unlearned. It is what God, mighty and exalted, has charged His servants to know:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'you asked about the knowledge that is obligatory the knowledge no believer may leave unlearned it is what god mighty and exalted has charged his servants to know', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 42, NULL, 'Knowledge of Him: declaring His oneness, holding Him far above all likeness, far above the stripping away of His attributes, and far above nonexistence. Acknowledgment of His messengers — the first and the last of them — and testimony that they conveyed their message. Acknowledgment of Muhammad, the Seal of the Prophets and the Master of the Messengers, and affirmation of everything he brought. Acknowledgment of the Imams from his progeny — those whom God, mighty and exalted, commanded us to take as our guardians and to whom He commanded that every question be referred. In His Book He joined obedience to Himself and obedience to His Messenger with obedience to them, for He said, mighty and exalted: Obey God, and obey the Messenger, and those vested with authority among you. Recognition of the Imam of the age: belief in his Imamate and his guardianship, submission to his command, and the taking of knowledge from him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'knowledge of him declaring his oneness holding him far above all likeness far above the stripping away of his attributes and far above nonexistence acknowledgment of his messengers the first and the last of them and testimony that they conveyed their message acknowledgment of muhammad the seal of the prophets and the master of the messengers and affirmation of everything he brought acknowledgment of the imams from his progeny those whom god mighty and exalted commanded us to take as our guardians and to whom he commanded that every question be referred in his book he joined obedience to himself and obedience to his messenger with obedience to them for he said mighty and exalted obey god and obey the messenger and those vested with authority among you recognition of the imam of the age belief in his imamate and his guardianship submission to his command and the taking of knowledge from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 43, NULL, 'All of this rests on the reality that God, mighty and exalted, has never left the earth without a proof against His servants and without an Imam calling them to His obedience. He who has no partner said: On the day We shall call every people by their Imam. And He said to Muhammad: You are only a warner, and for every people there is a guide.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'all of this rests on the reality that god mighty and exalted has never left the earth without a proof against his servants and without an imam calling them to his obedience he who has no partner said on the day we shall call every people by their imam and he said to muhammad you are only a warner and for every people there is a guide', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 44, NULL, 'Whoever knows this, believes it, acknowledges it, and affirms it as true — we are bound to follow the guide, trace the footsteps of the Messenger, ask them, and take from them. God, most truthful of all who speak, said: Ask the people of remembrance, if you do not know. In proportion to what a believer knows, after acknowledgment and affirmation, his degree is raised and his station elevated. God, exalted, said: God raises those of you who believe, and those who have been given knowledge, by degrees.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'whoever knows this believes it acknowledges it and affirms it as true we are bound to follow the guide trace the footsteps of the messenger ask them and take from them god most truthful of all who speak said ask the people of remembrance if you do not know in proportion to what a believer knows after acknowledgment and affirmation his degree is raised and his station elevated god exalted said god raises those of you who believe and those who have been given knowledge by degrees', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 45, NULL, 'And Ali, Amir al-Muminin (ع), said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'and ali amir al muminin ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 46, NULL, 'Sayingقِيمَةُ كُلِّ امْرِئٍ مَا كَانَ يُحْسِنُ مِنَ الْعِلْمِ', '', 'قِيمَةُ كُلِّ امْرِئٍ مَا كَانَ يُحْسِنُ مِنَ الْعِلْمِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingقيمه كل امري ما كان يحسن من العلم', 'قيمه كل امري ما كان يحسن من العلم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 47, NULL, 'The worth of every man is what he has mastered of knowledge.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'the worth of every man is what he has mastered of knowledge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 48, NULL, 'And the Messenger of God said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'and the messenger of god said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 49, NULL, 'Sayingطَلَبُ الْعِلْمِ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ وَمُسْلِمَةٍ', '', 'طَلَبُ الْعِلْمِ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ وَمُسْلِمَةٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingطلب العلم فريضه علي كل مسلم ومسلمه', 'طلب العلم فريضه علي كل مسلم ومسلمه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 50, NULL, 'The seeking of knowledge is an obligation upon every Muslim man and every Muslim woman.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'the seeking of knowledge is an obligation upon every muslim man and every muslim woman', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 51, NULL, 'I now address the prohibition of analogy in religion.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'i now address the prohibition of analogy in religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 52, NULL, 'Mawlana Amir al-Muminin Ali ibn Abi Talib (ع) said in his four hundred maxims of conduct:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'mawlana amir al muminin ali ibn abi talib ع said in his four hundred maxims of conduct', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 53, NULL, 'Sayingلا تقيسوا الدين فأنه لا يقاس وسيأتي قوم يقيسون الدين وهم أعداءه وأول من قاس إبليس', '', 'لا تقيسوا الدين فأنه لا يقاس وسيأتي قوم يقيسون الدين وهم أعداءه وأول من قاس إبليس', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingلا تقيسوا الدين فانه لا يقاس وسياتي قوم يقيسون الدين وهم اعداءه واول من قاس ابليس', 'لا تقيسوا الدين فانه لا يقاس وسياتي قوم يقيسون الدين وهم اعداءه واول من قاس ابليس');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 54, NULL, 'Do not measure the religion by analogy, for it cannot be measured. A people will come who measure the religion by analogy — and they are its enemies. The first to reason by analogy was Iblis.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'do not measure the religion by analogy for it cannot be measured a people will come who measure the religion by analogy and they are its enemies the first to reason by analogy was iblis', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 55, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 56, NULL, 'Sayingإِذَا سَمِعْتُمْ مِنْ حَدِيثِنَا مَا لَا تَعْرِفُونَهُ فَرُدُّوهُ إِلَيْنَا وَقِفُوا عِنْدَهُ تَسْلَمُوا', '', 'إِذَا سَمِعْتُمْ مِنْ حَدِيثِنَا مَا لَا تَعْرِفُونَهُ فَرُدُّوهُ إِلَيْنَا وَقِفُوا عِنْدَهُ تَسْلَمُوا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingاذا سمعتم من حديثنا ما لا تعرفونه فردوه الينا وقفوا عنده تسلموا', 'اذا سمعتم من حديثنا ما لا تعرفونه فردوه الينا وقفوا عنده تسلموا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 57, NULL, 'When you hear something in our discourse that you do not recognize, refer it back to us — stop there — and you will be safe.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'when you hear something in our discourse that you do not recognize refer it back to us stop there and you will be safe', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 58, NULL, 'I now take up the principle of referring back, in every obscure matter, to God, to His Messenger, to his legatee, to the Imams of his progeny, and to their callers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'i now take up the principle of referring back in every obscure matter to god to his messenger to his legatee to the imams of his progeny and to their callers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 59, NULL, 'Our master al-Qadi al-Numan ibn Muhammad said in his book Mafatih al-Nimah, and al-Sadiq (ع) has said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'our master al qadi al numan ibn muhammad said in his book mafatih al nimah and al sadiq ع has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 60, NULL, 'Sayingمَا أَشْتَكَلَ عَلَيْكُمْ شَيْءٌ مِنْ عُلُومِنَا فَرُدُّوهُ إِلَيْنَا وَلَا تَرُدُّوهُ عَلَيْنَا يَعْنِي رُدُّوا إِلَيْنَا لِنُبَرْهِنَ لَكُمْ بُرْهَانَهُ وَنُعَرِّفَكُمْ تَأْوِيلَهُ وَلَا تَرُدُّوهُ عَلَيْنَا بِأَنَّ تُكَذِّبُوا بِهِ وَتَرْجِعُوا عَنْهُ', '', 'مَا أَشْتَكَلَ عَلَيْكُمْ شَيْءٌ مِنْ عُلُومِنَا فَرُدُّوهُ إِلَيْنَا وَلَا تَرُدُّوهُ عَلَيْنَا يَعْنِي رُدُّوا إِلَيْنَا لِنُبَرْهِنَ لَكُمْ بُرْهَانَهُ وَنُعَرِّفَكُمْ تَأْوِيلَهُ وَلَا تَرُدُّوهُ عَلَيْنَا بِأَنَّ تُكَذِّبُوا بِهِ وَتَرْجِعُوا عَنْهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingما اشتكل عليكم شيء من علومنا فردوه الينا ولا تردوه علينا يعني ردوا الينا لنبرهن لكم برهانه ونعرفكم تاويله ولا تردوه علينا بان تكذبوا به وترجعوا عنه', 'ما اشتكل عليكم شيء من علومنا فردوه الينا ولا تردوه علينا يعني ردوا الينا لنبرهن لكم برهانه ونعرفكم تاويله ولا تردوه علينا بان تكذبوا به وترجعوا عنه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 61, NULL, 'Whenever anything of our sciences is obscure to you, refer it back to us — do not throw it back at us. That is: bring it to us, so that we may establish its proof for you and make its interpretation known to you; do not throw it back at us by calling it false and turning away from it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'whenever anything of our sciences is obscure to you refer it back to us do not throw it back at us that is bring it to us so that we may establish its proof for you and make its interpretation known to you do not throw it back at us by calling it false and turning away from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 62, NULL, 'I turn now to the command to conceal knowledge, the secrets, the religion, and the practice of precaution.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'i turn now to the command to conceal knowledge the secrets the religion and the practice of precaution', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 63, NULL, 'Amir al-Muminin Ali ibn Abi Talib (ع) said in his four hundred maxims of conduct:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'amir al muminin ali ibn abi talib ع said in his four hundred maxims of conduct', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 64, NULL, 'Sayingمَنْ أَذَاعَ سِرَّنَا أَذَاقَهُ اللَّهُ بَرْدَ الْحَدِيدِ', '', 'مَنْ أَذَاعَ سِرَّنَا أَذَاقَهُ اللَّهُ بَرْدَ الْحَدِيدِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'sayingمن اذاع سرنا اذاقه الله برد الحديد', 'من اذاع سرنا اذاقه الله برد الحديد');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what must be learned, what must be concealed', '6. What Must Be Learned, What Must Be Concealed', 65, NULL, 'Whoever divulges our secret, God will give him the cold of iron to taste.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 6 what must be learned what must be concealed', 'whoever divulges our secret god will give him the cold of iron to taste', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 0, NULL, 'I mention now the circumstances that make ablution (اَلْوُضُوء) necessary.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'i mention now the circumstances that make ablution الوضوء necessary', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 1, NULL, 'It is said in the book known as the Book of Question and Answer, arranged according to the order of the doors of Daaim al-Islam, the questions being those of certain teachers of the Indian lands and the answers those of the summoners of the Yemeni lands:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'it is said in the book known as the book of question and answer arranged according to the order of the doors of daaim al islam the questions being those of certain teachers of the indian lands and the answers those of the summoners of the yemeni lands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 2, NULL, 'Question: What do you say, O best of those who have cast upon us the lights of his knowledge, regarding a matter over which our minds have labored? It has come in the Book of Purity that a man is forbidden to urinate beneath fruit-bearing trees. O our master, what is intended by these trees — those upon which fruit is actually present, or those whose property it is to bear fruit? Answer: The trees in which fruit is present, or those whose property it is to bear it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'question what do you say o best of those who have cast upon us the lights of his knowledge regarding a matter over which our minds have labored it has come in the book of purity that a man is forbidden to urinate beneath fruit bearing trees o our master what is intended by these trees those upon which fruit is actually present or those whose property it is to bear fruit answer the trees in which fruit is present or those whose property it is to bear it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 3, NULL, 'Question: What do you say regarding what has come in the books of the dawah forbidding the greeting of one who is in a state of hadath, and forbidding speech in that state? O our master, if the one in that state rises from that place, having cleansed himself with a stone or with something else, is it permitted for him to speak, and is it permitted to greet him? Answer: Once he has risen, he may be greeted, and he must return the greeting and may speak.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'question what do you say regarding what has come in the books of the dawah forbidding the greeting of one who is in a state of hadath and forbidding speech in that state o our master if the one in that state rises from that place having cleansed himself with a stone or with something else is it permitted for him to speak and is it permitted to greet him answer once he has risen he may be greeted and he must return the greeting and may speak', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 4, NULL, 'Question: What does our master say regarding a stone or a clod of earth with which a man cleanses himself after urinating, which afterward dries, and which he then uses a second time — is that permitted? Answer: There is no harm in it, provided that no impurity and no moisture are evident upon it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'question what does our master say regarding a stone or a clod of earth with which a man cleanses himself after urinating which afterward dries and which he then uses a second time is that permitted answer there is no harm in it provided that no impurity and no moisture are evident upon it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 5, NULL, 'It is said in the book Mukhtasar al-Musannaf that what nullifies ablution is:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'it is said in the book mukhtasar al musannaf that what nullifies ablution is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 6, NULL, 'Sleep Whatever issues from the front or rear passage, whether a stone or wind An enema Fainting Insanity The disappearance of the glans into the front passage of a living person or a dead one', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'sleep whatever issues from the front or rear passage whether a stone or wind an enema fainting insanity the disappearance of the glans into the front passage of a living person or a dead one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 7, NULL, 'It is said in the book Tawil al-Daaim that it has likewise come down that if one performing ablution interrupts it, he may build upon what he has already done, so long as the water has not dried upon the limbs already washed.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'it is said in the book tawil al daaim that it has likewise come down that if one performing ablution interrupts it he may build upon what he has already done so long as the water has not dried upon the limbs already washed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 8, NULL, 'It is also said in Mukhtasar al-Musannaf that whoever has had both hands amputated above the elbows, so that nothing remains of them, the obligation of washing the hands has fallen away from him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'it is also said in mukhtasar al musannaf that whoever has had both hands amputated above the elbows so that nothing remains of them the obligation of washing the hands has fallen away from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 9, NULL, 'Our master and lord, the Trusted of the Imam, the Banner of Islam (رض), said in his gatherings entitled Majalis al-Bayan and Majalis al-Hikma, known as the Councils of al-Mustansiriyya, in the fifth council:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'our master and lord the trusted of the imam the banner of islam رض said in his gatherings entitled majalis al bayan and majalis al hikma known as the councils of al mustansiriyya in the fifth council', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 10, NULL, 'You have heard what was recited to you, wherein we singled you out with the splendid glad tidings and joined you to the company of those of whom God Almighty said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'you have heard what was recited to you wherein we singled you out with the splendid glad tidings and joined you to the company of those of whom god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 11, NULL, 'Yunus: 64لَهُمُ ٱلْبُشْرَىٰ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْآخِرَةِ', '', 'لَهُمُ ٱلْبُشْرَىٰ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْآخِرَةِ', 'Yunus: 64', 10, 64, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'yunus 64لهم البشري في الحيوه الدنيا وفي الاخره', 'لهم البشري في الحيوه الدنيا وفي الاخره');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 12, NULL, 'Theirs are the glad tidings in the life of this world and in the hereafter.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'theirs are the glad tidings in the life of this world and in the hereafter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 13, NULL, 'We set forth the honoring of the number nineteen by its conjunction with the clauses of the testimony and its seven letters and its twelve, and that Islam is built upon the seven obligations, to which twelve practices are attached — in a manner not hidden from one who possesses knowledge and discernment. Listen now, then, to what is recited to you: that to every obligation among the obligations already mentioned there belong seven obligations and twelve practices. Among them is the walaya (الْوِلَايَة), which is the first and most excellent of them. It has been said before that in every allusion made by these numbers, the ranking of the friends of God is the utmost aim and intention.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'we set forth the honoring of the number nineteen by its conjunction with the clauses of the testimony and its seven letters and its twelve and that islam is built upon the seven obligations to which twelve practices are attached in a manner not hidden from one who possesses knowledge and discernment listen now then to what is recited to you that to every obligation among the obligations already mentioned there belong seven obligations and twelve practices among them is the walaya الولايه which is the first and most excellent of them it has been said before that in every allusion made by these numbers the ranking of the friends of god is the utmost aim and intention', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 14, NULL, 'After the walaya comes purity, and in it are seven obligations and twelve practices. The seven obligations are those of ablution, which is the lesser purity (الطَّهَارَةُ الصُّغْرَى):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'after the walaya comes purity and in it are seven obligations and twelve practices the seven obligations are those of ablution which is the lesser purity الطهاره الصغري', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 15, NULL, 'Pure water Intention Washing the face Washing the hands Wiping the head Wiping the feet Order, which is that one begins with what God Almighty has begun by mentioning', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'pure water intention washing the face washing the hands wiping the head wiping the feet order which is that one begins with what god almighty has begun by mentioning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 16, NULL, 'The twelve practices are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'the twelve practices are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 17, NULL, 'Cleansing oneself after relieving oneself (اَلِاسْتِنْجَاءُ) Washing the hands before entering them into the vessel Pronouncing the name of God when sitting down for ablution Rinsing the mouth Drawing water into the nose Moving the ring so that the water reaches what is beneath it Combing the water through the beard Wetting the eyes with water Giving the right limbs precedence over the left Wiping the ears — their inner and outer parts — with water The second and third washings of the face, each a practice, while the first is the obligation The siwak (السِّوَاك)', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'cleansing oneself after relieving oneself الاستنجاء washing the hands before entering them into the vessel pronouncing the name of god when sitting down for ablution rinsing the mouth drawing water into the nose moving the ring so that the water reaches what is beneath it combing the water through the beard wetting the eyes with water giving the right limbs precedence over the left wiping the ears their inner and outer parts with water the second and third washings of the face each a practice while the first is the obligation the siwak السواك', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 18, NULL, 'We say that the greater purity (اَلطَّهَارَةُ الْكُبْرَى), which is the washing of the whole body, is likewise divided into seven obligations and twelve practices. The obligations are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'we say that the greater purity الطهاره الكبري which is the washing of the whole body is likewise divided into seven obligations and twelve practices the obligations are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 19, NULL, 'The washing from janabah (الْجَنَابَة) The washing from menstruation The washing of the unbeliever when he enters Islam The washing of one who has fallen unconscious when he recovers The washing from the blood of nifas (النِّفَاس) The washing after immersion in impurity The washing of the dead, which is an obligation upon the living until one of them performs it', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'the washing from janabah الجنابه the washing from menstruation the washing of the unbeliever when he enters islam the washing of one who has fallen unconscious when he recovers the washing from the blood of nifas النفاس the washing after immersion in impurity the washing of the dead which is an obligation upon the living until one of them performs it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 20, NULL, 'The practices are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'the practices are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 21, NULL, 'The washing of Friday The washing for the festival of الْفِطْر The washing for the festival of al-Adha The washing for ihram The washing for entering the Haram The washing for entering the Kabah The washing for entering Madinah The washing on the day of Arafah The washing on three nights of the month of Ramadan, the night of the nineteenth The night of the twenty-first The night of the twenty-third The washing after washing the dead', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'the washing of friday the washing for the festival of الفطر the washing for the festival of al adha the washing for ihram the washing for entering the haram the washing for entering the kabah the washing for entering madinah the washing on the day of arafah the washing on three nights of the month of ramadan the night of the nineteenth the night of the twenty first the night of the twenty third the washing after washing the dead', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 22, NULL, 'Our lord Amir al-Muminin Ali ibn Abi Talib (ع) said in his four hundred maxims of conduct:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'our lord amir al muminin ali ibn abi talib ع said in his four hundred maxims of conduct', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 23, NULL, 'Sayingتَنَظَّفُوا بِالْمَاءِ مِنَ الرِّيحِ الْمُنْتِنَةِ', '', 'تَنَظَّفُوا بِالْمَاءِ مِنَ الرِّيحِ الْمُنْتِنَةِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'sayingتنظفوا بالماء من الريح المنتنه', 'تنظفوا بالماء من الريح المنتنه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 24, NULL, 'Cleanse yourselves with water from the foul odor.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'cleanse yourselves with water from the foul odor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 25, NULL, 'And he said therein:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'and he said therein', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 26, NULL, 'Sayingإِذَا أَرَادَ أَحَدُكُمُ الْخَلَاءَ فَلْيَقُلْ بِسْمِ اللَّهِ اللَّهُمَّ أَمِطْ عَنِّي الْأَذَى وَأَعِذْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِيهِ فِي عَافِيَةٍ وَأَخْرَجَ مِنِّي أَذَاهُ فِي عَافِيَةٍ', '', 'إِذَا أَرَادَ أَحَدُكُمُ الْخَلَاءَ فَلْيَقُلْ بِسْمِ اللَّهِ اللَّهُمَّ أَمِطْ عَنِّي الْأَذَى وَأَعِذْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِيهِ فِي عَافِيَةٍ وَأَخْرَجَ مِنِّي أَذَاهُ فِي عَافِيَةٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'sayingاذا اراد احدكم الخلاء فليقل بسم الله اللهم امط عني الاذي واعذني من الشيطان الرجيم الحمد لله الذي اطعمنيه في عافيه واخرج مني اذاه في عافيه', 'اذا اراد احدكم الخلاء فليقل بسم الله اللهم امط عني الاذي واعذني من الشيطان الرجيم الحمد لله الذي اطعمنيه في عافيه واخرج مني اذاه في عافيه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 27, NULL, 'When any of you intends to go to the privy, let him say: "In the name of God. O God, remove the filth from me and protect me from the accursed devil. Praise be to God, who fed me in good health and expelled its harm from me in good health."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'when any of you intends to go to the privy let him say in the name of god o god remove the filth from me and protect me from the accursed devil praise be to god who fed me in good health and expelled its harm from me in good health', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 28, NULL, 'Sayingإِذَا نَظَرَ أَحَدُكُمْ إِلَىٰ حَدَثِهِ بَعْدَ فَرَاغِهِ فَلْيَقُلِ اللَّهُمَّ ارْزُقْنِي الْحَلَالَ وَجَنِّبْنِي الْحَرَامَ فَاِنَّ رَسُولَ اللَّهِ صَلَّىٰ اللَّهُ عَلَيْهِ وَآلِهِ قَالَ مَا مِنْ عَبْدٍ إِلَّا وَقَدْ وَكَّلَ اللَّهُ بِهِ مَلَكًا يَلْوِي عُنُقَهُ إِذَا أَحْدَثَ حَتَّىٰ يَنْظُرَ إِلَيْهِ وَيَنْبَغِي لَهُ أَنْ يَسْأَلَ اللَّهَ الْحَلَالَ فَاِنَّ الْمَلَكَ يَقُولُ يَا ابْنَ آدَمَ هَٰذَا مَا حَرَصْتَ عَلَيْهِ فَانْظُرْ مِنْ أَيْنَ أَخَذْتَهُ وَإِلَىٰ مَا صَارَ', '', 'إِذَا نَظَرَ أَحَدُكُمْ إِلَىٰ حَدَثِهِ بَعْدَ فَرَاغِهِ فَلْيَقُلِ اللَّهُمَّ ارْزُقْنِي الْحَلَالَ وَجَنِّبْنِي الْحَرَامَ فَاِنَّ رَسُولَ اللَّهِ صَلَّىٰ اللَّهُ عَلَيْهِ وَآلِهِ قَالَ مَا مِنْ عَبْدٍ إِلَّا وَقَدْ وَكَّلَ اللَّهُ بِهِ مَلَكًا يَلْوِي عُنُقَهُ إِذَا أَحْدَثَ حَتَّىٰ يَنْظُرَ إِلَيْهِ وَيَنْبَغِي لَهُ أَنْ يَسْأَلَ اللَّهَ الْحَلَالَ فَاِنَّ الْمَلَكَ يَقُولُ يَا ابْنَ آدَمَ هَٰذَا مَا حَرَصْتَ عَلَيْهِ فَانْظُرْ مِنْ أَيْنَ أَخَذْتَهُ وَإِلَىٰ مَا صَارَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'sayingاذا نظر احدكم الي حدثه بعد فراغه فليقل اللهم ارزقني الحلال وجنبني الحرام فان رسول الله صلي الله عليه واله قال ما من عبد الا وقد وكل الله به ملكا يلوي عنقه اذا احدث حتي ينظر اليه وينبغي له ان يسال الله الحلال فان الملك يقول يا ابن ادم هذا ما حرصت عليه فانظر من اين اخذته والي ما صار', 'اذا نظر احدكم الي حدثه بعد فراغه فليقل اللهم ارزقني الحلال وجنبني الحرام فان رسول الله صلي الله عليه واله قال ما من عبد الا وقد وكل الله به ملكا يلوي عنقه اذا احدث حتي ينظر اليه وينبغي له ان يسال الله الحلال فان الملك يقول يا ابن ادم هذا ما حرصت عليه فانظر من اين اخذته والي ما صار');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 29, NULL, 'When one of you looks at what has passed from him after he finishes, let him say: O God, grant me the lawful and keep me from the unlawful. For the Messenger of God said: There is no servant but that God has appointed over him an angel who turns his neck when he relieves himself, so that he looks at it. It is fitting for him to ask God for the lawful, for the angel says: O son of Adam, this is the thing you were so eager for — consider where you took it from and what it has come to.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'when one of you looks at what has passed from him after he finishes let him say o god grant me the lawful and keep me from the unlawful for the messenger of god said there is no servant but that god has appointed over him an angel who turns his neck when he relieves himself so that he looks at it it is fitting for him to ask god for the lawful for the angel says o son of adam this is the thing you were so eager for consider where you took it from and what it has come to', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 30, NULL, 'He also said in that same context:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'he also said in that same context', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 31, NULL, 'Sayingإِذَا خَالَطَ النَّوْمُ الْقَلْبَ وَجَبَ الْوُضُوءُ', '', 'إِذَا خَالَطَ النَّوْمُ الْقَلْبَ وَجَبَ الْوُضُوءُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'sayingاذا خالط النوم القلب وجب الوضوء', 'اذا خالط النوم القلب وجب الوضوء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'water and intention: the anatomy of ablution', '7. Water and Intention: The Anatomy of Ablution', 32, NULL, 'When sleep mingles with the heart, ablution becomes obligatory.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 7 water and intention the anatomy of ablution', 'when sleep mingles with the heart ablution becomes obligatory', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 0, NULL, 'I turn now to the manners that belong to the washing place and to the ablution itself.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'i turn now to the manners that belong to the washing place and to the ablution itself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 1, NULL, 'The book of questions and answers — arranged according to the chapters of Daaim al-Islam — records the following.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'the book of questions and answers arranged according to the chapters of daaim al islam records the following', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 2, NULL, 'Question: What does our master, may God illumine his inner being, say concerning one who forgot the istinja from a major impurity, then prayed and let the prayer time pass before he remembered? May he perform istinja and wudhu and repeat the prayer, or not? Answer: He repeats the prayer, for one does not pray while impurity is upon him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'question what does our master may god illumine his inner being say concerning one who forgot the istinja from a major impurity then prayed and let the prayer time pass before he remembered may he perform istinja and wudhu and repeat the prayer or not answer he repeats the prayer for one does not pray while impurity is upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 3, NULL, 'Question: What does our master, may God perpetuate his support, say concerning a man who performs wudhu and washes himself in the washing place while uncovered, the place being screened so that none of the people sees him? Does he pray with that wudhu or not? Answer: What was mentioned of the concealment of some of the Imams (عَلَيْهِمُ السَّلَامُ) in the water was mentioned for the excellence of good manners. If a man is in a place where none of the people sees him and he uncovers himself, there is no harm in that — though concealment is better — and he prays with the purity he performed while uncovered.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'question what does our master may god perpetuate his support say concerning a man who performs wudhu and washes himself in the washing place while uncovered the place being screened so that none of the people sees him does he pray with that wudhu or not answer what was mentioned of the concealment of some of the imams عليهم السلام in the water was mentioned for the excellence of good manners if a man is in a place where none of the people sees him and he uncovers himself there is no harm in that though concealment is better and he prays with the purity he performed while uncovered', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 4, NULL, 'From another source: whoever urinates in a place should not perform the istinja in that same place, but in a second place; and whoever has cleansed himself with a stone after relieving himself should not return to that stone.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'from another source whoever urinates in a place should not perform the istinja in that same place but in a second place and whoever has cleansed himself with a stone after relieving himself should not return to that stone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 5, NULL, 'From Kitab al-Idah, the Messenger of God said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'from kitab al idah the messenger of god said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 6, NULL, 'Sayingأمرني جبرئيل عَلَيْهِ السَّلَامُ عن ربي أن اغسل فنكي عند الوضوء', '', 'أمرني جبرئيل عَلَيْهِ السَّلَامُ عن ربي أن اغسل فنكي عند الوضوء', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingامرني جبرييل عليه السلام عن ربي ان اغسل فنكي عند الوضوء', 'امرني جبرييل عليه السلام عن ربي ان اغسل فنكي عند الوضوء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 7, NULL, 'Gabriel (ع) commanded me on behalf of my Lord to wash the two hollows beside my chin when I perform the ablution.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'gabriel ع commanded me on behalf of my lord to wash the two hollows beside my chin when i perform the ablution', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 8, NULL, 'And in the sound narration:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'and in the sound narration', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 9, NULL, 'Sayingإِذَا تَوَضَّأْتَ فَلَا تَنْسَيَنَّ الْفَنْكَيْنِ', '', 'إِذَا تَوَضَّأْتَ فَلَا تَنْسَيَنَّ الْفَنْكَيْنِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingاذا توضات فلا تنسين الفنكين', 'اذا توضات فلا تنسين الفنكين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 10, NULL, 'When you perform the ablution, do not forget the two hollows beside the chin.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'when you perform the ablution do not forget the two hollows beside the chin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 11, NULL, 'That is, the sides of the tuft below the lower lip, on the right and on the left — and these two are the neglected place.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'that is the sides of the tuft below the lower lip on the right and on the left and these two are the neglected place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 12, NULL, 'He said in Mukhtasar al-Musannaf: whoever forgets the wudhu until he has performed the ghusl, let him perform wudhu afterward, and nothing is upon him. And if a man performs wudhu and then begins his ghusl, but before completing the ghusl a state of impurity befalls him, he carries on with the ghusl and performs wudhu after it for the prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'he said in mukhtasar al musannaf whoever forgets the wudhu until he has performed the ghusl let him perform wudhu afterward and nothing is upon him and if a man performs wudhu and then begins his ghusl but before completing the ghusl a state of impurity befalls him he carries on with the ghusl and performs wudhu after it for the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 13, NULL, 'He said in Tawil al-Daaim: whoever intends the wudhu in its outward sense goes to the vessel in which is the water with which he performs wudhu, purifies himself, and places it on his right.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'he said in tawil al daaim whoever intends the wudhu in its outward sense goes to the vessel in which is the water with which he performs wudhu purifies himself and places it on his right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 14, NULL, 'In the book of questions and answers already mentioned — arranged according to the chapters of Daaim al-Islam — it is asked: What does our master, may God perpetuate his support, say concerning one who entered the prayer after performing wudhu and then recalled that he had forgotten the istinja? Does he complete his prayer or repeat it? Answer: Prayer is not permitted while a man carries an impurity of which he knows, until he washes it away.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'in the book of questions and answers already mentioned arranged according to the chapters of daaim al islam it is asked what does our master may god perpetuate his support say concerning one who entered the prayer after performing wudhu and then recalled that he had forgotten the istinja does he complete his prayer or repeat it answer prayer is not permitted while a man carries an impurity of which he knows until he washes it away', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 15, NULL, 'He said in Tawil al-Shariah, in the section on the manners of the wudhu: the manners of the wudhu are twelve.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'he said in tawil al shariah in the section on the manners of the wudhu the manners of the wudhu are twelve', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 16, NULL, 'Do not enter the privy except with sandals. Advance the left foot. Cover your head until you come out. Do not face the qiblah, nor turn your back to it. Conceal yourself. Lean upon your left leg. Do not sit long in the privy. Do not cleanse yourself with dung, nor with a decayed bone, nor with animal droppings, nor with a crumbling bone, but let it be three fresh stones. Cleanse yourself with your left hand. Do not pour water upon the excrement. Do not speak until you come out. Then advance your right foot when you leave.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'do not enter the privy except with sandals advance the left foot cover your head until you come out do not face the qiblah nor turn your back to it conceal yourself lean upon your left leg do not sit long in the privy do not cleanse yourself with dung nor with a decayed bone nor with animal droppings nor with a crumbling bone but let it be three fresh stones cleanse yourself with your left hand do not pour water upon the excrement do not speak until you come out then advance your right foot when you leave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 17, NULL, 'The dung mentioned here is human excrement, and the two terms rendered as decayed and crumbling bone both mean a worn bone.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'the dung mentioned here is human excrement and the two terms rendered as decayed and crumbling bone both mean a worn bone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 18, NULL, 'He said therein:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'he said therein', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 19, NULL, 'Sayingوَلَا تَجُوزُ الصَّلَاةُ بِغَيْرِ وُضُوءٍ', '', 'وَلَا تَجُوزُ الصَّلَاةُ بِغَيْرِ وُضُوءٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingولا تجوز الصلاه بغير وضوء', 'ولا تجوز الصلاه بغير وضوء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 20, NULL, 'Prayer is not valid without ablution.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'prayer is not valid without ablution', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 21, NULL, 'And he said that the Prophet forbade urinating in burrows, saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'and he said that the prophet forbade urinating in burrows saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 22, NULL, 'Sayingإِنَّهَا مَأْوَى الثَّعَابِينِ وَالْحَيَّاتِ', '', 'إِنَّهَا مَأْوَى الثَّعَابِينِ وَالْحَيَّاتِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingانها ماوي الثعابين والحيات', 'انها ماوي الثعابين والحيات');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 23, NULL, 'They are the lairs of serpents and snakes.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'they are the lairs of serpents and snakes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 24, NULL, 'The Prophet said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 25, NULL, 'Sayingلَا تُقْبَلُ الصَّلَاةُ اِلَّا بِطُهُورٍ', '', 'لَا تُقْبَلُ الصَّلَاةُ اِلَّا بِطُهُورٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingلا تقبل الصلاه الا بطهور', 'لا تقبل الصلاه الا بطهور');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 26, NULL, 'Prayer is not accepted except with purification.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'prayer is not accepted except with purification', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 27, NULL, 'Our master the Commander of the Faithful, Ali ibn Abi Talib (ع), said in his Four Hundred Manners:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'our master the commander of the faithful ali ibn abi talib ع said in his four hundred manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 28, NULL, 'Sayingاَلْمَضْمَضَةُ وَالِاسْتِنْشَاقُ بِالْمَاءِ عِنْدَ الطُّهُورِ طَهُورٌ لِلْفَمِ وَالْأَنْفِ وَهُوَ مِنَ السُّنَّةِ', '', 'اَلْمَضْمَضَةُ وَالِاسْتِنْشَاقُ بِالْمَاءِ عِنْدَ الطُّهُورِ طَهُورٌ لِلْفَمِ وَالْأَنْفِ وَهُوَ مِنَ السُّنَّةِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingالمضمضه والاستنشاق بالماء عند الطهور طهور للفم والانف وهو من السنه', 'المضمضه والاستنشاق بالماء عند الطهور طهور للفم والانف وهو من السنه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 29, NULL, 'Rinsing the mouth and drawing water into the nose at the time of purification purifies the mouth and the nose, and it is part of the practice of the Prophet.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'rinsing the mouth and drawing water into the nose at the time of purification purifies the mouth and the nose and it is part of the practice of the prophet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 30, NULL, 'He said therein:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'he said therein', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 31, NULL, 'Sayingاَلْاِسْتِنْجَاءُ بِالْمَاءِ الْبَارِدِ يَقْطَعُ الْبَوَاسِيرَ', '', 'اَلْاِسْتِنْجَاءُ بِالْمَاءِ الْبَارِدِ يَقْطَعُ الْبَوَاسِيرَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingالاستنجاء بالماء البارد يقطع البواسير', 'الاستنجاء بالماء البارد يقطع البواسير');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 32, NULL, 'Cleansing with cold water cuts off piles.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'cleansing with cold water cuts off piles', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 33, NULL, 'He said therein:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'he said therein', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 34, NULL, 'Sayingالْوُضُوءُ بَعْدَ الطُّهْرِ عَشْرُ حَسَنَاتٍ فَتَطَهَّرُوا', '', 'الْوُضُوءُ بَعْدَ الطُّهْرِ عَشْرُ حَسَنَاتٍ فَتَطَهَّرُوا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingالوضوء بعد الطهر عشر حسنات فتطهروا', 'الوضوء بعد الطهر عشر حسنات فتطهروا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 35, NULL, 'Ablution after purification is ten good deeds, so purify yourselves.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'ablution after purification is ten good deeds so purify yourselves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 36, NULL, 'He said therein:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'he said therein', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 37, NULL, 'Sayingلَا يَتَوَضَّأُ الرَّجُلُ حَتَّىٰ يَقُولَ قَبْلَ أَنْ يَمَسَّ الْمَاءَ بِسْمِ اللَّهِ اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ', '', 'لَا يَتَوَضَّأُ الرَّجُلُ حَتَّىٰ يَقُولَ قَبْلَ أَنْ يَمَسَّ الْمَاءَ بِسْمِ اللَّهِ اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingلا يتوضا الرجل حتي يقول قبل ان يمس الماء بسم الله اللهم اجعلني من التوابين واجعلني من المتطهرين', 'لا يتوضا الرجل حتي يقول قبل ان يمس الماء بسم الله اللهم اجعلني من التوابين واجعلني من المتطهرين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 38, NULL, 'No man should perform ablution until, before water touches him, he says: "In the name of God. O God, اجْعَلْنِي مِنَ التَّوَّابِينَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ — make me among those who turn to You in repentance, and make me among those who purify themselves."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'no man should perform ablution until before water touches him he says in the name of god o god اجعلني من التوابين واجعلني من المتطهرين make me among those who turn to you in repentance and make me among those who purify themselves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 39, NULL, 'He said therein:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'he said therein', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 40, NULL, 'Sayingإِذَا تَعَرَّى الرَّجُلُ نَظَرَ إِلَيْهِ الشَّيْطَانُ فَطَمِعَ فِيهِ فَاسْتَتِرُوا', '', 'إِذَا تَعَرَّى الرَّجُلُ نَظَرَ إِلَيْهِ الشَّيْطَانُ فَطَمِعَ فِيهِ فَاسْتَتِرُوا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingاذا تعري الرجل نظر اليه الشيطان فطمع فيه فاستتروا', 'اذا تعري الرجل نظر اليه الشيطان فطمع فيه فاستتروا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 41, NULL, 'When a man uncovers himself, Satan looks at him and covets him — so conceal yourselves.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'when a man uncovers himself satan looks at him and covets him so conceal yourselves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 42, NULL, 'He said therein:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'he said therein', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 43, NULL, 'Sayingلَيْسَ لِلرَّجُلِ أَنْ يَكْشِفَ ثِيَابَهُ عَنْ فَخِذِهِ وَيَجْلِسَ بَيْنَ أَيْدِي قَوْمٍ', '', 'لَيْسَ لِلرَّجُلِ أَنْ يَكْشِفَ ثِيَابَهُ عَنْ فَخِذِهِ وَيَجْلِسَ بَيْنَ أَيْدِي قَوْمٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingليس للرجل ان يكشف ثيابه عن فخذه ويجلس بين ايدي قوم', 'ليس للرجل ان يكشف ثيابه عن فخذه ويجلس بين ايدي قوم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 44, NULL, 'A man must not draw his garment back from his thigh and sit before a company of people.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'a man must not draw his garment back from his thigh and sit before a company of people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 45, NULL, 'He said therein:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'he said therein', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 46, NULL, 'Sayingاِغْسِلُوا أَيْدِيَ صِبْيَانِكُمْ مِنَ الْغَمَرِ فَأِنَّ الشَّيْطَانَ يَشُمُّ الْغَمَرَ فَيُفْزِعُ الصَّبِيَّ فِي رُقَادِهِ وَيُؤْذَى بِهِ الْكَاتِبَانِ', '', 'اِغْسِلُوا أَيْدِيَ صِبْيَانِكُمْ مِنَ الْغَمَرِ فَأِنَّ الشَّيْطَانَ يَشُمُّ الْغَمَرَ فَيُفْزِعُ الصَّبِيَّ فِي رُقَادِهِ وَيُؤْذَى بِهِ الْكَاتِبَانِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingاغسلوا ايدي صبيانكم من الغمر فان الشيطان يشم الغمر فيفزع الصبي في رقاده ويوذي به الكاتبان', 'اغسلوا ايدي صبيانكم من الغمر فان الشيطان يشم الغمر فيفزع الصبي في رقاده ويوذي به الكاتبان');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 47, NULL, 'Wash your children''s hands clean of the grease of food, for Satan smells it, the child is startled in his sleep, and the two recording angels are harmed by it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'wash your childrens hands clean of the grease of food for satan smells it the child is startled in his sleep and the two recording angels are harmed by it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 48, NULL, 'I turn now to the qualities of the wudhu.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'i turn now to the qualities of the wudhu', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 49, NULL, 'In the same book of questions and answers it is asked: What do you say, O best of those who have drawn us to the love of wisdom and of the wise, concerning what has come in the book of purity — that rinsing the mouth, drawing in water through the nose, and the istinja are prophetic practices that must not be deliberately abandoned, and that whoever forgets them or is unaware of them has not thereby spoiled his wudhu and owes no repetition if he has already prayed? What is intended by this istinja?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'in the same book of questions and answers it is asked what do you say o best of those who have drawn us to the love of wisdom and of the wise concerning what has come in the book of purity that rinsing the mouth drawing in water through the nose and the istinja are prophetic practices that must not be deliberately abandoned and that whoever forgets them or is unaware of them has not thereby spoiled his wudhu and owes no repetition if he has already prayed what is intended by this istinja', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 50, NULL, 'Answer: The istinja, the rinsing of the mouth, and the drawing in of water are practices that must not be deliberately abandoned, and whoever omits them has not spoiled his prayer. The istinja is nonetheless obligatory for the removal of impurity, because the removal of impurity is itself obligatory.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'answer the istinja the rinsing of the mouth and the drawing in of water are practices that must not be deliberately abandoned and whoever omits them has not spoiled his prayer the istinja is nonetheless obligatory for the removal of impurity because the removal of impurity is itself obligatory', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 51, NULL, 'Question: What do you say, O best of those whose blessed meeting has made us forget all love of family and friends, concerning what has come in Daaim al-Islam in the command to wash the face while letting the eyes drink of the water? Does any deficiency enter the wudhu of one who closes his eyes while washing his face?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'question what do you say o best of those whose blessed meeting has made us forget all love of family and friends concerning what has come in daaim al islam in the command to wash the face while letting the eyes drink of the water does any deficiency enter the wudhu of one who closes his eyes while washing his face', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 52, NULL, 'Answer: If he lets his eyes drink, that is better; and if he does not, his wudhu is complete.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'answer if he lets his eyes drink that is better and if he does not his wudhu is complete', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 53, NULL, 'Question: What do you say, O one with whom God is pleased only as He is pleased with His righteous servants, concerning a man who has upon his face or his hands a wound or a boil that water cannot touch? Must he leave it when performing the wudhu or the ghusl?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'question what do you say o one with whom god is pleased only as he is pleased with his righteous servants concerning a man who has upon his face or his hands a wound or a boil that water cannot touch must he leave it when performing the wudhu or the ghusl', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 54, NULL, 'Answer: Whoever has upon his legs or elsewhere an ailment, wound, or boil that water cannot touch may wipe over the bandages and whatever else covers the wound. If he fears that removing them would harm him through cold or severe injury, or if he is sick, he performs tayammum. That is the ruling for wudhu. As for the greater purification: whoever has an ailment such as smallpox, wounds, or the like pours water over it in a stream; and if he fears for himself, he must perform tayammum, whether he is traveling or at home.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'answer whoever has upon his legs or elsewhere an ailment wound or boil that water cannot touch may wipe over the bandages and whatever else covers the wound if he fears that removing them would harm him through cold or severe injury or if he is sick he performs tayammum that is the ruling for wudhu as for the greater purification whoever has an ailment such as smallpox wounds or the like pours water over it in a stream and if he fears for himself he must perform tayammum whether he is traveling or at home', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 55, NULL, 'Question: What does our master — may God grant us his pleasure — say concerning wiping over the two feet when most of the foot is exposed and the lesser part is covered beneath the strap of the sandal? Is such wiping permitted?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'question what does our master may god grant us his pleasure say concerning wiping over the two feet when most of the foot is exposed and the lesser part is covered beneath the strap of the sandal is such wiping permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 56, NULL, 'Answer: This is an obligation, and the wiping must be carried out beneath it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'answer this is an obligation and the wiping must be carried out beneath it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 57, NULL, 'Question: What does our master — may God perpetuate his support — say concerning one who entered the prayer after performing wudhu, then recalled that he had forgotten the istinja with water? Does he complete his prayer or repeat it?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'question what does our master may god perpetuate his support say concerning one who entered the prayer after performing wudhu then recalled that he had forgotten the istinja with water does he complete his prayer or repeat it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 58, NULL, 'Answer: The prayer is not permitted while a man carries an impurity of which he is aware, until he washes it away.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'answer the prayer is not permitted while a man carries an impurity of which he is aware until he washes it away', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 59, NULL, 'From another source: whoever performs wudhu, forgets the hand and the face, prays, and only recalls after the time has passed does not repeat the prayer. If a man performs wudhu, then rises and walks about until the limbs dry, he begins the wudhu again from the start; and if they have not dried, he completes what remains. Whoever performs wudhu for the prayer, then rises and afterward finds a spot on one of the wudhu limbs that has dried, does not repeat the wudhu but wipes the place that has dried. As for one whose hands are cut off and who cannot perform wudhu for the prayer, the bondmaid who belongs to him performs it for him, or his wife; and if he finds neither of them, he performs tayammum and prays.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'from another source whoever performs wudhu forgets the hand and the face prays and only recalls after the time has passed does not repeat the prayer if a man performs wudhu then rises and walks about until the limbs dry he begins the wudhu again from the start and if they have not dried he completes what remains whoever performs wudhu for the prayer then rises and afterward finds a spot on one of the wudhu limbs that has dried does not repeat the wudhu but wipes the place that has dried as for one whose hands are cut off and who cannot perform wudhu for the prayer the bondmaid who belongs to him performs it for him or his wife and if he finds neither of them he performs tayammum and prays', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 60, NULL, 'Question: What do you say, O one whom God Most High has made the trustee of His friends, concerning a pool or an empty hollow with no water, in which people relieve themselves, and then water flows into it together with the filth until it gathers and becomes overpowering — above the measure, subduing the impurities — so that none of their qualities can be detected in it? Is purification with it permitted?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'question what do you say o one whom god most high has made the trustee of his friends concerning a pool or an empty hollow with no water in which people relieve themselves and then water flows into it together with the filth until it gathers and becomes overpowering above the measure subduing the impurities so that none of their qualities can be detected in it is purification with it permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 61, NULL, 'Answer: If the water overpowers the impurity, purification with it is permitted, provided it is abundant and above the measure stated in the Shariah.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'answer if the water overpowers the impurity purification with it is permitted provided it is abundant and above the measure stated in the shariah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 62, NULL, 'Question: What do you say, O one whom God Most High has made the delight of the eye of the beloved of God, concerning a vessel filled with water to above the measure, in which an impurity then appears or falls and one of its qualities becomes apparent, after which water is poured into it in a stream until the trace of that impurity disappears? Is purification with it permitted?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'question what do you say o one whom god most high has made the delight of the eye of the beloved of god concerning a vessel filled with water to above the measure in which an impurity then appears or falls and one of its qualities becomes apparent after which water is poured into it in a stream until the trace of that impurity disappears is purification with it permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 63, NULL, 'Answer: The water has become impure, and purification with it is not permitted, unless it rises above the measure after the vessel has been purified.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'answer the water has become impure and purification with it is not permitted unless it rises above the measure after the vessel has been purified', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 64, NULL, 'Question: What do you say, O one whom God Most High has made a spring of water by which the souls of the people of Islam are made to endure, concerning a small quantity of pure water with which one who bears no impurity on his body purifies himself, then another purifies himself with it, and then another — and likewise the dust of tayammum? The Shariah has stated that used water is pure and purifying, yet we find in it no mention of used dust, and ordinary people do not permit using water or dust for purification a second time.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'question what do you say o one whom god most high has made a spring of water by which the souls of the people of islam are made to endure concerning a small quantity of pure water with which one who bears no impurity on his body purifies himself then another purifies himself with it and then another and likewise the dust of tayammum the shariah has stated that used water is pure and purifying yet we find in it no mention of used dust and ordinary people do not permit using water or dust for purification a second time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 65, NULL, 'Answer: Purification with it is permitted, once and many times.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'answer purification with it is permitted once and many times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 66, NULL, 'Question: What do you say concerning the meaning of his saying (ع):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'question what do you say concerning the meaning of his saying ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 67, NULL, 'Sayingمَنْ لَمْ يُطَهِّرْهُ الْبَحْرُ فَلَا طَهَّرَهُ اللهُ', '', 'مَنْ لَمْ يُطَهِّرْهُ الْبَحْرُ فَلَا طَهَّرَهُ اللهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingمن لم يطهره البحر فلا طهره الله', 'من لم يطهره البحر فلا طهره الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 68, NULL, 'Whoever the sea does not purify, may God not purify him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'whoever the sea does not purify may god not purify him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 69, NULL, 'Answer: Water purifies and is not itself purified; and likewise the knowledge of the Imam: whomever it does not purify, nothing else will purify him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'answer water purifies and is not itself purified and likewise the knowledge of the imam whomever it does not purify nothing else will purify him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 70, NULL, 'If the water in a pool is eight cubits in its length and breadth — though its depth be only a span or less — purification in it is permitted. If rain falls in the city and the water runs together with filth and refuse into a great pool in which a man and a camel might drown, and the pool is filled, washing and purification with it are permitted so long as its color or its taste or its smell has not changed. And if water is drawn from a well and the water is running, and an unbeliever washes a garment in it and its dirt is seen, purification with it is permitted, because it has the ruling of running water.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'if the water in a pool is eight cubits in its length and breadth though its depth be only a span or less purification in it is permitted if rain falls in the city and the water runs together with filth and refuse into a great pool in which a man and a camel might drown and the pool is filled washing and purification with it are permitted so long as its color or its taste or its smell has not changed and if water is drawn from a well and the water is running and an unbeliever washes a garment in it and its dirt is seen purification with it is permitted because it has the ruling of running water', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 71, NULL, 'From Mukhtasar al-Musannaf: if a man finds a little water upon the ground, or in a hollow, or the like, and it is greatly changed, and it is not known whether impurity has mixed with it, he performs wudhu with it nonetheless — for water may change without any impurity having mixed with it. What is extracted from substances by pressing or distillation, such as rosewater and the like, may not be used for purification. What has been used in purifying the limbs when no impurity was upon them, and has not gathered in an impure vessel, may be used for purification. And it is permitted to perform wudhu with water that has already been used once for wudhu, so long as no impurity has mixed with it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'from mukhtasar al musannaf if a man finds a little water upon the ground or in a hollow or the like and it is greatly changed and it is not known whether impurity has mixed with it he performs wudhu with it nonetheless for water may change without any impurity having mixed with it what is extracted from substances by pressing or distillation such as rosewater and the like may not be used for purification what has been used in purifying the limbs when no impurity was upon them and has not gathered in an impure vessel may be used for purification and it is permitted to perform wudhu with water that has already been used once for wudhu so long as no impurity has mixed with it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 72, NULL, 'It is mentioned in the Muayyadi Sessions: washing with rainwater at the time of the rain suffices. And it is said in Mukhtasar al-Musannaf: whoever has on his hand a ring bearing the name of God must not touch impurity while wearing it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'it is mentioned in the muayyadi sessions washing with rainwater at the time of the rain suffices and it is said in mukhtasar al musannaf whoever has on his hand a ring bearing the name of god must not touch impurity while wearing it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 73, NULL, 'Our master the Qadi al-Numan ibn Muhammad, may God exalt his sanctity, said in Kitab al-Idah, in the section on the description of washing the hands, that he had mentioned what was related from Abu Abdillah Jafar ibn Muhammad (ع), who said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'our master the qadi al numan ibn muhammad may god exalt his sanctity said in kitab al idah in the section on the description of washing the hands that he had mentioned what was related from abu abdillah jafar ibn muhammad ع who said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 74, NULL, 'Sayingوَلَا يَنْبَغِي أَنْ تَمْسَحَ ذِرَاعَيْكَ اِلَّا مِنَ الْمِرْفَقِ إِلَى فَوْقُ وَامْسَحْهُ مَسْحًا فَإِذَا كَانَ يَلْزَمُ فِي الْيَدَيْنِ عَلَى قِلَّةِ شَعَرِهِمَا فَهُوَ فِي الرَّأْسِ اَلْزَمُ', '', 'وَلَا يَنْبَغِي أَنْ تَمْسَحَ ذِرَاعَيْكَ اِلَّا مِنَ الْمِرْفَقِ إِلَى فَوْقُ وَامْسَحْهُ مَسْحًا فَإِذَا كَانَ يَلْزَمُ فِي الْيَدَيْنِ عَلَى قِلَّةِ شَعَرِهِمَا فَهُوَ فِي الرَّأْسِ اَلْزَمُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingولا ينبغي ان تمسح ذراعيك الا من المرفق الي فوق وامسحه مسحا فاذا كان يلزم في اليدين علي قله شعرهما فهو في الراس الزم', 'ولا ينبغي ان تمسح ذراعيك الا من المرفق الي فوق وامسحه مسحا فاذا كان يلزم في اليدين علي قله شعرهما فهو في الراس الزم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 75, NULL, 'It has likewise come down that when a person performing the wudhu interrupts it, he builds upon what he has done, so long as the water has not dried from the limbs he has already washed.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'it has likewise come down that when a person performing the wudhu interrupts it he builds upon what he has done so long as the water has not dried from the limbs he has already washed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 76, NULL, 'He said in Tawil al-Shariah of our master al-Muizz li-Din Allah, may the blessings of God be upon him, that the Prophet said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'he said in tawil al shariah of our master al muizz li din allah may the blessings of god be upon him that the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 77, NULL, 'Sayingإِذَا وَلَغَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ آخِرَهُنَّ بِالتُّرَابِ', '', 'إِذَا وَلَغَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ آخِرَهُنَّ بِالتُّرَابِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingاذا ولغ الكلب في اناء احدكم فليغسله سبع مرات اخرهن بالتراب', 'اذا ولغ الكلب في اناء احدكم فليغسله سبع مرات اخرهن بالتراب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 78, NULL, 'When a dog laps from the vessel of one of you, let him wash it seven times, the last of them with dust.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'when a dog laps from the vessel of one of you let him wash it seven times the last of them with dust', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 79, NULL, 'It is said in Mukhtasar al-Musannaf: when a vessel is made impure by a dog''s lapping, it is washed seven times, the first of them with dust; and the pig is like it. It is said therein also: if an impurity falls into one of two vessels and it is not known which of them it is, he does not perform wudhu with either of them, but performs tayammum and prays, and nothing is upon him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'it is said in mukhtasar al musannaf when a vessel is made impure by a dogs lapping it is washed seven times the first of them with dust and the pig is like it it is said therein also if an impurity falls into one of two vessels and it is not known which of them it is he does not perform wudhu with either of them but performs tayammum and prays and nothing is upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 80, NULL, 'It is said in Majalis al-Bayan that the obligatory acts of the wudhu are seven:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'it is said in majalis al bayan that the obligatory acts of the wudhu are seven', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 81, NULL, 'Pure water. The intention. Washing the face. Washing the hands. Wiping the head. Wiping the feet. The order — that one begins with what God began with in His mention.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'pure water the intention washing the face washing the hands wiping the head wiping the feet the order that one begins with what god began with in his mention', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 82, NULL, 'And its Sunnah acts are twelve:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'and its sunnah acts are twelve', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 83, NULL, 'The istinja. Washing the hands before entering them into the vessel. Pronouncing the name of God when sitting down for the wudhu. Rinsing the mouth. Drawing water into the nose. Moving the ring. Running the fingers through the beard. Letting the eyes drink of the water. Giving precedence to the right sides over the left. Wiping the two ears. The first washing, which is obligatory, the second and the third being Sunnah. The tooth stick.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'the istinja washing the hands before entering them into the vessel pronouncing the name of god when sitting down for the wudhu rinsing the mouth drawing water into the nose moving the ring running the fingers through the beard letting the eyes drink of the water giving precedence to the right sides over the left wiping the two ears the first washing which is obligatory the second and the third being sunnah the tooth stick', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 84, NULL, 'The obligatory forms of ghusl are seven:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'the obligatory forms of ghusl are seven', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 85, NULL, 'The ghusl from major ritual impurity. The ghusl of menstruation. The ghusl of the unbeliever when he enters Islam. The ghusl of the madman and of one who has fainted, when they recover. The ghusl from the blood of childbirth. The ghusl from immersion in impurity. The washing of the dead, which is an obligation upon the living until one of them undertakes it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'the ghusl from major ritual impurity the ghusl of menstruation the ghusl of the unbeliever when he enters islam the ghusl of the madman and of one who has fainted when they recover the ghusl from the blood of childbirth the ghusl from immersion in impurity the washing of the dead which is an obligation upon the living until one of them undertakes it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 86, NULL, 'And the Sunnah forms of ghusl are twelve:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'and the sunnah forms of ghusl are twelve', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 87, NULL, 'The ghusl of Friday. and 3. The ghusl for the two festivals. The ghusl for entering the state of consecration. The ghusl for entering the sacred precinct. The ghusl for entering the Kabah. The ghusl for entering Madinah. The ghusl on the day of Arafah. The ghusl on three nights of the month of Ramadan: the night of the nineteenth. The night of the twenty-first. The night of the twenty-third. The ghusl after washing the dead.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'the ghusl of friday and 3 the ghusl for the two festivals the ghusl for entering the state of consecration the ghusl for entering the sacred precinct the ghusl for entering the kabah the ghusl for entering madinah the ghusl on the day of arafah the ghusl on three nights of the month of ramadan the night of the nineteenth the night of the twenty first the night of the twenty third the ghusl after washing the dead', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 88, NULL, 'And the prayer is disliked in twelve places:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'and the prayer is disliked in twelve places', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 89, NULL, 'The graveyard. The slaughterhouse. The bathhouse. The privy. The resting places of camels. Praying toward a sleeping person. Praying without a screen. Upon wet, impure ground. Upon anything of food. In the places of worship of the Jews. Of the Christians. Of the Magians, unless water be sprinkled in them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'the graveyard the slaughterhouse the bathhouse the privy the resting places of camels praying toward a sleeping person praying without a screen upon wet impure ground upon anything of food in the places of worship of the jews of the christians of the magians unless water be sprinkled in them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 90, NULL, 'He said in Tawil al-Shariah that there is no fixed limit for the istinja other than purity, the settling of the heart and the soul, and the arrival of certainty that purity has been attained and impurity removed. He said therein also that the Prophet forbade wiping over the socks and forbade the abandoning of saying aloud بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'he said in tawil al shariah that there is no fixed limit for the istinja other than purity the settling of the heart and the soul and the arrival of certainty that purity has been attained and impurity removed he said therein also that the prophet forbade wiping over the socks and forbade the abandoning of saying aloud بسم الله الرحمن الرحيم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 91, NULL, 'Our master Jafar ibn Mansur al-Yaman, may God exalt his sanctity, said at the beginning of Kitab al-Rida al-Batin that the Sunnah in the wudhu is three times over, three times over, in every place of the wudhu, except the private parts — meaning that these are washed until the impurity is gone from them. Then he said, after that, may God exalt his sanctity, that the wudhu is threefold, threefold. And he said therein, after further words, that the Sunnah in the ghusl is that a man wash himself with water until it drips and flows; and if he does not find abundant water, then let him wipe with as much as will reach his whole body with water.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'our master jafar ibn mansur al yaman may god exalt his sanctity said at the beginning of kitab al rida al batin that the sunnah in the wudhu is three times over three times over in every place of the wudhu except the private parts meaning that these are washed until the impurity is gone from them then he said after that may god exalt his sanctity that the wudhu is threefold threefold and he said therein after further words that the sunnah in the ghusl is that a man wash himself with water until it drips and flows and if he does not find abundant water then let him wipe with as much as will reach his whole body with water', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 92, NULL, 'It is said in Mukhtasar al-Athar, in the mention of the qualities of the wudhu, that one then rinses the mouth and draws in water three times, and that this is of the Sunnah and should not be abandoned; and if one leaves it without intending to leave it, nothing is upon him. It is said therein: he washes it three times, and if he washes it twice or once in a complete washing, it suffices him — three is better, and there is no merit beyond three. And it is said therein: once suffices him, and if he wipes it three times, that is good.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'it is said in mukhtasar al athar in the mention of the qualities of the wudhu that one then rinses the mouth and draws in water three times and that this is of the sunnah and should not be abandoned and if one leaves it without intending to leave it nothing is upon him it is said therein he washes it three times and if he washes it twice or once in a complete washing it suffices him three is better and there is no merit beyond three and it is said therein once suffices him and if he wipes it three times that is good', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 93, NULL, 'Our master the most exalted summoner Zayd (زَيْد) ibn Muhammad ibn al-Fadl, may God sanctify his soul, said in al-Risalah al-Maknunah: God, the most truthful of those who speak, said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'our master the most exalted summoner zayd زيد ibn muhammad ibn al fadl may god sanctify his soul said in al risalah al maknunah god the most truthful of those who speak said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'the manners of the washing place', '8. The Manners of the Washing Place', 94, NULL, 'Al-Baqarah: 222إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّبِينَ وَيُحِبُّ ٱلْمُتَطَهِّرِينَ', '', 'إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّبِينَ وَيُحِبُّ ٱلْمُتَطَهِّرِينَ', 'Al-Baqarah: 222', 2, 222, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'al baqarah 222ان الله يحب التوبين ويحب المتطهرين', 'ان الله يحب التوبين ويحب المتطهرين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 95, NULL, 'Truly God loves those who turn to Him in repentance, and He loves those who purify themselves.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'truly god loves those who turn to him in repentance and he loves those who purify themselves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 96, NULL, 'And the Messenger of God said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'and the messenger of god said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 97, NULL, 'Sayingلَا تُقْبَلُ الصَّلَاةُ اِلَّا بِطُهُورٍ', '', 'لَا تُقْبَلُ الصَّلَاةُ اِلَّا بِطُهُورٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingلا تقبل الصلاه الا بطهور', 'لا تقبل الصلاه الا بطهور');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 98, NULL, 'Prayer is not accepted except with purification.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'prayer is not accepted except with purification', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 99, NULL, 'Purity is of two kinds, and so is filth. Outward purity is achieved through outward water, cleansing from the outward filth of urine and excrement; inward purity is achieved through inward water — which is knowledge — cleansing from the inward filth of doubt and ignorance.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'purity is of two kinds and so is filth outward purity is achieved through outward water cleansing from the outward filth of urine and excrement inward purity is achieved through inward water which is knowledge cleansing from the inward filth of doubt and ignorance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 100, NULL, 'He said therein that the name of wudhu covers seven meanings: four obligatory and three Sunnah. He also noted that the Messenger placed the three Sunnah acts before the four obligations, and he mentioned washing the hands before putting them into the vessel.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'he said therein that the name of wudhu covers seven meanings four obligatory and three sunnah he also noted that the messenger placed the three sunnah acts before the four obligations and he mentioned washing the hands before putting them into the vessel', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 101, NULL, 'He said that the mouth is what a person uses to take nourishment from all kinds of food and drink. A person has no other faculty through which nourishment comes to him; the mouth is the one that conveys nourishment to the five senses, and articulate expression belongs to it alone. Then he said: it is like the mouth of the lesser world — whoever seeks nourishment through anything other than the mouth is neither nourished nor alive.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'he said that the mouth is what a person uses to take nourishment from all kinds of food and drink a person has no other faculty through which nourishment comes to him the mouth is the one that conveys nourishment to the five senses and articulate expression belongs to it alone then he said it is like the mouth of the lesser world whoever seeks nourishment through anything other than the mouth is neither nourished nor alive', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 102, NULL, 'As for drawing water through the nose, he said: the nostrils draw breath from the air, by which the body lives and rests. When the nostrils are blocked, that function passes to the mouth, which takes their place with effort. But when both faculties together — the nose and the mouth — are blocked, the person perishes and can never live again.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'as for drawing water through the nose he said the nostrils draw breath from the air by which the body lives and rests when the nostrils are blocked that function passes to the mouth which takes their place with effort but when both faculties together the nose and the mouth are blocked the person perishes and can never live again', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 103, NULL, 'Then he said: rinsing the mouth, drawing in water, and the istinja are three Sunnah acts; washing the face and washing the hands are two obligations; and wiping the head and wiping the feet are two obligations. That is seven bounds. Of the two washings, one is bounded and the other is unbounded; and of the two wipings, one is bounded and the other is unbounded.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'then he said rinsing the mouth drawing in water and the istinja are three sunnah acts washing the face and washing the hands are two obligations and wiping the head and wiping the feet are two obligations that is seven bounds of the two washings one is bounded and the other is unbounded and of the two wipings one is bounded and the other is unbounded', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 104, NULL, 'The face bears the meaning of the Speaker, for in it are the seven openings: the two eyes, the two ears, the two nostrils, and the mouth. A person is known by his face; and likewise, no one is known except through his prophet, and there is no deliverance except by turning toward him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'the face bears the meaning of the speaker for in it are the seven openings the two eyes the two ears the two nostrils and the mouth a person is known by his face and likewise no one is known except through his prophet and there is no deliverance except by turning toward him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 105, NULL, 'And our master the Commander of the Faithful Ali ibn Abi Talib (ع) said in his Four Hundred Manners:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'and our master the commander of the faithful ali ibn abi talib ع said in his four hundred manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 106, NULL, 'Sayingلَيْسَ فِي شُرْبِ الْمُسْكِرِ وَالْمَسْحِ عَلَى الْخُفَّيْنِ تَقِيَّةٌ', '', 'لَيْسَ فِي شُرْبِ الْمُسْكِرِ وَالْمَسْحِ عَلَى الْخُفَّيْنِ تَقِيَّةٌ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'sayingليس في شرب المسكر والمسح علي الخفين تقيه', 'ليس في شرب المسكر والمسح علي الخفين تقيه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the manners of the washing place', '8. The Manners of the Washing Place', 107, NULL, 'There is no dissimulation in the drinking of intoxicants or in wiping over the socks.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 8 the manners of the washing place', 'there is no dissimulation in the drinking of intoxicants or in wiping over the socks', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 1, NULL, 'I take the questions and answers that follow from the book of questions and answers mentioned earlier, which one of its compilers arranged according to the chapters of the book Daaim al-Islam.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'i take the questions and answers that follow from the book of questions and answers mentioned earlier which one of its compilers arranged according to the chapters of the book daaim al islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 2, NULL, 'Question: What do you say, O best of those for whom our tongues fall short in praise and gratitude, concerning what has come in certain books of the Shariah: that when a man fears the cold and a ghusl is due upon him, he performs tayammum and prays, and then, when he is able to use water, he washes and repeats the prayer? Does this ruling apply equally to the resident and the traveler, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what do you say o best of those for whom our tongues fall short in praise and gratitude concerning what has come in certain books of the shariah that when a man fears the cold and a ghusl is due upon him he performs tayammum and prays and then when he is able to use water he washes and repeats the prayer does this ruling apply equally to the resident and the traveler or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 3, NULL, 'Answer: If he fears that the water will harm him — whether he is a resident or a traveler — he performs tayammum and prays, and nothing further is required of him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer if he fears that the water will harm him whether he is a resident or a traveler he performs tayammum and prays and nothing further is required of him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 4, NULL, 'Question: What do you say, O one to whose excellence the far and the near both bear witness, concerning the ghusl from janabah (جَنَابَة), since marital relations are a likeness of imparting and receiving? Explain, then, the likeness of the washing and what the one who washes is obliged to call to mind while washing, for the exposition of this in the books of the guiding Dawah is very long.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what do you say o one to whose excellence the far and the near both bear witness concerning the ghusl from janabah جنابه since marital relations are a likeness of imparting and receiving explain then the likeness of the washing and what the one who washes is obliged to call to mind while washing for the exposition of this in the books of the guiding dawah is very long', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 5, NULL, 'Answer: The washing is a likeness of the removal of doubt, and doubt arises only at the moment of imparting and receiving.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer the washing is a likeness of the removal of doubt and doubt arises only at the moment of imparting and receiving', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 6, NULL, 'Question: What do you say, O one whom God Most High has made a rope extended from heaven to this world for the people of the earth who remember God while sitting and while standing, concerning what has come in the Shariah: that one who has fallen unconscious, when he revives after some days and does not know whether he may have become in a state of janabah, must perform the ghusl? O our master, what is the measure of this if he sees no trace of semen?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what do you say o one whom god most high has made a rope extended from heaven to this world for the people of the earth who remember god while sitting and while standing concerning what has come in the shariah that one who has fallen unconscious when he revives after some days and does not know whether he may have become in a state of janabah must perform the ghusl o our master what is the measure of this if he sees no trace of semen', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 7, NULL, 'Answer: If he does not know his own condition, the ghusl becomes obligatory upon him once doubt has entered him concerning it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer if he does not know his own condition the ghusl becomes obligatory upon him once doubt has entered him concerning it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 8, NULL, 'Question: What does our master say — may God inspire him with the welfare of the Dawah — concerning a weak man who has been overtaken by janabah and who fears the cold if he washes, when the time of prayer has come? May he perform tayammum as the sick man does, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what does our master say may god inspire him with the welfare of the dawah concerning a weak man who has been overtaken by janabah and who fears the cold if he washes when the time of prayer has come may he perform tayammum as the sick man does or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 9, NULL, 'Answer: If he fears the water, he performs tayammum and prays, and he does not repeat the prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer if he fears the water he performs tayammum and prays and he does not repeat the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 10, NULL, 'Question: What does our master say — may God perpetuate his support — concerning a man who wakes from sleep and sees on his garment the trace of semen, wet or dry, though he did not see in his sleep that he had emitted? Is the ghusl obligatory upon him or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what does our master say may god perpetuate his support concerning a man who wakes from sleep and sees on his garment the trace of semen wet or dry though he did not see in his sleep that he had emitted is the ghusl obligatory upon him or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 11, NULL, 'Answer: The ghusl is obligatory upon him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer the ghusl is obligatory upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 12, NULL, 'Question: What do you say, O fulfiller of the needs of those who ask, concerning what is mentioned in the Shariah: that it is disliked for the one in janabah and for the menstruating woman to remove from themselves any hair or nail, and that the woman in post-natal bleeding is in the same state as the menstruating woman? O our master, is this permitted to them despite the dislike, or is it not permitted at all?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what do you say o fulfiller of the needs of those who ask concerning what is mentioned in the shariah that it is disliked for the one in janabah and for the menstruating woman to remove from themselves any hair or nail and that the woman in post natal bleeding is in the same state as the menstruating woman o our master is this permitted to them despite the dislike or is it not permitted at all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 13, NULL, 'Answer: To leave it is better, until such a one is purified.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer to leave it is better until such a one is purified', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 14, NULL, 'Question: What do you say, O one whom I approached from where I came — out of nothing but pure love — concerning the one in janabah and the menstruating woman who read supplications or other books in which there is something of the Quran, whether the reader recognizes it or does not? How is such a one to act — reading it or leaving it — when it has come in the radiant Shariah that the two do not recite the Quran and do not touch it? And may the one in janabah and the menstruating woman recite the declaration of God''s oneness, the magnification, the praise, and the glorification, all of which are in the Quran? And may such a one recite the اَلْبَسْمَلَة, when it has been said that it is a verse of the Quran?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what do you say o one whom i approached from where i came out of nothing but pure love concerning the one in janabah and the menstruating woman who read supplications or other books in which there is something of the quran whether the reader recognizes it or does not how is such a one to act reading it or leaving it when it has come in the radiant shariah that the two do not recite the quran and do not touch it and may the one in janabah and the menstruating woman recite the declaration of gods oneness the magnification the praise and the glorification all of which are in the quran and may such a one recite the البسمله when it has been said that it is a verse of the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 15, NULL, 'Answer: Neither the menstruating woman nor the one in janabah may recite the Quran, nor any part of it in a supplication or in books, deliberately; and neither may recite the اَلْبَسْمَلَة with the intention of reciting the Quran.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer neither the menstruating woman nor the one in janabah may recite the quran nor any part of it in a supplication or in books deliberately and neither may recite the البسمله with the intention of reciting the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 16, NULL, 'In the book Mukhtasar al-Musannaf it is said that whoever forgets the ablution until he has performed the ghusl performs the ablution, and there is nothing against him. It is also said there: when a man has performed the ablution and then begins the ghusl, and a minor impurity occurs before he has completed his washing, he continues with the ghusl and performs the ablution after it for the prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'in the book mukhtasar al musannaf it is said that whoever forgets the ablution until he has performed the ghusl performs the ablution and there is nothing against him it is also said there when a man has performed the ablution and then begins the ghusl and a minor impurity occurs before he has completed his washing he continues with the ghusl and performs the ablution after it for the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 17, NULL, 'Among the answers of certain summoners of Yemen to certain dignitaries of the Indian lands (رض): if one in janabah and a deceased person are brought together and there is not found of water except what suffices for one of them, the one in janabah performs the ghusl and tayammum is performed for the deceased.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'among the answers of certain summoners of yemen to certain dignitaries of the indian lands رض if one in janabah and a deceased person are brought together and there is not found of water except what suffices for one of them the one in janabah performs the ghusl and tayammum is performed for the deceased', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 18, NULL, 'The author of al-Risala al-Maknuna said: God has imposed the ghusl from janabah, for He said — exalted be He who speaks:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'the author of al risala al maknuna said god has imposed the ghusl from janabah for he said exalted be he who speaks', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 19, NULL, 'Al-Ma''idah: 6وَإِن كُنتُمْ جُنُبًۭا فَٱطَّهَّرُوا۟"And if you are in a state of major impurity, then purify yourselves."', '', NULL, 'Al-Ma''idah: 6', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'al maidah 6وان كنتم جنبا فاطهروا and if you are in a state of major impurity then purify yourselves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 20, NULL, 'And the Prophet said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'and the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 21, NULL, 'Sayingتَحْتَ كُلِّ شَعْرٍ جَنَابَةٌ فَبُلُّوا الشَّعْرَ وَاَنْقُوا الْبَشَرَ"Beneath every hair there is major impurity, so wet the hair and cleanse the skin."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingتحت كل شعر جنابه فبلوا الشعر وانقوا البشر beneath every hair there is major impurity so wet the hair and cleanse the skin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 22, NULL, 'Then he said: whoever does not do that is junub, and al-junub is the one far from a thing. It is said, "he is a stranger to me" — that is, far from my lineage. And the obedience of the one in janabah is void and false.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'then he said whoever does not do that is junub and al junub is the one far from a thing it is said he is a stranger to me that is far from my lineage and the obedience of the one in janabah is void and false', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 23, NULL, 'The Commander of the Faithful, our master Ali ibn Abi Talib (ع), said in his Four Hundred Manners:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'the commander of the faithful our master ali ibn abi talib ع said in his four hundred manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 24, NULL, 'Sayingلَا يَنَامُ الْمُسْلِمُ وَهُوَ جُنُبٌ وَلَا يَنَامُ اِلَّا وَهُوَ عَلَىٰ طَهُورٍ فَاِنْ لَمْ يَجِدِ الْمَاءَ فَلْيَتَيَمَّمْ بِالصَّعِيدِ فَاِنَّ رُوحَ الْمُؤْمِنِ تَرْتَفِعُ إِلَى اللَّهِ عَزَّ وَجَلَّ فَيَقْبَلُهَا وَيُبَارِكُ عَلَيْهَا فَاِنْ كَانَ قَدْ حَضَرَ أَجَلُهَا جَعَلَهَا فِي أَحْسَنِ صُورَةٍ وَاِنْ لَمْ يَحْضُرْ أَجَلُهَا بَعَثَ بِهَا مَعَ أُمَنَاءِهِ مِنَ الْمَلَائِكَةِ فَرَدُّوهَا إِلَىٰ جَسَدِهِ', '', 'لَا يَنَامُ الْمُسْلِمُ وَهُوَ جُنُبٌ وَلَا يَنَامُ اِلَّا وَهُوَ عَلَىٰ طَهُورٍ فَاِنْ لَمْ يَجِدِ الْمَاءَ فَلْيَتَيَمَّمْ بِالصَّعِيدِ فَاِنَّ رُوحَ الْمُؤْمِنِ تَرْتَفِعُ إِلَى اللَّهِ عَزَّ وَجَلَّ فَيَقْبَلُهَا وَيُبَارِكُ عَلَيْهَا فَاِنْ كَانَ قَدْ حَضَرَ أَجَلُهَا جَعَلَهَا فِي أَحْسَنِ صُورَةٍ وَاِنْ لَمْ يَحْضُرْ أَجَلُهَا بَعَثَ بِهَا مَعَ أُمَنَاءِهِ مِنَ الْمَلَائِكَةِ فَرَدُّوهَا إِلَىٰ جَسَدِهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingلا ينام المسلم وهو جنب ولا ينام الا وهو علي طهور فان لم يجد الماء فليتيمم بالصعيد فان روح المومن ترتفع الي الله عز وجل فيقبلها ويبارك عليها فان كان قد حضر اجلها جعلها في احسن صوره وان لم يحضر اجلها بعث بها مع امناءه من الملايكه فردوها الي جسده', 'لا ينام المسلم وهو جنب ولا ينام الا وهو علي طهور فان لم يجد الماء فليتيمم بالصعيد فان روح المومن ترتفع الي الله عز وجل فيقبلها ويبارك عليها فان كان قد حضر اجلها جعلها في احسن صوره وان لم يحضر اجلها بعث بها مع امناءه من الملايكه فردوها الي جسده');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 26, NULL, 'I take these also from the book of question and answer mentioned earlier, arranged according to the chapters of Daaim al-Islam.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'i take these also from the book of question and answer mentioned earlier arranged according to the chapters of daaim al islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 27, NULL, 'Question: What do you say, O best of those who have commanded us to endure with patience the decree of God and His judgment, concerning vomit? Does it render impure what it falls upon, as blood and pus and the other impurities do, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what do you say o best of those who have commanded us to endure with patience the decree of god and his judgment concerning vomit does it render impure what it falls upon as blood and pus and the other impurities do or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 28, NULL, 'Answer: Vomit does not render impure what it falls upon, though it is better that the place be washed.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer vomit does not render impure what it falls upon though it is better that the place be washed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 29, NULL, 'Question: What do you say, O one whom God Most High has made a provision for the traveler who wishes to arrive at God Most High, concerning ground on which children urinate and relieve themselves, which then dries so that the smell of the impurity and its substance are gone from it? Is prayer upon it permissible without a mat, and is tayammum from it permissible, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what do you say o one whom god most high has made a provision for the traveler who wishes to arrive at god most high concerning ground on which children urinate and relieve themselves which then dries so that the smell of the impurity and its substance are gone from it is prayer upon it permissible without a mat and is tayammum from it permissible or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 30, NULL, 'Answer: If the substance of the impurity has gone, its ruling is the ruling of pure ground, provided it is not ground set aside as a privy for need.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer if the substance of the impurity has gone its ruling is the ruling of pure ground provided it is not ground set aside as a privy for need', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 31, NULL, 'Question: What do you say, O one whom God Most High has made a measure by which the corrupt is tested against the pure in the religion of God, concerning what has come in the Shariah: that when impurity strikes the ground and water then runs over it and it dries, and the smell of the impurity and its substance are gone from it, prayer upon it and tayammum from it are permitted? And it has also come that there is no harm in praying in the dry places among the resting grounds of camels and the folds of sheep. O our master, what is the difference between this and that?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what do you say o one whom god most high has made a measure by which the corrupt is tested against the pure in the religion of god concerning what has come in the shariah that when impurity strikes the ground and water then runs over it and it dries and the smell of the impurity and its substance are gone from it prayer upon it and tayammum from it are permitted and it has also come that there is no harm in praying in the dry places among the resting grounds of camels and the folds of sheep o our master what is the difference between this and that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 32, NULL, 'Answer: The sun and the light purify it. So when the substance of the impurity and its smell have gone from it, prayer upon it and tayammum from it are permitted.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer the sun and the light purify it so when the substance of the impurity and its smell have gone from it prayer upon it and tayammum from it are permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 33, NULL, 'Question: What does our master say, may God make lasting the throne of his governance, concerning the meaning of the words of the Commander of the Faithful:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what does our master say may god make lasting the throne of his governance concerning the meaning of the words of the commander of the faithful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 34, NULL, 'Sayingمَنْ مَسَّ جَسَدَ مَيِّتٍ بَعْدَ أَنْ يَبْرُدَ لَزِمَهُ الْغُسْلُ"Whoever touches the body of a dead man after it has grown cold must perform the ghusl."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingمن مس جسد ميت بعد ان يبرد لزمه الغسل whoever touches the body of a dead man after it has grown cold must perform the ghusl', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 35, NULL, 'What is the meaning of his words, "after it has grown cold"?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'what is the meaning of his words after it has grown cold', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 36, NULL, 'Answer: Its meaning is: after it has become impure. So when it touches the living with its moisture, he becomes impure, and this is the meaning of the ghusl becoming binding — that it be decreed upon him. And the washing performed by the one who washes the corpse is from the Sunnah.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer its meaning is after it has become impure so when it touches the living with its moisture he becomes impure and this is the meaning of the ghusl becoming binding that it be decreed upon him and the washing performed by the one who washes the corpse is from the sunnah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 37, NULL, 'Question: Concerning a thing that a man wishes to purify but is not able to rub or to wring out three times — such as a fur, a mat, a rug, the quilts used in the mosque, and bedding — what is the manner of purifying it?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question concerning a thing that a man wishes to purify but is not able to rub or to wring out three times such as a fur a mat a rug the quilts used in the mosque and bedding what is the manner of purifying it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 38, NULL, 'Answer: For a thing that a man wishes to purify but is not able to rub or to wring out three times, he passes his hand over it until the impurity and its smell are gone, then lifts it from the water and leaves it until what is in it has dripped out, then repeats this three times. As for what is other than this, he treads it with his feet in the manner described, then takes it out of the water and presses upon it until the water has come out of it, then repeats this three times.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer for a thing that a man wishes to purify but is not able to rub or to wring out three times he passes his hand over it until the impurity and its smell are gone then lifts it from the water and leaves it until what is in it has dripped out then repeats this three times as for what is other than this he treads it with his feet in the manner described then takes it out of the water and presses upon it until the water has come out of it then repeats this three times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 39, NULL, 'Question: Concerning a woman''s milk that falls upon the garment of another, is it pure or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question concerning a womans milk that falls upon the garment of another is it pure or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 40, NULL, 'Answer: From the Walid Izz al-Din Maad ibn Abdullah ibn Ali: the milk of a nursing woman, if she is a Muslim, is pure, both for her and for others. And I say that this is an established position, since her milk is like her saliva, and the saliva of every Muslim is pure and does not render impure what it touches.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer from the walid izz al din maad ibn abdullah ibn ali the milk of a nursing woman if she is a muslim is pure both for her and for others and i say that this is an established position since her milk is like her saliva and the saliva of every muslim is pure and does not render impure what it touches', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 41, NULL, 'Question: Concerning a man who shaves his head, and something of his hair falls while it is wet upon his garment or upon his body: does that hair render impure what it touches or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question concerning a man who shaves his head and something of his hair falls while it is wet upon his garment or upon his body does that hair render impure what it touches or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 42, NULL, 'Answer: If that is a small amount, then a small amount of impurity has been excused.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer if that is a small amount then a small amount of impurity has been excused', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 43, NULL, 'Question: Concerning the animals that feed upon filth — of cattle and camels and sheep — and the milk and clarified butter of these, and the white of the eggs of hens, when they fall upon the garments of those praying or upon their bodies: does this render them impure or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question concerning the animals that feed upon filth of cattle and camels and sheep and the milk and clarified butter of these and the white of the eggs of hens when they fall upon the garments of those praying or upon their bodies does this render them impure or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 44, NULL, 'Answer: That follows what was mentioned in the first case: a small amount of it is excused.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer that follows what was mentioned in the first case a small amount of it is excused', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 45, NULL, 'Question: Concerning the traveler and the sick man, whose garments are touched by impurity and who are not able to cleanse them, is the prayer complete for them with tayammum, or must it be made up afterward?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question concerning the traveler and the sick man whose garments are touched by impurity and who are not able to cleanse them is the prayer complete for them with tayammum or must it be made up afterward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 46, NULL, 'Answer: The prayer is not complete except with a pure garment. Tayammum has been mentioned for ritual impurity, and it has not been mentioned for the impurity of garments. As for the sick man, he instructs someone to wash his garments for him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer the prayer is not complete except with a pure garment tayammum has been mentioned for ritual impurity and it has not been mentioned for the impurity of garments as for the sick man he instructs someone to wash his garments for him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 47, NULL, 'Question: The polytheist worships idols and knows neither the lawful nor the forbidden, and he weaves the cloth, and after that he bleaches it, and after that he sews it. Is his work pure, and is prayer in it permitted or not? For God Most High has said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question the polytheist worships idols and knows neither the lawful nor the forbidden and he weaves the cloth and after that he bleaches it and after that he sews it is his work pure and is prayer in it permitted or not for god most high has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 48, NULL, 'At-Tawbah: 28إِنَّمَا ٱلْمُشْرِكُونَ نَجَسٌۭ"The polytheists are nothing but impurity."', '', NULL, 'At-Tawbah: 28', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'at tawbah 28انما المشركون نجس the polytheists are nothing but impurity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 49, NULL, 'Answer: All such garments are pure until he wears them; and if he has worn them, then they are impure, or if impurity has appeared in them. As he said in the book al-Daaim:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer all such garments are pure until he wears them and if he has worn them then they are impure or if impurity has appeared in them as he said in the book al daaim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 50, NULL, 'Sayingورخصوا الأئمة صلوات الله عليهم في الصلاة في الثياب التي يعملها المشركين ما لم يلبسوها أو تظهر فيها النجاسة', '', 'ورخصوا الأئمة صلوات الله عليهم في الصلاة في الثياب التي يعملها المشركين ما لم يلبسوها أو تظهر فيها النجاسة', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingورخصوا الايمه صلوات الله عليهم في الصلاه في الثياب التي يعملها المشركين ما لم يلبسوها او تظهر فيها النجاسه', 'ورخصوا الايمه صلوات الله عليهم في الصلاه في الثياب التي يعملها المشركين ما لم يلبسوها او تظهر فيها النجاسه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 51, NULL, 'He said also: the same applies to a dyed garment when the dyer is a polytheist — it remains pure until he has worn it; once he has worn it, it is impure.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'he said also the same applies to a dyed garment when the dyer is a polytheist it remains pure until he has worn it once he has worn it it is impure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 52, NULL, 'Question: What does our master say, may God perpetuate his support, concerning the bleaching that polytheists perform on whatever they bleach — does it carry purity or not? Be so good as to make this clear.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what does our master say may god perpetuate his support concerning the bleaching that polytheists perform on whatever they bleach does it carry purity or not be so good as to make this clear', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 53, NULL, 'Answer: I say — trusting in God''s granting of success and drawing support from the blessings of His friends — that there is no path to the purity of polytheists'' garments except those they have made before wearing them. As for what they have bleached and washed with soap, its purity is not allowed except by washing. Perhaps those who heard the saying about this did not grasp the root of the question in it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer i say trusting in gods granting of success and drawing support from the blessings of his friends that there is no path to the purity of polytheists garments except those they have made before wearing them as for what they have bleached and washed with soap its purity is not allowed except by washing perhaps those who heard the saying about this did not grasp the root of the question in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 54, NULL, 'Question: What does our master say, may God perpetuate his support, concerning the garments of polytheists التي they have made but have not worn, which they sprinkle with impure water at the time of the weaving and the spinning, after which the water dries and the garments are sold, and they have neither worn them nor washed them with soap? Is prayer in them permitted or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what does our master say may god perpetuate his support concerning the garments of polytheists التي they have made but have not worn which they sprinkle with impure water at the time of the weaving and the spinning after which the water dries and the garments are sold and they have neither worn them nor washed them with soap is prayer in them permitted or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 55, NULL, 'Answer: There is no harm in praying in them, and the radiant Shariah has permitted them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer there is no harm in praying in them and the radiant shariah has permitted them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 56, NULL, 'Question: What do you say, O one whose people of response have come to take pride in the praiseworthy account of his conduct, concerning the wide, long garment and the bedding of which one part is pure and another part impure? Is prayer performed upon the part of it that is pure? For the common people say that if the garment is of such a size that when one end of it is moved the other end does not move, prayer is permitted upon the part of it that is pure.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what do you say o one whose people of response have come to take pride in the praiseworthy account of his conduct concerning the wide long garment and the bedding of which one part is pure and another part impure is prayer performed upon the part of it that is pure for the common people say that if the garment is of such a size that when one end of it is moved the other end does not move prayer is permitted upon the part of it that is pure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 57, NULL, 'Answer: One does not pray upon it, and prayer upon it is not permitted.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer one does not pray upon it and prayer upon it is not permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 58, NULL, 'In the book Mukhtasar al-Musannaf it is said that prayer in the garments of children who guard themselves against impurity is permitted so long as no impurity is known in them, and dispensation has been given for a slight sprinkling. It is said there also: as for the houses out in the open country, praying in them has not been forbidden, though it is not recommended.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'in the book mukhtasar al musannaf it is said that prayer in the garments of children who guard themselves against impurity is permitted so long as no impurity is known in them and dispensation has been given for a slight sprinkling it is said there also as for the houses out in the open country praying in them has not been forbidden though it is not recommended', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 59, NULL, 'I turn now to the book of question and answer whose questions are from the most excellent Sheikh Yusuf ibn Ismail ibn Ibrahim al-Samti al-Hindi and whose answers are from our master Idris ibn al-Hasan.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'i turn now to the book of question and answer whose questions are from the most excellent sheikh yusuf ibn ismail ibn ibrahim al samti al hindi and whose answers are from our master idris ibn al hasan', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 60, NULL, 'Question: Is prayer permitted upon stone and upon plaster? Favor us with a sufficient and clear answer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question is prayer permitted upon stone and upon plaster favor us with a sufficient and clear answer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 61, NULL, 'Answer: The Prophet said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 62, NULL, 'Sayingجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا"The earth has been made for me a place of prostration and a means of purification."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingجعلت لي الارض مسجدا وطهورا the earth has been made for me a place of prostration and a means of purification', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 63, NULL, 'Anything of the ground from which tayammum is not permitted may not be prayed upon.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'anything of the ground from which tayammum is not permitted may not be prayed upon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 64, NULL, 'Question: What do you say about sweeping houses? Most people in India hold that houses must not be swept at night at all, and they treat it as a religious scruple; they likewise hold that shops and stalls are not to be swept at night. How does this stand — may God make us your ransom?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what do you say about sweeping houses most people in india hold that houses must not be swept at night at all and they treat it as a religious scruple they likewise hold that shops and stalls are not to be swept at night how does this stand may god make us your ransom', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 65, NULL, 'Answer: This view is not reliable, and there is no blame on one who does it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer this view is not reliable and there is no blame on one who does it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 66, NULL, 'In Tawil al-Shariah it is recorded that the Prophet said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'in tawil al shariah it is recorded that the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 67, NULL, 'Sayingإِذَا وَلَغَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ إِحْدَاهُنَّ بِالتُّرَابِ"When a dog laps from the vessel of one of you, let him wash it seven times, one of them with earth."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingاذا ولغ الكلب في اناء احدكم فليغسله سبع مرات احداهن بالتراب when a dog laps from the vessel of one of you let him wash it seven times one of them with earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 68, NULL, 'Mukhtasar al-Musannaf states: when a vessel becomes impure from a dog''s lapping, it is washed seven times, the first of them with earth, and the pig is treated the same way. It is also stated there: if impurity falls into one of two vessels and it is not known which of them it is, neither vessel is to be approached; one performs tayammum and prays.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'mukhtasar al musannaf states when a vessel becomes impure from a dogs lapping it is washed seven times the first of them with earth and the pig is treated the same way it is also stated there if impurity falls into one of two vessels and it is not known which of them it is neither vessel is to be approached one performs tayammum and prays', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 69, NULL, 'The Commander of the Faithful, Ali ibn Abi Talib (ع), said in his Four Hundred Manners:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'the commander of the faithful ali ibn abi talib ع said in his four hundred manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 70, NULL, 'Sayingأَخْذُ الشَّارِبِ مِنَ النَّظَافَةِ وَهُوَ مِنَ السُّنَّةِ"Trimming the mustache is part of cleanliness, and it is of the Sunnah."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingاخذ الشارب من النظافه وهو من السنه trimming the mustache is part of cleanliness and it is of the sunnah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 71, NULL, 'Sayingغَسْلُ الرَّأْسِ بِالْحِطْمِيِّ يُذْهِبُ بِالدَّرَنِ وَهُوَ مِنَ السُّنَّةِ وَيَنْفِي الْأَقْذَارَ"Washing the head with mallow takes away grime, and it is of the Sunnah, and it drives off filth."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingغسل الراس بالحطمي يذهب بالدرن وهو من السنه وينفي الاقذار washing the head with mallow takes away grime and it is of the sunnah and it drives off filth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 72, NULL, 'Sayingالنُّورَةُ مَشَدَّةٌ لِلْبَدَنِ وَطَهُورٌ لِلْجَسَدِ"The depilatory paste strengthens the body and is a purification for the flesh."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingالنوره مشده للبدن وطهور للجسد the depilatory paste strengthens the body and is a purification for the flesh', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 73, NULL, 'Sayingتَقْلِيمُ الْأَظَافِرِ يَمْنَعُ الدَّاءَ الْأَعْظَمَ وَيَجْلِبُ الرِّزْقَ وَيَدُرُّهُ"Trimming the nails wards off the greatest disease, and draws sustenance and makes it flow."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingتقليم الاظافر يمنع الداء الاعظم ويجلب الرزق ويدره trimming the nails wards off the greatest disease and draws sustenance and makes it flow', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 74, NULL, 'Sayingنَتْفُ الْآبَاطِ يَنْفِي الرَّائِحَةَ الْمُنْكَرَةَ وَهُوَ طَهُورٌ وَهُوَ مِنَ السُّنَّةِ"Plucking the armpits removes the offensive odor; it is a purification, and it is of the Sunnah."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingنتف الاباط ينفي الرايحه المنكره وهو طهور وهو من السنه plucking the armpits removes the offensive odor it is a purification and it is of the sunnah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 75, NULL, 'Sayingغُسْلُ الْأَعْيَادِ طَهُورٌ لِمَنْ طَلَبَ الْحَوَائِجَ بَيْنَ يَدَيِ اللَّهِ عَزَّ وَجَلَّ وَأتِّبَاعُ السُّنَّةِ"Bathing on the feast days is a purification for whoever presents his needs before God, mighty and majestic, and a following of the Sunnah."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingغسل الاعياد طهور لمن طلب الحوايج بين يدي الله عز وجل واتباع السنه bathing on the feast days is a purification for whoever presents his needs before god mighty and majestic and a following of the sunnah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 76, NULL, 'Sayingغَسْلُ الثِّيَابِ يُذْهِبُ بِالْهَمِّ وَيَكْبِتُ الْعَدُوَّ وَهُوَ طَهُورٌ لِلصَّلَاةِ"Washing the garments takes away anxiety and subdues the enemy, and it is a purification for the prayer."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingغسل الثياب يذهب بالهم ويكبت العدو وهو طهور للصلاه washing the garments takes away anxiety and subdues the enemy and it is a purification for the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 77, NULL, 'Sayingلَا تَنْتِفُوا الشَّنَبَ فَاِنَّهُ نُورٍ لِلْمُسْلِمِ"Do not pluck out the mustache, for it is a light for the Muslim."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingلا تنتفوا الشنب فانه نور للمسلم do not pluck out the mustache for it is a light for the muslim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 78, NULL, 'Sayingمَنْ شَابَ فِي رَأْسِهِ شَيْبَةٌ فِي الْإِسْلَامِ كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ"Whoever grows a white hair upon his head while in Islam, it will be a light for him on the Day of Resurrection."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingمن شاب في راسه شيبه في الاسلام كانت له نورا يوم القيامه whoever grows a white hair upon his head while in islam it will be a light for him on the day of resurrection', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 79, NULL, 'Sayingولا يتغوّطنّ أحدكم على الحجة ولا يبل في سطح الهواء ولا في ماء راكد فمن فعل فأصابه شيء فلا يلومنّ الا نفسه فان للماء أهلاً وللهواء أهلاً فإذا بال أحدكم فلا يطمحنّ ببوله ولا يستقبل به الربح"Let none of you relieve himself on the road, nor urinate into the open air or into standing water. Whoever does so and something befalls him, let him blame none but himself — for the water has its folk, and the air has its folk. And when one of you urinates, let him not make his urine splash, and let him not face the wind with it."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingولا يتغوطن احدكم علي الحجه ولا يبل في سطح الهواء ولا في ماء راكد فمن فعل فاصابه شيء فلا يلومن الا نفسه فان للماء اهلا وللهواء اهلا فاذا بال احدكم فلا يطمحن ببوله ولا يستقبل به الربح let none of you relieve himself on the road nor urinate into the open air or into standing water whoever does so and something befalls him let him blame none but himself for the water has its folk and the air has its folk and when one of you urinates let him not make his urine splash and let him not face the wind with it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 80, NULL, 'Sayingولا ينا منّ أحدكم على الحجة ولا على وجهه فمن رأيتموه نام على وجهه فانبهوه"And let none of you sleep on the road, nor upon his face. Whoever you see sleeping upon his face, wake him."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingولا ينا من احدكم علي الحجه ولا علي وجهه فمن رايتموه نام علي وجهه فانبهوه and let none of you sleep on the road nor upon his face whoever you see sleeping upon his face wake him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 81, NULL, 'Sayingتَنَظَّفُوا بِالْمَاءِ مِنَ الرِّيحِ الْمُنْتِنَةِ وَتَعَاهَدُوا أَنْفُسَكُمْ فَاِنَّ اللَّهَ تَعَالَى يُبْغِضُ الْعَبْدَ الْقَاذُورَةَ الَّذِي یَتَأَذَّى بِهِ مَنْ جَلَسَ إِلَيْهِ"Cleanse yourselves of foul odor with water, and take care of your cleanliness, for God Most High hates the filthy servant who offends those who sit near him."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingتنظفوا بالماء من الريح المنتنه وتعاهدوا انفسكم فان الله تعالي يبغض العبد القاذوره الذي يتاذي به من جلس اليه cleanse yourselves of foul odor with water and take care of your cleanliness for god most high hates the filthy servant who offends those who sit near him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 82, NULL, 'Sayingتَنَزَّهُوا عَنْ قُرْبِ الْكِلَابِ فَمَنْ أَصَابَهُ كَلْبٌ جَافٌّ فَلْيَنْضَحْ ثَوْبَهُ بِالْمَاءِ وَاِنْ كَانَ الْكَلْبُ رَطِبًا فَلْيَغْسِلْهُ"Keep yourselves away from dogs. Whoever is touched by a dry dog should sprinkle his garment with water; if the dog was wet, he must wash it."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingتنزهوا عن قرب الكلاب فمن اصابه كلب جاف فلينضح ثوبه بالماء وان كان الكلب رطبا فليغسله keep yourselves away from dogs whoever is touched by a dry dog should sprinkle his garment with water if the dog was wet he must wash it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 83, NULL, 'Sayingاُحِبُّ لِلْمُؤْمِنِ أَنْ يَطَّلِّيَ فِي كُلِّ خَمْسَةَ عَشَرَ يَوْمًا مَرَّةً بِنُورَةٍ"I love for the believer that he anoint himself once every fifteen days with the depilatory paste."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingاحب للمومن ان يطلي في كل خمسه عشر يوما مره بنوره i love for the believer that he anoint himself once every fifteen days with the depilatory paste', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 84, NULL, 'What follows I take from a book of questions and answers: the questions come from the most excellent Sheikh Shimon ibn Muhammad Ghori al-Hindi (رض), and the answers are from our master Badr al-Din, our master Hasan ibn Idris.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'what follows i take from a book of questions and answers the questions come from the most excellent sheikh shimon ibn muhammad ghori al hindi رض and the answers are from our master badr al din our master hasan ibn idris', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 85, NULL, 'Question: What do you say, O one by whom our souls have life, concerning a man who lets the hair of his head grow long and neither combs nor parts it each day? Does his prayer suffer any defect, or not? And how often ought he to comb and part it?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what do you say o one by whom our souls have life concerning a man who lets the hair of his head grow long and neither combs nor parts it each day does his prayer suffer any defect or not and how often ought he to comb and part it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 86, NULL, 'Answer: If he parts it into two halves, there is no defect upon him; yet it is not fitting that he leave it without a parting. If he does so deliberately, in defiance of the ruling, his prayer is void.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer if he parts it into two halves there is no defect upon him yet it is not fitting that he leave it without a parting if he does so deliberately in defiance of the ruling his prayer is void', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 87, NULL, 'Question: What do you say concerning the meaning of the words of Ali (ع):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'question what do you say concerning the meaning of the words of ali ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 88, NULL, 'Sayingمَنْ لَا يُطَهِّرُهُ الْبَحْرُ فَلَا طَهَّرَهُ اللهُ"Whomever the sea does not purify, may God not purify him."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'sayingمن لا يطهره البحر فلا طهره الله whomever the sea does not purify may god not purify him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'major impurity and the cleanliness of things', '9. Major Impurity and the Cleanliness of Things', 89, NULL, 'Answer: Water purifies and is not itself purified. So likewise is the knowledge of the Imam: whomever it does not purify, God does not purify him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 9 major impurity and the cleanliness of things', 'answer water purifies and is not itself purified so likewise is the knowledge of the imam whomever it does not purify god does not purify him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 0, NULL, 'I turn now to the mention of the tooth-stick (السِّوَاك).', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'i turn now to the mention of the tooth stick السواك', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 1, NULL, 'I record what he stated in the book of questions and answers mentioned above, which one of its compilers arranged according to the chapter order of the book دَعَائِمُ الْإِسْلَامِ:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'i record what he stated in the book of questions and answers mentioned above which one of its compilers arranged according to the chapter order of the book دعايم الاسلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 2, NULL, 'Question: What do you say, O you at whose words our souls find rest, concerning the custom of most people of India — that after finishing with the siwak they take a split piece of bamboo cane or something similar and scrape their tongues with it to remove what has gathered there? Is this permissible or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'question what do you say o you at whose words our souls find rest concerning the custom of most people of india that after finishing with the siwak they take a split piece of bamboo cane or something similar and scrape their tongues with it to remove what has gathered there is this permissible or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 3, NULL, 'Answer: The siwak is the mainstay, and there is nothing against them if they do that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'answer the siwak is the mainstay and there is nothing against them if they do that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 4, NULL, 'From another place: one should not clean between the teeth with a stalk that has a knot in it, taken from dried grass. From another: it is disliked for anyone to use the siwak while in a state of janaba — that is, while in the condition of major ritual impurity.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'from another place one should not clean between the teeth with a stalk that has a knot in it taken from dried grass from another it is disliked for anyone to use the siwak while in a state of janaba that is while in the condition of major ritual impurity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 5, NULL, 'From the book شَرْحُ الْأَخْبَارِ: الريحان is every plant of fragrant scent, and the myrtle (اَلْآس) has been singled out for that name. From the book تَأْوِيلُ الدَّعَائِمِ: الريحان in the language means the tips of every sweet-scented plant when its blossom comes forth, and الريحان is a comprehensive name for all fragrant plants; most often, however, the myrtle is singled out for it, since it is the most lasting and the strongest of them all.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'from the book شرح الاخبار الريحان is every plant of fragrant scent and the myrtle الاس has been singled out for that name from the book تاويل الدعايم الريحان in the language means the tips of every sweet scented plant when its blossom comes forth and الريحان is a comprehensive name for all fragrant plants most often however the myrtle is singled out for it since it is the most lasting and the strongest of them all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 6, NULL, 'The Commander of the Faithful, Ali ibn Abi Talib (ع), said in his four hundred points of etiquette:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'the commander of the faithful ali ibn abi talib ع said in his four hundred points of etiquette', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 7, NULL, 'Sayingالسِّوَاكُ مَرْضَاةٌ لِلرَّبِّ عَزَّ وَجَلَّ وَمَطْيَبَةٌ لِلْفَمِ وَهُوَ مِنَ السُّنَّةِ', '', 'السِّوَاكُ مَرْضَاةٌ لِلرَّبِّ عَزَّ وَجَلَّ وَمَطْيَبَةٌ لِلْفَمِ وَهُوَ مِنَ السُّنَّةِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'sayingالسواك مرضاه للرب عز وجل ومطيبه للفم وهو من السنه', 'السواك مرضاه للرب عز وجل ومطيبه للفم وهو من السنه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 8, NULL, 'The tooth-stick is a means of pleasing the Lord, mighty and majestic; it sweetens the mouth, and it belongs to the established practice.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'the tooth stick is a means of pleasing the lord mighty and majestic it sweetens the mouth and it belongs to the established practice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 9, NULL, 'I turn now to the mention of dry purification (اَلتَّيَمُّم), again from the book of questions and answers mentioned above, arranged by one of its compilers according to the chapter order of the book دَعَائِمُ الْإِسْلَامِ.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'i turn now to the mention of dry purification التيمم again from the book of questions and answers mentioned above arranged by one of its compilers according to the chapter order of the book دعايم الاسلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 10, NULL, 'Question: What do you say, O best of those who have urged us to sit in the company of the learned, concerning a smooth rock fixed firmly in the ground: may one perform tayammum on it even when there is no dust on it and no soil is to be found anywhere? And if tayammum on it requires dust, what is the difference between it and any other stone?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'question what do you say o best of those who have urged us to sit in the company of the learned concerning a smooth rock fixed firmly in the ground may one perform tayammum on it even when there is no dust on it and no soil is to be found anywhere and if tayammum on it requires dust what is the difference between it and any other stone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 11, NULL, 'Answer: If dust is on it, he performs tayammum. If there is no dust on it, he does not.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'answer if dust is on it he performs tayammum if there is no dust on it he does not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 12, NULL, 'Question: What does our master say concerning a man who leaves a city for a destination short of the distance that counts as travel, and the time of prayer comes upon him on the road with no water: may he perform tayammum?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'question what does our master say concerning a man who leaves a city for a destination short of the distance that counts as travel and the time of prayer comes upon him on the road with no water may he perform tayammum', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 13, NULL, 'Answer: Tayammum is not permitted to a settled man except for cause. But if he is on a journey, far from water, and cannot perform the ablution before the time lapses — or if going to the water would put his person or his property at risk — he performs tayammum.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'answer tayammum is not permitted to a settled man except for cause but if he is on a journey far from water and cannot perform the ablution before the time lapses or if going to the water would put his person or his property at risk he performs tayammum', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 14, NULL, 'Question: Concerning a man who owes the full washing (اَلْغُسْل) during a night of Ramadan and forgets it until he has set out on a journey: does tayammum suffice him for prayer and for fasting?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'question concerning a man who owes the full washing الغسل during a night of ramadan and forgets it until he has set out on a journey does tayammum suffice him for prayer and for fasting', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 15, NULL, 'Answer: If he forgets the washing until he is already traveling and finds no water, tayammum suffices him for both the prayer and the fast.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'answer if he forgets the washing until he is already traveling and finds no water tayammum suffices him for both the prayer and the fast', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 16, NULL, 'Question: Concerning a man who dies on a journey and water cannot be found?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'question concerning a man who dies on a journey and water cannot be found', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 17, NULL, 'Answer: In that case he is given tayammum. From another: whoever is on a journey and the time comes while water is present, but fears illness for himself if he performs the ablution, performs tayammum and prays.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'answer in that case he is given tayammum from another whoever is on a journey and the time comes while water is present but fears illness for himself if he performs the ablution performs tayammum and prays', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 18, NULL, 'Question: Concerning a traveler who has with him only a little water — enough either to wash the limbs or to cleanse himself after relieving himself: with which does he begin? And if he does not cleanse himself, does the washing suffice him in place of tayammum?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'question concerning a traveler who has with him only a little water enough either to wash the limbs or to cleanse himself after relieving himself with which does he begin and if he does not cleanse himself does the washing suffice him in place of tayammum', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 19, NULL, 'Answer: Our master al-Numan said in the book of purity: if he cleanses himself with stones or with something else and removes what is there, he performs the ablution, since this arises from a cause — and the absence of water is that cause — and there is no call for tayammum.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'answer our master al numan said in the book of purity if he cleanses himself with stones or with something else and removes what is there he performs the ablution since this arises from a cause and the absence of water is that cause and there is no call for tayammum', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 20, NULL, 'Question: Concerning a man settled in town who has an ailment in his private part that prevents him from cleansing himself: if he washes the limbs, is tayammum then obligatory upon him as well?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'question concerning a man settled in town who has an ailment in his private part that prevents him from cleansing himself if he washes the limbs is tayammum then obligatory upon him as well', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 21, NULL, 'Answer: This has already been addressed in the reply to the first question.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'answer this has already been addressed in the reply to the first question', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 22, NULL, 'Question: Concerning a traveler who prays the obligatory prayers with tayammum before their times lapse: if those times pass him by, must he make up the prayer with tayammum?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'question concerning a traveler who prays the obligatory prayers with tayammum before their times lapse if those times pass him by must he make up the prayer with tayammum', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 23, NULL, 'Answer: When there is no water, prayer with tayammum is valid — both the prayer offered in its time and the one made up afterward.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'answer when there is no water prayer with tayammum is valid both the prayer offered in its time and the one made up afterward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 24, NULL, 'From another: the traveler''s wife, if she menstruates and then becomes pure and finds no water, performs tayammum and prays, and it becomes lawful for her husband to have intercourse with her. If a company are traveling and have an imam among them, and he becomes junub, and they have with them only water enough for one man''s ablution, their imam performs tayammum and leads in prayer those of them who have also performed tayammum. If a man is on a journey with only enough water for his ablution, and there is impurity on his garment, he washes the garment with that water, then performs tayammum and prays. If a man becomes junub on a journey and the noon prayer comes, and he has water enough for the ablution but not for the full washing, he performs tayammum and prays without performing the ablution; then when the afternoon prayer comes and that water is still with him, he performs the ablution with it and does not perform tayammum, because he is by then pure from janaba. If a deceased person and one in janaba come together and there is only water enough for a single washing, the one in janaba washes himself and the deceased is given tayammum. Whoever travels with a Christian or Zoroastrian wife, and she menstruates on the road and then becomes pure and finds no water, performs tayammum, and the husband teaches her the tayammum, and he may then go in to her.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'from another the travelers wife if she menstruates and then becomes pure and finds no water performs tayammum and prays and it becomes lawful for her husband to have intercourse with her if a company are traveling and have an imam among them and he becomes junub and they have with them only water enough for one mans ablution their imam performs tayammum and leads in prayer those of them who have also performed tayammum if a man is on a journey with only enough water for his ablution and there is impurity on his garment he washes the garment with that water then performs tayammum and prays if a man becomes junub on a journey and the noon prayer comes and he has water enough for the ablution but not for the full washing he performs tayammum and prays without performing the ablution then when the afternoon prayer comes and that water is still with him he performs the ablution with it and does not perform tayammum because he is by then pure from janaba if a deceased person and one in janaba come together and there is only water enough for a single washing the one in janaba washes himself and the deceased is given tayammum whoever travels with a christian or zoroastrian wife and she menstruates on the road and then becomes pure and finds no water performs tayammum and the husband teaches her the tayammum and he may then go in to her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 25, NULL, 'The same rulings appear in the book مُخْتَصَرُ الْمُصَنَّفِ, with these further points:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'the same rulings appear in the book مختصر المصنف with these further points', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 26, NULL, 'If water is found after the tayammum, the tayammum is broken and the man returns to the state of janaba. So if he has not yet washed and the sunset prayer comes and he has with him only water enough for the ablution and no more, he performs tayammum again; then when the final evening prayer comes and that water is still with him, he performs the ablution with it, since he is by then pure. If an unbeliever accepts Islam and finds no water, he performs tayammum and prays. It is recommended for a man who sleeps in the mosque of the Prophet and is touched by impurity and awakens that he perform tayammum, and that he not pass through the mosque except having performed tayammum, until he leaves it; and likewise within the sanctuary. If a deceased person and one in janaba come together and there is only water enough for a single washing, the one in janaba washes and the deceased is given tayammum. As for the invalid who cannot perform tayammum himself, a sound person performs it for him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'if water is found after the tayammum the tayammum is broken and the man returns to the state of janaba so if he has not yet washed and the sunset prayer comes and he has with him only water enough for the ablution and no more he performs tayammum again then when the final evening prayer comes and that water is still with him he performs the ablution with it since he is by then pure if an unbeliever accepts islam and finds no water he performs tayammum and prays it is recommended for a man who sleeps in the mosque of the prophet and is touched by impurity and awakens that he perform tayammum and that he not pass through the mosque except having performed tayammum until he leaves it and likewise within the sanctuary if a deceased person and one in janaba come together and there is only water enough for a single washing the one in janaba washes and the deceased is given tayammum as for the invalid who cannot perform tayammum himself a sound person performs it for him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 27, NULL, 'From the same book: a man in a state of minor impurity, while settled in the city, performs tayammum for the prayer over the dead if he fears that it will pass him by. And whoever prays with tayammum while there is water in his baggage that he has forgotten — if he remembers and time remains, he performs the ablution and prays; if the time has gone out, what he did suffices him and the prayer he offered with it stands.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'from the same book a man in a state of minor impurity while settled in the city performs tayammum for the prayer over the dead if he fears that it will pass him by and whoever prays with tayammum while there is water in his baggage that he has forgotten if he remembers and time remains he performs the ablution and prays if the time has gone out what he did suffices him and the prayer he offered with it stands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 28, NULL, 'He said in اَلْمُنْتَخَبَةُ:', '', 'اَلْمُنْتَخَبَةُ', NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'he said in المنتخبه', 'المنتخبه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 29, NULL, 'Sayingوَكُلُّ مَنْ لَمْ يَجِدِ التُّرَابَ فَلْيَنْفُضِ اللُّبُودَ وَالثِّيَابَ حتى إذا لم يرى شيئا طار وَلْيَتَيَمَّمْ ذَلِكَ الْغُبَارَ', '', 'وَكُلُّ مَنْ لَمْ يَجِدِ التُّرَابَ فَلْيَنْفُضِ اللُّبُودَ وَالثِّيَابَ حتى إذا لم يرى شيئا طار وَلْيَتَيَمَّمْ ذَلِكَ الْغُبَارَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'sayingوكل من لم يجد التراب فلينفض اللبود والثياب حتي اذا لم يري شييا طار وليتيمم ذلك الغبار', 'وكل من لم يجد التراب فلينفض اللبود والثياب حتي اذا لم يري شييا طار وليتيمم ذلك الغبار');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 30, NULL, 'Whoever finds no earth, let him beat out the felts and the garments; and then, even if he sees nothing fly up, let him take that dust for his dry purification.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'whoever finds no earth let him beat out the felts and the garments and then even if he sees nothing fly up let him take that dust for his dry purification', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 31, NULL, 'He said in the book تَأْوِيلُ الدَّعَائِمِ, concerning a man seized in a crush who cannot get free — that is, cannot reach the water — and the prayer comes upon him: he performs tayammum and prays, and then repeats that prayer when he is able to reach the water and purify himself with it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'he said in the book تاويل الدعايم concerning a man seized in a crush who cannot get free that is cannot reach the water and the prayer comes upon him he performs tayammum and prays and then repeats that prayer when he is able to reach the water and purify himself with it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 32, NULL, 'He said in the book of questions and answers mentioned above: if a woman becomes pure from menstrual blood in the month of Ramadan before sunset and fears harm from the full washing, she may perform tayammum and fast, and she need not make up that day. Likewise, a man who has an emission in his sleep during the month of Ramadan: if he fears illness from washing at night, he performs tayammum and fasts, and he does not make up that fast.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'he said in the book of questions and answers mentioned above if a woman becomes pure from menstrual blood in the month of ramadan before sunset and fears harm from the full washing she may perform tayammum and fast and she need not make up that day likewise a man who has an emission in his sleep during the month of ramadan if he fears illness from washing at night he performs tayammum and fasts and he does not make up that fast', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 33, NULL, 'He said in a book containing legal questions — all of them marvels — another question: What do you say concerning two men who performed tayammum and prayed together in one place because they found no water, and the prayer of one was valid while the prayer of the other was not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'he said in a book containing legal questions all of them marvels another question what do you say concerning two men who performed tayammum and prayed together in one place because they found no water and the prayer of one was valid while the prayer of the other was not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 34, NULL, 'Answer: The case is this: one man said to his companion, "Teach me the tayammum," and the other set about teaching him and striking the earth for him, and they both prayed. The prayer of the one who was taught was valid; the prayer of the teacher was not, because he did not form the intention for himself.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'answer the case is this one man said to his companion teach me the tayammum and the other set about teaching him and striking the earth for him and they both prayed the prayer of the one who was taught was valid the prayer of the teacher was not because he did not form the intention for himself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 35, NULL, 'I turn now to the purity of foods and drinks, drawing on the book of questions and answers mentioned above, which one of its compilers arranged according to the order of the chapters of the book دَعَائِمُ الْإِسْلَامِ.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'i turn now to the purity of foods and drinks drawing on the book of questions and answers mentioned above which one of its compilers arranged according to the order of the chapters of the book دعايم الاسلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 36, NULL, 'Question: What do you say, O you whom God has made a stronghold at whose door even the accursed may hope for refuge, concerning the oil of the neem (النِّيم)? People know that almost all of the neem''s fruit is eaten by crows, so that the stones pass out through their droppings and dry, and people gather them and sell them. Pressers buy those stones, press them, and sell the bitter oil that results, in which no trace of impurity is visible. Is it permitted to sell this oil, to buy it, to burn it for light, and to touch it, or not? Answer: Whatever is not lawful to eat, its dung is impure. It is not lawful to eat such oil, nor to sell it, nor to buy it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'question what do you say o you whom god has made a stronghold at whose door even the accursed may hope for refuge concerning the oil of the neem النيم people know that almost all of the neems fruit is eaten by crows so that the stones pass out through their droppings and dry and people gather them and sell them pressers buy those stones press them and sell the bitter oil that results in which no trace of impurity is visible is it permitted to sell this oil to buy it to burn it for light and to touch it or not answer whatever is not lawful to eat its dung is impure it is not lawful to eat such oil nor to sell it nor to buy it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 37, NULL, 'Question: What do you say, O best of those who have given us sight from the stored treasure of his knowledge, of what our eyes were veiled from, concerning what has come in the book of purity — that there is no harm in the leavings of a menstruating woman, a Jew, a Christian, beasts of prey, and riding animals — while it has also come therein that what a dog has lapped from is impure? How are these two reports to be reconciled? Answer: If there is moisture, it has been defiled and is impure, and there is no harm in selling it nor in buying it, as with the hide of carrion, which it is not lawful to sell. The primary ruling concerns water that is above the limit.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'question what do you say o best of those who have given us sight from the stored treasure of his knowledge of what our eyes were veiled from concerning what has come in the book of purity that there is no harm in the leavings of a menstruating woman a jew a christian beasts of prey and riding animals while it has also come therein that what a dog has lapped from is impure how are these two reports to be reconciled answer if there is moisture it has been defiled and is impure and there is no harm in selling it nor in buying it as with the hide of carrion which it is not lawful to sell the primary ruling concerns water that is above the limit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 38, NULL, 'Question: What does our master, the possessor of all, say concerning honey, clarified butter, olive oil, and sesame oil in which a mouse is found? Is such a substance to be fed to the beasts or buried in the ground? And if soap is made from it, may it be sold in the market and elsewhere, or is it to be given to people without price? Answer: Any liquid in which an animal having flowing blood has died is not to be eaten, and it is not fitting that an animal lawful to eat be fed what is forbidden. There is no harm in making soap from it, but it may not be sold unless the buyer is informed of its corruption. A garment washed with such impure soap must afterward be rinsed with pure water.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'question what does our master the possessor of all say concerning honey clarified butter olive oil and sesame oil in which a mouse is found is such a substance to be fed to the beasts or buried in the ground and if soap is made from it may it be sold in the market and elsewhere or is it to be given to people without price answer any liquid in which an animal having flowing blood has died is not to be eaten and it is not fitting that an animal lawful to eat be fed what is forbidden there is no harm in making soap from it but it may not be sold unless the buyer is informed of its corruption a garment washed with such impure soap must afterward be rinsed with pure water', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 39, NULL, 'From the book of reports: such a substance is fed to dogs and to beasts whose flesh is not eaten. And from it: if a dead mouse is found in a cooking pot, the broth is poured away, the meat is washed, and it is eaten. From another: food from which a single grain of mouse droppings has been removed is eaten; likewise if there are two. But if three grains come out of it, it is not permitted as food for a human being, nor for an animal whose milk is drunk.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'from the book of reports such a substance is fed to dogs and to beasts whose flesh is not eaten and from it if a dead mouse is found in a cooking pot the broth is poured away the meat is washed and it is eaten from another food from which a single grain of mouse droppings has been removed is eaten likewise if there are two but if three grains come out of it it is not permitted as food for a human being nor for an animal whose milk is drunk', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 40, NULL, 'Question: What do you say concerning betel that is chewed with a small amount of lime (اَلنُّورَة) put into it? Is that permitted — may it be eaten or not? Answer: If the lime is a small amount that does no harm to a person, there is no objection to eating it along with the rest. Similarly, drinking water may contain a small amount of earth, and that is not forbidden unless it is gross and would harm the one who takes it. God and His friends know best.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'question what do you say concerning betel that is chewed with a small amount of lime النوره put into it is that permitted may it be eaten or not answer if the lime is a small amount that does no harm to a person there is no objection to eating it along with the rest similarly drinking water may contain a small amount of earth and that is not forbidden unless it is gross and would harm the one who takes it god and his friends know best', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 41, NULL, 'Question: Concerning the clarified butter, sesame oil, sugar, honey, and other such foodstuffs held by unbelievers, which they sell in the markets of the Muslims: is it lawful to eat them or not? Answer: And from God is the granting of success. The slaughtered animals of unbelievers were forbidden only because they do not pronounce the name of God over them and do not turn them toward the qibla. As for the food and moist provisions they possess: what they have touched, they have defiled, and what they have not touched with their hands and their impure implements, there is no harm in its being sold, bought, eaten, and used as a relish. Yet their handiwork is hardly ever free of this, since they are impure and handle their implements while these are wet. The obligation, therefore, is to avoid what they have prepared if something other than it can be found. If there is need, then nothing is forbidden except their slaughtered animals, and their moisture is impure. If something falls upon a garment from the relish prepared by the people of association, or from moist food, and it is known that they defiled it, then whatever of that is on the garment or on a person''s body is washed.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'question concerning the clarified butter sesame oil sugar honey and other such foodstuffs held by unbelievers which they sell in the markets of the muslims is it lawful to eat them or not answer and from god is the granting of success the slaughtered animals of unbelievers were forbidden only because they do not pronounce the name of god over them and do not turn them toward the qibla as for the food and moist provisions they possess what they have touched they have defiled and what they have not touched with their hands and their impure implements there is no harm in its being sold bought eaten and used as a relish yet their handiwork is hardly ever free of this since they are impure and handle their implements while these are wet the obligation therefore is to avoid what they have prepared if something other than it can be found if there is need then nothing is forbidden except their slaughtered animals and their moisture is impure if something falls upon a garment from the relish prepared by the people of association or from moist food and it is known that they defiled it then whatever of that is on the garment or on a persons body is washed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 42, NULL, 'From another: if the leavings of a Jew, a Christian, a Magian, or a cat fall into a small vessel, purification with it remains valid so long as no saliva is apparent.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'from another if the leavings of a jew a christian a magian or a cat fall into a small vessel purification with it remains valid so long as no saliva is apparent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 43, NULL, 'He said in the questions of Sheikh Hasan ibn Nuh (نُوح) to our master Husayn (حُسَيْن) ibn Idris, and his answers to him: as for the slaughtered animals of the People of the Book, if a Muslim has observed that they turned them toward the qibla and pronounced the name of God over them, they are eaten. As for the rest of their food, it is lawful by the text of the Noble Book; but if they have touched it with their moisture, it becomes impure. And God knows best.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'he said in the questions of sheikh hasan ibn nuh نوح to our master husayn حسين ibn idris and his answers to him as for the slaughtered animals of the people of the book if a muslim has observed that they turned them toward the qibla and pronounced the name of god over them they are eaten as for the rest of their food it is lawful by the text of the noble book but if they have touched it with their moisture it becomes impure and god knows best', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'tooth-stick, dust, and the purity of food', '10. Tooth-Stick, Dust, and the Purity of Food', 44, NULL, 'He said in the brief legal discourse whose questions are from Sheikh Hasan al-Hindi and whose answers are from the masters of Yemen: eating the cooking of a serving girl who is not careful about ritual purity is permitted.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 10 tooth stick dust and the purity of food', 'he said in the brief legal discourse whose questions are from sheikh hasan al hindi and whose answers are from the masters of yemen eating the cooking of a serving girl who is not careful about ritual purity is permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 0, NULL, 'I turn now to the matters of cleanliness and the purifications of the natural disposition. I quote first from the book of questions and answers already mentioned, which its compiler arranged according to the order of the chapters of the book Daaim al-Islam.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'i turn now to the matters of cleanliness and the purifications of the natural disposition i quote first from the book of questions and answers already mentioned which its compiler arranged according to the order of the chapters of the book daaim al islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 1, NULL, 'Question: What do you say, O diver into the current of the sciences, concerning what has come in the Shariah — that no uncircumcised man is left so in Islam until he is circumcised, even if he reaches eighty years of age? So, our master, if a woman grows old and has still not undergone the circumcision of girls (الْخَفْض), is she to be left without it or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'question what do you say o diver into the current of the sciences concerning what has come in the shariah that no uncircumcised man is left so in islam until he is circumcised even if he reaches eighty years of age so our master if a woman grows old and has still not undergone the circumcision of girls الخفض is she to be left without it or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 2, NULL, 'Answer: She undergoes it and is not left without it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'answer she undergoes it and is not left without it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 3, NULL, 'Question: What do you say, O our master, our support, and our pillar, concerning the custom of the lands of India — that men and women part the hair of the head toward the middle and not toward the nape? Does this suffice them as a parting or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'question what do you say o our master our support and our pillar concerning the custom of the lands of india that men and women part the hair of the head toward the middle and not toward the nape does this suffice them as a parting or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 4, NULL, 'Answer: Let the hair be parted in two halves, from the front of the head to its back, and let no one deliberately neglect this.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'answer let the hair be parted in two halves from the front of the head to its back and let no one deliberately neglect this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 5, NULL, 'Question: What do you say, O best of those from whose direction we hope the gates of good will be opened to us, concerning the hair of the beard when some of it is long and some short, and the bearded man shortens part of it so that it is made even, which adds to his comeliness? Is there anything against him in that or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'question what do you say o best of those from whose direction we hope the gates of good will be opened to us concerning the hair of the beard when some of it is long and some short and the bearded man shortens part of it so that it is made even which adds to his comeliness is there anything against him in that or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 6, NULL, 'Answer: He has been permitted to trim from the two sides of the beard (الْعَارِضِينَ). Other than that, it is not permitted to trim from it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'answer he has been permitted to trim from the two sides of the beard العارضين other than that it is not permitted to trim from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 7, NULL, 'Question: What do you say, O one whom God has made a fountainhead of honor for the people of obedience to God, concerning the hair of the human body apart from that whose removal has been commanded? Is there anything against a man if he shaves it, shortens it, or plucks it?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'question what do you say o one whom god has made a fountainhead of honor for the people of obedience to god concerning the hair of the human body apart from that whose removal has been commanded is there anything against a man if he shaves it shortens it or plucks it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 8, NULL, 'Answer: There is nothing against him in that, except the beard — he removes nothing from it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'answer there is nothing against him in that except the beard he removes nothing from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 9, NULL, 'Question: What do you say, O one whom God has made a physician who heals the souls of His friends of every ailment, concerning a man and his wife combing their hair with a single comb, given that some of the people of India dislike this?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'question what do you say o one whom god has made a physician who heals the souls of his friends of every ailment concerning a man and his wife combing their hair with a single comb given that some of the people of india dislike this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 10, NULL, 'Answer: There is no reliance to be placed upon that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'answer there is no reliance to be placed upon that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 11, NULL, 'Question: What do you say, O best of those who have driven from the eyes of our insight, by the light of his knowledge, every blindness, concerning what has come in the book of purity — that the first to be circumcised was Ibrahim (ع) at the age of eighty? Our master, is the intent, in the outward sense, that this ruling and what follows it had not been sent down before that, or not? May I be your ransom.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'question what do you say o best of those who have driven from the eyes of our insight by the light of his knowledge every blindness concerning what has come in the book of purity that the first to be circumcised was ibrahim ع at the age of eighty our master is the intent in the outward sense that this ruling and what follows it had not been sent down before that or not may i be your ransom', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 12, NULL, 'Answer: This is established in the outward sense, for Ibrahim (ع) was not commanded with purification until he reached the age of eighty.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'answer this is established in the outward sense for ibrahim ع was not commanded with purification until he reached the age of eighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 13, NULL, 'Question: What do you say concerning what has come in the book of purity, that Ali (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'question what do you say concerning what has come in the book of purity that ali ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 14, NULL, 'Sayingيَا مَعْشَرَ النِّسَاءِ إِذَا خَفَضْتُنَّ بَنَاتِكُنَّ فَلَا تَسْتَقْصِيهِ وَلْتَتْرُكْ بِهِ شَيْئًا فَهُوَ أَحْسَنُ لِلْوَجْهِ وَأَحْظَى لِلزَّوْجِ"O company of women, when you circumcise your daughters, do not take it to the utmost, and let something of it be left, for that is better for the face and more favored by the husband."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingيا معشر النساء اذا خفضتن بناتكن فلا تستقصيه ولتترك به شييا فهو احسن للوجه واحظي للزوج o company of women when you circumcise your daughters do not take it to the utmost and let something of it be left for that is better for the face and more favored by the husband', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 15, NULL, 'Our master, is there sin upon them if they take it to the utmost, and what is the meaning of his words, that it is better for the face?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'our master is there sin upon them if they take it to the utmost and what is the meaning of his words that it is better for the face', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 16, NULL, 'Answer: One acts upon what has been mentioned, and it is not taken to the utmost, for that is better for the husband''s inclination toward her.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'answer one acts upon what has been mentioned and it is not taken to the utmost for that is better for the husbands inclination toward her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 17, NULL, 'Question: What do you say, O best of those whom God has made a storehouse for the secrets of His friends, concerning the saying of the Prophet:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'question what do you say o best of those whom god has made a storehouse for the secrets of his friends concerning the saying of the prophet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 18, NULL, 'Sayingلَيْسَ لِامْرَأَةٍ حَاضَتْ أَنْ تَتَّخِذَ قُصَّةً وَلَا جُمَّةً"It is not for a woman who has begun to menstruate to take up a qassa or a jumma."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingليس لامراه حاضت ان تتخذ قصه ولا جمه it is not for a woman who has begun to menstruate to take up a qassa or a jumma', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 19, NULL, 'Our master, may I be your ransom, what is its meaning?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'our master may i be your ransom what is its meaning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 20, NULL, 'Answer: The jumma (الجمّة) is the plaiting of hair from the side locks to the nape. The qassa (القصّة) is when the hair of the head is cut, leaving about a quarter of it at the front. As for the qunzua (الْقُنْزُعَة), it is when the hair is gathered with certain portions left standing up — and that, too, is forbidden.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'answer the jumma الجمه is the plaiting of hair from the side locks to the nape the qassa القصه is when the hair of the head is cut leaving about a quarter of it at the front as for the qunzua القنزعه it is when the hair is gathered with certain portions left standing up and that too is forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 21, NULL, 'Question: What do you say, O sea of the sciences, concerning this: most women of the people of India engrave their palms and feet with henna for adornment, and some dye their teeth with a red preparation or something else, likewise for adornment — yet the Shariah has forbidden the engraving of dye. What is their condition?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'question what do you say o sea of the sciences concerning this most women of the people of india engrave their palms and feet with henna for adornment and some dye their teeth with a red preparation or something else likewise for adornment yet the shariah has forbidden the engraving of dye what is their condition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 22, NULL, 'Answer: The engraving of dye has indeed been forbidden. As for the teeth, there is no harm in dyeing them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'answer the engraving of dye has indeed been forbidden as for the teeth there is no harm in dyeing them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 23, NULL, 'Question: What does our master say concerning a man who applies henna to his hands and feet for the sake of adornment and not for any benefit? Is that permitted or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'question what does our master say concerning a man who applies henna to his hands and feet for the sake of adornment and not for any benefit is that permitted or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 24, NULL, 'Answer: It is not fitting for a man to apply henna for adornment. Women are commanded to use it; for a man to leave it when there is no cause is better. Yet there is no sin upon one who does it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'answer it is not fitting for a man to apply henna for adornment women are commanded to use it for a man to leave it when there is no cause is better yet there is no sin upon one who does it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 25, NULL, 'Question: What do you say, O treasury of the jewels of wisdom, concerning a man or woman whose teeth are uneven — some long and some short — and who levels them by filing with a stone or with iron or with something else, as an increase in comeliness? Is there sin in that or not? Favor us with a satisfying answer; may God make us your ransom.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'question what do you say o treasury of the jewels of wisdom concerning a man or woman whose teeth are uneven some long and some short and who levels them by filing with a stone or with iron or with something else as an increase in comeliness is there sin in that or not favor us with a satisfying answer may god make us your ransom', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 26, NULL, 'Answer: There is no harm in that for women.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'answer there is no harm in that for women', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 27, NULL, 'Question: What do you say, O sea of hopes, concerning this: the women of India pierce their own ears and the ears of their infant daughters, and keep the piercings open as far as they are able, so as to wear ornaments. Is there anything against them in that or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'question what do you say o sea of hopes concerning this the women of india pierce their own ears and the ears of their infant daughters and keep the piercings open as far as they are able so as to wear ornaments is there anything against them in that or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 28, NULL, 'Answer: There is no harm in that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'answer there is no harm in that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 29, NULL, 'Question: What do you say, O one by whom our souls have life, concerning a man who lets the hair of his head be, neither combing it nor parting it each day? Does deficiency enter into his prayer or not? And how often should he comb it and part it?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'question what do you say o one by whom our souls have life concerning a man who lets the hair of his head be neither combing it nor parting it each day does deficiency enter into his prayer or not and how often should he comb it and part it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 30, NULL, 'Answer: If it is in two halves, there is no deficiency upon him. He should not leave it without a parting; and if he does so deliberately in defiance of the ruling, his prayer is corrupted.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'answer if it is in two halves there is no deficiency upon him he should not leave it without a parting and if he does so deliberately in defiance of the ruling his prayer is corrupted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 31, NULL, 'Question: What do you say, O dwelling place of all who come to him out of perplexity, concerning combing the hair on the night of Friday, for most of the people of India hold that leaving it is a binding necessity?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'question what do you say o dwelling place of all who come to him out of perplexity concerning combing the hair on the night of friday for most of the people of india hold that leaving it is a binding necessity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 32, NULL, 'Answer: No reliance is to be placed upon that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'answer no reliance is to be placed upon that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 33, NULL, 'Question: What does our master say, may God perpetuate his elevation, concerning what has been mentioned in the Shariah — that the uncircumcised is not left so in Islam until he is circumcised? Is he circumcised after his death if he was a child, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'question what does our master say may god perpetuate his elevation concerning what has been mentioned in the shariah that the uncircumcised is not left so in islam until he is circumcised is he circumcised after his death if he was a child or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 34, NULL, 'Answer: The preferred practice of the sunna is that he be circumcised after his death.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'answer the preferred practice of the sunna is that he be circumcised after his death', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 35, NULL, 'Another has said: the prayer of a woman who has not undergone the circumcision of girls is valid, as is intercourse with her, and likewise for the man; but the sunna is that one hasten to it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'another has said the prayer of a woman who has not undergone the circumcision of girls is valid as is intercourse with her and likewise for the man but the sunna is that one hasten to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 36, NULL, 'From the answer of our master Qadi al-Numan, may God sanctify his soul, to one who questioned him, namely the governor of his districts, al-Khattab ibn Wasim: You asked about a man found to be uncircumcised, who had married a woman and fathered children by her and had not been circumcised. It is upon him to be circumcised, for the uncircumcised is not left so in Islam, even if he reaches eighty years of age — unless he was born circumcised, for it has come down that some of the prophets (عَلَيْهِمُ السَّلَامُ) were born in that state. If the glans, or most of it, is exposed, he is not compelled to circumcision; and it is recommended, if he is young, that the skin be drawn back and whatever remains of it over the glans be cut away.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'from the answer of our master qadi al numan may god sanctify his soul to one who questioned him namely the governor of his districts al khattab ibn wasim you asked about a man found to be uncircumcised who had married a woman and fathered children by her and had not been circumcised it is upon him to be circumcised for the uncircumcised is not left so in islam even if he reaches eighty years of age unless he was born circumcised for it has come down that some of the prophets عليهم السلام were born in that state if the glans or most of it is exposed he is not compelled to circumcision and it is recommended if he is young that the skin be drawn back and whatever remains of it over the glans be cut away', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 37, NULL, 'Our master and mawla Jafar ibn Sulayman, may God exalt his sanctity and grant us his intercession, wrote in his noble letter which he named السَّيْفُ الْأَقْطَعُ فِي إِبْطَالِ الْبِدَعِ, by which he counseled his people and roused those among them who had grown heedless and long asleep, among the people of the Island of Yemen while he dwelt and settled there:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'our master and mawla jafar ibn sulayman may god exalt his sanctity and grant us his intercession wrote in his noble letter which he named السيف الاقطع في ابطال البدع by which he counseled his people and roused those among them who had grown heedless and long asleep among the people of the island of yemen while he dwelt and settled there', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 38, NULL, 'Section: Among these matters is what we have come to learn — that some of the womenfolk among your women, especially those bound by covenant among them, crop the hair of their heads by shaving, as men shave their heads. This, together with what we mentioned first, belongs to the contrary and inverted order of things: for that was something with which faces and heads are adorned, and this is something by which heads and faces are disfigured. When one of you reflects upon this, the aspects of the matter become plain to him. God, glorified and exalted, has placed the adornment of men in the hair of their beards, in its combing and its grooming, and the adornment of women in the hair of their heads, in its combing and its lengthening. As for hair, it has come down concerning it, in what has reached us of the prophetic reports, that it is one of the two beauties. So a woman''s shaving of it and the cropping of her head is nothing but a disfigurement of her pleasing form. The Prophet has said concerning this that which removes the rust from hearts, where he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'section among these matters is what we have come to learn that some of the womenfolk among your women especially those bound by covenant among them crop the hair of their heads by shaving as men shave their heads this together with what we mentioned first belongs to the contrary and inverted order of things for that was something with which faces and heads are adorned and this is something by which heads and faces are disfigured when one of you reflects upon this the aspects of the matter become plain to him god glorified and exalted has placed the adornment of men in the hair of their beards in its combing and its grooming and the adornment of women in the hair of their heads in its combing and its lengthening as for hair it has come down concerning it in what has reached us of the prophetic reports that it is one of the two beauties so a womans shaving of it and the cropping of her head is nothing but a disfigurement of her pleasing form the prophet has said concerning this that which removes the rust from hearts where he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 39, NULL, 'Sayingإِذَا أَرَادَ أَحَدُكُمْ أَنْ يَتَزَوَّجَ امْرَأَةً فَيَسْأَلُ عَنْ شَعْرِهَا كَمَا يَسْأَلُ عَنْ وَجْهِهَا فَاِنَّ الشَّعْرَ أَحَدُ الْجَمَالَيْنِ"When one of you wishes to marry a woman, let him ask about her hair as he asks about her face, for the hair is one of the two beauties."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingاذا اراد احدكم ان يتزوج امراه فيسال عن شعرها كما يسال عن وجهها فان الشعر احد الجمالين when one of you wishes to marry a woman let him ask about her hair as he asks about her face for the hair is one of the two beauties', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 40, NULL, 'And from him:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'and from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 41, NULL, 'Sayingاَلشَّعْرُ الْحَسَنُ مِنْ كِسْوَةِ اللهِ فَمَنْ عَرَّى جِسْمَهُ مِنْ كِسْوَتِهِ لَا سِيَّمَا كِسْوَةِ رَبِّهِ سُبْحَانَهُ الَّتِي كَسَاهُ إِيَّاهَا فَقَدْ شَوَّهَ بِصُورَتِهِ وَمَنْ شَوَّهَ بِصُورَتِهِ شَاهَ فِي دُنْيَاهُ وَآخِرَتِهِ', '', 'اَلشَّعْرُ الْحَسَنُ مِنْ كِسْوَةِ اللهِ فَمَنْ عَرَّى جِسْمَهُ مِنْ كِسْوَتِهِ لَا سِيَّمَا كِسْوَةِ رَبِّهِ سُبْحَانَهُ الَّتِي كَسَاهُ إِيَّاهَا فَقَدْ شَوَّهَ بِصُورَتِهِ وَمَنْ شَوَّهَ بِصُورَتِهِ شَاهَ فِي دُنْيَاهُ وَآخِرَتِهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingالشعر الحسن من كسوه الله فمن عري جسمه من كسوته لا سيما كسوه ربه سبحانه التي كساه اياها فقد شوه بصورته ومن شوه بصورته شاه في دنياه واخرته', 'الشعر الحسن من كسوه الله فمن عري جسمه من كسوته لا سيما كسوه ربه سبحانه التي كساه اياها فقد شوه بصورته ومن شوه بصورته شاه في دنياه واخرته');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 42, NULL, 'I marvel at those who have declared this permissible and made it a rule unto themselves, and equally at those who have raised no prohibition against it and offered no restraint — all the more so when every one of them has learned what the noble book Daaim al-Islam contains regarding the hair of women''s heads, a passage that clearly indicates the prohibition of shaving it, both for the people of the guiding dawa and for others. Its author, may God sanctify his soul, says:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'i marvel at those who have declared this permissible and made it a rule unto themselves and equally at those who have raised no prohibition against it and offered no restraint all the more so when every one of them has learned what the noble book daaim al islam contains regarding the hair of womens heads a passage that clearly indicates the prohibition of shaving it both for the people of the guiding dawa and for others its author may god sanctify his soul says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 43, NULL, 'Sayingوقالوا يعني الأئمة من أهل بيت النبوة عَلَيْهِمُ السَّلَامُ في المرأة إذا تطهرت إنها تنقض شعرها الا أن تكون تعلم أن الماء يصل إلى بشرة رأسها ويبل شعرها كله وذلك أن تكون أظفار شعرها رخوة', '', 'وقالوا يعني الأئمة من أهل بيت النبوة عَلَيْهِمُ السَّلَامُ في المرأة إذا تطهرت إنها تنقض شعرها الا أن تكون تعلم أن الماء يصل إلى بشرة رأسها ويبل شعرها كله وذلك أن تكون أظفار شعرها رخوة', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingوقالوا يعني الايمه من اهل بيت النبوه عليهم السلام في المراه اذا تطهرت انها تنقض شعرها الا ان تكون تعلم ان الماء يصل الي بشره راسها ويبل شعرها كله وذلك ان تكون اظفار شعرها رخوه', 'وقالوا يعني الايمه من اهل بيت النبوه عليهم السلام في المراه اذا تطهرت انها تنقض شعرها الا ان تكون تعلم ان الماء يصل الي بشره راسها ويبل شعرها كله وذلك ان تكون اظفار شعرها رخوه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 44, NULL, 'He also wrote on this topic in discussing the shaving and trimming of hair upon release from ihram — for men and for women — the distinction between them in that matter, and the application of the pure Shariah''s laws upon their proper foundation. He reported from Ali (ع) that he said, concerning the bald man:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'he also wrote on this topic in discussing the shaving and trimming of hair upon release from ihram for men and for women the distinction between them in that matter and the application of the pure shariahs laws upon their proper foundation he reported from ali ع that he said concerning the bald man', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 45, NULL, 'Sayingيَمُرُّ الْمُوسَي عَلَى رَأْسِهِ"The razor is passed over his head."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingيمر الموسي علي راسه the razor is passed over his head', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 46, NULL, 'And from him (ع):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'and from him ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 47, NULL, 'Sayingإِذَا حَلَّتِ الْمَرْأَةُ مِنْ إِحْرَامِهَا أَخَذَتْ مِنْ أَطْرَافِ قُرُونِ رَأْسِهَا"When the woman is released from her ihram, she takes from the ends of the plaits of her head."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingاذا حلت المراه من احرامها اخذت من اطراف قرون راسها when the woman is released from her ihram she takes from the ends of the plaits of her head', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 48, NULL, 'And he said also, may God sanctify his soul:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'and he said also may god sanctify his soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 49, NULL, 'Sayingوَقَدْ ذَكَرْنَا أَنَّ الْأَقْرَعَ وَالْأَصْلَعَ يُمِرَّانِ الْمُوسَي عَلَى رَأْسَيْهِمَا وَالْمَرْأَةُ تُقَصِّرُ إِذَا حَلَّتْ مِنَ الْإِحْرَامِ تَقْطَعُ شَيْئًا مِنْ أَطْرَافِ شَعْرِهَا وَلَا تَحْلِقُهُ وَلَا شَيْئًا مِنْهُ', '', 'وَقَدْ ذَكَرْنَا أَنَّ الْأَقْرَعَ وَالْأَصْلَعَ يُمِرَّانِ الْمُوسَي عَلَى رَأْسَيْهِمَا وَالْمَرْأَةُ تُقَصِّرُ إِذَا حَلَّتْ مِنَ الْإِحْرَامِ تَقْطَعُ شَيْئًا مِنْ أَطْرَافِ شَعْرِهَا وَلَا تَحْلِقُهُ وَلَا شَيْئًا مِنْهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingوقد ذكرنا ان الاقرع والاصلع يمران الموسي علي راسيهما والمراه تقصر اذا حلت من الاحرام تقطع شييا من اطراف شعرها ولا تحلقه ولا شييا منه', 'وقد ذكرنا ان الاقرع والاصلع يمران الموسي علي راسيهما والمراه تقصر اذا حلت من الاحرام تقطع شييا من اطراف شعرها ولا تحلقه ولا شييا منه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 50, NULL, 'We count this saying of his among the clearest proofs that women are forbidden from shaving their hair — whether a little or a great deal — for he forbade them that very act in the context of their release from ihram, with an emphatic prohibition that admits no ambiguity of any kind, large or small. Whoever follows this path has followed the way of right guidance and has kept misfortune from himself.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'we count this saying of his among the clearest proofs that women are forbidden from shaving their hair whether a little or a great deal for he forbade them that very act in the context of their release from ihram with an emphatic prohibition that admits no ambiguity of any kind large or small whoever follows this path has followed the way of right guidance and has kept misfortune from himself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 51, NULL, 'Sayingوَمَنْ يَرْغَبُ عَنْ مِلَّةِ إِبْرَاهِيمَ اِلَّا مَنْ سَفِهَ نَفْسَهُ"And who turns away from the creed of Ibrahim except one who has made a fool of himself?"', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingومن يرغب عن مله ابراهيم الا من سفه نفسه and who turns away from the creed of ibrahim except one who has made a fool of himself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 52, NULL, 'Then he said, concerning a matter of the same kind:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'then he said concerning a matter of the same kind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 53, NULL, 'Section: Among these matters is what we have come to learn: that the womenfolk among you, entirely — including those who do not shave their hair — hold that they must shave the edges of their heads around the crown, and shave the temples likewise. This is something with which God is not pleased in the woman who does it; indeed, it is among the things that cast them into destruction. This follows from what has already been cited from the saying of our master Qadi al-Numan ibn Muhammad, set down above — that the man with scalp disease and the bald man pass the razor over their heads, and that the woman shortens her hair when she is released from ihram, cutting something from the ends of her hair and shaving neither it nor anything of it. For if it is not permissible for women, upon their release from ihram, to shave the ends of the hair of their heads — nor anything of it, ever — but rather they cut from it only what they cut, then such shaving is never permissible as a standing custom, and its practice leads to no guidance. Whoever among them contravenes this has contravened the marks of the upright religion and has pulled down its foundation; she has turned away from the creed of Ibrahim, and none turns away from it except one who has made a fool of himself. Nothing is incumbent upon us but this kind of instruction for the people of religion, because of the word of God, glorified and exalted:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'section among these matters is what we have come to learn that the womenfolk among you entirely including those who do not shave their hair hold that they must shave the edges of their heads around the crown and shave the temples likewise this is something with which god is not pleased in the woman who does it indeed it is among the things that cast them into destruction this follows from what has already been cited from the saying of our master qadi al numan ibn muhammad set down above that the man with scalp disease and the bald man pass the razor over their heads and that the woman shortens her hair when she is released from ihram cutting something from the ends of her hair and shaving neither it nor anything of it for if it is not permissible for women upon their release from ihram to shave the ends of the hair of their heads nor anything of it ever but rather they cut from it only what they cut then such shaving is never permissible as a standing custom and its practice leads to no guidance whoever among them contravenes this has contravened the marks of the upright religion and has pulled down its foundation she has turned away from the creed of ibrahim and none turns away from it except one who has made a fool of himself nothing is incumbent upon us but this kind of instruction for the people of religion because of the word of god glorified and exalted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 54, NULL, 'An-Nur: 54وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَغُ ٱلْمُبِينُ"The Messenger has no duty but clear delivery of the message."', '', NULL, 'An-Nur: 54', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'an nur 54وما علي الرسول الا البلغ المبين the messenger has no duty but clear delivery of the message', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 55, NULL, 'Then he said, concerning the circumcision of girls:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'then he said concerning the circumcision of girls', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 56, NULL, 'Section: Among these matters also is what we have come to learn: that you hasten the circumcision of your girls in the days falling short of ten, or beyond that up to a limit of forty days — which is the outermost term among your elite and common alike. That is contrary to the Shariah of the Prophet and to the religion of Islam, and contrary to what our master Qadi al-Numan ibn Muhammad set down concerning it in the noble book Daaim al-Islam, reporting it from your mawla the Commander of the Faithful, Ali ibn Abi Talib (ع), where he stated it with the clearest exposition; and from him (ع) that he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'section among these matters also is what we have come to learn that you hasten the circumcision of your girls in the days falling short of ten or beyond that up to a limit of forty days which is the outermost term among your elite and common alike that is contrary to the shariah of the prophet and to the religion of islam and contrary to what our master qadi al numan ibn muhammad set down concerning it in the noble book daaim al islam reporting it from your mawla the commander of the faithful ali ibn abi talib ع where he stated it with the clearest exposition and from him ع that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 57, NULL, 'Sayingأَسْرِعُوا بِخِتَانِ أَوْلَادِكُمْ فَأِنَّهُ أَطْهَرُ لَهُمْ"Hasten the circumcision of your children, for it is purer for them."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingاسرعوا بختان اولادكم فانه اطهر لهم hasten the circumcision of your children for it is purer for them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 58, NULL, 'And he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 59, NULL, 'Sayingلَا تَخْفِضِ الْجَارِيَةَ دُونَ أَنْ تَبْلُغَ سَبْعَ سِنِينَ"The girl is not circumcised before she reaches seven years."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingلا تخفض الجاريه دون ان تبلغ سبع سنين the girl is not circumcised before she reaches seven years', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 60, NULL, 'This is a clear prohibition from the one who summons to guidance, and it may never be transgressed. It belongs to the firm limits of God, blessed be His names.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'this is a clear prohibition from the one who summons to guidance and it may never be transgressed it belongs to the firm limits of god blessed be his names', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 61, NULL, 'Sayingوَمَنْ يَتَعَدَّ حُدُودَ فَقَدْ ظَلَمَ نَفْسَهُ"Whoever transgresses the limits has wronged himself."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingومن يتعد حدود فقد ظلم نفسه whoever transgresses the limits has wronged himself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 62, NULL, 'We have further learned, in this matter, that at the time of the circumcision of girls, members of the household and neighbors are gathered together, hospitality is prepared, and the forbidden prayer is performed for it with the call to prayer and the summons. People then spread word of the circumcision, so that near and far, close neighbor and distant, all come to hear of it. None of this has any place in that practice. Such ceremony belongs only to the purification of male children. The circumcision of girls is to be carried out in concealment, known to no one except the girl herself, the woman who performs it, and a few of the women of the household. Whoever makes that affair public has offended against the canons of his religion — and offended again. This belongs to the chapter of modesty, of which the Prophet said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'we have further learned in this matter that at the time of the circumcision of girls members of the household and neighbors are gathered together hospitality is prepared and the forbidden prayer is performed for it with the call to prayer and the summons people then spread word of the circumcision so that near and far close neighbor and distant all come to hear of it none of this has any place in that practice such ceremony belongs only to the purification of male children the circumcision of girls is to be carried out in concealment known to no one except the girl herself the woman who performs it and a few of the women of the household whoever makes that affair public has offended against the canons of his religion and offended again this belongs to the chapter of modesty of which the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 63, NULL, 'Sayingاَلْحَيَاءُ مِنَ الْإِيمَانِ وَمَنْ لَا حَيَاءَ لَهُ لَا دِينَ لَهُ', '', 'اَلْحَيَاءُ مِنَ الْإِيمَانِ وَمَنْ لَا حَيَاءَ لَهُ لَا دِينَ لَهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingالحياء من الايمان ومن لا حياء له لا دين له', 'الحياء من الايمان ومن لا حياء له لا دين له');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 64, NULL, 'By the same measure, the deliberate deferral of girls'' circumcision carries a meaning — one among the meanings the Mighty Creator intends in the affairs of His precious religion. His will may not be contravened in this matter, nor His command transgressed in what He has forbidden — glorified be He — in any forbidden matter. This holds in all matters without exception, in their branches and their roots alike. Every sensible matter has an intelligible counterpart set opposite it, and every outward likeness holds within it that which is likened. Whoever contravenes the established practice in this has nullified it and damaged the road and its passages — and that is never permissible, as the friends of God (عَلَيْهِمُ السَّلَامُ), the friends of their ages, have indicated and by which they have given warning. God, glorified and exalted, says concerning this:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'by the same measure the deliberate deferral of girls circumcision carries a meaning one among the meanings the mighty creator intends in the affairs of his precious religion his will may not be contravened in this matter nor his command transgressed in what he has forbidden glorified be he in any forbidden matter this holds in all matters without exception in their branches and their roots alike every sensible matter has an intelligible counterpart set opposite it and every outward likeness holds within it that which is likened whoever contravenes the established practice in this has nullified it and damaged the road and its passages and that is never permissible as the friends of god عليهم السلام the friends of their ages have indicated and by which they have given warning god glorified and exalted says concerning this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 65, NULL, 'Sayingمَٓا أَتَاكُمُ الرَّسُولُ فَخُذُوهُ مَٓا نَهَاكُمْ عَنْهُ فَانْتَهُوا"Whatever the Messenger gives you, take it; and whatever he forbids you, abstain from it."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingما اتاكم الرسول فخذوه ما نهاكم عنه فانتهوا whatever the messenger gives you take it and whatever he forbids you abstain from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 66, NULL, 'Then our master Jafar said, concerning the purification of children:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'then our master jafar said concerning the purification of children', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 67, NULL, 'Section: Among these matters is also what has become known — the delay practiced by most of you in the purification of your male children, whose hastening is commanded in the transmitted prophetic report, in which the speaker among the imams (عَلَيْهِمُ السَّلَامُ) said: hasten the circumcision of your children, for it is purer for them. This is the reverse of your practice with the girls, and so you have inverted the matter in both cases, contrary to the command of the Mighty Creator. I have learned of people in other regions who leave their children uncircumcised until close upon twenty years of age — and that is a manifest contravention of the Shariah of Islam.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'section among these matters is also what has become known the delay practiced by most of you in the purification of your male children whose hastening is commanded in the transmitted prophetic report in which the speaker among the imams عليهم السلام said hasten the circumcision of your children for it is purer for them this is the reverse of your practice with the girls and so you have inverted the matter in both cases contrary to the command of the mighty creator i have learned of people in other regions who leave their children uncircumcised until close upon twenty years of age and that is a manifest contravention of the shariah of islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 68, NULL, 'The wonder of wonders, for whoever reflects upon it as it deserves — in what has been of affairs and what shall be, and surely in that are signs for a people who reflect — is this: all the People of the Book among the protected communities who came before you hasten the circumcision of their children with the utmost haste, on the seventh day of their lives, in compliance with what Moses, the one addressed by God (ع), prescribed for them in his law from his Lord. They have carried on with that practice through these successive thousands of years, enduring for their children the pain of it at that tender age. Yet you are nearer than they to the covenant of your Prophet — and still you cast aside his command in this, when he commanded you to hasten, deferring it to what lies beyond and above those days, with this deliberate delay contrary to the canons of the Shariah of Islam. Glory be to God the Mighty, and again glory be to God the Mighty, at what you do in this — for its matter is grave.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'the wonder of wonders for whoever reflects upon it as it deserves in what has been of affairs and what shall be and surely in that are signs for a people who reflect is this all the people of the book among the protected communities who came before you hasten the circumcision of their children with the utmost haste on the seventh day of their lives in compliance with what moses the one addressed by god ع prescribed for them in his law from his lord they have carried on with that practice through these successive thousands of years enduring for their children the pain of it at that tender age yet you are nearer than they to the covenant of your prophet and still you cast aside his command in this when he commanded you to hasten deferring it to what lies beyond and above those days with this deliberate delay contrary to the canons of the shariah of islam glory be to god the mighty and again glory be to god the mighty at what you do in this for its matter is grave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 69, NULL, 'Sayingيَعِظُكُمُ اللَّهُ أَنْ تَعُودُوا لِمِثْلِهِ أَبَدًا إِنْ كُنْتُمْ مُؤْمِنِينَ وَبَيَّنَ اللَّهُ لَكُمُ الْآيَاتِ وَاللَّهُ عَلِيمٌ حَكِيمٌ"God admonishes you never to return to the like of it, if you are believers. God makes clear to you the signs, and God is All-Knowing, All-Wise."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingيعظكم الله ان تعودوا لمثله ابدا ان كنتم مومنين وبين الله لكم الايات والله عليم حكيم god admonishes you never to return to the like of it if you are believers god makes clear to you the signs and god is all knowing all wise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 70, NULL, 'And our master Jafar said, concerning the practice of men applying henna, in the same noble letter:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'and our master jafar said concerning the practice of men applying henna in the same noble letter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 71, NULL, 'Section: Among these matters also is what has become known and reported of some among you who are bound by the bond of allegiance to the friends of God (عَلَيْهِمُ السَّلَامُ) — that they imitate the women of their households by dyeing their hands with henna, and some of them their hands and their feet as well. Neither the law of the Prophet nor the religion of Islam permits this. It was appointed in both cases for women and not for men, just as jewelry belongs to women and not to men in every circumstance. A man who does this — taking it from the women, adorning himself with it and making himself resemble them — is like one who adorns himself with their ornaments of silver and gold. None would choose this for himself unless his reason had been lost and gone. Beware of committing it, for it is among the acts of disobedience to God, the Mighty and Exalted. Adorn yourselves in its place with the fear of God, for you will not attain your hope in any of your affairs except through the fear of God. You have heard the report current in the sunna among non-Arabs and Arabs alike:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'section among these matters also is what has become known and reported of some among you who are bound by the bond of allegiance to the friends of god عليهم السلام that they imitate the women of their households by dyeing their hands with henna and some of them their hands and their feet as well neither the law of the prophet nor the religion of islam permits this it was appointed in both cases for women and not for men just as jewelry belongs to women and not to men in every circumstance a man who does this taking it from the women adorning himself with it and making himself resemble them is like one who adorns himself with their ornaments of silver and gold none would choose this for himself unless his reason had been lost and gone beware of committing it for it is among the acts of disobedience to god the mighty and exalted adorn yourselves in its place with the fear of god for you will not attain your hope in any of your affairs except through the fear of god you have heard the report current in the sunna among non arabs and arabs alike', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 72, NULL, 'Sayingحَلْيُ الرِّجَالِ الْأَدَبُ وَحَلْيُ النِّسَاءِ الذَّهَبُ', '', 'حَلْيُ الرِّجَالِ الْأَدَبُ وَحَلْيُ النِّسَاءِ الذَّهَبُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingحلي الرجال الادب وحلي النساء الذهب', 'حلي الرجال الادب وحلي النساء الذهب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 73, NULL, 'Leave the opponents of the guiding dawa and what they uphold in this matter, for the one whom they claim as their master and the owner of their affair had already gone before them in that practice — and that detestable deed is reckoning enough for him and for them alike. God, God — keep yourselves clean of it, so that your faces may be made white before Him on the day when faces are made white and faces are made black.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'leave the opponents of the guiding dawa and what they uphold in this matter for the one whom they claim as their master and the owner of their affair had already gone before them in that practice and that detestable deed is reckoning enough for him and for them alike god god keep yourselves clean of it so that your faces may be made white before him on the day when faces are made white and faces are made black', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 74, NULL, 'Our master Jafar, may God exalt his sanctity, said in answering the questions that I, his servant and the author of this book, put to him — questions he answered from his Island of Yemen to the Island of Hind: As for what you asked, that it has come in the books of the pure Shariah that girls are not circumcised before seven years — if one of them passes away while below that limit, is she circumcised as male children are circumcised when they have not been circumcised in their lifetimes, or is she buried in her state without it? The point is that, since that stated limit has been set for their circumcision, it is not permissible that it be transgressed in their case.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'our master jafar may god exalt his sanctity said in answering the questions that i his servant and the author of this book put to him questions he answered from his island of yemen to the island of hind as for what you asked that it has come in the books of the pure shariah that girls are not circumcised before seven years if one of them passes away while below that limit is she circumcised as male children are circumcised when they have not been circumcised in their lifetimes or is she buried in her state without it the point is that since that stated limit has been set for their circumcision it is not permissible that it be transgressed in their case', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 75, NULL, 'Our master Muhammad ibn Fahd al-Mukarrami, may God exalt his sanctity, was asked about a daughter who dies before reaching seven years: is she circumcised or not? He answered his questioner: she is not circumcised, because she has not reached the age of circumcision.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'our master muhammad ibn fahd al mukarrami may god exalt his sanctity was asked about a daughter who dies before reaching seven years is she circumcised or not he answered his questioner she is not circumcised because she has not reached the age of circumcision', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 76, NULL, 'Our mawla the Commander of the Faithful, Ali ibn Abi Talib (ع), said in his four hundred counsels:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'our mawla the commander of the faithful ali ibn abi talib ع said in his four hundred counsels', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'bodies, hair, and the reform of custom', '11. Bodies, Hair, and the Reform of Custom', 77, NULL, 'Sayingاِخْتِنُوا أَوْلَادَكُمْ يَوْمَ السَّابِعِ وَلَا يَمْنَعْكُمْ حَرٌّ وَلَا بَرْدٌ فَأِنَّهُ طَهُورٌ لِلْجَسَدِ وَاِنَّ الْأَرْضَ تَضِجُّ إِلَى اللهِ مِنْ بَوْلِ الْأَقْلَفِ عَلَيْهَا"Circumcise your children on the seventh day, and let neither heat nor cold prevent you, for it is a purification of the body; and the earth cries out to God because of the urine of the uncircumcised upon it."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 11 bodies hair and the reform of custom', 'sayingاختنوا اولادكم يوم السابع ولا يمنعكم حر ولا برد فانه طهور للجسد وان الارض تضج الي الله من بول الاقلف عليها circumcise your children on the seventh day and let neither heat nor cold prevent you for it is a purification of the body and the earth cries out to god because of the urine of the uncircumcised upon it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 0, NULL, 'I turn now to the purity of skins, bones, hair, and wool. What follows is drawn from the book of questions and answers mentioned earlier, which its compiler arranged in the order of the chapters of the book دَعَائِمُ الْإِسْلَامِ.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'i turn now to the purity of skins bones hair and wool what follows is drawn from the book of questions and answers mentioned earlier which its compiler arranged in the order of the chapters of the book دعايم الاسلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 1, NULL, 'Question: What do you say, O ray of the sun of guidance, concerning impure garments — or the skins of carrion, or the skins of beasts of prey — when they cling to the body while either the skin or the body is wet? Must the body be washed, or not? The same question applies to garments washed by the hands of polytheists.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'question what do you say o ray of the sun of guidance concerning impure garments or the skins of carrion or the skins of beasts of prey when they cling to the body while either the skin or the body is wet must the body be washed or not the same question applies to garments washed by the hands of polytheists', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 2, NULL, 'Answer: If any such thing clings to the body, the body must be washed. The same ruling applies to whatever polytheists have washed with their hands.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'answer if any such thing clings to the body the body must be washed the same ruling applies to whatever polytheists have washed with their hands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 3, NULL, 'Question: What do you say concerning what has come in تَأْوِيلُ الدَّعَائِمِ — that the goat is not shorn of its hair as the sheep is shorn of its wool, that benefit may be taken from it while the animals are alive, and that it is lawful to be clothed in it and to pray in it and upon it? The passage further states that the rest of the animal is lawful — its flesh, its skins, and its bones — and that these are purified if the animal is properly slaughtered. Given all this, our master, may one pray upon the goat''s hair and skins if they were taken after the slaughter?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'question what do you say concerning what has come in تاويل الدعايم that the goat is not shorn of its hair as the sheep is shorn of its wool that benefit may be taken from it while the animals are alive and that it is lawful to be clothed in it and to pray in it and upon it the passage further states that the rest of the animal is lawful its flesh its skins and its bones and that these are purified if the animal is properly slaughtered given all this our master may one pray upon the goats hair and skins if they were taken after the slaughter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 4, NULL, 'Answer: If the goat''s hair and skins are taken after it has been properly slaughtered, prayer upon them is permitted. The goat is a kind of sheep: its private parts are uncovered, its tail turns upward, and it has two horns. It is most common in India.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'answer if the goats hair and skins are taken after it has been properly slaughtered prayer upon them is permitted the goat is a kind of sheep its private parts are uncovered its tail turns upward and it has two horns it is most common in india', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 5, NULL, 'Question: Concerning a lawful animal — when some of its wool, fleece, or hair is shorn from it while it is still alive: must that shorn material be washed as an impure garment is washed, or not? And if there is moisture in it before it is washed, and it touches a garment or the body, does it render them impure, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'question concerning a lawful animal when some of its wool fleece or hair is shorn from it while it is still alive must that shorn material be washed as an impure garment is washed or not and if there is moisture in it before it is washed and it touches a garment or the body does it render them impure or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 6, NULL, 'Answer: The text states that prayer is not permitted in it until it has been washed, yet the material itself is not impure.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'answer the text states that prayer is not permitted in it until it has been washed yet the material itself is not impure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 7, NULL, 'Question: What does our master say — may God perpetuate his guidance — concerning a vessel made from the skins of carrion in the district of Waghar, which is a large town whose people are mostly unbelievers? The vessel is filled with ghee or oil and brought to Ahmedabad, and what is in it is then sold. Is that permitted or not? And if soap is made from it, mixed with lye and soda ash, is the sale and purchase of that soap permitted or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'question what does our master say may god perpetuate his guidance concerning a vessel made from the skins of carrion in the district of waghar which is a large town whose people are mostly unbelievers the vessel is filled with ghee or oil and brought to ahmedabad and what is in it is then sold is that permitted or not and if soap is made from it mixed with lye and soda ash is the sale and purchase of that soap permitted or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 8, NULL, 'Answer: If anything edible is placed in this vessel, it becomes impure, and one may not pray in a garment that such a thing has touched. The sale and purchase of the ghee or the soap are permitted, but the buyer must be informed that they are impure. It is not lawful, however, to sell or to buy the skins of carrion themselves.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'answer if anything edible is placed in this vessel it becomes impure and one may not pray in a garment that such a thing has touched the sale and purchase of the ghee or the soap are permitted but the buyer must be informed that they are impure it is not lawful however to sell or to buy the skins of carrion themselves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 9, NULL, 'And from the book تَأْوِيلُ الدَّعَائِمِ:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'and from the book تاويل الدعايم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 10, NULL, 'Sayingوَلَا يُجَزُّ الشَّعْرُ مِنَ الْمَعْزِ اِلَّا بَعْدَ الذَّبْحِ فَاِنْ جُزَّ وَهُوَ حَيٌّ فَهُوَ مَيَّةٌ', '', 'وَلَا يُجَزُّ الشَّعْرُ مِنَ الْمَعْزِ اِلَّا بَعْدَ الذَّبْحِ فَاِنْ جُزَّ وَهُوَ حَيٌّ فَهُوَ مَيَّةٌ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'sayingولا يجز الشعر من المعز الا بعد الذبح فان جز وهو حي فهو ميه', 'ولا يجز الشعر من المعز الا بعد الذبح فان جز وهو حي فهو ميه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 11, NULL, 'The hair of the goat is not to be shorn except after slaughter. If it is shorn while the animal is alive, it counts as carrion. This ruling applies to the goat in particular. And from the same book: the goat is not shorn of its hair as the sheep is shorn of its wool, so that benefit may be taken from it while the animals are alive, and it is lawful to be clothed in it and to pray in it and upon it. The rest of the animal is likewise lawful — its hair, its skins, its bones, and whatever else belongs to it — and these are purified if the animal is properly slaughtered.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'the hair of the goat is not to be shorn except after slaughter if it is shorn while the animal is alive it counts as carrion this ruling applies to the goat in particular and from the same book the goat is not shorn of its hair as the sheep is shorn of its wool so that benefit may be taken from it while the animals are alive and it is lawful to be clothed in it and to pray in it and upon it the rest of the animal is likewise lawful its hair its skins its bones and whatever else belongs to it and these are purified if the animal is properly slaughtered', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 12, NULL, 'And from مُخْتَصَرُ الْمُصَنَّفِ: if a person''s bone is broken, it is not permitted to patch it except with the bone of an animal whose flesh is eaten and which has been properly slaughtered. Whoever patches one of his bones with the bone of carrion, or with the bone of an animal whose flesh is not eaten, or with the bone of a dead human being, must remove it and repeat every prayer he has prayed. The ruling authority compels him to do so if his case becomes known. If it is not known until he dies and he himself did not know of it, it is not removed after his death. And one may not take benefit from the hair of human beings as one takes benefit from the hair of beasts.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'and from مختصر المصنف if a persons bone is broken it is not permitted to patch it except with the bone of an animal whose flesh is eaten and which has been properly slaughtered whoever patches one of his bones with the bone of carrion or with the bone of an animal whose flesh is not eaten or with the bone of a dead human being must remove it and repeat every prayer he has prayed the ruling authority compels him to do so if his case becomes known if it is not known until he dies and he himself did not know of it it is not removed after his death and one may not take benefit from the hair of human beings as one takes benefit from the hair of beasts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 13, NULL, 'And from تَأْوِيلُ الدَّعَائِمِ, on the view that benefit may be taken from a covering made of carrion that does not adhere: the meaning is that it does not cling to anything pure while either of the two is wet, so that impurity reaches it. And from كِتَابُ الْأَخْبَارِ:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'and from تاويل الدعايم on the view that benefit may be taken from a covering made of carrion that does not adhere the meaning is that it does not cling to anything pure while either of the two is wet so that impurity reaches it and from كتاب الاخبار', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 14, NULL, 'Sayingوَكَرِهُوا أَنْ يُنْتَفَعَ بِلَحْمِ الْخِنْزِيرِ', '', 'وَكَرِهُوا أَنْ يُنْتَفَعَ بِلَحْمِ الْخِنْزِيرِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'sayingوكرهوا ان ينتفع بلحم الخنزير', 'وكرهوا ان ينتفع بلحم الخنزير');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 15, NULL, 'And they held it reprehensible to take benefit from the flesh of swine.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'and they held it reprehensible to take benefit from the flesh of swine', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 16, NULL, 'I come now to menstruation and postpartum bleeding, drawing again upon that same book of questions and answers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'i come now to menstruation and postpartum bleeding drawing again upon that same book of questions and answers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 17, NULL, 'Question: What do you say concerning what has come in the Sharia — that the menstruating woman wraps herself with a wrapper from below the navel to the knees, and that her husband may have of her what is above the wrapper and what is below it? So, our master, may he touch her whole body short of intercourse? Answer: Yes, he may touch her body, but it is better that he avoid what is beneath the wrapper, for fear that the fluid reach her womb.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'question what do you say concerning what has come in the sharia that the menstruating woman wraps herself with a wrapper from below the navel to the knees and that her husband may have of her what is above the wrapper and what is below it so our master may he touch her whole body short of intercourse answer yes he may touch her body but it is better that he avoid what is beneath the wrapper for fear that the fluid reach her womb', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 18, NULL, 'Another matter: if a woman menstruates and remains in that state for ten days, and after those ten days the blood continues for two, three, four, or five more days, she does not pray and does not fast, her husband does not approach her, and she does not make up the prayers after her purification, provided she is certain that menstrual blood is distinguishable from the blood of istihadah. If she is in doubt about the blood, then she is a mustahadah.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'another matter if a woman menstruates and remains in that state for ten days and after those ten days the blood continues for two three four or five more days she does not pray and does not fast her husband does not approach her and she does not make up the prayers after her purification provided she is certain that menstrual blood is distinguishable from the blood of istihadah if she is in doubt about the blood then she is a mustahadah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 19, NULL, 'Another matter: whoever misses the prayer of the Feast of Ghadir and its fast makes them up after that day, on whatever day it may be, performing the make-up at the time of the sun''s decline, just as it would have been.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'another matter whoever misses the prayer of the feast of ghadir and its fast makes them up after that day on whatever day it may be performing the make up at the time of the suns decline just as it would have been', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 20, NULL, 'Question: What do you say concerning a woman who becomes pure from menstruation or from postpartum bleeding within the time of a prayer, and when she has finished the washing, the time of the prayer has passed? Is she obliged to make up that prayer or not? Answer: If she was leisurely, she makes it up; but if she was diligent in her washing and did not finish it until the time passed, she is not obliged to make up that prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'question what do you say concerning a woman who becomes pure from menstruation or from postpartum bleeding within the time of a prayer and when she has finished the washing the time of the prayer has passed is she obliged to make up that prayer or not answer if she was leisurely she makes it up but if she was diligent in her washing and did not finish it until the time passed she is not obliged to make up that prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 21, NULL, 'And from the answers of our master al-Numan, may God sanctify his soul, to the governor of Zawatah, Khattab ibn Wasim: You asked me about a blind woman, and how she is to manage her menstruation. Command her to insert a piece of cotton or a white cloth, and to have it inspected by a woman whose religion she trusts. As long as the blood comes out upon it she is menstruating; and when it comes out white she has become pure, so she washes, prays, and fasts, and her husband comes to her. She does likewise at the beginning of her menstruation if she does not perceive it herself.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'and from the answers of our master al numan may god sanctify his soul to the governor of zawatah khattab ibn wasim you asked me about a blind woman and how she is to manage her menstruation command her to insert a piece of cotton or a white cloth and to have it inspected by a woman whose religion she trusts as long as the blood comes out upon it she is menstruating and when it comes out white she has become pure so she washes prays and fasts and her husband comes to her she does likewise at the beginning of her menstruation if she does not perceive it herself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 22, NULL, 'Another matter: if a woman becomes pure from menstrual blood in the month of Ramadan before sunset and fears harm from washing, it is permitted to her to perform tayammum and to fast, and she does not make up that fast. Likewise the man who has a nocturnal emission in the month of Ramadan: if he fears illness for himself from washing at night, he performs tayammum and fasts, and he does not make up that fast.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'another matter if a woman becomes pure from menstrual blood in the month of ramadan before sunset and fears harm from washing it is permitted to her to perform tayammum and to fast and she does not make up that fast likewise the man who has a nocturnal emission in the month of ramadan if he fears illness for himself from washing at night he performs tayammum and fasts and he does not make up that fast', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 23, NULL, 'Question: Concerning the woman who becomes pure in the month of Ramadan from menstruation and fasts nine days, and menstruation comes to her on the tenth day — is her fasting of those nine days established or not? Answer: It has been mentioned that the least of menstruation is three days, and the least of purity is ten days.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'question concerning the woman who becomes pure in the month of ramadan from menstruation and fasts nine days and menstruation comes to her on the tenth day is her fasting of those nine days established or not answer it has been mentioned that the least of menstruation is three days and the least of purity is ten days', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 24, NULL, 'Question: From the book of purification, that the most of the days of menstruation is ten days: if the bleeding exceeds this term, are her prayer and her fasting established, even if the blood is thick and foul, or not? Answer: Menstrual blood and the blood of istihadah have both been described, and the distinction between them made, so rely upon the text in that matter.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'question from the book of purification that the most of the days of menstruation is ten days if the bleeding exceeds this term are her prayer and her fasting established even if the blood is thick and foul or not answer menstrual blood and the blood of istihadah have both been described and the distinction between them made so rely upon the text in that matter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 25, NULL, 'Question: It has come in the Sharia that the limit of postpartum bleeding is forty days, and in some books sixty days. Which of the two, our master, is more correct? Answer: This answer is from our master Hasan ibn Nuh in his own words, may God sanctify his soul. He said: the woman in her postpartum period reckons the nifas according to the duration to which she is accustomed, and the blood of nifas is distinguishable from the blood of istihadah. Whenever she becomes pure and is clean of blood, she washes, prays, and fasts, and her husband comes to her. And it is said in the book of purification: the woman in her postpartum period, when she has given birth, or has seen blood before delivery in a state of menstruation, continues with the blood until it ceases from her; and the menstruating woman washes when she becomes pure. If the blood is prolonged with her, she is a mustahadah, and the blood of nifas is distinguishable from the blood of istihadah, just as we mentioned the distinction of menstrual blood from the blood of istihadah. And it is said in مُخْتَصَرُ الْآثَارِ: the woman in her postpartum period is like the menstruating woman, and in a state like hers; what is obligatory upon her and upon her husband in her affair is what is obligatory in menstruation, and she washes when the blood of nifas ceases from her. And it is said in مُخْتَصَرُ الْمُصَنَّفِ: the woman in her postpartum period leaves the prayer for the number of the days of her nifas and according to what her custom has been, if she has a custom; and likewise in دَعَائِمُ الْإِسْلَامِ, which sets her upon this same course.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'question it has come in the sharia that the limit of postpartum bleeding is forty days and in some books sixty days which of the two our master is more correct answer this answer is from our master hasan ibn nuh in his own words may god sanctify his soul he said the woman in her postpartum period reckons the nifas according to the duration to which she is accustomed and the blood of nifas is distinguishable from the blood of istihadah whenever she becomes pure and is clean of blood she washes prays and fasts and her husband comes to her and it is said in the book of purification the woman in her postpartum period when she has given birth or has seen blood before delivery in a state of menstruation continues with the blood until it ceases from her and the menstruating woman washes when she becomes pure if the blood is prolonged with her she is a mustahadah and the blood of nifas is distinguishable from the blood of istihadah just as we mentioned the distinction of menstrual blood from the blood of istihadah and it is said in مختصر الاثار the woman in her postpartum period is like the menstruating woman and in a state like hers what is obligatory upon her and upon her husband in her affair is what is obligatory in menstruation and she washes when the blood of nifas ceases from her and it is said in مختصر المصنف the woman in her postpartum period leaves the prayer for the number of the days of her nifas and according to what her custom has been if she has a custom and likewise in دعايم الاسلام which sets her upon this same course', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 26, NULL, 'I myself saw, in one of the books of the Sharia of the people of the House (عَلَيْهِمُ السَّلَامُ), the term of the woman in her postpartum period reckoned by days. It is mentioned there that the least of nifas is twenty days, the middle is forty days, and the most is sixty days; and that this is when the blood continues with her, so that it does not exceed sixty days; and that menstrual blood is other than the blood of istihadah; and that it never falls short of twenty days, and the woman in her postpartum period does not become pure before twenty days. This is the sense of the words of that book. As for its exact wording, I did not find it at the time of writing this page; if I live and come upon that book, I will set down its wording exactly, God willing.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'i myself saw in one of the books of the sharia of the people of the house عليهم السلام the term of the woman in her postpartum period reckoned by days it is mentioned there that the least of nifas is twenty days the middle is forty days and the most is sixty days and that this is when the blood continues with her so that it does not exceed sixty days and that menstrual blood is other than the blood of istihadah and that it never falls short of twenty days and the woman in her postpartum period does not become pure before twenty days this is the sense of the words of that book as for its exact wording i did not find it at the time of writing this page if i live and come upon that book i will set down its wording exactly god willing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 27, NULL, 'As for the point intended, I have made clear to you that the woman in her postpartum period, when she is clean of blood, has become pure after twenty days. This is the ruling concerning her, decisively. Thereafter she relies upon what she is accustomed to. If the blood exceeds her custom, she looks to see whether the blood has changed or is as it was. If it has changed, then it is the blood of istihadah; and if it has not changed, then its ruling is as I described at first. And our master al-Numan, may God sanctify his soul, mentioned in اَلْمُنْتَخَبَةُ:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'as for the point intended i have made clear to you that the woman in her postpartum period when she is clean of blood has become pure after twenty days this is the ruling concerning her decisively thereafter she relies upon what she is accustomed to if the blood exceeds her custom she looks to see whether the blood has changed or is as it was if it has changed then it is the blood of istihadah and if it has not changed then its ruling is as i described at first and our master al numan may god sanctify his soul mentioned in المنتخبه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 28, NULL, 'Sayingوَالنُّفَسَاءُ تَجْلِسُ قَدْرَ الْحَيْضِ فَاِنْ تَمَادَى دَمُهَا بِالْفَيْضِ تَرَيَّصْتُ لِمَبْلَغِ الشَّهْرَیْنِ ثُمَّ قَضَتْ مَا بَيْنَمَا الْوَقْتَيْنِ تَطَهَّرَتْ حِيَاطَةُ لِتُسْلِمَ مِنَ الصَّلَاةِ وَالصِّيَامِ بَعْدَ مَا إِنِ اسْتَحَاضَتْ بَعْدَ هَذَا الْاِنْقِضَا وَقَدْ ذَكَرْتُ حُكْمَهَا فِي مَا مَضَى', '', 'وَالنُّفَسَاءُ تَجْلِسُ قَدْرَ الْحَيْضِ فَاِنْ تَمَادَى دَمُهَا بِالْفَيْضِ تَرَيَّصْتُ لِمَبْلَغِ الشَّهْرَیْنِ ثُمَّ قَضَتْ مَا بَيْنَمَا الْوَقْتَيْنِ تَطَهَّرَتْ حِيَاطَةُ لِتُسْلِمَ مِنَ الصَّلَاةِ وَالصِّيَامِ بَعْدَ مَا إِنِ اسْتَحَاضَتْ بَعْدَ هَذَا الْاِنْقِضَا وَقَدْ ذَكَرْتُ حُكْمَهَا فِي مَا مَضَى', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'sayingوالنفساء تجلس قدر الحيض فان تمادي دمها بالفيض تريصت لمبلغ الشهرين ثم قضت ما بينما الوقتين تطهرت حياطه لتسلم من الصلاه والصيام بعد ما ان استحاضت بعد هذا الانقضا وقد ذكرت حكمها في ما مضي', 'والنفساء تجلس قدر الحيض فان تمادي دمها بالفيض تريصت لمبلغ الشهرين ثم قضت ما بينما الوقتين تطهرت حياطه لتسلم من الصلاه والصيام بعد ما ان استحاضت بعد هذا الانقضا وقد ذكرت حكمها في ما مضي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 29, NULL, 'This applies when the postpartum blood extends beyond a woman''s established pattern, and the blood is turbid, thick, and foul — the character of true nifas blood. In that case, she refrains from prayer and fasting and keeps away from her husband until two full months have elapsed. If the blood continues beyond the two months, she is unquestionably a mustahadah. She then washes and makes up the prayers and fasts she abandoned — from the completion of her customary term to the completion of the two months — by way of precaution, since this is a matter of doubt: it is possible that menstruation followed the nifas. That is the ruling of nifas, and God and His Messenger know best. With this, the answer of our master is complete, by the praise and bounty of God.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'this applies when the postpartum blood extends beyond a womans established pattern and the blood is turbid thick and foul the character of true nifas blood in that case she refrains from prayer and fasting and keeps away from her husband until two full months have elapsed if the blood continues beyond the two months she is unquestionably a mustahadah she then washes and makes up the prayers and fasts she abandoned from the completion of her customary term to the completion of the two months by way of precaution since this is a matter of doubt it is possible that menstruation followed the nifas that is the ruling of nifas and god and his messenger know best with this the answer of our master is complete by the praise and bounty of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 30, NULL, 'It is said in the book مُخْتَصَرُ الْمُصَنَّفِ: if she begins the prayer at its proper time and then menstruates, she need not make up that prayer. If she menstruates for a day or two and the blood then stops, and she observes ten days of purity, that does not count as menstruation — for menstruation is not less than three days — and if she abandoned the prayer during that time, she repeats it. If she sees blood for a day or two, then sees purity for fewer than ten days, then sees blood again, the first and second episodes together constitute menstruation.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'it is said in the book مختصر المصنف if she begins the prayer at its proper time and then menstruates she need not make up that prayer if she menstruates for a day or two and the blood then stops and she observes ten days of purity that does not count as menstruation for menstruation is not less than three days and if she abandoned the prayer during that time she repeats it if she sees blood for a day or two then sees purity for fewer than ten days then sees blood again the first and second episodes together constitute menstruation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 31, NULL, 'It is said in تَأْوِيلُ الدَّعَائِمِ that the word nifas was mentioned only in connection with childbirth, and that what is meant by it is the blood that accompanies it. This is made plain by what was reported from the Messenger of God, who said to one of his wives when she was with him on his bed and she drew back:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'it is said in تاويل الدعايم that the word nifas was mentioned only in connection with childbirth and that what is meant by it is the blood that accompanies it this is made plain by what was reported from the messenger of god who said to one of his wives when she was with him on his bed and she drew back', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 32, NULL, 'Sayingمَا لَكَ أَنْفَسْتَ ؟ قَالَتْ نَعَمْ', '', 'مَا لَكَ أَنْفَسْتَ ؟ قَالَتْ نَعَمْ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'sayingما لك انفست قالت نعم', 'ما لك انفست قالت نعم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 33, NULL, 'What is the matter with you? Have you begun to bleed? She said: Yes. He meant that she had menstruated.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'what is the matter with you have you begun to bleed she said yes he meant that she had menstruated', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 34, NULL, 'Likewise the mustahadah — she is the woman whose blood does not cease, though it is distinguishable from menstrual blood. When her menstruation is upon her, the blood comes thick and turbid; when it departs, the blood becomes thin. What is binding upon her is this: as long as the menstrual blood is with her, she is in a state of menstruation — she does not pray, does not enter the mosque, and her husband may not approach her. When the menstrual blood departs and the remaining flow thins, she purifies herself as she purifies herself from menstruation; she is then in a state of purity, praying, fasting, entering the mosque, and her husband may come to her. Whenever any of that blood appears, she performs ablution, for it is an ailment affecting her.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'likewise the mustahadah she is the woman whose blood does not cease though it is distinguishable from menstrual blood when her menstruation is upon her the blood comes thick and turbid when it departs the blood becomes thin what is binding upon her is this as long as the menstrual blood is with her she is in a state of menstruation she does not pray does not enter the mosque and her husband may not approach her when the menstrual blood departs and the remaining flow thins she purifies herself as she purifies herself from menstruation she is then in a state of purity praying fasting entering the mosque and her husband may come to her whenever any of that blood appears she performs ablution for it is an ailment affecting her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 35, NULL, 'It is reported from تَأْوِيلُ الدَّعَائِمِ — regarding the teaching that whoever approaches a menstruating woman has approached what is not lawful to him and has done what he ought not to do — that he must seek God''s forgiveness and repent to Him for his offense, and if he gives charity alongside that, it is good. The blood of nifas is distinguishable from the blood of istihadah in the same way that menstrual blood is distinguishable from the blood of istihadah, as we mentioned. It is also reported from تَأْوِيلُ الدَّعَائِمِ: the same obligation applies to the woman if she consented; but if he compelled her, there is nothing upon her. If the man did not know of her menstruation and she concealed it from him until he had intercourse with her, the sin falls upon her and nothing upon him, since he did not know of her menstruation. The menstruating woman does not touch the mushaf.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'it is reported from تاويل الدعايم regarding the teaching that whoever approaches a menstruating woman has approached what is not lawful to him and has done what he ought not to do that he must seek gods forgiveness and repent to him for his offense and if he gives charity alongside that it is good the blood of nifas is distinguishable from the blood of istihadah in the same way that menstrual blood is distinguishable from the blood of istihadah as we mentioned it is also reported from تاويل الدعايم the same obligation applies to the woman if she consented but if he compelled her there is nothing upon her if the man did not know of her menstruation and she concealed it from him until he had intercourse with her the sin falls upon her and nothing upon him since he did not know of her menstruation the menstruating woman does not touch the mushaf', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 36, NULL, 'It is said in the questions that came from the most venerable Shaykh Shimon ibn Muhammad Ghuri al-Hindi to our master Hasan ibn Idris, may God exalt his sanctity.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'it is said in the questions that came from the most venerable shaykh shimon ibn muhammad ghuri al hindi to our master hasan ibn idris may god exalt his sanctity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 37, NULL, 'Question: What do you say, O support of the Dawa, concerning the term of nifas? The common people claim that the limit — both its minimum and its maximum — is forty days.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'question what do you say o support of the dawa concerning the term of nifas the common people claim that the limit both its minimum and its maximum is forty days', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 38, NULL, 'Answer: It may be less than forty days, except that forty days must be reckoned. And you asked, O magnificent master and forbearing scholar, about menstruation that exceeds ten days: if it exceeds ten days, she is a mustahadah. Our master and mawla, the dear father Muhammad ibn al-Fahd, may God exalt his sanctity, used to say that if a woman sees blood after ten days of her menstruation she is a mustahadah. She washes for each prayer time if she is able, and prays. If she cannot wash, she performs tayammum and prays. If she can wash at one time but not at another, she does so when she is able; and when she is unable, she performs tayammum for that time and prays and fasts.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'answer it may be less than forty days except that forty days must be reckoned and you asked o magnificent master and forbearing scholar about menstruation that exceeds ten days if it exceeds ten days she is a mustahadah our master and mawla the dear father muhammad ibn al fahd may god exalt his sanctity used to say that if a woman sees blood after ten days of her menstruation she is a mustahadah she washes for each prayer time if she is able and prays if she cannot wash she performs tayammum and prays if she can wash at one time but not at another she does so when she is able and when she is unable she performs tayammum for that time and prays and fasts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 39, NULL, 'It is said in the book of the question that came from the most venerable Shaykh Shimon ibn Muhammad Ghuri al-Hindi (رض), together with the answer of our master, the moon of the world and of religion, Hasan ibn Idris, may God exalt his sanctity and grant us his intercession and his company.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'it is said in the book of the question that came from the most venerable shaykh shimon ibn muhammad ghuri al hindi رض together with the answer of our master the moon of the world and of religion hasan ibn idris may god exalt his sanctity and grant us his intercession and his company', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 40, NULL, 'Question: What do you say concerning the one in a state of janaba, and the menstruating woman, who recites supplications or other texts containing something of the Quran — whether the reciter knows this or does not? How is such a person to act: does he recite it or leave it? For it is established in the radiant Sharia that neither of these two recites the Quran nor touches it. And may the one in a state of janaba, or the menstruating woman, recite the tahlil, the takbir, the tahmid, and the tasbih, given that all of these appear in the Quran? And may such a person recite the basmala, given that it has been said to be a verse of the Quran?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'question what do you say concerning the one in a state of janaba and the menstruating woman who recites supplications or other texts containing something of the quran whether the reciter knows this or does not how is such a person to act does he recite it or leave it for it is established in the radiant sharia that neither of these two recites the quran nor touches it and may the one in a state of janaba or the menstruating woman recite the tahlil the takbir the tahmid and the tasbih given that all of these appear in the quran and may such a person recite the basmala given that it has been said to be a verse of the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 41, NULL, 'Answer: The menstruating woman does not recite the Quran, nor does the one in a state of janaba, nor any portion of it — whether in supplication or in books. Nor does such a person recite the basmala with the intention of reciting the Quran.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'answer the menstruating woman does not recite the quran nor does the one in a state of janaba nor any portion of it whether in supplication or in books nor does such a person recite the basmala with the intention of reciting the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 42, NULL, 'Sayingفَتَحَقَّقْ مَا ذَكَرْتُهُ لَكَ أَيُّهَا الْأَخُ وَكُنْ مِنَ الْمُوقِنِينَ وَأعْبُدْ رَبَّكَ حَتَّى يَأْتِيَكَ الْيَقِينُ', '', 'فَتَحَقَّقْ مَا ذَكَرْتُهُ لَكَ أَيُّهَا الْأَخُ وَكُنْ مِنَ الْمُوقِنِينَ وَأعْبُدْ رَبَّكَ حَتَّى يَأْتِيَكَ الْيَقِينُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'sayingفتحقق ما ذكرته لك ايها الاخ وكن من الموقنين واعبد ربك حتي ياتيك اليقين', 'فتحقق ما ذكرته لك ايها الاخ وكن من الموقنين واعبد ربك حتي ياتيك اليقين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 43, NULL, 'Hold fast to everything I have set before you, brother — be among those who know with certainty, and worship your Lord until that certainty comes to you.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'hold fast to everything i have set before you brother be among those who know with certainty and worship your lord until that certainty comes to you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 44, NULL, 'I turn now to istibra, the clearing of the womb, and I will say what appears in the book of questions and answers I have already cited:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'i turn now to istibra the clearing of the womb and i will say what appears in the book of questions and answers i have already cited', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 45, NULL, 'Sayingمَنْ زَنَى بِامْرَأَةٍ بِكْرًا أَوْ ثَيِّبًا فَأَرَادَ أَنْ يَتَزَوَّجَهَا فَلَا يَجُوزُ الْعَقْدُ اِلَّا بَعْدَ الِاسْتِبْرَاءِ', '', 'مَنْ زَنَى بِامْرَأَةٍ بِكْرًا أَوْ ثَيِّبًا فَأَرَادَ أَنْ يَتَزَوَّجَهَا فَلَا يَجُوزُ الْعَقْدُ اِلَّا بَعْدَ الِاسْتِبْرَاءِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'sayingمن زني بامراه بكرا او ثيبا فاراد ان يتزوجها فلا يجوز العقد الا بعد الاستبراء', 'من زني بامراه بكرا او ثيبا فاراد ان يتزوجها فلا يجوز العقد الا بعد الاستبراء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 46, NULL, 'Whoever commits fornication with a woman — virgin or previously married — and then wishes to marry her: the marriage contract is not permitted until her womb has been cleared.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'whoever commits fornication with a woman virgin or previously married and then wishes to marry her the marriage contract is not permitted until her womb has been cleared', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 47, NULL, 'The book الْاِقْتِصَارُ records the following: if a man has a wife who has a child by another man, and that child dies leaving property, her husband withdraws from her until her womb is cleared. If she is pregnant, the child in the womb inherits from the deceased, provided his mother does not inherit from him; otherwise, nothing is cast into the womb that has no right in the inheritance. This applies when the mother is a slave or a polytheist. If she is a free Muslim woman, his inheritance belongs to her rather than to the brothers, and she does not withdraw.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'the book الاقتصار records the following if a man has a wife who has a child by another man and that child dies leaving property her husband withdraws from her until her womb is cleared if she is pregnant the child in the womb inherits from the deceased provided his mother does not inherit from him otherwise nothing is cast into the womb that has no right in the inheritance this applies when the mother is a slave or a polytheist if she is a free muslim woman his inheritance belongs to her rather than to the brothers and she does not withdraw', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 48, NULL, 'The book مُخْتَصَرُ الْمُصَنَّفِ states that the woman undergoing the clearing of the womb withdraws for two months. The book كِتَابُ الْأَخْبَارِ records two transmitted positions: that a woman who has reached maturity but has not menstruated is cleared by forty-five nights; and that a virgin who reaches maturity, has not menstruated, and is then deflowered by the seller is cleared by nine months.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'the book مختصر المصنف states that the woman undergoing the clearing of the womb withdraws for two months the book كتاب الاخبار records two transmitted positions that a woman who has reached maturity but has not menstruated is cleared by forty five nights and that a virgin who reaches maturity has not menstruated and is then deflowered by the seller is cleared by nine months', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 49, NULL, 'The book كِتَابُ الزِّينَةِ, concerning the saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'the book كتاب الزينه concerning the saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 50, NULL, 'Sayingاَلْوَلَدُ لِلْفِرَاشِ وَلِلْعَاهِرِ الْحَجَرُ', '', 'اَلْوَلَدُ لِلْفِرَاشِ وَلِلْعَاهِرِ الْحَجَرُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'sayingالولد للفراش وللعاهر الحجر', 'الولد للفراش وللعاهر الحجر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 51, NULL, 'He said: what is meant is only that the fornicator has no right in the lineage of the child.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'he said what is meant is only that the fornicator has no right in the lineage of the child', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'skins, blood, and waiting periods', '12. Skins, Blood, and Waiting Periods', 52, NULL, 'The book of questions and answers already mentioned states: whoever commits fornication with a man''s slave girl and then buys her from him while she is pregnant may not approach her until she gives birth. If she bears a child, its sale is permitted — even though the child came from him — because الْوَلَدُ لِلْفِرَاشِ، وَلِلزَّانِي الْحَجَرُ.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 12 skins blood and waiting periods', 'the book of questions and answers already mentioned states whoever commits fornication with a mans slave girl and then buys her from him while she is pregnant may not approach her until she gives birth if she bears a child its sale is permitted even though the child came from him because الولد للفراش وللزاني الحجر', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 0, NULL, 'I now enter the Book of Prayer, beginning with what has been transmitted regarding its merits, what is forbidden within it, and the matters connected to these.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'i now enter the book of prayer beginning with what has been transmitted regarding its merits what is forbidden within it and the matters connected to these', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 2, NULL, 'I record first what the Commander of the Faithful, Ali ibn Abi Talib (ع), said in his four hundred precepts of good conduct:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'i record first what the commander of the faithful ali ibn abi talib ع said in his four hundred precepts of good conduct', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 3, NULL, 'Sayingقِيَامُ اللَّيْلِ مَصْلَحَةٌ لِلْبَدَنِ وَرِضًى لِلرَّبِّ وَتَعَرُّضٌ لِلرَّحْمَةِ وَتَمَسُّكٌ بِأَخْلَاقِ النَّبِيِّينَ"Standing in prayer at night is a benefit to the body, a way of earning the Lord''s pleasure, an opening of oneself to mercy, and a holding fast to the character of the prophets."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingقيام الليل مصلحه للبدن ورضي للرب وتعرض للرحمه وتمسك باخلاق النبيين standing in prayer at night is a benefit to the body a way of earning the lords pleasure an opening of oneself to mercy and a holding fast to the character of the prophets', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 4, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 5, NULL, 'Sayingوَلَا يَقُومَنَّ الرَّجُلُ إِلَى الصَّلَاةِ مُتَكَاسِلًا وَلَا مُتَنَاعِسًا وَلْيُقْلِلِ الْعَبْدُ الْفِكْرَ إِذَا قَامَ بَيْنَ يَدَيِ اللَّهِ عَزَّ وَجَلَّ فَإِنَّمَا لَهُ مِنْ صَلَاتِهِ مَا أَقْبَلَ عَلَيْهِ وَلَا تَدَعُوا ذِكْرَ اللَّهِ فِي كُلِّ مَكَانٍ عَلَى كُلِّ حَالٍ وَلَا يَلْتَفِتَنَّ أَحَدُكُمْ فِي صَلَاتِهِ فَإِنَّ الْعَبْدَ إِذَا الْتَفَتَ فِيهَا قَالَ اللَّهُ عَزَّ وَجَلَّ: أَنِّي خَيْرٌ لَكَ مِمَّا الْتَفَتَّ إِلَيْهِ"Let no man rise to prayer in laziness or in drowsiness. Let the servant limit his wandering thoughts when he stands before God Almighty, for he receives of his prayer only that much of it to which he turned his attention. Do not abandon the remembrance of God in any place or in any condition. And let none of you look aside during his prayer, for when the servant looks aside in it, God Almighty says: I am better for you than that toward which you have turned."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingولا يقومن الرجل الي الصلاه متكاسلا ولا متناعسا وليقلل العبد الفكر اذا قام بين يدي الله عز وجل فانما له من صلاته ما اقبل عليه ولا تدعوا ذكر الله في كل مكان علي كل حال ولا يلتفتن احدكم في صلاته فان العبد اذا التفت فيها قال الله عز وجل اني خير لك مما التفت اليه let no man rise to prayer in laziness or in drowsiness let the servant limit his wandering thoughts when he stands before god almighty for he receives of his prayer only that much of it to which he turned his attention do not abandon the remembrance of god in any place or in any condition and let none of you look aside during his prayer for when the servant looks aside in it god almighty says i am better for you than that toward which you have turned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 6, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 7, NULL, 'Sayingإِيَّاكُمْ وَالْكَسَلَ فَإِنَّ مَنْ كَسِلَ لَمْ يُؤَدِّ حَقَّ اللَّهِ عَزَّ وَجَلَّ"Beware of laziness, for whoever grows lazy does not discharge the right of God Almighty."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingاياكم والكسل فان من كسل لم يود حق الله عز وجل beware of laziness for whoever grows lazy does not discharge the right of god almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 8, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 9, NULL, 'Sayingلَا يَعْبَثْ أَحَدُكُمْ بِلِحْيَتِهِ فِي الصَّلَاةِ وَلَا بِمَا يَشْغَلُهُ عَنْهَا"Let none of you toy with his beard during the prayer, nor with anything that distracts him from it."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingلا يعبث احدكم بلحيته في الصلاه ولا بما يشغله عنها let none of you toy with his beard during the prayer nor with anything that distracts him from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 10, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 11, NULL, 'Sayingاَلصَّلَاةُ قُرْبَانٌ لِكُلِّ تَقِيٍّ', '', 'اَلصَّلَاةُ قُرْبَانٌ لِكُلِّ تَقِيٍّ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingالصلاه قربان لكل تقي', 'الصلاه قربان لكل تقي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 12, NULL, 'Sayingاَلصَّلَاةُ قُرْبَانُ كُلِّ تَقِيٍّ', '', 'اَلصَّلَاةُ قُرْبَانُ كُلِّ تَقِيٍّ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingالصلاه قربان كل تقي', 'الصلاه قربان كل تقي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 13, NULL, '"Prayer is the offering of every godfearing person." And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'prayer is the offering of every godfearing person and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 14, NULL, 'Sayingلَيْسَ مِنْ عَمَلٍ أَحَبَّ إِلَى اللَّهِ مِنَ الصَّلَاةِ فَلَا تَشْغَلْكُمْ عَنْ أَوْقَاتِهَا أُمُورُ الدُّنْيَا فَإِنَّ اللَّهَ سُبْحَانَهُ ذَمَّ قَوْمًا اسْتَهَانُوا بِأَوْقَاتِهَا"There is no deed more beloved to God than prayer, so let not the affairs of this world distract you from its appointed times, for God — glory be to Him — reproached a people who made light of its times."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingليس من عمل احب الي الله من الصلاه فلا تشغلكم عن اوقاتها امور الدنيا فان الله سبحانه ذم قوما استهانوا باوقاتها there is no deed more beloved to god than prayer so let not the affairs of this world distract you from its appointed times for god glory be to him reproached a people who made light of its times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 15, NULL, 'He then cited the words of God Almighty:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'he then cited the words of god almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 16, NULL, 'Sayingفَوَيْلٌ لِّلْمُصَلِّينَ الَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ', '', 'فَوَيْلٌ لِّلْمُصَلِّينَ الَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingفويل للمصلين الذين هم عن صلاتهم ساهون', 'فويل للمصلين الذين هم عن صلاتهم ساهون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 17, NULL, '"So woe to those who pray — those who are neglectful of their prayer." That is to say, heedless of it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'so woe to those who pray those who are neglectful of their prayer that is to say heedless of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 18, NULL, 'I turn now to what is recorded in a book of legal questions, each of them a marvel.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'i turn now to what is recorded in a book of legal questions each of them a marvel', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 19, NULL, 'Another question: What is said of a man for whom prayer is not permissible, yet who is not excused for abandoning it? The answer is that he is a man who drank wine until his reason was gone. Prayer was therefore not permissible for him because of his drinking, yet he is not excused for leaving it, in view of the words of God Almighty:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'another question what is said of a man for whom prayer is not permissible yet who is not excused for abandoning it the answer is that he is a man who drank wine until his reason was gone prayer was therefore not permissible for him because of his drinking yet he is not excused for leaving it in view of the words of god almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 20, NULL, 'An-Nisa: 43لَا تَقْرَبُوا الصَّلَاةَ وَأَنتُمْ سُكَارَىٰ', '', 'لَا تَقْرَبُوا الصَّلَاةَ وَأَنتُمْ سُكَارَىٰ', 'An-Nisa: 43', 4, 43, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'an nisa 43لا تقربوا الصلاه وانتم سكاري', 'لا تقربوا الصلاه وانتم سكاري');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 21, NULL, '"Do not approach prayer while you are intoxicated." Consider what you say.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'do not approach prayer while you are intoxicated consider what you say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 22, NULL, 'Another question: What is said of a man who prayed in a state of purity, yet whose prayer was not valid? The answer is that he was a man who had emigrated and prayed behind a bedouin (أَعْرَابِيّ), so his prayer was not valid, because the bedouins are harder in disbelief and hypocrisy, and it is not permissible to pray behind them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'another question what is said of a man who prayed in a state of purity yet whose prayer was not valid the answer is that he was a man who had emigrated and prayed behind a bedouin اعرابي so his prayer was not valid because the bedouins are harder in disbelief and hypocrisy and it is not permissible to pray behind them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 23, NULL, 'Another question: What is said of an obligatory prayer in which the worshipper performs neither bowing nor prostration? The answer is: a man swimming who is unable to come out of the water onto dry land; upon him there is neither bowing nor prostration.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'another question what is said of an obligatory prayer in which the worshipper performs neither bowing nor prostration the answer is a man swimming who is unable to come out of the water onto dry land upon him there is neither bowing nor prostration', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 25, NULL, 'What follows I take from the aforementioned book of questions and answers, which is arranged according to the order of the chapters of the Book of the Pillars of Islam.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'what follows i take from the aforementioned book of questions and answers which is arranged according to the order of the chapters of the book of the pillars of islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 26, NULL, 'Question: What do you say — O you before whose awe the necks of great tyrants have bowed — concerning what has come in the Book of Purity: that when a man remembers his missed prayers (الْفَوَايِت) during the time of a current prayer, he prays the missed prayers first if there is room in the time, and afterward prays the one whose time he is in? Does our master hold that he sins if there is room in the time and he leaves the missed prayers and performs the current one instead, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'question what do you say o you before whose awe the necks of great tyrants have bowed concerning what has come in the book of purity that when a man remembers his missed prayers الفوايت during the time of a current prayer he prays the missed prayers first if there is room in the time and afterward prays the one whose time he is in does our master hold that he sins if there is room in the time and he leaves the missed prayers and performs the current one instead or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 27, NULL, 'Answer: Yes, he sins if there is room in the time, nothing hinders him, and he neglects them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'answer yes he sins if there is room in the time nothing hinders him and he neglects them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 28, NULL, 'Question: What do you say concerning what has come in the Book of the Pillars — that the Messenger of God, when he prayed the Fajr prayer after its time had passed, began with the sunnah before the obligatory prayer? How, then, should one act who has missed both the sunnah of Fajr and the obligatory Dhuhr?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'question what do you say concerning what has come in the book of the pillars that the messenger of god when he prayed the fajr prayer after its time had passed began with the sunnah before the obligatory prayer how then should one act who has missed both the sunnah of fajr and the obligatory dhuhr', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 29, NULL, 'Answer: He gives the sunnah of Fajr precedence, in making up, over the missed prayers that come after it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'answer he gives the sunnah of fajr precedence in making up over the missed prayers that come after it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 30, NULL, 'Question: What does our master say concerning a man who prayed the sunnah — two rakahs or four rakahs — and then prayed the obligatory prayer with the imam? How does he pray the remainder of the sunnah: as a performance in its time (أَدَاء) or as a making up (قَضَاء)?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'question what does our master say concerning a man who prayed the sunnah two rakahs or four rakahs and then prayed the obligatory prayer with the imam how does he pray the remainder of the sunnah as a performance in its time اداء or as a making up قضاء', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 31, NULL, 'Answer: Whatever remains of the sunnah he makes up if its time has passed. The time of the sunnah is before the obligatory prayer, except in the case of Maghrib.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'answer whatever remains of the sunnah he makes up if its time has passed the time of the sunnah is before the obligatory prayer except in the case of maghrib', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 32, NULL, 'Question: What does our master say concerning one who performed the obligatory prayer with the imam and had missed the sunnah? Does he perform the sunnah before the optional prayer (نَافِلَة) as a performance in its time, or as a making up?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'question what does our master say concerning one who performed the obligatory prayer with the imam and had missed the sunnah does he perform the sunnah before the optional prayer نافله as a performance in its time or as a making up', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 33, NULL, 'Answer: There is no harm in his praying the optional prayer as a performance in its time, so long as the time has not passed. The better course is that he pray the optional prayer as a performance in its time and then make up the sunnah.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'answer there is no harm in his praying the optional prayer as a performance in its time so long as the time has not passed the better course is that he pray the optional prayer as a performance in its time and then make up the sunnah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 34, NULL, 'Question: What does our master say concerning a man who prayed the obligatory prayer at the end of its time, so that the time then passed? Does he pray the optional prayer as a performance in its time, or as a making up?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'question what does our master say concerning a man who prayed the obligatory prayer at the end of its time so that the time then passed does he pray the optional prayer as a performance in its time or as a making up', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 35, NULL, 'Answer: He prays the optional prayer as a performance in its time, because he prayed the obligatory prayer as a performance in its time.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'answer he prays the optional prayer as a performance in its time because he prayed the obligatory prayer as a performance in its time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 36, NULL, 'Question: What does our master say concerning a man who prays the obligatory Maghrib prayer and then falls to talking while the people are praying the sunnah, goes out to a nearby place, and then returns while the people are again in the sunnah prayer? Does he pray the sunnah as a performance in its time, or as a making up?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'question what does our master say concerning a man who prays the obligatory maghrib prayer and then falls to talking while the people are praying the sunnah goes out to a nearby place and then returns while the people are again in the sunnah prayer does he pray the sunnah as a performance in its time or as a making up', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 37, NULL, 'Answer: If he prays the sunnah at the time of drawing near and of glorification, then it is a performance in its time; if that has passed, it is a making up. And if he went out to a nearby place and returned while the people were still in the sunnah prayer, it is a performance in its time.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'answer if he prays the sunnah at the time of drawing near and of glorification then it is a performance in its time if that has passed it is a making up and if he went out to a nearby place and returned while the people were still in the sunnah prayer it is a performance in its time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 38, NULL, 'Question: What does our master say concerning a man who arrives while the imam is praying the Asr prayer with the people during the time of Dhuhr, and the latecomer knows that the imam is praying Asr? Does he intend Dhuhr with the imam, or Asr? Or does he pray Asr and Dhuhr apart from the imam?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'question what does our master say concerning a man who arrives while the imam is praying the asr prayer with the people during the time of dhuhr and the latecomer knows that the imam is praying asr does he intend dhuhr with the imam or asr or does he pray asr and dhuhr apart from the imam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 39, NULL, 'Answer: If he enters while the imam is in the Asr prayer and the time of Dhuhr is still possible, he intends Dhuhr with him. If the time of Dhuhr has passed, he prays Asr with the imam if he wishes and then makes up Dhuhr. In praying with the imam there is a merit that is encouraged.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'answer if he enters while the imam is in the asr prayer and the time of dhuhr is still possible he intends dhuhr with him if the time of dhuhr has passed he prays asr with the imam if he wishes and then makes up dhuhr in praying with the imam there is a merit that is encouraged', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 40, NULL, 'Question: Concerning the worshipper who prays the obligatory Dhuhr prayer and then departs while the optional prayer is still owed by him, and becomes occupied until the end of the time of Dhuhr, then wishes to pray it: is it a performance in its time or a making up?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'question concerning the worshipper who prays the obligatory dhuhr prayer and then departs while the optional prayer is still owed by him and becomes occupied until the end of the time of dhuhr then wishes to pray it is it a performance in its time or a making up', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 41, NULL, 'Answer: Our master Malik al-Jami said: if a portion of the time remains, he prays the optional prayer as a performance in its time.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'answer our master malik al jami said if a portion of the time remains he prays the optional prayer as a performance in its time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 42, NULL, 'Question: Concerning one who enters the mosque at the declining of the sun and prays the prayer of the declining — six rakahs — and then remembers that sunnah prayers are owed by him from before which he had missed: is it incumbent upon him to make up those sunnah prayers between the prayer of the declining and the obligatory Dhuhr prayer, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'question concerning one who enters the mosque at the declining of the sun and prays the prayer of the declining six rakahs and then remembers that sunnah prayers are owed by him from before which he had missed is it incumbent upon him to make up those sunnah prayers between the prayer of the declining and the obligatory dhuhr prayer or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 43, NULL, 'Answer: If he prayed the sunnah of the Dhuhr prayer at the first of its time, there is no harm in his making up the sunnah prayers between it and the obligatory prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'answer if he prayed the sunnah of the dhuhr prayer at the first of its time there is no harm in his making up the sunnah prayers between it and the obligatory prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 44, NULL, 'Question: If prayer within its appointed time is a performance in its time, and upon the passing of the times it is a making up, then how does the worshipper intend the sunnah of Maghrib, seeing that it is not prayed except after the time of Maghrib has passed?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'question if prayer within its appointed time is a performance in its time and upon the passing of the times it is a making up then how does the worshipper intend the sunnah of maghrib seeing that it is not prayed except after the time of maghrib has passed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 45, NULL, 'Answer: The sunnah of Maghrib is prayed as a performance in its time after the obligatory prayer, provided that nothing separates the two. And if there was some slight matter and he returned while the congregation had not yet finished the sunnah of Maghrib, he prays it as a performance in its time.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'answer the sunnah of maghrib is prayed as a performance in its time after the obligatory prayer provided that nothing separates the two and if there was some slight matter and he returned while the congregation had not yet finished the sunnah of maghrib he prays it as a performance in its time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 46, NULL, 'Question: Concerning the worshipper who prays the prayer of the declining as a performance in its time, and when he has finished remembers that a prayer of the declining is owed by him as a making up: is it incumbent upon him to convert what he has already prayed into the making up and begin the performance afresh, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'question concerning the worshipper who prays the prayer of the declining as a performance in its time and when he has finished remembers that a prayer of the declining is owed by him as a making up is it incumbent upon him to convert what he has already prayed into the making up and begin the performance afresh or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 47, NULL, 'Answer: That is not established. Rather, he makes up the one he missed.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'answer that is not established rather he makes up the one he missed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 48, NULL, 'Another matter: whoever prays what he wishes between the obligatory later Isha prayer and its optional prayer, and then prays the optional prayer, does not intend it as a making up, because it is called the night prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'another matter whoever prays what he wishes between the obligatory later isha prayer and its optional prayer and then prays the optional prayer does not intend it as a making up because it is called the night prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 49, NULL, 'Question: Concerning the making up of missed prayers at the rising of the sun, at its setting, and at its standing at the meridian, and the offering of voluntary prayer at these times on the day of Friday: is that permissible or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'question concerning the making up of missed prayers at the rising of the sun at its setting and at its standing at the meridian and the offering of voluntary prayer at these times on the day of friday is that permissible or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 50, NULL, 'Answer: That is disliked (مَكْرُوه) on Friday and on other days as well.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'answer that is disliked مكروه on friday and on other days as well', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 51, NULL, 'Another matter: whoever prays the later Isha prayer with the imam while Maghrib is owed by him proceeds in the following order:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'another matter whoever prays the later isha prayer with the imam while maghrib is owed by him proceeds in the following order', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 52, NULL, 'He makes up Maghrib first. He makes up the sunnah of Maghrib and the later Isha as a making up. He prays the optional prayer of the later Isha as a performance in its time until the middle of the night — and it is called the night prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'he makes up maghrib first he makes up the sunnah of maghrib and the later isha as a making up he prays the optional prayer of the later isha as a performance in its time until the middle of the night and it is called the night prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 53, NULL, 'And whoever prays the Dhuhr prayer while Fajr is owed by him proceeds as follows:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'and whoever prays the dhuhr prayer while fajr is owed by him proceeds as follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 54, NULL, 'He makes up Fajr first. Then the sunnah of Dhuhr. Then the optional prayer of Dhuhr as a making up.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'he makes up fajr first then the sunnah of dhuhr then the optional prayer of dhuhr as a making up', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 55, NULL, 'Question: A man abandoned the prescribed prayer in the days of his youth and repented after a long period. How does he act? Does he perform the obligatory prayers for their times, or does he also pray the sunnah prayers and the optional prayers?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'question a man abandoned the prescribed prayer in the days of his youth and repented after a long period how does he act does he perform the obligatory prayers for their times or does he also pray the sunnah prayers and the optional prayers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 56, NULL, 'Answer: Everyone who abandons the prescribed prayers for a long period without excuse is not counted a Muslim during that period, because of the saying of the Prophet:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'answer everyone who abandons the prescribed prayers for a long period without excuse is not counted a muslim during that period because of the saying of the prophet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 57, NULL, 'Sayingمَا بَيْنَ الْعَبْدِ وَالْكُفْرِ إِلَّا تَرْكُ الصَّلَاةِ"There is nothing between the servant and disbelief except the abandonment of prayer."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingما بين العبد والكفر الا ترك الصلاه there is nothing between the servant and disbelief except the abandonment of prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 58, NULL, 'And no deed of the legitimate deeds is accepted from him, because of the saying of our master, the Commander of the Faithful, Ali ibn Abi Talib (ع):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'and no deed of the legitimate deeds is accepted from him because of the saying of our master the commander of the faithful ali ibn abi talib ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 59, NULL, 'Sayingاَلصَّلَاةُ عَمُودُ الدِّينِ وَهِيَ أَوَّلُ مَا يَنْظُرُ اللهُ فِيهِ مِنْ عَمَلِ ابْنِ آدَمَ فَإِنْ صَحَّتْ نَظَرَ فِي بَاقِي عَمَلِهِ وَإِنْ لَمْ تَصِحَّ لَمْ يَنْظُرْ لَهُ فِي عَمَلٍ', '', 'اَلصَّلَاةُ عَمُودُ الدِّينِ وَهِيَ أَوَّلُ مَا يَنْظُرُ اللهُ فِيهِ مِنْ عَمَلِ ابْنِ آدَمَ فَإِنْ صَحَّتْ نَظَرَ فِي بَاقِي عَمَلِهِ وَإِنْ لَمْ تَصِحَّ لَمْ يَنْظُرْ لَهُ فِي عَمَلٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingالصلاه عمود الدين وهي اول ما ينظر الله فيه من عمل ابن ادم فان صحت نظر في باقي عمله وان لم تصح لم ينظر له في عمل', 'الصلاه عمود الدين وهي اول ما ينظر الله فيه من عمل ابن ادم فان صحت نظر في باقي عمله وان لم تصح لم ينظر له في عمل');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 60, NULL, 'Sayingلَا حَظَّ فِي الْإِسْلَامِ لِمَنْ تَرَكَ الصَّلَاةَ"There is no share in Islam for one who abandons prayer."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingلا حظ في الاسلام لمن ترك الصلاه there is no share in islam for one who abandons prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 61, NULL, 'By "disbelief" I mean here that nothing is accepted from the one who abandons prayer, since he stands in the position of a disbeliever. But what does this imply in practice?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'by disbelief i mean here that nothing is accepted from the one who abandons prayer since he stands in the position of a disbeliever but what does this imply in practice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 62, NULL, 'Is the poll tax to be taken from him? Is he to be killed? Are his offspring taken captive? Is he considered ritually impure, as a disbeliever is? Is what he slaughters forbidden to eat?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'is the poll tax to be taken from him is he to be killed are his offspring taken captive is he considered ritually impure as a disbeliever is is what he slaughters forbidden to eat', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 63, NULL, 'In all these matters his ruling remains that of a Muslim, because the two testimonies of faith have placed him within the rulings of Islam.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'in all these matters his ruling remains that of a muslim because the two testimonies of faith have placed him within the rulings of islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 64, NULL, 'As for the one who finds himself in this condition and then repents — returning to the establishment of the prescribed prayer with a sincere intention toward God, seeking His good pleasure, without display and without hypocrisy — God turns to him in acceptance, for He says:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'as for the one who finds himself in this condition and then repents returning to the establishment of the prescribed prayer with a sincere intention toward god seeking his good pleasure without display and without hypocrisy god turns to him in acceptance for he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 65, NULL, 'Sayingيَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَّصُوحًا عَسَىٰ رَبُّكُمْ أَن يُكَفِّرَ عَنكُمْ سَيِّئَاتِكُمْ وَيُدْخِلَكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ"O you who believe, repent to God with a sincere repentance. It may be that your Lord will efface your evil deeds from you and admit you into gardens beneath which rivers flow."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingيا ايها الذين امنوا توبوا الي الله توبه نصوحا عسي ربكم ان يكفر عنكم سيياتكم ويدخلكم جنات تجري من تحتها الانهار o you who believe repent to god with a sincere repentance it may be that your lord will efface your evil deeds from you and admit you into gardens beneath which rivers flow', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 66, NULL, 'With that, he truly becomes a Muslim, and all his legitimate deeds are accepted. He is not required to make up the prayers he missed before his repentance; from that point on, he prays every prayer that falls due, together with its sunnah and optional prayers. Should he choose to make up the prescribed prayers he missed before his repentance and ask God''s forgiveness for those sins, he is rewarded for doing so. If, however, he had deliberately broken his fast during the daytime of Ramadan before his repentance — during the period in which he was abandoning the prescribed prayer — then making up those fasts and performing the expiation are both required of him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'with that he truly becomes a muslim and all his legitimate deeds are accepted he is not required to make up the prayers he missed before his repentance from that point on he prays every prayer that falls due together with its sunnah and optional prayers should he choose to make up the prescribed prayers he missed before his repentance and ask gods forgiveness for those sins he is rewarded for doing so if however he had deliberately broken his fast during the daytime of ramadan before his repentance during the period in which he was abandoning the prescribed prayer then making up those fasts and performing the expiation are both required of him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 67, NULL, 'As for one who misses an obligatory prayer, or several obligatory prayers, out of necessity while otherwise constant in his prayer: he does not perform the sunnah or optional prayers of the current prayer time until he has first made up the obligatory prayer he missed.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'as for one who misses an obligatory prayer or several obligatory prayers out of necessity while otherwise constant in his prayer he does not perform the sunnah or optional prayers of the current prayer time until he has first made up the obligatory prayer he missed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 68, NULL, 'The meaning of "O you who believe, repent to God with a sincere repentance" is: O you who have affirmed the two testimonies — that there is no god but God and that Muhammad is the Messenger of God. Faith in this verse is the affirming of those two testimonies.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the meaning of o you who believe repent to god with a sincere repentance is o you who have affirmed the two testimonies that there is no god but god and that muhammad is the messenger of god faith in this verse is the affirming of those two testimonies', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 69, NULL, 'One further matter: there is no harm in leaving the prayer when food is present, provided the prayer is not thereby missed, as the Prophet said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'one further matter there is no harm in leaving the prayer when food is present provided the prayer is not thereby missed as the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 70, NULL, 'Sayingإِذَا حَضَرَ الْعَشَاءُ تَرَكَ الْعِشَاءَ"When the evening meal is present, the evening prayer is set aside."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingاذا حضر العشاء ترك العشاء when the evening meal is present the evening prayer is set aside', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 71, NULL, 'This comes from the text of the book on the interpretation of the Pillars: a man may pray outside the prescribed time — meaning the later time — and what he missed of the earlier time would have been better for him than his family and his wealth.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'this comes from the text of the book on the interpretation of the pillars a man may pray outside the prescribed time meaning the later time and what he missed of the earlier time would have been better for him than his family and his wealth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 72, NULL, 'Mukhtasar al-Musannaf records the following rulings for one who wishes to join Dhuhr and Asr on account of some excuse:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'mukhtasar al musannaf records the following rulings for one who wishes to join dhuhr and asr on account of some excuse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 73, NULL, 'If he prays Dhuhr before the sun''s decline and prays Asr after it, he must repeat both prayers. If he prays Asr first after the sun''s decline and then prays Dhuhr after it, the Dhuhr prayer is valid but he must repeat the Asr. If he prays Dhuhr after the sun''s decline without ablution, then performs ablution and prays Asr, he must repeat both. If the Dhuhr prayer is rendered invalid for any reason whatsoever, praying Asr before it does not suffice him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'if he prays dhuhr before the suns decline and prays asr after it he must repeat both prayers if he prays asr first after the suns decline and then prays dhuhr after it the dhuhr prayer is valid but he must repeat the asr if he prays dhuhr after the suns decline without ablution then performs ablution and prays asr he must repeat both if the dhuhr prayer is rendered invalid for any reason whatsoever praying asr before it does not suffice him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 74, NULL, 'Whoever is in doubt about the time — because of cloud cover or any other reason — does not pray until he is certain; prayer at the end of the time with certainty is better than prayer at its beginning with doubt. Whoever prays part of his prayer, or all of it, before the time has entered, and then becomes certain of this, must repeat it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'whoever is in doubt about the time because of cloud cover or any other reason does not pray until he is certain prayer at the end of the time with certainty is better than prayer at its beginning with doubt whoever prays part of his prayer or all of it before the time has entered and then becomes certain of this must repeat it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 75, NULL, 'The reports state: whoever has missed a prayer prays it at whatever time he remembers it, except at the moment of sunrise, the moment when the sun stands at the meridian, or the moment of sunset. So it is mentioned in the reports.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the reports state whoever has missed a prayer prays it at whatever time he remembers it except at the moment of sunrise the moment when the sun stands at the meridian or the moment of sunset so it is mentioned in the reports', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 76, NULL, 'The reports further record that they agreed: there is no prayer after the Fajr prayer until the sun declines, unless one is making up a missed prayer or an obligatory prayer — such as:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the reports further record that they agreed there is no prayer after the fajr prayer until the sun declines unless one is making up a missed prayer or an obligatory prayer such as', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 77, NULL, 'the prayer of the state of consecration, the two rakahs of the circumambulation, the two festival prayers, and what resembles these.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the prayer of the state of consecration the two rakahs of the circumambulation the two festival prayers and what resembles these', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 78, NULL, 'They disapproved of voluntary prayer in that interval, except on Friday, concerning which they said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'they disapproved of voluntary prayer in that interval except on friday concerning which they said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 79, NULL, 'Sayingلَا تُسَعَّرُ فِيهَا النِّيرَانُ"The fires are not stoked on it."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingلا تسعر فيها النيران the fires are not stoked on it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 80, NULL, 'Mukhtasar al-Musannaf also states: there is no harm in a congregation who have missed the prayer making it up outside its time, with the call to prayer and the summons to stand, in congregation.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'mukhtasar al musannaf also states there is no harm in a congregation who have missed the prayer making it up outside its time with the call to prayer and the summons to stand in congregation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 81, NULL, 'Another matter, transmitted from a book of questions and answers found in the hand of our master Hasan ibn Abd al-Malik: as for what has come from him (ع), that on Friday voluntary prayer is permissible from the beginning of the day until the Asr prayer — together with praying Dhuhr at the first of its time and after an hour has passed — it is nonetheless not permissible for him to offer voluntary prayer after he has prayed the Asr prayer. For whoever prays Dhuhr and then offers voluntary prayer as he wishes until the end of the Asr prayer, once he has prayed Asr its time has passed, and it is not permissible for him to offer voluntary prayer thereafter.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'another matter transmitted from a book of questions and answers found in the hand of our master hasan ibn abd al malik as for what has come from him ع that on friday voluntary prayer is permissible from the beginning of the day until the asr prayer together with praying dhuhr at the first of its time and after an hour has passed it is nonetheless not permissible for him to offer voluntary prayer after he has prayed the asr prayer for whoever prays dhuhr and then offers voluntary prayer as he wishes until the end of the asr prayer once he has prayed asr its time has passed and it is not permissible for him to offer voluntary prayer thereafter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 82, NULL, 'The book of Clarification records that the Messenger of God joined Dhuhr and Asr, and Maghrib and Isha, without journey, without illness, and without any pressing cause.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the book of clarification records that the messenger of god joined dhuhr and asr and maghrib and isha without journey without illness and without any pressing cause', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 83, NULL, 'The aforementioned book of questions and answers also contains the following:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the aforementioned book of questions and answers also contains the following', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 84, NULL, 'Question: What do you say, O you who are entrusted with the divine mysteries, concerning the prayer of the middle of the night — two rakahs? Are they prayed after the two halves of the night, when the one rising wakes from sleep, or only at the precise midpoint?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'question what do you say o you who are entrusted with the divine mysteries concerning the prayer of the middle of the night two rakahs are they prayed after the two halves of the night when the one rising wakes from sleep or only at the precise midpoint', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 85, NULL, 'Answer: The time of the declining of the night is the more excellent.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'answer the time of the declining of the night is the more excellent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 86, NULL, 'Among the matters whose questions come from our master Sulayman ibn Hasan and whose answers come from our master Dawud (دَاوُد) ibn Ajab, it is recorded: "Your question concerns one who had cut himself off from prayer for a period of time, until God, glory be to Him, favored him with repentance and return, and who had not reckoned how much of it he had missed so as to make it up, and who perhaps prayed at some times and abandoned prayer at others without keeping guard over it. What is obligatory upon him? The answer is that if he repents with a sincere repentance and enters into the noble covenant, then he does not cut himself off from prayer thereafter, and there is no guilt upon him for what has passed; and whoever goes back to it, God will exact His retribution from him."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'among the matters whose questions come from our master sulayman ibn hasan and whose answers come from our master dawud داود ibn ajab it is recorded your question concerns one who had cut himself off from prayer for a period of time until god glory be to him favored him with repentance and return and who had not reckoned how much of it he had missed so as to make it up and who perhaps prayed at some times and abandoned prayer at others without keeping guard over it what is obligatory upon him the answer is that if he repents with a sincere repentance and enters into the noble covenant then he does not cut himself off from prayer thereafter and there is no guilt upon him for what has passed and whoever goes back to it god will exact his retribution from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 87, NULL, 'Our master and father Muhammad ibn al-Fahd ibn Salah also wrote on this subject in a letter. I now set down what that noble epistle contains, ascribing it to him without reservation; it is a path of guidance for those who seek guidance and a disclosure of what is obscure in the questions of fiqh among the matters of religion.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'our master and father muhammad ibn al fahd ibn salah also wrote on this subject in a letter i now set down what that noble epistle contains ascribing it to him without reservation it is a path of guidance for those who seek guidance and a disclosure of what is obscure in the questions of fiqh among the matters of religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 88, NULL, 'The first question. You asked — and may God the Exalted grant you success — about a man who died and bequeathed three letters'' weight of gold to whoever would make up on his behalf the prayers and the fast he had not performed, and you mentioned that this stated wage is small for the one who would undertake to make them up on his behalf. The answer to you in that — and God, glory be to Him, grants success in what is correct — is that the books of the friends of God record: whoever has missed a prayer owes, in order:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the first question you asked and may god the exalted grant you success about a man who died and bequeathed three letters weight of gold to whoever would make up on his behalf the prayers and the fast he had not performed and you mentioned that this stated wage is small for the one who would undertake to make them up on his behalf the answer to you in that and god glory be to him grants success in what is correct is that the books of the friends of god record whoever has missed a prayer owes in order', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 89, NULL, 'the making up of its obligatory portions, then the shaf and the witr, then the sunan.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the making up of its obligatory portions then the shaf and the witr then the sunan', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 90, NULL, 'If the stated wage suffices to make up all of that together with the making up of the mentioned fast, then let it discharge both. If it does not, the prayer is advanced before the obligatory fast, and what remains of the wage goes toward the making up of the mentioned fast to the measure of what remains of the stated wage. Nor is it hidden from you that if the deceased owes only the making up of prayer, then the obligatory prayers are made up first, then the shaf and the witr, then the sunan, to the measure of the wage, whether that be half of it, less, or more. And God, glory be to Him, is the Patron of pardon and of acceptance.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'if the stated wage suffices to make up all of that together with the making up of the mentioned fast then let it discharge both if it does not the prayer is advanced before the obligatory fast and what remains of the wage goes toward the making up of the mentioned fast to the measure of what remains of the stated wage nor is it hidden from you that if the deceased owes only the making up of prayer then the obligatory prayers are made up first then the shaf and the witr then the sunan to the measure of the wage whether that be half of it less or more and god glory be to him is the patron of pardon and of acceptance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 91, NULL, 'He, may God exalt his sanctity, said further in the epistle mentioned:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'he may god exalt his sanctity said further in the epistle mentioned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 92, NULL, 'The second question. You asked also — and may God, glory be to Him and exalted is He, grant you success in what pleases Him — about a woman who had children from a first husband, and who then married another man after him and bore a son by him. This later son killed her, not having reached puberty by his own account. When the matter of her killing was what it was and she died, her first children performed the Hajj on her behalf out of her property — the Hajj of Islam only, of all the religious obligations owed. Then her later son, the one who killed her, regretted what he had done, and he asked you:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the second question you asked also and may god glory be to him and exalted is he grant you success in what pleases him about a woman who had children from a first husband and who then married another man after him and bore a son by him this later son killed her not having reached puberty by his own account when the matter of her killing was what it was and she died her first children performed the hajj on her behalf out of her property the hajj of islam only of all the religious obligations owed then her later son the one who killed her regretted what he had done and he asked you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 93, NULL, 'what is obligatory upon him in the killing of her, what will deliver him before God, glory be to Him, from the consequence of that deed, what good he may do on her behalf whose reward will reach her, and likewise whether any portion of the blood money is binding upon him toward those brothers of hers who have been mentioned, or not.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'what is obligatory upon him in the killing of her what will deliver him before god glory be to him from the consequence of that deed what good he may do on her behalf whose reward will reach her and likewise whether any portion of the blood money is binding upon him toward those brothers of hers who have been mentioned or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 94, NULL, 'The answer to you in that also — and God, glory be to Him, grants success in what is correct — is that if his question is confined to what will deliver him before God, glory be to Him, from the consequence of that deed, then it is fitting that he undertake on her behalf her release and her discharge, which are known in the books of the friends of God (عَلَيْهِمُ السَّلَامُ). Then, as to what he wishes to convey to her of good deeds — whether a charity out of some of his property continuing upon the believers, or other than that of the doors of goodness and righteousness — then above all the Hajj, concerning which our master al-Sadiq, Imam Jafar ibn Muhammad (ع), spoke when one of his companions asked him about it and said to him:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the answer to you in that also and god glory be to him grants success in what is correct is that if his question is confined to what will deliver him before god glory be to him from the consequence of that deed then it is fitting that he undertake on her behalf her release and her discharge which are known in the books of the friends of god عليهم السلام then as to what he wishes to convey to her of good deeds whether a charity out of some of his property continuing upon the believers or other than that of the doors of goodness and righteousness then above all the hajj concerning which our master al sadiq imam jafar ibn muhammad ع spoke when one of his companions asked him about it and said to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 95, NULL, 'Sayingيَا بْنَ رَسُولِ اللهِ أَنَا رَجُلٌ مُوسِرٌ وَقَدْ حَجَجْتُ حِجَّةَ الإِسْلَامِ وَقَدْ سَمِعْتُ مَا فِي التَّطَوُّعِ بِالْحَجِّ مِنَ الرَّغَايِبِ فَهَلْ لِي أَنْ صَدَّقْتُ بِمِثْلِ نَفَقَةِ الْحَجِّ أَوْ أَكْثَرَ مِنْهَا ثَوَابُ الْحَجِّ، فَنَظَرَ عَلَيْهِ السَّلَامُ إِلَى جَبَلِ أَبِي قُبَيْسٍ وَقَالَ لَهُ: لَوْ صَدَّقْتَ بِوَزْنِ هَذَا مَا أَدْرَكْتَ ثَوَابَ الْحَجِّ.', '', 'يَا بْنَ رَسُولِ اللهِ أَنَا رَجُلٌ مُوسِرٌ وَقَدْ حَجَجْتُ حِجَّةَ الإِسْلَامِ وَقَدْ سَمِعْتُ مَا فِي التَّطَوُّعِ بِالْحَجِّ مِنَ الرَّغَايِبِ فَهَلْ لِي أَنْ صَدَّقْتُ بِمِثْلِ نَفَقَةِ الْحَجِّ أَوْ أَكْثَرَ مِنْهَا ثَوَابُ الْحَجِّ، فَنَظَرَ عَلَيْهِ السَّلَامُ إِلَى جَبَلِ أَبِي قُبَيْسٍ وَقَالَ لَهُ: لَوْ صَدَّقْتَ بِوَزْنِ هَذَا مَا أَدْرَكْتَ ثَوَابَ الْحَجِّ.', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingيا بن رسول الله انا رجل موسر وقد حججت حجه الاسلام وقد سمعت ما في التطوع بالحج من الرغايب فهل لي ان صدقت بمثل نفقه الحج او اكثر منها ثواب الحج فنظر عليه السلام الي جبل ابي قبيس وقال له لو صدقت بوزن هذا ما ادركت ثواب الحج', 'يا بن رسول الله انا رجل موسر وقد حججت حجه الاسلام وقد سمعت ما في التطوع بالحج من الرغايب فهل لي ان صدقت بمثل نفقه الحج او اكثر منها ثواب الحج فنظر عليه السلام الي جبل ابي قبيس وقال له لو صدقت بوزن هذا ما ادركت ثواب الحج');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 96, NULL, 'He is rewarded for what he does, and his reward comes back to him through that deed by virtue of the mercy God — glory be to Him — bestows upon him. This applies provided she was a believing woman who prayed. If she was neither a believer nor one who prayed, he makes up her prayer on her behalf, for prayer is the first of the son of Adam''s deeds that God — glory be to Him — looks at. If it is sound, He looks into the rest of his deeds; if it is not sound, He does not look at him in any deed. His making up of her prayer is according to whatever he is capable of — all of the obligatory prayers, or some of them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'he is rewarded for what he does and his reward comes back to him through that deed by virtue of the mercy god glory be to him bestows upon him this applies provided she was a believing woman who prayed if she was neither a believer nor one who prayed he makes up her prayer on her behalf for prayer is the first of the son of adams deeds that god glory be to him looks at if it is sound he looks into the rest of his deeds if it is not sound he does not look at him in any deed his making up of her prayer is according to whatever he is capable of all of the obligatory prayers or some of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 97, NULL, 'Sayingوَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ', '', 'وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingومن يعمل مثقال ذره خيرا يره ومن يعمل مثقال ذره شرا يره', 'ومن يعمل مثقال ذره خيرا يره ومن يعمل مثقال ذره شرا يره');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 98, NULL, 'Whoever does an atom''s weight of good will see it, and whoever does an atom''s weight of evil will see it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'whoever does an atoms weight of good will see it and whoever does an atoms weight of evil will see it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 99, NULL, 'He, may God exalt his sanctity, then spoke on the matter of blood money, and I shall bring that forward in its proper place, God willing.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'he may god exalt his sanctity then spoke on the matter of blood money and i shall bring that forward in its proper place god willing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 100, NULL, 'Our master the Judge al-Numan ibn Muhammad, may God exalt his sanctity and multiply his intimacy, said in a letter he wrote to one of the judges, in reply to questions that judge had put to him — among them this: As for what you asked about the time of Dhuhr and Asr — when the sun declines, its time has entered, and one is not prevented from the Asr prayer within it in the presence; and that is the beginning of the seventh hour.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'our master the judge al numan ibn muhammad may god exalt his sanctity and multiply his intimacy said in a letter he wrote to one of the judges in reply to questions that judge had put to him among them this as for what you asked about the time of dhuhr and asr when the sun declines its time has entered and one is not prevented from the asr prayer within it in the presence and that is the beginning of the seventh hour', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 101, NULL, 'He said in the book of the interpretation of the Sharia: Whoever forgets a prayer, let him pray it when he remembers it, for that is its time.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'he said in the book of the interpretation of the sharia whoever forgets a prayer let him pray it when he remembers it for that is its time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 102, NULL, 'He said in it: The times of prayer are five — hidden, not known except by some indication other than themselves. The time of Dhuhr is when the shadow of everything becomes its own length; the time of Asr is when the shadow of everything becomes twice its length; the time of the Maghrib prayer is at the setting of the sun''s disc; the time of Isha al-Akhirah is at the vanishing of the white twilight; and the time of the Fajr prayer runs from the breaking of dawn until the sun is about to rise. These are five times for five prayers. The times are hidden and imperceptible, while the prayers are manifest, being movements that are sensed and stillnesses that are felt. So these make ten, present in every day and night: five outward and five inward.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'he said in it the times of prayer are five hidden not known except by some indication other than themselves the time of dhuhr is when the shadow of everything becomes its own length the time of asr is when the shadow of everything becomes twice its length the time of the maghrib prayer is at the setting of the suns disc the time of isha al akhirah is at the vanishing of the white twilight and the time of the fajr prayer runs from the breaking of dawn until the sun is about to rise these are five times for five prayers the times are hidden and imperceptible while the prayers are manifest being movements that are sensed and stillnesses that are felt so these make ten present in every day and night five outward and five inward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 103, NULL, 'He said in it that prayer has four boundaries, like the boundaries of a house:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'he said in it that prayer has four boundaries like the boundaries of a house', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 104, NULL, 'the time the qibla the wudu the intention', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the time the qibla the wudu the intention', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 105, NULL, 'He said in it: The obligatory elements of prayer are seven:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'he said in it the obligatory elements of prayer are seven', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 106, NULL, 'the takbir the recitation the bowing the prostration the glorification the tashahhud the sealing', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the takbir the recitation the bowing the prostration the glorification the tashahhud the sealing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 107, NULL, 'He said in it: Prayer is not permitted except in its time. He said in it: The Fajr prayer is performed in the last darkness of the night. He said in it: The Maghrib prayer is at the falling of the disc. He said in it: The Prophet said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'he said in it prayer is not permitted except in its time he said in it the fajr prayer is performed in the last darkness of the night he said in it the maghrib prayer is at the falling of the disc he said in it the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 108, NULL, 'Sayingإِذَا اشْتَدَّ الْحَرُّ فَأَبْرِدُوا بِالظُّهْرِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ لَفْحِ جَهَنَّمَ"When the heat grows severe, wait for the cool for the noon prayer, for the severity of the heat is from the scorching breath of Hell."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingاذا اشتد الحر فابردوا بالظهر فان شده الحر من لفح جهنم when the heat grows severe wait for the cool for the noon prayer for the severity of the heat is from the scorching breath of hell', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 109, NULL, 'He said in it: Imam al-Muizz li-Din Allah (ع) was asked about the Fajr prayer, whether it belongs to the prayer of the night or to the prayer of the day. He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'he said in it imam al muizz li din allah ع was asked about the fajr prayer whether it belongs to the prayer of the night or to the prayer of the day he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 110, NULL, 'Sayingلَا مِنْ صَلَاةِ اللَّيْلِ وَلَا مِنْ صَلَاةِ النَّهَارِ، لِأَنَّهَا لَوْ كَانَتْ مِنْ صَلَاةِ اللَّيْلِ لَكَانَ يَجُوزُ لِلصَّائِمِ أَنْ يَأْكُلَ وَقْتَ الصَّلَاةِ، وَلَوْ كَانَتْ مِنْ صَلَاةِ النَّهَارِ لَمَا جَهَرَ فِيهَا بِالْقِرَاءَةِ، وَذَلِكَ لِأَنَّ الصَّلَوَاتِ خَمْسٌ: صَلَاتَانِ مِنْ قِسْمِ النَّهَارِ وَصَلَاتَانِ مِنْ قِسْمِ اللَّيْلِ وَصَلَاةٌ مُتَوَسِّطَةٌ بَيْنَ الصَّلَوَاتِ الْأَرْبَعِ لَا مِنْ قِسْمَةِ اللَّيْلِ وَلَا مِنْ قِسْمَةِ النَّهَارِ، وَهَٰذِهِ الْحِكْمَةُ الْبَالِغَةُ.', '', 'لَا مِنْ صَلَاةِ اللَّيْلِ وَلَا مِنْ صَلَاةِ النَّهَارِ، لِأَنَّهَا لَوْ كَانَتْ مِنْ صَلَاةِ اللَّيْلِ لَكَانَ يَجُوزُ لِلصَّائِمِ أَنْ يَأْكُلَ وَقْتَ الصَّلَاةِ، وَلَوْ كَانَتْ مِنْ صَلَاةِ النَّهَارِ لَمَا جَهَرَ فِيهَا بِالْقِرَاءَةِ، وَذَلِكَ لِأَنَّ الصَّلَوَاتِ خَمْسٌ: صَلَاتَانِ مِنْ قِسْمِ النَّهَارِ وَصَلَاتَانِ مِنْ قِسْمِ اللَّيْلِ وَصَلَاةٌ مُتَوَسِّطَةٌ بَيْنَ الصَّلَوَاتِ الْأَرْبَعِ لَا مِنْ قِسْمَةِ اللَّيْلِ وَلَا مِنْ قِسْمَةِ النَّهَارِ، وَهَٰذِهِ الْحِكْمَةُ الْبَالِغَةُ.', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingلا من صلاه الليل ولا من صلاه النهار لانها لو كانت من صلاه الليل لكان يجوز للصايم ان ياكل وقت الصلاه ولو كانت من صلاه النهار لما جهر فيها بالقراءه وذلك لان الصلوات خمس صلاتان من قسم النهار وصلاتان من قسم الليل وصلاه متوسطه بين الصلوات الاربع لا من قسمه الليل ولا من قسمه النهار وهذه الحكمه البالغه', 'لا من صلاه الليل ولا من صلاه النهار لانها لو كانت من صلاه الليل لكان يجوز للصايم ان ياكل وقت الصلاه ولو كانت من صلاه النهار لما جهر فيها بالقراءه وذلك لان الصلوات خمس صلاتان من قسم النهار وصلاتان من قسم الليل وصلاه متوسطه بين الصلوات الاربع لا من قسمه الليل ولا من قسمه النهار وهذه الحكمه البالغه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 111, NULL, 'Sayingوَصَلَاةُ الْفَجْرِ فَرِيضَتُهَا رَكْعَتَانِ بَعْدَ السُّنَّةِ، لِأَنَّهَا دَعْوَةٌ بَعْدَ دَعْوَةٍ مُتَقَدِّمَةٍ وَلَيْسَ بَعْدَهَا دَعْوَةٌ، لِذَلِكَ لَا صَلَاةَ بَعْدَهَا."It is neither of the night prayer nor of the day prayer — for if it belonged to the night prayer, the fasting person would be permitted to eat at its time; and if it belonged to the day prayer, the recitation would not be made aloud in it. The prayers are five: two from the portion of the day, two from the portion of the night, and one set midway between all four, belonging to neither the night''s division nor the day''s division. This is the far-reaching wisdom. The obligatory portion of the Fajr prayer is two units following the sunnah, for it is a call that comes after a preceding call, yet with no call after it — and that is why there is no prayer after it."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingوصلاه الفجر فريضتها ركعتان بعد السنه لانها دعوه بعد دعوه متقدمه وليس بعدها دعوه لذلك لا صلاه بعدها it is neither of the night prayer nor of the day prayer for if it belonged to the night prayer the fasting person would be permitted to eat at its time and if it belonged to the day prayer the recitation would not be made aloud in it the prayers are five two from the portion of the day two from the portion of the night and one set midway between all four belonging to neither the nights division nor the days division this is the far reaching wisdom the obligatory portion of the fajr prayer is two units following the sunnah for it is a call that comes after a preceding call yet with no call after it and that is why there is no prayer after it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 112, NULL, 'Then he said: In the night prayer, the recitation is made aloud. Then he said: Every prayer in which the recitation is made aloud belongs to the night prayer and its portion. Then he said: The Prophet said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'then he said in the night prayer the recitation is made aloud then he said every prayer in which the recitation is made aloud belongs to the night prayer and its portion then he said the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 113, NULL, 'Sayingصَلَاةُ الْغَدَاةِ يَحْضُرُهَا مَلَائِكَةُ اللَّيْلِ وَمَلَائِكَةُ النَّهَارِ"The morning prayer is attended by the angels of the night and the angels of the day."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingصلاه الغداه يحضرها ملايكه الليل وملايكه النهار the morning prayer is attended by the angels of the night and the angels of the day', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 114, NULL, 'Our master Jafar ibn Mansur al-Yaman, may God exalt his sanctity, said in the Book of the Inward Nursing: The time of the first prayer is seven hours of the day. After setting forth the inward meaning of this, he continued: Likewise, the time of Asr follows the time of the first prayer and comes after it. He then said: There are no voluntary prayers after Asr. After it, he said, comes the Isha prayer — by which he meant the Maghrib. After that, he said, comes the prayer of the darkness. He said: The time of the prayer of the darkness begins after the twilight has vanished. Then, after further words, he said: After the night prayer comes the witr prayer, and it consists of three units. In the first unit, after the surah of al-Hamd, one particular surah is recited and no other surah of the Quran — and it is:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'our master jafar ibn mansur al yaman may god exalt his sanctity said in the book of the inward nursing the time of the first prayer is seven hours of the day after setting forth the inward meaning of this he continued likewise the time of asr follows the time of the first prayer and comes after it he then said there are no voluntary prayers after asr after it he said comes the isha prayer by which he meant the maghrib after that he said comes the prayer of the darkness he said the time of the prayer of the darkness begins after the twilight has vanished then after further words he said after the night prayer comes the witr prayer and it consists of three units in the first unit after the surah of al hamd one particular surah is recited and no other surah of the quran and it is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 115, NULL, 'Sayingسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى الَّذِي خَلَقَ فَسَوَّى"Glorify the name of your Lord, the Most High, who created and gave order."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingسبح اسم ربك الاعلي الذي خلق فسوي glorify the name of your lord the most high who created and gave order', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 116, NULL, 'Then he said: In the second unit, after al-Hamd, he recites:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'then he said in the second unit after al hamd he recites', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 117, NULL, 'Sayingقُلْ يَا أَيُّهَا الْكَافِرُونَ"Say: O you who disbelieve."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'sayingقل يا ايها الكافرون say o you who disbelieve', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 118, NULL, 'Then he said: As for the third unit, after the surah of al-Hamd he recites the surah of sincerity in particular and not the other surahs — and it is:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'then he said as for the third unit after the surah of al hamd he recites the surah of sincerity in particular and not the other surahs and it is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 119, NULL, 'Al-Ikhlas: 1قُلْ هُوَ اللَّهُ أَحَدٌ"Say: He is God, One."', '', NULL, 'Al-Ikhlas: 1', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'al ikhlas 1قل هو الله احد say he is god one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 120, NULL, 'Then he said: In it is the qunut — the qunut of the witr. After bowing and raising his head, the one praying spreads out his hands and supplicates while standing, with the supplication of the qunut. Then he said: After these three units of the witr there is a separation, and then come two units that the one praying performs while seated in both of them. Then he said: In these two seated units he recites these two surahs — the surah:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'then he said in it is the qunut the qunut of the witr after bowing and raising his head the one praying spreads out his hands and supplicates while standing with the supplication of the qunut then he said after these three units of the witr there is a separation and then come two units that the one praying performs while seated in both of them then he said in these two seated units he recites these two surahs the surah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 121, NULL, 'Al-Falaq: 1قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ"Say: I take refuge with the Lord of the daybreak,"', '', NULL, 'Al-Falaq: 1', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'al falaq 1قل اعوذ برب الفلق say i take refuge with the lord of the daybreak', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 122, NULL, 'in the first unit, and:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'in the first unit and', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 123, NULL, 'An-Nas: 1قُلْ أَعُوذُ بِرَبِّ النَّاسِ"Say: I take refuge with the Lord of mankind,"', '', NULL, 'An-Nas: 1', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'an nas 1قل اعوذ برب الناس say i take refuge with the lord of mankind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 124, NULL, 'in the second — these two surahs specifically, and no others. Then he said: And then the dawn prayer. Then he said: It is the middle prayer, of which God said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'in the second these two surahs specifically and no others then he said and then the dawn prayer then he said it is the middle prayer of which god said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 125, NULL, 'Al-Baqarah: 238حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى وَقُومُوا لِلَّهِ قَانِتِينَ"Guard strictly the prayers and the middle prayer, and stand before God in devout obedience."', '', NULL, 'Al-Baqarah: 238', NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'al baqarah 238حافظوا علي الصلوات والصلاه الوسطي وقوموا لله قانتين guard strictly the prayers and the middle prayer and stand before god in devout obedience', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 126, NULL, 'The qunut is in the dawn prayer. Then he said: It consists of four units — two voluntary and two obligatory.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the qunut is in the dawn prayer then he said it consists of four units two voluntary and two obligatory', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 127, NULL, 'The author of the Hidden Epistle, may God sanctify his spirit, wrote in it: God, mighty and exalted, has laid five prayers upon His servants across the day and night — seventeen units in all — and He has commanded them to observe these prayers with care. The Fajr prayer extends from the first break of morning until sunrise. The first prayer falls at the seventh hour of the day, at the declining of the sun from its rising to its setting. The Asr prayer falls at the ninth hour — that is, when the shadow of everything has become twice its length. The Maghrib prayer falls at the setting of the sun and the appearance of darkness. The Isha al-Akhirah falls when the twilight has vanished and darkness has settled. These are the outward times in which God the Exalted has commanded you to stand before Him in devout obedience.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the author of the hidden epistle may god sanctify his spirit wrote in it god mighty and exalted has laid five prayers upon his servants across the day and night seventeen units in all and he has commanded them to observe these prayers with care the fajr prayer extends from the first break of morning until sunrise the first prayer falls at the seventh hour of the day at the declining of the sun from its rising to its setting the asr prayer falls at the ninth hour that is when the shadow of everything has become twice its length the maghrib prayer falls at the setting of the sun and the appearance of darkness the isha al akhirah falls when the twilight has vanished and darkness has settled these are the outward times in which god the exalted has commanded you to stand before him in devout obedience', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 128, NULL, 'He wrote in it: There is no prayer after Asr until the sun sets. He wrote in it: And there is no prayer between the adhan and the iqamah of the Maghrib prayer, as one prays between the adhan and iqamah of the four prayers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'he wrote in it there is no prayer after asr until the sun sets he wrote in it and there is no prayer between the adhan and the iqamah of the maghrib prayer as one prays between the adhan and iqamah of the four prayers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 129, NULL, 'In the book of questions from the most eminent Shaykh Shimon ibn Muhammad Ghuri al-Hindi (رض), with answers by our master Badr al-Din Hasan ibn Idris:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'in the book of questions from the most eminent shaykh shimon ibn muhammad ghuri al hindi رض with answers by our master badr al din hasan ibn idris', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 130, NULL, 'The question: What do you say, O you who are entrusted with the divine secrets, concerning the prayer of two units in the middle of the night? Is it prayed once both halves of the night have passed, when the one who rises wakes from sleep, or only at the precise midpoint of the night?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the question what do you say o you who are entrusted with the divine secrets concerning the prayer of two units in the middle of the night is it prayed once both halves of the night have passed when the one who rises wakes from sleep or only at the precise midpoint of the night', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 131, NULL, 'The answer: The time of the declining of the night is more excellent.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the answer the time of the declining of the night is more excellent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 132, NULL, 'Our master and lord Hibat Allah ibn Ibrahim said, in his answer to questions from his slave and the lowliest of his servants, Muhammad Ali ibn Salih al-Badri — which he answered for him from the island of Yemen to the island of Hind in the year 1145 of the Hijra:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'our master and lord hibat allah ibn ibrahim said in his answer to questions from his slave and the lowliest of his servants muhammad ali ibn salih al badri which he answered for him from the island of yemen to the island of hind in the year 1145 of the hijra', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 133, NULL, 'Another question. O our master, may God perpetuate your support: it has come in the books of the radiant Sharia that the fasts men have missed are made up by men. But as for prayer, nothing has come concerning it. So, O our master, do women make up prayer on behalf of men, or not? May our master be gracious with a sufficient answer. And also: if a man has grown weak and is unable to make up what he has missed of prayer, does another make it up on his behalf, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'another question o our master may god perpetuate your support it has come in the books of the radiant sharia that the fasts men have missed are made up by men but as for prayer nothing has come concerning it so o our master do women make up prayer on behalf of men or not may our master be gracious with a sufficient answer and also if a man has grown weak and is unable to make up what he has missed of prayer does another make it up on his behalf or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the pillar of religion and its appointed hours', '13. The Pillar of Religion and Its Appointed Hours', 134, NULL, 'The answer to that, by the help of God the Exalted and the support of His friend and His full moon (عَلَيْهِمُ السَّلَامُ), is that the ruling on the making up of prayer is like the ruling on the fast: none makes it up on behalf of men except men. As for the man who is advanced in years and has reached an age that leaves him too weak for the making up of prayer, he prays as much as he is able, and another makes up on his behalf, and expiation is made. This applies once he has become bent and it is evident that his ability is slight.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 13 the pillar of religion and its appointed hours', 'the answer to that by the help of god the exalted and the support of his friend and his full moon عليهم السلام is that the ruling on the making up of prayer is like the ruling on the fast none makes it up on behalf of men except men as for the man who is advanced in years and has reached an age that leaves him too weak for the making up of prayer he prays as much as he is able and another makes up on his behalf and expiation is made this applies once he has become bent and it is evident that his ability is slight', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 0, NULL, 'I turn now to the adhan and the iqama.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'i turn now to the adhan and the iqama', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 1, NULL, 'In the book of questions and answers named at the outset — the one whose compiler arranged it according to the chapter order of Daaim al-Islam — the following is recorded.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'in the book of questions and answers named at the outset the one whose compiler arranged it according to the chapter order of daaim al islam the following is recorded', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 2, NULL, 'The question: What do you say about a man from among the people of the call whom a tyrannical sultan, or his agents, appoints to a position — whether as prayer leader in a mosque, muezzin, teacher, or some other role — paid from the proceeds of the port levy or the jizya, while the people know that the one who holds the port levy takes from their wealth whatever he sees fit, not what is rightfully due? Is it permissible for such a man to accept this position or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'the question what do you say about a man from among the people of the call whom a tyrannical sultan or his agents appoints to a position whether as prayer leader in a mosque muezzin teacher or some other role paid from the proceeds of the port levy or the jizya while the people know that the one who holds the port levy takes from their wealth whatever he sees fit not what is rightfully due is it permissible for such a man to accept this position or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 3, NULL, 'The answer: This comes from the public treasury (بَيْتُ الْمَال). If it is administered according to the judgment of one appointed by the friends of God, it is lawful for him to consume it; if not, it is not lawful.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'the answer this comes from the public treasury بيت المال if it is administered according to the judgment of one appointed by the friends of god it is lawful for him to consume it if not it is not lawful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 4, NULL, 'From Mukhtasar al-Idah, on the authority of Jafar ibn Muhammad ibn Ali (ع), concerning a man who gives the call to prayer while walking or mounted, he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'from mukhtasar al idah on the authority of jafar ibn muhammad ibn ali ع concerning a man who gives the call to prayer while walking or mounted he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 5, NULL, 'Sayingنَعَمْ إِذَا كَانَ وَقْتُ التَّشَهُّدِ مُسْتَقْبِلَ الْقِبْلَةِ فَلَا بَأْسَ', '', 'نَعَمْ إِذَا كَانَ وَقْتُ التَّشَهُّدِ مُسْتَقْبِلَ الْقِبْلَةِ فَلَا بَأْسَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingنعم اذا كان وقت التشهد مستقبل القبله فلا باس', 'نعم اذا كان وقت التشهد مستقبل القبله فلا باس');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 6, NULL, 'Yes; if at the moment of the testimony he is facing the direction of prayer, there is no harm in it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'yes if at the moment of the testimony he is facing the direction of prayer there is no harm in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 7, NULL, 'As far as I have learned, and as far as I have seen in what I have gathered from the books attributed to the Ahl al-Bayt (عَلَيْهِمُ السَّلَامُ), there is agreement that the iqama is not valid unless one is standing upon the ground.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'as far as i have learned and as far as i have seen in what i have gathered from the books attributed to the ahl al bayt عليهم السلام there is agreement that the iqama is not valid unless one is standing upon the ground', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 8, NULL, 'From the book Mukhtasar al-Musannaf: it is proper for the muezzin, when he says twice', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'from the book mukhtasar al musannaf it is proper for the muezzin when he says twice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 9, NULL, 'Sayingاَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ', '', 'اَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingاشهد ان محمدا رسول الله', 'اشهد ان محمدا رسول الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 10, NULL, 'I bear witness that Muhammad is the Messenger of God,', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'i bear witness that muhammad is the messenger of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 11, NULL, 'that he say within himself', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'that he say within himself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 12, NULL, 'Sayingاَشْهَدُ أَنَّ عَلِيًّا وَلِيُّ اللَّهِ', '', 'اَشْهَدُ أَنَّ عَلِيًّا وَلِيُّ اللَّهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingاشهد ان عليا ولي الله', 'اشهد ان عليا ولي الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 13, NULL, 'I bear witness that Ali is the friend of God.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'i bear witness that ali is the friend of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 14, NULL, 'And when he says twice', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'and when he says twice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 15, NULL, 'Sayingحَيَّ عَلَى خَيْرِ الْعَمَلِ', '', 'حَيَّ عَلَى خَيْرِ الْعَمَلِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingحي علي خير العمل', 'حي علي خير العمل');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 16, NULL, 'Come to the best of deeds — that he say within himself:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'come to the best of deeds that he say within himself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 17, NULL, 'Sayingآلُ مُحَمَّدٍ خَيْرُ الْبَشَرِ', '', 'آلُ مُحَمَّدٍ خَيْرُ الْبَشَرِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingال محمد خير البشر', 'ال محمد خير البشر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 18, NULL, 'The family of Muhammad are the best of humankind.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'the family of muhammad are the best of humankind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 19, NULL, 'That same book also states that it is not proper for anyone in the mosque, when the muezzin gives the call, to leave before praying — unless he leaves for a necessity and intends to return, knowing he will still reach the prayer; or unless he is without ablution, in which case he may leave to perform it and strive to return in time. If he does not reach the prayer, he prays alone, or with another congregation in another mosque, and no fault rests upon him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'that same book also states that it is not proper for anyone in the mosque when the muezzin gives the call to leave before praying unless he leaves for a necessity and intends to return knowing he will still reach the prayer or unless he is without ablution in which case he may leave to perform it and strive to return in time if he does not reach the prayer he prays alone or with another congregation in another mosque and no fault rests upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 20, NULL, 'The book Tawil al-Sharia states that it is permissible for the muezzin to give the call while not in a state of purity, but the iqama is not valid except from one who is pure. That book also states: he faces the direction of prayer and forms the intention first. It further states: the obligatory prayer is not prayed when the call has been given — it is prayed when the iqama has been given. The supererogatory prayer is joined to the adhan and the obligatory prayer to the iqama, with the supererogatory coming first. And that book records that the Prophet (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'the book tawil al sharia states that it is permissible for the muezzin to give the call while not in a state of purity but the iqama is not valid except from one who is pure that book also states he faces the direction of prayer and forms the intention first it further states the obligatory prayer is not prayed when the call has been given it is prayed when the iqama has been given the supererogatory prayer is joined to the adhan and the obligatory prayer to the iqama with the supererogatory coming first and that book records that the prophet ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 21, NULL, 'Sayingمَنْ أَحْرَمَ فَقَدْ دَخَلَ جَنَّةَ أَهْلِ الْحَقِّ', '', 'مَنْ أَحْرَمَ فَقَدْ دَخَلَ جَنَّةَ أَهْلِ الْحَقِّ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingمن احرم فقد دخل جنه اهل الحق', 'من احرم فقد دخل جنه اهل الحق');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 22, NULL, 'Whoever enters the sacred state of the prayer has entered the garden of the people of truth.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'whoever enters the sacred state of the prayer has entered the garden of the people of truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 23, NULL, 'Our sayyid and mawla Idris ibn Sayyidina Hasan recorded in his book known as Uyun al-Akhbar — in its sixth part, on the matter of the call to prayer with the testimony that our mawla Ali is the friend of God, and that Muhammad and Ali are the best of humankind and their kindred the best of kindred, in his account of our mawla the Commander of the Faithful al-Hakim bi-Amr Allah (ع) and his pure forefathers — these being his words:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'our sayyid and mawla idris ibn sayyidina hasan recorded in his book known as uyun al akhbar in its sixth part on the matter of the call to prayer with the testimony that our mawla ali is the friend of god and that muhammad and ali are the best of humankind and their kindred the best of kindred in his account of our mawla the commander of the faithful al hakim bi amr allah ع and his pure forefathers these being his words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 24, NULL, 'The muezzins gave the call in the time of the caliphate of the Commander of the Faithful al-Hakim bi-Amr Allah (ع), and they proclaimed in their call, after the testimony that Muhammad is the Messenger of God:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'the muezzins gave the call in the time of the caliphate of the commander of the faithful al hakim bi amr allah ع and they proclaimed in their call after the testimony that muhammad is the messenger of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 25, NULL, 'Sayingأَشْهَدُ أَنَّ مَوْلَانَا عَلِيًّا وَلِيُّ اللَّهِ', '', 'أَشْهَدُ أَنَّ مَوْلَانَا عَلِيًّا وَلِيُّ اللَّهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingاشهد ان مولانا عليا ولي الله', 'اشهد ان مولانا عليا ولي الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 26, NULL, 'I bear witness that our mawla Ali is the friend of God,', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'i bear witness that our mawla ali is the friend of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 27, NULL, 'in confirmation of the proclamation of the Prophet (ع) on the Day of Ghadir:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'in confirmation of the proclamation of the prophet ع on the day of ghadir', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 28, NULL, 'Sayingمَنْ كُنْتُ مَوْلَاهُ فَعَلِيٌّ مَوْلَاهُ', '', 'مَنْ كُنْتُ مَوْلَاهُ فَعَلِيٌّ مَوْلَاهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingمن كنت مولاه فعلي مولاه', 'من كنت مولاه فعلي مولاه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 29, NULL, 'Whoever''s master I am, Ali is his master.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'whoevers master i am ali is his master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 30, NULL, 'That was a declaration of loyalty to the Messenger and of the guardianship of his legatee, upon whom he had expressly conferred it and to whom he had pointed. Then they proclaimed in the call:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'that was a declaration of loyalty to the messenger and of the guardianship of his legatee upon whom he had expressly conferred it and to whom he had pointed then they proclaimed in the call', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 31, NULL, 'Sayingمُحَمَّدٌ وَعَلِيٌّ خَيْرُ الْبَشَرِ وَعِتْرَتُهُمَا خَيْرُ الْعِتَرِ', '', 'مُحَمَّدٌ وَعَلِيٌّ خَيْرُ الْبَشَرِ وَعِتْرَتُهُمَا خَيْرُ الْعِتَرِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingمحمد وعلي خير البشر وعترتهما خير العتر', 'محمد وعلي خير البشر وعترتهما خير العتر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 32, NULL, 'Muhammad and Ali are the best of humankind, and their kindred are the best of kindred.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'muhammad and ali are the best of humankind and their kindred are the best of kindred', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 33, NULL, 'This made plain the excellence of the Messenger of God, in whose glory they took pride, and who was raised from majesty to the highest of his rank. None was nearer to him than his brother and legatee Ali ibn Abi Talib, his daughter Fatima al-Zahra, his two grandsons al-Hasan and al-Husayn, and the pure Imams whom He chose from the progeny of His Messenger and made guides for His creation along the open road of His path. When Abdullah ibn Abbas was asked who the near kindred are, he said: Ali, and Fatima, and al-Hasan, and al-Husayn. For all his excellence, his learning, and his kinship, Abdullah ibn Abbas claimed it for no one else. The kindred of a man are his nearest folk; yet they relate from Abu Bakr ibn Abi Quhafa that he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'this made plain the excellence of the messenger of god in whose glory they took pride and who was raised from majesty to the highest of his rank none was nearer to him than his brother and legatee ali ibn abi talib his daughter fatima al zahra his two grandsons al hasan and al husayn and the pure imams whom he chose from the progeny of his messenger and made guides for his creation along the open road of his path when abdullah ibn abbas was asked who the near kindred are he said ali and fatima and al hasan and al husayn for all his excellence his learning and his kinship abdullah ibn abbas claimed it for no one else the kindred of a man are his nearest folk yet they relate from abu bakr ibn abi quhafa that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 34, NULL, 'Sayingنَحْنُ عِتْرَةُ رَسُولِ اللهِ', '', 'نَحْنُ عِتْرَةُ رَسُولِ اللهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingنحن عتره رسول الله', 'نحن عتره رسول الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 35, NULL, 'We are the kindred of the Messenger of God.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'we are the kindred of the messenger of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 36, NULL, 'By my life, Abu Bakr had no kinship with the Messenger (ع) except that he was of Quraysh — and that is remote when the lineage is traced. Ali and Fatima and al-Hasan and al-Husayn (عَلَيْهِمُ السَّلَامُ) are worthier and nearer than every one who kept his company and drew close. Al-Kumayt said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'by my life abu bakr had no kinship with the messenger ع except that he was of quraysh and that is remote when the lineage is traced ali and fatima and al hasan and al husayn عليهم السلام are worthier and nearer than every one who kept his company and drew close al kumayt said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 37, NULL, 'Sayingبَنِي هَاشِمٍ رَهْطَ النَّبِيِّ مُحَمَّدٍ وَلَهُمْ وَبِهِمْ أَرْضَى مِرَارًا وَأَغْضَبُ', '', 'بَنِي هَاشِمٍ رَهْطَ النَّبِيِّ مُحَمَّدٍ وَلَهُمْ وَبِهِمْ أَرْضَى مِرَارًا وَأَغْضَبُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingبني هاشم رهط النبي محمد ولهم وبهم ارضي مرارا واغضب', 'بني هاشم رهط النبي محمد ولهم وبهم ارضي مرارا واغضب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 38, NULL, 'The sons of Hashim are the clan of the Prophet Muhammad — for them and through them I am pleased, time and again, and for them I am angered.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'the sons of hashim are the clan of the prophet muhammad for them and through them i am pleased time and again and for them i am angered', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 39, NULL, 'This shows that they are his kin. We have already mentioned the near kindred and what has come from Ibn Abbas (رض) in that exposition.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'this shows that they are his kin we have already mentioned the near kindred and what has come from ibn abbas رض in that exposition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 40, NULL, 'Many among the common people have denied that Ali is the best of all humankind. They say: we grant that Muhammad is the best of humankind, but we do not grant the same of Ali, because among humankind there are prophets. This is a saying whose true meaning they have not grasped and whose grounds they have not understood — a saying of obstinacy, a feeble argument, refuted and turned back upon itself. All Muslims are agreed that the community of Muhammad is the best of communities, for the word of God Most High:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'many among the common people have denied that ali is the best of all humankind they say we grant that muhammad is the best of humankind but we do not grant the same of ali because among humankind there are prophets this is a saying whose true meaning they have not grasped and whose grounds they have not understood a saying of obstinacy a feeble argument refuted and turned back upon itself all muslims are agreed that the community of muhammad is the best of communities for the word of god most high', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'the disputed words of the call', '14. The Disputed Words of the Call', 41, NULL, 'Ali ''Imran: 110كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ', '', 'كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ', 'Ali ''Imran: 110', 3, 110, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'ali imran 110كنتم خير امه اخرجت للناس', 'كنتم خير امه اخرجت للناس');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 42, NULL, 'You were the best community brought forth for the people.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'you were the best community brought forth for the people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 43, NULL, 'And among the communities before them were prophets sent as messengers and friends of God given precedence. If they say that this is by way of figurative speech and magnification, we say as they say — and every transgressing sinner is brought to loss. The Prophet (ع) said, in the sound narration from him on the authority of Hudhayfa ibn al-Yaman and others:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'and among the communities before them were prophets sent as messengers and friends of god given precedence if they say that this is by way of figurative speech and magnification we say as they say and every transgressing sinner is brought to loss the prophet ع said in the sound narration from him on the authority of hudhayfa ibn al yaman and others', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 44, NULL, 'Sayingأني مخلف فيكم ما أن تمسكتم به لن تضلوا كتاب الله وعترتي أهل بيتي كسفينة نوح من ركبها نجى ومن تخلف عنها غرق', '', 'أني مخلف فيكم ما أن تمسكتم به لن تضلوا كتاب الله وعترتي أهل بيتي كسفينة نوح من ركبها نجى ومن تخلف عنها غرق', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingاني مخلف فيكم ما ان تمسكتم به لن تضلوا كتاب الله وعترتي اهل بيتي كسفينه نوح من ركبها نجي ومن تخلف عنها غرق', 'اني مخلف فيكم ما ان تمسكتم به لن تضلوا كتاب الله وعترتي اهل بيتي كسفينه نوح من ركبها نجي ومن تخلف عنها غرق');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 45, NULL, 'I leave behind among you that which, if you hold fast to it, you will never go astray: the Book of God and my kindred, the people of my house. They are like the ark of Noah: whoever boards it is saved, and whoever holds back from it is drowned.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'i leave behind among you that which if you hold fast to it you will never go astray the book of god and my kindred the people of my house they are like the ark of noah whoever boards it is saved and whoever holds back from it is drowned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 46, NULL, 'And he (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'and he ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 47, NULL, 'Sayingعَلِيٌّ خَيْرُ الْبَشَرِ مَنْ أَبَى ذَلِكَ فَقَدْ كَفَرَ', '', 'عَلِيٌّ خَيْرُ الْبَشَرِ مَنْ أَبَى ذَلِكَ فَقَدْ كَفَرَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingعلي خير البشر من ابي ذلك فقد كفر', 'علي خير البشر من ابي ذلك فقد كفر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 48, NULL, 'Ali is the best of humankind, and whoever refuses this has disbelieved.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'ali is the best of humankind and whoever refuses this has disbelieved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 49, NULL, 'That is sufficient guidance for the one whose path to truth has been opened. As for the community described as the best community ever raised up for humanity, its meaning has been explained by the Imams (عَلَيْهِمُ السَّلَامُ), as we have set out earlier in this book.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'that is sufficient guidance for the one whose path to truth has been opened as for the community described as the best community ever raised up for humanity its meaning has been explained by the imams عليهم السلام as we have set out earlier in this book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 50, NULL, 'In the narration transmitted through its chain from Ali ibn al-Husayn al-Qari, at the inhabited palace in Cairo, he said: I was with the Imam al-Hakim bi-Amr Allah, the Commander of the Faithful (ع), at al-Gharafa, by a mosque known as that of al-Qudai. He was standing there when he heard a great outcry and tumult. He said to one of his attendants: Go and see what this shouting and tumult is, and tell me of it. The young man went and returned and said: O our mawla, they are the people of Atfih, and they are split into two parties. He (ع) said: Bring them to me. The young man went and brought them. Among them was a black man who was clinging to another man and pressing him hard. He (ع) said to him: Release the man. So he released him. The Commander of the Faithful said to the black man: Who are you? He said: I am the preacher at Atfih. He said: And who is the other man? He said: He is the dai. He said: What has passed between you? He said: O our mawla, something has appeared in our town the like of which we have never heard at all. He said: And what is it? He said: He gave the call, and in his call he declared that Muhammad and Ali are the best of humankind, and their kindred the best of kindred. We never heard this call before now. It may be accepted that Muhammad (ع) is the best of humankind, but it cannot be accepted that Ali is the best of humankind — for among humankind are Adam, Noah, Abraham, Moses, and Jesus, and it cannot be accepted that he is better than these prophets, the possessors of the revealed laws.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'in the narration transmitted through its chain from ali ibn al husayn al qari at the inhabited palace in cairo he said i was with the imam al hakim bi amr allah the commander of the faithful ع at al gharafa by a mosque known as that of al qudai he was standing there when he heard a great outcry and tumult he said to one of his attendants go and see what this shouting and tumult is and tell me of it the young man went and returned and said o our mawla they are the people of atfih and they are split into two parties he ع said bring them to me the young man went and brought them among them was a black man who was clinging to another man and pressing him hard he ع said to him release the man so he released him the commander of the faithful said to the black man who are you he said i am the preacher at atfih he said and who is the other man he said he is the dai he said what has passed between you he said o our mawla something has appeared in our town the like of which we have never heard at all he said and what is it he said he gave the call and in his call he declared that muhammad and ali are the best of humankind and their kindred the best of kindred we never heard this call before now it may be accepted that muhammad ع is the best of humankind but it cannot be accepted that ali is the best of humankind for among humankind are adam noah abraham moses and jesus and it cannot be accepted that he is better than these prophets the possessors of the revealed laws', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 51, NULL, 'Our mawla (ع) said: I shall make it plain to you, O shaykh, that Ali (ع) is the best of humankind together with the Prophet (ع). Have you studied any of the hadith, O shaykh? He said: Yes, O Commander of the Faithful, a great deal. He said: Here is a report I bring to you; if it proves sound, confirm it, and if it proves false, refute it — so that I may bring you another. He said: Yes, O our mawla (ع).', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'our mawla ع said i shall make it plain to you o shaykh that ali ع is the best of humankind together with the prophet ع have you studied any of the hadith o shaykh he said yes o commander of the faithful a great deal he said here is a report i bring to you if it proves sound confirm it and if it proves false refute it so that i may bring you another he said yes o our mawla ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 52, NULL, 'He said: Ibn Khallad related to us from Sajja ibn Suwayd, who related it from al-Mamun al-Abbasi, from his father al-Rashid, from his father al-Mahdi, from his father al-Mansur, from Abdullah ibn Abbas, who said: One day we were gathered with the Messenger of God (ع), and he was speaking to us and teaching us the understanding of our religion, when his daughter Fatima al-Zahra (عَلَيْهِمُ السَّلَامُ) came to him with her eyes pouring out tears. The Prophet sprang up and said: O my daughter, what makes you weep? She said: O my father, I have lost my two sons al-Hasan and al-Husayn, and I feared my heart would split from the loss of them, O my father. He said: The Prophet raised his gaze to the heavens, grew tender, and prayed. Then Gabriel the Trustworthy descended upon him and said: O Muhammad, peace be upon you, do not be alarmed. The Peace sends you peace, and He says to you: your two sons al-Hasan and al-Husayn went to the enclosure of the Banu al-Najjar and played there, and sleep overcame them. So He sent to them an angel, kindly and gentle, who spread his right wing beneath them and covered them with his left — and so he found them and took charge of them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'he said ibn khallad related to us from sajja ibn suwayd who related it from al mamun al abbasi from his father al rashid from his father al mahdi from his father al mansur from abdullah ibn abbas who said one day we were gathered with the messenger of god ع and he was speaking to us and teaching us the understanding of our religion when his daughter fatima al zahra عليهم السلام came to him with her eyes pouring out tears the prophet sprang up and said o my daughter what makes you weep she said o my father i have lost my two sons al hasan and al husayn and i feared my heart would split from the loss of them o my father he said the prophet raised his gaze to the heavens grew tender and prayed then gabriel the trustworthy descended upon him and said o muhammad peace be upon you do not be alarmed the peace sends you peace and he says to you your two sons al hasan and al husayn went to the enclosure of the banu al najjar and played there and sleep overcame them so he sent to them an angel kindly and gentle who spread his right wing beneath them and covered them with his left and so he found them and took charge of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 53, NULL, 'The Messenger of God (ع) set out for the enclosure of the Banu al-Najjar, and his companions went with him. There he saw al-Hasan and al-Husayn (عَلَيْهِمُ السَّلَامُ) sleeping, with the angel seated beside them, guarding them by the command of God, mighty and majestic. The Prophet lifted them onto his shoulder, and Abu Bakr said: Let me carry them for you, O Messenger of God. He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'the messenger of god ع set out for the enclosure of the banu al najjar and his companions went with him there he saw al hasan and al husayn عليهم السلام sleeping with the angel seated beside them guarding them by the command of god mighty and majestic the prophet lifted them onto his shoulder and abu bakr said let me carry them for you o messenger of god he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 54, NULL, 'Sayingذرهما فنعم المطي مطيهما ونعم الراكبان هما وأبوهما خير منهما', '', 'ذرهما فنعم المطي مطيهما ونعم الراكبان هما وأبوهما خير منهما', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingذرهما فنعم المطي مطيهما ونعم الراكبان هما وابوهما خير منهما', 'ذرهما فنعم المطي مطيهما ونعم الراكبان هما وابوهما خير منهما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 55, NULL, 'Leave them be, for excellent is their mount, and excellent riders are they both, and their father is better than the two of them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'leave them be for excellent is their mount and excellent riders are they both and their father is better than the two of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 56, NULL, 'He carried them on his shoulders and quickened his steps, hurrying to bring the good news to Fatima (عَلَيْهِمُ السَّلَامُ), until he reached the mosque. There he came upon a group of people who had been alarmed by this. He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'he carried them on his shoulders and quickened his steps hurrying to bring the good news to fatima عليهم السلام until he reached the mosque there he came upon a group of people who had been alarmed by this he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 57, NULL, 'Sayingأَيُّهَا النَّاسُ أَنِّي أُخْبِرُكُمْ بِخَيْرِ النَّاسِ أَبًا وَأُمًّا هُمَا هَذَانِ الْحَسَنُ وَالْحُسَيْنُ أَبُوهُمَا عَلِيٌّ وَصِيِّي أَفْضَلُ الْوَصِيِّينَ وَأُمُّهُمَا فَاطِمَةُ ابْنَتِي أَفْضَلُ نِسَاءِ الْعَالَمِينَ أَلَا أُخْبِرُكُمْ بِخَيْرِ النَّاسِ جَدًّا وَجَدَّةً هَذَانِ الْحَسَنُ وَالْحُسَيْنُ جَدُّهُمَا رَسُولُ اللَّهِ وَجَدَّتُهُمَا خَدِيجَةُ أَوَّلُ مَنْ آمَنَ بِاللَّهِ وَرَسُولِهِ أَلَا أُخْبِرُكُمْ بِخَيْرِ النَّاسِ عَمًّا وَعَمَّةً"O people, I tell you who the best of people are in father and mother: they are these two — al-Hasan and al-Husayn. Their father is Ali, my legatee and the finest of all legatees; their mother is Fatima, my daughter and the finest of the women of the worlds. Shall I tell you who the best of people are in grandfather and grandmother? These two — al-Hasan and al-Husayn. Their grandfather is the Messenger of God, and their grandmother is Khadija, the first to believe in God and His Messenger. Shall I tell you who the best of people are in paternal uncle and paternal aunt?"', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingايها الناس اني اخبركم بخير الناس ابا واما هما هذان الحسن والحسين ابوهما علي وصيي افضل الوصيين وامهما فاطمه ابنتي افضل نساء العالمين الا اخبركم بخير الناس جدا وجده هذان الحسن والحسين جدهما رسول الله وجدتهما خديجه اول من امن بالله ورسوله الا اخبركم بخير الناس عما وعمه o people i tell you who the best of people are in father and mother they are these two al hasan and al husayn their father is ali my legatee and the finest of all legatees their mother is fatima my daughter and the finest of the women of the worlds shall i tell you who the best of people are in grandfather and grandmother these two al hasan and al husayn their grandfather is the messenger of god and their grandmother is khadija the first to believe in god and his messenger shall i tell you who the best of people are in paternal uncle and paternal aunt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 58, NULL, 'They said: Yes, O Messenger of God. He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'they said yes o messenger of god he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 59, NULL, 'Sayingهَذَانِ الْحَسَنُ وَالْحُسَيْنُ عَمُّهُمَا جَعْفَرُ بْنُ أَبِي طَالِبٍ وَعَمَّتُهُمَا أُمُّ هَانِيٍ بِنْتُ أَبِي طَالِبٍ مَا أَشْرَكَتْ بِاللهِ طَرْفَةَ عَيْنٍ أَلَا أُخْبِرُكُمْ بِخَيْرِ النَّاسِ خَالًا وَخَالَةً هَذَانِ الْحَسَنُ وَالْحُسَيْنُ خَالُهُمَا قَاسِمُ بْنُ رَسُولِ اللهِ وَخَالَتُهُمَا زَيْنَبُ بِنْتُ رَسُولِ اللهِ اللَّهُمَّ أَنَّكَ تَعْلَمُ اَنَّهُمَا وَأَبَاهُمَا وَأُمَّهُمَا وَجَدَّهُمَا وَجَدَّتَهُمَا وَخَالَهُمَا وَخَالَتَهُمَا وَعَمَّهُمَا وَعَمَّتَهُمَا وَشِيعَتَهُمَا وَمُحِبِّيهِمَا فِي الْجَنَّةِ', '', 'هَذَانِ الْحَسَنُ وَالْحُسَيْنُ عَمُّهُمَا جَعْفَرُ بْنُ أَبِي طَالِبٍ وَعَمَّتُهُمَا أُمُّ هَانِيٍ بِنْتُ أَبِي طَالِبٍ مَا أَشْرَكَتْ بِاللهِ طَرْفَةَ عَيْنٍ أَلَا أُخْبِرُكُمْ بِخَيْرِ النَّاسِ خَالًا وَخَالَةً هَذَانِ الْحَسَنُ وَالْحُسَيْنُ خَالُهُمَا قَاسِمُ بْنُ رَسُولِ اللهِ وَخَالَتُهُمَا زَيْنَبُ بِنْتُ رَسُولِ اللهِ اللَّهُمَّ أَنَّكَ تَعْلَمُ اَنَّهُمَا وَأَبَاهُمَا وَأُمَّهُمَا وَجَدَّهُمَا وَجَدَّتَهُمَا وَخَالَهُمَا وَخَالَتَهُمَا وَعَمَّهُمَا وَعَمَّتَهُمَا وَشِيعَتَهُمَا وَمُحِبِّيهِمَا فِي الْجَنَّةِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingهذان الحسن والحسين عمهما جعفر بن ابي طالب وعمتهما ام هاني بنت ابي طالب ما اشركت بالله طرفه عين الا اخبركم بخير الناس خالا وخاله هذان الحسن والحسين خالهما قاسم بن رسول الله وخالتهما زينب بنت رسول الله اللهم انك تعلم انهما واباهما وامهما وجدهما وجدتهما وخالهما وخالتهما وعمهما وعمتهما وشيعتهما ومحبيهما في الجنه', 'هذان الحسن والحسين عمهما جعفر بن ابي طالب وعمتهما ام هاني بنت ابي طالب ما اشركت بالله طرفه عين الا اخبركم بخير الناس خالا وخاله هذان الحسن والحسين خالهما قاسم بن رسول الله وخالتهما زينب بنت رسول الله اللهم انك تعلم انهما واباهما وامهما وجدهما وجدتهما وخالهما وخالتهما وعمهما وعمتهما وشيعتهما ومحبيهما في الجنه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 60, NULL, 'Is this hadith sound? He said: Yes, by God, O Commander of the Faithful — and it is indeed among the choicest of reports. The Commander of the Faithful said: And in the hadith, the Messenger of God (ع) said before a company of his companions:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'is this hadith sound he said yes by god o commander of the faithful and it is indeed among the choicest of reports the commander of the faithful said and in the hadith the messenger of god ع said before a company of his companions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 61, NULL, 'Sayingوَلَدَايَ هَذَانِ إِمَامَا حَقٍّ قَامَا أَوْ قَعَدَا وَأَبُوهُمَا خَيْرٌ مِنْهُمَا', '', 'وَلَدَايَ هَذَانِ إِمَامَا حَقٍّ قَامَا أَوْ قَعَدَا وَأَبُوهُمَا خَيْرٌ مِنْهُمَا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingولداي هذان اماما حق قاما او قعدا وابوهما خير منهما', 'ولداي هذان اماما حق قاما او قعدا وابوهما خير منهما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 62, NULL, 'These two sons of mine are two rightful Imams, whether they rise or sit, and their father is better than the two of them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'these two sons of mine are two rightful imams whether they rise or sit and their father is better than the two of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 63, NULL, 'He said: Yes. And the Prophet (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'he said yes and the prophet ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 64, NULL, 'Sayingوَلَدَايَ هَذَانِ سَيِّدَا شَبَابِ أَهْلِ الْجَنَّةِ', '', 'وَلَدَايَ هَذَانِ سَيِّدَا شَبَابِ أَهْلِ الْجَنَّةِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingولداي هذان سيدا شباب اهل الجنه', 'ولداي هذان سيدا شباب اهل الجنه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 65, NULL, 'These two sons of mine are the two masters of the youth of the people of the Garden.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'these two sons of mine are the two masters of the youth of the people of the garden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 66, NULL, 'Is the report sound, O shaykh, or not? He said: It is sound, O Commander of the Faithful. He said: Is it not in the report that the Messenger of God (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'is the report sound o shaykh or not he said it is sound o commander of the faithful he said is it not in the report that the messenger of god ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 67, NULL, 'Sayingإِنَّ أَهْلَ الْجَنَّةِ شَبَابٌ لَا يَهْرَمُونَ', '', 'إِنَّ أَهْلَ الْجَنَّةِ شَبَابٌ لَا يَهْرَمُونَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'sayingان اهل الجنه شباب لا يهرمون', 'ان اهل الجنه شباب لا يهرمون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 68, NULL, 'The people of the Garden are youths who do not grow old.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'the people of the garden are youths who do not grow old', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 69, NULL, 'He said: Yes. He said: Is that sound? He said: Yes, O Commander of the Faithful. He said to him: O shaykh, are Adam and Noah and Abraham and Moses and Jesus in the Garden, or not? He said: Yes indeed, O Commander of the Faithful. He said: O shaykh, then if al-Hasan and al-Husayn are the two masters of the youth of the people of the Garden, and their father is better than the two of them, it is established that Ali is the best of humankind together with the Prophet (ع). At that the shaykh said: I have believed and I have affirmed it as true. Then our mawla al-Hakim bi-Amr Allah, the Commander of the Faithful (ع), turned to the dai and said: O shaykh, give the call as you wish, for no one will oppose you.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'he said yes he said is that sound he said yes o commander of the faithful he said to him o shaykh are adam and noah and abraham and moses and jesus in the garden or not he said yes indeed o commander of the faithful he said o shaykh then if al hasan and al husayn are the two masters of the youth of the people of the garden and their father is better than the two of them it is established that ali is the best of humankind together with the prophet ع at that the shaykh said i have believed and i have affirmed it as true then our mawla al hakim bi amr allah the commander of the faithful ع turned to the dai and said o shaykh give the call as you wish for no one will oppose you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the disputed words of the call', '14. The Disputed Words of the Call', 70, NULL, 'I now turn to the matter of the Commander of the Faithful Ali (ع) and the matter of the call to prayer. I set down here a complete epistle by our sayyid and mawla and father Muhammad ibn Fahd — may God exalt his sanctity — the epistle entitled al-Muriba amma jarat bihi al-mubahatha, in which there is a lesson for whoever takes a lesson from it. It concerns the question of the words of the one who says in the call to prayer that Muhammad and Ali are the best of humankind and their kindred the best of kindred: between the one who holds that this saying is not permitted in the canons of the upright religion and is not among what has been narrated in the transmitted reports, and the one who holds that it is among what the Noble Book has commanded, and that upholding it belongs to whoever obeys the command of those whose command is to be obeyed.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 14 the disputed words of the call', 'i now turn to the matter of the commander of the faithful ali ع and the matter of the call to prayer i set down here a complete epistle by our sayyid and mawla and father muhammad ibn fahd may god exalt his sanctity the epistle entitled al muriba amma jarat bihi al mubahatha in which there is a lesson for whoever takes a lesson from it it concerns the question of the words of the one who says in the call to prayer that muhammad and ali are the best of humankind and their kindred the best of kindred between the one who holds that this saying is not permitted in the canons of the upright religion and is not among what has been narrated in the transmitted reports and the one who holds that it is among what the noble book has commanded and that upholding it belongs to whoever obeys the command of those whose command is to be obeyed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 0, NULL, 'In the name of God, the Most Gracious, the Most Merciful, and in Him I seek help.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'in the name of god the most gracious the most merciful and in him i seek help', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 1, NULL, 'Sayingبِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ وَبِهِ اَسْتَعِينُ', '', 'بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ وَبِهِ اَسْتَعِينُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'sayingبسم الله الرحمن الرحيم وبه استعين', 'بسم الله الرحمن الرحيم وبه استعين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 2, NULL, 'Praise belongs to God, Lord of the worlds, and may God bless His messenger, our master Muhammad, and his family, and grant them abundant peace. Having praised God, Lord of the worlds, and invoked blessings upon the best of His messengers, Muhammad al-Amin, upon his guardian, the most honorable of guardians, and upon all who are of the household of the two of them, the good and the pure — and (عَلَيْهِمُ السَّلَامُ):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'praise belongs to god lord of the worlds and may god bless his messenger our master muhammad and his family and grant them abundant peace having praised god lord of the worlds and invoked blessings upon the best of his messengers muhammad al amin upon his guardian the most honorable of guardians and upon all who are of the household of the two of them the good and the pure and عليهم السلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 3, NULL, 'A discussion took place between two jurists among the people of knowledge, and I am obliged to record both the questioner''s words and those of the one questioned, so that whoever comes upon this account may know which of the two spoke truth and which spoke outside the bounds of truth, guidance, and reasonable speech.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'a discussion took place between two jurists among the people of knowledge and i am obliged to record both the questioners words and those of the one questioned so that whoever comes upon this account may know which of the two spoke truth and which spoke outside the bounds of truth guidance and reasonable speech', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 4, NULL, 'One of the two jurists said to the other: "How is it that the people of your school say in the call to prayer, Muhammad and Ali are the best of human beings, and their kindred are the best of kindred? No other group in Islam says this."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'one of the two jurists said to the other how is it that the people of your school say in the call to prayer muhammad and ali are the best of human beings and their kindred are the best of kindred no other group in islam says this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 5, NULL, 'The other jurist, the one questioned about it, answered him with these words, drawn from the saying of God, blessed and exalted:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'the other jurist the one questioned about it answered him with these words drawn from the saying of god blessed and exalted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 6, NULL, 'Fussilat: 46مَنْ عَمِلَ صَالِحاً فَلِنَفْسِهِ وَمَنْ أَسَاءَ فَعَلَيْهَا', '', 'مَنْ عَمِلَ صَالِحاً فَلِنَفْسِهِ وَمَنْ أَسَاءَ فَعَلَيْهَا', 'Fussilat: 46', 41, 46, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'fussilat 46من عمل صالحا فلنفسه ومن اساء فعليها', 'من عمل صالحا فلنفسه ومن اساء فعليها');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 7, NULL, 'Whoever does righteous work does so for his own soul, and whoever does evil does so against it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'whoever does righteous work does so for his own soul and whoever does evil does so against it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 8, NULL, '"If our saying in the call to prayer — Muhammad and Ali are the best of human beings, and their kindred are the best of kindred — is righteous work, then we have done it only for ourselves. And if it is not righteous work but wrongdoing, then it falls back upon us alone, especially in light of His saying, exalted is He:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'if our saying in the call to prayer muhammad and ali are the best of human beings and their kindred are the best of kindred is righteous work then we have done it only for ourselves and if it is not righteous work but wrongdoing then it falls back upon us alone especially in light of his saying exalted is he', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 9, NULL, 'Al-An''am: 164وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى', '', 'وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى', 'Al-An''am: 164', 6, 164, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'al anam 164ولا تزر وازره وزر اخري', 'ولا تزر وازره وزر اخري');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 10, NULL, 'No bearer of burdens shall bear the burden of another."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'no bearer of burdens shall bear the burden of another', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 11, NULL, 'At that the questioner said to him: "You have spoken truly in what you have cited from these two verses of the most truthful of speakers. But I ask you for the clear argument and the plain proof you possess for the soundness of what you have mentioned — namely, that Muhammad, may God bless him and his family, and Ali are the best of human beings, and that you set Ali as the like of Muhammad, blessings be upon them both, according to what you employ in the call to prayer. It is a known matter that Muhammad, may God bless him and his family, is the best of human beings, since it is established that he is the master of the messengers. But as for Ali ibn Abi Talib (ع), it is not established that he is the like of the Messenger in this excellence until you prove it to me with a plain proof."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'at that the questioner said to him you have spoken truly in what you have cited from these two verses of the most truthful of speakers but i ask you for the clear argument and the plain proof you possess for the soundness of what you have mentioned namely that muhammad may god bless him and his family and ali are the best of human beings and that you set ali as the like of muhammad blessings be upon them both according to what you employ in the call to prayer it is a known matter that muhammad may god bless him and his family is the best of human beings since it is established that he is the master of the messengers but as for ali ibn abi talib ع it is not established that he is the like of the messenger in this excellence until you prove it to me with a plain proof', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 12, NULL, 'The respondent answered him: You have asked me a question that must be answered. I shall make this clear with illuminating proofs, to the measure of my capacity and strength, and above every possessor of knowledge there is One who knows.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'the respondent answered him you have asked me a question that must be answered i shall make this clear with illuminating proofs to the measure of my capacity and strength and above every possessor of knowledge there is one who knows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 13, NULL, '1. The first proof. I say, with the help and enabling grace of God, exalted is He, that since the word of God is:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', '1 the first proof i say with the help and enabling grace of god exalted is he that since the word of god is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 14, NULL, 'Al-Ahzab: 33إِنَّمَا يُرِيدُ اللهُ لِيُذْهِبَ عَنكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا', '', 'إِنَّمَا يُرِيدُ اللهُ لِيُذْهِبَ عَنكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا', 'Al-Ahzab: 33', 33, 33, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'al ahzab 33انما يريد الله ليذهب عنكم الرجس اهل البيت ويطهركم تطهيرا', 'انما يريد الله ليذهب عنكم الرجس اهل البيت ويطهركم تطهيرا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 15, NULL, 'God only wishes to remove all impurity from you, people of the household, and to purify you completely.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'god only wishes to remove all impurity from you people of the household and to purify you completely', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 16, NULL, 'The people of the household are thereby established as equal to the Prophet in purity. The most excellent of the people of the household after him is Ali ibn Abi Talib, the Commander of the Believers, the blessings of God be upon him, who is the Prophet''s guardian and friend — may God bless him and his family — and his successor in his community. Likeness to the Prophet is therefore established for him. He is the best of human beings alongside him, and their kindred are the best of kindred, by reason of their likeness to the two of them in purity. This is among the clearest of matters, leaving no room for ambiguity, for it rests on the word of the glorious Quran:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'the people of the household are thereby established as equal to the prophet in purity the most excellent of the people of the household after him is ali ibn abi talib the commander of the believers the blessings of god be upon him who is the prophets guardian and friend may god bless him and his family and his successor in his community likeness to the prophet is therefore established for him he is the best of human beings alongside him and their kindred are the best of kindred by reason of their likeness to the two of them in purity this is among the clearest of matters leaving no room for ambiguity for it rests on the word of the glorious quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 17, NULL, 'Fussilat: 42لَا يَأْتِيهِ الْبَاطِلُ مِنْ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِ تَنزِيلٌ مِنْ حَكِيمٍ حَمِيدٍ', '', 'لَا يَأْتِيهِ الْبَاطِلُ مِنْ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِ تَنزِيلٌ مِنْ حَكِيمٍ حَمِيدٍ', 'Fussilat: 42', 41, 42, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'fussilat 42لا ياتيه الباطل من بين يديه ولا من خلفه تنزيل من حكيم حميد', 'لا ياتيه الباطل من بين يديه ولا من خلفه تنزيل من حكيم حميد');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 18, NULL, 'Falsehood does not come to it from before it nor from behind it; it is a revelation from One who is Wise, Praiseworthy.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'falsehood does not come to it from before it nor from behind it it is a revelation from one who is wise praiseworthy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 19, NULL, '2. The second proof. We say, with the help and enabling grace of God, that since the word of God, exalted is He, in His clear Book is:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', '2 the second proof we say with the help and enabling grace of god that since the word of god exalted is he in his clear book is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 20, NULL, 'Sayingسَلَامٌ عَلَى آلِ يَاسِينَ إِنَّا كَذَلِكَ نَجْزِي الْمُحْسِنِينَ', '', 'سَلَامٌ عَلَى آلِ يَاسِينَ إِنَّا كَذَلِكَ نَجْزِي الْمُحْسِنِينَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'sayingسلام علي ال ياسين انا كذلك نجزي المحسنين', 'سلام علي ال ياسين انا كذلك نجزي المحسنين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 21, NULL, 'Peace be upon the family of Yasin. Thus do We reward those who do good.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'peace be upon the family of yasin thus do we reward those who do good', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 22, NULL, 'This verse declares that the family of Yasin — upon whom God, glorified is He, has sent peace — are the family of the Messenger of God, may God bless him and his family: the excellent ones, the people of his household. The first and most excellent among them was the one whom the Messenger of God, may God bless him and his family, chose as his guardian over his community, and that is Ali ibn Abi Talib.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'this verse declares that the family of yasin upon whom god glorified is he has sent peace are the family of the messenger of god may god bless him and his family the excellent ones the people of his household the first and most excellent among them was the one whom the messenger of god may god bless him and his family chose as his guardian over his community and that is ali ibn abi talib', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 23, NULL, 'It is therefore established that only the best of human beings could be the most excellent of the family of Yasin: those upon whom God sent peace and whom He described as those who do good. For the people of the household who came after him — who are the family of Yasin — are themselves among human beings and of them, and so he is the best of them. This is among the clear matters, leaving no room for ambiguity, for it rests on the word of the glorious Quran, to which falsehood does not come from before it nor from behind it, a revelation from One who is Wise, Praiseworthy.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'it is therefore established that only the best of human beings could be the most excellent of the family of yasin those upon whom god sent peace and whom he described as those who do good for the people of the household who came after him who are the family of yasin are themselves among human beings and of them and so he is the best of them this is among the clear matters leaving no room for ambiguity for it rests on the word of the glorious quran to which falsehood does not come from before it nor from behind it a revelation from one who is wise praiseworthy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 24, NULL, '3. The third proof. We say, with the help and enabling grace of God, exalted is He, that the word of God, exalted is He, in this noble verse:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', '3 the third proof we say with the help and enabling grace of god exalted is he that the word of god exalted is he in this noble verse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 25, NULL, 'Ali ''Imran: 110كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللهِ', '', 'كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللهِ', 'Ali ''Imran: 110', 3, 110, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'ali imran 110كنتم خير امه اخرجت للناس تامرون بالمعروف وتنهون عن المنكر وتومنون بالله', 'كنتم خير امه اخرجت للناس تامرون بالمعروف وتنهون عن المنكر وتومنون بالله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 26, NULL, 'You are the best community brought forth for humankind: you enjoin what is right, forbid what is wrong, and believe in God.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'you are the best community brought forth for humankind you enjoin what is right forbid what is wrong and believe in god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 27, NULL, 'is an address from Him to the people of the household of the Messenger of God. His statement, exalted is He, that they are the best community brought forth for humankind requires that what He has appointed them to be admit of no alteration — namely, that they are the best community brought forth for humankind. Since the most excellent and the first of them is the Commander of the Believers, Ali ibn Abi Talib, according to what has already been explained in the two preceding proofs, it is therefore sound and established, and again sound and established, that he is the best of human beings after the Prophet and together with him, blessings be upon them both. This is among the clear matters, leaving no room for ambiguity, for it rests on the word of the glorious Quran, to which falsehood does not come from before it nor from behind it, a revelation from One who is Wise, Praiseworthy.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'is an address from him to the people of the household of the messenger of god his statement exalted is he that they are the best community brought forth for humankind requires that what he has appointed them to be admit of no alteration namely that they are the best community brought forth for humankind since the most excellent and the first of them is the commander of the believers ali ibn abi talib according to what has already been explained in the two preceding proofs it is therefore sound and established and again sound and established that he is the best of human beings after the prophet and together with him blessings be upon them both this is among the clear matters leaving no room for ambiguity for it rests on the word of the glorious quran to which falsehood does not come from before it nor from behind it a revelation from one who is wise praiseworthy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 28, NULL, '4. The fourth proof. We say, with the help and enabling grace of God, exalted is He, that God has recounted in His noble Book the request of His prophet Moses (ع), which is his saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', '4 the fourth proof we say with the help and enabling grace of god exalted is he that god has recounted in his noble book the request of his prophet moses ع which is his saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 29, NULL, 'Sayingوَاجْعَل لِّي وَزِيرًا مِّنْ أَهْلِي هَارُونَ أَخِي اشْدُدْ بِهِ أَزْرِي وَأَشْرِكْهُ فِي أَمْرِي كَيْ نُسَبِّحَكَ كَثِيرًا وَنَذْكُرَكَ كَثِيرًا إِنَّكَ كُنتَ بِنَا بَصِيرًا"And appoint for me a minister from my family, Aaron my brother. Strengthen my back through him and let him share in my task, so that we may glorify You much and remember You much. Indeed, You are ever watching over us."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'sayingواجعل لي وزيرا من اهلي هارون اخي اشدد به ازري واشركه في امري كي نسبحك كثيرا ونذكرك كثيرا انك كنت بنا بصيرا and appoint for me a minister from my family aaron my brother strengthen my back through him and let him share in my task so that we may glorify you much and remember you much indeed you are ever watching over us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 30, NULL, 'The Creator''s answer to him, exalted is He, was His saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'the creators answer to him exalted is he was his saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 31, NULL, 'Sayingقَدْ أُوتِيتَ سُؤْلَكَ يَا مُوسَى', '', 'قَدْ أُوتِيتَ سُؤْلَكَ يَا مُوسَى', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'sayingقد اوتيت سولك يا موسي', 'قد اوتيت سولك يا موسي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 32, NULL, 'You have been granted your request, Moses.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'you have been granted your request moses', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 33, NULL, 'From this I understand that Moses (ع) asked God, glorified is He, to appoint his brother Aaron as a minister — one through whom his back would be strengthened and who would share in his task. He stated his own reason openly: that together they might glorify Him much and remember Him much, for He is ever watching over them. Then, in another place of His noble Book, God, exalted is He, relates what Moses (ع) — the one He had addressed — went on to say:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'from this i understand that moses ع asked god glorified is he to appoint his brother aaron as a minister one through whom his back would be strengthened and who would share in his task he stated his own reason openly that together they might glorify him much and remember him much for he is ever watching over them then in another place of his noble book god exalted is he relates what moses ع the one he had addressed went on to say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 34, NULL, 'Al-Qasas: 34وَأَخِي هَارُونُ هُوَ أَفْصَحُ مِنِّي لِسَانًا فَأَرْسِلْهُ مَعِيَ رِدْءًا يُصَدِّقُنِي إِنِّي أَخَافُ أَن يُكَذِّبُونِ', '', 'وَأَخِي هَارُونُ هُوَ أَفْصَحُ مِنِّي لِسَانًا فَأَرْسِلْهُ مَعِيَ رِدْءًا يُصَدِّقُنِي إِنِّي أَخَافُ أَن يُكَذِّبُونِ', 'Al-Qasas: 34', 28, 34, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'al qasas 34واخي هارون هو افصح مني لسانا فارسله معي ردءا يصدقني اني اخاف ان يكذبون', 'واخي هارون هو افصح مني لسانا فارسله معي ردءا يصدقني اني اخاف ان يكذبون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 35, NULL, 'And my brother Aaron is more eloquent than I in speech, so send him with me as a helper to confirm me. I fear that they will call me a liar.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'and my brother aaron is more eloquent than i in speech so send him with me as a helper to confirm me i fear that they will call me a liar', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 36, NULL, 'And His saying, exalted is He, in answer to that:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'and his saying exalted is he in answer to that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 37, NULL, 'Al-Qasas: 35سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجْعَلُ لَكُمَا سُلْطَانًا فَلَا يَصِلُونَ إِلَيْكُمَا بِآيَاتِنَا أَنتُمَا وَمَنِ اتَّبَعَكُمَا الْغَالِبُونَ', '', 'سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجْعَلُ لَكُمَا سُلْطَانًا فَلَا يَصِلُونَ إِلَيْكُمَا بِآيَاتِنَا أَنتُمَا وَمَنِ اتَّبَعَكُمَا الْغَالِبُونَ', 'Al-Qasas: 35', 28, 35, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'al qasas 35سنشد عضدك باخيك ونجعل لكما سلطانا فلا يصلون اليكما باياتنا انتما ومن اتبعكما الغالبون', 'سنشد عضدك باخيك ونجعل لكما سلطانا فلا يصلون اليكما باياتنا انتما ومن اتبعكما الغالبون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 38, NULL, 'We shall strengthen your arm through your brother and grant you both authority, so that they will not reach you. By Our signs, you two and those who follow you will be the victors.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'we shall strengthen your arm through your brother and grant you both authority so that they will not reach you by our signs you two and those who follow you will be the victors', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 39, NULL, 'In another verse of His noble Book, God, exalted is He, speaks to His prophet Muhammad (ع):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'in another verse of his noble book god exalted is he speaks to his prophet muhammad ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 40, NULL, 'Al-An''am: 90أُولَٰئِكَ الَّذِينَ هَدَى اللهُ فَبِهُدَاهُمُ اقْتَدِهْ', '', 'أُولَٰئِكَ الَّذِينَ هَدَى اللهُ فَبِهُدَاهُمُ اقْتَدِهْ', 'Al-An''am: 90', 6, 90, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'al anam 90اوليك الذين هدي الله فبهداهم اقتده', 'اوليك الذين هدي الله فبهداهم اقتده');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 41, NULL, 'Those are the ones whom God has guided, so follow their guidance.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'those are the ones whom god has guided so follow their guidance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 42, NULL, 'And in another verse of it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'and in another verse of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 43, NULL, 'Fussilat: 43مَا يُقَالُ لَكَ إِلَّا مَا قَدْ قِيلَ لِلرُّسُلِ مِن قَبْلِكَ', '', 'مَا يُقَالُ لَكَ إِلَّا مَا قَدْ قِيلَ لِلرُّسُلِ مِن قَبْلِكَ', 'Fussilat: 43', 41, 43, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'fussilat 43ما يقال لك الا ما قد قيل للرسل من قبلك', 'ما يقال لك الا ما قد قيل للرسل من قبلك');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 44, NULL, 'Nothing is said to you except what was said to the messengers before you.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'nothing is said to you except what was said to the messengers before you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 45, NULL, 'And in another verse of it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'and in another verse of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 46, NULL, 'Ash-Shura: 13شَرَعَ لَكُم مِّنَ الدِّينِ مَا وَصَّى بِهِ نُوحًا وَالَّذِي أَوْحَيْنَا إِلَيْكَ وَمَا وَصَّيْنَا بِهِ إِبْرَاهِيمَ وَمُوسَى وَعِيسَى أَنْ أَقِيمُوا الدِّينَ وَلَا تَتَفَرَّقُوا فِيهِ', '', 'شَرَعَ لَكُم مِّنَ الدِّينِ مَا وَصَّى بِهِ نُوحًا وَالَّذِي أَوْحَيْنَا إِلَيْكَ وَمَا وَصَّيْنَا بِهِ إِبْرَاهِيمَ وَمُوسَى وَعِيسَى أَنْ أَقِيمُوا الدِّينَ وَلَا تَتَفَرَّقُوا فِيهِ', 'Ash-Shura: 13', 42, 13, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'ash shura 13شرع لكم من الدين ما وصي به نوحا والذي اوحينا اليك وما وصينا به ابراهيم وموسي وعيسي ان اقيموا الدين ولا تتفرقوا فيه', 'شرع لكم من الدين ما وصي به نوحا والذي اوحينا اليك وما وصينا به ابراهيم وموسي وعيسي ان اقيموا الدين ولا تتفرقوا فيه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 47, NULL, 'He has ordained for you of religion what He enjoined upon Noah, and what We have revealed to you, and what We enjoined upon Abraham and Moses and Jesus: that you establish the religion and not be divided in it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'he has ordained for you of religion what he enjoined upon noah and what we have revealed to you and what we enjoined upon abraham and moses and jesus that you establish the religion and not be divided in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 48, NULL, 'All of this obliges the Messenger to appoint the Commander of the Believers, Ali ibn Abi Talib, as his guardian, his minister, and his brother, to have him strengthen his back and share in his task. It further establishes that God, glorified is He, strengthened his arm through him and granted to him and to the other the authority mentioned — especially given His words to him, exalted is He, in one place of His noble Book:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'all of this obliges the messenger to appoint the commander of the believers ali ibn abi talib as his guardian his minister and his brother to have him strengthen his back and share in his task it further establishes that god glorified is he strengthened his arm through him and granted to him and to the other the authority mentioned especially given his words to him exalted is he in one place of his noble book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 49, NULL, 'Al-Ahzab: 62وَلَن تَجِدَ لِسُنَّةِ اللهِ تَبْدِيلًا', '', 'وَلَن تَجِدَ لِسُنَّةِ اللهِ تَبْدِيلًا', 'Al-Ahzab: 62', 33, 62, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'al ahzab 62ولن تجد لسنه الله تبديلا', 'ولن تجد لسنه الله تبديلا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 50, NULL, 'You will never find any change in the way of God.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'you will never find any change in the way of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 51, NULL, 'And in another place:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'and in another place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 52, NULL, 'Sayingوَلَن تَجِدَ لِسُنَّةِ اللهِ تَحْوِيلًا', '', 'وَلَن تَجِدَ لِسُنَّةِ اللهِ تَحْوِيلًا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'sayingولن تجد لسنه الله تحويلا', 'ولن تجد لسنه الله تحويلا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 53, NULL, 'You will never find any alteration in the way of God.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'you will never find any alteration in the way of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 54, NULL, 'This being so, it is sound and firmly established that Ali (ع) is the minister of the Messenger of God, his brother, and his partner in his task and in the authority that God appointed for them both. This is confirmed by what has been narrated from the Messenger concerning him — his saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'this being so it is sound and firmly established that ali ع is the minister of the messenger of god his brother and his partner in his task and in the authority that god appointed for them both this is confirmed by what has been narrated from the messenger concerning him his saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 55, NULL, 'Sayingعَلِيٌّ مِنِّي بِمَنْزِلَةِ هَارُونَ مِنْ مُوسَى إِلَّا أَنَّهُ لَا نَبِيَّ بَعْدِي', '', 'عَلِيٌّ مِنِّي بِمَنْزِلَةِ هَارُونَ مِنْ مُوسَى إِلَّا أَنَّهُ لَا نَبِيَّ بَعْدِي', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'sayingعلي مني بمنزله هارون من موسي الا انه لا نبي بعدي', 'علي مني بمنزله هارون من موسي الا انه لا نبي بعدي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 56, NULL, 'Ali stands to me in the station of Aaron to Moses, except that there is no prophet after me.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'ali stands to me in the station of aaron to moses except that there is no prophet after me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 57, NULL, 'This being so, it is sound and firmly established — established again and beyond all doubt — by the force of these noble verses of the glorious Quran, to which falsehood cannot come from before it or from behind it: a revelation from One who is Wise, Praiseworthy, of which He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'this being so it is sound and firmly established established again and beyond all doubt by the force of these noble verses of the glorious quran to which falsehood cannot come from before it or from behind it a revelation from one who is wise praiseworthy of which he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 58, NULL, 'Al-Isra: 9إِنَّ هَٰذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ', '', 'إِنَّ هَٰذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ', 'Al-Isra: 9', 17, 9, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'al isra 9ان هذا القران يهدي للتي هي اقوم', 'ان هذا القران يهدي للتي هي اقوم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 59, NULL, 'Indeed, this Quran guides to that which is most upright.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'indeed this quran guides to that which is most upright', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 60, NULL, 'And by the force of the Prophet''s words already cited, it is established that Ali, the Commander of the Believers, stands among the best of human beings after the Messenger — for God linked him to the Messenger in both task and authority. This is among the clearest and most self-evident of matters, admitting no ambiguity, for it rests on the word of the glorious القرآن, to which falsehood cannot come from before it or from behind it: a revelation from One who is Wise, Praiseworthy.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'and by the force of the prophets words already cited it is established that ali the commander of the believers stands among the best of human beings after the messenger for god linked him to the messenger in both task and authority this is among the clearest and most self evident of matters admitting no ambiguity for it rests on the word of the glorious القران to which falsehood cannot come from before it or from behind it a revelation from one who is wise praiseworthy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 61, NULL, '5. The fifth proof. We say, by the help and enabling grace of God, exalted is He, that the word of God, mighty and majestic, in His noble Book is:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', '5 the fifth proof we say by the help and enabling grace of god exalted is he that the word of god mighty and majestic in his noble book is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 62, NULL, 'Al-Ma''idah: 55إِنَّمَا وَلِيُّكُمُ اللهُ وَرَسُولُهُ وَالَّذِينَ آمَنُوا الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُمْ رَاكِعُونَ', '', 'إِنَّمَا وَلِيُّكُمُ اللهُ وَرَسُولُهُ وَالَّذِينَ آمَنُوا الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُمْ رَاكِعُونَ', 'Al-Ma''idah: 55', 5, 55, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'al maidah 55انما وليكم الله ورسوله والذين امنوا الذين يقيمون الصلاه ويوتون الزكاه وهم راكعون', 'انما وليكم الله ورسوله والذين امنوا الذين يقيمون الصلاه ويوتون الزكاه وهم راكعون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 63, NULL, 'Your guardian is only God, and His Messenger, and those who believe: those who establish the prayer and give the alms while bowing.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'your guardian is only god and his messenger and those who believe those who establish the prayer and give the alms while bowing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 64, NULL, 'Al-Ma''idah: 56وَمَن يَتَوَلَّ اللهَ وَرَسُولَهُ وَالَّذِينَ آمَنُوا فَإِنَّ حِزْبَ اللهِ هُمُ الْغَالِبُونَ', '', 'وَمَن يَتَوَلَّ اللهَ وَرَسُولَهُ وَالَّذِينَ آمَنُوا فَإِنَّ حِزْبَ اللهِ هُمُ الْغَالِبُونَ', 'Al-Ma''idah: 56', 5, 56, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'al maidah 56ومن يتول الله ورسوله والذين امنوا فان حزب الله هم الغالبون', 'ومن يتول الله ورسوله والذين امنوا فان حزب الله هم الغالبون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 65, NULL, 'And whoever takes God and His Messenger and those who believe as guardians, then the party of God are the victors.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'and whoever takes god and his messenger and those who believe as guardians then the party of god are the victors', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 66, NULL, 'This requires that those whom God, exalted is He, named in that verse as the believers — those He described as establishing the prayer and giving the alms, and as the victorious party of God — are among the people of bounty, of whom God said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'this requires that those whom god exalted is he named in that verse as the believers those he described as establishing the prayer and giving the alms and as the victorious party of god are among the people of bounty of whom god said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 67, NULL, 'Hud: 3وَيُؤْتِ كُلَّ ذِي فَضْلٍ فَضْلَهُ', '', 'وَيُؤْتِ كُلَّ ذِي فَضْلٍ فَضْلَهُ', 'Hud: 3', 11, 3, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'hud 3ويوت كل ذي فضل فضله', 'ويوت كل ذي فضل فضله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 68, NULL, 'And He gives every possessor of bounty his bounty.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'and he gives every possessor of bounty his bounty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 69, NULL, 'And of whom He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'and of whom he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 70, NULL, 'Al-Hadid: 29إِنَّ الْفَضْلَ بِيَدِ اللهِ يُؤْتِيهِ مَن يَشَاءُ وَاللهُ ذُو الْفَضْلِ الْعَظِيمِ', '', 'إِنَّ الْفَضْلَ بِيَدِ اللهِ يُؤْتِيهِ مَن يَشَاءُ وَاللهُ ذُو الْفَضْلِ الْعَظِيمِ', 'Al-Hadid: 29', 57, 29, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'al hadid 29ان الفضل بيد الله يوتيه من يشاء والله ذو الفضل العظيم', 'ان الفضل بيد الله يوتيه من يشاء والله ذو الفضل العظيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 71, NULL, 'Indeed, bounty is in the hand of God; He gives it to whomever He wills, and God is the possessor of great bounty.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'indeed bounty is in the hand of god he gives it to whomever he wills and god is the possessor of great bounty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 72, NULL, 'And no one among human beings had a better right or a stronger claim to this bounty than the people of the household of the Messenger of God, of whom God said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'and no one among human beings had a better right or a stronger claim to this bounty than the people of the household of the messenger of god of whom god said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 73, NULL, 'Al-Ahzab: 33إِنَّمَا يُرِيدُ اللهُ لِيُذْهِبَ عَنكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا', '', 'إِنَّمَا يُرِيدُ اللهُ لِيُذْهِبَ عَنكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا', 'Al-Ahzab: 33', 33, 33, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'al ahzab 33انما يريد الله ليذهب عنكم الرجس اهل البيت ويطهركم تطهيرا', 'انما يريد الله ليذهب عنكم الرجس اهل البيت ويطهركم تطهيرا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 74, NULL, 'God only wishes to remove all impurity from you, people of the household, and to purify you completely.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'god only wishes to remove all impurity from you people of the household and to purify you completely', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 75, NULL, 'For His will is turned back by none of the created. And God also said of them:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'for his will is turned back by none of the created and god also said of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 76, NULL, 'Ali ''Imran: 110كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللهِ', '', 'كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللهِ', 'Ali ''Imran: 110', 3, 110, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'ali imran 110كنتم خير امه اخرجت للناس تامرون بالمعروف وتنهون عن المنكر وتومنون بالله', 'كنتم خير امه اخرجت للناس تامرون بالمعروف وتنهون عن المنكر وتومنون بالله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 77, NULL, 'You are the best community brought forth for humankind: you enjoin what is right, forbid what is wrong, and believe in God.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'you are the best community brought forth for humankind you enjoin what is right forbid what is wrong and believe in god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 78, NULL, 'And God also said of them:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'and god also said of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 79, NULL, 'Sayingسَلَامٌ عَلَى آلِ يَاسِينَ إِنَّا كَذَلِكَ نَجْزِي الْمُحْسِنِينَ', '', 'سَلَامٌ عَلَى آلِ يَاسِينَ إِنَّا كَذَلِكَ نَجْزِي الْمُحْسِنِينَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'sayingسلام علي ال ياسين انا كذلك نجزي المحسنين', 'سلام علي ال ياسين انا كذلك نجزي المحسنين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 80, NULL, 'Peace be upon the family of Yasin. Thus do We reward those who do good.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'peace be upon the family of yasin thus do we reward those who do good', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 81, NULL, 'The first and most excellent of them was the one whom the Messenger made his brother, his guardian, his minister, and his successor over his community. It is therefore sound and established — and sound and established once more — that Ali ibn Abi Talib holds command after the Messenger, is the one intended by the verse cited above, and is the Messenger''s partner in guardianship over the believers. No one can occupy such a station except one who is the best of human beings after the Messenger and alongside him, by reason of that shared guardianship. This is among the clearest of matters, admitting no ambiguity, for it rests upon the words of the glorious Quran — to which falsehood does not come from before it nor from behind it, a revelation from One who is Wise, Praiseworthy — and especially so after the clarification the Messenger of God gave on the day of the festival of Ghadir Khumm, the day of the explicit designation of Ali: that he had made him, like himself, a master over the believers in his lifetime, saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'the first and most excellent of them was the one whom the messenger made his brother his guardian his minister and his successor over his community it is therefore sound and established and sound and established once more that ali ibn abi talib holds command after the messenger is the one intended by the verse cited above and is the messengers partner in guardianship over the believers no one can occupy such a station except one who is the best of human beings after the messenger and alongside him by reason of that shared guardianship this is among the clearest of matters admitting no ambiguity for it rests upon the words of the glorious quran to which falsehood does not come from before it nor from behind it a revelation from one who is wise praiseworthy and especially so after the clarification the messenger of god gave on the day of the festival of ghadir khumm the day of the explicit designation of ali that he had made him like himself a master over the believers in his lifetime saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 82, NULL, 'Sayingمَنْ كُنْتُ مَوْلَاهُ فَهَذَا عَلِيٌّ مَوْلَاهُ اللَّهُمَّ وَالِ مَنْ وَالَاهُ وَعَادِ مَنْ عَادَاهُ وَانْصُرْ مَنْ نَصَرَهُ وَاخْذُلْ مَنْ خَذَلَهُ وَأَدِرِ الْحَقَّ مَعَهُ حَيْثُ دَارَ', '', 'مَنْ كُنْتُ مَوْلَاهُ فَهَذَا عَلِيٌّ مَوْلَاهُ اللَّهُمَّ وَالِ مَنْ وَالَاهُ وَعَادِ مَنْ عَادَاهُ وَانْصُرْ مَنْ نَصَرَهُ وَاخْذُلْ مَنْ خَذَلَهُ وَأَدِرِ الْحَقَّ مَعَهُ حَيْثُ دَارَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'sayingمن كنت مولاه فهذا علي مولاه اللهم وال من والاه وعاد من عاداه وانصر من نصره واخذل من خذله وادر الحق معه حيث دار', 'من كنت مولاه فهذا علي مولاه اللهم وال من والاه وعاد من عاداه وانصر من نصره واخذل من خذله وادر الحق معه حيث دار');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 83, NULL, 'And truly, even the portion we have already set forth — these verses and arguments — is sufficient, fully sufficient, for anyone who has a heart, or who gives ear while he is a witness.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'and truly even the portion we have already set forth these verses and arguments is sufficient fully sufficient for anyone who has a heart or who gives ear while he is a witness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 84, NULL, '6. The sixth proof. We say, with the help and enabling grace of God, exalted is He, that the word of God, exalted is He, in this noble verse of His noble Book is:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', '6 the sixth proof we say with the help and enabling grace of god exalted is he that the word of god exalted is he in this noble verse of his noble book is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 85, NULL, 'Al-Bayyinah: 7إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُولَٰئِكَ هُمْ خَيْرُ الْبَرِيَّةِ', '', 'إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُولَٰئِكَ هُمْ خَيْرُ الْبَرِيَّةِ', 'Al-Bayyinah: 7', 98, 7, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'al bayyinah 7ان الذين امنوا وعملوا الصالحات اوليك هم خير البريه', 'ان الذين امنوا وعملوا الصالحات اوليك هم خير البريه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 86, NULL, 'Indeed, those who believe and do righteous deeds are the best of creation.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'indeed those who believe and do righteous deeds are the best of creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 87, NULL, 'It is a known matter that the people of the household of the Messenger are the best of creation — for they are the finest of those who believed in God and performed righteous deeds, and because of what God has declared concerning them: that they are the best community brought forth for humankind. It is likewise a known matter that Ali, the Commander of the Believers, is the most excellent of the people of the household. It therefore follows, soundly and firmly, that our words in the call to prayer — that Muhammad and Ali are the best of human beings, and their kindred are the best of kindred — are the truth, free of all ambiguity. This truth comes from the glorious Quran, to which falsehood does not come from before it nor from behind it: a revelation from One who is Wise, Praiseworthy.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'it is a known matter that the people of the household of the messenger are the best of creation for they are the finest of those who believed in god and performed righteous deeds and because of what god has declared concerning them that they are the best community brought forth for humankind it is likewise a known matter that ali the commander of the believers is the most excellent of the people of the household it therefore follows soundly and firmly that our words in the call to prayer that muhammad and ali are the best of human beings and their kindred are the best of kindred are the truth free of all ambiguity this truth comes from the glorious quran to which falsehood does not come from before it nor from behind it a revelation from one who is wise praiseworthy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 88, NULL, '7. The seventh proof. We say, with the help and enabling grace of God, exalted is He, that since the word of God in His noble Book is:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', '7 the seventh proof we say with the help and enabling grace of god exalted is he that since the word of god in his noble book is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 89, NULL, 'Sayingإِنَّ اللهَ اصْطَفَى آدَمَ وَنُوحًا وَآلَ إِبْرَاهِيمَ وَآلَ عِمْرَانَ عَلَى الْعَالَمِينَ ذُرِّيَّةً بَعْضُهَا مِنْ بَعْضٍ وَاللهُ سَمِيعٌ عَلِيمٌ', '', 'إِنَّ اللهَ اصْطَفَى آدَمَ وَنُوحًا وَآلَ إِبْرَاهِيمَ وَآلَ عِمْرَانَ عَلَى الْعَالَمِينَ ذُرِّيَّةً بَعْضُهَا مِنْ بَعْضٍ وَاللهُ سَمِيعٌ عَلِيمٌ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'sayingان الله اصطفي ادم ونوحا وال ابراهيم وال عمران علي العالمين ذريه بعضها من بعض والله سميع عليم', 'ان الله اصطفي ادم ونوحا وال ابراهيم وال عمران علي العالمين ذريه بعضها من بعض والله سميع عليم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 90, NULL, 'Indeed, God chose Adam and Noah and the family of Abraham and the family of Imran above all the worlds, descendants one from another, and God is Hearing, Knowing.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'indeed god chose adam and noah and the family of abraham and the family of imran above all the worlds descendants one from another and god is hearing knowing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 91, NULL, 'This verse makes plain that God chose the family of Abraham and the family of Imran just as He chose Adam and Noah, singling them out for His message and prophethood. Now, it is well established that the Messenger of God is more excellent than both Adam and Noah. It therefore follows, soundly, that his family is more excellent than the family of Abraham and the family of Imran (عَلَيْهِمُ السَّلَامُ) taken together. And since this is so, it follows equally that our master the Commander of the Believers, Ali ibn Abi Talib, is the most excellent member of the Messenger''s family. It is therefore sound and established — sound and established — that our saying in the call to prayer, that Muhammad and Ali are the best of human beings and their kindred are the best of kindred, is among those whose soundness and firmness are witnessed by the verses of the glorious Quran, to which falsehood does not come from before it nor from behind it: a revelation from One who is Wise, Praiseworthy.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'this verse makes plain that god chose the family of abraham and the family of imran just as he chose adam and noah singling them out for his message and prophethood now it is well established that the messenger of god is more excellent than both adam and noah it therefore follows soundly that his family is more excellent than the family of abraham and the family of imran عليهم السلام taken together and since this is so it follows equally that our master the commander of the believers ali ibn abi talib is the most excellent member of the messengers family it is therefore sound and established sound and established that our saying in the call to prayer that muhammad and ali are the best of human beings and their kindred are the best of kindred is among those whose soundness and firmness are witnessed by the verses of the glorious quran to which falsehood does not come from before it nor from behind it a revelation from one who is wise praiseworthy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 92, NULL, '8. The eighth proof. We say, with the help and enabling grace of God, exalted is He, that since the word of God, exalted is He, in this noble verse is:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', '8 the eighth proof we say with the help and enabling grace of god exalted is he that since the word of god exalted is he in this noble verse is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 93, NULL, 'Sayingوَلَقَدْ نَجَّيْنَا بَنِي إِسْرَائِيلَ مِنَ الْعَذَابِ الْمُهِينِ مِن فِرْعَوْنَ إِنَّهُ كَانَ عَالِيًا مِّنَ الْمُسْرِفِينَ وَلَقَدِ اخْتَرْنَاهُمْ عَلَى عِلْمٍ عَلَى الْعَالَمِينَ', '', 'وَلَقَدْ نَجَّيْنَا بَنِي إِسْرَائِيلَ مِنَ الْعَذَابِ الْمُهِينِ مِن فِرْعَوْنَ إِنَّهُ كَانَ عَالِيًا مِّنَ الْمُسْرِفِينَ وَلَقَدِ اخْتَرْنَاهُمْ عَلَى عِلْمٍ عَلَى الْعَالَمِينَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'sayingولقد نجينا بني اسراييل من العذاب المهين من فرعون انه كان عاليا من المسرفين ولقد اخترناهم علي علم علي العالمين', 'ولقد نجينا بني اسراييل من العذاب المهين من فرعون انه كان عاليا من المسرفين ولقد اخترناهم علي علم علي العالمين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 94, NULL, 'This verse makes plain that God chose the Children of Israel, in their era, above all the worlds and preferred them over all creation — for the worlds are human beings, and human beings are creation. The family of the Messenger, then, are the best of human beings not only in their own era but also in the eras of all who came before them, since it is established that the Messenger is the master of all messengers and all prophets — the most honorable and excellent of them all. This being so, it is sound and settled — and sound and settled again — that his family, who are his kindred, are more excellent than the family of every prophet and more honorable than the kindred of every prophet, and that they are chosen above all the people of his era. It is likewise established that our saying in the call to prayer — that Muhammad and Ali are the best of human beings and their kindred are the best of kindred — is true and correct speech, because Ali is the most excellent of the family of the Messenger of God, the most honorable among them and the best of them. This judgment is a true judgment, as attested by these verses of the noble Book that we have cited here — along with others like them that we have not cited — and as attested by the noble verse we have mentioned, from the glorious Quran, to which falsehood does not come from before it nor from behind it: a revelation from One who is Wise, Praiseworthy.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'this verse makes plain that god chose the children of israel in their era above all the worlds and preferred them over all creation for the worlds are human beings and human beings are creation the family of the messenger then are the best of human beings not only in their own era but also in the eras of all who came before them since it is established that the messenger is the master of all messengers and all prophets the most honorable and excellent of them all this being so it is sound and settled and sound and settled again that his family who are his kindred are more excellent than the family of every prophet and more honorable than the kindred of every prophet and that they are chosen above all the people of his era it is likewise established that our saying in the call to prayer that muhammad and ali are the best of human beings and their kindred are the best of kindred is true and correct speech because ali is the most excellent of the family of the messenger of god the most honorable among them and the best of them this judgment is a true judgment as attested by these verses of the noble book that we have cited here along with others like them that we have not cited and as attested by the noble verse we have mentioned from the glorious quran to which falsehood does not come from before it nor from behind it a revelation from one who is wise praiseworthy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 95, NULL, 'Having completed the mention of these eight answers on the matter in question, together with the proofs drawn from the saying of the most truthful of speakers — proofs that expand the breast and remove doubt from the hearts of believers — we now seal this treatise of ours, which we devoted to that subject, with praise to God, Lord of the worlds, and with blessings upon our master Muhammad, master of the messengers, and upon his pure family until the Day of Judgment. (عَلَيْهِمُ السَّلَامُ). God is sufficient for us, and how excellent a trustee.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'having completed the mention of these eight answers on the matter in question together with the proofs drawn from the saying of the most truthful of speakers proofs that expand the breast and remove doubt from the hearts of believers we now seal this treatise of ours which we devoted to that subject with praise to god lord of the worlds and with blessings upon our master muhammad master of the messengers and upon his pure family until the day of judgment عليهم السلام god is sufficient for us and how excellent a trustee', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 96, NULL, 'In the name of God, the Most Gracious, the Most Merciful.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'in the name of god the most gracious the most merciful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 97, NULL, 'There is a confusion raised at this point by certain objectors who oppose the noble school — namely, that what Umar ibn al-Khattab removed from the call to prayer, the phrase', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'there is a confusion raised at this point by certain objectors who oppose the noble school namely that what umar ibn al khattab removed from the call to prayer the phrase', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 98, NULL, 'Sayingحَيَّ عَلَى خَيْرِ الْعَمَلِ', '', 'حَيَّ عَلَى خَيْرِ الْعَمَلِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'sayingحي علي خير العمل', 'حي علي خير العمل');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 99, NULL, 'is not to be accepted as a charge against him, because no such narration exists in their books; and that even granting it, it is neither objectionable nor an error, since it was a sound exercise of judgment; and that if it were permissible to call it an error on his part, then what certain imams added — the saying', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'is not to be accepted as a charge against him because no such narration exists in their books and that even granting it it is neither objectionable nor an error since it was a sound exercise of judgment and that if it were permissible to call it an error on his part then what certain imams added the saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 100, NULL, 'Sayingأَشْهَدُ أَنَّ مَوْلَانَا عَلِيًّا وَلِيُّ اللهِ', '', 'أَشْهَدُ أَنَّ مَوْلَانَا عَلِيًّا وَلِيُّ اللهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'sayingاشهد ان مولانا عليا ولي الله', 'اشهد ان مولانا عليا ولي الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 101, NULL, '— would likewise be an error, since one who adds to the call to prayer is like one who subtracts from it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'would likewise be an error since one who adds to the call to prayer is like one who subtracts from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 102, NULL, 'I say: this is confusion on his part and a sophistry played upon fancies, as I shall set out and clarify in what follows, with the help and enabling grace of God. Even if we were to concede, for the sake of argument, that error lies in both addition and subtraction in the call to prayer, we do not concede that the one who adds and the one who subtracts stand equal in their degree of error. To make them equal is gross error and plain misguidance, for several reasons:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'i say this is confusion on his part and a sophistry played upon fancies as i shall set out and clarify in what follows with the help and enabling grace of god even if we were to concede for the sake of argument that error lies in both addition and subtraction in the call to prayer we do not concede that the one who adds and the one who subtracts stand equal in their degree of error to make them equal is gross error and plain misguidance for several reasons', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 103, NULL, 'The first: consider how many are those who follow the subtraction from the call to prayer compared with those who follow the addition in it — as one to a hundred thousand or fewer. The one who subtracted therefore led great numbers of people astray, so his offense is greater than that of the one who added.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'the first consider how many are those who follow the subtraction from the call to prayer compared with those who follow the addition in it as one to a hundred thousand or fewer the one who subtracted therefore led great numbers of people astray so his offense is greater than that of the one who added', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 104, NULL, 'The second: he ascribes this addition to our master the Imam al-Hakim bi-Amr Allah, the blessings of God be upon him. If that is granted, then the one who subtracted must have preceded him in error and in leading the community astray by more than four hundred years, since al-Hakim was not born until after the fourth century. The one who goes before in error holds a greater degree of offense, and the two are not equal.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'the second he ascribes this addition to our master the imam al hakim bi amr allah the blessings of god be upon him if that is granted then the one who subtracted must have preceded him in error and in leading the community astray by more than four hundred years since al hakim was not born until after the fourth century the one who goes before in error holds a greater degree of offense and the two are not equal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 105, NULL, 'The third: had the one who subtracted confined himself to subtraction, he and the one who added would stand at a single degree. But along with his subtraction he added, by his own opinion, a sentence of the ugliest and feeblest sort — namely, his saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'the third had the one who subtracted confined himself to subtraction he and the one who added would stand at a single degree but along with his subtraction he added by his own opinion a sentence of the ugliest and feeblest sort namely his saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 106, NULL, 'Sayingالصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ', '', 'الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'sayingالصلاه خير من النوم', 'الصلاه خير من النوم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 107, NULL, 'Glory be to God! Where is prayer and where is sleep, that the two should be set against each other in terms of better and lesser, like one who says, "This sword is better than wood," not knowing whether he is praising or mocking? So the one who subtracted holds two errors, while the one who adds to the call to prayer holds one, and the two are not equal.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'glory be to god where is prayer and where is sleep that the two should be set against each other in terms of better and lesser like one who says this sword is better than wood not knowing whether he is praising or mocking so the one who subtracted holds two errors while the one who adds to the call to prayer holds one and the two are not equal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 108, NULL, 'The fourth: grant that it was his exercise of judgment. Why then did he command the dropping of the Prophet''s phrase from all five prayer times, yet attach his own sentence only once, in the dawn prayer? And how many hideous and feeble things are contained in this sentence — matters I have left aside for fear of length.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'the fourth grant that it was his exercise of judgment why then did he command the dropping of the prophets phrase from all five prayer times yet attach his own sentence only once in the dawn prayer and how many hideous and feeble things are contained in this sentence matters i have left aside for fear of length', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 109, NULL, 'As for the ascription of this addition to our master al-Hakim bi-Amr Allah, the blessings of God be upon him — while the Twelver Shia, despite their disagreement with him in school, nonetheless employ this sentence in the call to prayer — it is a plainly void ascription, and whoever makes it speaks in raving slander.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'as for the ascription of this addition to our master al hakim bi amr allah the blessings of god be upon him while the twelver shia despite their disagreement with him in school nonetheless employ this sentence in the call to prayer it is a plainly void ascription and whoever makes it speaks in raving slander', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 110, NULL, 'As for his saying that ascribing this subtraction to Umar ibn al-Khattab is unacceptable because it does not exist in the books of those people: his saying carries no weight. Regarding the books that those people rely on for soundness — such as Sahih al-Bukhari and the rest of the five and al-Mishkat — the disagreement of their own scholars over those books'' soundness, and the fabricated reports found within them, relieve the people of truth of any need to refute them or to set up proofs against them. Moreover, the narration transmitted by our master al-Qadi al-Numan from our master Jafar al-Sadiq predates the compilation of those people''s books; and it may well be that when they saw in it an opening for censure against them, they dropped it and erased it, fearing to give room to the censure of the people of truth — for such has been their custom. This is the refutation of the saying that one who adds to the call to prayer is like one who subtracts from it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'as for his saying that ascribing this subtraction to umar ibn al khattab is unacceptable because it does not exist in the books of those people his saying carries no weight regarding the books that those people rely on for soundness such as sahih al bukhari and the rest of the five and al mishkat the disagreement of their own scholars over those books soundness and the fabricated reports found within them relieve the people of truth of any need to refute them or to set up proofs against them moreover the narration transmitted by our master al qadi al numan from our master jafar al sadiq predates the compilation of those peoples books and it may well be that when they saw in it an opening for censure against them they dropped it and erased it fearing to give room to the censure of the people of truth for such has been their custom this is the refutation of the saying that one who adds to the call to prayer is like one who subtracts from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 111, NULL, 'As for the origin of the ascription of this addition, the answer is that this phrase and the testimony to guardianship issued from the Commander of the Believers, Ali ibn Abi Talib, concerning himself, when the office of guardianship passed to him after the Prophet — just as the Prophet testified for himself to prophethood and messengership, and as God, glorified is He, testified concerning His own essence, saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'as for the origin of the ascription of this addition the answer is that this phrase and the testimony to guardianship issued from the commander of the believers ali ibn abi talib concerning himself when the office of guardianship passed to him after the prophet just as the prophet testified for himself to prophethood and messengership and as god glorified is he testified concerning his own essence saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 112, NULL, 'Ali ''Imran: 18شَهِدَ اللهُ أَنَّهُ لَا إِلَهَ إِلَّا هُوَ', '', 'شَهِدَ اللهُ أَنَّهُ لَا إِلَهَ إِلَّا هُوَ', 'Ali ''Imran: 18', 3, 18, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'ali imran 18شهد الله انه لا اله الا هو', 'شهد الله انه لا اله الا هو');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 113, NULL, 'And that was after the verse of guardianship was revealed concerning him — His saying, "Your guardian is only God and His Messenger," to the end of it. Though they have disagreed about the occasion of its revelation, out of a desire on their part to deny his guardianship, their books are nonetheless filled with testimony that it was revealed concerning the Commander of the Believers, the blessings of God be upon him. In this there is sufficiency for those who seek right direction and guidance; and as for the stubborn disputer, he has nothing but going astray.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'and that was after the verse of guardianship was revealed concerning him his saying your guardian is only god and his messenger to the end of it though they have disagreed about the occasion of its revelation out of a desire on their part to deny his guardianship their books are nonetheless filled with testimony that it was revealed concerning the commander of the believers the blessings of god be upon him in this there is sufficiency for those who seek right direction and guidance and as for the stubborn disputer he has nothing but going astray', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 114, NULL, 'Sayingوَكُلُّ إِنَاءٍ يَتَرَشَّحُ بِمَا فِيهِ وَاللهُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ', '', 'وَكُلُّ إِنَاءٍ يَتَرَشَّحُ بِمَا فِيهِ وَاللهُ يَهْدِي مَنْ يَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'sayingوكل اناء يترشح بما فيه والله يهدي من يشاء الي صراط مستقيم', 'وكل اناء يترشح بما فيه والله يهدي من يشاء الي صراط مستقيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eight proofs for the best of human beings', '15. Eight Proofs for the Best of Human Beings', 115, NULL, 'Every vessel seeps with what is in it, and God guides whom He wills to a straight path.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 15 eight proofs for the best of human beings', 'every vessel seeps with what is in it and god guides whom he wills to a straight path', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 0, NULL, 'In the book of questions and answers I mentioned at the outset — arranged by one of its compilers in the order of the chapters of Daaim al-Islam — I find the matter of mosques treated as follows.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'in the book of questions and answers i mentioned at the outset arranged by one of its compilers in the order of the chapters of daaim al islam i find the matter of mosques treated as follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 1, NULL, 'Question: What do you say concerning what has come in the Sharia forbidding prayer between graves, the dislike of building a mosque beside them, and the saying of the Messenger of God (ع):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'question what do you say concerning what has come in the sharia forbidding prayer between graves the dislike of building a mosque beside them and the saying of the messenger of god ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 2, NULL, 'Sayingجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا إِلَّا الْحَمَّامَ وَالْمَقْبَرَةَ وَالْحُشَّ', '', 'جُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا إِلَّا الْحَمَّامَ وَالْمَقْبَرَةَ وَالْحُشَّ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'sayingجعلت لي الارض مسجدا وطهورا الا الحمام والمقبره والحش', 'جعلت لي الارض مسجدا وطهورا الا الحمام والمقبره والحش');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 3, NULL, 'The earth has been made for me a place of prayer and a means of purification, except for the bathhouse, the cemetery, and the latrine.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'the earth has been made for me a place of prayer and a means of purification except for the bathhouse the cemetery and the latrine', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 4, NULL, 'Explain its detail to us. Answer: This is in accordance with what has been stated in the outward sense of the Sharia. One does not pray in any of those places at all, and no mosque is built beside graves.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'explain its detail to us answer this is in accordance with what has been stated in the outward sense of the sharia one does not pray in any of those places at all and no mosque is built beside graves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 5, NULL, 'Question: What do you say concerning a mosque given over to public use that stands above a house or a shop: may its owners remove it and pull it down, or not? Answer: If it belongs to him alone and he has not given it over to public use, he may pull it down. If it has been given over to public use, it is not lawful for him to pull it down; and if it collapses on its own, nothing is owed by him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'question what do you say concerning a mosque given over to public use that stands above a house or a shop may its owners remove it and pull it down or not answer if it belongs to him alone and he has not given it over to public use he may pull it down if it has been given over to public use it is not lawful for him to pull it down and if it collapses on its own nothing is owed by him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 6, NULL, 'Question: What do you say concerning a man who wishes to build the congregational mosque or another on his own property: must he seek the governor''s permission for that, or not? Answer: He does as he wishes and does not seek permission.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'question what do you say concerning a man who wishes to build the congregational mosque or another on his own property must he seek the governors permission for that or not answer he does as he wishes and does not seek permission', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 7, NULL, 'Question: What do you say concerning what has come in the Book of Purity — that there is no prayer for the neighbor of the mosque except in the mosque, meaning that his prayer does not carry the merit of one who prays in the mosque — and also that the prayer of a man alone in his house is a single prayer? So, our master, what is the difference between the neighbor of the mosque and any other person, if the prayer of a man in his house is a single prayer? Answer: The neighbor of the mosque is the one who hears the call to prayer, and the prayer of a man without congregation is a single prayer. For the neighbor of the mosque, however, it is disliked for him to pray alone in his house without an excuse.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'question what do you say concerning what has come in the book of purity that there is no prayer for the neighbor of the mosque except in the mosque meaning that his prayer does not carry the merit of one who prays in the mosque and also that the prayer of a man alone in his house is a single prayer so our master what is the difference between the neighbor of the mosque and any other person if the prayer of a man in his house is a single prayer answer the neighbor of the mosque is the one who hears the call to prayer and the prayer of a man without congregation is a single prayer for the neighbor of the mosque however it is disliked for him to pray alone in his house without an excuse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 8, NULL, 'Question: What do you say concerning what is related in the Book of Purity — that when the mosque of the Prophet (ع) leaked, the people said, "O Messenger of God, if only we plastered it," and he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'question what do you say concerning what is related in the book of purity that when the mosque of the prophet ع leaked the people said o messenger of god if only we plastered it and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 9, NULL, 'Sayingلَا، عَرِيشٌ كَعَرِيشِ مُوسَىٰ', '', 'لَا، عَرِيشٌ كَعَرِيشِ مُوسَىٰ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'sayingلا عريش كعريش موسي', 'لا عريش كعريش موسي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 10, NULL, 'No; a shelter like the shelter of Moses.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'no a shelter like the shelter of moses', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 11, NULL, 'What is the meaning of this saying? Answer: It means that this is not like the plastered shelter of Moses.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'what is the meaning of this saying answer it means that this is not like the plastered shelter of moses', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 12, NULL, 'Question: What do you say concerning a man who hears the call to prayer from a mosque in which one of the licensed men of the mission leads the prayer, while the hearer prays in his house with another licensed man: have the two of them forfeited a prayer of merit, or not? Answer: The prayer in the mosque is more excellent, as the Prophet (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'question what do you say concerning a man who hears the call to prayer from a mosque in which one of the licensed men of the mission leads the prayer while the hearer prays in his house with another licensed man have the two of them forfeited a prayer of merit or not answer the prayer in the mosque is more excellent as the prophet ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 13, NULL, 'Sayingلَا صَلَاةَ لِجَارِ الْمَسْجِدِ إِلَّا فِي الْمَسْجِدِ', '', 'لَا صَلَاةَ لِجَارِ الْمَسْجِدِ إِلَّا فِي الْمَسْجِدِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'sayingلا صلاه لجار المسجد الا في المسجد', 'لا صلاه لجار المسجد الا في المسجد');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 14, NULL, 'There is no prayer for the neighbor of the mosque except in the mosque.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'there is no prayer for the neighbor of the mosque except in the mosque', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 15, NULL, 'Question: What do you say concerning a mosque in which the imam leads the noon prayer with the congregation, while another imam leads that same prayer with another congregation on the roof: is that permissible, and is the prayer of greeting prayed both below and above, or not? Answer: There is no harm in it, and there is no prayer of greeting above it for one who has already prayed it below.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'question what do you say concerning a mosque in which the imam leads the noon prayer with the congregation while another imam leads that same prayer with another congregation on the roof is that permissible and is the prayer of greeting prayed both below and above or not answer there is no harm in it and there is no prayer of greeting above it for one who has already prayed it below', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 16, NULL, 'Question: What do you say concerning a quarter in which there are several mosques, and a man leaves his house at the time of prayer: may he pass by the nearer mosque and go to the farther one because the licensed man in the farther one is of greater rank than the licensed man of the nearer? Answer: Yes, that is established, and there is no blame upon one who does so.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'question what do you say concerning a quarter in which there are several mosques and a man leaves his house at the time of prayer may he pass by the nearer mosque and go to the farther one because the licensed man in the farther one is of greater rank than the licensed man of the nearer answer yes that is established and there is no blame upon one who does so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 17, NULL, 'Question: What does our master say concerning a mosque that a man sets up within his house but has not dedicated to God, exalted be He, as a place open to the people: may he relocate it or absorb it into an enlargement of his house, and is the prayer of greeting prayed in it, or not? Answer: If the mosque is open to the people, the prayer of greeting is prayed in it. If it is confined within the house and has not been made open, it is a place of prayer only — the prayer of greeting is not prayed in it, and he may incorporate it into whatever part of the house he wishes, as long as he has not made it open.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'question what does our master say concerning a mosque that a man sets up within his house but has not dedicated to god exalted be he as a place open to the people may he relocate it or absorb it into an enlargement of his house and is the prayer of greeting prayed in it or not answer if the mosque is open to the people the prayer of greeting is prayed in it if it is confined within the house and has not been made open it is a place of prayer only the prayer of greeting is not prayed in it and he may incorporate it into whatever part of the house he wishes as long as he has not made it open', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 18, NULL, 'Question: What does our master say concerning a man who comes to the mosque at the time of dawn while the imam is praying the obligatory prayer in congregation, and the one arriving is able to pray the Sunnah and still join the imam: does he pray the greeting and the Sunnah, or does he enter with the imam? Answer: If it is possible for him to reach the prayer before the imam bows, let him pray whatever he wishes of the Sunnah prayers before the imam raises his head from bowing.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'question what does our master say concerning a man who comes to the mosque at the time of dawn while the imam is praying the obligatory prayer in congregation and the one arriving is able to pray the sunnah and still join the imam does he pray the greeting and the sunnah or does he enter with the imam answer if it is possible for him to reach the prayer before the imam bows let him pray whatever he wishes of the sunnah prayers before the imam raises his head from bowing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 19, NULL, 'Question: What does our master say concerning a man who comes to the mosque before midday to make up an obligatory prayer he has missed: does he pray the greeting, or not? Answer: He does not pray a Sunnah prayer while an obligatory prayer is owed by him, except the Sunnah of the dawn, for that has been joined to the obligatory prayers; and the greeting is not prayed except at times when the Sunnah prayer is permitted.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'question what does our master say concerning a man who comes to the mosque before midday to make up an obligatory prayer he has missed does he pray the greeting or not answer he does not pray a sunnah prayer while an obligatory prayer is owed by him except the sunnah of the dawn for that has been joined to the obligatory prayers and the greeting is not prayed except at times when the sunnah prayer is permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 20, NULL, 'Question: What does our master say concerning one who comes while the imam is in the obligatory dawn prayer and enters into it with him: does he make up the greeting or the Sunnah after finishing it, or after midday? Answer: If he prays anything before the greeting, its time has passed. There is no harm in making up the Sunnah after the obligatory dawn prayer, as long as the sun has not yet risen — or after midday, or at night.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'question what does our master say concerning one who comes while the imam is in the obligatory dawn prayer and enters into it with him does he make up the greeting or the sunnah after finishing it or after midday answer if he prays anything before the greeting its time has passed there is no harm in making up the sunnah after the obligatory dawn prayer as long as the sun has not yet risen or after midday or at night', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 21, NULL, 'Question: What does our master say concerning an imam who has led the congregation in prayer in a mosque and then departed, after which another licensed man comes: does he lead that same prayer in congregation in that mosque, or not? Answer: Two imams do not lead prayer at one time in one assembly, unless the imam is overtaken by something that breaks his state and he appoints another imam in his place.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'question what does our master say concerning an imam who has led the congregation in prayer in a mosque and then departed after which another licensed man comes does he lead that same prayer in congregation in that mosque or not answer two imams do not lead prayer at one time in one assembly unless the imam is overtaken by something that breaks his state and he appoints another imam in his place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 22, NULL, 'Question: If the imam leads the funeral prayer with the people in the mosque, what is the ruling regarding the greeting? Answer: If they entered the mosque at a time when supererogatory prayers are permitted, they pray the greeting first.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'question if the imam leads the funeral prayer with the people in the mosque what is the ruling regarding the greeting answer if they entered the mosque at a time when supererogatory prayers are permitted they pray the greeting first', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 23, NULL, 'Other rulings follow:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'other rulings follow', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 24, NULL, 'Whoever prays in open country and finds nothing to set up as a screen draws a line and prays; he does not leave his sandal facing the qibla as a screen. Whoever prays the doubled prayer or the Sunnah of noon in his house and then comes to the mosque begins with the greeting of the mosque, if his entry is at the time of noon or when dawn has broken. Whoever builds a mosque and people are buried around it afterward, prayer in it is permitted; but if it was built after the grave, prayer in it is not permitted. It is disliked that the qibla of the mosque face toward a bathhouse, toward graves, or toward a latrine. Whoever does not know the qibla because something prevents him exerts his judgment and prays. If he errs and learns of the error while he is still in the prayer and the time is short, he turns toward the direction of the House and completes his prayer, provided he was between the east and the west; but if he had his back to the Kaaba, nothing suffices him but repetition. If two directions are confused for a man — so that he sees the qibla as lying in each of them and neither of the two prevails in his judgment — he prays toward both directions together; and the like of this has been mentioned concerning the four directions. Whoever travels and the time of prayer comes upon him on the road while he is in a state of major impurity and finds no water, and there is a mosque on the way, performs the dry ablution and prays in the mosque. If prayer has been performed in congregation in the mosque and the imam departs and the congregation departs, and a second imam comes with a congregation, that imam prays by himself and they pray by themselves. The leading of prayer is not held in one mosque more than once. Whoever enters the mosque, prays the greeting of the mosque, then goes out for a need and returns, prays the greeting of the mosque again. A man does not pray with camels facing the qibla; but if they are cattle, sheep, or the like, the prayer is permitted. Whoever prays the doubled prayer in his house in its proper time and then enters the mosque may not pray the greeting of the mosque until dawn breaks; then he begins with the greeting of the mosque and prays the dawn prayer. If he enters the mosque and prays the greeting of the mosque and the time of the doubled prayer returns, he repeats the doubled prayer, for there is no prayer between the doubled prayer and the dawn prayer. Whoever prays the obligatory prayer in the mosque, and another comes and places a sword facing the qibla, and the worshipper is under a restriction and unable to move away, completes the prayer, and his prayer is valid. It is disliked to pray between the two pillars as long as the worshipper finds another place in the mosque; and if he finds none, the prayer is permitted. If land lies between partners and one of them builds a mosque upon it, prayer in it is permitted, because he built on his own property; and if the other builds a mosque, prayer in it is permitted also.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'whoever prays in open country and finds nothing to set up as a screen draws a line and prays he does not leave his sandal facing the qibla as a screen whoever prays the doubled prayer or the sunnah of noon in his house and then comes to the mosque begins with the greeting of the mosque if his entry is at the time of noon or when dawn has broken whoever builds a mosque and people are buried around it afterward prayer in it is permitted but if it was built after the grave prayer in it is not permitted it is disliked that the qibla of the mosque face toward a bathhouse toward graves or toward a latrine whoever does not know the qibla because something prevents him exerts his judgment and prays if he errs and learns of the error while he is still in the prayer and the time is short he turns toward the direction of the house and completes his prayer provided he was between the east and the west but if he had his back to the kaaba nothing suffices him but repetition if two directions are confused for a man so that he sees the qibla as lying in each of them and neither of the two prevails in his judgment he prays toward both directions together and the like of this has been mentioned concerning the four directions whoever travels and the time of prayer comes upon him on the road while he is in a state of major impurity and finds no water and there is a mosque on the way performs the dry ablution and prays in the mosque if prayer has been performed in congregation in the mosque and the imam departs and the congregation departs and a second imam comes with a congregation that imam prays by himself and they pray by themselves the leading of prayer is not held in one mosque more than once whoever enters the mosque prays the greeting of the mosque then goes out for a need and returns prays the greeting of the mosque again a man does not pray with camels facing the qibla but if they are cattle sheep or the like the prayer is permitted whoever prays the doubled prayer in his house in its proper time and then enters the mosque may not pray the greeting of the mosque until dawn breaks then he begins with the greeting of the mosque and prays the dawn prayer if he enters the mosque and prays the greeting of the mosque and the time of the doubled prayer returns he repeats the doubled prayer for there is no prayer between the doubled prayer and the dawn prayer whoever prays the obligatory prayer in the mosque and another comes and places a sword facing the qibla and the worshipper is under a restriction and unable to move away completes the prayer and his prayer is valid it is disliked to pray between the two pillars as long as the worshipper finds another place in the mosque and if he finds none the prayer is permitted if land lies between partners and one of them builds a mosque upon it prayer in it is permitted because he built on his own property and if the other builds a mosque prayer in it is permitted also', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 25, NULL, 'From the book Mukhtasar al-Musannaf: It is disliked that the qibla of the mosque face toward a bathhouse, toward graves, or toward a latrine. Whoever does not know the qibla because something prevents him exerts his judgment and prays; if he errs and learns of the error while he is still in the prayer and the time is short, he turns toward the direction of the House and completes his prayer, if it was between the east and the west; but if he had his back to the Kaaba, nothing suffices him but repetition. And if two directions are confused for a man — so that he sees the qibla as lying in each of them and neither of the two prevails in his judgment — he prays toward both directions together; and the like of this has been mentioned concerning the four directions.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'from the book mukhtasar al musannaf it is disliked that the qibla of the mosque face toward a bathhouse toward graves or toward a latrine whoever does not know the qibla because something prevents him exerts his judgment and prays if he errs and learns of the error while he is still in the prayer and the time is short he turns toward the direction of the house and completes his prayer if it was between the east and the west but if he had his back to the kaaba nothing suffices him but repetition and if two directions are confused for a man so that he sees the qibla as lying in each of them and neither of the two prevails in his judgment he prays toward both directions together and the like of this has been mentioned concerning the four directions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 26, NULL, 'From the book Tawil al-Daaim: as for His saying, وسلاحكم, the laying down of weapons and the bringing of them into the mosques is not permitted in the outward sense, except for the imam of the mosque on the day of Friday.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'from the book tawil al daaim as for his saying وسلاحكم the laying down of weapons and the bringing of them into the mosques is not permitted in the outward sense except for the imam of the mosque on the day of friday', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 27, NULL, 'It is said in the book al-Idah that Abu Abd Allah (ع) disliked that a mosque be inside a house with a door locked upon it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'it is said in the book al idah that abu abd allah ع disliked that a mosque be inside a house with a door locked upon it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 28, NULL, 'It is said in Majalis al-Bayan that prayer is disliked in twelve places:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'it is said in majalis al bayan that prayer is disliked in twelve places', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 29, NULL, 'The cemetery The slaughterhouse The bathhouse The latrine The resting places of camels Prayer facing a sleeping person Prayer without a screen Upon wet, impure ground Upon anything of food Prayer in places of worship Churches The houses of the Magians, unless they have been sprinkled with water', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'the cemetery the slaughterhouse the bathhouse the latrine the resting places of camels prayer facing a sleeping person prayer without a screen upon wet impure ground upon anything of food prayer in places of worship churches the houses of the magians unless they have been sprinkled with water', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 30, NULL, 'Our master and our lord and our father, Muhammad ibn al-Fahd — may God exalt his sanctity and grant us his intercession and his company — said in his noble epistle, which he named The Clear Highway of the Path of Guidance for Those Who Seek Guidance, and the Uncoverer of Obscurities in the Juristic Questions of Religion:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'our master and our lord and our father muhammad ibn al fahd may god exalt his sanctity and grant us his intercession and his company said in his noble epistle which he named the clear highway of the path of guidance for those who seek guidance and the uncoverer of obscurities in the juristic questions of religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 31, NULL, 'Question Nineteen: You asked also — may God, glorified be He, grant you success in what pleases Him — about prayer in a domed structure or a mosque in which there is a grave on any of its sides. Answer: You have, in this too, by the granting of success from God, glorified be He, the sound word concerning it, and its truth is this: if the said domed structure or the said mosque was built for prayer to be performed in it, and afterward the making of a grave in it occurred to one who made it there and buried a dead person in it after that, then prayer in either of them is permitted, in its obligatory prayers and its Sunnah prayers. But if either of them was built on account of a grave that required it, coming after the grave, then their ruling is the ruling of the cemetery, and prayer is never permitted in either of them for one who would pray.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'question nineteen you asked also may god glorified be he grant you success in what pleases him about prayer in a domed structure or a mosque in which there is a grave on any of its sides answer you have in this too by the granting of success from god glorified be he the sound word concerning it and its truth is this if the said domed structure or the said mosque was built for prayer to be performed in it and afterward the making of a grave in it occurred to one who made it there and buried a dead person in it after that then prayer in either of them is permitted in its obligatory prayers and its sunnah prayers but if either of them was built on account of a grave that required it coming after the grave then their ruling is the ruling of the cemetery and prayer is never permitted in either of them for one who would pray', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 32, NULL, 'He said also — may God exalt his sanctity — in the noble epistle mentioned, concerning the matter of the greeting of the mosque built for the seeking of the face of its Owner:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'he said also may god exalt his sanctity in the noble epistle mentioned concerning the matter of the greeting of the mosque built for the seeking of the face of its owner', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 33, NULL, 'You also asked — may God, glorified be He, grant you success in all that pleases Him — about the prayer of greeting the mosque: is it obligatory only within the mosque itself, never in its courtyard and forecourt? And if someone enters the mosque and performs it there, then goes out to the courtyard and returns, is he obliged to perform it again on account of that departure, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'you also asked may god glorified be he grant you success in all that pleases him about the prayer of greeting the mosque is it obligatory only within the mosque itself never in its courtyard and forecourt and if someone enters the mosque and performs it there then goes out to the courtyard and returns is he obliged to perform it again on account of that departure or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 34, NULL, 'Here too, with the granting of success from God, glorified be He, you have reached the sound word on the matter. The truth of it is this: the greeting prayer is obligatory only within the mosque itself — not in its courtyard and not in its forecourt. If it is performed in those areas, that is good, since they have become part of the mosque and within its bounds. Therefore, if a person inside the mosque goes out to the courtyard and returns — as I have explained — he is not obliged to repeat it, because he has not yet gone out from the mosque''s bounds.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'here too with the granting of success from god glorified be he you have reached the sound word on the matter the truth of it is this the greeting prayer is obligatory only within the mosque itself not in its courtyard and not in its forecourt if it is performed in those areas that is good since they have become part of the mosque and within its bounds therefore if a person inside the mosque goes out to the courtyard and returns as i have explained he is not obliged to repeat it because he has not yet gone out from the mosques bounds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 35, NULL, 'The book Tawil al-Sharia records, relating it from the Prophet (ع), that he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'the book tawil al sharia records relating it from the prophet ع that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 36, NULL, 'Sayingلَا تُقَامُ الْحُدُودُ فِي الْمَسَاجِدِ، وَمَنْ سَمِعْتُمُوهُ يُنْشِدُ ضَالَّتَهُ فِي مَسْجِدٍ فَقُولُوا: لا وجدت', '', 'لَا تُقَامُ الْحُدُودُ فِي الْمَسَاجِدِ، وَمَنْ سَمِعْتُمُوهُ يُنْشِدُ ضَالَّتَهُ فِي مَسْجِدٍ فَقُولُوا: لا وجدت', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'sayingلا تقام الحدود في المساجد ومن سمعتموه ينشد ضالته في مسجد فقولوا لا وجدت', 'لا تقام الحدود في المساجد ومن سمعتموه ينشد ضالته في مسجد فقولوا لا وجدت');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 37, NULL, 'The prescribed penalties are not to be carried out in the mosques; and whoever you hear calling out for his lost property in a mosque, say to him: May you not find it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'the prescribed penalties are not to be carried out in the mosques and whoever you hear calling out for his lost property in a mosque say to him may you not find it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 38, NULL, 'The same book records that the Prophet (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'the same book records that the prophet ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 39, NULL, 'Sayingلَا بَأْسَ بِالصَّلَاةِ فِي مَرَابِضِ الْغَنَمِ', '', 'لَا بَأْسَ بِالصَّلَاةِ فِي مَرَابِضِ الْغَنَمِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'sayingلا باس بالصلاه في مرابض الغنم', 'لا باس بالصلاه في مرابض الغنم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 40, NULL, 'There is no harm in praying in the folds of sheep.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'there is no harm in praying in the folds of sheep', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 41, NULL, 'The author of al-Majalis al-Mustansiriyya — may the peace of God be upon its author — said in the eighth assembly: Hear now what we set before you concerning its meaning: prayer has seven ranks, by which the prayers of those who pray are graded one above another:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'the author of al majalis al mustansiriyya may the peace of god be upon its author said in the eighth assembly hear now what we set before you concerning its meaning prayer has seven ranks by which the prayers of those who pray are graded one above another', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 42, NULL, 'the prayer of the worshipper in his house, as a single prayer; the prayer of the worshipper in the mosque of the market, as twelve prayers; the prayer of the worshipper in the mosque of the tribe, as twenty-five prayers; the prayer of the worshipper in the congregational mosque, as one hundred prayers; the prayer of the worshipper in the Farthest Mosque, as one thousand prayers; the prayer of the worshipper in the mosque of the Messenger of God, as ten thousand prayers; the prayer of the worshipper in the Sacred House of God, as one hundred thousand prayers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'the prayer of the worshipper in his house as a single prayer the prayer of the worshipper in the mosque of the market as twelve prayers the prayer of the worshipper in the mosque of the tribe as twenty five prayers the prayer of the worshipper in the congregational mosque as one hundred prayers the prayer of the worshipper in the farthest mosque as one thousand prayers the prayer of the worshipper in the mosque of the messenger of god as ten thousand prayers the prayer of the worshipper in the sacred house of god as one hundred thousand prayers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 43, NULL, 'For every one of these there are abundant meanings and likenesses of wisdom.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'for every one of these there are abundant meanings and likenesses of wisdom', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 44, NULL, 'Our lord, the Commander of the Believers, Ali ibn Abi Talib (ع), said in his four hundred rules of conduct:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'our lord the commander of the believers ali ibn abi talib ع said in his four hundred rules of conduct', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 45, NULL, 'Sayingالْجُلُوسُ فِي الْمَسْجِدِ بَعْدَ طُلُوعِ الْفَجْرِ إِلَىٰ طُلُوعِ الشَّمْسِ أَسْرَعُ لِطَلَبِ الرِّزْقِ مِنَ الضَّرْبِ فِي الْأَرْضِ', '', 'الْجُلُوسُ فِي الْمَسْجِدِ بَعْدَ طُلُوعِ الْفَجْرِ إِلَىٰ طُلُوعِ الشَّمْسِ أَسْرَعُ لِطَلَبِ الرِّزْقِ مِنَ الضَّرْبِ فِي الْأَرْضِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'sayingالجلوس في المسجد بعد طلوع الفجر الي طلوع الشمس اسرع لطلب الرزق من الضرب في الارض', 'الجلوس في المسجد بعد طلوع الفجر الي طلوع الشمس اسرع لطلب الرزق من الضرب في الارض');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 46, NULL, 'Sitting in the mosque from the breaking of dawn until the rising of the sun is أسرع for seeking provision than traveling إِلَى الْأَرْضِ.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'sitting in the mosque from the breaking of dawn until the rising of the sun is اسرع for seeking provision than traveling الي الارض', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 47, NULL, 'And he said in it: The Muslim is not to spit toward the qibla; and if he does so forgetfully, let him ask forgiveness. And he said in it: A man is not to blow upon the place of his prostration, nor upon his food, nor upon his incense. And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'and he said in it the muslim is not to spit toward the qibla and if he does so forgetfully let him ask forgiveness and he said in it a man is not to blow upon the place of his prostration nor upon his food nor upon his incense and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 48, NULL, 'Sayingولا يصلي أحدكم وبين يديه سيف، فإن القبلة آمن', '', 'ولا يصلي أحدكم وبين يديه سيف، فإن القبلة آمن', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'sayingولا يصلي احدكم وبين يديه سيف فان القبله امن', 'ولا يصلي احدكم وبين يديه سيف فان القبله امن');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 49, NULL, 'None of you is to pray with a sword before him, for the qibla is a place of safety.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'none of you is to pray with a sword before him for the qibla is a place of safety', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'where a muslim stands to pray', '16. Where a Muslim Stands to Pray', 50, NULL, 'And he said in it: Whoever eats any of the offensive foods, let him not come near the mosque.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 16 where a muslim stands to pray', 'and he said in it whoever eats any of the offensive foods let him not come near the mosque', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 0, NULL, 'I come now to the subject of the imamate.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'i come now to the subject of the imamate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 1, NULL, 'I begin with the book of questions and answers I named at the outset, which its compiler arranged according to the order of the chapters of دَعَائِمُ الْإِسْلَامِ.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'i begin with the book of questions and answers i named at the outset which its compiler arranged according to the order of the chapters of دعايم الاسلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 2, NULL, 'Question: What do you say concerning an imam who prays with the people in the arch of the qibla while they stand behind him in the public mosque, given that the common people dislike the imam''s prayer in the arch, though not his prostration in it?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning an imam who prays with the people in the arch of the qibla while they stand behind him in the public mosque given that the common people dislike the imams prayer in the arch though not his prostration in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 3, NULL, 'Answer: There is no harm in praying and prostrating in it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'answer there is no harm in praying and prostrating in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 4, NULL, 'Question: What do you say concerning a traveler who follows a resident in a four-cycle prayer and prays two cycles with him? Is it better for him to give the greeting of peace and depart, or to remain until he gives the greeting together with the imam at the end of the cycles?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning a traveler who follows a resident in a four cycle prayer and prays two cycles with him is it better for him to give the greeting of peace and depart or to remain until he gives the greeting together with the imam at the end of the cycles', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 5, NULL, 'Answer: It is better for him to remain until he gives the greeting together with the imam.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'answer it is better for him to remain until he gives the greeting together with the imam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 6, NULL, 'Question: What do you say concerning what has come in the Shariah forbidding prayer behind the محدود? O our master, what is meant here by the حد and by the one so described?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning what has come in the shariah forbidding prayer behind the محدود o our master what is meant here by the حد and by the one so described', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 7, NULL, 'Answer: The محدود is one upon whom the prescribed penalty has been carried out.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'answer the محدود is one upon whom the prescribed penalty has been carried out', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 8, NULL, 'Question: What do you say concerning what has come in the Shariah, that the one in fetters does not lead those who are free of them? O our master, does this refer to every kind of bond and shackle placed upon him, or only those upon the legs?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning what has come in the shariah that the one in fetters does not lead those who are free of them o our master does this refer to every kind of bond and shackle placed upon him or only those upon the legs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 9, NULL, 'Answer: What is meant is bonds and shackles upon the legs and elsewhere.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'answer what is meant is bonds and shackles upon the legs and elsewhere', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 10, NULL, 'Question: What do you say concerning what has come in the Shariah, that there is no harm in praying behind a slave if he is learned in jurisprudence and there is none present more learned than he to lead his people? O our master, does "his people" mean those like him among the slaves, or all who are below him in rank?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning what has come in the shariah that there is no harm in praying behind a slave if he is learned in jurisprudence and there is none present more learned than he to lead his people o our master does his people mean those like him among the slaves or all who are below him in rank', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 11, NULL, 'Answer: He leads whoever is below him in rank, even if they are free men.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'answer he leads whoever is below him in rank even if they are free men', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 12, NULL, 'Question: What do you say concerning one granted license who prays with the people while some of the common people are with him, and who therefore omits saying رَبَّنَا لَكَ الْحَمْدُ out of taqiyya? Does a deficiency enter his prayer or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning one granted license who prays with the people while some of the common people are with him and who therefore omits saying ربنا لك الحمد out of taqiyya does a deficiency enter his prayer or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 13, NULL, 'Answer: There is no harm in it for the sake of taqiyya, but he should not omit it for any cause other than taqiyya. Rather, let him use it as the pure friends of God used it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'answer there is no harm in it for the sake of taqiyya but he should not omit it for any cause other than taqiyya rather let him use it as the pure friends of god used it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 14, NULL, 'Question: What do you say concerning a ship — broad, long, and wide — in which an imam prays the noon prayer with the people in one part of it, and then another imam prays that same prayer in another part, and likewise in a spacious house? Is that permitted or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning a ship broad long and wide in which an imam prays the noon prayer with the people in one part of it and then another imam prays that same prayer in another part and likewise in a spacious house is that permitted or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 15, NULL, 'Answer: If there is a partition between them, there is no harm. Otherwise, two imams are not to be gathered in one place, unless the later of them is the more excellent. The meaning of "gathering" here is this: one granted license prays the noon prayer with the people in a house or elsewhere, and then one above him among those granted license comes and prays that same prayer with another congregation in that same house with no partition between them. That is permitted to him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'answer if there is a partition between them there is no harm otherwise two imams are not to be gathered in one place unless the later of them is the more excellent the meaning of gathering here is this one granted license prays the noon prayer with the people in a house or elsewhere and then one above him among those granted license comes and prays that same prayer with another congregation in that same house with no partition between them that is permitted to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 16, NULL, 'Question: What do you say concerning an imam who prays with the people on a ship while seated — because of the movement of the ship, the narrowness of the place, or some other cause that makes standing impossible? Is that permitted or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning an imam who prays with the people on a ship while seated because of the movement of the ship the narrowness of the place or some other cause that makes standing impossible is that permitted or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 17, NULL, 'Answer: There is no harm in it for necessity, whatever the necessity may be.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'answer there is no harm in it for necessity whatever the necessity may be', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 18, NULL, 'Question: What do you say concerning an imam who prays with the people and stands ahead of them by a span or so, while all those following him have taken their place on his right and have left his left side empty, and so they prayed? Is their prayer valid or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning an imam who prays with the people and stands ahead of them by a span or so while all those following him have taken their place on his right and have left his left side empty and so they prayed is their prayer valid or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 19, NULL, 'Answer: They may pray on his right or on his left, and there is no harm in his standing slightly ahead. Their prayer is sound.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'answer they may pray on his right or on his left and there is no harm in his standing slightly ahead their prayer is sound', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 20, NULL, 'Question: What do you say concerning a man who prays the obligatory sunset prayer with the people while the people of the outward have also gathered with him? How is he to recite بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ aloud, when among them that is not permitted at all?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning a man who prays the obligatory sunset prayer with the people while the people of the outward have also gathered with him how is he to recite بسم الله الرحمن الرحيم aloud when among them that is not permitted at all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 21, NULL, 'Answer: He must recite بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ aloud, but he may lower his voice so that he hears himself only, for the sake of taqiyya.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'answer he must recite بسم الله الرحمن الرحيم aloud but he may lower his voice so that he hears himself only for the sake of taqiyya', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 22, NULL, 'Question: What do you say concerning one granted license who prays with the people, and certain letters do not come out of his mouth correctly — either because his teeth have fallen out or because he knows little of the points of articulation? Is it permitted to complete the prayer with him or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning one granted license who prays with the people and certain letters do not come out of his mouth correctly either because his teeth have fallen out or because he knows little of the points of articulation is it permitted to complete the prayer with him or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 23, NULL, 'Answer: If he alters anything of the meaning, the prayer is spoiled.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'answer if he alters anything of the meaning the prayer is spoiled', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 24, NULL, 'Question: What do you say concerning one granted license who prays with the people and whose nose bleeds in the midst of his prayer? May he appoint in his place, to complete the prayer, one whom he sees as fit for it — though that person is not among those to whom leave has been given to appoint — or is the prayer left void?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning one granted license who prays with the people and whose nose bleeds in the midst of his prayer may he appoint in his place to complete the prayer one whom he sees as fit for it though that person is not among those to whom leave has been given to appoint or is the prayer left void', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 25, NULL, 'Answer: If he is one granted unrestricted leave, there is no harm, and he may put forward whom he wishes.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'answer if he is one granted unrestricted leave there is no harm and he may put forward whom he wishes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 26, NULL, 'Question: What does our master say concerning a mosque in which an imam prays the noon prayer with the people, and when they have departed another one granted license comes and prays that same prayer there with the people — they not knowing of the first prayer, and then afterward coming to know? Are they ordered to repeat the prayer or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what does our master say concerning a mosque in which an imam prays the noon prayer with the people and when they have departed another one granted license comes and prays that same prayer there with the people they not knowing of the first prayer and then afterward coming to know are they ordered to repeat the prayer or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 27, NULL, 'Answer: The prayer has been completed and there is no repetition required of them, whether they knew of it or did not know.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'answer the prayer has been completed and there is no repetition required of them whether they knew of it or did not know', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 28, NULL, 'Sayingفَخُذْ مَا آتَيْتُهُ وَكُنْ مِنَ الشَّاكِرِينَ', '', 'فَخُذْ مَا آتَيْتُهُ وَكُنْ مِنَ الشَّاكِرِينَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'sayingفخذ ما اتيته وكن من الشاكرين', 'فخذ ما اتيته وكن من الشاكرين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 29, NULL, 'So take what you have been given, and be among the grateful.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'so take what you have been given and be among the grateful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 30, NULL, 'Question: What do you say? May a resident pray with travelers, and a traveler with residents?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say may a resident pray with travelers and a traveler with residents', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 31, NULL, 'Answer: If the traveler is more excellent than the residents, he leads them and departs after two cycles, and they rise and complete the prayer. Likewise, if the resident is more excellent than the travelers, he leads them and they depart after two cycles.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'answer if the traveler is more excellent than the residents he leads them and departs after two cycles and they rise and complete the prayer likewise if the resident is more excellent than the travelers he leads them and they depart after two cycles', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 32, NULL, 'Question: Concerning an imam who prays with a congregation and, when he has finished, recalls that there was an impurity upon him which he had known of before the prayer and had forgotten to wash away — does the one who prayed with the imam repeat both the obligatory prayer and the sunna, or is nothing required of him but the repetition of the obligatory prayer without the sunna?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question concerning an imam who prays with a congregation and when he has finished recalls that there was an impurity upon him which he had known of before the prayer and had forgotten to wash away does the one who prayed with the imam repeat both the obligatory prayer and the sunna or is nothing required of him but the repetition of the obligatory prayer without the sunna', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 33, NULL, 'Answer: Nothing is required of the follower but the repetition of the obligatory prayer. As for the sunnas, no.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'answer nothing is required of the follower but the repetition of the obligatory prayer as for the sunnas no', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 34, NULL, 'From another source: if a eunuch prays with women it is permitted, and his sitting with them is permitted.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'from another source if a eunuch prays with women it is permitted and his sitting with them is permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 35, NULL, 'From the book مُخْتَصَرُ الْمُصَنَّفِ: if a man opens an obligatory prayer for himself, wherever he may be, and then an imam comes and steps forward, it is recommended that the man bow and prostrate until he completes that cycle, count it as a supererogatory prayer for himself, and begin the prayer anew with the imam. If he does not do so and continues his prayer alone, that suffices him. If some of those following stand in front of the imam, the prayer of the imam is valid, and so is the prayer of whoever stands at his side, but the prayer of whoever stands in front of him is not valid.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'from the book مختصر المصنف if a man opens an obligatory prayer for himself wherever he may be and then an imam comes and steps forward it is recommended that the man bow and prostrate until he completes that cycle count it as a supererogatory prayer for himself and begin the prayer anew with the imam if he does not do so and continues his prayer alone that suffices him if some of those following stand in front of the imam the prayer of the imam is valid and so is the prayer of whoever stands at his side but the prayer of whoever stands in front of him is not valid', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 36, NULL, 'When prayer is held in Mecca and the rows encircle the Kaaba, no row may draw closer to the Kaaba''s walls than the imam''s position, from any direction.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'when prayer is held in mecca and the rows encircle the kaaba no row may draw closer to the kaabas walls than the imams position from any direction', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 37, NULL, 'If one who has not yet reached maturity holds the office of appointed governor over the Muslims, no one may stand ahead of him in prayer — though the imamate of other boys is not permitted in the obligatory prayers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'if one who has not yet reached maturity holds the office of appointed governor over the muslims no one may stand ahead of him in prayer though the imamate of other boys is not permitted in the obligatory prayers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 38, NULL, 'One whose recitation is so distorted that it alters the meanings of the Quran may not step forward to lead. Nor may one whose deafness prevents him from hearing when he is corrected.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'one whose recitation is so distorted that it alters the meanings of the quran may not step forward to lead nor may one whose deafness prevents him from hearing when he is corrected', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 39, NULL, 'When the master of a slave is present in the slave''s own dwelling, the master holds the stronger right to the imamate.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'when the master of a slave is present in the slaves own dwelling the master holds the stronger right to the imamate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 40, NULL, 'The book of the interpretation of the Shariah of our master al-Muizz records, on the authority of the Prophet (ع), that he once rode a horse that stumbled beneath him; he fell, and his right side was injured. His companions came to visit him. When the time of prayer arrived, he led them in prayer while seated. They rose to stand, and he signaled to them to sit — so they sat. When he had completed his prayer, he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'the book of the interpretation of the shariah of our master al muizz records on the authority of the prophet ع that he once rode a horse that stumbled beneath him he fell and his right side was injured his companions came to visit him when the time of prayer arrived he led them in prayer while seated they rose to stand and he signaled to them to sit so they sat when he had completed his prayer he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 41, NULL, 'Sayingإِنَّمَا الْإِمَامُ لِيُؤْتَمَّ بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا فَإِذَا قَرَأَ فَأَنْصِتُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا لَكَ الْحَمْدُ اللَّهُ أَكْبَرُ وَإِذَا سَلَّمَ فَسَلِّمُوا وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعِينَ', '', 'إِنَّمَا الْإِمَامُ لِيُؤْتَمَّ بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا فَإِذَا قَرَأَ فَأَنْصِتُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا لَكَ الْحَمْدُ اللَّهُ أَكْبَرُ وَإِذَا سَلَّمَ فَسَلِّمُوا وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعِينَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'sayingانما الامام ليوتم به فاذا كبر فكبروا فاذا قرا فانصتوا واذا قال سمع الله لمن حمده فقولوا ربنا لك الحمد الله اكبر واذا سلم فسلموا واذا صلي جالسا فصلوا جلوسا اجمعين', 'انما الامام ليوتم به فاذا كبر فكبروا فاذا قرا فانصتوا واذا قال سمع الله لمن حمده فقولوا ربنا لك الحمد الله اكبر واذا سلم فسلموا واذا صلي جالسا فصلوا جلوسا اجمعين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 42, NULL, 'The author of the book of glosses states that اَلْاِخْتِصَارُ permits the imamate of a blind man when there is need, though he is not to be taken as a standing imam. اَلْمُنْتَخَبَةُ further states that a blind man may not lead unless he is set straight on a given day, that he is not to be a standing imam, and that the nasib is set aside if he has led them from the side.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'the author of the book of glosses states that الاختصار permits the imamate of a blind man when there is need though he is not to be taken as a standing imam المنتخبه further states that a blind man may not lead unless he is set straight on a given day that he is not to be a standing imam and that the nasib is set aside if he has led them from the side', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 43, NULL, 'Our master al-Qadi al-Numan ibn Muhammad, in an epistle of his responding to questions put to him by some of the judges, wrote: "You asked about the imamate of the blind man. There is no harm in his leading if he is set straight, but he is not to be taken as a standing imam."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'our master al qadi al numan ibn muhammad in an epistle of his responding to questions put to him by some of the judges wrote you asked about the imamate of the blind man there is no harm in his leading if he is set straight but he is not to be taken as a standing imam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 44, NULL, 'The book مُخْتَصَرُ الْآثَارِ records: "We have related from the People of the House (عَلَيْهِمُ السَّلَامُ) that they disliked the imamate of the one afflicted with white leprosy, the leper, the child of adultery, the castrated, the owned slave, and the blind man — unless he is set straight when there is need, in which case he is not to be taken as a standing imam. Likewise, they did not hold that the bedouin should lead, nor the one upon whom the prescribed penalty has been carried out, nor the madman." It is further stated there that license was given to these persons to lead one another, each one of them leading whoever is in a condition like his own.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'the book مختصر الاثار records we have related from the people of the house عليهم السلام that they disliked the imamate of the one afflicted with white leprosy the leper the child of adultery the castrated the owned slave and the blind man unless he is set straight when there is need in which case he is not to be taken as a standing imam likewise they did not hold that the bedouin should lead nor the one upon whom the prescribed penalty has been carried out nor the madman it is further stated there that license was given to these persons to lead one another each one of them leading whoever is in a condition like his own', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 45, NULL, 'The book مُخْتَصَرُ الْمُصَنَّفِ states: if a man prays with a congregation and his ablution is then broken, and he exits the mosque without appointing anyone to complete the prayer with them, their prayer is spoiled. If they put someone forward after the imam has left the mosque, it does not suffice them. It suffices only if someone is put forward at the very moment the imam''s ablution breaks, before he exits the mosque. Furthermore, no follower may begin any act of the prayer before the imam; he must begin after him. If he precedes the imam in anything through forgetfulness, he returns to his prior position so as to remain a follower.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'the book مختصر المصنف states if a man prays with a congregation and his ablution is then broken and he exits the mosque without appointing anyone to complete the prayer with them their prayer is spoiled if they put someone forward after the imam has left the mosque it does not suffice them it suffices only if someone is put forward at the very moment the imams ablution breaks before he exits the mosque furthermore no follower may begin any act of the prayer before the imam he must begin after him if he precedes the imam in anything through forgetfulness he returns to his prior position so as to remain a follower', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 46, NULL, 'The book الْمَجَالِسُ الْحَاتِمِيَّةُ relates, on the authority of the Prophet (ع), that he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'the book المجالس الحاتميه relates on the authority of the prophet ع that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 47, NULL, 'Sayingإِنَّمَا يَخْشَى الَّذِي يَرْفَعُ رَأْسَهُ قَبْلَ الْإِمَامِ أَنْ يَمْسَخَ اللَّهُ رَأْسَهُ رَأْسَ حِمَارٍ', '', 'إِنَّمَا يَخْشَى الَّذِي يَرْفَعُ رَأْسَهُ قَبْلَ الْإِمَامِ أَنْ يَمْسَخَ اللَّهُ رَأْسَهُ رَأْسَ حِمَارٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'sayingانما يخشي الذي يرفع راسه قبل الامام ان يمسخ الله راسه راس حمار', 'انما يخشي الذي يرفع راسه قبل الامام ان يمسخ الله راسه راس حمار');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 48, NULL, 'The one who raises his head before the imam has cause to fear that God will transform his head into the head of a donkey.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'the one who raises his head before the imam has cause to fear that god will transform his head into the head of a donkey', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 49, NULL, 'In the book of purity it is stated: if a wall stands between the imam and those following him, it is not permitted for them to follow him unless they can see his prayer — either by the wall being low enough that they can see his prayer over it, or by the wall being pierced with openings, as the walls of the women''s enclosures in mosques are made.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'in the book of purity it is stated if a wall stands between the imam and those following him it is not permitted for them to follow him unless they can see his prayer either by the wall being low enough that they can see his prayer over it or by the wall being pierced with openings as the walls of the womens enclosures in mosques are made', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 50, NULL, 'In the book مُخْتَصَرُ الْمُصَنَّفِ it is stated: if a man leads a congregation in prayer and two latecomers join him, having missed part of it, then when the imam gives the greeting of peace they rise to complete what remains due from them, and one of them follows the other — the prayer of the one leading is valid, but the prayer of the one following is spoiled.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'in the book مختصر المصنف it is stated if a man leads a congregation in prayer and two latecomers join him having missed part of it then when the imam gives the greeting of peace they rise to complete what remains due from them and one of them follows the other the prayer of the one leading is valid but the prayer of the one following is spoiled', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 51, NULL, 'It is related in the book الإيضاح that the Messenger of God (ع) combined the noon and afternoon prayers, and the sunset and later evening prayers, with neither travel nor illness nor any excuse.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'it is related in the book الايضاح that the messenger of god ع combined the noon and afternoon prayers and the sunset and later evening prayers with neither travel nor illness nor any excuse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 52, NULL, 'Our master, the author of the book الْمَجَالِسُ الْمُسْتَنْصِرِيَّةُ, states in the tenth of its assemblies that the right to lead prayer belongs to seven, ranked one above another in precedence. Our master Jafar ibn Muhammad al-Sadiq (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'our master the author of the book المجالس المستنصريه states in the tenth of its assemblies that the right to lead prayer belongs to seven ranked one above another in precedence our master jafar ibn muhammad al sadiq ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 53, NULL, 'Sayingيؤم القوم أقدمهم هجرة فان استووا فأقرأهم فان استووا في حفظ القرآن فأفقههم وان استووا في علم الفقه فأكبرهم سناً وصاحب المسجد أحق بمسجده والإمام عَلَيْهِ السَّلَامُ ومن أقامه أحق من جميعهم والمرأة تصلي بالنساء ولا تتقدمهن بل يقفن عن يمينها وشمالها', '', 'يؤم القوم أقدمهم هجرة فان استووا فأقرأهم فان استووا في حفظ القرآن فأفقههم وان استووا في علم الفقه فأكبرهم سناً وصاحب المسجد أحق بمسجده والإمام عَلَيْهِ السَّلَامُ ومن أقامه أحق من جميعهم والمرأة تصلي بالنساء ولا تتقدمهن بل يقفن عن يمينها وشمالها', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'sayingيوم القوم اقدمهم هجره فان استووا فاقراهم فان استووا في حفظ القران فافقههم وان استووا في علم الفقه فاكبرهم سنا وصاحب المسجد احق بمسجده والامام عليه السلام ومن اقامه احق من جميعهم والمراه تصلي بالنساء ولا تتقدمهن بل يقفن عن يمينها وشمالها', 'يوم القوم اقدمهم هجره فان استووا فاقراهم فان استووا في حفظ القران فافقههم وان استووا في علم الفقه فاكبرهم سنا وصاحب المسجد احق بمسجده والامام عليه السلام ومن اقامه احق من جميعهم والمراه تصلي بالنساء ولا تتقدمهن بل يقفن عن يمينها وشمالها');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 54, NULL, 'Twelve among the men do not lead in prayer:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'twelve among the men do not lead in prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 55, NULL, 'A sick man does not lead the healthy. Nor does a leper. Nor one afflicted with white leprosy. Nor a madman. Nor one upon whom a prescribed penalty has been carried out. Nor the child of adultery. A bedouin does not lead the emigrants. Nor does one in fetters lead those who are free. Nor does one who has performed the dry ablution lead those who have performed the ablution with water. Nor does the mute lead those who speak. Nor does a traveler lead residents. Nor does one set apart by hostility to the household lead those who follow it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'a sick man does not lead the healthy nor does a leper nor one afflicted with white leprosy nor a madman nor one upon whom a prescribed penalty has been carried out nor the child of adultery a bedouin does not lead the emigrants nor does one in fetters lead those who are free nor does one who has performed the dry ablution lead those who have performed the ablution with water nor does the mute lead those who speak nor does a traveler lead residents nor does one set apart by hostility to the household lead those who follow it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 56, NULL, 'Each of these may lead whoever shares his own condition.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'each of these may lead whoever shares his own condition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 57, NULL, 'It is said in the book of questions — which is from the most excellent Shaykh Shamun ibn Muhammad Ghuri al-Hindi (رض) — with the answers from our master Badr al-Din Hasan ibn Idris ibn al-Hasan.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'it is said in the book of questions which is from the most excellent shaykh shamun ibn muhammad ghuri al hindi رض with the answers from our master badr al din hasan ibn idris ibn al hasan', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 58, NULL, 'Question: What do you say concerning two men, one holding license in Rajpur and the other in Jalalpur, who met in Rajpur not knowing which was the superior and which the lesser, so that the one licensed in Rajpur led while the one licensed in Jalalpur followed him — and then they met in the same way in Jalalpur, and the one licensed in Jalalpur led while the one licensed in Rajpur followed him? What is the condition of their prayer? Answer: When it is not known which of them is the more excellent, the owner of the mosque has the better right to his own mosque.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning two men one holding license in rajpur and the other in jalalpur who met in rajpur not knowing which was the superior and which the lesser so that the one licensed in rajpur led while the one licensed in jalalpur followed him and then they met in the same way in jalalpur and the one licensed in jalalpur led while the one licensed in rajpur followed him what is the condition of their prayer answer when it is not known which of them is the more excellent the owner of the mosque has the better right to his own mosque', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 59, NULL, 'Question: What do you say concerning a licensed man who stood to pray for himself, and another man came — whether before the bow or after he had bowed — and followed him, while the licensed man did not know he was leading anyone? Is the prayer valid? Answer: His prayer is valid together with the leader, even though he did not intend to lead.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning a licensed man who stood to pray for himself and another man came whether before the bow or after he had bowed and followed him while the licensed man did not know he was leading anyone is the prayer valid answer his prayer is valid together with the leader even though he did not intend to lead', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 60, NULL, 'Question: What do you say concerning an imam who prays with the people on a ship while seated, because the ship''s motion or some other cause makes standing impossible for some of them, while the rest remain able? What is the condition of their prayer? Answer: A concession has been granted in this on account of the ship, when they are unable. Whoever is able should make haste and pray alone, standing.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning an imam who prays with the people on a ship while seated because the ships motion or some other cause makes standing impossible for some of them while the rest remain able what is the condition of their prayer answer a concession has been granted in this on account of the ship when they are unable whoever is able should make haste and pray alone standing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 61, NULL, 'It is said among the questions put by certain of the shaykhs of India, with the answers from certain of our masters, the summoners of Yemen.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'it is said among the questions put by certain of the shaykhs of india with the answers from certain of our masters the summoners of yemen', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 62, NULL, 'Question: If a man prays and with him is a woman of his unmarriageable kin, where does the man stand and where does the woman? Answer: If he prays with a woman of his unmarriageable kin, he stands ahead of her and she prays behind him, or at his right but set back from him. If she is a stranger to him, her prayer alongside him is not valid unless a third person is with them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question if a man prays and with him is a woman of his unmarriageable kin where does the man stand and where does the woman answer if he prays with a woman of his unmarriageable kin he stands ahead of her and she prays behind him or at his right but set back from him if she is a stranger to him her prayer alongside him is not valid unless a third person is with them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 63, NULL, 'A further question, from among the questions of certain of the ranks of India, with its answer from certain of our masters, the summoners of Yemen: You asked about an imam who leads a people while not reciting well, bringing substitution and distortion into his recitation — as when he says أَنَّ ٱللَّهَ بَرِىٓءٌۭ مِّنَ ٱلْمُشْرِكِينَ وَرَسُولُهُۥ with a kasra upon the lam, or وَمِنْهُمْ مَنْ هَدَى اللَّهُ with a fatha upon the ha, and the like. Answer: Whoever does not recite well in such matters may not be taken as an imam. It is incumbent upon him to correct his recitation so that he does not exchange a verse of mercy for a verse of punishment, nor exchange truth for falsehood. It is not fitting for anyone to pray in the prayer of such a man. And upon whoever recites well it is incumbent to pray with the people when they call him to it and he is acceptable to them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'a further question from among the questions of certain of the ranks of india with its answer from certain of our masters the summoners of yemen you asked about an imam who leads a people while not reciting well bringing substitution and distortion into his recitation as when he says ان الله بريء من المشركين ورسوله with a kasra upon the lam or ومنهم من هدي الله with a fatha upon the ha and the like answer whoever does not recite well in such matters may not be taken as an imam it is incumbent upon him to correct his recitation so that he does not exchange a verse of mercy for a verse of punishment nor exchange truth for falsehood it is not fitting for anyone to pray in the prayer of such a man and upon whoever recites well it is incumbent to pray with the people when they call him to it and he is acceptable to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 64, NULL, 'It is said among the questions of the law whose answers are from certain of our masters: You asked about an imam who led a people and then did not know how much of the prayer he had completed or how much remained. He must build upon what is certain. If those behind him prompt him with words of glorification, he returns to the point to which they have prompted him until he arrives at what is correct, provided those behind him are certain of it. If they too do not know, and neither he nor they can determine whether he has added to the prayer or fallen short in it, he begins the prayer anew.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'it is said among the questions of the law whose answers are from certain of our masters you asked about an imam who led a people and then did not know how much of the prayer he had completed or how much remained he must build upon what is certain if those behind him prompt him with words of glorification he returns to the point to which they have prompted him until he arrives at what is correct provided those behind him are certain of it if they too do not know and neither he nor they can determine whether he has added to the prayer or fallen short in it he begins the prayer anew', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 65, NULL, 'I turn now to the mention of the congregation and the rows, again from that book of questions and answers arranged according to the order of the chapters of دَعَائِمُ الْإِسْلَامِ.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'i turn now to the mention of the congregation and the rows again from that book of questions and answers arranged according to the order of the chapters of دعايم الاسلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 66, NULL, 'Question: What do you say concerning a man who prays alone while his wife — or a woman of his unmarriageable kin — prays by herself at his right, opposite him; and concerning a man who prays while his wife, or such a woman, stands ahead of him? Is his prayer valid or not? Answer: It is not permitted for the woman to stand ahead of the man and pray while he prays behind her.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning a man who prays alone while his wife or a woman of his unmarriageable kin prays by herself at his right opposite him and concerning a man who prays while his wife or such a woman stands ahead of him is his prayer valid or not answer it is not permitted for the woman to stand ahead of the man and pray while he prays behind her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 67, NULL, 'Question: What do you say concerning a man of the people of the summons who has prayed the afternoon prayer and then prays that same prayer a second time, outside its time, for the sake of taqiyya — and some of the people of the summons follow him in taqiyya before those who are not upon the way of the People of the House (عَلَيْهِمُ السَّلَامُ), following him and praying behind him with him as their intended imam? What is the condition of their prayer, and does anything fall upon the imam in that? Answer: He does it for the sake of taqiyya, and he need not concern himself with their following him; no sin falls upon him in that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning a man of the people of the summons who has prayed the afternoon prayer and then prays that same prayer a second time outside its time for the sake of taqiyya and some of the people of the summons follow him in taqiyya before those who are not upon the way of the people of the house عليهم السلام following him and praying behind him with him as their intended imam what is the condition of their prayer and does anything fall upon the imam in that answer he does it for the sake of taqiyya and he need not concern himself with their following him no sin falls upon him in that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 68, NULL, 'Question: What do you say concerning what has come in the book of purity — that the Messenger of God (ع) came upon a man who prayed alone behind the rows with a gap before him and ordered him to repeat the prayer, and that Jafar ibn Muhammad (ع) said the like? O our master, is one who prays in that manner ordered to repeat? Answer: He is indeed ordered to repeat, and this is the established practice.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning what has come in the book of purity that the messenger of god ع came upon a man who prayed alone behind the rows with a gap before him and ordered him to repeat the prayer and that jafar ibn muhammad ع said the like o our master is one who prays in that manner ordered to repeat answer he is indeed ordered to repeat and this is the established practice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 69, NULL, 'Question: What do you say concerning a man engaged in the prayer of glorification or another supererogatory prayer? May he cut it short if he fears that the congregation will pass him by? Answer: The obligatory prayer in congregation is more excellent and more binding than any other.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning a man engaged in the prayer of glorification or another supererogatory prayer may he cut it short if he fears that the congregation will pass him by answer the obligatory prayer in congregation is more excellent and more binding than any other', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 70, NULL, 'Question: What do you say concerning a man who wishes to pray in congregation and has already entered upon a supererogatory prayer? May he cut it short if he fears that he will miss the performance of the sunna? Answer: If he fears that the obligatory prayer will pass him by, he cuts it short; otherwise he does not.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning a man who wishes to pray in congregation and has already entered upon a supererogatory prayer may he cut it short if he fears that he will miss the performance of the sunna answer if he fears that the obligatory prayer will pass him by he cuts it short otherwise he does not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 71, NULL, 'Question: What do you say concerning a man who entered the sanctified state for the obligatory prayer and had begun his recitation, and then the imam came forward while the man was still standing — and when the imam bowed, he bowed with him without renewing the sanctified state? What is the condition of his prayer? Answer: He must repeat it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning a man who entered the sanctified state for the obligatory prayer and had begun his recitation and then the imam came forward while the man was still standing and when the imam bowed he bowed with him without renewing the sanctified state what is the condition of his prayer answer he must repeat it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 72, NULL, 'Question: What do you say concerning a licensed man who stood to pray for himself, and another man came — before the bow or after he had bowed — and followed him, while the licensed man did not intend to lead anyone? Is the follower''s prayer valid or not? Answer: His prayer is valid together with the leader, even though he did not intend to lead.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question what do you say concerning a licensed man who stood to pray for himself and another man came before the bow or after he had bowed and followed him while the licensed man did not intend to lead anyone is the followers prayer valid or not answer his prayer is valid together with the leader even though he did not intend to lead', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 73, NULL, 'Question: If a man prays and with him is a woman of his unmarriageable kin — or he prays with both a man and such a woman — where does the man stand and where does the woman? Answer: If he prays with a woman of his unmarriageable kin, he stands ahead of her and she prays behind him, or at his right but set back from him. If she is a stranger to him, her prayer is not valid unless a third person is with them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question if a man prays and with him is a woman of his unmarriageable kin or he prays with both a man and such a woman where does the man stand and where does the woman answer if he prays with a woman of his unmarriageable kin he stands ahead of her and she prays behind him or at his right but set back from him if she is a stranger to him her prayer is not valid unless a third person is with them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 74, NULL, 'Question: May those holding license read the benefits of religion to women of unmarriageable kin and to others in a single gathering? Answer: If there is a screen between the man and the woman, he reads to her in such a way that she hears his speech but he does not see her. And let no man be alone with a woman unless another woman is with her, or another man with him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question may those holding license read the benefits of religion to women of unmarriageable kin and to others in a single gathering answer if there is a screen between the man and the woman he reads to her in such a way that she hears his speech but he does not see her and let no man be alone with a woman unless another woman is with her or another man with him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 75, NULL, 'Question: Concerning a man who reaches the imam in the obligatory prayer at the final sitting of witness — does he intend to complete the prayer with him or not? Answer: If he reaches him at the final sitting of witness, he intends the prayer as a follower, for the final sitting of witness is the last of the prayer''s limits. He sits and supplicates with the supplication of turning toward God, and when the imam gives the greeting of peace he rises and prays — and he has caught the congregation.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'question concerning a man who reaches the imam in the obligatory prayer at the final sitting of witness does he intend to complete the prayer with him or not answer if he reaches him at the final sitting of witness he intends the prayer as a follower for the final sitting of witness is the last of the prayers limits he sits and supplicates with the supplication of turning toward god and when the imam gives the greeting of peace he rises and prays and he has caught the congregation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 76, NULL, 'From another source, the saying of al-Sadiq Jafar ibn Muhammad (ع):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'from another source the saying of al sadiq jafar ibn muhammad ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 77, NULL, 'Sayingيَنْبَغِي لِلصُّفُوفِ أَنْ تَكُونَ تَامَّةً مُتَوَاصِلَةً بَعْضُهَا إِلَى بَعْضٍ فَيَكُونَ بَيْنَ كُلِّ صَفَّيْنِ قَدْرُ مَسْقَطِ جَسَدِ الْإِنْسَانِ إِذَا سَجَدَ فَاِنْ لَمْ يُصَلُّوا مِثْلَ هَذَا لَمْ تَكُنْ لَهُمْ صَلَاةٌ', '', 'يَنْبَغِي لِلصُّفُوفِ أَنْ تَكُونَ تَامَّةً مُتَوَاصِلَةً بَعْضُهَا إِلَى بَعْضٍ فَيَكُونَ بَيْنَ كُلِّ صَفَّيْنِ قَدْرُ مَسْقَطِ جَسَدِ الْإِنْسَانِ إِذَا سَجَدَ فَاِنْ لَمْ يُصَلُّوا مِثْلَ هَذَا لَمْ تَكُنْ لَهُمْ صَلَاةٌ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'sayingينبغي للصفوف ان تكون تامه متواصله بعضها الي بعض فيكون بين كل صفين قدر مسقط جسد الانسان اذا سجد فان لم يصلوا مثل هذا لم تكن لهم صلاه', 'ينبغي للصفوف ان تكون تامه متواصله بعضها الي بعض فيكون بين كل صفين قدر مسقط جسد الانسان اذا سجد فان لم يصلوا مثل هذا لم تكن لهم صلاه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 78, NULL, 'By "the fall of a man''s body" I mean simply that each worshipper must have sufficient room to prostrate.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'by the fall of a mans body i mean simply that each worshipper must have sufficient room to prostrate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 79, NULL, 'If the imam leads the congregation and all the rows are full, and a man arrives to find no place among them, he prays alone alongside the imam — he does not join the imam''s own row. But if the imam''s hujja, who stands in the imam''s place after him, arrives and likewise finds no place in the rows, he steps forward and stands level with the imam and prays with him. This is permitted to no one else. That is the explicit text.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'if the imam leads the congregation and all the rows are full and a man arrives to find no place among them he prays alone alongside the imam he does not join the imams own row but if the imams hujja who stands in the imams place after him arrives and likewise finds no place in the rows he steps forward and stands level with the imam and prays with him this is permitted to no one else that is the explicit text', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 80, NULL, 'It is said in the book مُخْتَصَرُ الْمُصَنَّفِ, concerning the saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'it is said in the book مختصر المصنف concerning the saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 81, NULL, 'Sayingمَنْ صَلَّى الصَّلَاةَ فِي جَمَاعَةٍ فَظُنُّوا بِهِ كُلَّ خَيْرٍ', '', 'مَنْ صَلَّى الصَّلَاةَ فِي جَمَاعَةٍ فَظُنُّوا بِهِ كُلَّ خَيْرٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'sayingمن صلي الصلاه في جماعه فظنوا به كل خير', 'من صلي الصلاه في جماعه فظنوا به كل خير');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 82, NULL, 'Whoever prays the prayer in congregation, think every good of him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'whoever prays the prayer in congregation think every good of him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 83, NULL, 'And it is said: this applies when nothing evil is known of him. And it is said in the reports that scholars differed concerning the forming of rows between the pillars — some related that it is disliked, while others held that the position permitting it is the stronger. And it has come in the book الإيضاح that the Messenger of God (ع) joined the noon and afternoon prayers, and the sunset and the later evening prayers, with neither travel nor illness nor any excuse.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'and it is said this applies when nothing evil is known of him and it is said in the reports that scholars differed concerning the forming of rows between the pillars some related that it is disliked while others held that the position permitting it is the stronger and it has come in the book الايضاح that the messenger of god ع joined the noon and afternoon prayers and the sunset and the later evening prayers with neither travel nor illness nor any excuse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 84, NULL, 'Our master Jafar ibn Sayyidna Sulayman answered — from the island of his Yemen to the island of his India — questions put to him by the author of this book, Sayyidna Ali ibn Sulayman: That which you asked about, may God preserve you, concerning the women, when they pray in congregation with men from behind a screen — whether it is incumbent upon the one of them nearest to the men to look toward them or not, and whether, if the place is connected, there is any need for them to look toward the men or not. Answer: It is incumbent upon them to look toward the men before entering the sanctified state, just as the Daudis hold that the woman whose place is near the men prays in a place close to them and keeps her gaze upon the men during the bowing and the prostration, and that otherwise there is no prayer for any of them. The intent is that if the place is connected — as through an opening or a lattice — the prayer is thereby complete, and looking toward the men before the sanctified state or after it is not permitted. Indeed, the prohibition of it has come even outside the prayer — so how much more within it, which is the greatest of all acts of worship. And looking during the bowing or the prostration, or while standing or sitting, after the sanctified state has been entered, cuts off the prayer if it is directed toward any of those who are not of unmarriageable kin, for in that is disobedience. If the place is not connected, then the woman nearest the men glances at their garments — one glance only — before entering the sanctified state, and in that is sufficiency; by it the prayer of all of them is completed.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'our master jafar ibn sayyidna sulayman answered from the island of his yemen to the island of his india questions put to him by the author of this book sayyidna ali ibn sulayman that which you asked about may god preserve you concerning the women when they pray in congregation with men from behind a screen whether it is incumbent upon the one of them nearest to the men to look toward them or not and whether if the place is connected there is any need for them to look toward the men or not answer it is incumbent upon them to look toward the men before entering the sanctified state just as the daudis hold that the woman whose place is near the men prays in a place close to them and keeps her gaze upon the men during the bowing and the prostration and that otherwise there is no prayer for any of them the intent is that if the place is connected as through an opening or a lattice the prayer is thereby complete and looking toward the men before the sanctified state or after it is not permitted indeed the prohibition of it has come even outside the prayer so how much more within it which is the greatest of all acts of worship and looking during the bowing or the prostration or while standing or sitting after the sanctified state has been entered cuts off the prayer if it is directed toward any of those who are not of unmarriageable kin for in that is disobedience if the place is not connected then the woman nearest the men glances at their garments one glance only before entering the sanctified state and in that is sufficiency by it the prayer of all of them is completed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'who may lead, and who may not', '17. Who May Lead, and Who May Not', 85, NULL, 'It is said in the interpretation of the Shariah that the Prophet (ع) saw a man praying alone and ordered him to repeat the prayer — meaning he was behind the row without standing level with the imam, facing him from behind. And it is said there: just as none may step forward to the prayer niche except one whom the imam designates when his ablution is broken, so too none of the respondents may step forward except one whom the summoner designates and deems fit for it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 17 who may lead and who may not', 'it is said in the interpretation of the shariah that the prophet ع saw a man praying alone and ordered him to repeat the prayer meaning he was behind the row without standing level with the imam facing him from behind and it is said there just as none may step forward to the prayer niche except one whom the imam designates when his ablution is broken so too none of the respondents may step forward except one whom the summoner designates and deems fit for it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 0, NULL, 'I turn now to the characteristics of the prayer and its sunnahs.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'i turn now to the characteristics of the prayer and its sunnahs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 1, NULL, 'In the question-and-answer book mentioned at the outset — arranged by one of its compilers according to the chapter order of Daaim al-Islam — the following exchange appears. Question: What do you say concerning what has come in the Book of Purity, that Ibn al-Kawwa repeatedly opposed Amir al-Muminin Ali (ع) by raising his voice during the prayer, and that Ali (ع) then recited:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'in the question and answer book mentioned at the outset arranged by one of its compilers according to the chapter order of daaim al islam the following exchange appears question what do you say concerning what has come in the book of purity that ibn al kawwa repeatedly opposed amir al muminin ali ع by raising his voice during the prayer and that ali ع then recited', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 2, NULL, 'Ar-Rum: 60فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّۭ', '', 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّۭ', 'Ar-Rum: 60', 30, 60, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'ar rum 60فاصبر ان وعد الله حق', 'فاصبر ان وعد الله حق');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 3, NULL, 'So be patient; the promise of God is true.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'so be patient the promise of god is true', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 4, NULL, 'O our master, did Ali (ع) begin the prayer with the surah of which this verse is a part, or not? Answer: No. Rather, he recited this verse in order to silence him and to rebuke him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'o our master did ali ع begin the prayer with the surah of which this verse is a part or not answer no rather he recited this verse in order to silence him and to rebuke him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 5, NULL, 'Question: What do you say concerning what has come in the books of the Shariah regarding the long portions of al-mufassal, its middle portions, and its short portions? O our master, what are their limits in the madhhab of the Ahl al-Bayt (عَلَيْهِمُ السَّلَامُ)? Answer: The long portions of al-mufassal run from al-Hujurat to al-Mujadila; its middle portions run from al-Mujadila to عَم يَتَسَآءَلُونَ; and its short portions run from عَم يَتَسَآءَلُونَ to al-Nas.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'question what do you say concerning what has come in the books of the shariah regarding the long portions of al mufassal its middle portions and its short portions o our master what are their limits in the madhhab of the ahl al bayt عليهم السلام answer the long portions of al mufassal run from al hujurat to al mujadila its middle portions run from al mujadila to عم يتساءلون and its short portions run from عم يتساءلون to al nas', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 6, NULL, 'From the same source: whoever abandons the prayer without excuse, or abandons any of the prescribed works, has broken the covenant. Whoever accuses a believer, and the accused then swears by God, and the accuser does not believe him, has broken the covenant. Whoever commits fornication or kills a believer has broken the covenant. Whoever reviles the summoner, or reviles the one whom the summoner has appointed, has broken the covenant. If the summoner commands the believer to strive with his person and his wealth, and he refuses without excuse, he has broken the covenant. Whoever forms the intention for the prayer, and then that intention slips away before he enters the prayer — whether through preoccupation, forgetfulness, or anything else — and he then prays after that, his prayer does not suffice him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'from the same source whoever abandons the prayer without excuse or abandons any of the prescribed works has broken the covenant whoever accuses a believer and the accused then swears by god and the accuser does not believe him has broken the covenant whoever commits fornication or kills a believer has broken the covenant whoever reviles the summoner or reviles the one whom the summoner has appointed has broken the covenant if the summoner commands the believer to strive with his person and his wealth and he refuses without excuse he has broken the covenant whoever forms the intention for the prayer and then that intention slips away before he enters the prayer whether through preoccupation forgetfulness or anything else and he then prays after that his prayer does not suffice him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 7, NULL, 'It is not permissible for a man to recite within himself what he has not uttered with his tongue. Whoever performs the first tashahhud is not thereby excused from the second, though the second does suffice in place of the first.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'it is not permissible for a man to recite within himself what he has not uttered with his tongue whoever performs the first tashahhud is not thereby excused from the second though the second does suffice in place of the first', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 8, NULL, 'He said in the book Mukhtasar al-Musannaf: whoever forms the intention for the prayer, and then that intention slips away before he enters it — whether through preoccupation, forgetfulness, or anything else — and he then prays after that, his prayer does not suffice him. And from the same book: the one praying makes the tawajjuh after the takbirat al-ihram, the imam and the follower being equal in this, so long as the imam has not preceded the follower in something; and he begins the recitation after the tawajjuh.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'he said in the book mukhtasar al musannaf whoever forms the intention for the prayer and then that intention slips away before he enters it whether through preoccupation forgetfulness or anything else and he then prays after that his prayer does not suffice him and from the same book the one praying makes the tawajjuh after the takbirat al ihram the imam and the follower being equal in this so long as the imam has not preceded the follower in something and he begins the recitation after the tawajjuh', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 9, NULL, 'He said in al-Ikhtisar: he opens the prayer with a takbir in which he raises his hands, spreading his palms and joining his fingers in a straight extension. The least by which the prayer is completed — its minimum — is this:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'he said in al ikhtisar he opens the prayer with a takbir in which he raises his hands spreading his palms and joining his fingers in a straight extension the least by which the prayer is completed its minimum is this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 10, NULL, 'Opening with the takbir Standing, for whoever is able Bowing Prostration Sitting for the tashahhud', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'opening with the takbir standing for whoever is able bowing prostration sitting for the tashahhud', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 11, NULL, 'Whoever performs these five limits, having forgotten or not knowing what lies beyond them, his prayer is complete. But whoever knows their limits and then deliberately omits something from the obligations or the sunnahs of the prayer has no prayer, and he must repeat what he omitted of the prayer in this way. As for the one who is ignorant of this, it is upon him to learn.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'whoever performs these five limits having forgotten or not knowing what lies beyond them his prayer is complete but whoever knows their limits and then deliberately omits something from the obligations or the sunnahs of the prayer has no prayer and he must repeat what he omitted of the prayer in this way as for the one who is ignorant of this it is upon him to learn', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 12, NULL, 'He said in al-Akhbar: the woman places her hands above her knees upon her thighs, so that she does not stoop too far and thereby raise her hindquarters.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'he said in al akhbar the woman places her hands above her knees upon her thighs so that she does not stoop too far and thereby raise her hindquarters', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 13, NULL, 'He said in the book Tawil al-Daaim: those behind the imam, when he says:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'he said in the book tawil al daaim those behind the imam when he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 14, NULL, 'Sayingسَمِعَ اللَّهُ لِمَنْ حَمِدَهُ', '', 'سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingسمع الله لمن حمده', 'سمع الله لمن حمده');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 15, NULL, 'God has heard the one who praised Him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'god has heard the one who praised him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 16, NULL, 'say quietly:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'say quietly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 17, NULL, 'Sayingرَبَّنَا لَكَ الْحَمْدُ', '', 'رَبَّنَا لَكَ الْحَمْدُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingربنا لك الحمد', 'ربنا لك الحمد');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 18, NULL, 'Our Lord, to You belongs all praise.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'our lord to you belongs all praise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 19, NULL, 'The exception is the one who relays for the imam when those praying behind him are many and one among them has been appointed to make them hear on his behalf. That man raises his voice with it and with the takbir, but he does not raise his voice with the tasbih.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the exception is the one who relays for the imam when those praying behind him are many and one among them has been appointed to make them hear on his behalf that man raises his voice with it and with the takbir but he does not raise his voice with the tasbih', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 20, NULL, 'He said in the book Mukhtasar al-Musannaf: whoever performs the first tashahhud is not thereby excused from the second, though the second suffices in place of the first. And he said in the book Tawil al-Daaim, concerning the outward sense, that when the one praying sits in the prayer he folds his left leg beneath him and keeps his right leg upright.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'he said in the book mukhtasar al musannaf whoever performs the first tashahhud is not thereby excused from the second though the second suffices in place of the first and he said in the book tawil al daaim concerning the outward sense that when the one praying sits in the prayer he folds his left leg beneath him and keeps his right leg upright', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 21, NULL, 'He said in the brief discourse on jurisprudence, whose questions come from the most eminent Shaykh Hasan ibn Mawla Adam al-Hindi and whose answers come from the sayyids of Yemen, may God sanctify all their souls: the prayer of a woman who has not undergone khafd is valid, and intimacy with her is permissible, and likewise for the man; but the sunnah is to hasten to that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'he said in the brief discourse on jurisprudence whose questions come from the most eminent shaykh hasan ibn mawla adam al hindi and whose answers come from the sayyids of yemen may god sanctify all their souls the prayer of a woman who has not undergone khafd is valid and intimacy with her is permissible and likewise for the man but the sunnah is to hasten to that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 22, NULL, 'Our master and our lord Jafar ibn Sulayman, may God exalt his sanctity and grant us his intercession and his company, said in his noble epistle, which he entitled al-Sayf al-Aqta fi Ibtal al-Bida, with which he counseled his people and roused from heedlessness those among them whose sleep had grown long — the people of the island of Yemen — after he had settled among them and taken up residence there. Section: And of this also is what has been known and witnessed of many among you, men and women alike, who cling to the mountain of loyalty and come to the rope of obedience to God, glorified be He, by way of undertaking the obligation of the prayer, and yet their foreheads do not prostrate to God, glorified be He, in a single rakah of the prayer, so that the prayer is diminished of the rakahs that belong around it. This is among the gravest of all matters in its consequence, and the most notorious of them all in repute. Has there never reached the ears of such people the word of the Messenger of God (ع):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'our master and our lord jafar ibn sulayman may god exalt his sanctity and grant us his intercession and his company said in his noble epistle which he entitled al sayf al aqta fi ibtal al bida with which he counseled his people and roused from heedlessness those among them whose sleep had grown long the people of the island of yemen after he had settled among them and taken up residence there section and of this also is what has been known and witnessed of many among you men and women alike who cling to the mountain of loyalty and come to the rope of obedience to god glorified be he by way of undertaking the obligation of the prayer and yet their foreheads do not prostrate to god glorified be he in a single rakah of the prayer so that the prayer is diminished of the rakahs that belong around it this is among the gravest of all matters in its consequence and the most notorious of them all in repute has there never reached the ears of such people the word of the messenger of god ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 23, NULL, 'Sayingبَيْنَ الْعَبْدِ وَبَيْنَ الْكُفْرِ تَرْكُ الصَّلَاةِ', '', 'بَيْنَ الْعَبْدِ وَبَيْنَ الْكُفْرِ تَرْكُ الصَّلَاةِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingبين العبد وبين الكفر ترك الصلاه', 'بين العبد وبين الكفر ترك الصلاه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 24, NULL, 'and the word of Amir al-Muminin (ع):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'and the word of amir al muminin ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 25, NULL, 'Sayingلَا حَظَّ فِي الْإِسْلَامِ لِمَنْ تَرَكَ الصَّلَاةَ', '', 'لَا حَظَّ فِي الْإِسْلَامِ لِمَنْ تَرَكَ الصَّلَاةَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingلا حظ في الاسلام لمن ترك الصلاه', 'لا حظ في الاسلام لمن ترك الصلاه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 26, NULL, 'There is no portion in Islam for the one who abandons the prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'there is no portion in islam for the one who abandons the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 27, NULL, 'Given this — that one who abandons the prayer holds no share in Islam, and that abandoning the prayer is precisely what separates the servant from unbelief — no person who neglects the prayer should, while still counting himself among the faithful, suppose that he stands among the Muslims, or that he holds of Islam so much as the parings of a fingernail. God, glorified be He, has declared this in the verses of His clear Book:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'given this that one who abandons the prayer holds no share in islam and that abandoning the prayer is precisely what separates the servant from unbelief no person who neglects the prayer should while still counting himself among the faithful suppose that he stands among the muslims or that he holds of islam so much as the parings of a fingernail god glorified be he has declared this in the verses of his clear book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 28, NULL, 'Sayingومن يبتع غير الإسلام ديناً فلن يقبل منه وهو في الآخرة من الخاسرين', '', 'ومن يبتع غير الإسلام ديناً فلن يقبل منه وهو في الآخرة من الخاسرين', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingومن يبتع غير الاسلام دينا فلن يقبل منه وهو في الاخره من الخاسرين', 'ومن يبتع غير الاسلام دينا فلن يقبل منه وهو في الاخره من الخاسرين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 29, NULL, 'And whoever seeks a religion other than Islam, it will never be accepted from him, and in the Hereafter he will be among the losers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'and whoever seeks a religion other than islam it will never be accepted from him and in the hereafter he will be among the losers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 30, NULL, 'Among the people of this description we have seen, those who abandon the prayer fall into two kinds:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'among the people of this description we have seen those who abandon the prayer fall into two kinds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 31, NULL, 'The first are people of tribal temper who have turned away from the concerns of religion altogether, people absorbed in themselves and removed from all of that — the animal nature dominant over them, as though they had sprung from the well. The second are people of arrogance and coarse insolence, the women among them most especially.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the first are people of tribal temper who have turned away from the concerns of religion altogether people absorbed in themselves and removed from all of that the animal nature dominant over them as though they had sprung from the well the second are people of arrogance and coarse insolence the women among them most especially', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 32, NULL, 'But there is no insolence and no arrogance against God, glorified be He, nor against His worship. Whoever takes that path has destroyed his own soul and wronged it. As for his Creator, glorified be He, He has no need of that person''s worship. Its benefit returns only to the worshipper himself, and to those like him — the learned among them and the lowly. God did not create them and require their service in His worship except to benefit them by it, as God, glorified and exalted be He, has said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'but there is no insolence and no arrogance against god glorified be he nor against his worship whoever takes that path has destroyed his own soul and wronged it as for his creator glorified be he he has no need of that persons worship its benefit returns only to the worshipper himself and to those like him the learned among them and the lowly god did not create them and require their service in his worship except to benefit them by it as god glorified and exalted be he has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 33, NULL, 'Adh-Dhariyat: 56وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ', '', 'وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ', 'Adh-Dhariyat: 56', 51, 56, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'adh dhariyat 56وما خلقت الجن والانس الا ليعبدون', 'وما خلقت الجن والانس الا ليعبدون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 34, NULL, 'And I did not create the jinn and mankind except that they should worship Me.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'and i did not create the jinn and mankind except that they should worship me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 35, NULL, 'There is no doubt that whoever walks that path has entered into the warning God, exalted be He, issues in the verses of His clear Book, where He says:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'there is no doubt that whoever walks that path has entered into the warning god exalted be he issues in the verses of his clear book where he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 36, NULL, 'Ghafir: 60إِنَّ ٱلَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِى سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ', '', 'إِنَّ ٱلَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِى سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ', 'Ghafir: 60', 40, 60, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'ghafir 60ان الذين يستكبرون عن عبادتي سيدخلون جهنم داخرين', 'ان الذين يستكبرون عن عبادتي سيدخلون جهنم داخرين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 37, NULL, 'Indeed, those who are too proud to worship Me will enter Hell abased.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'indeed those who are too proud to worship me will enter hell abased', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 38, NULL, 'It was on that very path that Iblis met his end — and he is truly dead — for whenever a servant prostrates to his Lord, glorified be He, in his prayer, Iblis cries out: Woe to me, this one obeyed and I refused. As for the unbeliever, even though he does not pray the prayer of Islam or worship his Lord, glorified be He, with the worship that is accepted, he still has within his own religion a form of worship that he performs, handed down to him from his forebears. Not even the unbelievers of the lands of India are so arrogant toward the worship of God, glorified be He, nor do they turn away from Him with such turning away — men and women, the whole and the parts — except for those among them who fall under the two kinds already described and who follow them in their misguidance and deviation. Those two kinds are found in all the schools of Islam as well, and likewise in the creeds of every religion. But such conduct does not befit one who has attached himself to the walaya of the friends of God, glorified be He, by its firm mountain, and who traces himself, in his affairs, back to the people of piety and faith. No one has any claim of walaya to them except by holding fast to the hem of the prayer. Otherwise he is like one who proclaims upon himself, in the Hereafter, destruction and woe — like those who oppose the guiding call. Even if there are among them, men and women alike, some who are formed that way, leave them and what they are formed in, for they are not granted success in their affairs, while you, in your affairs, by the praise of God, glorified be He, are granted success. As for the one who acknowledges the call of the friend of God (ع), and the Garden and the Fire, the punishment and the reckoning, the balance and the path, the gathering and the raising — his reason requires him to hold fast to the worship of his Lord, glorified be He, through the prayer, which is the pillar of the religion and the support of Islam, and to comply through it with the command. He who warns has given excuse, and he who has cautioned against the punishment of his Lord has cleared himself. So let those who would set things right set their souls right by this, and whoever fears God and guards himself against Him — those are the ones who prosper.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'it was on that very path that iblis met his end and he is truly dead for whenever a servant prostrates to his lord glorified be he in his prayer iblis cries out woe to me this one obeyed and i refused as for the unbeliever even though he does not pray the prayer of islam or worship his lord glorified be he with the worship that is accepted he still has within his own religion a form of worship that he performs handed down to him from his forebears not even the unbelievers of the lands of india are so arrogant toward the worship of god glorified be he nor do they turn away from him with such turning away men and women the whole and the parts except for those among them who fall under the two kinds already described and who follow them in their misguidance and deviation those two kinds are found in all the schools of islam as well and likewise in the creeds of every religion but such conduct does not befit one who has attached himself to the walaya of the friends of god glorified be he by its firm mountain and who traces himself in his affairs back to the people of piety and faith no one has any claim of walaya to them except by holding fast to the hem of the prayer otherwise he is like one who proclaims upon himself in the hereafter destruction and woe like those who oppose the guiding call even if there are among them men and women alike some who are formed that way leave them and what they are formed in for they are not granted success in their affairs while you in your affairs by the praise of god glorified be he are granted success as for the one who acknowledges the call of the friend of god ع and the garden and the fire the punishment and the reckoning the balance and the path the gathering and the raising his reason requires him to hold fast to the worship of his lord glorified be he through the prayer which is the pillar of the religion and the support of islam and to comply through it with the command he who warns has given excuse and he who has cautioned against the punishment of his lord has cleared himself so let those who would set things right set their souls right by this and whoever fears god and guards himself against him those are the ones who prosper', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 39, NULL, 'He said in the book Tawil al-Shariah: The obligations of the prayer are seven:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'he said in the book tawil al shariah the obligations of the prayer are seven', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 40, NULL, 'The first takbir The recitation The bowing The prostration The tasbih The greeting The taslim', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the first takbir the recitation the bowing the prostration the tasbih the greeting the taslim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 41, NULL, 'And he said in it: When you have made the takbir, it is not permissible for you to move your foot, to advance it or draw it back; rather you remain fixed. Nor may you speak from the opening takbir until the taslim, nor move from your place.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'and he said in it when you have made the takbir it is not permissible for you to move your foot to advance it or draw it back rather you remain fixed nor may you speak from the opening takbir until the taslim nor move from your place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 42, NULL, 'And he said in it: The Prophet (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'and he said in it the prophet ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 43, NULL, 'Sayingأُمِرْتُ أَنْ أَسْجُدَ عَلَى سَبْعَةِ أَدَوَاتٍ', '', 'أُمِرْتُ أَنْ أَسْجُدَ عَلَى سَبْعَةِ أَدَوَاتٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingامرت ان اسجد علي سبعه ادوات', 'امرت ان اسجد علي سبعه ادوات');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 44, NULL, 'I have been commanded to prostrate upon seven members.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'i have been commanded to prostrate upon seven members', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 45, NULL, 'And he said in it: The Prophet (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'and he said in it the prophet ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 46, NULL, 'Sayingلا تقرأ وأنت راكع ولا تحركوا الحصى في الصلاة ولا تلتفتوا التّغات الثعلب ولا تقعوا اقعاء القرد ولا تنقروا نقر الغراب', '', 'لا تقرأ وأنت راكع ولا تحركوا الحصى في الصلاة ولا تلتفتوا التّغات الثعلب ولا تقعوا اقعاء القرد ولا تنقروا نقر الغراب', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingلا تقرا وانت راكع ولا تحركوا الحصي في الصلاه ولا تلتفتوا التغات الثعلب ولا تقعوا اقعاء القرد ولا تنقروا نقر الغراب', 'لا تقرا وانت راكع ولا تحركوا الحصي في الصلاه ولا تلتفتوا التغات الثعلب ولا تقعوا اقعاء القرد ولا تنقروا نقر الغراب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 47, NULL, 'Do not recite while you are bowing; do not disturb the pebbles during the prayer; do not turn about as the fox turns; do not squat as the monkey squats; and do not peck as the crow pecks.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'do not recite while you are bowing do not disturb the pebbles during the prayer do not turn about as the fox turns do not squat as the monkey squats and do not peck as the crow pecks', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 48, NULL, 'He said in it: He separates the two rakahs with a sitting. He said in it: Do not pray the obligatory prayer when the adhan is called — pray it when the iqama is given. He said in it: The Zuhr prayer is four rakahs. He said in it: It is related from the Prophet (ع) that he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'he said in it he separates the two rakahs with a sitting he said in it do not pray the obligatory prayer when the adhan is called pray it when the iqama is given he said in it the zuhr prayer is four rakahs he said in it it is related from the prophet ع that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 49, NULL, 'Sayingلَا تُطْرِقُوا فِي الرُّكُوعِ إِطْرَاقَ الْحِمَارِ وَالْكُبَابَهِ', '', 'لَا تُطْرِقُوا فِي الرُّكُوعِ إِطْرَاقَ الْحِمَارِ وَالْكُبَابَهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingلا تطرقوا في الركوع اطراق الحمار والكبابه', 'لا تطرقوا في الركوع اطراق الحمار والكبابه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 50, NULL, 'Do not droop the head in the bowing with the drooping of the donkey and of the lowered beast.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'do not droop the head in the bowing with the drooping of the donkey and of the lowered beast', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 51, NULL, 'He commanded, further, that the head not be dropped below the level of the back. He said in it: The head and the back are level and aligned in the prayer. He said in it: The Prophet (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'he commanded further that the head not be dropped below the level of the back he said in it the head and the back are level and aligned in the prayer he said in it the prophet ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 52, NULL, 'Sayingمَنْ كَثُرَتْ صَلَاتُهُ بِاللَّيْلِ حَسُنَ وَجْهُهُ بِالنَّهَارِ', '', 'مَنْ كَثُرَتْ صَلَاتُهُ بِاللَّيْلِ حَسُنَ وَجْهُهُ بِالنَّهَارِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingمن كثرت صلاته بالليل حسن وجهه بالنهار', 'من كثرت صلاته بالليل حسن وجهه بالنهار');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 53, NULL, 'Whoever prays much by night, his face is made beautiful by day.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'whoever prays much by night his face is made beautiful by day', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 54, NULL, 'The author of the guarded epistle, which contains the protected secrets of the religion of God — the most eminent and noble Dai Zayd ibn Muhammad ibn al-Fadl, may God exalt his sanctity and grant us his intercession and his company — said: The obligations of the prayer are seven, and they are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the author of the guarded epistle which contains the protected secrets of the religion of god the most eminent and noble dai zayd ibn muhammad ibn al fadl may god exalt his sanctity and grant us his intercession and his company said the obligations of the prayer are seven and they are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 55, NULL, 'The intention The first takbir The standing The recitation The bowing The prostration The taslim', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the intention the first takbir the standing the recitation the bowing the prostration the taslim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 56, NULL, 'He said in it: Five prayers have been appointed for every day. He said in it: The prayer has four limits, and they are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'he said in it five prayers have been appointed for every day he said in it the prayer has four limits and they are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 57, NULL, 'The place The time The purity The intention', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the place the time the purity the intention', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 58, NULL, 'He said in it: The five prayers are seventeen rakahs. He said in it: The prayer is of two kinds — obligation and sunnah. He said in it: For that reason Muhammad (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'he said in it the five prayers are seventeen rakahs he said in it the prayer is of two kinds obligation and sunnah he said in it for that reason muhammad ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 59, NULL, 'Sayingتَارِكُ سُنَّتِي مَلْعُونٌ', '', 'تَارِكُ سُنَّتِي مَلْعُونٌ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingتارك سنتي ملعون', 'تارك سنتي ملعون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 60, NULL, 'The one who abandons my sunnah is cursed.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the one who abandons my sunnah is cursed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 61, NULL, 'Meaning: the one who abandons my legatee is one banished from the mercy of God. He said in it: The Messenger of God (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'meaning the one who abandons my legatee is one banished from the mercy of god he said in it the messenger of god ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 62, NULL, 'Sayingلَا صَلَاةَ لِمَنْ لَا يُؤَدِّي الزَّكَاةَ', '', 'لَا صَلَاةَ لِمَنْ لَا يُؤَدِّي الزَّكَاةَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingلا صلاه لمن لا يودي الزكاه', 'لا صلاه لمن لا يودي الزكاه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 63, NULL, 'There is no prayer for the one who does not pay the zakat.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'there is no prayer for the one who does not pay the zakat', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 64, NULL, 'He said in it: The movements of the prayer — the bowing and the prostration — are submission and humility. Then he said: For that reason the Messenger of God (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'he said in it the movements of the prayer the bowing and the prostration are submission and humility then he said for that reason the messenger of god ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 65, NULL, 'Sayingمَنْ لَمْ تَنْهَ صَلَاتُهُ عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ لَمْ يَزْدَدْ مِنَ اللَّهِ اِلَّا بُعْدًا', '', 'مَنْ لَمْ تَنْهَ صَلَاتُهُ عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ لَمْ يَزْدَدْ مِنَ اللَّهِ اِلَّا بُعْدًا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingمن لم تنه صلاته عن الفحشاء والمنكر لم يزدد من الله الا بعدا', 'من لم تنه صلاته عن الفحشاء والمنكر لم يزدد من الله الا بعدا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 66, NULL, 'Whoever is not restrained by his prayer from indecency and wrongdoing increases in nothing but distance from God.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'whoever is not restrained by his prayer from indecency and wrongdoing increases in nothing but distance from god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 67, NULL, 'And for that reason, the people of Shuayb said to him:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'and for that reason the people of shuayb said to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 68, NULL, 'Sayingيا شعيب أصلواتك تأمرك أن نترك ما يعبد آبائنا', '', 'يا شعيب أصلواتك تأمرك أن نترك ما يعبد آبائنا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingيا شعيب اصلواتك تامرك ان نترك ما يعبد اباينا', 'يا شعيب اصلواتك تامرك ان نترك ما يعبد اباينا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 69, NULL, 'O Shuayb, does your prayer command you that we abandon what our fathers worshipped?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'o shuayb does your prayer command you that we abandon what our fathers worshipped', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 70, NULL, 'Then he said: it is because the outward prayer neither forbids nor commands.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'then he said it is because the outward prayer neither forbids nor commands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 71, NULL, 'Our master, the author of the Majalis al-Mustansiriyya — may the peace of God be upon its author — said in the sixth of these councils: You have heard what we recited to you of the divisions of the obligations of purity and its sunnahs, corresponding in number to the clauses of the shahada and its letters, since purity is one of the rights of the shahada. Among its rights also is the prayer. So listen now to what we recite to you of its meaning. The prayers are seven obligatory prayers and twelve sunnah prayers. The obligatory prayers are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'our master the author of the majalis al mustansiriyya may the peace of god be upon its author said in the sixth of these councils you have heard what we recited to you of the divisions of the obligations of purity and its sunnahs corresponding in number to the clauses of the shahada and its letters since purity is one of the rights of the shahada among its rights also is the prayer so listen now to what we recite to you of its meaning the prayers are seven obligatory prayers and twelve sunnah prayers the obligatory prayers are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 72, NULL, 'The prayer of residence, which is seventeen rakahs in every day and night The prayer of travel, which is eleven rakahs in the day and night The Friday prayer, which is not complete until four gather with the imam The prayer of fear, part of which is prayed with the imam and the remainder of which is completed alone The prayer of the circumambulation of the obligatory Hajj The prayer of the circumambulation of the obligatory Umrah The prayer over the bier, which is an obligation upon every Muslim who knows of it — until one of them undertakes it, whereupon the rest become volunteers in it', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the prayer of residence which is seventeen rakahs in every day and night the prayer of travel which is eleven rakahs in the day and night the friday prayer which is not complete until four gather with the imam the prayer of fear part of which is prayed with the imam and the remainder of which is completed alone the prayer of the circumambulation of the obligatory hajj the prayer of the circumambulation of the obligatory umrah the prayer over the bier which is an obligation upon every muslim who knows of it until one of them undertakes it whereupon the rest become volunteers in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 73, NULL, 'The sunnah prayers are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the sunnah prayers are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 74, NULL, 'The prayer of the Feast of the Breaking of the Fast The prayer of the Feast of the Sacrifice The prayer of the eclipse of the sun The prayer of the eclipse of the moon The prayer for rain The prayer of the earthquake The prayer for events that occur as signs The prayer of the shaf and the witr The prayer of the watira, which is two rakahs performed sitting The prayer of the two rakahs of the dawn — for the Prophet (ع) made them up after the rising of the sun and made up the obligatory prayer after them Twenty-eight rakahs in every day and night, among them:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the prayer of the feast of the breaking of the fast the prayer of the feast of the sacrifice the prayer of the eclipse of the sun the prayer of the eclipse of the moon the prayer for rain the prayer of the earthquake the prayer for events that occur as signs the prayer of the shaf and the witr the prayer of the watira which is two rakahs performed sitting the prayer of the two rakahs of the dawn for the prophet ع made them up after the rising of the sun and made up the obligatory prayer after them twenty eight rakahs in every day and night among them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 75, NULL, '- The prayer of the oft-returning, which is six rakahs after the sun''s decline - Eight rakahs between Zuhr and Asr - Ten rakahs between Maghrib and the later Isha - Four rakahs after the later Isha, which is the prayer of the night', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the prayer of the oft returning which is six rakahs after the suns decline eight rakahs between zuhr and asr ten rakahs between maghrib and the later isha four rakahs after the later isha which is the prayer of the night', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 76, NULL, 'The prayer of greeting the mosque upon entering it', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the prayer of greeting the mosque upon entering it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 77, NULL, 'Then he said, may the good pleasure of God be upon him, in the seventh of these councils: So listen now to what we recite to you — that in each of the five prayers there are seven obligations and twelve sunnahs. The seven obligations are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'then he said may the good pleasure of god be upon him in the seventh of these councils so listen now to what we recite to you that in each of the five prayers there are seven obligations and twelve sunnahs the seven obligations are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 78, NULL, 'The intention Turning toward the qibla Then the takbirat al-ihram The recitation of the Opening of the Book The bowing The prostration The sitting for the salutation', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the intention turning toward the qibla then the takbirat al ihram the recitation of the opening of the book the bowing the prostration the sitting for the salutation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 79, NULL, 'The twelve sunnahs are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the twelve sunnahs are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 80, NULL, 'The adhan The iqama Saying, I have turned my face to Him who created the heavens and the earth, as one of pure faith, to the end of the words Seeking refuge from the accursed Satan Reciting a surah after the Opening of the Book in the first two rakahs of every obligatory prayer Raising the hands at every rising from the bowing and every descent into it The tasbih during the bowing The imam''s saying, God has heard the one who praised Him, and the follower''s saying, Our Lord, to You belongs all praise The tasbih during the prostration The first sitting and the first tashahhud The second tashahhud Every prayer in which there is no first sitting has a qunut that stands in its place in the count, and every prayer in which there are two sittings for the tashahhud has no qunut in it', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the adhan the iqama saying i have turned my face to him who created the heavens and the earth as one of pure faith to the end of the words seeking refuge from the accursed satan reciting a surah after the opening of the book in the first two rakahs of every obligatory prayer raising the hands at every rising from the bowing and every descent into it the tasbih during the bowing the imams saying god has heard the one who praised him and the followers saying our lord to you belongs all praise the tasbih during the prostration the first sitting and the first tashahhud the second tashahhud every prayer in which there is no first sitting has a qunut that stands in its place in the count and every prayer in which there are two sittings for the tashahhud has no qunut in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 81, NULL, 'Our lord Amir al-Muminin Ali ibn Abi Talib (ع) said in his Four Hundred Etiquettes:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'our lord amir al muminin ali ibn abi talib ع said in his four hundred etiquettes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 82, NULL, 'Sayingلَا يَجْمَعُ الْمُؤْمِنُ يَدَيْهِ فِي الصَّلَاةِ وَهُوَ قَائِمٌ يُشْبِهُ بِأَهْلِ الْكِتَابِ', '', 'لَا يَجْمَعُ الْمُؤْمِنُ يَدَيْهِ فِي الصَّلَاةِ وَهُوَ قَائِمٌ يُشْبِهُ بِأَهْلِ الْكِتَابِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingلا يجمع المومن يديه في الصلاه وهو قايم يشبه باهل الكتاب', 'لا يجمع المومن يديه في الصلاه وهو قايم يشبه باهل الكتاب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 83, NULL, 'The believer does not clasp his hands together in الصلاة while standing, resembling thereby the People of the Book.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the believer does not clasp his hands together in الصلاه while standing resembling thereby the people of the book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 84, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 85, NULL, 'Sayingإِذَا أَصَابَ أَحَدُكُمْ فِي الصَّلَاةِ الدَّابَّةَ فَلْيَدْفِنْهَا أَوْ لِيَسْتُرْ عَلَيْهَا أَوْ لِيَضَعْهَا فِي ثَوْبِهِ حَتَّى يَنْصَرِفَ', '', 'إِذَا أَصَابَ أَحَدُكُمْ فِي الصَّلَاةِ الدَّابَّةَ فَلْيَدْفِنْهَا أَوْ لِيَسْتُرْ عَلَيْهَا أَوْ لِيَضَعْهَا فِي ثَوْبِهِ حَتَّى يَنْصَرِفَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingاذا اصاب احدكم في الصلاه الدابه فليدفنها او ليستر عليها او ليضعها في ثوبه حتي ينصرف', 'اذا اصاب احدكم في الصلاه الدابه فليدفنها او ليستر عليها او ليضعها في ثوبه حتي ينصرف');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 86, NULL, 'If أحدكم of you comes upon أصاب a crawling creature during the prayer, let him bury it, أو cover it over, or place it in his garment until he has finished.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'if احدكم of you comes upon اصاب a crawling creature during the prayer let him bury it او cover it over or place it in his garment until he has finished', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 87, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 88, NULL, 'Sayingالْاِلْتِفَاتُ الْفَاحِشُ يَقْطَعُ الصَّلَاةَ فَمَنْ فَعَلَهُ فَعَلَيْهِ الْاِبْتِدَاءُ . اَلصَّلَاةُ بِالْأَذَانِ وَالْإِقَامَةِ وَالتَّكْبِيرِ', '', 'الْاِلْتِفَاتُ الْفَاحِشُ يَقْطَعُ الصَّلَاةَ فَمَنْ فَعَلَهُ فَعَلَيْهِ الْاِبْتِدَاءُ . اَلصَّلَاةُ بِالْأَذَانِ وَالْإِقَامَةِ وَالتَّكْبِيرِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingالالتفات الفاحش يقطع الصلاه فمن فعله فعليه الابتداء الصلاه بالاذان والاقامه والتكبير', 'الالتفات الفاحش يقطع الصلاه فمن فعله فعليه الابتداء الصلاه بالاذان والاقامه والتكبير');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 89, NULL, 'Gross turning about cuts off the prayer, and whoever does it must begin again: the prayer with the adhan, the iqama, and the takbir.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'gross turning about cuts off the prayer and whoever does it must begin again the prayer with the adhan the iqama and the takbir', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 90, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 91, NULL, 'Sayingأَعْطُوا كُلَّ سُورَةٍ حَقَّهَا مِنَ الرُّكُوعِ وَالسُّجُودِ إِذَا كُنْتُمْ فِي الصَّلَاةِ', '', 'أَعْطُوا كُلَّ سُورَةٍ حَقَّهَا مِنَ الرُّكُوعِ وَالسُّجُودِ إِذَا كُنْتُمْ فِي الصَّلَاةِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingاعطوا كل سوره حقها من الركوع والسجود اذا كنتم في الصلاه', 'اعطوا كل سوره حقها من الركوع والسجود اذا كنتم في الصلاه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 92, NULL, 'Give every surah its due of bowing and prostration when you are in the prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'give every surah its due of bowing and prostration when you are in the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 93, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 94, NULL, 'Sayingأَجْلِسُوا بَيْنَ السَّجْدَتَيْنِ حَتَّى تَسْكُنَ جَوَارِحُكُمْ وَقُومُوا فَاِنَّ ذَلِكَ مِنْ فِعْلِنَا', '', 'أَجْلِسُوا بَيْنَ السَّجْدَتَيْنِ حَتَّى تَسْكُنَ جَوَارِحُكُمْ وَقُومُوا فَاِنَّ ذَلِكَ مِنْ فِعْلِنَا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingاجلسوا بين السجدتين حتي تسكن جوارحكم وقوموا فان ذلك من فعلنا', 'اجلسوا بين السجدتين حتي تسكن جوارحكم وقوموا فان ذلك من فعلنا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 95, NULL, 'Sit between the two prostrations until your limbs are still, then rise — for that is our practice.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sit between the two prostrations until your limbs are still then rise for that is our practice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 96, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 97, NULL, 'Sayingلِيَرْفَعِ السَّاجِدُ مُؤَخَّرَهُ فِي الصَّلَاةِ إِذَا سَجَدَ', '', 'لِيَرْفَعِ السَّاجِدُ مُؤَخَّرَهُ فِي الصَّلَاةِ إِذَا سَجَدَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingليرفع الساجد موخره في الصلاه اذا سجد', 'ليرفع الساجد موخره في الصلاه اذا سجد');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 98, NULL, 'Let the one who prostrates raise his haunches when he prostrates.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'let the one who prostrates raise his haunches when he prostrates', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 99, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 100, NULL, 'Sayingإِذَا صَلَّيْتَ وَحْدَكَ فَاَسْمِعْ نَفْسَكَ الْقِرَاءَةَ وَالتَّسْبِيحَ وَالتَّكْبِيرَ وَإِذَا انْقَّلْتَ عَنِ الصَّلَاةِ فَعَنْ يَمِينِكَ', '', 'إِذَا صَلَّيْتَ وَحْدَكَ فَاَسْمِعْ نَفْسَكَ الْقِرَاءَةَ وَالتَّسْبِيحَ وَالتَّكْبِيرَ وَإِذَا انْقَّلْتَ عَنِ الصَّلَاةِ فَعَنْ يَمِينِكَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'sayingاذا صليت وحدك فاسمع نفسك القراءه والتسبيح والتكبير واذا انقلت عن الصلاه فعن يمينك', 'اذا صليت وحدك فاسمع نفسك القراءه والتسبيح والتكبير واذا انقلت عن الصلاه فعن يمينك');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 101, NULL, 'When you pray alone, make yourself hear your recitation, your tasbih, and your takbir. When you turn away from the prayer, turn to your right.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'when you pray alone make yourself hear your recitation your tasbih and your takbir when you turn away from the prayer turn to your right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 102, NULL, 'A question was raised by the head of the island of India, Muhammad Ali ibn Salih al-Badri, may God preserve him, and answered by the lord and master, our master Hibat Allah, may God prolong his life. The following is its text and substance.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'a question was raised by the head of the island of india muhammad ali ibn salih al badri may god preserve him and answered by the lord and master our master hibat allah may god prolong his life the following is its text and substance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 103, NULL, 'The second question: What does our master — may God perpetuate his support — say concerning a person who recites Surat al-Falaq and Surat al-Nas inadvertently in the obligatory prayer? Does he complete the prayer, or does he repeat it? And if it is permissible, what is the ruling for one who recited Surat al-Nas in the first rakah? Does he repeat it in the second, or does he recite the surah before it from its opening, or does he repeat the prayer? And if it is not permissible, what of one who recited Surat al-Ikhlas in the first rakah? Does he repeat it in the second, or does he recite the surah above it from its opening? May our master — may God perpetuate his exaltation — favor us with a satisfying answer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'the second question what does our master may god perpetuate his support say concerning a person who recites surat al falaq and surat al nas inadvertently in the obligatory prayer does he complete the prayer or does he repeat it and if it is permissible what is the ruling for one who recited surat al nas in the first rakah does he repeat it in the second or does he recite the surah before it from its opening or does he repeat the prayer and if it is not permissible what of one who recited surat al ikhlas in the first rakah does he repeat it in the second or does he recite the surah above it from its opening may our master may god perpetuate his exaltation favor us with a satisfying answer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the shape of the prayer itself', '18. The Shape of the Prayer Itself', 104, NULL, 'Answer: We seek help from God for success and right direction, and from His friend and his full moon we ask for rain from the clouds of confirmation. No text has come from the friends of God forbidding the recitation of the two surahs of refuge in the obligatory prayer. So if the one praying recites them, his prayer is complete. If he recited Surat al-Nas in the first rakah, he repeats it in the last. Whoever recited Surat al-Ikhlas in the first recites al-Falaq in the second. One should not, however, deliberately recite in this manner in the obligatory prayer, placing it in the position of the sunnah.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 18 the shape of the prayer itself', 'answer we seek help from god for success and right direction and from his friend and his full moon we ask for rain from the clouds of confirmation no text has come from the friends of god forbidding the recitation of the two surahs of refuge in the obligatory prayer so if the one praying recites them his prayer is complete if he recited surat al nas in the first rakah he repeats it in the last whoever recited surat al ikhlas in the first recites al falaq in the second one should not however deliberately recite in this manner in the obligatory prayer placing it in the position of the sunnah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 0, NULL, 'I turn now to supplication after the prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'i turn now to supplication after the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 1, NULL, 'In the question-and-answer book arranged according to the chapters of the Pillars of Islam, the question was put: what is to be said about the teaching found in the books of the guiding call — that supplication is not recited after the afternoon prayer? Does this mean only the supplication of drawing near, or all supplications? The answer given was: both the supplication of drawing near and all others — and if anyone does supplicate, no sin rests upon him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'in the question and answer book arranged according to the chapters of the pillars of islam the question was put what is to be said about the teaching found in the books of the guiding call that supplication is not recited after the afternoon prayer does this mean only the supplication of drawing near or all supplications the answer given was both the supplication of drawing near and all others and if anyone does supplicate no sin rests upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 2, NULL, 'A further question was asked: does the worshipper supplicate after the obligatory afternoon prayer, and does he wipe his face at the place of prostration at the close of every prayer? The answer: it is not permitted except after the afternoon prayer and after dawn. Our masters, may God sanctify their souls, commanded wiping specifically after the afternoon prayer and after dawn, and this is among what they received from the pure Imams (عَلَيْهِمُ السَّلَامُ). It has been noted that one does not prolong supplication after the afternoon prayer, yet if he does prolong it, nothing rests upon him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'a further question was asked does the worshipper supplicate after the obligatory afternoon prayer and does he wipe his face at the place of prostration at the close of every prayer the answer it is not permitted except after the afternoon prayer and after dawn our masters may god sanctify their souls commanded wiping specifically after the afternoon prayer and after dawn and this is among what they received from the pure imams عليهم السلام it has been noted that one does not prolong supplication after the afternoon prayer yet if he does prolong it nothing rests upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 3, NULL, 'The book on the interpretation of the Sharia states that when the prayer falls in the daytime the recitation is kept low; when it falls at night, in the dominion of darkness, the voice is raised; and the dawn prayer, offered in the last darkness of night, is announced aloud.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'the book on the interpretation of the sharia states that when the prayer falls in the daytime the recitation is kept low when it falls at night in the dominion of darkness the voice is raised and the dawn prayer offered in the last darkness of night is announced aloud', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 4, NULL, 'Our lord and master, the author of the Mustansiriyya Councils, peace of God be upon him, said in the Eleventh Council: having brought the discussion of the jurisprudence of prayer to the limit set out above — where the outward receives its exposition and its expoundings, and the inward its sign and its intimation — we follow it with what is now read to you: the mention of the supplication that comes at the close of the prayer, and what it contains of the seven and the twelve, in the manner our explanation has proceeded throughout, for the benefit of those of understanding who take it to heart.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'our lord and master the author of the mustansiriyya councils peace of god be upon him said in the eleventh council having brought the discussion of the jurisprudence of prayer to the limit set out above where the outward receives its exposition and its expoundings and the inward its sign and its intimation we follow it with what is now read to you the mention of the supplication that comes at the close of the prayer and what it contains of the seven and the twelve in the manner our explanation has proceeded throughout for the benefit of those of understanding who take it to heart', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 5, NULL, 'Of the seven, these are they:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'of the seven these are they', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 6, NULL, 'the supplication of asking (دُعَاءُ الْمَسْأَلَةِ), in which the supplicant spreads out his hands and sets the inner surface of his palms facing his face; the supplication of seeking refuge (دُعَاءُ الْاِسْتِعَاذَةِ) from what he fears, in which he turns his palms about and sets their backs facing his face; the supplication of humble submission (دُعَاءُ الْاِسْتِكَانَةِ), in which he grasps his shoulders with his hands — this is done only in solitude; the supplication of devotion (دُعَاءُ التَّبَتُّلِ), in which he points with the index finger; the supplication of entreaty (دُعَاءُ التَّضَرُّعِ), which is made by moving the finger; the supplication of fervent appeal (دُعَاءُ الْاِبْتِهَالِ), in which he spreads his palms and extends both hands together, raised toward the sky; the supplication of abasement in the dust (دُعَاءُ التَّعْفِيرِ), in which he supplicates while turning his cheeks upon the ground.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'the supplication of asking دعاء المساله in which the supplicant spreads out his hands and sets the inner surface of his palms facing his face the supplication of seeking refuge دعاء الاستعاذه from what he fears in which he turns his palms about and sets their backs facing his face the supplication of humble submission دعاء الاستكانه in which he grasps his shoulders with his hands this is done only in solitude the supplication of devotion دعاء التبتل in which he points with the index finger the supplication of entreaty دعاء التضرع which is made by moving the finger the supplication of fervent appeal دعاء الابتهال in which he spreads his palms and extends both hands together raised toward the sky the supplication of abasement in the dust دعاء التعفير in which he supplicates while turning his cheeks upon the ground', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 7, NULL, 'For each of these seven supplications there is a mention in the Quran, which we shall bring forward when we return to the explanation of what we have read, for everything we have set down is of the nature of roots — like the roots of a tree awaiting the branching of its boughs and the bearing of its fruit.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'for each of these seven supplications there is a mention in the quran which we shall bring forward when we return to the explanation of what we have read for everything we have set down is of the nature of roots like the roots of a tree awaiting the branching of its boughs and the bearing of its fruit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 8, NULL, 'As for the twelve, they are the foundations of supplication and the base upon which it is built. Whoever desires that his supplication be answered should do as follows:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'as for the twelve they are the foundations of supplication and the base upon which it is built whoever desires that his supplication be answered should do as follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 9, NULL, 'send ahead of it repentance from what God has forbidden; or a charity that he gives; or a fast; or a prayer — for God, mighty and majestic, says:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'send ahead of it repentance from what god has forbidden or a charity that he gives or a fast or a prayer for god mighty and majestic says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 10, NULL, 'Fatir: 10إِلَيْهِ يَصْعَدُ ٱلْكَلِمُ ٱلطَّيِّبُ وَٱلْعَمَلُ ٱلصَّلِحُ يَرْفَعُهُۚۥ', '', 'إِلَيْهِ يَصْعَدُ ٱلْكَلِمُ ٱلطَّيِّبُ وَٱلْعَمَلُ ٱلصَّلِحُ يَرْفَعُهُۚۥ', 'Fatir: 10', 35, 10, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'fatir 10اليه يصعد الكلم الطيب والعمل الصلح يرفعه', 'اليه يصعد الكلم الطيب والعمل الصلح يرفعه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 11, NULL, 'To Him ascends the good word, and the righteous deed raises it;', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'to him ascends the good word and the righteous deed raises it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 12, NULL, 'then purify his intention in the supplication and turn toward God with his whole heart; begin with the praise of God, exalted is He, and with extolling Him as He deserves; call down blessings upon the Prophet at the beginning of the supplication, in its middle, and at its end; draw near to God, exalted is He, through the imams of the religion, naming them one by one until he reaches the imam of his own age; seek access through him and through them to God in the answering of his supplication; then ask for the good of this world and the hereafter; seek refuge from the evil of this world and the hereafter; then supplicate after that for whatever he loves and wills.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'then purify his intention in the supplication and turn toward god with his whole heart begin with the praise of god exalted is he and with extolling him as he deserves call down blessings upon the prophet at the beginning of the supplication in its middle and at its end draw near to god exalted is he through the imams of the religion naming them one by one until he reaches the imam of his own age seek access through him and through them to god in the answering of his supplication then ask for the good of this world and the hereafter seek refuge from the evil of this world and the hereafter then supplicate after that for whatever he loves and wills', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 13, NULL, 'Our master, the Commander of the Faithful, Ali ibn Abi Talib (ع), said in his Four Hundred Etiquettes:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'our master the commander of the faithful ali ibn abi talib ع said in his four hundred etiquettes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 14, NULL, 'Sayingوَاذْكُرُوا اللَّهَ عَزَّ وَجَلَّ يَقْبَلْ دُعَاءَكُمْ عِنْدَ ذِكْرِهِ وَحِفْظِكُمْ وَرِعَايَتِكُمْ إِيَّاهُ', '', 'وَاذْكُرُوا اللَّهَ عَزَّ وَجَلَّ يَقْبَلْ دُعَاءَكُمْ عِنْدَ ذِكْرِهِ وَحِفْظِكُمْ وَرِعَايَتِكُمْ إِيَّاهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'sayingواذكروا الله عز وجل يقبل دعاءكم عند ذكره وحفظكم ورعايتكم اياه', 'واذكروا الله عز وجل يقبل دعاءكم عند ذكره وحفظكم ورعايتكم اياه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 15, NULL, 'Remember God, mighty and majestic — He will accept your supplication when you remember Him, guard His right, and keep watch over it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'remember god mighty and majestic he will accept your supplication when you remember him guard his right and keep watch over it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 16, NULL, 'And he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 17, NULL, 'Sayingتَقَدَّمُوا فِي الدُّعَاءِ قَبْلَ نُزُولِ الْبَلَاءِ فَإِنَّ أَبْوَابَ السَّمَاءِ تُفَتَّحُ فِي سِتَّةِ مَوَاقِيتَ: ١- عِنْدَ نُزُولِ الْغَيْثِ ٢- وَعِنْدِ الزَّحْفِ ٣- وَعِنْدَ الْأَذَانِ ٤- وَعِنْدَ قِرَاءَةِ الْقُرْآنِ ٥- وَعِنْدَ زَوَالِ الشَّمْسِ ٦- وَعِنْدَ طُلُوعِ الْفَجْرِ', '', 'تَقَدَّمُوا فِي الدُّعَاءِ قَبْلَ نُزُولِ الْبَلَاءِ فَإِنَّ أَبْوَابَ السَّمَاءِ تُفَتَّحُ فِي سِتَّةِ مَوَاقِيتَ: ١- عِنْدَ نُزُولِ الْغَيْثِ ٢- وَعِنْدِ الزَّحْفِ ٣- وَعِنْدَ الْأَذَانِ ٤- وَعِنْدَ قِرَاءَةِ الْقُرْآنِ ٥- وَعِنْدَ زَوَالِ الشَّمْسِ ٦- وَعِنْدَ طُلُوعِ الْفَجْرِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'sayingتقدموا في الدعاء قبل نزول البلاء فان ابواب السماء تفتح في سته مواقيت ١ عند نزول الغيث ٢ وعند الزحف ٣ وعند الاذان ٤ وعند قراءه القران ٥ وعند زوال الشمس ٦ وعند طلوع الفجر', 'تقدموا في الدعاء قبل نزول البلاء فان ابواب السماء تفتح في سته مواقيت ١ عند نزول الغيث ٢ وعند الزحف ٣ وعند الاذان ٤ وعند قراءه القران ٥ وعند زوال الشمس ٦ وعند طلوع الفجر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 18, NULL, 'Come forward with supplication before affliction descends, for the gates of heaven are opened at six appointed times:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'come forward with supplication before affliction descends for the gates of heaven are opened at six appointed times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 19, NULL, '1 – at the falling of rain; 2 – at the advance of the ranks in battle; 3 – at the call to prayer; 4 – at the recitation of the Quran; 5 – at the declining of the sun; 6 – at the breaking of dawn.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', '1 at the falling of rain 2 at the advance of the ranks in battle 3 at the call to prayer 4 at the recitation of the quran 5 at the declining of the sun 6 at the breaking of dawn', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 20, NULL, 'And he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 21, NULL, 'Sayingالدُّعَاءُ يَرُدُّ الْقَضَاءَ الْمُبْرَمَ فَادْعُوهُ وَاسْتَعْجِلُوهُ', '', 'الدُّعَاءُ يَرُدُّ الْقَضَاءَ الْمُبْرَمَ فَادْعُوهُ وَاسْتَعْجِلُوهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'sayingالدعاء يرد القضاء المبرم فادعوه واستعجلوه', 'الدعاء يرد القضاء المبرم فادعوه واستعجلوه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 22, NULL, 'Supplication turns back the decree that has been firmly settled, so call upon Him and press your request with urgency.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'supplication turns back the decree that has been firmly settled so call upon him and press your request with urgency', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 23, NULL, 'And he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 24, NULL, 'Sayingادفعوا داعي البلاء بالدعاء وعليكم به قبل نزول البلاء فوالذي فلق الحبة وبرأ النسمة للبلاء أسرع إلى المؤمن من السيل من أعلى الجبل إلى أسفلها ومن ركض البراذين', '', 'ادفعوا داعي البلاء بالدعاء وعليكم به قبل نزول البلاء فوالذي فلق الحبة وبرأ النسمة للبلاء أسرع إلى المؤمن من السيل من أعلى الجبل إلى أسفلها ومن ركض البراذين', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'sayingادفعوا داعي البلاء بالدعاء وعليكم به قبل نزول البلاء فوالذي فلق الحبه وبرا النسمه للبلاء اسرع الي المومن من السيل من اعلي الجبل الي اسفلها ومن ركض البراذين', 'ادفعوا داعي البلاء بالدعاء وعليكم به قبل نزول البلاء فوالذي فلق الحبه وبرا النسمه للبلاء اسرع الي المومن من السيل من اعلي الجبل الي اسفلها ومن ركض البراذين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 25, NULL, 'Repel the summons of affliction through supplication, and hold fast to it before affliction descends. By Him who split the seed and brought the soul into being — affliction overtakes the believer more swiftly than a torrent down a mountainside, and more swiftly than the galloping of horses.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'repel the summons of affliction through supplication and hold fast to it before affliction descends by him who split the seed and brought the soul into being affliction overtakes the believer more swiftly than a torrent down a mountainside and more swiftly than the galloping of horses', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 26, NULL, 'And he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 27, NULL, 'Sayingاَلدَّاعِيُ بِلَا عَمَلٍ كَالرَّامِي بِلَا وَتَرٍ', '', 'اَلدَّاعِيُ بِلَا عَمَلٍ كَالرَّامِي بِلَا وَتَرٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'sayingالداعي بلا عمل كالرامي بلا وتر', 'الداعي بلا عمل كالرامي بلا وتر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 28, NULL, 'Whoever supplicates without deeds is like an archer with no bowstring.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'whoever supplicates without deeds is like an archer with no bowstring', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 29, NULL, 'And he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 30, NULL, 'Sayingمَنْ قَرَأَ قُلْ هُوَ اللَّهُ أَحَدٌ إِلَى أَنْ تَطْلُعَ الشَّمْسُ عَشْرَ مَرَّاتٍ وَإِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ لَمْ يُصِبْ ذَنْبًا وَلَوْ اجْتَهَدَ إِبْلِيسُ', '', 'مَنْ قَرَأَ قُلْ هُوَ اللَّهُ أَحَدٌ إِلَى أَنْ تَطْلُعَ الشَّمْسُ عَشْرَ مَرَّاتٍ وَإِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ لَمْ يُصِبْ ذَنْبًا وَلَوْ اجْتَهَدَ إِبْلِيسُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'sayingمن قرا قل هو الله احد الي ان تطلع الشمس عشر مرات وانا انزلناه في ليله القدر لم يصب ذنبا ولو اجتهد ابليس', 'من قرا قل هو الله احد الي ان تطلع الشمس عشر مرات وانا انزلناه في ليله القدر لم يصب ذنبا ولو اجتهد ابليس');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 31, NULL, 'Whoever recites until sunrise the chapter beginning "Say: He is God, One" ten times, and the chapter beginning "Indeed We sent it down on the Night of Decree" — no sin will touch him, however hard Iblis may strive against him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'whoever recites until sunrise the chapter beginning say he is god one ten times and the chapter beginning indeed we sent it down on the night of decree no sin will touch him however hard iblis may strive against him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 32, NULL, 'I turn now to the subject of speech and of acts performed within the prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'i turn now to the subject of speech and of acts performed within the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 33, NULL, 'It was asked in that same book of questions and answers: what is to be said of a man praying behind the imam when the imam loses his place, and the man alerts him by clearing his throat or by some similar means rather than by words of glorification — does anything fall upon him for that? The answer: clearing the throat cuts off the prayer when it is done deliberately and without excuse. He should alert the imam with words of glorification, or with a gesture.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'it was asked in that same book of questions and answers what is to be said of a man praying behind the imam when the imam loses his place and the man alerts him by clearing his throat or by some similar means rather than by words of glorification does anything fall upon him for that the answer clearing the throat cuts off the prayer when it is done deliberately and without excuse he should alert the imam with words of glorification or with a gesture', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 34, NULL, 'It was asked: what is to be said of a man who clears his throat often in prayer out of mere habit — does anything fall upon him for that? The answer: if he does so deliberately, he must repeat the prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'it was asked what is to be said of a man who clears his throat often in prayer out of mere habit does anything fall upon him for that the answer if he does so deliberately he must repeat the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 35, NULL, 'It was asked: what is to be said of a woman who prays — whether in congregation or alone — while carrying her child, because there is no other way to quiet his weeping — is that permitted to her or not? The answer: it is not permitted to her to occupy herself in prayer with such a thing.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'it was asked what is to be said of a woman who prays whether in congregation or alone while carrying her child because there is no other way to quiet his weeping is that permitted to her or not the answer it is not permitted to her to occupy herself in prayer with such a thing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 36, NULL, 'It was asked: what is to be said of one who prays with food in his mouth, placed there on account of pain — does a deficiency enter his prayer on that account or not? The answer: if he placed it there out of necessity, nothing falls upon him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'it was asked what is to be said of one who prays with food in his mouth placed there on account of pain does a deficiency enter his prayer on that account or not the answer if he placed it there out of necessity nothing falls upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 37, NULL, 'It was asked: what is to be said of a man who prays with his braid wound inside his turban, drawn from the back of his neck around to the region of the forehead above the hairline, without tucking it into the middle of his head — is that permitted or not? The answer: there is no harm in that. The binding up of hair that is forbidden is when a man turns the hair back upon its root, gathering it to the middle of his head, and the like of that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'it was asked what is to be said of a man who prays with his braid wound inside his turban drawn from the back of his neck around to the region of the forehead above the hairline without tucking it into the middle of his head is that permitted or not the answer there is no harm in that the binding up of hair that is forbidden is when a man turns the hair back upon its root gathering it to the middle of his head and the like of that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 38, NULL, 'As for a man who prays with something in his mouth resembling a gemstone or a dirham, or anything of that kind — if it does not prevent him from forming the letters properly, his prayer is complete. If he holds something in his hand that does not prevent him from fulfilling the limits of his prayer, nothing falls upon him. Yet to be free of all such things is more fitting for him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'as for a man who prays with something in his mouth resembling a gemstone or a dirham or anything of that kind if it does not prevent him from forming the letters properly his prayer is complete if he holds something in his hand that does not prevent him from fulfilling the limits of his prayer nothing falls upon him yet to be free of all such things is more fitting for him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 39, NULL, 'The abridgment of the compiled book states that whoever eats or drinks in prayer — whether forgetfully or deliberately — has cut off his prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'the abridgment of the compiled book states that whoever eats or drinks in prayer whether forgetfully or deliberately has cut off his prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 40, NULL, 'The book of the interpretation of the Sharia states that the recitation comes before the bowing. And it says:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'the book of the interpretation of the sharia states that the recitation comes before the bowing and it says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 41, NULL, 'Sayingوَلَا تَرْفَعْ صَوْتَكَ فَوْقَ صَوْتِهِ', '', 'وَلَا تَرْفَعْ صَوْتَكَ فَوْقَ صَوْتِهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'sayingولا ترفع صوتك فوق صوته', 'ولا ترفع صوتك فوق صوته');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 42, NULL, 'Do not raise your voice above his — meaning the voice of the imam.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'do not raise your voice above his meaning the voice of the imam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 43, NULL, 'It also says that the recitation in the noon prayer and the afternoon prayer is not made aloud but kept low, because these belong to the prayers of the daytime. And it says that in the night prayer the recitation is made aloud. And it says that the Prophet forbade wiping over the leather socks and forbade omitting the audible utterance of the words "In the name of God, the Merciful, the Compassionate."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'it also says that the recitation in the noon prayer and the afternoon prayer is not made aloud but kept low because these belong to the prayers of the daytime and it says that in the night prayer the recitation is made aloud and it says that the prophet forbade wiping over the leather socks and forbade omitting the audible utterance of the words in the name of god the merciful the compassionate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 44, NULL, 'Sayingالْمُصَلِّي إِذَا كَبَّرَ لَا يَتَكَلَّمُ حَتَّى يُسَلِّمَ', '', 'الْمُصَلِّي إِذَا كَبَّرَ لَا يَتَكَلَّمُ حَتَّى يُسَلِّمَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'sayingالمصلي اذا كبر لا يتكلم حتي يسلم', 'المصلي اذا كبر لا يتكلم حتي يسلم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 45, NULL, 'Once the worshipper has pronounced the opening magnification, he does not speak until he gives the salutation.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'once the worshipper has pronounced the opening magnification he does not speak until he gives the salutation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 46, NULL, 'Our master Jafar ibn Mansur al-Yaman, may God exalt his sanctity, said in his book on the inward nursing, concerning the meaning of prayer: the prayer has doors that are numbered, and their full number must be completed, for by them the prayer is made complete. They are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'our master jafar ibn mansur al yaman may god exalt his sanctity said in his book on the inward nursing concerning the meaning of prayer the prayer has doors that are numbered and their full number must be completed for by them the prayer is made complete they are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 47, NULL, 'the ablution; the opening; the call to prayer; the standing call; the turning toward God; the recitation; the bowing; the praise; the glorification; the prostration; the testimony; the salutation; the supplication of the standing invocation; the supplication of the odd-numbered prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'the ablution the opening the call to prayer the standing call the turning toward god the recitation the bowing the praise the glorification the prostration the testimony the salutation the supplication of the standing invocation the supplication of the odd numbered prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'supplication, speech, and silence', '19. Supplication, Speech, and Silence', 48, NULL, 'These are fourteen doors from which the worshipper has no escape. They are the supporting pillars of the prayer, and without them his prayer is not complete.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 19 supplication speech and silence', 'these are fourteen doors from which the worshipper has no escape they are the supporting pillars of the prayer and without them his prayer is not complete', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 0, NULL, 'I turn now to the dress of the worshipper and what he prostrates upon.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'i turn now to the dress of the worshipper and what he prostrates upon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 1, NULL, 'In the book of questions and answers mentioned at the outset — the one whose arranger organized it according to the chapters of the book دَعَائِمُ الْإِسْلَامِ (Pillars of Islam) — I find the following exchanges.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'in the book of questions and answers mentioned at the outset the one whose arranger organized it according to the chapters of the book دعايم الاسلام pillars of islam i find the following exchanges', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 2, NULL, 'Question: What is your ruling on the prayer mat, the rug, and other cloths on which the qibla or another image is depicted, in such a way that it does not occupy the worshipper when he looks at it? Is prayer upon such items permitted, whether the image falls in the place of prostration or elsewhere?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'question what is your ruling on the prayer mat the rug and other cloths on which the qibla or another image is depicted in such a way that it does not occupy the worshipper when he looks at it is prayer upon such items permitted whether the image falls in the place of prostration or elsewhere', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 3, NULL, 'Answer: If it is of a kind that occupies the worshipper when he looks at it, prayer is not permitted. If it does not occupy him, prayer is permitted — except in the case of images, toward which he does not pray.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'answer if it is of a kind that occupies the worshipper when he looks at it prayer is not permitted if it does not occupy him prayer is permitted except in the case of images toward which he does not pray', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 4, NULL, 'Question: What is your ruling on a man who prays in a garment dyed with safflower that is not deeply red? Is his prayer permitted? And what of a woman who prays in pure silk, or in a garment of a very deep red, whether dyed with safflower or not? Is her prayer permitted?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'question what is your ruling on a man who prays in a garment dyed with safflower that is not deeply red is his prayer permitted and what of a woman who prays in pure silk or in a garment of a very deep red whether dyed with safflower or not is her prayer permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 5, NULL, 'Answer: This belongs to the domain of etiquette. If anyone wears such a garment, it does not invalidate the prayer performed in it, whether the wearer is a man or a woman — except for pure silk, which is disliked for men.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'answer this belongs to the domain of etiquette if anyone wears such a garment it does not invalidate the prayer performed in it whether the wearer is a man or a woman except for pure silk which is disliked for men', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 6, NULL, 'Question: What is your ruling on what has come in the books of the Sharia — that if any part of a woman''s عورة (awra) becomes exposed during prayer her prayer is spoiled, whether she knew of it or not? The women of the people of the dawa in India do not customarily wear the long shift and the head-veil, and their legs are uncovered during prayer once or twice. How then does their prayer stand?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'question what is your ruling on what has come in the books of the sharia that if any part of a womans عوره awra becomes exposed during prayer her prayer is spoiled whether she knew of it or not the women of the people of the dawa in india do not customarily wear the long shift and the head veil and their legs are uncovered during prayer once or twice how then does their prayer stand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 7, NULL, 'Answer: Covering is indispensable, for the whole of a woman is عورة. If any part of her awra is exposed, prayer is not permitted to her, whether she knew this ruling or was ignorant of it. This is its meaning.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'answer covering is indispensable for the whole of a woman is عوره if any part of her awra is exposed prayer is not permitted to her whether she knew this ruling or was ignorant of it this is its meaning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 8, NULL, 'Question: Concerning the man wading through water, the man in fear, and the traveler pressing hard upon his journey — men who carry weaponry that bars them from prayer, such as the feathering of arrows, leather straps, the trimmings of daggers, and garments of pure silk — is their prayer complete without repetition, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'question concerning the man wading through water the man in fear and the traveler pressing hard upon his journey men who carry weaponry that bars them from prayer such as the feathering of arrows leather straps the trimmings of daggers and garments of pure silk is their prayer complete without repetition or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 9, NULL, 'Answer: Prayer is valid only in pure garments. Whatever is impure, the worshipper strips from himself.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'answer prayer is valid only in pure garments whatever is impure the worshipper strips from himself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 10, NULL, 'Question: What is your ruling on a man who prays while carrying weights of gold and silver upon him, wrought or unwrought, tucked into his waistband? Is his prayer established or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'question what is your ruling on a man who prays while carrying weights of gold and silver upon him wrought or unwrought tucked into his waistband is his prayer established or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 11, NULL, 'Answer: His prayer is complete and established.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'answer his prayer is complete and established', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 12, NULL, 'Question: The abridgment of the Musannaf states that there is no harm in praying upon a rug bearing figures, so long as they are not in the place of prostration and do not divert him from the prayer. Is prayer upon such a rug permitted? And likewise, if garments bearing figures are worn, is prayer in them permitted?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'question the abridgment of the musannaf states that there is no harm in praying upon a rug bearing figures so long as they are not in the place of prostration and do not divert him from the prayer is prayer upon such a rug permitted and likewise if garments bearing figures are worn is prayer in them permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 13, NULL, 'Answer: As for the rug and the garment bearing figures, prayer is not permitted when they are seen. When they are not seen, prayer in them and upon them is permitted.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'answer as for the rug and the garment bearing figures prayer is not permitted when they are seen when they are not seen prayer in them and upon them is permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 14, NULL, 'Question: If the worshipper prays upon stone, upon unbaked brick, or upon the like of these, is prayer upon them permitted or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'question if the worshipper prays upon stone upon unbaked brick or upon the like of these is prayer upon them permitted or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 15, NULL, 'Answer: Obligatory prayer upon them is not permitted; only the supererogatory and the sunna prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'answer obligatory prayer upon them is not permitted only the supererogatory and the sunna prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 16, NULL, 'Question: What is your ruling on a man who applies henna to his hand or foot for adornment and not for any benefit? Is that permitted?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'question what is your ruling on a man who applies henna to his hand or foot for adornment and not for any benefit is that permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 17, NULL, 'Answer: It is not fitting that men use henna for adornment. Women are commanded to use it. For men, to leave it aside without cause is better, though no sin falls upon one who does it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'answer it is not fitting that men use henna for adornment women are commanded to use it for men to leave it aside without cause is better though no sin falls upon one who does it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 18, NULL, 'From another place: prayer is permitted in the garments of the children of Muslims and the slaves of Muslims, so long as no impurity appears in them and none is seen, when they themselves do not pray. Whoever prays, then finishes his prayer, and then sees that his garment was impure — if he knew of it beforehand, his prayer is void and he repeats it, whether its time has passed or not. A man is not to pray bareheaded, without turban and without mantle; but if he finds neither, he prays. Whoever prays leaving upon his shoulders only a small kerchief — that is, his handcloth — while he has another garment available, his prayer is not permitted; but if he finds nothing else, his prayer in it is permitted.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'from another place prayer is permitted in the garments of the children of muslims and the slaves of muslims so long as no impurity appears in them and none is seen when they themselves do not pray whoever prays then finishes his prayer and then sees that his garment was impure if he knew of it beforehand his prayer is void and he repeats it whether its time has passed or not a man is not to pray bareheaded without turban and without mantle but if he finds neither he prays whoever prays leaving upon his shoulders only a small kerchief that is his handcloth while he has another garment available his prayer is not permitted but if he finds nothing else his prayer in it is permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 19, NULL, 'The book of the abridgment of the Musannaf states: if a man prays with his عَوْرَة uncovered and does not know of it until he has finished the prayer, he must repeat it once he comes to know. And if a free woman or a slave woman prays with her awra uncovered — whether she knew of it or not — her prayer is spoiled.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'the book of the abridgment of the musannaf states if a man prays with his عوره uncovered and does not know of it until he has finished the prayer he must repeat it once he comes to know and if a free woman or a slave woman prays with her awra uncovered whether she knew of it or not her prayer is spoiled', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 20, NULL, 'Our master Jafar ibn Mansur al-Yaman, may God exalt his sanctity, says in the book of the obligations and the limits of religion: it is lawful for a man to uncover his head openly, to go out among the congregation, and to pray with his head uncovered. If a man prays with something in his mouth — such as a gemstone, a dirham, or the like — and it does not prevent him from forming the letters properly, his prayer is complete. If he is holding something in his hand and it does not prevent him from fulfilling the limits of his prayer, there is no harm upon him; yet to be free of it is better for him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'our master jafar ibn mansur al yaman may god exalt his sanctity says in the book of the obligations and the limits of religion it is lawful for a man to uncover his head openly to go out among the congregation and to pray with his head uncovered if a man prays with something in his mouth such as a gemstone a dirham or the like and it does not prevent him from forming the letters properly his prayer is complete if he is holding something in his hand and it does not prevent him from fulfilling the limits of his prayer there is no harm upon him yet to be free of it is better for him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 21, NULL, 'From the same source: whoever has nothing but an impure garment, can obtain no other, and has no water with which to purify it, prays in it and repeats the prayer when he finds another garment or water to purify it. If he has two garments, one of them impure, but does not know which one, it is incumbent upon him to pray that prayer in each of them, intending by it the performance of the obligation. There is no harm in praying upon a rug bearing figures, so long as they are not in the place of prostration and do not divert him from the prayer. As for plaster and the like, over which carrion is burned and with which the mosque and the house are plastered, there is no harm in prostrating upon it, for the fire has purified it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'from the same source whoever has nothing but an impure garment can obtain no other and has no water with which to purify it prays in it and repeats the prayer when he finds another garment or water to purify it if he has two garments one of them impure but does not know which one it is incumbent upon him to pray that prayer in each of them intending by it the performance of the obligation there is no harm in praying upon a rug bearing figures so long as they are not in the place of prostration and do not divert him from the prayer as for plaster and the like over which carrion is burned and with which the mosque and the house are plastered there is no harm in prostrating upon it for the fire has purified it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 22, NULL, 'In the book of the interpretation of the Daaim, upon the saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'in the book of the interpretation of the daaim upon the saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 23, NULL, 'Sayingوَلَا بَأْسَ فِي الصَّلَاةِ فِي الْقَمِيصِ الْوَاحِدِ الْكَثِيفِ إِذَا أَزَرَّهُ', '', 'وَلَا بَأْسَ فِي الصَّلَاةِ فِي الْقَمِيصِ الْوَاحِدِ الْكَثِيفِ إِذَا أَزَرَّهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'sayingولا باس في الصلاه في القميص الواحد الكثيف اذا ازره', 'ولا باس في الصلاه في القميص الواحد الكثيف اذا ازره');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 24, NULL, 'There is no harm in praying in a single thick shirt if he belts it — meaning the worshipper. The sense of this is that, when he bows, his private part should not appear from its edge.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'there is no harm in praying in a single thick shirt if he belts it meaning the worshipper the sense of this is that when he bows his private part should not appear from its edge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 25, NULL, 'From the same, upon the saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'from the same upon the saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 26, NULL, 'Sayingمَثَلُ جَنَاحَيِ الْخُطَّافِ', '', 'مَثَلُ جَنَاحَيِ الْخُطَّافِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'sayingمثل جناحي الخطاف', 'مثل جناحي الخطاف');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 27, NULL, 'Like the two wings of the swallow. This means a garment that he wraps over his back and whose two ends he brings back upon his shoulders, when he finds nothing other than that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'like the two wings of the swallow this means a garment that he wraps over his back and whose two ends he brings back upon his shoulders when he finds nothing other than that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 28, NULL, 'From the same, upon the saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'from the same upon the saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 29, NULL, 'Sayingنَهَىٰ عَنِ اشْتِمَالِ الصَّمَّاءِ', '', 'نَهَىٰ عَنِ اشْتِمَالِ الصَّمَّاءِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'sayingنهي عن اشتمال الصماء', 'نهي عن اشتمال الصماء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 30, NULL, 'He forbade the wrapping called اِشْتِمَالُ الصَّمَّاءِ. That is when a man wraps himself in a single garment, setting its middle upon his head or upon his shoulders, drawing one end with his left hand against his body, and turning the end on his right toward his left and behind him, gathering it with his right hand, so that he becomes as though sewn into it with both his hands beneath it. If he prays in this condition, he cannot perform the prayer properly: he cannot set his palms upon the ground as required, he cannot bow or prostrate, and he cannot manage the raising of his hands. Such a prayer is therefore incomplete and does not suffice him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'he forbade the wrapping called اشتمال الصماء that is when a man wraps himself in a single garment setting its middle upon his head or upon his shoulders drawing one end with his left hand against his body and turning the end on his right toward his left and behind him gathering it with his right hand so that he becomes as though sewn into it with both his hands beneath it if he prays in this condition he cannot perform the prayer properly he cannot set his palms upon the ground as required he cannot bow or prostrate and he cannot manage the raising of his hands such a prayer is therefore incomplete and does not suffice him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 31, NULL, 'The book of the abridgment of the Musannaf states: as for the slave woman, the woman under a contract of manumission, the woman freed at her master''s death, and the girl who has not yet reached menstruation, there is no harm in their praying without a head covering. Whichever of them is set free while she does not know of it must repeat every prayer she prayed after her freedom without a head covering.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'the book of the abridgment of the musannaf states as for the slave woman the woman under a contract of manumission the woman freed at her masters death and the girl who has not yet reached menstruation there is no harm in their praying without a head covering whichever of them is set free while she does not know of it must repeat every prayer she prayed after her freedom without a head covering', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 32, NULL, 'The book of questions and answers — whose questions come from the most venerable Shaykh Yusuf ibn Ismail ibn Ibrahim al-Samati al-Hindi and whose answers come from our master Idris ibn al-Hasan, may God exalt his sanctity — contains the following. Question: Is prayer permitted upon stones and plaster? Favor us with a clear and sufficient answer. Answer: The Prophet said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'the book of questions and answers whose questions come from the most venerable shaykh yusuf ibn ismail ibn ibrahim al samati al hindi and whose answers come from our master idris ibn al hasan may god exalt his sanctity contains the following question is prayer permitted upon stones and plaster favor us with a clear and sufficient answer answer the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 33, NULL, 'Sayingجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا', '', 'جُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'sayingجعلت لي الارض مسجدا وطهورا', 'جعلت لي الارض مسجدا وطهورا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 34, NULL, 'The earth has been made for me a place of prostration and a means of purification.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'the earth has been made for me a place of prostration and a means of purification', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 35, NULL, 'And everything of the earth with which dry ablution is not permitted — prayer upon it is not permitted.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'and everything of the earth with which dry ablution is not permitted prayer upon it is not permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 36, NULL, 'The book of questions on matters of the Sharia and their answers — containing one hundred and three questions, put by certain eminent shaykhs of India and answered by certain callers from Yemen, may God sanctify their souls — records the following.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'the book of questions on matters of the sharia and their answers containing one hundred and three questions put by certain eminent shaykhs of india and answered by certain callers from yemen may god sanctify their souls records the following', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 37, NULL, 'The seventeenth question: Concerning a free woman who prays with a net upon her head — does the net serve her in place of a mantle, or not? Answer: It is not recorded that prayer in a shift and head-veil suffices unless both are thick; and the net does not cover.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'the seventeenth question concerning a free woman who prays with a net upon her head does the net serve her in place of a mantle or not answer it is not recorded that prayer in a shift and head veil suffices unless both are thick and the net does not cover', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 38, NULL, 'The fourth question: Concerning camels, cattle, and sheep that feed upon filth — when their milk and their clarified butter, or the egg whites of hens, reach the garments or bodies of those praying, do they render them impure or not? Answer: A small amount of it is permitted.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'the fourth question concerning camels cattle and sheep that feed upon filth when their milk and their clarified butter or the egg whites of hens reach the garments or bodies of those praying do they render them impure or not answer a small amount of it is permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 39, NULL, 'It is said in the book of the interpretation of the Sharia: there is no prayer except upon the earth or upon what grows from it, such as green plants. And it is said therein: the Prophet said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'it is said in the book of the interpretation of the sharia there is no prayer except upon the earth or upon what grows from it such as green plants and it is said therein the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 40, NULL, 'Sayingحُبِّبَ إِلَيَّ مِنْ دُنْيَاكُمْ ثَلَاثَةٌ النِّسَاءُ وَالطِّيبُ وَجُعِلَتْ قُرَّةُ عَيْنِي فِي الصَّلَاةِ', '', 'حُبِّبَ إِلَيَّ مِنْ دُنْيَاكُمْ ثَلَاثَةٌ النِّسَاءُ وَالطِّيبُ وَجُعِلَتْ قُرَّةُ عَيْنِي فِي الصَّلَاةِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'sayingحبب الي من دنياكم ثلاثه النساء والطيب وجعلت قره عيني في الصلاه', 'حبب الي من دنياكم ثلاثه النساء والطيب وجعلت قره عيني في الصلاه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 41, NULL, 'Three things of your world have been made beloved to me: women and perfume, and the delight of my eye has been placed in prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'three things of your world have been made beloved to me women and perfume and the delight of my eye has been placed in prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 42, NULL, 'And it is said therein: the Prophet (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'and it is said therein the prophet ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 43, NULL, 'Sayingكُلُّ صَلَاةٍ لَا يُقْرَأُ فِيهَا بِفَاتِحَةِ الْكِتَابِ فَهِيَ خِدَاجٌ غَيْرُ تَامَّةٍ', '', 'كُلُّ صَلَاةٍ لَا يُقْرَأُ فِيهَا بِفَاتِحَةِ الْكِتَابِ فَهِيَ خِدَاجٌ غَيْرُ تَامَّةٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'sayingكل صلاه لا يقرا فيها بفاتحه الكتاب فهي خداج غير تامه', 'كل صلاه لا يقرا فيها بفاتحه الكتاب فهي خداج غير تامه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 44, NULL, 'Every prayer in which the Opening of the Book is not recited is defective and incomplete.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'every prayer in which the opening of the book is not recited is defective and incomplete', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 45, NULL, 'And it is said therein:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'and it is said therein', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 46, NULL, 'Sayingلَا صَلَاةَ فِي أَعْطَانِ الْإِبِلِ وَلَا بَأْسَ بِالصَّلَاةِ فِي مَرَابِضِ الْغَنَمِ بَعْدَ أَنْ تُكْنَسَ وَتُرَشَّ', '', 'لَا صَلَاةَ فِي أَعْطَانِ الْإِبِلِ وَلَا بَأْسَ بِالصَّلَاةِ فِي مَرَابِضِ الْغَنَمِ بَعْدَ أَنْ تُكْنَسَ وَتُرَشَّ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'sayingلا صلاه في اعطان الابل ولا باس بالصلاه في مرابض الغنم بعد ان تكنس وترش', 'لا صلاه في اعطان الابل ولا باس بالصلاه في مرابض الغنم بعد ان تكنس وترش');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 47, NULL, 'Prayer is not valid in the resting places of camels. There is, however, no harm in praying in the folds of sheep once they have been swept and sprinkled with water.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'prayer is not valid in the resting places of camels there is however no harm in praying in the folds of sheep once they have been swept and sprinkled with water', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 48, NULL, 'Our master the Commander of the Faithful, Ali ibn Abi Talib (ع), said in his four hundred counsels of etiquette:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'our master the commander of the faithful ali ibn abi talib ع said in his four hundred counsels of etiquette', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 49, NULL, 'Sayingلَا يَقُومَنَّ أَحَدُكُمْ بَيْنَ يَدَيِ اللَّهِ عَزَّ وَجَلَّ اِلَّا وَعَلَيْهِ ثَوْبٌ نَظِيفٌ', '', 'لَا يَقُومَنَّ أَحَدُكُمْ بَيْنَ يَدَيِ اللَّهِ عَزَّ وَجَلَّ اِلَّا وَعَلَيْهِ ثَوْبٌ نَظِيفٌ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'sayingلا يقومن احدكم بين يدي الله عز وجل الا وعليه ثوب نظيف', 'لا يقومن احدكم بين يدي الله عز وجل الا وعليه ثوب نظيف');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 50, NULL, 'Let none of you stand before God, the Mighty and Exalted, except in a clean garment.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'let none of you stand before god the mighty and exalted except in a clean garment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 51, NULL, 'And he said therein:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'and he said therein', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 52, NULL, 'Sayingلا يصلي الرجل في قميص متوشحاً فأنه فعل قوم لوط', '', 'لا يصلي الرجل في قميص متوشحاً فأنه فعل قوم لوط', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'sayingلا يصلي الرجل في قميص متوشحا فانه فعل قوم لوط', 'لا يصلي الرجل في قميص متوشحا فانه فعل قوم لوط');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 53, NULL, 'A man is not to pray in a shirt draped loosely across him, for that is the practice of the people of Lot.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'a man is not to pray in a shirt draped loosely across him for that is the practice of the people of lot', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 54, NULL, 'And he said therein:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'and he said therein', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 55, NULL, 'Sayingلَا تَجُوزُ الصَّلَاةُ فِي ثَوْبٍ يُعَسْطِلُ فِيهِ عَلَى عُنُقِهِ وَفِي الْقَمِيِّصِ الصَّفِيقِ يَرُدُّهُ عَلَيْهِ', '', 'لَا تَجُوزُ الصَّلَاةُ فِي ثَوْبٍ يُعَسْطِلُ فِيهِ عَلَى عُنُقِهِ وَفِي الْقَمِيِّصِ الصَّفِيقِ يَرُدُّهُ عَلَيْهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'sayingلا تجوز الصلاه في ثوب يعسطل فيه علي عنقه وفي القميص الصفيق يرده عليه', 'لا تجوز الصلاه في ثوب يعسطل فيه علي عنقه وفي القميص الصفيق يرده عليه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 56, NULL, 'Prayer is not permitted in a garment that hangs slack about his neck, nor in a close-woven shirt unless he draws it over himself.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'prayer is not permitted in a garment that hangs slack about his neck nor in a close woven shirt unless he draws it over himself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 57, NULL, 'And he said therein:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'and he said therein', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 58, NULL, 'Sayingلَا يَسْجُدُ الرَّجُلُ عَلَى صُورَةٍ وَلَا عَلَى بِسَاطٍ هِيَ فِيهِ', '', 'لَا يَسْجُدُ الرَّجُلُ عَلَى صُورَةٍ وَلَا عَلَى بِسَاطٍ هِيَ فِيهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'sayingلا يسجد الرجل علي صوره ولا علي بساط هي فيه', 'لا يسجد الرجل علي صوره ولا علي بساط هي فيه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 59, NULL, 'A man must not prostrate upon an image, nor upon a rug that contains one.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'a man must not prostrate upon an image nor upon a rug that contains one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 60, NULL, 'And he said therein:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'and he said therein', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 61, NULL, 'Sayingوَلَا يَعْقِدُ الرَّجُلُ الدِّرْهَمَ الَّذِي فِيهِ الصُّورَةُ فِي ثَوْبِهِ وَهُوَ يُصَلِّي وَتَجُوزُ أَنْ تَكُونَ الدَّرَاهِمُ فِي هِمْيَانٍ أَوْ ثَوْبٍ إِذَا كَانَ طَاهِرًا وَلَا يَسْجُدُ الرَّجُلُ عَلَى كُدْسِ الْحِنْطَةِ وَلَا عَلَى شَعِيرٍ وَلَا عَلَى شَيْءٍ مِمَّا يُؤْكَلُ وَلَا عَلَى الْخُبْزِ', '', 'وَلَا يَعْقِدُ الرَّجُلُ الدِّرْهَمَ الَّذِي فِيهِ الصُّورَةُ فِي ثَوْبِهِ وَهُوَ يُصَلِّي وَتَجُوزُ أَنْ تَكُونَ الدَّرَاهِمُ فِي هِمْيَانٍ أَوْ ثَوْبٍ إِذَا كَانَ طَاهِرًا وَلَا يَسْجُدُ الرَّجُلُ عَلَى كُدْسِ الْحِنْطَةِ وَلَا عَلَى شَعِيرٍ وَلَا عَلَى شَيْءٍ مِمَّا يُؤْكَلُ وَلَا عَلَى الْخُبْزِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'sayingولا يعقد الرجل الدرهم الذي فيه الصوره في ثوبه وهو يصلي وتجوز ان تكون الدراهم في هميان او ثوب اذا كان طاهرا ولا يسجد الرجل علي كدس الحنطه ولا علي شعير ولا علي شيء مما يوكل ولا علي الخبز', 'ولا يعقد الرجل الدرهم الذي فيه الصوره في ثوبه وهو يصلي وتجوز ان تكون الدراهم في هميان او ثوب اذا كان طاهرا ولا يسجد الرجل علي كدس الحنطه ولا علي شعير ولا علي شيء مما يوكل ولا علي الخبز');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'what the worshipper wears and stands upon', '20. What the Worshipper Wears and Stands Upon', 62, NULL, 'A man must not knot a dirham bearing an image into his garment while praying. It is, however, permitted for coins to be carried in a money belt or in a cloth, provided it is clean. He must not prostrate upon a heap of wheat, barley, anything edible, or bread.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 20 what the worshipper wears and stands upon', 'a man must not knot a dirham bearing an image into his garment while praying it is however permitted for coins to be carried in a money belt or in a cloth provided it is clean he must not prostrate upon a heap of wheat barley anything edible or bread', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 1, NULL, 'I turn now to the Friday prayer, and I set down first what I find in the book of questions and answers mentioned at the outset — which one of its arrangers ordered according to the chapters of Daaim al-Islam.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'i turn now to the friday prayer and i set down first what i find in the book of questions and answers mentioned at the outset which one of its arrangers ordered according to the chapters of daaim al islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 2, NULL, 'The question: What do you say concerning what has come in the Book of Purity — that if three miles or more separate two congregational mosques, Friday prayer is established in each of them, whether they stand in one city or two; but if the distance between them in a single city falls short of that, Friday prayer is established in only one of them? Our master, if the distance is less than three miles and the two mosques belong to two separate cities, is Friday prayer established in both of them or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'the question what do you say concerning what has come in the book of purity that if three miles or more separate two congregational mosques friday prayer is established in each of them whether they stand in one city or two but if the distance between them in a single city falls short of that friday prayer is established in only one of them our master if the distance is less than three miles and the two mosques belong to two separate cities is friday prayer established in both of them or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 3, NULL, 'The answer: Friday prayer is not established in both when the distance between them is less than three miles, whether they belong to one city or to two.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'the answer friday prayer is not established in both when the distance between them is less than three miles whether they belong to one city or to two', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 4, NULL, 'The question concerns the words of our master al-Muayyad in the Friday sermon:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'the question concerns the words of our master al muayyad in the friday sermon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 5, NULL, 'Sayingفَمَنْ تَرَكَهَا مُتَعَمِّداً أَوْ مُسْتَخِفّاً بِحَقِّهَا مِنْ غَيْرِ عُذْرٍ لَهُ مَعَ إِمَامٍ عَدْلٍ أَوْ جَائِرٍ فَلَا تَجْمَعِ اللهُ شَمْلَهُ', '', 'فَمَنْ تَرَكَهَا مُتَعَمِّداً أَوْ مُسْتَخِفّاً بِحَقِّهَا مِنْ غَيْرِ عُذْرٍ لَهُ مَعَ إِمَامٍ عَدْلٍ أَوْ جَائِرٍ فَلَا تَجْمَعِ اللهُ شَمْلَهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'sayingفمن تركها متعمدا او مستخفا بحقها من غير عذر له مع امام عدل او جاير فلا تجمع الله شمله', 'فمن تركها متعمدا او مستخفا بحقها من غير عذر له مع امام عدل او جاير فلا تجمع الله شمله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 6, NULL, 'Whoever abandons it deliberately, or makes light of its due, without excuse — whether under a just imam or an unjust one — may God not gather his affairs together; to the end of the passage.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'whoever abandons it deliberately or makes light of its due without excuse whether under a just imam or an unjust one may god not gather his affairs together to the end of the passage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 7, NULL, 'The answer: It is not permissible to pray behind the people of injustice except for the sake of dissimulation, as has come in the Shariah from Mawlana al-Baqir Muhammad ibn Ali (ع), who said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'the answer it is not permissible to pray behind the people of injustice except for the sake of dissimulation as has come in the shariah from mawlana al baqir muhammad ibn ali ع who said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 8, NULL, 'Do not count the prayer behind a الناصب or a الحروري as valid. Treat such a person as one of the pillars of المسجد and recite for yourself, as though you were praying alone.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'do not count the prayer behind a الناصب or a الحروري as valid treat such a person as one of the pillars of المسجد and recite for yourself as though you were praying alone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 9, NULL, 'Sayingلَا تَعْتَدَّ بِالصَّلَاةِ خَلْفَ النَّاصِبِ وَلَا الْحَرُورِيِّ وَاجْعَلْهُ سَارِيَةً مِنْ سَوَارِي الْمَسْجِدِ وَاقْرَأْ لِنَفْسِكَ كَأَنَّكَ وَحْدَكَ', '', 'لَا تَعْتَدَّ بِالصَّلَاةِ خَلْفَ النَّاصِبِ وَلَا الْحَرُورِيِّ وَاجْعَلْهُ سَارِيَةً مِنْ سَوَارِي الْمَسْجِدِ وَاقْرَأْ لِنَفْسِكَ كَأَنَّكَ وَحْدَكَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'sayingلا تعتد بالصلاه خلف الناصب ولا الحروري واجعله ساريه من سواري المسجد واقرا لنفسك كانك وحدك', 'لا تعتد بالصلاه خلف الناصب ولا الحروري واجعله ساريه من سواري المسجد واقرا لنفسك كانك وحدك');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 10, NULL, 'The commentary on the reports records that al-Husayn ibn Ali (ع) put the governor of Muawiya forward to lead the prayer over his brother al-Hasan ibn Ali (عَلَيْهِمُ السَّلَامُ), and said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'the commentary on the reports records that al husayn ibn ali ع put the governor of muawiya forward to lead the prayer over his brother al hasan ibn ali عليهم السلام and said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 11, NULL, 'Sayingلَوْلَا السُّنَّةُ لَمَا قَدَّمْتُكَ', '', 'لَوْلَا السُّنَّةُ لَمَا قَدَّمْتُكَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'sayingلولا السنه لما قدمتك', 'لولا السنه لما قدمتك');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 12, NULL, 'Were it not for the practice, I would not have put you forward.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'were it not for the practice i would not have put you forward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 13, NULL, 'By that, he meant the practice of the People of the House (عَلَيْهِمُ السَّلَامُ) in dissimulation — as one of the Imams (عَلَيْهِمُ السَّلَامُ) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'by that he meant the practice of the people of the house عليهم السلام in dissimulation as one of the imams عليهم السلام said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 14, NULL, 'Sayingالتَّقِيَّةُ دِينِي وَدِينُ آبَائِي', '', 'التَّقِيَّةُ دِينِي وَدِينُ آبَائِي', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'sayingالتقيه ديني ودين ابايي', 'التقيه ديني ودين ابايي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 15, NULL, 'Dissimulation is my religion and the religion of my fathers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'dissimulation is my religion and the religion of my fathers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 16, NULL, 'As for what is meant by "the unjust" in his words, it refers to whoever has been set up among the summoners and from whom injustice and transgression have appeared: it is obligatory to pray behind him, and it is incumbent upon the people, when they observe this in him, to bring the matter before the holder of authority and to await his response. This is the meaning of his saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'as for what is meant by the unjust in his words it refers to whoever has been set up among the summoners and from whom injustice and transgression have appeared it is obligatory to pray behind him and it is incumbent upon the people when they observe this in him to bring the matter before the holder of authority and to await his response this is the meaning of his saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 17, NULL, 'Sayingأَيُّهَا الصَّالِحُونَ فَتَحَقَّقُوا ذَلِكَ وَلَا تَرْتَابُوا بَعْدَ الْيَقِينِ فَقَدِ اعْتَصَمْتُمْ بِجَبَلِ اللَّهِ الْمَتِينِ', '', 'أَيُّهَا الصَّالِحُونَ فَتَحَقَّقُوا ذَلِكَ وَلَا تَرْتَابُوا بَعْدَ الْيَقِينِ فَقَدِ اعْتَصَمْتُمْ بِجَبَلِ اللَّهِ الْمَتِينِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'sayingايها الصالحون فتحققوا ذلك ولا ترتابوا بعد اليقين فقد اعتصمتم بجبل الله المتين', 'ايها الصالحون فتحققوا ذلك ولا ترتابوا بعد اليقين فقد اعتصمتم بجبل الله المتين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 18, NULL, 'O righteous ones, verify this and do not fall into doubt after certainty, for you have taken firm hold of the strong mountain of God.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'o righteous ones verify this and do not fall into doubt after certainty for you have taken firm hold of the strong mountain of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 19, NULL, 'He says in the book Mukhtasar al-Musannaf: The Friday prayer behind the Imam of the Muslims is more excellent than the prayer behind his deputies. If the Imam is delayed because he is occupied with some of the interests of the Muslims, and his deputies pray in his stead in mosques that are near one another, then the prayer in his own mosque — the one in which it has been his custom to pray — is more fitting than in any other.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'he says in the book mukhtasar al musannaf the friday prayer behind the imam of the muslims is more excellent than the prayer behind his deputies if the imam is delayed because he is occupied with some of the interests of the muslims and his deputies pray in his stead in mosques that are near one another then the prayer in his own mosque the one in which it has been his custom to pray is more fitting than in any other', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 20, NULL, 'He says in it: The call to prayer that obliges the one upon whom the Friday duty rests to leave off buying and selling is the call given in the presence of the preacher when he sits in the place from which he delivers the sermon. If two of those obliged to the Friday prayer transact a sale at the time when it is forbidden, their sale is not annulled. Whoever grows thirsty while the Imam is on the pulpit may drink.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'he says in it the call to prayer that obliges the one upon whom the friday duty rests to leave off buying and selling is the call given in the presence of the preacher when he sits in the place from which he delivers the sermon if two of those obliged to the friday prayer transact a sale at the time when it is forbidden their sale is not annulled whoever grows thirsty while the imam is on the pulpit may drink', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 21, NULL, 'He says in it: If the Imam delivers the sermon on Friday and his state of purity is broken, he descends and performs the ablution; then if he wishes he repeats the sermon, and if he wishes he prays — all of this suffices him. If he delivers the sermon seated because of an ailment, that suffices him. It is disliked for him to omit the sitting between the two sermons, but if he has done so, repetition is not obligatory upon him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'he says in it if the imam delivers the sermon on friday and his state of purity is broken he descends and performs the ablution then if he wishes he repeats the sermon and if he wishes he prays all of this suffices him if he delivers the sermon seated because of an ailment that suffices him it is disliked for him to omit the sitting between the two sermons but if he has done so repetition is not obligatory upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 22, NULL, 'If the Imam delivers the sermon on Friday and then some matter overtakes the people and they go off to it, and only one man remains with him, then he prays four cycles. If he has delivered the sermon to the people on Friday and prayed one cycle with them and then they all departed and he remained alone, he prays the Friday prayer as two cycles. If he has opened the prayer and they departed before he bowed, he begins afresh the noon prayer of four cycles. If the Imam prays the Friday prayer with the people, and when he has finished the second cycle he rises to stand and then remembers, it is upon him to sit, to make the testimony, to give the greeting of peace, and to perform the two prostrations of forgetfulness.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'if the imam delivers the sermon on friday and then some matter overtakes the people and they go off to it and only one man remains with him then he prays four cycles if he has delivered the sermon to the people on friday and prayed one cycle with them and then they all departed and he remained alone he prays the friday prayer as two cycles if he has opened the prayer and they departed before he bowed he begins afresh the noon prayer of four cycles if the imam prays the friday prayer with the people and when he has finished the second cycle he rises to stand and then remembers it is upon him to sit to make the testimony to give the greeting of peace and to perform the two prostrations of forgetfulness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 23, NULL, 'And from it: Whoever among the people of Friday sleeps while waiting for the Friday prayer, and the prayer is established and purification is not possible for him, performs the dry ablution and prays with the Imam, then repeats it as four.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'and from it whoever among the people of friday sleeps while waiting for the friday prayer and the prayer is established and purification is not possible for him performs the dry ablution and prays with the imam then repeats it as four', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 24, NULL, 'He says in the book of reports: And he leans upon his sword; if he does not find a sword, then upon a staff.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'he says in the book of reports and he leans upon his sword if he does not find a sword then upon a staff', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 25, NULL, 'He says in the book Tawil al-Shariah: The sermon is before the prayer, and the prayer after the sermon is two cycles. He divides the sermon into two portions with a sitting that separates them. The raising of the voice in its recitation distinguishes it from the noon prayer on the remaining days, and the noon prayer is at seven hours. He said: The call to stand for prayer comes after the sermon.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'he says in the book tawil al shariah the sermon is before the prayer and the prayer after the sermon is two cycles he divides the sermon into two portions with a sitting that separates them the raising of the voice in its recitation distinguishes it from the noon prayer on the remaining days and the noon prayer is at seven hours he said the call to stand for prayer comes after the sermon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 26, NULL, 'He says in it: The practice of the respondents in the assembly of the summoner is like the practice of the congregation on Friday, or the congregation behind the Imam. When the preacher on Friday ascends the pulpit and faces the people, silence becomes obligatory, such that it is not permissible for anyone to speak or to occupy himself with anything other than listening to him and giving ear to him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'he says in it the practice of the respondents in the assembly of the summoner is like the practice of the congregation on friday or the congregation behind the imam when the preacher on friday ascends the pulpit and faces the people silence becomes obligatory such that it is not permissible for anyone to speak or to occupy himself with anything other than listening to him and giving ear to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 27, NULL, 'He says in it: It is not permissible for him to give suck unless his summoner has appointed him to the suckling and chosen him for it. When the Imam recites, listening becomes obligatory and nothing else, and it is not permissible to turn away from him. Likewise, it is not permissible for the respondent to press proposals upon the summoner or to demand from him the various branches of knowledge, for he knows better how to raise his children.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'he says in it it is not permissible for him to give suck unless his summoner has appointed him to the suckling and chosen him for it when the imam recites listening becomes obligatory and nothing else and it is not permissible to turn away from him likewise it is not permissible for the respondent to press proposals upon the summoner or to demand from him the various branches of knowledge for he knows better how to raise his children', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 28, NULL, 'Our master Zayd ibn Muhammad ibn al-Fadl said in his Hidden Epistle: The Friday prayer points to Muhammad (ع), who is the gate of the Garden, and he has two summonses — an outward summons to the outward face of his Shariah and an inward summons to the interpretation of his law. Then he said: Because the prayer on the remaining days was four cycles, on Friday it became two, and the sermon was made a substitute for the two cycles. It is praise, admonition, supplication, and exposition from the Lord of exposition, and it is never without warning. The sitting during the sermon is the separation between the upper light and the lower light; the Qaim (ع) rises with the two lights. Then he said: The preacher is not to deliver the sermon upon the call to prayer that has already been given, until the muezzin who stands before the seat gives the call after the Imam has ascended the pulpit. Then he said: The call is given only in the congregational mosque, as an announcement. Then he said: Whoever gives the call on that day in one of the mosques other than the congregational mosque has erred, and if he did it deliberately he is punished and commanded to perform the washing of Friday. Then he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'our master zayd ibn muhammad ibn al fadl said in his hidden epistle the friday prayer points to muhammad ع who is the gate of the garden and he has two summonses an outward summons to the outward face of his shariah and an inward summons to the interpretation of his law then he said because the prayer on the remaining days was four cycles on friday it became two and the sermon was made a substitute for the two cycles it is praise admonition supplication and exposition from the lord of exposition and it is never without warning the sitting during the sermon is the separation between the upper light and the lower light the qaim ع rises with the two lights then he said the preacher is not to deliver the sermon upon the call to prayer that has already been given until the muezzin who stands before the seat gives the call after the imam has ascended the pulpit then he said the call is given only in the congregational mosque as an announcement then he said whoever gives the call on that day in one of the mosques other than the congregational mosque has erred and if he did it deliberately he is punished and commanded to perform the washing of friday then he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 29, NULL, 'Sayingفَاعْرِفْ فَضْلَ يَوْمِ الْجُمُعَةِ حَتَّىٰ يَجْمَعَ اللَّهُ شَمْلَكَ بِيَوْمِ السَّبْتِ فَتَسْتَرِيحَ وَتَسْبُتَ وَلَا تَشْقَىٰ إِنْ شَاءَ اللَّهُ تَعَالَىٰ', '', 'فَاعْرِفْ فَضْلَ يَوْمِ الْجُمُعَةِ حَتَّىٰ يَجْمَعَ اللَّهُ شَمْلَكَ بِيَوْمِ السَّبْتِ فَتَسْتَرِيحَ وَتَسْبُتَ وَلَا تَشْقَىٰ إِنْ شَاءَ اللَّهُ تَعَالَىٰ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'sayingفاعرف فضل يوم الجمعه حتي يجمع الله شملك بيوم السبت فتستريح وتسبت ولا تشقي ان شاء الله تعالي', 'فاعرف فضل يوم الجمعه حتي يجمع الله شملك بيوم السبت فتستريح وتسبت ولا تشقي ان شاء الله تعالي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 30, NULL, 'Know the excellence of the day of Friday, so that God may gather your affairs together on the day of the Sabbath and you may rest and repose, spared from wretchedness — if God the Exalted wills.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'know the excellence of the day of friday so that god may gather your affairs together on the day of the sabbath and you may rest and repose spared from wretchedness if god the exalted wills', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 31, NULL, 'Mawlana Amir al-Muminin Ali ibn Abi Talib (ع) said in his Four Hundred Points of Conduct:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'mawlana amir al muminin ali ibn abi talib ع said in his four hundred points of conduct', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 32, NULL, 'Sayingمَنْ كَانَتْ لَهُ إِلَى اللَّهِ حَاجَةٌ فَلْيَطْلُبْهَا فِي ثَلَاثِ سَاعَاتٍ: ١- فِي يَوْمِ الْجُمُعَةِ سَاعَةَ زَوَالِ الشَّمْسِ ٢- وَحِينَ تَهبُّ الرِّيَاحُ وَتُفْتَحُ أَبْوَابُ السَّمَاءِ وَتَنْزِلُ الرَّحْمَةُ ٣- وَسَاعَةً فِي آخِرِ اللَّيْلِ عِنْدَ طُلُوعِ الْفَجْرِ.', '', 'مَنْ كَانَتْ لَهُ إِلَى اللَّهِ حَاجَةٌ فَلْيَطْلُبْهَا فِي ثَلَاثِ سَاعَاتٍ: ١- فِي يَوْمِ الْجُمُعَةِ سَاعَةَ زَوَالِ الشَّمْسِ ٢- وَحِينَ تَهبُّ الرِّيَاحُ وَتُفْتَحُ أَبْوَابُ السَّمَاءِ وَتَنْزِلُ الرَّحْمَةُ ٣- وَسَاعَةً فِي آخِرِ اللَّيْلِ عِنْدَ طُلُوعِ الْفَجْرِ.', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'sayingمن كانت له الي الله حاجه فليطلبها في ثلاث ساعات ١ في يوم الجمعه ساعه زوال الشمس ٢ وحين تهب الرياح وتفتح ابواب السماء وتنزل الرحمه ٣ وساعه في اخر الليل عند طلوع الفجر', 'من كانت له الي الله حاجه فليطلبها في ثلاث ساعات ١ في يوم الجمعه ساعه زوال الشمس ٢ وحين تهب الرياح وتفتح ابواب السماء وتنزل الرحمه ٣ وساعه في اخر الليل عند طلوع الفجر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 33, NULL, 'Sayingوَإِنَّ مَلَكَيْنِ يُنَادِيَانِ هَلْ مِنْ تَائِبٍ فَيُتَابَ عَلَيْهِ هَلْ مِنْ سَائِلٍ فَيُعْطَىٰ هَلْ مِنْ مُسْتَغْفِرٍ فَيُغْفَرَ لَهُ هَلْ مِنْ طَالِبِ حَاجَةٍ فَأَجِيبُوا دَاعِيَ اللَّهِ', '', 'وَإِنَّ مَلَكَيْنِ يُنَادِيَانِ هَلْ مِنْ تَائِبٍ فَيُتَابَ عَلَيْهِ هَلْ مِنْ سَائِلٍ فَيُعْطَىٰ هَلْ مِنْ مُسْتَغْفِرٍ فَيُغْفَرَ لَهُ هَلْ مِنْ طَالِبِ حَاجَةٍ فَأَجِيبُوا دَاعِيَ اللَّهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'sayingوان ملكين يناديان هل من تايب فيتاب عليه هل من سايل فيعطي هل من مستغفر فيغفر له هل من طالب حاجه فاجيبوا داعي الله', 'وان ملكين يناديان هل من تايب فيتاب عليه هل من سايل فيعطي هل من مستغفر فيغفر له هل من طالب حاجه فاجيبوا داعي الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 34, NULL, 'Whoever has a need before God, let him seek it in three hours:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'whoever has a need before god let him seek it in three hours', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 35, NULL, 'On the day of Friday, at the hour when the sun passes its zenith. When the winds blow, and the gates of heaven are opened, and mercy descends. An hour at the end of the night, at the breaking of dawn.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'on the day of friday at the hour when the sun passes its zenith when the winds blow and the gates of heaven are opened and mercy descends an hour at the end of the night at the breaking of dawn', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 36, NULL, 'He says in it: the supplication of devotion in the Friday prayer falls before the bowing in the second cycle. The recitation on Friday is: in the first cycle, the chapter of the Congregation after the Opening of the Book, and in the second, the Opening of the Book followed by the chapter of the Hypocrites.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'he says in it the supplication of devotion in the friday prayer falls before the bowing in the second cycle the recitation on friday is in the first cycle the chapter of the congregation after the opening of the book and in the second the opening of the book followed by the chapter of the hypocrites', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 37, NULL, 'He says in it, among legal questions that are all marvels, another question: What do you say of a preacher who was delivering the sermon on Friday when a man entered through the door of the congregational mosque, whereupon the sermon of that preacher was spoiled, and so was the prayer of those who prayed with him? The answer: that preacher is the property of the man who entered through the door of the congregational mosque, for that man had appointed him as his deputy; so when he came in upon him, it was no longer permissible for him to go before his master, nor to lead him in prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'he says in it among legal questions that are all marvels another question what do you say of a preacher who was delivering the sermon on friday when a man entered through the door of the congregational mosque whereupon the sermon of that preacher was spoiled and so was the prayer of those who prayed with him the answer that preacher is the property of the man who entered through the door of the congregational mosque for that man had appointed him as his deputy so when he came in upon him it was no longer permissible for him to go before his master nor to lead him in prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 39, NULL, 'I likewise set down here what is contained in the book of questions and answers mentioned at the outset, arranged according to the order of the chapters of the book Daaim al-Islam.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'i likewise set down here what is contained in the book of questions and answers mentioned at the outset arranged according to the order of the chapters of the book daaim al islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 40, NULL, 'The question: What do you say concerning what has come in the Shariah — that no tashriq is incumbent upon the traveler except in a congregational city? Our master, is what is intended by tashriq here the festival prayer, or not? And whoever forgets one of the magnifications in the festival prayer, or more than one — how should he act?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'the question what do you say concerning what has come in the shariah that no tashriq is incumbent upon the traveler except in a congregational city our master is what is intended by tashriq here the festival prayer or not and whoever forgets one of the magnifications in the festival prayer or more than one how should he act', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 41, NULL, 'The answer: It has come in the book al-Mujzi, in the section on the ages of camels, cattle, and the like, that there is no tashriq except in a congregational city — that is, no prayer of the two festivals — because the two festival prayers are prayed at the rising of the sun, and the one who prays them is called المشرّق (al-mushriq). And it has come in Mukhtasar al-Musannaf: whoever forgets part of the magnification completes it before he bows; and if he has already passed beyond the bowing and is certain of the omission, he performs the two prostrations of forgetfulness.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'the answer it has come in the book al mujzi in the section on the ages of camels cattle and the like that there is no tashriq except in a congregational city that is no prayer of the two festivals because the two festival prayers are prayed at the rising of the sun and the one who prays them is called المشرق al mushriq and it has come in mukhtasar al musannaf whoever forgets part of the magnification completes it before he bows and if he has already passed beyond the bowing and is certain of the omission he performs the two prostrations of forgetfulness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 42, NULL, 'The question: What do you say concerning the magnification from the day of Arafah to the last of the days of tashriq being twenty-three magnifications, while in our lands they add one magnification after the festival prayer so that it becomes twenty-four? And what is the meaning of this?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'the question what do you say concerning the magnification from the day of arafah to the last of the days of tashriq being twenty three magnifications while in our lands they add one magnification after the festival prayer so that it becomes twenty four and what is the meaning of this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 43, NULL, 'The answer: The magnification in those days is twenty-three, and it is a likeness of what obtains in the summons of the five speakers — the possessors of firm resolve — who correspond to the five prayers, drawn from the mention of the ten spiritual ranks and the ten bodily ranks, and the mention of the speaker of the cycle, his executor, and the Imam of the age.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'the answer the magnification in those days is twenty three and it is a likeness of what obtains in the summons of the five speakers the possessors of firm resolve who correspond to the five prayers drawn from the mention of the ten spiritual ranks and the ten bodily ranks and the mention of the speaker of the cycle his executor and the imam of the age', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 44, NULL, 'Sayingفَخُذْ مَا أُوتِيتَ وَكُنْ مِنَ الشَّاكِرِينَ', '', 'فَخُذْ مَا أُوتِيتَ وَكُنْ مِنَ الشَّاكِرِينَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'sayingفخذ ما اوتيت وكن من الشاكرين', 'فخذ ما اوتيت وكن من الشاكرين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 45, NULL, 'So take what you have been given, and be among the thankful.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'so take what you have been given and be among the thankful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 46, NULL, 'From another source: whoever prays the festival prayer while owing a makeup of the dawn prayer, his festival prayer is valid and he does not repeat it; and likewise the funeral prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'from another source whoever prays the festival prayer while owing a makeup of the dawn prayer his festival prayer is valid and he does not repeat it and likewise the funeral prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 47, NULL, 'From our master al-Hasan ibn Idris: whoever prays the festival prayer before bringing out the alms of the breaking of the fast does not repeat it, and he hands over the alms afterward. The washing for the two festivals is a practice of the Prophet. The first of its time is the breaking of dawn, and the last of it is the time of the sun''s passing the zenith. Whoever prays the festival prayer before the sun passes the zenith, for an excuse, it is valid for him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'from our master al hasan ibn idris whoever prays the festival prayer before bringing out the alms of the breaking of the fast does not repeat it and he hands over the alms afterward the washing for the two festivals is a practice of the prophet the first of its time is the breaking of dawn and the last of it is the time of the suns passing the zenith whoever prays the festival prayer before the sun passes the zenith for an excuse it is valid for him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 48, NULL, 'He says in the book Mukhtasar al-Musannaf: the washing for the two festivals is a practice of the Prophet; the first of its time is the breaking of dawn and the last of it is the time of the sun''s passing the zenith.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'he says in the book mukhtasar al musannaf the washing for the two festivals is a practice of the prophet the first of its time is the breaking of dawn and the last of it is the time of the suns passing the zenith', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 49, NULL, 'He says in the book of reports: and the supplication of devotion is:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'he says in the book of reports and the supplication of devotion is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 50, NULL, 'Sayingاَللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاعْفُ عَنِّي فِي الدِّينِ وَالدُّنْيَا إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', '', 'اَللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاعْفُ عَنِّي فِي الدِّينِ وَالدُّنْيَا إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'sayingاللهم اغفر لي وارحمني وعافني واعف عني في الدين والدنيا انك علي كل شيء قدير', 'اللهم اغفر لي وارحمني وعافني واعف عني في الدين والدنيا انك علي كل شيء قدير');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 51, NULL, 'O God, forgive me, have mercy on me, grant me well-being, and pardon me in religion and in the world. You are powerful over all things.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'o god forgive me have mercy on me grant me well being and pardon me in religion and in the world you are powerful over all things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 52, NULL, 'He says in it: if the people of the desert attend — and those travelers who choose to attend the festival — that is good, and there is merit in it for them. And from it: it is fitting for whoever is among the people of the desert, at two leagues from the city or less, to witness the festival.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'he says in it if the people of the desert attend and those travelers who choose to attend the festival that is good and there is merit in it for them and from it it is fitting for whoever is among the people of the desert at two leagues from the city or less to witness the festival', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 53, NULL, 'He says in it: its congregation is five, one of them the Imam, as with the congregation of the Friday prayer; and where there is one who establishes it, it is an obligation like the obligation of Friday. Whoever misses it with the one who establishes it but catches the two sermons prays it as four as well. Whoever misses one cycle of the festival prayer and catches the second with the Imam adds to it another cycle with its magnifications. The practice regarding the magnification is that it begins after the completion of the fast, on the night of the breaking of the fast and on the day of the breaking of the fast, until he prays and finishes the prayer. Whoever prays the festival prayer raises his hands with every magnification. Whoever forgets part of the magnification completes it before he bows; and if he has passed beyond the bowing and is certain of the omission, he performs the two prostrations of forgetfulness.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'he says in it its congregation is five one of them the imam as with the congregation of the friday prayer and where there is one who establishes it it is an obligation like the obligation of friday whoever misses it with the one who establishes it but catches the two sermons prays it as four as well whoever misses one cycle of the festival prayer and catches the second with the imam adds to it another cycle with its magnifications the practice regarding the magnification is that it begins after the completion of the fast on the night of the breaking of the fast and on the day of the breaking of the fast until he prays and finishes the prayer whoever prays the festival prayer raises his hands with every magnification whoever forgets part of the magnification completes it before he bows and if he has passed beyond the bowing and is certain of the omission he performs the two prostrations of forgetfulness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 54, NULL, 'He says in the book al-Musannaf: the festival prayer is not prayed at Mina. Likewise our master al-Qadi al-Numan ibn Muhammad said in Tawil al-Daaim; and it has been verified from our master Idris ibn Hasan that the festival prayer is not prayed there in congregation, but each one prays it by himself, one by one.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'he says in the book al musannaf the festival prayer is not prayed at mina likewise our master al qadi al numan ibn muhammad said in tawil al daaim and it has been verified from our master idris ibn hasan that the festival prayer is not prayed there in congregation but each one prays it by himself one by one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 55, NULL, 'He says in the book of questions and answers mentioned at the outset: intercourse with one''s wife is permitted on the night of the festival of the breaking of the fast and before the festival prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'he says in the book of questions and answers mentioned at the outset intercourse with ones wife is permitted on the night of the festival of the breaking of the fast and before the festival prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 56, NULL, 'Our master Jafar ibn Mansur al-Yaman said in the book al-Rida al-Batin: it is permitted after the festival of the breaking of the fast to fast on the following day and thereafter. And he says in it: it is not permitted after this festival — meaning the festival of the sacrifice — as it is permitted after the festival of the breaking of the fast.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'our master jafar ibn mansur al yaman said in the book al rida al batin it is permitted after the festival of the breaking of the fast to fast on the following day and thereafter and he says in it it is not permitted after this festival meaning the festival of the sacrifice as it is permitted after the festival of the breaking of the fast', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 57, NULL, 'Our master Zayd ibn Muhammad ibn al-Fadl said in the Hidden Epistle, concerning the prayer of the festival of the breaking of the fast: الفطر (al-fitr) in the language means appearance and beginning. One says تَفَطَّرَتِ الْأَرْضُ وَانْفَطَرَتْ (تَفَطَّرَتِ الْأَرْضُ وَانْفَطَرَتْ) — meaning the earth split open and what lay within it appeared and came forth. Likewise تَفَطَّرَتِ الشَّجَرَةُ (tafattarat al-shajarah) means that its hidden fruit appeared. And فَطَرَ نَابُ الْبَعِيرِ (fatara nab al-bair) means that it came up and appeared. In all these examples there runs a single sense: it is the day on which the command and the things that had been hidden come to light. From this, the breaking of the fast was named fitr, for fasting is silence and concealment. God the Exalted said in the story of Maryam:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'our master zayd ibn muhammad ibn al fadl said in the hidden epistle concerning the prayer of the festival of the breaking of the fast الفطر al fitr in the language means appearance and beginning one says تفطرت الارض وانفطرت تفطرت الارض وانفطرت meaning the earth split open and what lay within it appeared and came forth likewise تفطرت الشجره tafattarat al shajarah means that its hidden fruit appeared and فطر ناب البعير fatara nab al bair means that it came up and appeared in all these examples there runs a single sense it is the day on which the command and the things that had been hidden come to light from this the breaking of the fast was named fitr for fasting is silence and concealment god the exalted said in the story of maryam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'friday and the two festivals', '21. Friday and the Two Festivals', 58, NULL, 'Maryam: 26إِنِّى نَذَرْتُ لِلرَّحْمَنِ صَوْمًۭا فَلَنْ أُكَلِّمَ ٱلْيَوْمَ إِنسِيًّۭا', '', 'إِنِّى نَذَرْتُ لِلرَّحْمَنِ صَوْمًۭا فَلَنْ أُكَلِّمَ ٱلْيَوْمَ إِنسِيًّۭا', 'Maryam: 26', 19, 26, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'maryam 26اني نذرت للرحمن صوما فلن اكلم اليوم انسيا', 'اني نذرت للرحمن صوما فلن اكلم اليوم انسيا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 59, NULL, 'I have vowed a fast to the Most Merciful, so I shall not speak to any human being today.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'i have vowed a fast to the most merciful so i shall not speak to any human being today', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 60, NULL, 'That is: I have vowed silence and stillness, showing nothing of what is within me. So fitr is the appearance of secrets and the knowledge of hidden things. And His saying,', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'that is i have vowed silence and stillness showing nothing of what is within me so fitr is the appearance of secrets and the knowledge of hidden things and his saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'friday and the two festivals', '21. Friday and the Two Festivals', 61, NULL, 'Al-Infitar: 1وإذا السماء انفطرت', '', 'وإذا السماء انفطرت', 'Al-Infitar: 1', 82, 1, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'al infitar 1واذا السماء انفطرت', 'واذا السماء انفطرت');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 62, NULL, 'And when the sky is split open,', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'and when the sky is split open', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 63, NULL, 'means that it was cleft and what was within it came forth. In another meaning, الْفِطْر is the new; and فَطَرَ اللَّهُ الْخَلْقَ (fatara Allah al-khalq) means the beginning of His fashioning of them. The day of the breaking of the fast is therefore the day of the manifestation of the command that had been veiled. Then he said: Whoever has fasted the days of the month of Ramadan, for him is the breaking of the fast, the festival, and joy; and whoever does not know the meaning of the reality of fasting and its limits has nothing of God, and he is as God, mighty and majestic, said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'means that it was cleft and what was within it came forth in another meaning الفطر is the new and فطر الله الخلق fatara allah al khalq means the beginning of his fashioning of them the day of the breaking of the fast is therefore the day of the manifestation of the command that had been veiled then he said whoever has fasted the days of the month of ramadan for him is the breaking of the fast the festival and joy and whoever does not know the meaning of the reality of fasting and its limits has nothing of god and he is as god mighty and majestic said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 64, NULL, 'Sayingعَامِلَةٌ نَاصِبَةٌ تَصْلَى نَارًا حَامِيَةً', '', 'عَامِلَةٌ نَاصِبَةٌ تَصْلَى نَارًا حَامِيَةً', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'sayingعامله ناصبه تصلي نارا حاميه', 'عامله ناصبه تصلي نارا حاميه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 65, NULL, 'Toiling, weary, burning in a scorching fire.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'toiling weary burning in a scorching fire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'friday and the two festivals', '21. Friday and the Two Festivals', 66, NULL, 'The festival prayer has neither a call to prayer nor a call to stand. He then said: the sermon at the breaking of the fast comes after the prayer. He said: the recitation in it is aloud. He said: the prayer of the sacrifice is on the day of the sacrifice — the day of the pilgrimage. He then said: the fact that this sermon begins contrary to all other sermons is a sign that the command appears otherwise than it was in the cycles that have passed. Every sermon begins with praise, except the sermon of the day of the sacrifice, which begins with the four magnifications.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 21 friday and the two festivals', 'the festival prayer has neither a call to prayer nor a call to stand he then said the sermon at the breaking of the fast comes after the prayer he said the recitation in it is aloud he said the prayer of the sacrifice is on the day of the sacrifice the day of the pilgrimage he then said the fact that this sermon begins contrary to all other sermons is a sign that the command appears otherwise than it was in the cycles that have passed every sermon begins with praise except the sermon of the day of the sacrifice which begins with the four magnifications', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 0, NULL, 'I turn now to the subject of omission in the prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'i turn now to the subject of omission in the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 1, NULL, 'In the question-and-answer book I named at the outset — one of whose arrangers set out following the order of the chapters of the Book of the Pillars of Islam — the following is asked:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'in the question and answer book i named at the outset one of whose arrangers set out following the order of the chapters of the book of the pillars of islam the following is asked', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 2, NULL, 'Question: What do you say if someone makes room for another to pray, standing in for a man who does not know all the positions in the prayer that require the prostration of omission? Must that man perform the two prostrations of omission after completing every obligatory act about which something appears uncertain to him, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question what do you say if someone makes room for another to pray standing in for a man who does not know all the positions in the prayer that require the prostration of omission must that man perform the two prostrations of omission after completing every obligatory act about which something appears uncertain to him or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 3, NULL, 'The answer is: if it is established that he has indeed committed an omission, he prostrates for it; otherwise he does not.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'the answer is if it is established that he has indeed committed an omission he prostrates for it otherwise he does not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 4, NULL, 'Question: What do you say regarding the statement in the Book of Purity that whoever errs by not pronouncing the opening takbir — or omits it deliberately or out of ignorance — must repeat the prayer? O our master, if a man forgets to open the prayer after every two rakahs in the four-rakah and six-rakah prayers, does that invalidate his prayer or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question what do you say regarding the statement in the book of purity that whoever errs by not pronouncing the opening takbir or omits it deliberately or out of ignorance must repeat the prayer o our master if a man forgets to open the prayer after every two rakahs in the four rakah and six rakah prayers does that invalidate his prayer or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 5, NULL, 'The answer is: if he did not sit after each pair of rakahs, his prayer is invalidated.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'the answer is if he did not sit after each pair of rakahs his prayer is invalidated', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 6, NULL, 'Question: What do you say regarding the statement in the Book of Purity that whoever inadvertently adds to his prayer, even without sitting for the tashahhud, must repeat the prayer; and that if he adds an extra bowing he repeats the prayer, but if he adds an extra prostration he completes the prayer and performs the two prostrations of omission? What does this mean?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question what do you say regarding the statement in the book of purity that whoever inadvertently adds to his prayer even without sitting for the tashahhud must repeat the prayer and that if he adds an extra bowing he repeats the prayer but if he adds an extra prostration he completes the prayer and performs the two prostrations of omission what does this mean', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 7, NULL, 'The answer is: if he adds a bowing and has not sat for the tashahhud, he must repeat the prayer. But if he has sat for the tashahhud and completed two rakahs — whether with an additional bowing or an additional prostration — he has done so in order.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'the answer is if he adds a bowing and has not sat for the tashahhud he must repeat the prayer but if he has sat for the tashahhud and completed two rakahs whether with an additional bowing or an additional prostration he has done so in order', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 8, NULL, 'Question: What do you say about a man who is praying behind an Imam and neglects one of the pillars of the prayer while following the Imam? How is his prayer?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question what do you say about a man who is praying behind an imam and neglects one of the pillars of the prayer while following the imam how is his prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 9, NULL, 'The answer is: the Imam bears the responsibility for the omission, except in the case of the bowing and the opening takbir — and the first thing is that he should not neglect those.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'the answer is the imam bears the responsibility for the omission except in the case of the bowing and the opening takbir and the first thing is that he should not neglect those', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 10, NULL, 'Question: What do you say regarding the statement in religious law that whoever forgets a prostration should prostrate after delivering the salaam, when he remembers? O our master, how does he prostrate after having left the prayer?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question what do you say regarding the statement in religious law that whoever forgets a prostration should prostrate after delivering the salaam when he remembers o our master how does he prostrate after having left the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 11, NULL, 'The answer is: he prostrates if he remembers before delivering the salaam. If he has already left the prayer, he has no recourse.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'the answer is he prostrates if he remembers before delivering the salaam if he has already left the prayer he has no recourse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 12, NULL, 'Question: What does our master say about a man who prayed the obligatory prayer and recited it in reverse order, from bottom to top? Must he perform the two prostrations of omission or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question what does our master say about a man who prayed the obligatory prayer and recited it in reverse order from bottom to top must he perform the two prostrations of omission or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 13, NULL, 'The answer is: there is nothing wrong with that, and it is not obligatory upon him to perform the two prostrations of omission.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'the answer is there is nothing wrong with that and it is not obligatory upon him to perform the two prostrations of omission', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 14, NULL, 'Question: A man prayed some of the obligatory Zuhr prayer and sat down and recited the first tashahhud, then prayed two more rakahs and recited the tashahhud again, then recalled that he had prayed only three rakahs. What should he do?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question a man prayed some of the obligatory zuhr prayer and sat down and recited the first tashahhud then prayed two more rakahs and recited the tashahhud again then recalled that he had prayed only three rakahs what should he do', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 15, NULL, 'The answer is: he prays the rakah he missed after the salaam, reciting in it the Opening and a surah, because it is one of the first two rakahs. He then recites the tashahhud, delivers the salaam, and performs the two prostrations of omission.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'the answer is he prays the rakah he missed after the salaam reciting in it the opening and a surah because it is one of the first two rakahs he then recites the tashahhud delivers the salaam and performs the two prostrations of omission', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 16, NULL, 'Question: Whoever neglects the first tashahhud in the obligatory prayer but recites the final tashahhud, then remembers before delivering the salaam — must he perform the prostration of omission or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question whoever neglects the first tashahhud in the obligatory prayer but recites the final tashahhud then remembers before delivering the salaam must he perform the prostration of omission or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 17, NULL, 'The answer is: there is no explicit text on this, and where there is no text it has not been stipulated that the worshipper must prostrate.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'the answer is there is no explicit text on this and where there is no text it has not been stipulated that the worshipper must prostrate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 18, NULL, 'Question: Regarding the man who repeats a single surah in the obligatory prayer after the Opening — must he perform the prostration of omission or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question regarding the man who repeats a single surah in the obligatory prayer after the opening must he perform the prostration of omission or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 19, NULL, 'The answer is: this too has not been stipulated.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'the answer is this too has not been stipulated', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 20, NULL, 'Question: Regarding a man who omits one obligation — should he prostrate the two prostrations of omission? And if he omits three obligations, does he prostrate separately for each omission with two prostrations, or do two prostrations suffice for all of them?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question regarding a man who omits one obligation should he prostrate the two prostrations of omission and if he omits three obligations does he prostrate separately for each omission with two prostrations or do two prostrations suffice for all of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 21, NULL, 'The answer is: the prostration of omission is not multiplied.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'the answer is the prostration of omission is not multiplied', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 22, NULL, 'Question: Regarding a man who prays behind an Imam and makes it clear that he intends in his prayer to be a follower — if the Imam delivers the salaam of the dhikr yet he did not intend the prayer, is his prayer valid or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question regarding a man who prays behind an imam and makes it clear that he intends in his prayer to be a follower if the imam delivers the salaam of the dhikr yet he did not intend the prayer is his prayer valid or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 23, NULL, 'The answer is: if the Imam intends the prayer on his behalf, then it is so; if he does not, the prayer lapses.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'the answer is if the imam intends the prayer on his behalf then it is so if he does not the prayer lapses', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 24, NULL, 'Question: What is transmitted from Jafar ibn Muhammad (ع), who said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question what is transmitted from jafar ibn muhammad ع who said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 25, NULL, 'Sayingمَنْ سَهَىٰ عَنِ الْقِرَاءَةِ فِي بَعْضِ الصَّلَاةِ فَقَرَأَ فِي مَا بَقِيَ مِنْهَا أَجْزَاَهُ ذَٰلِكَ فَإِنْ نَسِيَ الْقِرَاءَةَ كُلَّهَا وَأَتَمَّ الرُّكُوعَ وَالسُّجُودَ وَالتَّكْبِيرَ لَمْ يَكُنْ عَلَيْهِ الْإِعَادَةُ', '', 'مَنْ سَهَىٰ عَنِ الْقِرَاءَةِ فِي بَعْضِ الصَّلَاةِ فَقَرَأَ فِي مَا بَقِيَ مِنْهَا أَجْزَاَهُ ذَٰلِكَ فَإِنْ نَسِيَ الْقِرَاءَةَ كُلَّهَا وَأَتَمَّ الرُّكُوعَ وَالسُّجُودَ وَالتَّكْبِيرَ لَمْ يَكُنْ عَلَيْهِ الْإِعَادَةُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'sayingمن سهي عن القراءه في بعض الصلاه فقرا في ما بقي منها اجزاه ذلك فان نسي القراءه كلها واتم الركوع والسجود والتكبير لم يكن عليه الاعاده', 'من سهي عن القراءه في بعض الصلاه فقرا في ما بقي منها اجزاه ذلك فان نسي القراءه كلها واتم الركوع والسجود والتكبير لم يكن عليه الاعاده');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 26, NULL, 'This statement presents no difficulty.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'this statement presents no difficulty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 27, NULL, 'Question: If one forgets to recite some of the Quran, or all of it, must he perform the two prostrations of omission?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question if one forgets to recite some of the quran or all of it must he perform the two prostrations of omission', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 28, NULL, 'The answer is: the two prostrations of omission are required, and he performs them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'the answer is the two prostrations of omission are required and he performs them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 29, NULL, 'Question: What of a man whom the Imam has preceded in some part of the prayer? Must the latecomer perform the two prostrations of omission that the Imam himself owed before the latecomer arrived?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question what of a man whom the imam has preceded in some part of the prayer must the latecomer perform the two prostrations of omission that the imam himself owed before the latecomer arrived', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 30, NULL, 'The answer is: whoever enters the prayer with the Imam prostrates those two prostrations for his Imam''s omission — even if the only part he caught with him before the salaam was the opening takbir.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'the answer is whoever enters the prayer with the imam prostrates those two prostrations for his imams omission even if the only part he caught with him before the salaam was the opening takbir', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 31, NULL, 'Question: In the case of one who was preceded and prays part of the prayer with the Imam, then makes an error in what remains upon him — must he prostrate for the omission?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question in the case of one who was preceded and prays part of the prayer with the imam then makes an error in what remains upon him must he prostrate for the omission', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 32, NULL, 'The answer is: if he omits something while praying on his own, he prostrates.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'the answer is if he omits something while praying on his own he prostrates', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 33, NULL, 'Question: The text states that', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'question the text states that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 34, NULL, 'Sayingالْأَعْمَالُ لَا تُقْبَلُ اِلَّا بِالنِّيَّاتِ', '', 'الْأَعْمَالُ لَا تُقْبَلُ اِلَّا بِالنِّيَّاتِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'sayingالاعمال لا تقبل الا بالنيات', 'الاعمال لا تقبل الا بالنيات');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 35, NULL, 'deeds are accepted only with intentions. So if a person neglects — when purifying himself, or when beginning his prayer, or when fasting, or when performing any of the duties of God — to contract the intention with the tongue while he intends the act in his heart, is his action valid?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'deeds are accepted only with intentions so if a person neglects when purifying himself or when beginning his prayer or when fasting or when performing any of the duties of god to contract the intention with the tongue while he intends the act in his heart is his action valid', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 36, NULL, 'The answer is: the intention resides in the heart, and what is said with the tongue is merely a verbal expression, as mentioned in the Pillars. If he has contracted the intention in his heart, his act is complete.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'the answer is the intention resides in the heart and what is said with the tongue is merely a verbal expression as mentioned in the pillars if he has contracted the intention in his heart his act is complete', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 37, NULL, 'He said in the councils of instruction that doubt in prayer has its root in omission, which is inattention. It is a word that troubles many of those who occupy themselves with jurisprudence, so that they suppose doubt to be like omission — but it is not so. The one who commits an omission is certain of what he has omitted, while the doubter is not certain of what he doubts.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'he said in the councils of instruction that doubt in prayer has its root in omission which is inattention it is a word that troubles many of those who occupy themselves with jurisprudence so that they suppose doubt to be like omission but it is not so the one who commits an omission is certain of what he has omitted while the doubter is not certain of what he doubts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 38, NULL, 'Concerning the prostration of omission, it is said in the reports that it is performed after the salaam, and that after it one recites a brief testimony:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'concerning the prostration of omission it is said in the reports that it is performed after the salaam and that after it one recites a brief testimony', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 39, NULL, 'Sayingبِسْمِ اللَّهِ وَبِاللَّهِ وَأَشْهَدُ أَنْ لَا اِلَهَ إِلَّا اللَّهُ وَصَلَّى اللَّهُ عَلَى مُحَمَّدٍ وَآلِهِ', '', 'بِسْمِ اللَّهِ وَبِاللَّهِ وَأَشْهَدُ أَنْ لَا اِلَهَ إِلَّا اللَّهُ وَصَلَّى اللَّهُ عَلَى مُحَمَّدٍ وَآلِهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'sayingبسم الله وبالله واشهد ان لا اله الا الله وصلي الله علي محمد واله', 'بسم الله وبالله واشهد ان لا اله الا الله وصلي الله علي محمد واله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 40, NULL, 'In the name of God, and by God, and I bear witness that there is no god but God, and may God bless Muhammad and his family.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'in the name of god and by god and i bear witness that there is no god but god and may god bless muhammad and his family', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 41, NULL, 'It is also said: whoever falls into doubt while praying and does not know whether he is in an obligatory prayer or a voluntary one — if he stood up for the prescribed prayer and then became inattentive afterward and supposed it to be voluntary, that prayer suffices him for the prescribed one and his inattention does no harm; but if he stood up for a voluntary prayer, then it is voluntary. It is said: whoever doubts and does not know whether he prayed Zuhr or Asr — if some of the time of Asr still remains, he prays it; but if the sun has set and he then doubts, no making up is due from him. It is said: if you doubt about the dawn prayer, pray it again; and if you doubt about the sunset prayer, pray it again. It is said: whoever commits omissions repeatedly in a single prayer owes nothing but the two prostrations of omission.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'it is also said whoever falls into doubt while praying and does not know whether he is in an obligatory prayer or a voluntary one if he stood up for the prescribed prayer and then became inattentive afterward and supposed it to be voluntary that prayer suffices him for the prescribed one and his inattention does no harm but if he stood up for a voluntary prayer then it is voluntary it is said whoever doubts and does not know whether he prayed zuhr or asr if some of the time of asr still remains he prays it but if the sun has set and he then doubts no making up is due from him it is said if you doubt about the dawn prayer pray it again and if you doubt about the sunset prayer pray it again it is said whoever commits omissions repeatedly in a single prayer owes nothing but the two prostrations of omission', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 42, NULL, 'I find in the Mukhtasar al-Musannaf that if a man prays a four-rakah prayer and then, through inattention, rises for a fifth — if he had already recited the tashahhud in the fourth, he delivers the salaam while standing and departs; if he had not yet recited it, he sits, recites the tashahhud, and performs the two prostrations of omission. If he remembers that he rose to a fifth rakah only after he has bowed, and he had already recited the tashahhud in the fourth, his prayer is complete, and he joins to that rakah another as a voluntary prayer for himself; but if he had not recited the tashahhud in the fourth and did not sit for the length of the tashahhud, he repeats the prayer. Whoever forgets a prayer and does not know whether he prayed two, three, or four rakahs — and the Imam who prays aloud in what is prayed silently — has done ill, though his prayer is complete; and if he did that inattentively, the two prostrations of omission are upon him. If he is not an Imam but prays alone, and recites silently in what is recited aloud, or aloud in what is recited silently, nothing is due from him. Whatever holds concerning omission in the prayer of residence holds equally in the prayer of travel.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'i find in the mukhtasar al musannaf that if a man prays a four rakah prayer and then through inattention rises for a fifth if he had already recited the tashahhud in the fourth he delivers the salaam while standing and departs if he had not yet recited it he sits recites the tashahhud and performs the two prostrations of omission if he remembers that he rose to a fifth rakah only after he has bowed and he had already recited the tashahhud in the fourth his prayer is complete and he joins to that rakah another as a voluntary prayer for himself but if he had not recited the tashahhud in the fourth and did not sit for the length of the tashahhud he repeats the prayer whoever forgets a prayer and does not know whether he prayed two three or four rakahs and the imam who prays aloud in what is prayed silently has done ill though his prayer is complete and if he did that inattentively the two prostrations of omission are upon him if he is not an imam but prays alone and recites silently in what is recited aloud or aloud in what is recited silently nothing is due from him whatever holds concerning omission in the prayer of residence holds equally in the prayer of travel', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 43, NULL, 'I find, in the questions put by certain of the ranks of the island of India — with their answers from certain of the summoners of the island of Yemen, may God sanctify all their souls — in the twenty-sixth issue: concerning the man who is inattentive in the recitation in the obligatory prayer and recites in the second rakah, after the first, a surah taken from above, which is not what is required in the obligatory prayer — are the two prostrations of omission upon him? The answer is: this has not been stipulated, and he should not do it deliberately. And in the first issue of that collection: the text states that deeds are accepted only with intentions — so if a person neglects, when purifying himself, or in his prayer, or in his fasting, or when performing any of the duties of God, to contract the intention with the tongue while he intends the act in his heart, is his action valid? And if he goes beyond that and abandons the intention of the tongue entirely, is his action valid? The answer is: the intention resides in the heart, and what is uttered on the tongue is merely a statement, as mentioned in the Pillars. If he has contracted the intention in his heart, his act is complete.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'i find in the questions put by certain of the ranks of the island of india with their answers from certain of the summoners of the island of yemen may god sanctify all their souls in the twenty sixth issue concerning the man who is inattentive in the recitation in the obligatory prayer and recites in the second rakah after the first a surah taken from above which is not what is required in the obligatory prayer are the two prostrations of omission upon him the answer is this has not been stipulated and he should not do it deliberately and in the first issue of that collection the text states that deeds are accepted only with intentions so if a person neglects when purifying himself or in his prayer or in his fasting or when performing any of the duties of god to contract the intention with the tongue while he intends the act in his heart is his action valid and if he goes beyond that and abandons the intention of the tongue entirely is his action valid the answer is the intention resides in the heart and what is uttered on the tongue is merely a statement as mentioned in the pillars if he has contracted the intention in his heart his act is complete', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 44, NULL, 'I find in the book on the interpretation of the Sharia that whoever misses a prayer or forgets it should pray it when he remembers it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'i find in the book on the interpretation of the sharia that whoever misses a prayer or forgets it should pray it when he remembers it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 45, NULL, 'Our master, the owner of the Mustansiriyya councils, God''s (ع), said in the ninth of them: Listen now to what we recite to you of the meaning of doubt and omission in the prayer. The places of omission in prayer are seven, in six of which the two prostrations of omission are proper. They are the two that rub down the nose (اَلْمُرْغِمَتَانِ), and they are so named because they rub down the nose of the devil when the corruption of forgetfulness is repaired by them. Of these:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'our master the owner of the mustansiriyya councils gods ع said in the ninth of them listen now to what we recite to you of the meaning of doubt and omission in the prayer the places of omission in prayer are seven in six of which the two prostrations of omission are proper they are the two that rub down the nose المرغمتان and they are so named because they rub down the nose of the devil when the corruption of forgetfulness is repaired by them of these', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 46, NULL, 'Whoever is inattentive to a prostration prostrates when he remembers it, and the two prostrations of omission are upon him. Whoever forgets to sit for the first tashahhud and stands for the third rakah, and remembers before he bows that he did not sit, sits and recites the tashahhud, and when he delivers the salaam he performs the two prostrations of omission. If his inattention to the first tashahhud carries him on until he has bowed and prostrated, he completes his prayer, and the two prostrations of omission are upon him. Whoever is inattentive to the second tashahhud and delivers the salaam owes the two prostrations of omission. Whoever, through inattention, delivers the salaam after two rakahs when he is in a four-rakah prayer, prays two rakahs after them and performs the two prostrations of omission. Whoever, through inattention, rises from the final tashahhud after completing it to a fifth rakah owes the two prostrations of omission. Whoever is inattentive behind the Imam owes no prostration of omission, for the Imam bears that for him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'whoever is inattentive to a prostration prostrates when he remembers it and the two prostrations of omission are upon him whoever forgets to sit for the first tashahhud and stands for the third rakah and remembers before he bows that he did not sit sits and recites the tashahhud and when he delivers the salaam he performs the two prostrations of omission if his inattention to the first tashahhud carries him on until he has bowed and prostrated he completes his prayer and the two prostrations of omission are upon him whoever is inattentive to the second tashahhud and delivers the salaam owes the two prostrations of omission whoever through inattention delivers the salaam after two rakahs when he is in a four rakah prayer prays two rakahs after them and performs the two prostrations of omission whoever through inattention rises from the final tashahhud after completing it to a fifth rakah owes the two prostrations of omission whoever is inattentive behind the imam owes no prostration of omission for the imam bears that for him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 47, NULL, 'These are the seven places of omission in which the two prostrations are proper. As for doubt in prayer, it is a word that troubles many of those who occupy themselves with jurisprudence, so that they suppose it to be like omission — but it is not so. The one who commits an omission is certain of what he omitted, while the doubter is not certain of what he doubts. Doubt falls into twelve cases; in some of them there is a prostration of omission, and in others nothing at all. Those in which there is a prostration of omission are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'these are the seven places of omission in which the two prostrations are proper as for doubt in prayer it is a word that troubles many of those who occupy themselves with jurisprudence so that they suppose it to be like omission but it is not so the one who commits an omission is certain of what he omitted while the doubter is not certain of what he doubts doubt falls into twelve cases in some of them there is a prostration of omission and in others nothing at all those in which there is a prostration of omission are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 48, NULL, 'If the worshipper doubts about the bowing while he is still in the prayer, he bows, and the two prostrations of omission are upon him. If he doubts and does not know whether he is in one rakah or two, he builds upon what is certain, and that is the lesser. Likewise, if he doubts and does not know whether he has prayed two rakahs or three, he builds upon what is certain. If he doubts and does not know whether he has prayed three or four, he delivers the salaam, prays two rakahs seated, and performs the two prostrations of omission. If he does not know whether he has prayed two or four, he delivers the salaam, prays two rakahs standing, and performs the two prostrations of omission.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'if the worshipper doubts about the bowing while he is still in the prayer he bows and the two prostrations of omission are upon him if he doubts and does not know whether he is in one rakah or two he builds upon what is certain and that is the lesser likewise if he doubts and does not know whether he has prayed two rakahs or three he builds upon what is certain if he doubts and does not know whether he has prayed three or four he delivers the salaam prays two rakahs seated and performs the two prostrations of omission if he does not know whether he has prayed two or four he delivers the salaam prays two rakahs standing and performs the two prostrations of omission', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 49, NULL, 'As for those in which nothing is due:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'as for those in which nothing is due', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 50, NULL, 'If the worshipper doubts about the opening takbir after he has bowed, he continues in his prayer and nothing is due from him. Likewise if he doubts about the recitation after his bowing. Likewise if he doubts about the bowing after his prostration. Likewise if he doubts about the first prostration after his second prostration. Likewise if he doubts about the prostration after the tashahhud. Likewise if he doubts about anything of the prayer after the salaam.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'if the worshipper doubts about the opening takbir after he has bowed he continues in his prayer and nothing is due from him likewise if he doubts about the recitation after his bowing likewise if he doubts about the bowing after his prostration likewise if he doubts about the first prostration after his second prostration likewise if he doubts about the prostration after the tashahhud likewise if he doubts about anything of the prayer after the salaam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 51, NULL, 'In all of this nothing is due from him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'in all of this nothing is due from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 52, NULL, 'Our master, the Commander of the Faithful, Ali ibn Abi Talib (ع), said in his four hundred manners:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'our master the commander of the faithful ali ibn abi talib ع said in his four hundred manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 53, NULL, 'Sayingمَنْ كَانَ عَلَى يَقِينِهِ فَأَصَابَهُ شَكٌّ فَلْيَمْضِ عَلَى يَقِينِهِ فَاِنَّ الشَّكَّ لَا يَدْفَعُ الْيَقِينَ وَلَا يَنْقُصُهُ', '', 'مَنْ كَانَ عَلَى يَقِينِهِ فَأَصَابَهُ شَكٌّ فَلْيَمْضِ عَلَى يَقِينِهِ فَاِنَّ الشَّكَّ لَا يَدْفَعُ الْيَقِينَ وَلَا يَنْقُصُهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'sayingمن كان علي يقينه فاصابه شك فليمض علي يقينه فان الشك لا يدفع اليقين ولا ينقصه', 'من كان علي يقينه فاصابه شك فليمض علي يقينه فان الشك لا يدفع اليقين ولا ينقصه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 54, NULL, 'Whoever is certain of something and is then struck by doubt should act on his certainty, for doubt neither dispels certainty nor diminishes it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'whoever is certain of something and is then struck by doubt should act on his certainty for doubt neither dispels certainty nor diminishes it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 55, NULL, 'Among the questions submitted by certain shaykhs of India — may God be pleased with them — along with answers from our masters the summoners of Yemen — may God exalt their sanctity and grant us their intercession and their nearness — is the following. Question: What do you say concerning a man who is inattentive in forming his intention and does not declare himself a follower? Is his prayer valid or not? Answer: If his intention was to follow the Imam, his prayer is complete, even though he did not utter it aloud.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'among the questions submitted by certain shaykhs of india may god be pleased with them along with answers from our masters the summoners of yemen may god exalt their sanctity and grant us their intercession and their nearness is the following question what do you say concerning a man who is inattentive in forming his intention and does not declare himself a follower is his prayer valid or not answer if his intention was to follow the imam his prayer is complete even though he did not utter it aloud', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 56, NULL, 'In the book of questions, I was asked about one who doubts during his prayer and does not know how much of it he has performed. He builds on what he is certain of and then prostrates the two prostrations of omission after he delivers the salaam. If, however, he is certain of nothing — not knowing whether he added to or fell short of his prayer — he begins again from the beginning, and so likewise does the Imam.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'in the book of questions i was asked about one who doubts during his prayer and does not know how much of it he has performed he builds on what he is certain of and then prostrates the two prostrations of omission after he delivers the salaam if however he is certain of nothing not knowing whether he added to or fell short of his prayer he begins again from the beginning and so likewise does the imam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 57, NULL, 'I now turn to what interrupts the prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'i now turn to what interrupts the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 58, NULL, 'In the question-and-answer book named at the outset, arranged according to the chapters of the book of the Pillars of Islam: whoever vomits during the prayer, and the vomit reaches his garment, should wash the garment if water is close at hand; otherwise his prayer is void, and he then washes his garment and prays again. Whoever breaks his purity before the tashahhud must repeat the prayer; and if he breaks it after he has said,', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'in the question and answer book named at the outset arranged according to the chapters of the book of the pillars of islam whoever vomits during the prayer and the vomit reaches his garment should wash the garment if water is close at hand otherwise his prayer is void and he then washes his garment and prays again whoever breaks his purity before the tashahhud must repeat the prayer and if he breaks it after he has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 59, NULL, 'Sayingاَلسَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ اَلسَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ', '', 'اَلسَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ اَلسَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'sayingالسلام عليك ايها النبي ورحمه الله وبركاته السلام علينا وعلي عباد الله الصالحين', 'السلام عليك ايها النبي ورحمه الله وبركاته السلام علينا وعلي عباد الله الصالحين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 60, NULL, '"Peace be upon you, O Prophet, and the mercy of God and His blessings; peace be upon us and upon the righteous servants of God" — his prayer is permitted, and he does not repeat it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'peace be upon you o prophet and the mercy of god and his blessings peace be upon us and upon the righteous servants of god his prayer is permitted and he does not repeat it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 61, NULL, 'I mentioned in the Book of Purity that if a person suffers a nosebleed or vomits while in prayer, and can wash away the blood and stop the bleeding, and rinse away the vomit, all without turning his face from the qibla, he does so and builds upon his prayer. If he does turn his face from the qibla, however, he must repeat the prayer from its beginning. The reports add: unless he detects the breaking of purity — by finding its smell, hearing its sound, or having another person hear it from him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'i mentioned in the book of purity that if a person suffers a nosebleed or vomits while in prayer and can wash away the blood and stop the bleeding and rinse away the vomit all without turning his face from the qibla he does so and builds upon his prayer if he does turn his face from the qibla however he must repeat the prayer from its beginning the reports add unless he detects the breaking of purity by finding its smell hearing its sound or having another person hear it from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 62, NULL, 'I also mentioned in the book on the interpretation of prayer that the Prophet (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'i also mentioned in the book on the interpretation of prayer that the prophet ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 63, NULL, 'Sayingثَلَاثٌ تَقْطَعُ الصَّلَاةَ الْمَرْأَةُ وَالْحِمَارُ وَالْكَلْبُ الْأَسْوَدُ', '', 'ثَلَاثٌ تَقْطَعُ الصَّلَاةَ الْمَرْأَةُ وَالْحِمَارُ وَالْكَلْبُ الْأَسْوَدُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'sayingثلاث تقطع الصلاه المراه والحمار والكلب الاسود', 'ثلاث تقطع الصلاه المراه والحمار والكلب الاسود');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 64, NULL, 'Three things interrupt the prayer: a woman, a donkey, and a black dog. There is also the report that the Messenger of God (ع) was standing in prayer when a dog passed before him, then a donkey passed, then a woman passed while he was praying; and when he had finished he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'three things interrupt the prayer a woman a donkey and a black dog there is also the report that the messenger of god ع was standing in prayer when a dog passed before him then a donkey passed then a woman passed while he was praying and when he had finished he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 65, NULL, 'Sayingرَأَيْتُ الَّذِي رَأَيْتُمْ وَلَيْسَ يَقْطَعُ صَلَاةَ الْمُؤْمِنِ شَيْءٌ وَلَكِنِ ادْرَءُوا مَا اسْتَطَعْتُمْ', '', 'رَأَيْتُ الَّذِي رَأَيْتُمْ وَلَيْسَ يَقْطَعُ صَلَاةَ الْمُؤْمِنِ شَيْءٌ وَلَكِنِ ادْرَءُوا مَا اسْتَطَعْتُمْ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'sayingرايت الذي رايتم وليس يقطع صلاه المومن شيء ولكن ادرءوا ما استطعتم', 'رايت الذي رايتم وليس يقطع صلاه المومن شيء ولكن ادرءوا ما استطعتم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 66, NULL, 'I saw what you saw, and nothing interrupts the prayer of a believer; but ward off what you are able to ward off.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'i saw what you saw and nothing interrupts the prayer of a believer but ward off what you are able to ward off', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 67, NULL, 'Our master, the Commander of the Faithful, Ali ibn Abi Talib (ع), said in his four hundred manners:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'our master the commander of the faithful ali ibn abi talib ع said in his four hundred manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 68, NULL, 'Sayingلَا يَقْطَعُ الصَّلَاةَ التَّبَسُّمُ وَيَقْطَعُهَا الْقَهْقَهَةُ', '', 'لَا يَقْطَعُ الصَّلَاةَ التَّبَسُّمُ وَيَقْطَعُهَا الْقَهْقَهَةُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'sayingلا يقطع الصلاه التبسم ويقطعها القهقهه', 'لا يقطع الصلاه التبسم ويقطعها القهقهه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 69, NULL, 'Smiling does not interrupt the prayer, but loud laughter interrupts it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'smiling does not interrupt the prayer but loud laughter interrupts it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 70, NULL, 'It is mentioned in the book of questions — its question from the most honorable Shaykh Shimun ibn Muhammad Ghuri al-Hindi, and its answer from our master Badr al-Din Hasan ibn Idris, may God exalt their sanctity and grant us their intercession and their nearness. Question: What do you say about a man who entered the obligatory prayer with the opening takbir and recited, and then the Imam arrived and came forward while the man was still standing; and when the Imam bowed, the man bowed with him without renewing the opening takbir? What is the state of his prayer? The answer: he must repeat it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'it is mentioned in the book of questions its question from the most honorable shaykh shimun ibn muhammad ghuri al hindi and its answer from our master badr al din hasan ibn idris may god exalt their sanctity and grant us their intercession and their nearness question what do you say about a man who entered the obligatory prayer with the opening takbir and recited and then the imam arrived and came forward while the man was still standing and when the imam bowed the man bowed with him without renewing the opening takbir what is the state of his prayer the answer he must repeat it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 71, NULL, 'I come now to the prayer of one who has been preceded in part of the prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'i come now to the prayer of one who has been preceded in part of the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 72, NULL, 'It is mentioned in the question-and-answer book named at the outset, arranged according to the chapters of the book of the Pillars of Islam. Question: What do you say about a worshipper who reaches the Imam while the Imam is in the final tashahhud of any of the five prayers, the latecomer intending in his prayer to follow, sitting while the Imam sits, until when the Imam delivers the salaam of his prayer the latecomer rises and prays? Has the latecomer attained the congregation, and is his prayer valid? The answer: if he reached the Imam in the tashahhud — which is the last of the prayer''s limits — he intends the prayer as a follower, sits, and makes the supplication of turning toward God; and when the Imam delivers the salaam, he rises and prays his prayer, and he has attained the prayer of the congregation.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'it is mentioned in the question and answer book named at the outset arranged according to the chapters of the book of the pillars of islam question what do you say about a worshipper who reaches the imam while the imam is in the final tashahhud of any of the five prayers the latecomer intending in his prayer to follow sitting while the imam sits until when the imam delivers the salaam of his prayer the latecomer rises and prays has the latecomer attained the congregation and is his prayer valid the answer if he reached the imam in the tashahhud which is the last of the prayers limits he intends the prayer as a follower sits and makes the supplication of turning toward god and when the imam delivers the salaam he rises and prays his prayer and he has attained the prayer of the congregation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 73, NULL, 'It is mentioned in the book Mukhtasar al-Musannaf: if a latecomer reaches the Imam in the bowing, he says the takbir for the opening and then the takbir for the bowing, and that rakah is counted for him; and if he fears missing it, a single takbir suffices for both the opening and the bowing. Whoever reaches the Imam having been preceded enters into whatever the Imam is in — if it is something that is counted, he builds upon it; if not, he is one performing a voluntary act. He prays what he has caught and makes up what escaped him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'it is mentioned in the book mukhtasar al musannaf if a latecomer reaches the imam in the bowing he says the takbir for the opening and then the takbir for the bowing and that rakah is counted for him and if he fears missing it a single takbir suffices for both the opening and the bowing whoever reaches the imam having been preceded enters into whatever the imam is in if it is something that is counted he builds upon it if not he is one performing a voluntary act he prays what he has caught and makes up what escaped him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 74, NULL, 'It is said in the reports concerning an Imam whose purity is broken, who then puts forward a man who has been preceded: if that man does not know what the Imam preceded him with, he proceeds on his certainty until those behind him say the glorification to him, and then he reverts accordingly.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'it is said in the reports concerning an imam whose purity is broken who then puts forward a man who has been preceded if that man does not know what the imam preceded him with he proceeds on his certainty until those behind him say the glorification to him and then he reverts accordingly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'forgetting, doubting, and beginning again', '22. Forgetting, Doubting, and Beginning Again', 75, NULL, 'Our master and lord Muhammad ibn Fahd, may God exalt his sanctity, said in his noble epistle, which he titled The Broad Road of the Path of Guidance for the Rightly Guided, in the twentieth question: You asked also, may God grant you success in what pleases Him, about the latecomer who is unable to make the intention by uttering it with his tongue, and who enters with the Imam into whatever part of the prayer and its rakahs the Imam is in. The answer to you in this, by the granting of God — be He glorified — of what is correct in speech upon it, and its truth is thus: it has come in the books of the friends of God (عَلَيْهِمُ السَّلَامُ) that if the latecomer reaches the Imam in any rakah of his prayer and the Imam has not yet raised his head from the bowing in it, and the latecomer says a single takbir and enters with the Imam into his prayer by it, then he has attained that rakah with the Imam, and that is so together with the contracting of the intention in his heart upon it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 22 forgetting doubting and beginning again', 'our master and lord muhammad ibn fahd may god exalt his sanctity said in his noble epistle which he titled the broad road of the path of guidance for the rightly guided in the twentieth question you asked also may god grant you success in what pleases him about the latecomer who is unable to make the intention by uttering it with his tongue and who enters with the imam into whatever part of the prayer and its rakahs the imam is in the answer to you in this by the granting of god be he glorified of what is correct in speech upon it and its truth is thus it has come in the books of the friends of god عليهم السلام that if the latecomer reaches the imam in any rakah of his prayer and the imam has not yet raised his head from the bowing in it and the latecomer says a single takbir and enters with the imam into his prayer by it then he has attained that rakah with the imam and that is so together with the contracting of the intention in his heart upon it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 0, NULL, 'I turn now to the age at which boys are commanded to pray, and to what that entails.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'i turn now to the age at which boys are commanded to pray and to what that entails', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 2, NULL, 'Our master Amir al-Muminin Ali ibn Abi Talib (ع) said in his four hundred counsels of manners:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'our master amir al muminin ali ibn abi talib ع said in his four hundred counsels of manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 3, NULL, 'Sayingعَلِّمُوا صِبْيَانَكُمْ مَا يَنْفَعُكُمُ اللَّهُ بِهِ', '', 'عَلِّمُوا صِبْيَانَكُمْ مَا يَنْفَعُكُمُ اللَّهُ بِهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'sayingعلموا صبيانكم ما ينفعكم الله به', 'علموا صبيانكم ما ينفعكم الله به');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 4, NULL, 'Teach your boys that by which God will benefit you.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'teach your boys that by which god will benefit you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 5, NULL, 'And he said in the same place:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'and he said in the same place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 6, NULL, 'Sayingعَلِّمُوا صِبْيَانَكُمُ الصَّلَاةَ وَخُذُوهُمْ بِهَا إِذَا بَلَغُوا ثَمَانَ سِنِينَ', '', 'عَلِّمُوا صِبْيَانَكُمُ الصَّلَاةَ وَخُذُوهُمْ بِهَا إِذَا بَلَغُوا ثَمَانَ سِنِينَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'sayingعلموا صبيانكم الصلاه وخذوهم بها اذا بلغوا ثمان سنين', 'علموا صبيانكم الصلاه وخذوهم بها اذا بلغوا ثمان سنين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 7, NULL, 'Teach your boys the prayer, and hold them to it when they reach eight years.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'teach your boys the prayer and hold them to it when they reach eight years', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 8, NULL, 'Our master the noble dai Ibrahim ibn Husayn al-Hamidi said in the book عِبَارَةُ الْبِشَارَةِ that Amir al-Muminin (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'our master the noble dai ibrahim ibn husayn al hamidi said in the book عباره البشاره that amir al muminin ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 9, NULL, 'Sayingوَالصَّبِيُّ يَتَغَرُّ لِسَبْعِ سِنِينَ وَيَبْلُغُ لِأَرْبَعَ عَشَرَ وَيَكْمُلُ طُولُهُ وَعَرْضُهُ وَعُمْقُهُ لِإِحْدَى وَعِشْرِينَ سَنَةً وَيَكْمُلُ عَقْلُهُ لِثَمَانِيَةٍ وَعِشْرِينَ سَنَةً', '', 'وَالصَّبِيُّ يَتَغَرُّ لِسَبْعِ سِنِينَ وَيَبْلُغُ لِأَرْبَعَ عَشَرَ وَيَكْمُلُ طُولُهُ وَعَرْضُهُ وَعُمْقُهُ لِإِحْدَى وَعِشْرِينَ سَنَةً وَيَكْمُلُ عَقْلُهُ لِثَمَانِيَةٍ وَعِشْرِينَ سَنَةً', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'sayingوالصبي يتغر لسبع سنين ويبلغ لاربع عشر ويكمل طوله وعرضه وعمقه لاحدي وعشرين سنه ويكمل عقله لثمانيه وعشرين سنه', 'والصبي يتغر لسبع سنين ويبلغ لاربع عشر ويكمل طوله وعرضه وعمقه لاحدي وعشرين سنه ويكمل عقله لثمانيه وعشرين سنه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 10, NULL, 'The boy sheds his milk teeth at seven years, reaches maturity at fourteen, completes his height and breadth and depth at twenty-one years, and completes his intellect at twenty-eight years.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'the boy sheds his milk teeth at seven years reaches maturity at fourteen completes his height and breadth and depth at twenty one years and completes his intellect at twenty eight years', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 11, NULL, 'And in مُخْتَصَرُ الْآثَارِ I find this: they are to be separated in their sleeping places when they reach this stage, as a precaution against their proximity to one another. They have drawn close to maturity and to the stirring of desire, and there is concern that something to be feared may arise between them when one draws near another.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'and in مختصر الاثار i find this they are to be separated in their sleeping places when they reach this stage as a precaution against their proximity to one another they have drawn close to maturity and to the stirring of desire and there is concern that something to be feared may arise between them when one draws near another', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 13, NULL, 'In the book of questions and answers I mentioned above — arranged by one of its arrangers according to the order of the chapters of the book دَعَائِمُ الْإِسْلَامِ — I find:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'in the book of questions and answers i mentioned above arranged by one of its arrangers according to the order of the chapters of the book دعايم الاسلام i find', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 14, NULL, 'Question: What do you say of a man who has two houses, one in Ahmadabad and the other in Nahrwala, and who lives some days in Ahmadabad and some days in Nahrwala? May he pray in full before he enters the boundaries of the town in which his house stands?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question what do you say of a man who has two houses one in ahmadabad and the other in nahrwala and who lives some days in ahmadabad and some days in nahrwala may he pray in full before he enters the boundaries of the town in which his house stands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 15, NULL, 'Answer: If he stays for five prayer times with his wife or with his mahram relatives by lineage, he prays in full and fasts.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer if he stays for five prayer times with his wife or with his mahram relatives by lineage he prays in full and fasts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 16, NULL, 'Question: What do you say of what has come in the Book of Purity, that one whose journey is a pleasure outing does not shorten the prayer? Our master, what is meant by a journey of pleasure?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question what do you say of what has come in the book of purity that one whose journey is a pleasure outing does not shorten the prayer our master what is meant by a journey of pleasure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 17, NULL, 'Answer: If he has land of the extent that would ordinarily require the shortening of the prayer, and he wishes to walk in it for pleasure, he does not shorten the prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer if he has land of the extent that would ordinarily require the shortening of the prayer and he wishes to walk in it for pleasure he does not shorten the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 18, NULL, 'Question: What do you say of a man who prays the sunnah and the supererogatory prayer aboard a ship, and the ship turns? Must he turn with it or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question what do you say of a man who prays the sunnah and the supererogatory prayer aboard a ship and the ship turns must he turn with it or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 19, NULL, 'Answer: He ascertains the direction at the moment he enters into the prayer. If the ship turns, nothing is required of him. If he is able to turn with it and does so, that is better. If he is in an obligatory prayer, let him turn with it as much as he is able.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer he ascertains the direction at the moment he enters into the prayer if the ship turns nothing is required of him if he is able to turn with it and does so that is better if he is in an obligatory prayer let him turn with it as much as he is able', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 20, NULL, 'Question: What do you say of an owned man who is authorized to trade, or who is not authorized, and whose master sends him traveling in the month of Ramadan or at another time? Must he shorten the prayer and break the fast or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question what do you say of an owned man who is authorized to trade or who is not authorized and whose master sends him traveling in the month of ramadan or at another time must he shorten the prayer and break the fast or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 21, NULL, 'Answer: Yes, he shortens and he breaks the fast.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer yes he shortens and he breaks the fast', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 22, NULL, 'Question: What do you say of the divorced women in India, when someone goes out with them on a journey for trade or for anything else, in the month of Ramadan or at another time? Does he pray in full because of their company, and does he fast the month of Ramadan, or not? And likewise if someone goes out with the collector?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question what do you say of the divorced women in india when someone goes out with them on a journey for trade or for anything else in the month of ramadan or at another time does he pray in full because of their company and does he fast the month of ramadan or not and likewise if someone goes out with the collector', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 23, NULL, 'Answer: If their purpose was to go out with him, they pray in full. If they went out for something other than that, their ruling is the ruling of travelers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer if their purpose was to go out with him they pray in full if they went out for something other than that their ruling is the ruling of travelers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 24, NULL, 'Question: What do you say of this, that God has forbidden in the Quran thirteen degrees of kinship in marriage? Our master, with which of these degrees does one travel, and through which of them does one complete the prayer and the fast?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question what do you say of this that god has forbidden in the quran thirteen degrees of kinship in marriage our master with which of these degrees does one travel and through which of them does one complete the prayer and the fast', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 25, NULL, 'Answer: Everyone who is of the blood kin is one through whom the traveler completes his prayer and his fast by his stopping for the five prayers in the place where that relative is. A man completes through his wife, but this does not hold through his wife''s relatives, nor through those related by nursing.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer everyone who is of the blood kin is one through whom the traveler completes his prayer and his fast by his stopping for the five prayers in the place where that relative is a man completes through his wife but this does not hold through his wifes relatives nor through those related by nursing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 26, NULL, 'Question: And one who travels from Nahrwala to Ahmadabad and meets one of his relatives outside the town, does he pray in full or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question and one who travels from nahrwala to ahmadabad and meets one of his relatives outside the town does he pray in full or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 27, NULL, 'Answer: He does not pray in full until after he has entered the boundaries of the town in which his relative is.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer he does not pray in full until after he has entered the boundaries of the town in which his relative is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 28, NULL, 'From another place: whoever leaves his house for a journey and spends the night in the city, or in the house of a relative, or sits a day or more, does not shorten the prayer so long as he is in the city; and if he goes outside the city and spends the night or sits a day or more, he does not shorten the prayer. The master of the ship and the merchants all pray in full before one of them sets out from Cambay to Aden, and nothing further than this is required of them, nor is anything imposed upon him after he reaches his family.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'from another place whoever leaves his house for a journey and spends the night in the city or in the house of a relative or sits a day or more does not shorten the prayer so long as he is in the city and if he goes outside the city and spends the night or sits a day or more he does not shorten the prayer the master of the ship and the merchants all pray in full before one of them sets out from cambay to aden and nothing further than this is required of them nor is anything imposed upon him after he reaches his family', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 29, NULL, 'From another place: whoever travels, and the time of prayer comes while the clouds are heavy so that the qibla is not known, prays each obligatory prayer toward the four directions, and God, may He be exalted, is the more excusing toward His servant when He afflicts him. If he prayed and finished, and then the sun broke through and he knew the qibla and there still remained time for the prayer to be performed, he repeats the prayer. If a traveler alights in a place intending to reside there, and after two days or more a matter arises for him in which travel is unavoidable, he does not repeat.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'from another place whoever travels and the time of prayer comes while the clouds are heavy so that the qibla is not known prays each obligatory prayer toward the four directions and god may he be exalted is the more excusing toward his servant when he afflicts him if he prayed and finished and then the sun broke through and he knew the qibla and there still remained time for the prayer to be performed he repeats the prayer if a traveler alights in a place intending to reside there and after two days or more a matter arises for him in which travel is unavoidable he does not repeat', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 30, NULL, 'Whoever enters Mecca prays in full and does not shorten, even if he sits an hour or a day, because of the word of God:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'whoever enters mecca prays in full and does not shorten even if he sits an hour or a day because of the word of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 31, NULL, 'Al-Hajj: 25سَوَآءً ٱلْعَكِفُ فِيهِ وَٱلْبَادِ', '', 'سَوَآءً ٱلْعَكِفُ فِيهِ وَٱلْبَادِ', 'Al-Hajj: 25', 22, 25, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'al hajj 25سواء العكف فيه والباد', 'سواء العكف فيه والباد');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 32, NULL, 'The resident and the visitor stand equal.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'the resident and the visitor stand equal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 33, NULL, 'Our master Ismail ibn Sayyidina Hiba held that the prayer is completed in full only within the sanctuary of the House of God, and that in Mecca the Honored, the prayer is shortened.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'our master ismail ibn sayyidina hiba held that the prayer is completed in full only within the sanctuary of the house of god and that in mecca the honored the prayer is shortened', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 34, NULL, 'Question: What is your ruling on the shaykhs who have leave to travel among the villages — such as Shaykh Abdullah ibn Nuh, who moves among them visiting the believers, some villages being close together and others separated by a distance that requires shortening the prayer or more? Do they shorten the prayer and break the fast, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question what is your ruling on the shaykhs who have leave to travel among the villages such as shaykh abdullah ibn nuh who moves among them visiting the believers some villages being close together and others separated by a distance that requires shortening the prayer or more do they shorten the prayer and break the fast or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 35, NULL, 'Answer: Such a man is like the prince who makes his rounds within his emirate. He is not required to shorten the prayer or to break the fast. This answer comes from our master Idris.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer such a man is like the prince who makes his rounds within his emirate he is not required to shorten the prayer or to break the fast this answer comes from our master idris', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 36, NULL, 'Question: A traveler reaches his people before midday and stays with them until after midday of the second day. Does that count for him as a day and a night, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question a traveler reaches his people before midday and stays with them until after midday of the second day does that count for him as a day and a night or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 37, NULL, 'Answer: If he intended to remain until he prays on the second day, his prayer and his fast are complete.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer if he intended to remain until he prays on the second day his prayer and his fast are complete', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 38, NULL, 'Question: As for the relatives through whom a traveler completes his prayer and fast — are these the relatives God, mighty and majestic, mentions in the Quran where He says:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question as for the relatives through whom a traveler completes his prayer and fast are these the relatives god mighty and majestic mentions in the quran where he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 39, NULL, 'An-Nisa: 23حُرِّمَتْ عَلَيْكُمْ أُمَّهَتُكُمْ وَبَنَاتُكُمْ وَأَخَوَتُكُمْ وَعَمَّتُكُمْ وَخَلَتُكُمْ وَبَنَاتُ ٱلْأَخِ وَبَنَاتُ ٱلْأُخْتِ', '', 'حُرِّمَتْ عَلَيْكُمْ أُمَّهَتُكُمْ وَبَنَاتُكُمْ وَأَخَوَتُكُمْ وَعَمَّتُكُمْ وَخَلَتُكُمْ وَبَنَاتُ ٱلْأَخِ وَبَنَاتُ ٱلْأُخْتِ', 'An-Nisa: 23', 4, 23, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'an nisa 23حرمت عليكم امهتكم وبناتكم واخوتكم وعمتكم وخلتكم وبنات الاخ وبنات الاخت', 'حرمت عليكم امهتكم وبناتكم واخوتكم وعمتكم وخلتكم وبنات الاخ وبنات الاخت');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 40, NULL, 'Forbidden to you are your mothers, your daughters, your sisters, your paternal aunts, your maternal aunts, the daughters of the brother, and the daughters of the sister.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'forbidden to you are your mothers your daughters your sisters your paternal aunts your maternal aunts the daughters of the brother and the daughters of the sister', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 41, NULL, 'And what corresponds to these verses among men? Do mothers-in-law, stepdaughters, and relatives through nursing also complete the prayer and fast for the traveler, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'and what corresponds to these verses among men do mothers in law stepdaughters and relatives through nursing also complete the prayer and fast for the traveler or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 42, NULL, 'Answer: The relatives of lineage — both male and female — are those through whom the prayer and fast are completed. As for mothers-in-law and those mentioned alongside them, no.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer the relatives of lineage both male and female are those through whom the prayer and fast are completed as for mothers in law and those mentioned alongside them no', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 43, NULL, 'From another source: a man who enters the gate of a city or village after a journey during Ramadan before midday, but whose midday arrives before he enters his house, completes his prayer and his fast. Whoever travels and reaches a village where his wife''s kinswoman or kinsman resides shortens the prayer. But if the woman has come to her father''s house yet does not dwell there, and she has settled as a resident, or she is in the house of the mahram relative, and she is young and has not reached maturity, or she has given birth to that child, he prays in full.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'from another source a man who enters the gate of a city or village after a journey during ramadan before midday but whose midday arrives before he enters his house completes his prayer and his fast whoever travels and reaches a village where his wifes kinswoman or kinsman resides shortens the prayer but if the woman has come to her fathers house yet does not dwell there and she has settled as a resident or she is in the house of the mahram relative and she is young and has not reached maturity or she has given birth to that child he prays in full', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 44, NULL, 'Whoever travels less than two barids intending residence, and the time of prayer comes upon him on the road, prays in full and does not shorten. And whoever travels one barid intending to return, then returns to his family, and the time of prayer comes upon him on the road, prays in full and does not shorten.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'whoever travels less than two barids intending residence and the time of prayer comes upon him on the road prays in full and does not shorten and whoever travels one barid intending to return then returns to his family and the time of prayer comes upon him on the road prays in full and does not shorten', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 45, NULL, 'Question: It has come in the shariah that when a man arrives from a journey and enters the road of his quarter, he prays in full. Our master, are Kanbur and Sarangpur and the rest of the outskirts of Ahmadabad all considered one with it, each within its boundary?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question it has come in the shariah that when a man arrives from a journey and enters the road of his quarter he prays in full our master are kanbur and sarangpur and the rest of the outskirts of ahmadabad all considered one with it each within its boundary', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 46, NULL, 'Answer: It is not permitted for a traveler returning from his journey to pray in full until he has entered his own house. But if he enters one of the city gates and has not yet reached his dwelling, and fears the prayer will pass, he prays shortened. Likewise, if he leaves his house while still within the city and has not yet passed through any of its gates, and the prayer falls due while he is in the city, he prays shortened — as has been set out plainly and expressly in the book مُخْتَصَرُ الْآثَارِ, the composition of our master al-Numan, where it is stated: the traveler breaks the fast and shortens when he goes out from his dwelling and sets out on the journey, until he returns and enters his dwelling, if he is pressing on in the journey. But if one of his blood kin meets him at a distance from his town short of the travel distance, and that blood relative is resident in that town, that traveler completes his prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer it is not permitted for a traveler returning from his journey to pray in full until he has entered his own house but if he enters one of the city gates and has not yet reached his dwelling and fears the prayer will pass he prays shortened likewise if he leaves his house while still within the city and has not yet passed through any of its gates and the prayer falls due while he is in the city he prays shortened as has been set out plainly and expressly in the book مختصر الاثار the composition of our master al numan where it is stated the traveler breaks the fast and shortens when he goes out from his dwelling and sets out on the journey until he returns and enters his dwelling if he is pressing on in the journey but if one of his blood kin meets him at a distance from his town short of the travel distance and that blood relative is resident in that town that traveler completes his prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 47, NULL, 'Question: If a man intends to reside in a lodging for ten days, then leaves it after four or five days because an unavoidable need has arisen, what is his state regarding the prayers and fasts he has performed?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question if a man intends to reside in a lodging for ten days then leaves it after four or five days because an unavoidable need has arisen what is his state regarding the prayers and fasts he has performed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 48, NULL, 'Answer: So long as the intention of residence remains in his heart, he prays and fasts in full. When he intends to travel and depart from the place where he was residing, and sets out on the journey, he shortens from the moment that intention arises in his heart and he resolves upon it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer so long as the intention of residence remains in his heart he prays and fasts in full when he intends to travel and depart from the place where he was residing and sets out on the journey he shortens from the moment that intention arises in his heart and he resolves upon it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 49, NULL, 'Question: If the traveler leaves a lodging in which he was residing — before the ten days are complete — for another lodging nearby, with no more than a mile between them, does he need to intend a full ten days of residence in the new lodging, or does his earlier intention stand complete with the fulfillment of the first ten days?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question if the traveler leaves a lodging in which he was residing before the ten days are complete for another lodging nearby with no more than a mile between them does he need to intend a full ten days of residence in the new lodging or does his earlier intention stand complete with the fulfillment of the first ten days', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 50, NULL, 'Answer: So long as he intends to return to the place in which he first intended residence, he prays and fasts in full. But if he left it with the intention of traveling, he does not pray in full in the other place unless he renews his intention and resides there ten days.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer so long as he intends to return to the place in which he first intended residence he prays and fasts in full but if he left it with the intention of traveling he does not pray in full in the other place unless he renews his intention and resides there ten days', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 51, NULL, 'Question: If the traveler has family in a village and he enters its outskirts or a lodging within it, but has not yet come face to face with his family and relatives there, does he pray in full or shortened?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question if the traveler has family in a village and he enters its outskirts or a lodging within it but has not yet come face to face with his family and relatives there does he pray in full or shortened', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 52, NULL, 'Answer: He does not pray in full until he meets his blood relative, provided he is staying with that blood relative for five prayer times — unless he intends to reside ten days; for when he reaches the village and intends residence, he prays and fasts in full.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer he does not pray in full until he meets his blood relative provided he is staying with that blood relative for five prayer times unless he intends to reside ten days for when he reaches the village and intends residence he prays and fasts in full', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 53, NULL, 'These three answers are from our master Idris ibn Hasan.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'these three answers are from our master idris ibn hasan', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 54, NULL, 'It is said in the book مُخْتَصَرُ الْمُصَنَّفِ: if the traveler prays in full — whether forgetfully or deliberately — and time still remains, he must repeat the prayer; but if the time has passed, then no. Every prayer or prostration that becomes obligatory upon a person while he is on the ground cannot be discharged on horseback; and every prayer or prostration that becomes obligatory upon him while he is riding may be discharged on the ground. As for the Sacred Mosque, there is no shortening within it, the resident and the visitor being alike.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'it is said in the book مختصر المصنف if the traveler prays in full whether forgetfully or deliberately and time still remains he must repeat the prayer but if the time has passed then no every prayer or prostration that becomes obligatory upon a person while he is on the ground cannot be discharged on horseback and every prayer or prostration that becomes obligatory upon him while he is riding may be discharged on the ground as for the sacred mosque there is no shortening within it the resident and the visitor being alike', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 55, NULL, 'It is said in مُخْتَصَرُ الْآثَارِ: they said the traveler prays the sunnah and the supererogatory prayer; and if he is traveling by day and the journey presses him, he prays the obligatory prayer as two rakahs and defers the sunnah until he alights at night, then performs it together with the night prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'it is said in مختصر الاثار they said the traveler prays the sunnah and the supererogatory prayer and if he is traveling by day and the journey presses him he prays the obligatory prayer as two rakahs and defers the sunnah until he alights at night then performs it together with the night prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 56, NULL, 'From the same book: the barid is four farsakhs; the farsakh is three miles; the mile is three thousand cubits, which is a thousand even paces of a single leg — from where the right foot is lifted to where it is set down. If the place a man intends is one barid away, and he has neither family nor dwelling there, and he intends to return within less than ten days, he shortens and breaks the fast until he departs. The traveler breaks the fast and shortens when he goes out from his dwelling and sets out on the journey, until he returns and enters his dwelling, if he is pressing on in the journey. But if one of his blood kin meets him at a distance from his town short of the travel distance, and that blood relative is resident in that town, that traveler completes his prayers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'from the same book the barid is four farsakhs the farsakh is three miles the mile is three thousand cubits which is a thousand even paces of a single leg from where the right foot is lifted to where it is set down if the place a man intends is one barid away and he has neither family nor dwelling there and he intends to return within less than ten days he shortens and breaks the fast until he departs the traveler breaks the fast and shortens when he goes out from his dwelling and sets out on the journey until he returns and enters his dwelling if he is pressing on in the journey but if one of his blood kin meets him at a distance from his town short of the travel distance and that blood relative is resident in that town that traveler completes his prayers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 57, NULL, 'In مُخْتَصَرُ الْآثَارِ, I find the ruling that praying on the beaten highway is forbidden. And in تَأْوِيلُ الدَّعَائِمِ, concerning the supererogatory prayer of the Messenger of God upon his mount while he was heading toward Medina, it is recorded that he would gesture with his head for the prostration, the qibla being behind him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'in مختصر الاثار i find the ruling that praying on the beaten highway is forbidden and in تاويل الدعايم concerning the supererogatory prayer of the messenger of god upon his mount while he was heading toward medina it is recorded that he would gesture with his head for the prostration the qibla being behind him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 58, NULL, 'I also record here from the questions of certain of the hudud of the Indian island, with their answers from certain of the duat of the Yemeni island:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'i also record here from the questions of certain of the hudud of the indian island with their answers from certain of the duat of the yemeni island', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 59, NULL, 'The thirty-fifth question: concerning the traveler who follows a resident imam, then gives the tashahhud after two rakahs and salutes while the imam is still completing the prayer — is the traveler''s prayer sound or not? Answer: This is expressly stipulated: if he wishes, he may withdraw after two rakahs; and if he waits for the imam until he salutes, there is no harm in that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'the thirty fifth question concerning the traveler who follows a resident imam then gives the tashahhud after two rakahs and salutes while the imam is still completing the prayer is the travelers prayer sound or not answer this is expressly stipulated if he wishes he may withdraw after two rakahs and if he waits for the imam until he salutes there is no harm in that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 60, NULL, 'Also from that source: Question: What do you say of the imam who leads the people in prayer aboard a ship while seated — because the ship''s movement, or something else, makes standing impossible for some of them, while the rest are able? What is the state of their prayer? Answer: A dispensation has been granted for this on account of the ship, when they are unable. Whoever is able, however, should hasten and pray alone, standing.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'also from that source question what do you say of the imam who leads the people in prayer aboard a ship while seated because the ships movement or something else makes standing impossible for some of them while the rest are able what is the state of their prayer answer a dispensation has been granted for this on account of the ship when they are unable whoever is able however should hasten and pray alone standing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 61, NULL, 'Also from that source: Question: What do you say of the copy of the Quran and of other books — may they be used as a pillow in travel and at home, or not? For the common people narrate from the Prophet that he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'also from that source question what do you say of the copy of the quran and of other books may they be used as a pillow in travel and at home or not for the common people narrate from the prophet that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 62, NULL, 'Sayingلَا تَوَسَّدُوا بِالْقُرْآنِ', '', 'لَا تَوَسَّدُوا بِالْقُرْآنِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'sayingلا توسدوا بالقران', 'لا توسدوا بالقران');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 63, NULL, 'Do not use the Quran as a pillow.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'do not use the quran as a pillow', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 64, NULL, 'Answer: It ought to be raised upon the head, for the honor of the Quran and for good manners, but this is not obligatory.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer it ought to be raised upon the head for the honor of the quran and for good manners but this is not obligatory', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 65, NULL, 'Our master and mawlana Jafar ibn Sayyidina Sulayman said in غُرُفَاتُ الْجِنَانِ, in answer to questions from his servant, Sayyidina Ali ibn Sulayman, the author of this book, which he answered for him from the Yemeni island to the Indian island: And that which you asked about, saying, what do you say of one who shortens and prays behind a resident imam, and sits after his completion of the two rakahs while the imam rises to complete his prayer, and there is no one behind the imam except that one who shortens — does the imam say the takbir aloud in the remainder of his prayer or not? The answer is that nothing obliges the imam to say the takbir aloud; he should lower his voice with it. His raising the voice was for the sake of the one following him, so when no follower remains with him through his bowing, his prostration, and his rising, there is no sense in his raising the voice with it. Know that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'our master and mawlana jafar ibn sayyidina sulayman said in غرفات الجنان in answer to questions from his servant sayyidina ali ibn sulayman the author of this book which he answered for him from the yemeni island to the indian island and that which you asked about saying what do you say of one who shortens and prays behind a resident imam and sits after his completion of the two rakahs while the imam rises to complete his prayer and there is no one behind the imam except that one who shortens does the imam say the takbir aloud in the remainder of his prayer or not the answer is that nothing obliges the imam to say the takbir aloud he should lower his voice with it his raising the voice was for the sake of the one following him so when no follower remains with him through his bowing his prostration and his rising there is no sense in his raising the voice with it know that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 66, NULL, 'Our master Jafar ibn Mansur al-Yaman said in كِتَابُ الرِّضَاعِ الْبَاطِنِ: the sunnah of shortening applies to three prayers — the first, the afternoon, and the late evening. Each of these has four rakahs as its obligation, making twelve rakahs in total; the shortening from each four rakahs is two rakahs, so six rakahs in all are shortened.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'our master jafar ibn mansur al yaman said in كتاب الرضاع الباطن the sunnah of shortening applies to three prayers the first the afternoon and the late evening each of these has four rakahs as its obligation making twelve rakahs in total the shortening from each four rakahs is two rakahs so six rakahs in all are shortened', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 67, NULL, 'I also record from the questions of the most noble Shaykh Hasan ibn Nuh to our master Idris ibn Hasan, with his answers to him:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'i also record from the questions of the most noble shaykh hasan ibn nuh to our master idris ibn hasan with his answers to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 68, NULL, 'The eleventh question: may a man travel with his son''s wife, or with his wife''s mother, without a screen, and speak with them? And may he bury her and travel with her? And likewise, what is the state of kin by nursing? Answer: There is no harm in it under necessity, if none of her blood kin is to be found — and God knows best. Yet the better course is caution regarding these women in the matters mentioned, because of the saying of the Prophet:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'the eleventh question may a man travel with his sons wife or with his wifes mother without a screen and speak with them and may he bury her and travel with her and likewise what is the state of kin by nursing answer there is no harm in it under necessity if none of her blood kin is to be found and god knows best yet the better course is caution regarding these women in the matters mentioned because of the saying of the prophet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 69, NULL, 'Sayingاَلْمُتَّقِي مَنْ تَرَكَ مَا لَا بَأْسَ فِيهِ حَذَرًا أَنْ يَقَعَ فِي مَا بَأْسٌ فِيهِ', '', 'اَلْمُتَّقِي مَنْ تَرَكَ مَا لَا بَأْسَ فِيهِ حَذَرًا أَنْ يَقَعَ فِي مَا بَأْسٌ فِيهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'sayingالمتقي من ترك ما لا باس فيه حذرا ان يقع في ما باس فيه', 'المتقي من ترك ما لا باس فيه حذرا ان يقع في ما باس فيه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 70, NULL, 'The God-fearing man is the one who leaves what carries no harm, out of caution against falling into what does.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'the god fearing man is the one who leaves what carries no harm out of caution against falling into what does', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 71, NULL, 'This applies when one of their blood kin is available. When none is to be found, however, all of that is permitted — and God knows best what is right.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'this applies when one of their blood kin is available when none is to be found however all of that is permitted and god knows best what is right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 72, NULL, 'Our master Muhammad ibn Fahd stated in his treatise entitled لَاحِبَةُ سَبِيلِ الْهُدَى لِلْمُهْتَدِينَ:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'our master muhammad ibn fahd stated in his treatise entitled لاحبه سبيل الهدي للمهتدين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 73, NULL, 'The seventeenth question: You asked, my brother, about a traveler who covers the distance of a barid, resides there for eight days, and returns on the ninth. Does he shorten his prayer or pray it in full? Two rulings appear in the books of the purified shariah: first, that when a traveler covers a barid and returns within it, he shortens his prayer, because the outward and return journeys together make two barids for him; and second, that the limit of residence is ten days.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'the seventeenth question you asked my brother about a traveler who covers the distance of a barid resides there for eight days and returns on the ninth does he shorten his prayer or pray it in full two rulings appear in the books of the purified shariah first that when a traveler covers a barid and returns within it he shortens his prayer because the outward and return journeys together make two barids for him and second that the limit of residence is ten days', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 74, NULL, 'The answer — and may God the Glorified likewise grant you success toward what is right in it — is this: what is expressly stipulated in the books of the friends of God (عَلَيْهِمُ السَّلَامُ) regarding the residence mentioned is that its limit is ten days, just as you said, and neither less than that nor short of it. The better course for one who travels a barid and intends to return after some days is to commit to a stay of ten days and pray in full. Then, should it become clear to him that he wishes to return before those ten days are complete, he may do so; he is not obliged to complete the residence — I mean the ten days mentioned — as the texts in the books of the friends of God (عَلَيْهِمُ السَّلَامُ) make plain. His praying in full, as described, is not invalidated.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'the answer and may god the glorified likewise grant you success toward what is right in it is this what is expressly stipulated in the books of the friends of god عليهم السلام regarding the residence mentioned is that its limit is ten days just as you said and neither less than that nor short of it the better course for one who travels a barid and intends to return after some days is to commit to a stay of ten days and pray in full then should it become clear to him that he wishes to return before those ten days are complete he may do so he is not obliged to complete the residence i mean the ten days mentioned as the texts in the books of the friends of god عليهم السلام make plain his praying in full as described is not invalidated', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 75, NULL, 'You also asked about the prayer of a traveler who leads residents as imam. He said that this is permitted when the imam is among the men of excellence: he gives the salutation after two rakahs, and those following him rise and complete their prayers. This is particular to the people of the high ranks, and does not extend to others among all the hudud.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'you also asked about the prayer of a traveler who leads residents as imam he said that this is permitted when the imam is among the men of excellence he gives the salutation after two rakahs and those following him rise and complete their prayers this is particular to the people of the high ranks and does not extend to others among all the hudud', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 76, NULL, 'You also asked about the prayer of one who has performed tayammum leading those who have performed the ablution. That is permitted for the people of the high ranks, as is established by what has been recorded concerning our master and mawlana, the Dai of the age, Jafar ibn Sayyidina Sulayman. When he was in the Yemeni island and descended from the fortress of Tayba to the land of Haraz, he purified himself for the noon prayer of one of his days as others purify themselves — but that did not suit him, because of the scrupulous care he took in this and in other matters, and scrupulous care in purification with the complete purification was not available to him. When he finished, he performed tayammum where no one perceived it, then led the people in congregation. Then he said to certain of the most noble hudud of his dawa: thus has the dispensation come for the prayer of one who has performed tayammum leading those who have performed the ablution, when some weighty matter makes it necessary for the good of the guiding dawa and the raising of its standard, just as there is the dispensation for the prayer of the traveler leading residents.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'you also asked about the prayer of one who has performed tayammum leading those who have performed the ablution that is permitted for the people of the high ranks as is established by what has been recorded concerning our master and mawlana the dai of the age jafar ibn sayyidina sulayman when he was in the yemeni island and descended from the fortress of tayba to the land of haraz he purified himself for the noon prayer of one of his days as others purify themselves but that did not suit him because of the scrupulous care he took in this and in other matters and scrupulous care in purification with the complete purification was not available to him when he finished he performed tayammum where no one perceived it then led the people in congregation then he said to certain of the most noble hudud of his dawa thus has the dispensation come for the prayer of one who has performed tayammum leading those who have performed the ablution when some weighty matter makes it necessary for the good of the guiding dawa and the raising of its standard just as there is the dispensation for the prayer of the traveler leading residents', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 77, NULL, 'The book أُنْسُ الْأَفْئِدَةِ الْمُنِيبَةِ records that he — meaning Amir al-Muminin (ع) — ruled that six categories of people do not shorten their prayers or their fasts:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'the book انس الافيده المنيبه records that he meaning amir al muminin ع ruled that six categories of people do not shorten their prayers or their fasts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 78, NULL, 'collectors who travel a circuit in their collecting; merchants who travel from market to market in their trade; princes who travel a circuit within their emirate; men who go out in pursuit of game; shepherds who seek out places where rain has fallen and the trees have sprouted; warriors who cut the road.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'collectors who travel a circuit in their collecting merchants who travel from market to market in their trade princes who travel a circuit within their emirate men who go out in pursuit of game shepherds who seek out places where rain has fallen and the trees have sprouted warriors who cut the road', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 79, NULL, 'The book of the question from the most noble Shaykh Shamun ibn Muhammad Ghuri al-Hindi, with the answer from our master Badr al-Din Hasan ibn Idris, records the following:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'the book of the question from the most noble shaykh shamun ibn muhammad ghuri al hindi with the answer from our master badr al din hasan ibn idris records the following', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 80, NULL, 'Question: What do you say regarding this matter? Certain shaykhs raised a question about the women who are mahram: with which of them does one travel, and with which of them does one not shorten the prayer by stopping with her for the five prayers? The answer given was that when the person is of blood kin, the traveler completes the prayer and the fast by stopping with that person for the five prayers; and that a man completes his prayer through his wife, but that this does not hold through the wife''s relatives nor through kinship by nursing. So make clear to us, our master, in detail: with which of these women does one travel and touch with one''s hand or otherwise, and with which of them does one not shorten the prayer? And explain the detail of the ruling that a man completes his prayer through his wife — for on this point the feet of the deniers have slipped, and deliverance comes from you, O best of those who consider and reflect upon the affairs of religion.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question what do you say regarding this matter certain shaykhs raised a question about the women who are mahram with which of them does one travel and with which of them does one not shorten the prayer by stopping with her for the five prayers the answer given was that when the person is of blood kin the traveler completes the prayer and the fast by stopping with that person for the five prayers and that a man completes his prayer through his wife but that this does not hold through the wifes relatives nor through kinship by nursing so make clear to us our master in detail with which of these women does one travel and touch with ones hand or otherwise and with which of them does one not shorten the prayer and explain the detail of the ruling that a man completes his prayer through his wife for on this point the feet of the deniers have slipped and deliverance comes from you o best of those who consider and reflect upon the affairs of religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 81, NULL, 'Answer: He does not pray in full except when one of his mahrams is stopping in a place and the traveler stops with that person for the five prayer times — then he prays in full. Likewise, he prays in full through his wife if she is resident, when he stops with her for the five prayer times.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer he does not pray in full except when one of his mahrams is stopping in a place and the traveler stops with that person for the five prayer times then he prays in full likewise he prays in full through his wife if she is resident when he stops with her for the five prayer times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 82, NULL, 'The questions from certain shaykhs of India, with the answers from certain of our masters, the duat of Yemen, record the following:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'the questions from certain shaykhs of india with the answers from certain of our masters the duat of yemen record the following', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 83, NULL, 'Question: What do you say — does the resident lead the travelers in prayer, or does the traveler lead the residents?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question what do you say does the resident lead the travelers in prayer or does the traveler lead the residents', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 84, NULL, 'Answer: If the traveler is more excellent than the residents, he leads them and withdraws after two rakahs, and they rise and complete the prayer. Likewise, if the resident is more excellent than the travelers, he leads them, and they withdraw after two rakahs.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer if the traveler is more excellent than the residents he leads them and withdraws after two rakahs and they rise and complete the prayer likewise if the resident is more excellent than the travelers he leads them and they withdraw after two rakahs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 86, NULL, 'The book of questions and answers mentioned above — arranged by one of its arrangers according to the order of the chapters of the book دَعَائِمُ الْإِسْلَامِ — records the following:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'the book of questions and answers mentioned above arranged by one of its arrangers according to the order of the chapters of the book دعايم الاسلام records the following', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 87, NULL, 'Question: What do you say of the sick man who is unable to pray standing, nor seated cross-legged with the bowing and prostration? How should he proceed?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'question what do you say of the sick man who is unable to pray standing nor seated cross legged with the bowing and prostration how should he proceed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 88, NULL, 'Answer: He prays seated, or cross-legged with the bowing and prostration, for God is the more excusing toward His servant when He afflicts him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'answer he prays seated or cross legged with the bowing and prostration for god is the more excusing toward his servant when he afflicts him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 89, NULL, 'The Book of Purity states: if he is not able to gesture with his head, he gestures with his eyes; and if he is not able to do that, he gestures with his heart.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'the book of purity states if he is not able to gesture with his head he gestures with his eyes and if he is not able to do that he gestures with his heart', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 90, NULL, 'مُخْتَصَرُ الْآثَارِ states: if the sick man is not able to pray anything but the obligatory prayer, he prays it; then when he recovers, he may make up, if he wishes, what he omitted of the sunnah or the supererogatory prayer — and in that there is merit and reward, though making it up is not obligatory as the making up of the obligatory prayer is obligatory.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'مختصر الاثار states if the sick man is not able to pray anything but the obligatory prayer he prays it then when he recovers he may make up if he wishes what he omitted of the sunnah or the supererogatory prayer and in that there is merit and reward though making it up is not obligatory as the making up of the obligatory prayer is obligatory', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'children, travelers, and the sick', '23. Children, Travelers, and the Sick', 91, NULL, 'مُخْتَصَرُ الْمُصَنَّفِ states: whoever drinks something by which he treats himself, and it brings about the loss of his reason, must repeat the prayers that passed him by while he was in that state. The same applies if he does something to himself that brings about the loss of his reason — and it makes no difference whether, in what he did, he was obedient to God, the Glorified and Exalted, or disobedient.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 23 children travelers and the sick', 'مختصر المصنف states whoever drinks something by which he treats himself and it brings about the loss of his reason must repeat the prayers that passed him by while he was in that state the same applies if he does something to himself that brings about the loss of his reason and it makes no difference whether in what he did he was obedient to god the glorified and exalted or disobedient', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 0, NULL, 'I turn now to the prayer of the eclipse. What follows is drawn from the book of questions and answers mentioned earlier, which one of its arrangers organized according to the chapters of كِتَابُ دَعَائِمِ الْإِسْلَامِ (The Pillars of Islam).', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'i turn now to the prayer of the eclipse what follows is drawn from the book of questions and answers mentioned earlier which one of its arrangers organized according to the chapters of كتاب دعايم الاسلام the pillars of islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 1, NULL, 'Question: Concerning the eclipse that occurred in the year eight hundred and thirty-seven, in the month of Dhu al-Qadah: it began on Monday, two hours after the sun had passed its height, and the solar eclipse fell out in accordance with the reckoning of the table. Yet the letters of the Brethren of Purity, in the treatise on astronomy, state that a solar eclipse occurs only at the end of the month, and the cause of this is given there. This has happened repeatedly in years before this one. We were fasting during the first days of the blessed month of Ramadan when an eclipse occurred, and the believers were left perplexed about how the matter is to be answered.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question concerning the eclipse that occurred in the year eight hundred and thirty seven in the month of dhu al qadah it began on monday two hours after the sun had passed its height and the solar eclipse fell out in accordance with the reckoning of the table yet the letters of the brethren of purity in the treatise on astronomy state that a solar eclipse occurs only at the end of the month and the cause of this is given there this has happened repeatedly in years before this one we were fasting during the first days of the blessed month of ramadan when an eclipse occurred and the believers were left perplexed about how the matter is to be answered', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 2, NULL, 'Answer: A statement has come from Mawlana, the author of the letters (ع), in summary, and the pure Imams and the ranks that follow them have explained it. They said that the eclipse of the moon occurs at the dawn of the fifteenth and at the dawn of the sixteenth, while the eclipse of the sun may occur at the beginning of the month or at its end. The matter is in the hand of God.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'answer a statement has come from mawlana the author of the letters ع in summary and the pure imams and the ranks that follow them have explained it they said that the eclipse of the moon occurs at the dawn of the fifteenth and at the dawn of the sixteenth while the eclipse of the sun may occur at the beginning of the month or at its end the matter is in the hand of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 3, NULL, 'Sayingوَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ', '', 'وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'sayingولا حول ولا قوه الا بالله العلي العظيم', 'ولا حول ولا قوه الا بالله العلي العظيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 4, NULL, 'There is no might and no power except with God, the Most High, the Great.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'there is no might and no power except with god the most high the great', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 5, NULL, 'Question: One who joins the imam at the third rakah counts it as the beginning of his own prayer. He bows with the imam''s bowing and prostrates with his prostration. When the imam rises from the prostration, he rises with him and prays the five bowings with him and prostrates with him. When the imam makes the testimony, the latecomer sits poised and ready. When the imam gives the salutation, the latecomer rises and completes what remains upon him of the bowings; he recites the qunut, bows, prostrates, makes the testimony, and gives the salutation. He does not count the first two prostrations he performed with the imam, just as is done by one who catches only the prostration at the end of the obligatory prayers with the imam.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question one who joins the imam at the third rakah counts it as the beginning of his own prayer he bows with the imams bowing and prostrates with his prostration when the imam rises from the prostration he rises with him and prays the five bowings with him and prostrates with him when the imam makes the testimony the latecomer sits poised and ready when the imam gives the salutation the latecomer rises and completes what remains upon him of the bowings he recites the qunut bows prostrates makes the testimony and gives the salutation he does not count the first two prostrations he performed with the imam just as is done by one who catches only the prostration at the end of the obligatory prayers with the imam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 6, NULL, 'Another case: whoever misses the eclipse prayer with the imam counts his joining as the beginning of his own prayer. If he comes before the first two prostrations, he prays what remains with the imam, and whenever the imam prostrates in the first two prostrations, he prostrates with him — for it has been mentioned that one who leaves these is counted as unable. When the imam rises, the latecomer prays the five bowings with him and prostrates and rises with the imam; when the imam prostrates, he prostrates with him; when the imam sits, the latecomer sits poised and ready; and when the imam gives the salutation, the latecomer rises and prays what remains upon him of the bowings, then prostrates, makes the testimony, and gives the salutation. He does not count the first two prostrations in which he prostrated with the imam, just as is done by one who has been outstripped in the prayer and catches only the prostration and the obligatory portions.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'another case whoever misses the eclipse prayer with the imam counts his joining as the beginning of his own prayer if he comes before the first two prostrations he prays what remains with the imam and whenever the imam prostrates in the first two prostrations he prostrates with him for it has been mentioned that one who leaves these is counted as unable when the imam rises the latecomer prays the five bowings with him and prostrates and rises with the imam when the imam prostrates he prostrates with him when the imam sits the latecomer sits poised and ready and when the imam gives the salutation the latecomer rises and prays what remains upon him of the bowings then prostrates makes the testimony and gives the salutation he does not count the first two prostrations in which he prostrated with the imam just as is done by one who has been outstripped in the prayer and catches only the prostration and the obligatory portions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 7, NULL, 'It is said in the book of purity: the eclipse prayer is not to be prayed until the eclipse appears and is seen. It is not prayed on the word of an astrologer or of anyone else that it is occurring, and if a veil of cloud or anything else intervenes, it is not prayed until the eclipse appears and is seen with the eye.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'it is said in the book of purity the eclipse prayer is not to be prayed until the eclipse appears and is seen it is not prayed on the word of an astrologer or of anyone else that it is occurring and if a veil of cloud or anything else intervenes it is not prayed until the eclipse appears and is seen with the eye', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 8, NULL, 'I turn now to the prayer of fear, and again from that same book of questions and answers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'i turn now to the prayer of fear and again from that same book of questions and answers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 9, NULL, 'Question: What do you say concerning what has come in the book of purity — that when there is the crossing of swords, close fighting, and the thrusting of spears, they make their prayers into takbir, so that they say one takbir in the place of each bowing? O our master, do they shorten the takbir as they shorten in the prayer of fear? Answer: He shortens in the takbir as shortening has been made obligatory in it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question what do you say concerning what has come in the book of purity that when there is the crossing of swords close fighting and the thrusting of spears they make their prayers into takbir so that they say one takbir in the place of each bowing o our master do they shorten the takbir as they shorten in the prayer of fear answer he shortens in the takbir as shortening has been made obligatory in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 10, NULL, 'It is said in the book مُخْتَصَرُ الْمُصَنَّفِ: if the imam prays the prayer of fear with three men while three men stand guard for him, that is permitted. If their number is fewer than three, it is not recommended for them to pray the prayer of fear, since the word "party" does not apply to fewer than three. And if the eclipse prayer and a funeral prayer come together for the imam along with fear, he prays over the funeral, and prays the eclipse prayer and the prayer of fear.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'it is said in the book مختصر المصنف if the imam prays the prayer of fear with three men while three men stand guard for him that is permitted if their number is fewer than three it is not recommended for them to pray the prayer of fear since the word party does not apply to fewer than three and if the eclipse prayer and a funeral prayer come together for the imam along with fear he prays over the funeral and prays the eclipse prayer and the prayer of fear', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 11, NULL, 'I turn now to the prayer for rain. It is said in كِتَابُ الْاِقْتِصَارِ, and in الأخبار, and in اَلْمُنْتَخَبَةُ: then he faced the people and said one hundred takbirs; then he turned to his right and glorified God one hundred times; then he turned to his left and declared the oneness of God one hundred times, raising his voice in all of this. Then he faced the people and praised God with one hundred utterances of praise and magnification, and extolled Him. It is said in the book of purity: he delivered two sermons in the same manner as is done for the two feasts; then he descended and departed, and the people departed. He delivers the sermon leaning upon an Arabian bow, if he finds one, as the Messenger of God (ع) did. And from the same source: if they go out on a day other than Monday, there is no harm in it. It is said in مُخْتَصَرُ الْمُصَنَّفِ: whoever delivers the sermon before the prayer must pray and then deliver the sermon.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'i turn now to the prayer for rain it is said in كتاب الاقتصار and in الاخبار and in المنتخبه then he faced the people and said one hundred takbirs then he turned to his right and glorified god one hundred times then he turned to his left and declared the oneness of god one hundred times raising his voice in all of this then he faced the people and praised god with one hundred utterances of praise and magnification and extolled him it is said in the book of purity he delivered two sermons in the same manner as is done for the two feasts then he descended and departed and the people departed he delivers the sermon leaning upon an arabian bow if he finds one as the messenger of god ع did and from the same source if they go out on a day other than monday there is no harm in it it is said in مختصر المصنف whoever delivers the sermon before the prayer must pray and then deliver the sermon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 12, NULL, 'I turn now to the witr prayer, the two bowings of dawn, and the qunut, and again from that book of questions and answers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'i turn now to the witr prayer the two bowings of dawn and the qunut and again from that book of questions and answers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 13, NULL, 'Question: Concerning a man who is heedless of the qunut. Answer: In the witr he must repeat, and in the dawn prayer he performs the two prostrations of forgetfulness.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question concerning a man who is heedless of the qunut answer in the witr he must repeat and in the dawn prayer he performs the two prostrations of forgetfulness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 14, NULL, 'Question: What do you say concerning a man who prays the witr and forgets the qunut, then remembers it after he has bowed or prostrated or sat? Does he repeat the witr, or does he perform the two prostrations of forgetfulness? Answer: The qunut is a supplication that is not to be abandoned deliberately. Whoever forgets it need not repeat, and there are no two prostrations of forgetfulness in the sunnah prayers. Whoever abandons it in the witr deliberately must repeat. The least of the qunut is three glorifications or three takbirs.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question what do you say concerning a man who prays the witr and forgets the qunut then remembers it after he has bowed or prostrated or sat does he repeat the witr or does he perform the two prostrations of forgetfulness answer the qunut is a supplication that is not to be abandoned deliberately whoever forgets it need not repeat and there are no two prostrations of forgetfulness in the sunnah prayers whoever abandons it in the witr deliberately must repeat the least of the qunut is three glorifications or three takbirs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 15, NULL, 'Question: When is the qunut recited in the witr? Answer: The qunut is recited after the worshipper says:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question when is the qunut recited in the witr answer the qunut is recited after the worshipper says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 16, NULL, 'Sayingرَبَّنَا لَكَ الْحَمْدُ', '', 'رَبَّنَا لَكَ الْحَمْدُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'sayingربنا لك الحمد', 'ربنا لك الحمد');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 17, NULL, 'Our Lord, to You belongs all praise.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'our lord to you belongs all praise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 18, NULL, 'Let that be verified. And whoever prays the shaf prayer of two bowings and then occupies himself with something until dawn breaks repeats the shaf as a make-up. If he has prayed three bowings and only the sitting remains until dawn breaks, he does not repeat the three, but makes up the sitting with the intention of a make-up.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'let that be verified and whoever prays the shaf prayer of two bowings and then occupies himself with something until dawn breaks repeats the shaf as a make up if he has prayed three bowings and only the sitting remains until dawn breaks he does not repeat the three but makes up the sitting with the intention of a make up', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 19, NULL, 'Question: Concerning the worshipper who gives the salutation after the first bowing of the witr — is speech permitted to him, or does he join the consecration to the consecration? For it has been said that the prayer of one seated is half the prayer of one standing, and it has been said in another place:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question concerning the worshipper who gives the salutation after the first bowing of the witr is speech permitted to him or does he join the consecration to the consecration for it has been said that the prayer of one seated is half the prayer of one standing and it has been said in another place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 20, NULL, 'Sayingأَنَّ الصَّلَاةَ تَحْرِيمُهَا تَكْبِيرُهَا وَتَحْلِيلُهَا تَسْلِيمُهَا', '', 'أَنَّ الصَّلَاةَ تَحْرِيمُهَا تَكْبِيرُهَا وَتَحْلِيلُهَا تَسْلِيمُهَا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'sayingان الصلاه تحريمها تكبيرها وتحليلها تسليمها', 'ان الصلاه تحريمها تكبيرها وتحليلها تسليمها');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 21, NULL, 'الصَّلَاةُ تَحْرِيمُهَا التَّكْبِيرُ وَتَحْلِيلُهَا التَّسْلِيمُ — the prayer: its consecration is its takbir, and its release is its salutation. By which of the two, then, does one act? Answer: our master the Judge al-Numan, may God raise his sanctity, has mentioned in اَلْمُنْتَخَبَةُ أَنْ:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'الصلاه تحريمها التكبير وتحليلها التسليم the prayer its consecration is its takbir and its release is its salutation by which of the two then does one act answer our master the judge al numan may god raise his sanctity has mentioned in المنتخبه ان', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 22, NULL, 'Sayingوَالْوِتْرُ قَدْ يُفْصَلُ بِالسَّلَامِ مِنْ غَيْرِ أَعْمَالٍ وَلَا كَلَامٍ', '', 'وَالْوِتْرُ قَدْ يُفْصَلُ بِالسَّلَامِ مِنْ غَيْرِ أَعْمَالٍ وَلَا كَلَامٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'sayingوالوتر قد يفصل بالسلام من غير اعمال ولا كلام', 'والوتر قد يفصل بالسلام من غير اعمال ولا كلام');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 23, NULL, 'The witr may be divided by the salutation, without actions and without speech. And if one is compelled to speak, there is no harm in it so long as the talk is not prolonged.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'the witr may be divided by the salutation without actions and without speech and if one is compelled to speak there is no harm in it so long as the talk is not prolonged', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 24, NULL, 'Question: Is it permissible to perform the shaf and the witr in their proper time during the first dawn — which the Arabs call ذَنَبُ السِّرْحَانِ — before the second dawn spreads across the sky, or not? And does the dispensation extend to praying the two bowings of the sunnah of dawn? Answer: The shaf prayer and the witr are performed in their proper time so long as the dawn has not spread; this is established.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question is it permissible to perform the shaf and the witr in their proper time during the first dawn which the arabs call ذنب السرحان before the second dawn spreads across the sky or not and does the dispensation extend to praying the two bowings of the sunnah of dawn answer the shaf prayer and the witr are performed in their proper time so long as the dawn has not spread this is established', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 25, NULL, 'Whoever prays the dawn prayer with the imam and bows before the imam, then raises his head and bows a second time with the imam, his prayer is valid, because his prayer follows the prayer of the imam. But if he prayed alone, he repeats the prayer. Whoever prays the witr and forgets the qunut performs the two prostrations of forgetfulness after the salutation.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'whoever prays the dawn prayer with the imam and bows before the imam then raises his head and bows a second time with the imam his prayer is valid because his prayer follows the prayer of the imam but if he prayed alone he repeats the prayer whoever prays the witr and forgets the qunut performs the two prostrations of forgetfulness after the salutation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 26, NULL, 'Question: If a man prays the shaf, then enters the mosque and prays the greeting of the mosque during the time of the shaf, does he repeat the shaf or not? Answer: He repeats the shaf, because it is not for him to pray after it until dawn breaks. When dawn has broken he prays the greeting, then prays the dawn prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question if a man prays the shaf then enters the mosque and prays the greeting of the mosque during the time of the shaf does he repeat the shaf or not answer he repeats the shaf because it is not for him to pray after it until dawn breaks when dawn has broken he prays the greeting then prays the dawn prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 27, NULL, 'It is said in مَعَالِمُ الدِّينِ: the witr prayer is obligatory, and there is no dispensation in abandoning it; it is among the appendages of the obligatory prayers, even though it is a sunnah.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'it is said in معالم الدين the witr prayer is obligatory and there is no dispensation in abandoning it it is among the appendages of the obligatory prayers even though it is a sunnah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 28, NULL, 'It is said in the book of purity: he recites in the first bowing the opening of the Book and the surah:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'it is said in the book of purity he recites in the first bowing the opening of the book and the surah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 29, NULL, 'Al-Falaq: 1قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ', '', 'قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ', 'Al-Falaq: 1', 113, 1, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'al falaq 1قل اعوذ برب الفلق', 'قل اعوذ برب الفلق');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 30, NULL, 'In the second bowing, I recite the opening of the Book and the surah:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'in the second bowing i recite the opening of the book and the surah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 31, NULL, 'An-Nas: 1قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ', '', 'قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ', 'An-Nas: 1', 114, 1, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'an nas 1قل اعوذ برب الناس', 'قل اعوذ برب الناس');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 32, NULL, 'Say: I seek refuge with the Lord of mankind.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'say i seek refuge with the lord of mankind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 33, NULL, 'I then make the testimony and give the salutation. These two bowings are part of the witr. I sit cross-legged throughout both of them, as already described, spreading my palms upon my thighs with my fingertips upon my knees, and I recite. When I have finished the recitation, I bow and place the inner surfaces of my palms upon my knees, still seated cross-legged. When I raise my head from the bowing, I draw my right foot back behind me, set my feet upright, prostrate, and then sit for the testimony as one sits in prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'i then make the testimony and give the salutation these two bowings are part of the witr i sit cross legged throughout both of them as already described spreading my palms upon my thighs with my fingertips upon my knees and i recite when i have finished the recitation i bow and place the inner surfaces of my palms upon my knees still seated cross legged when i raise my head from the bowing i draw my right foot back behind me set my feet upright prostrate and then sit for the testimony as one sits in prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 34, NULL, 'Our master Muhammad ibn Fahd, may God raise his sanctity, said in his noble treatise, which he named لَاحِبَةُ سَبِيلِ الْهُدَى لِلْمُهْتَدِينَ, in the twenty-second question: you also asked about one who prays the shaf and the witr, then sits afterward for as long as is easy for him, then rises and prays the dawn — its sunnah and its obligation — and it afterward becomes clear to him that he was still in the night and the dawn had not yet come. What is his condition in that prayer? The answer is that his shaf and his witr stand confirmed, and he must repeat the dawn, both its sunnah and its obligation, unless the dawn was close upon him, in which case the sunnah prayer also stands confirmed for him. This is because it has come in the books of the friends of God (عَلَيْهِمُ السَّلَامُ) that it is permissible to pray it before dawn, on account of the noble meaning beneath this that permits it. So know this.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'our master muhammad ibn fahd may god raise his sanctity said in his noble treatise which he named لاحبه سبيل الهدي للمهتدين in the twenty second question you also asked about one who prays the shaf and the witr then sits afterward for as long as is easy for him then rises and prays the dawn its sunnah and its obligation and it afterward becomes clear to him that he was still in the night and the dawn had not yet come what is his condition in that prayer the answer is that his shaf and his witr stand confirmed and he must repeat the dawn both its sunnah and its obligation unless the dawn was close upon him in which case the sunnah prayer also stands confirmed for him this is because it has come in the books of the friends of god عليهم السلام that it is permissible to pray it before dawn on account of the noble meaning beneath this that permits it so know this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 35, NULL, 'The Commander of the Faithful, Ali ibn Abi Talib (ع), said in his four hundred points of conduct:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'the commander of the faithful ali ibn abi talib ع said in his four hundred points of conduct', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 36, NULL, 'Sayingتَوَكَّلُوا عَلَى اللَّهِ عِنْدَ رَكْعَتَيِ الْفَجْرِ بَعْدَ فَرَاغِكُمْ مِنْهَا فَفِيهَا تُعْطَى الرَّغَايِبُ', '', 'تَوَكَّلُوا عَلَى اللَّهِ عِنْدَ رَكْعَتَيِ الْفَجْرِ بَعْدَ فَرَاغِكُمْ مِنْهَا فَفِيهَا تُعْطَى الرَّغَايِبُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'sayingتوكلوا علي الله عند ركعتي الفجر بعد فراغكم منها ففيها تعطي الرغايب', 'توكلوا علي الله عند ركعتي الفجر بعد فراغكم منها ففيها تعطي الرغايب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 37, NULL, 'Place your trust in God at the two bowings of dawn after you have finished them, for in them the things most desired are granted.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'place your trust in god at the two bowings of dawn after you have finished them for in them the things most desired are granted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 38, NULL, 'Our master and Mawlana Sharaf al-Din Jafar, son of our master Sulayman — may God raise their sanctity in the chambers of the Garden — set down in his book الْحَدَائِقُ الْأَنِيقَةُ النَّفْسَانِيَّةُ الْمُشْتَمِلَةُ عَلَى الْجَوَابَاتِ الْبُرْهَانِيَّةِ, drawing from the answers of our master Daud ibn Ajab to his son in religion, Sulayman ibn Hasan, the following of his chosen words: as for your question about one who owes a make-up of the witr — is it permissible for him to pray voluntary prayers or not — and about one who owes a make-up of the sunnah prayers: it is permissible, though it is better that he give precedence to the witr make-up before everything else.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'our master and mawlana sharaf al din jafar son of our master sulayman may god raise their sanctity in the chambers of the garden set down in his book الحدايق الانيقه النفسانيه المشتمله علي الجوابات البرهانيه drawing from the answers of our master daud ibn ajab to his son in religion sulayman ibn hasan the following of his chosen words as for your question about one who owes a make up of the witr is it permissible for him to pray voluntary prayers or not and about one who owes a make up of the sunnah prayers it is permissible though it is better that he give precedence to the witr make up before everything else', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 39, NULL, 'I turn now to the sunnah and the voluntary prayers, again from that book of questions and answers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'i turn now to the sunnah and the voluntary prayers again from that book of questions and answers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 40, NULL, 'Question: What do you say concerning the prayer of opening, the prayer of glorification, and the prayer of night vigil? Has anything fixed come down regarding their recitation, and what ought to be recited in them of the surahs?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question what do you say concerning the prayer of opening the prayer of glorification and the prayer of night vigil has anything fixed come down regarding their recitation and what ought to be recited in them of the surahs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 41, NULL, 'Answer: Nothing fixed has come down. They are like the sunnah and voluntary prayers: one recites in them whatever one wishes.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'answer nothing fixed has come down they are like the sunnah and voluntary prayers one recites in them whatever one wishes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 42, NULL, 'Question: What do you say concerning the witr prayer and the prayer of the two feasts? Is it permissible for one who has not memorized the appointed portion of the Quran to recite something else in them?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question what do you say concerning the witr prayer and the prayer of the two feasts is it permissible for one who has not memorized the appointed portion of the quran to recite something else in them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 43, NULL, 'Answer: If he has not memorized it, he recites what is easy for him and does not abandon the prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'answer if he has not memorized it he recites what is easy for him and does not abandon the prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 44, NULL, 'Question: What do you say concerning the supplications of the night vigil? Is it permissible for one who has not memorized them to intend a voluntary prayer?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question what do you say concerning the supplications of the night vigil is it permissible for one who has not memorized them to intend a voluntary prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 45, NULL, 'Answer: He intends the prayer of the night vigil and supplicates with the supplication if he has memorized it; otherwise he supplicates with what is easy for him, while still intending the prayer of the night vigil. It is twelve bowings, and it has two times: one is between the sunset prayer and the evening prayer, in which a person prays using the short surahs of the detailed portion.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'answer he intends the prayer of the night vigil and supplicates with the supplication if he has memorized it otherwise he supplicates with what is easy for him while still intending the prayer of the night vigil it is twelve bowings and it has two times one is between the sunset prayer and the evening prayer in which a person prays using the short surahs of the detailed portion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 46, NULL, 'Question: What do you say concerning the tarawih prayer, when the believers pray behind the imam for the sake of protective concealment with the intention of a voluntary prayer, while the imam recites the Quran from its beginning to its end — a practice not followed in the obligatory prayers, and particularly not in the witr, the sunnah of dawn, and the greeting of the mosque?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question what do you say concerning the tarawih prayer when the believers pray behind the imam for the sake of protective concealment with the intention of a voluntary prayer while the imam recites the quran from its beginning to its end a practice not followed in the obligatory prayers and particularly not in the witr the sunnah of dawn and the greeting of the mosque', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 47, NULL, 'Answer: There is no harm in it for the sake of protective concealment, but they do not follow him as a leader.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'answer there is no harm in it for the sake of protective concealment but they do not follow him as a leader', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 48, NULL, 'Question: It is mentioned in كِتَابُ الشَّوَاهِدِ وَالْبَيَانِ that the worshipper prays the noon prayer as ten bowings, the afternoon prayer as eight bowings, the sunset prayer as five bowings, and the evening prayer as ten bowings.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question it is mentioned in كتاب الشواهد والبيان that the worshipper prays the noon prayer as ten bowings the afternoon prayer as eight bowings the sunset prayer as five bowings and the evening prayer as ten bowings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 49, NULL, 'Answer: The reliance is upon الدعائم, which is the gathering place of the questions. If a person leaves anything of the sunnah for the sake of protective concealment, he makes it up.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'answer the reliance is upon الدعايم which is the gathering place of the questions if a person leaves anything of the sunnah for the sake of protective concealment he makes it up', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 50, NULL, 'Question: It has come down concerning the prayer of glorification that when he rises from the second prostration he glorifies ten times. O our master, how does he do this — seated upon his feet, or standing?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question it has come down concerning the prayer of glorification that when he rises from the second prostration he glorifies ten times o our master how does he do this seated upon his feet or standing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 51, NULL, 'Answer: When one who prays the prayer of glorification wishes to do this, he sits poised and ready after raising his head from the second prostration, glorifies ten times, then rises for the second bowing. Likewise, after the second bowing, he sits poised and ready after the second prostration, glorifies ten times, then sits settled, makes the testimony, and gives the salutation. He does the same in the last two bowings. This practice, however, is irregular. As for that upon which practice rests in the prayer of glorification: he sits settled after raising his head from the second prostration in each bowing and glorifies ten times, then rises for the next — or, after the second, makes the testimony following the glorification, remaining settled in his sitting during both the glorification and the testimony.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'answer when one who prays the prayer of glorification wishes to do this he sits poised and ready after raising his head from the second prostration glorifies ten times then rises for the second bowing likewise after the second bowing he sits poised and ready after the second prostration glorifies ten times then sits settled makes the testimony and gives the salutation he does the same in the last two bowings this practice however is irregular as for that upon which practice rests in the prayer of glorification he sits settled after raising his head from the second prostration in each bowing and glorifies ten times then rises for the next or after the second makes the testimony following the glorification remaining settled in his sitting during both the glorification and the testimony', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 52, NULL, 'Question: It has come down concerning the prayer of sufficiency that in the first bowing one recites the opening of the Book, the chapter of sincerity, the chapter of the disbelievers, and the verse of the Throne — once each; in the second, twice each; in the third, three times each; and in the fourth, four times each. O our master, does he repeat the opening of the Book in each bowing, or is it recited once in each bowing? Kindly give the answer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question it has come down concerning the prayer of sufficiency that in the first bowing one recites the opening of the book the chapter of sincerity the chapter of the disbelievers and the verse of the throne once each in the second twice each in the third three times each and in the fourth four times each o our master does he repeat the opening of the book in each bowing or is it recited once in each bowing kindly give the answer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 53, NULL, 'Answer: He recites the opening of the Book once in each bowing, and God knows best.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'answer he recites the opening of the book once in each bowing and god knows best', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 54, NULL, 'It is said in مُخْتَصَرُ الْآثَارِ: whoever has not learned the Quran, let him recite what is easy of it. God, Exalted is He, said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'it is said in مختصر الاثار whoever has not learned the quran let him recite what is easy of it god exalted is he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 55, NULL, 'Al-Muzzammil: 20فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنَ ٱلْقُرْآنِ', '', 'فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنَ ٱلْقُرْآنِ', 'Al-Muzzammil: 20', 73, 20, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'al muzzammil 20فاقرءوا ما تيسر من القران', 'فاقرءوا ما تيسر من القران');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 56, NULL, 'So recite what is easy of the Quran.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'so recite what is easy of the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 57, NULL, 'And whoever wishes may stand the whole night with a single surah, repeating it, or with part of a surah, or with two surahs or more than that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'and whoever wishes may stand the whole night with a single surah repeating it or with part of a surah or with two surahs or more than that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 58, NULL, 'It is said in تَأْوِيلُ الدَّعَائِمِ, concerning the voluntary prayer of the Messenger of God (ع) upon his mount while he was making his way toward Medina: he would gesture with his head in indication of the prostration, with the direction of prayer behind him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'it is said in تاويل الدعايم concerning the voluntary prayer of the messenger of god ع upon his mount while he was making his way toward medina he would gesture with his head in indication of the prostration with the direction of prayer behind him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 59, NULL, 'It is said in the abridged discourse on jurisprudence — whose questions are from the most honorable Shaykh Hasan, son of the Mawla Adam al-Hindi, and whose answers are from the masters of Yemen, may God sanctify all their spirits — that whoever prays between the obligation of the later evening prayer and its voluntary prayer whatever he wishes, then prays the voluntary prayer, does not intend it as a make-up, for it is called the prayer of the night.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'it is said in the abridged discourse on jurisprudence whose questions are from the most honorable shaykh hasan son of the mawla adam al hindi and whose answers are from the masters of yemen may god sanctify all their spirits that whoever prays between the obligation of the later evening prayer and its voluntary prayer whatever he wishes then prays the voluntary prayer does not intend it as a make up for it is called the prayer of the night', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 60, NULL, 'Our master and Mawlana Jafar, son of our master Sulayman, may God raise their sanctity in the Gardens, wrote in like manner to his servant, the compiler of this book, from the island of Yemen to the island of Hind, concerning the matter of the prayer of Umm Daud, which is known among all who are of the ranks. He had asked him about it so that the sources and the paths might be made clear by his sufficient answer. He mentioned what concerns the prayer of Umm Daud and the supplication of opening, and that Qasim ibn Fir — the summoner of the maimed and blinded Daudi faction — commanded his companions to pray it, to fast it, and to supplicate with it in the month of Rabi al-Awwal of the year 1042, when the fifteenth of it fell on a Friday and they were in prison, and likewise in the honored month of Ramadan of that year. You asked about that, and about its permissibility and its practice, and I answered the one who asked you about it that Mawlana al-Sadiq (ع) gave no text on the aforementioned prayer of Umm Daud except for the month of Rajab, and he commanded her to purify herself. And when I asked him about it, and whether that supplication may be recited in a month other than Rajab, he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'our master and mawlana jafar son of our master sulayman may god raise their sanctity in the gardens wrote in like manner to his servant the compiler of this book from the island of yemen to the island of hind concerning the matter of the prayer of umm daud which is known among all who are of the ranks he had asked him about it so that the sources and the paths might be made clear by his sufficient answer he mentioned what concerns the prayer of umm daud and the supplication of opening and that qasim ibn fir the summoner of the maimed and blinded daudi faction commanded his companions to pray it to fast it and to supplicate with it in the month of rabi al awwal of the year 1042 when the fifteenth of it fell on a friday and they were in prison and likewise in the honored month of ramadan of that year you asked about that and about its permissibility and its practice and i answered the one who asked you about it that mawlana al sadiq ع gave no text on the aforementioned prayer of umm daud except for the month of rajab and he commanded her to purify herself and when i asked him about it and whether that supplication may be recited in a month other than rajab he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 61, NULL, 'Sayingفِي يَوْمِ عَرَفَةَ وَإِذَا كَانَ يَوْمَ جُمُعَةٍ لَمْ يَفْرُغْ صَاحِبُهُ اِلَّا وَقَدْ غُفِرَ لَهُ', '', 'فِي يَوْمِ عَرَفَةَ وَإِذَا كَانَ يَوْمَ جُمُعَةٍ لَمْ يَفْرُغْ صَاحِبُهُ اِلَّا وَقَدْ غُفِرَ لَهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'sayingفي يوم عرفه واذا كان يوم جمعه لم يفرغ صاحبه الا وقد غفر له', 'في يوم عرفه واذا كان يوم جمعه لم يفرغ صاحبه الا وقد غفر له');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 62, NULL, 'On the day of Arafah; and if it falls on a Friday, the one who performs it does not finish until he has been forgiven.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'on the day of arafah and if it falls on a friday the one who performs it does not finish until he has been forgiven', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 63, NULL, 'The matter stands as I have stated it. Nothing outward exists without a sign by which it is recognized, and no practice is valid without a supporting text. In the command given to Umm Daud — to seek forgiveness until the month of Rajab, along with the supplication of opening already mentioned — there is both sufficiency and satisfaction. And in the text that follows, specifying the day of Arafah when it is not a Friday, and when it is a Friday as he mentioned, there is likewise sufficiency and satisfaction: the practice applies only to that specified day. As for any occasion other than these, no one should proceed without a text. If a text exists in the matter, let it be followed; and if not, then little practice, as the Prophet (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'the matter stands as i have stated it nothing outward exists without a sign by which it is recognized and no practice is valid without a supporting text in the command given to umm daud to seek forgiveness until the month of rajab along with the supplication of opening already mentioned there is both sufficiency and satisfaction and in the text that follows specifying the day of arafah when it is not a friday and when it is a friday as he mentioned there is likewise sufficiency and satisfaction the practice applies only to that specified day as for any occasion other than these no one should proceed without a text if a text exists in the matter let it be followed and if not then little practice as the prophet ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 64, NULL, 'Sayingعَمَلٌ قَلِيلٌ فِي سُنَّةٍ خَيْرٌ مِنْ عَمَلٍ كَثِيرٍ فِي بِدْعَةٍ', '', 'عَمَلٌ قَلِيلٌ فِي سُنَّةٍ خَيْرٌ مِنْ عَمَلٍ كَثِيرٍ فِي بِدْعَةٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'sayingعمل قليل في سنه خير من عمل كثير في بدعه', 'عمل قليل في سنه خير من عمل كثير في بدعه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 65, NULL, 'You asked whether, on the day of Arafah, one should supplicate with the mentioned supplication or perform the mentioned prayer on that day. The root of the matter is that the mentioned supplication has as its condition the mentioned prayer, for he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'you asked whether on the day of arafah one should supplicate with the mentioned supplication or perform the mentioned prayer on that day the root of the matter is that the mentioned supplication has as its condition the mentioned prayer for he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 66, NULL, 'Sayingفَأَيْنَ أَنْتَ مِنْ دُعَاءِ الْاِسْتِفْتَاحِ', '', 'فَأَيْنَ أَنْتَ مِنْ دُعَاءِ الْاِسْتِفْتَاحِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'sayingفاين انت من دعاء الاستفتاح', 'فاين انت من دعاء الاستفتاح');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 67, NULL, 'Where are you with regard to the supplication of opening?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'where are you with regard to the supplication of opening', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 68, NULL, 'When I asked him about it, he made it known to her by that mentioned prayer, then by the mentioned supplication. So if you pray on that day, its prayer is upon that; and if one supplicates with it on that day, it is accepted for its excellence and its nobility. God knows best and judges best; from His friends we learn in order to know, and God grants success to what is right and guides to the best of means.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'when i asked him about it he made it known to her by that mentioned prayer then by the mentioned supplication so if you pray on that day its prayer is upon that and if one supplicates with it on that day it is accepted for its excellence and its nobility god knows best and judges best from his friends we learn in order to know and god grants success to what is right and guides to the best of means', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 69, NULL, 'In the questions from some of the shaykhs of Hind (رض), with answers from some of our masters — the summoners of Yemen, may God raise their sanctity — it is said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'in the questions from some of the shaykhs of hind رض with answers from some of our masters the summoners of yemen may god raise their sanctity it is said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 70, NULL, 'Question: Most of the believers do not keep the sunnah fasts as they pray the sunnah prayers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question most of the believers do not keep the sunnah fasts as they pray the sunnah prayers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 71, NULL, 'Answer: It is permissible for them to omit the sunnah fast, and no make-up is required of them. As for the sunnah prayer, whoever has missed it ought to make it up. The Imams (عَلَيْهِمُ السَّلَامُ) and their followers did so, and they have reward from God if they fast.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'answer it is permissible for them to omit the sunnah fast and no make up is required of them as for the sunnah prayer whoever has missed it ought to make it up the imams عليهم السلام and their followers did so and they have reward from god if they fast', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 72, NULL, 'Our master and Mawlana Hibat Allah, son of our master Ibrahim, said in his answer to questions from his servant and the humblest of his slaves, Salih ibn Ahmad — answering him from the island of Yemen to the island of Hind in the year 1135: You asked concerning what has come in the books, that the prophets — such as Jesus and others — and the Imams, such as Mawlana Ali and Mawlana Zayn al-Abidin and others among the Imams, the blessings of God be upon them all, at the time of a great event would call for water, perform the ablution, and pray two bowings, and in some instances four bowings, for the relief of distress. It has not been made clear at what time they prayed. Is that prayer to be prayed at all times of trial, affliction, and calamity, or only at a time when the sunnah and voluntary prayers are permitted? May the master and owner graciously give the answer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'our master and mawlana hibat allah son of our master ibrahim said in his answer to questions from his servant and the humblest of his slaves salih ibn ahmad answering him from the island of yemen to the island of hind in the year 1135 you asked concerning what has come in the books that the prophets such as jesus and others and the imams such as mawlana ali and mawlana zayn al abidin and others among the imams the blessings of god be upon them all at the time of a great event would call for water perform the ablution and pray two bowings and in some instances four bowings for the relief of distress it has not been made clear at what time they prayed is that prayer to be prayed at all times of trial affliction and calamity or only at a time when the sunnah and voluntary prayers are permitted may the master and owner graciously give the answer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 73, NULL, 'Answer: By the help of God, Exalted is He, and the favor of His friend upon His earth (ع), and by the instruction of my master Badr al-Din, the inspired and the helper: the prayer of the prophets and the prayer of the Imams, the blessings and peace and benedictions of God be upon them all, flows down to us from them at times of grave matters and events, and at the descent of calamities and disasters. Their prayer is praise of God and thanksgiving for what He disclosed to them of the secret of affairs, and for their knowledge that those things do not come to pass except by a measure decreed. You mentioned that they, the blessings of God be upon them, did not inform us at what times it is to be prayed, but only reported it in a summary way. Yes, it is permissible to pray it at all the times when the sunnah and voluntary prayers are permitted; prohibition has come only concerning the forbidden times, which are not hidden from one of clear mind and illumined form. When their servants and their followers wish to pray that mentioned prayer, and by it to repel all calamities and to be shielded by it from all evils and ruinous things, it is for them to be guided by their guidance and to follow their practice. May God, Mighty and Majestic, keep us firm upon obedience to them, grant us their accepted intercession, and supply us from their secret and their blessings. He is the Guardian of that and the One able to do it, by the right that is His and the secret that is with Him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'answer by the help of god exalted is he and the favor of his friend upon his earth ع and by the instruction of my master badr al din the inspired and the helper the prayer of the prophets and the prayer of the imams the blessings and peace and benedictions of god be upon them all flows down to us from them at times of grave matters and events and at the descent of calamities and disasters their prayer is praise of god and thanksgiving for what he disclosed to them of the secret of affairs and for their knowledge that those things do not come to pass except by a measure decreed you mentioned that they the blessings of god be upon them did not inform us at what times it is to be prayed but only reported it in a summary way yes it is permissible to pray it at all the times when the sunnah and voluntary prayers are permitted prohibition has come only concerning the forbidden times which are not hidden from one of clear mind and illumined form when their servants and their followers wish to pray that mentioned prayer and by it to repel all calamities and to be shielded by it from all evils and ruinous things it is for them to be guided by their guidance and to follow their practice may god mighty and majestic keep us firm upon obedience to them grant us their accepted intercession and supply us from their secret and their blessings he is the guardian of that and the one able to do it by the right that is his and the secret that is with him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 74, NULL, 'I turn now to the prostration of the Quran, and again from that book of questions and answers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'i turn now to the prostration of the quran and again from that book of questions and answers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 75, NULL, 'Question: What do you say concerning one who recites a supplication in which there is a verse of prostration? Is it obligatory upon him to prostrate or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question what do you say concerning one who recites a supplication in which there is a verse of prostration is it obligatory upon him to prostrate or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 76, NULL, 'Answer: If it is among the binding ones, he must prostrate.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'answer if it is among the binding ones he must prostrate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 77, NULL, 'Question: What do you say concerning the teacher of boys, when he is teaching them the Quran and passes over the places of prostration while instructing them? Does he prostrate every time he passes over them, and do those who hear him prostrate as well, or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'question what do you say concerning the teacher of boys when he is teaching them the quran and passes over the places of prostration while instructing them does he prostrate every time he passes over them and do those who hear him prostrate as well or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 78, NULL, 'Answer: He has a choice in that: if he wishes, he prostrates, and if he wishes, he leaves it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'answer he has a choice in that if he wishes he prostrates and if he wishes he leaves it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 79, NULL, 'Another case: a man says in the prostration of the Quran what he says in the prostration of prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'another case a man says in the prostration of the quran what he says in the prostration of prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 80, NULL, 'It is said in مُخْتَصَرُ الْمُصَنَّفِ: when the reciter recites one of the binding prostrations, whoever is present prostrates. If that same prostration is recited again, none of them is required to prostrate a second time so long as he remains in that place. As for the remaining prostrations, whoever wishes to prostrate may prostrate, and whoever wishes may leave it; though prostrating is better.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'it is said in مختصر المصنف when the reciter recites one of the binding prostrations whoever is present prostrates if that same prostration is recited again none of them is required to prostrate a second time so long as he remains in that place as for the remaining prostrations whoever wishes to prostrate may prostrate and whoever wishes may leave it though prostrating is better', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 81, NULL, 'Mawlana, the Commander of the Faithful, Ali ibn Abi Talib (ع), said in his four hundred points of conduct:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'mawlana the commander of the faithful ali ibn abi talib ع said in his four hundred points of conduct', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 82, NULL, 'Sayingأَطِيلُوا السُّجُودَ فَمَا مِنْ عَمَلٍ أَشَدُّ عَلَى إِبْلِيسَ مِنْ أَنْ يَرَى ابْنَ آدَمَ سَاجِدًا فَأَنَّهُ أُمِرَ بِالسُّجُودِ فَعَصَى وَأُمِرَ ابْنُ آدَمَ بِالسُّجُودِ فَأَطَاعَ وَنَجَا', '', 'أَطِيلُوا السُّجُودَ فَمَا مِنْ عَمَلٍ أَشَدُّ عَلَى إِبْلِيسَ مِنْ أَنْ يَرَى ابْنَ آدَمَ سَاجِدًا فَأَنَّهُ أُمِرَ بِالسُّجُودِ فَعَصَى وَأُمِرَ ابْنُ آدَمَ بِالسُّجُودِ فَأَطَاعَ وَنَجَا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'sayingاطيلوا السجود فما من عمل اشد علي ابليس من ان يري ابن ادم ساجدا فانه امر بالسجود فعصي وامر ابن ادم بالسجود فاطاع ونجا', 'اطيلوا السجود فما من عمل اشد علي ابليس من ان يري ابن ادم ساجدا فانه امر بالسجود فعصي وامر ابن ادم بالسجود فاطاع ونجا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'eclipse, fear, rain, and the night vigil', '24. Eclipse, Fear, Rain, and the Night Vigil', 83, NULL, 'Prolong the prostration, for nothing bears more heavily on Iblis than to see the son of Adam prostrating. He was himself commanded to prostrate and disobeyed, while the son of Adam was commanded to prostrate, obeyed, and was saved.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 24 eclipse fear rain and the night vigil', 'prolong the prostration for nothing bears more heavily on iblis than to see the son of adam prostrating he was himself commanded to prostrate and disobeyed while the son of adam was commanded to prostrate obeyed and was saved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 0, NULL, 'I turn now to the book of funerals — to its teachings on the sick person, the visits made to him, and the state of dying itself. In the book of the interpretation of the pillars, I find that the dying state is the moment when death draws near and the passage from this world to the hereafter is at hand.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'i turn now to the book of funerals to its teachings on the sick person the visits made to him and the state of dying itself in the book of the interpretation of the pillars i find that the dying state is the moment when death draws near and the passage from this world to the hereafter is at hand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 1, NULL, 'In the book of questions and answers — whose questions were put by the eminent Shaykh Yusuf ibn Ismail al-Samiti al-Hindi, and whose answers were given by our master Idris ibn Hasan, may Allah sanctify him — I read the following exchange.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'in the book of questions and answers whose questions were put by the eminent shaykh yusuf ibn ismail al samiti al hindi and whose answers were given by our master idris ibn hasan may allah sanctify him i read the following exchange', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 2, NULL, 'Question: What do you say concerning people who move from one place to another out of fear of epidemic and plague, believing that it will not reach them? Is that permitted or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'question what do you say concerning people who move from one place to another out of fear of epidemic and plague believing that it will not reach them is that permitted or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 3, NULL, 'Answer:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'answer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 4, NULL, 'Sayingيَتَوَجَّهُونَ حَيْثُ يَشَاءُونَ وَالْأَمْرُ بِيَدِ اللَّهِ تَعَالَى', '', 'يَتَوَجَّهُونَ حَيْثُ يَشَاءُونَ وَالْأَمْرُ بِيَدِ اللَّهِ تَعَالَى', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingيتوجهون حيث يشاءون والامر بيد الله تعالي', 'يتوجهون حيث يشاءون والامر بيد الله تعالي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 5, NULL, 'They may go wherever they wish. The matter is in the hand of Allah, exalted be He.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'they may go wherever they wish the matter is in the hand of allah exalted be he', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 6, NULL, 'I turn next to what our master and mawlana Jafar ibn Sayyidina Sulayman — may Allah sanctify him and grant us his intercession and his nearness — set down in his noble epistle, which he named The Sharpest Sword in the Nullifying of Innovations. He wrote it to counsel his people and to rouse those among them who had grown heedless and slept too long — among the people of the island of Yemen — after he had settled and dwelt among them. In one section of it, he says that it has been reported of some of you that you are slow in visiting the sick, though the reward for it has its established place in the noble book of the pillars of Islam, where it is recorded on the authority of your mawla the Commander of the Faithful (ع) that he heard the Messenger of Allah say:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'i turn next to what our master and mawlana jafar ibn sayyidina sulayman may allah sanctify him and grant us his intercession and his nearness set down in his noble epistle which he named the sharpest sword in the nullifying of innovations he wrote it to counsel his people and to rouse those among them who had grown heedless and slept too long among the people of the island of yemen after he had settled and dwelt among them in one section of it he says that it has been reported of some of you that you are slow in visiting the sick though the reward for it has its established place in the noble book of the pillars of islam where it is recorded on the authority of your mawla the commander of the faithful ع that he heard the messenger of allah say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 7, NULL, 'Sayingمَا مِنْ عَبْدٍ مُسْلِمٍ يَعُودُ مَرِيضًا إِلَّا صَلَّى عَلَيْهِ سَبْعُونَ أَلْفِ مَلَكٍ مِنْ سَاعَتِهِ الَّتِي يَعُودُ فِيهَا إِنْ كَانَ نَهَارًا حَتَّى تَغْرُبَ الشَّمْسُ أَوْ لَيْلًا حَتَّى تَطْلُعَ', '', 'مَا مِنْ عَبْدٍ مُسْلِمٍ يَعُودُ مَرِيضًا إِلَّا صَلَّى عَلَيْهِ سَبْعُونَ أَلْفِ مَلَكٍ مِنْ سَاعَتِهِ الَّتِي يَعُودُ فِيهَا إِنْ كَانَ نَهَارًا حَتَّى تَغْرُبَ الشَّمْسُ أَوْ لَيْلًا حَتَّى تَطْلُعَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingما من عبد مسلم يعود مريضا الا صلي عليه سبعون الف ملك من ساعته التي يعود فيها ان كان نهارا حتي تغرب الشمس او ليلا حتي تطلع', 'ما من عبد مسلم يعود مريضا الا صلي عليه سبعون الف ملك من ساعته التي يعود فيها ان كان نهارا حتي تغرب الشمس او ليلا حتي تطلع');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 8, NULL, 'I also find recorded there, from the Commander of the Faithful (ع), that he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'i also find recorded there from the commander of the faithful ع that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 9, NULL, 'Sayingنَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ أَنْ يَأْكُلَ الْعَائِدُ عِنْدَ الْعَلِيلِ فَيُحْبِطَ اللَّهُ عِيَادَتَهُ', '', 'نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ أَنْ يَأْكُلَ الْعَائِدُ عِنْدَ الْعَلِيلِ فَيُحْبِطَ اللَّهُ عِيَادَتَهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingنهي رسول الله صلي الله عليه واله ان ياكل العايد عند العليل فيحبط الله عيادته', 'نهي رسول الله صلي الله عليه واله ان ياكل العايد عند العليل فيحبط الله عيادته');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 10, NULL, 'The Messenger of Allah forbade the visitor from eating in the presence of the sick person, for when that happens, Allah renders his visit worthless.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'the messenger of allah forbade the visitor from eating in the presence of the sick person for when that happens allah renders his visit worthless', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 11, NULL, 'In another narration, the wording is that Allah renders his reward worthless — and indeed casts it behind him. The reason is this: when the visitor eats and drinks in a sick man''s house, he presses upon someone already pressed by illness, and harms the household as well. The sick man may be of slender means, so that he and his family are inwardly galled by it. Whoever knows this must pass it on to those who do not, for not all people are learned, and the learned among them are few and select. The one who gives the warning has discharged his duty. The truth has come and falsehood has perished.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'in another narration the wording is that allah renders his reward worthless and indeed casts it behind him the reason is this when the visitor eats and drinks in a sick mans house he presses upon someone already pressed by illness and harms the household as well the sick man may be of slender means so that he and his family are inwardly galled by it whoever knows this must pass it on to those who do not for not all people are learned and the learned among them are few and select the one who gives the warning has discharged his duty the truth has come and falsehood has perished', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 12, NULL, 'Our mawlana the Commander of the Faithful Ali ibn Abi Talib (ع) said in his four hundred points of conduct:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'our mawlana the commander of the faithful ali ibn abi talib ع said in his four hundred points of conduct', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 13, NULL, 'Sayingولا ينامنّ أحدكم على الحجة ولا على وجهه فمن رأيتموه نام على وجهه فانتبهوه ولا تنام المرأة مستلقية على ظهرها', '', 'ولا ينامنّ أحدكم على الحجة ولا على وجهه فمن رأيتموه نام على وجهه فانتبهوه ولا تنام المرأة مستلقية على ظهرها', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingولا ينامن احدكم علي الحجه ولا علي وجهه فمن رايتموه نام علي وجهه فانتبهوه ولا تنام المراه مستلقيه علي ظهرها', 'ولا ينامن احدكم علي الحجه ولا علي وجهه فمن رايتموه نام علي وجهه فانتبهوه ولا تنام المراه مستلقيه علي ظهرها');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 14, NULL, 'Let none of أحدكم sleep in that posture, nor upon his face. Whomever you see sleeping upon his face, wake him. And let المرأة not sleep stretched out upon her back.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'let none of احدكم sleep in that posture nor upon his face whomever you see sleeping upon his face wake him and let المراه not sleep stretched out upon her back', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 15, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 16, NULL, 'Sayingأسأل الله العافية من جهد البلاء فان جهد البلاء ذهاب للدين', '', 'أسأل الله العافية من جهد البلاء فان جهد البلاء ذهاب للدين', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingاسال الله العافيه من جهد البلاء فان جهد البلاء ذهاب للدين', 'اسال الله العافيه من جهد البلاء فان جهد البلاء ذهاب للدين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 17, NULL, 'I ask Allah for well-being and refuge from severe affliction, for the gravest affliction of all is the loss of one''s religion.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'i ask allah for well being and refuge from severe affliction for the gravest affliction of all is the loss of ones religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 18, NULL, 'I turn now to the command to remember death and to what accompanies it. In this same book of questions and answers — arranged by its compiler following the chapter order of the book of the pillars of Islam — I read the following.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'i turn now to the command to remember death and to what accompanies it in this same book of questions and answers arranged by its compiler following the chapter order of the book of the pillars of islam i read the following', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 19, NULL, 'Question: What is your view on the lifespans of people? Are they fixed with Allah, glorified be He, admitting neither increase nor decrease? And if that is so, what is the meaning of what the books record — that a lifespan may be both increased and decreased?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'question what is your view on the lifespans of people are they fixed with allah glorified be he admitting neither increase nor decrease and if that is so what is the meaning of what the books record that a lifespan may be both increased and decreased', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 20, NULL, 'Answer:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'answer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 21, NULL, 'Sayingأَنَّهَا أَعْمَارٌ مُؤَجَّلَةٌ لَا تَزِيدُ وَلَا تَنْقُصُ وَأَمَّا مَعْنَى الزِّيَادَةِ وَالنُّقْصَانِ فَهُوَ صَحِيحٌ بِمَعْنَى أَنَّ الَّذِي يَنْقُصُ فِي الدَّوْرِ الْمَاضِي يَزِيدُ فِي الْمُسْتَقْبَلِ فِيهِ', '', 'أَنَّهَا أَعْمَارٌ مُؤَجَّلَةٌ لَا تَزِيدُ وَلَا تَنْقُصُ وَأَمَّا مَعْنَى الزِّيَادَةِ وَالنُّقْصَانِ فَهُوَ صَحِيحٌ بِمَعْنَى أَنَّ الَّذِي يَنْقُصُ فِي الدَّوْرِ الْمَاضِي يَزِيدُ فِي الْمُسْتَقْبَلِ فِيهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingانها اعمار موجله لا تزيد ولا تنقص واما معني الزياده والنقصان فهو صحيح بمعني ان الذي ينقص في الدور الماضي يزيد في المستقبل فيه', 'انها اعمار موجله لا تزيد ولا تنقص واما معني الزياده والنقصان فهو صحيح بمعني ان الذي ينقص في الدور الماضي يزيد في المستقبل فيه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 22, NULL, 'Question: What do you say concerning his saying (ع):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'question what do you say concerning his saying ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 23, NULL, 'Sayingالشَّقِيُّ كُلُّ الشَّقِيِّ مَنْ أَدْرَكَتْهُ السَّاعَةُ حَيًّا لَمْ يَمُتْ', '', 'الشَّقِيُّ كُلُّ الشَّقِيِّ مَنْ أَدْرَكَتْهُ السَّاعَةُ حَيًّا لَمْ يَمُتْ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingالشقي كل الشقي من ادركته الساعه حيا لم يمت', 'الشقي كل الشقي من ادركته الساعه حيا لم يمت');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 24, NULL, 'The wretched — wholly wretched — is the one whom the Hour overtakes while he is alive and has not died.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'the wretched wholly wretched is the one whom the hour overtakes while he is alive and has not died', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 25, NULL, 'Is what is meant here that the most wretched of the wretched is the one whose death comes upon him while he still lives the sensory, animal life, not yet having passed into the angelic life? Or is something else intended?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'is what is meant here that the most wretched of the wretched is the one whose death comes upon him while he still lives the sensory animal life not yet having passed into the angelic life or is something else intended', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 26, NULL, 'Answer:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'answer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 27, NULL, 'Sayingإِنَّ قَصْدَهُ إِذَا أَتَتْهُ السَّاعَةُ وَهُوَ فِي حَالِ الْبَهِيْمِيَّةِ', '', 'إِنَّ قَصْدَهُ إِذَا أَتَتْهُ السَّاعَةُ وَهُوَ فِي حَالِ الْبَهِيْمِيَّةِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingان قصده اذا اتته الساعه وهو في حال البهيميه', 'ان قصده اذا اتته الساعه وهو في حال البهيميه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 28, NULL, 'What is intended is that the Hour overtakes him while he is still in the animal condition.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'what is intended is that the hour overtakes him while he is still in the animal condition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 29, NULL, 'Among the questions that the eminent Shaykh Hasan ibn Nuh addressed to our master Husayn ibn Idris — may Allah sanctify his soul — along with his answers to them, the tenth question is this: a woman dies while pregnant, carrying in her womb a fully formed and living child; should the child be left in her womb, or should it be taken out?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'among the questions that the eminent shaykh hasan ibn nuh addressed to our master husayn ibn idris may allah sanctify his soul along with his answers to them the tenth question is this a woman dies while pregnant carrying in her womb a fully formed and living child should the child be left in her womb or should it be taken out', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 30, NULL, 'Answer:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'answer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 31, NULL, 'Sayingإن حضرت المرأة امرأة تحسن إخراجه فهو الواجب إذا قدر أو في ستة أشهر فما فوقها ويرجى له الحياة وان لم فلا تقبر أمه حتى يتحقق موته والله أعلم', '', 'إن حضرت المرأة امرأة تحسن إخراجه فهو الواجب إذا قدر أو في ستة أشهر فما فوقها ويرجى له الحياة وان لم فلا تقبر أمه حتى يتحقق موته والله أعلم', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingان حضرت المراه امراه تحسن اخراجه فهو الواجب اذا قدر او في سته اشهر فما فوقها ويرجي له الحياه وان لم فلا تقبر امه حتي يتحقق موته والله اعلم', 'ان حضرت المراه امراه تحسن اخراجه فهو الواجب اذا قدر او في سته اشهر فما فوقها ويرجي له الحياه وان لم فلا تقبر امه حتي يتحقق موته والله اعلم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 32, NULL, 'If there is present with the woman another woman skilled in delivering the child, that is what must be done, if it is possible, or if the child is of six months or more and life is hoped for it. If not, then the mother is not to be buried until his death is confirmed. And Allah knows best.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'if there is present with the woman another woman skilled in delivering the child that is what must be done if it is possible or if the child is of six months or more and life is hoped for it if not then the mother is not to be buried until his death is confirmed and allah knows best', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 33, NULL, 'Our mawlana the Commander of the Faithful Ali ibn Abi Talib (ع) said in his four hundred points of conduct:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'our mawlana the commander of the faithful ali ibn abi talib ع said in his four hundred points of conduct', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 34, NULL, 'Sayingتَمَسَّكُوا بِمَا أَمَرَكُمُ اللَّهُ تَعَالَى فَمَا بَيْنَ أَحَدِكُمْ وَبَيْنَ أَنْ يَغْتَبِطَ وَيَرَى مَا يُحِبُّ إِلَّا أَنْ يَحْضُرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ وَمَا عِنْدَ اللَّهِ خَيْرٌ وَأَبْقَى وَتَأْتِيهِ الْبِشَارَةُ وَاللَّهِ لَتَقَرَّنَّ عَيْنُهُ وَلَيَحِينَ لِقَاءُ اللَّهِ', '', 'تَمَسَّكُوا بِمَا أَمَرَكُمُ اللَّهُ تَعَالَى فَمَا بَيْنَ أَحَدِكُمْ وَبَيْنَ أَنْ يَغْتَبِطَ وَيَرَى مَا يُحِبُّ إِلَّا أَنْ يَحْضُرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ وَمَا عِنْدَ اللَّهِ خَيْرٌ وَأَبْقَى وَتَأْتِيهِ الْبِشَارَةُ وَاللَّهِ لَتَقَرَّنَّ عَيْنُهُ وَلَيَحِينَ لِقَاءُ اللَّهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingتمسكوا بما امركم الله تعالي فما بين احدكم وبين ان يغتبط ويري ما يحب الا ان يحضره رسول الله صلي الله عليه واله وما عند الله خير وابقي وتاتيه البشاره والله لتقرن عينه وليحين لقاء الله', 'تمسكوا بما امركم الله تعالي فما بين احدكم وبين ان يغتبط ويري ما يحب الا ان يحضره رسول الله صلي الله عليه واله وما عند الله خير وابقي وتاتيه البشاره والله لتقرن عينه وليحين لقاء الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 35, NULL, 'Hold fast to what Allah, exalted be He, has commanded you. There is nothing between one of you and his rejoicing and seeing what he loves except that the Messenger of Allah should be present with him, and what is with Allah is better and more lasting, and the glad tidings come to him. By Allah, his eye shall be gladdened, and the meeting with Allah shall surely draw near.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'hold fast to what allah exalted be he has commanded you there is nothing between one of you and his rejoicing and seeing what he loves except that the messenger of allah should be present with him and what is with allah is better and more lasting and the glad tidings come to him by allah his eye shall be gladdened and the meeting with allah shall surely draw near', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 36, NULL, 'And he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 37, NULL, 'Sayingأَكْثِرُوا ذِكْرَ الْمَوْتِ يَوْمَ خُرُوجِكُمْ مِنْ عِنْدِ الْقُبُورِ وَيَوْمَ قِيَامِكُمْ بَيْنَ يَدَيِ اللَّهِ تَهْنْ عَلَيْكُمُ الْمَصَايِبُ', '', 'أَكْثِرُوا ذِكْرَ الْمَوْتِ يَوْمَ خُرُوجِكُمْ مِنْ عِنْدِ الْقُبُورِ وَيَوْمَ قِيَامِكُمْ بَيْنَ يَدَيِ اللَّهِ تَهْنْ عَلَيْكُمُ الْمَصَايِبُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingاكثروا ذكر الموت يوم خروجكم من عند القبور ويوم قيامكم بين يدي الله تهن عليكم المصايب', 'اكثروا ذكر الموت يوم خروجكم من عند القبور ويوم قيامكم بين يدي الله تهن عليكم المصايب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 38, NULL, 'Remember death often, and the day of your coming forth from the graves, and the day of your standing before Allah, and calamities will sit lightly upon you.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'remember death often and the day of your coming forth from the graves and the day of your standing before allah and calamities will sit lightly upon you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 39, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 40, NULL, 'Sayingاَلْحُمَّى رَايِدُ الْمَوْتِ وَسِجْنُ اللهِ فِي الْأَرْضِ يَحْبِسُ بِهِ مَنْ يَشَاءُ مِنْ عِبَادِهِ وَهُوَ يَحُتُّ الذُّنُوبَ كَمَا يَحُتُّ الْوَبَرُ مِنْ مَسَامِّ الْبَعِيرِ', '', 'اَلْحُمَّى رَايِدُ الْمَوْتِ وَسِجْنُ اللهِ فِي الْأَرْضِ يَحْبِسُ بِهِ مَنْ يَشَاءُ مِنْ عِبَادِهِ وَهُوَ يَحُتُّ الذُّنُوبَ كَمَا يَحُتُّ الْوَبَرُ مِنْ مَسَامِّ الْبَعِيرِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingالحمي رايد الموت وسجن الله في الارض يحبس به من يشاء من عباده وهو يحت الذنوب كما يحت الوبر من مسام البعير', 'الحمي رايد الموت وسجن الله في الارض يحبس به من يشاء من عباده وهو يحت الذنوب كما يحت الوبر من مسام البعير');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 41, NULL, 'Fever is the forerunner of death — Allah''s prison on earth, through which He confines whomever He wills among His servants. It strips away sins as hair is stripped from the pores of the camel.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'fever is the forerunner of death allahs prison on earth through which he confines whomever he wills among his servants it strips away sins as hair is stripped from the pores of the camel', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 42, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 43, NULL, 'Sayingمَا مِنْ شِيعَتِنَا أَحَدٌ يُفَارِقُ أَمْرًا نَهَيْنَا عَنْهُ فَيَمُوتُ حَتَّىٰ يُبْتَلَىٰ بِبَلِيَّةٍ تُمَحِّصُ ذُنُوبَهُ أَمَّا فِي مَالِهِ أَوْ وَلَدِهِ أَوْ فِي نَفْسِهِ حَتَّىٰ يَلْقَى اللَّهَ بِمُحِبِّنَا وَمَا لَهُ مِنْ ذَنْبٍ وَأَنَّهُ لَا يَبْقَىٰ عَلَيْهِ شَيْءٌ مِنْ ذُنُوبِهِ فَيُشَدَّدُ عَلَيْهِ عِنْدَ مَوْتِهِ وَيُمَحَّصُ مِنْ ذُنُوبِهِ وَالْمَيِّتُ مِنْ شِيعَتِنَا صِدِّيقٌ شَهِيدٌ صَدَّقَ بِأَمْرِنَا وَأَحَبَّ فِينَا وَأَبْغَضَ فِينَا', '', 'مَا مِنْ شِيعَتِنَا أَحَدٌ يُفَارِقُ أَمْرًا نَهَيْنَا عَنْهُ فَيَمُوتُ حَتَّىٰ يُبْتَلَىٰ بِبَلِيَّةٍ تُمَحِّصُ ذُنُوبَهُ أَمَّا فِي مَالِهِ أَوْ وَلَدِهِ أَوْ فِي نَفْسِهِ حَتَّىٰ يَلْقَى اللَّهَ بِمُحِبِّنَا وَمَا لَهُ مِنْ ذَنْبٍ وَأَنَّهُ لَا يَبْقَىٰ عَلَيْهِ شَيْءٌ مِنْ ذُنُوبِهِ فَيُشَدَّدُ عَلَيْهِ عِنْدَ مَوْتِهِ وَيُمَحَّصُ مِنْ ذُنُوبِهِ وَالْمَيِّتُ مِنْ شِيعَتِنَا صِدِّيقٌ شَهِيدٌ صَدَّقَ بِأَمْرِنَا وَأَحَبَّ فِينَا وَأَبْغَضَ فِينَا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingما من شيعتنا احد يفارق امرا نهينا عنه فيموت حتي يبتلي ببليه تمحص ذنوبه اما في ماله او ولده او في نفسه حتي يلقي الله بمحبنا وما له من ذنب وانه لا يبقي عليه شيء من ذنوبه فيشدد عليه عند موته ويمحص من ذنوبه والميت من شيعتنا صديق شهيد صدق بامرنا واحب فينا وابغض فينا', 'ما من شيعتنا احد يفارق امرا نهينا عنه فيموت حتي يبتلي ببليه تمحص ذنوبه اما في ماله او ولده او في نفسه حتي يلقي الله بمحبنا وما له من ذنب وانه لا يبقي عليه شيء من ذنوبه فيشدد عليه عند موته ويمحص من ذنوبه والميت من شيعتنا صديق شهيد صدق بامرنا واحب فينا وابغض فينا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 44, NULL, 'I turn now to condolences and patience — to the weeping that is permitted and the wailing that is forbidden — and to everything that falls within these subjects.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'i turn now to condolences and patience to the weeping that is permitted and the wailing that is forbidden and to everything that falls within these subjects', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 45, NULL, 'The abridged compendium states that no hair is to be shaved, no lamp lit, and no nail cut on account of the dead. In the book of questions and answers already mentioned — arranged according to the chapters of the book of the pillars of Islam — I find the following:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'the abridged compendium states that no hair is to be shaved no lamp lit and no nail cut on account of the dead in the book of questions and answers already mentioned arranged according to the chapters of the book of the pillars of islam i find the following', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 46, NULL, 'Question: What do you say concerning some people who place weapons beside the dead when the body passes the night in the house with them, and others who hold that sitting beside the body is a binding obligation? How is that?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'question what do you say concerning some people who place weapons beside the dead when the body passes the night in the house with them and others who hold that sitting beside the body is a binding obligation how is that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 47, NULL, 'Answer:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'answer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 48, NULL, 'Sayingمِثْلُ هَذَا لَا مُعَوَّلَ عَلَيْهِ', '', 'مِثْلُ هَذَا لَا مُعَوَّلَ عَلَيْهِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingمثل هذا لا معول عليه', 'مثل هذا لا معول عليه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 49, NULL, 'There is no reliance to be placed upon anything of this kind.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'there is no reliance to be placed upon anything of this kind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 50, NULL, 'Our master and mawlana Jafar ibn Sayyidina Sulayman, may Allah sanctify their souls in the chambers of the gardens, addressed this in his noble epistle known as The Sharpest Sword in the Nullifying of Innovations, through which he counseled his people and roused those among them who had grown heedless and slept too long — among the people of the island of Yemen, after he had settled and dwelt among them. In one section he writes that among these innovations is what has become known of some of you: the wailing over the dead, with all the innovations it carries. A company of women gathers from their various places to lament the dead through nights and days on end, as though it were a prescription from your Lord — glorified be He — appointed at fixed times. With it comes singing and all that follows: diversion and play that stretch past the limit within which they are permitted on the days of weddings and banquets, where their purpose is to distinguish fornication from lawful marriage — and stretch on into what is prohibited, forbidden, and altogether impermissible. Even if your adversaries who stand outside this noble creed have a full share of such things, you are not free of them either. They disgrace you before Allah, glorified be He, and before His friends (عَلَيْهِمُ السَّلَامُ), and they bring you — may Allah protect you — to destruction in your return to Him. And you are the cream of this whole world and its kernel. What then is the matter with you, that you do not restrain yourselves from this fault, nor guard yourselves against falling into the pit? May Allah shield you from it from this hour onward, and from returning to its like, if you are believers.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'our master and mawlana jafar ibn sayyidina sulayman may allah sanctify their souls in the chambers of the gardens addressed this in his noble epistle known as the sharpest sword in the nullifying of innovations through which he counseled his people and roused those among them who had grown heedless and slept too long among the people of the island of yemen after he had settled and dwelt among them in one section he writes that among these innovations is what has become known of some of you the wailing over the dead with all the innovations it carries a company of women gathers from their various places to lament the dead through nights and days on end as though it were a prescription from your lord glorified be he appointed at fixed times with it comes singing and all that follows diversion and play that stretch past the limit within which they are permitted on the days of weddings and banquets where their purpose is to distinguish fornication from lawful marriage and stretch on into what is prohibited forbidden and altogether impermissible even if your adversaries who stand outside this noble creed have a full share of such things you are not free of them either they disgrace you before allah glorified be he and before his friends عليهم السلام and they bring you may allah protect you to destruction in your return to him and you are the cream of this whole world and its kernel what then is the matter with you that you do not restrain yourselves from this fault nor guard yourselves against falling into the pit may allah shield you from it from this hour onward and from returning to its like if you are believers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 51, NULL, 'The one among you who reads has read in the noble book of the pillars of Islam the words of its author — may Allah sanctify his soul — in the narration whose soundness he intended and sought, from Jafar ibn Muhammad, the blessings of Allah be upon him, who made this bequest when death came upon him:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'the one among you who reads has read in the noble book of the pillars of islam the words of its author may allah sanctify his soul in the narration whose soundness he intended and sought from jafar ibn muhammad the blessings of allah be upon him who made this bequest when death came upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 52, NULL, 'Sayingلَا يُلْطَمَنَّ عَلَيَّ خَدٌّ وَلَا يُشَقَّنَّ عَلَيَّ جَيْبٌ فَمَا مِنِ امْرَأَةٍ تَشُقُّ جَيْبَهَا إِلَّا لَهَا فِي جَهَنَّمَ صَدْعٌ كُلَّمَا زَادَتْ زِيدَتْ"Let no cheek be struck for me, and let no collar be torn for me. There is no woman who tears her collar but that she has a rent in Hell, and whenever she adds to it, it is added for her."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingلا يلطمن علي خد ولا يشقن علي جيب فما من امراه تشق جيبها الا لها في جهنم صدع كلما زادت زيدت let no cheek be struck for me and let no collar be torn for me there is no woman who tears her collar but that she has a rent in hell and whenever she adds to it it is added for her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 53, NULL, 'He also records in it, from Ali, the blessings of Allah be upon him, that he wrote to Rifaah ibn Shaddad, his judge over al-Ahwaz:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'he also records in it from ali the blessings of allah be upon him that he wrote to rifaah ibn shaddad his judge over al ahwaz', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 54, NULL, 'Sayingوَإِيَّاكَ وَالنَّوْحَ عَلَى الْمَيِّتِ بِبَلَدٍ يَكُونُ لَكَ بِهِ سُلْطَانٌ"Beware of wailing over the dead in a land where you hold authority."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingواياك والنوح علي الميت ببلد يكون لك به سلطان beware of wailing over the dead in a land where you hold authority', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 55, NULL, 'I also record in it, in plain terms, from the Messenger of Allah, that he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'i also record in it in plain terms from the messenger of allah that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 56, NULL, 'Sayingصَوْتَانِ مَلْعُونَانِ يُبْغِضُهُمَا اللَّهُ اِعْوَالٌ عِنْدَ مُصِيبَةٍ وَصَوْتٌ عِنْدَ نِعْمَةٍ', '', 'صَوْتَانِ مَلْعُونَانِ يُبْغِضُهُمَا اللَّهُ اِعْوَالٌ عِنْدَ مُصِيبَةٍ وَصَوْتٌ عِنْدَ نِعْمَةٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingصوتان ملعونان يبغضهما الله اعوال عند مصيبه وصوت عند نعمه', 'صوتان ملعونان يبغضهما الله اعوال عند مصيبه وصوت عند نعمه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 57, NULL, 'Two voices are accursed, hated by Allah: a howling at a calamity and a voice raised at a blessing.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'two voices are accursed hated by allah a howling at a calamity and a voice raised at a blessing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 58, NULL, 'By this I mean wailing and singing. Whoever wails for his dead calls down upon himself the very causes of affliction by which the soul is punished — as the Prophet has explained. This is precisely what the noble book I have already named recounts in the account of Abdullah ibn Rawahah. The Prophet visited him while he lay ill, finding him weighed down by pain and fallen unconscious, aware of nothing, while the women shrieked around him. The Messenger of Allah called to him three times and received no answer, so he prayed for him with the prayer he made to his Lord — glorified be He — and turned away from him. Afterward, Abdullah felt a lightness in himself and emerged from his unconsciousness; the Prophet was informed of it. He returned, stood over him, and said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'by this i mean wailing and singing whoever wails for his dead calls down upon himself the very causes of affliction by which the soul is punished as the prophet has explained this is precisely what the noble book i have already named recounts in the account of abdullah ibn rawahah the prophet visited him while he lay ill finding him weighed down by pain and fallen unconscious aware of nothing while the women shrieked around him the messenger of allah called to him three times and received no answer so he prayed for him with the prayer he made to his lord glorified be he and turned away from him afterward abdullah felt a lightness in himself and emerged from his unconsciousness the prophet was informed of it he returned stood over him and said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 59, NULL, 'Sayingيَا عَبْدَ اللَّهِ حَدِّثْ بِمَا رَأَيْتَ فَاِنَّكَ رَأَيْتَ عَجَبًا"O Abdullah, tell what you saw, for you have seen something wondrous."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingيا عبد الله حدث بما رايت فانك رايت عجبا o abdullah tell what you saw for you have seen something wondrous', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 60, NULL, 'He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 61, NULL, 'Sayingيَا رَسُولَ اللهِ رَأَيْتُ مَلَكًا مِنَ الْمَلَائِكَةِ بِيَدِهِ مِقْمَعَةٌ مِنْ حَدِيدٍ تَأَجَّجُ نَارًا وَكُلَّمَا صَرَخَتْ صَارِخَةٌ يَا جَبَلَاه أَهْوَى بِهَا لِهَامَتِي وَقَالَ أَنْتَ جَبَلُهَا فَأَقُولُ لَا بَلِ اللهُ فَيَكُفُّ بَعْدَ أَهْوَائِهَا فَإِذَا صَرَخَتْ صَارِخَةٌ يَا عِزَّاه أَهْوَى بِهَا لِهَامَتِي وَقَالَ أَنْتَ عِزُّهَا فَأَقُولُ لَا بَلِ اللهُ فَيَكُفُّ بَعْدَ أَهْوَائِهَا', '', 'يَا رَسُولَ اللهِ رَأَيْتُ مَلَكًا مِنَ الْمَلَائِكَةِ بِيَدِهِ مِقْمَعَةٌ مِنْ حَدِيدٍ تَأَجَّجُ نَارًا وَكُلَّمَا صَرَخَتْ صَارِخَةٌ يَا جَبَلَاه أَهْوَى بِهَا لِهَامَتِي وَقَالَ أَنْتَ جَبَلُهَا فَأَقُولُ لَا بَلِ اللهُ فَيَكُفُّ بَعْدَ أَهْوَائِهَا فَإِذَا صَرَخَتْ صَارِخَةٌ يَا عِزَّاه أَهْوَى بِهَا لِهَامَتِي وَقَالَ أَنْتَ عِزُّهَا فَأَقُولُ لَا بَلِ اللهُ فَيَكُفُّ بَعْدَ أَهْوَائِهَا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingيا رسول الله رايت ملكا من الملايكه بيده مقمعه من حديد تاجج نارا وكلما صرخت صارخه يا جبلاه اهوي بها لهامتي وقال انت جبلها فاقول لا بل الله فيكف بعد اهوايها فاذا صرخت صارخه يا عزاه اهوي بها لهامتي وقال انت عزها فاقول لا بل الله فيكف بعد اهوايها', 'يا رسول الله رايت ملكا من الملايكه بيده مقمعه من حديد تاجج نارا وكلما صرخت صارخه يا جبلاه اهوي بها لهامتي وقال انت جبلها فاقول لا بل الله فيكف بعد اهوايها فاذا صرخت صارخه يا عزاه اهوي بها لهامتي وقال انت عزها فاقول لا بل الله فيكف بعد اهوايها');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 62, NULL, 'The Messenger of Allah said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'the messenger of allah said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 63, NULL, 'Sayingصَدَقَ عَبْدُ اللَّهِ فَمَا بَالُ مَوْتَاكُمْ يُبْتَلَوْنَ بِقَوْلِ أَحْيَائِكُمْ', '', 'صَدَقَ عَبْدُ اللَّهِ فَمَا بَالُ مَوْتَاكُمْ يُبْتَلَوْنَ بِقَوْلِ أَحْيَائِكُمْ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingصدق عبد الله فما بال موتاكم يبتلون بقول احيايكم', 'صدق عبد الله فما بال موتاكم يبتلون بقول احيايكم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 64, NULL, 'Abdullah has spoken the truth. What is the matter with your dead, that they should be made to suffer by the words of your living?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'abdullah has spoken the truth what is the matter with your dead that they should be made to suffer by the words of your living', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 65, NULL, 'Is there not, in this — and in less than this — enough for your living? The learned among you has come to know it; its signs and landmarks have been made plain before him. And yet he engages in a forbidden matter, walks a path that earns displeasure, and leaves his own ground unguarded. As for whoever conceals it from the one in authority over him and keeps it within his house among his household — he has broken the covenant of Allah that he took upon himself and retreated from his knowledge back into his ignorance.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'is there not in this and in less than this enough for your living the learned among you has come to know it its signs and landmarks have been made plain before him and yet he engages in a forbidden matter walks a path that earns displeasure and leaves his own ground unguarded as for whoever conceals it from the one in authority over him and keeps it within his house among his household he has broken the covenant of allah that he took upon himself and retreated from his knowledge back into his ignorance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 66, NULL, 'The noble book I have already named makes clear what is permitted in this matter and what is not, through its noble sayings — sayings that tell the one who conforms to them that he has attained. From Ali, the blessings of Allah be upon him, that he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'the noble book i have already named makes clear what is permitted in this matter and what is not through its noble sayings sayings that tell the one who conforms to them that he has attained from ali the blessings of allah be upon him that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 67, NULL, 'Sayingبَكَىٰ رَسُولُ اللَّهِ صَلَّىٰ اللَّهُ عَلَيْهِ وَآلِهِ عِنْدَ مَوْتِ بَعْضِ وَلَدِهِ فَقِيلَ لَهُ يَا رَسُولَ اللَّهِ تَبْكِي وَتَنْهَانَا عَنِ الْبُكَاءِ فَقَالَ لَمْ أَنْهَكُمْ عَنِ الْبُكَاءِ وَاِنَّمَا نَهَيْتُكُمْ عَنِ النَّوْحِ وَالْعَوِيلِ وَاِنَّمَا هَٰذِهِ رِقَّةٌ وَرَحْمَةٌ يَجْعَلُهَا اللَّهُ تَبَارَكَ وَتَعَالَىٰ فِي قَلْبِ مَنْ يَشَاءُ مِنْ خَلْقِهِ وَيَرْحَمُ اللَّهُ مَنْ يَشَاءُ وَإِنَّمَا يَرْحَمُ اللَّهُ مِنْ عِبَادِهِ الرُّحَمَاءَ', '', 'بَكَىٰ رَسُولُ اللَّهِ صَلَّىٰ اللَّهُ عَلَيْهِ وَآلِهِ عِنْدَ مَوْتِ بَعْضِ وَلَدِهِ فَقِيلَ لَهُ يَا رَسُولَ اللَّهِ تَبْكِي وَتَنْهَانَا عَنِ الْبُكَاءِ فَقَالَ لَمْ أَنْهَكُمْ عَنِ الْبُكَاءِ وَاِنَّمَا نَهَيْتُكُمْ عَنِ النَّوْحِ وَالْعَوِيلِ وَاِنَّمَا هَٰذِهِ رِقَّةٌ وَرَحْمَةٌ يَجْعَلُهَا اللَّهُ تَبَارَكَ وَتَعَالَىٰ فِي قَلْبِ مَنْ يَشَاءُ مِنْ خَلْقِهِ وَيَرْحَمُ اللَّهُ مَنْ يَشَاءُ وَإِنَّمَا يَرْحَمُ اللَّهُ مِنْ عِبَادِهِ الرُّحَمَاءَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingبكي رسول الله صلي الله عليه واله عند موت بعض ولده فقيل له يا رسول الله تبكي وتنهانا عن البكاء فقال لم انهكم عن البكاء وانما نهيتكم عن النوح والعويل وانما هذه رقه ورحمه يجعلها الله تبارك وتعالي في قلب من يشاء من خلقه ويرحم الله من يشاء وانما يرحم الله من عباده الرحماء', 'بكي رسول الله صلي الله عليه واله عند موت بعض ولده فقيل له يا رسول الله تبكي وتنهانا عن البكاء فقال لم انهكم عن البكاء وانما نهيتكم عن النوح والعويل وانما هذه رقه ورحمه يجعلها الله تبارك وتعالي في قلب من يشاء من خلقه ويرحم الله من يشاء وانما يرحم الله من عباده الرحماء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 68, NULL, 'The Messenger of Allah wept at the death of one of his children. Someone said to him, "O Messenger of Allah, you weep, yet you forbid us to weep?" He replied, "I did not forbid you from weeping. What I forbade was wailing and lamentation. This is nothing but tenderness and mercy — a mercy that Allah, blessed and exalted, places in the heart of whomever He wills among His creation. He shows mercy to whom He wills, and He shows mercy only to the merciful among His servants."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'the messenger of allah wept at the death of one of his children someone said to him o messenger of allah you weep yet you forbid us to weep he replied i did not forbid you from weeping what i forbade was wailing and lamentation this is nothing but tenderness and mercy a mercy that allah blessed and exalted places in the heart of whomever he wills among his creation he shows mercy to whom he wills and he shows mercy only to the merciful among his servants', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 69, NULL, 'And from him (ع), he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'and from him ع he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 70, NULL, 'Sayingرَخَّصَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ فِي الْبُكَاءِ عِنْدَ الْمُصِيبَةِ وَقَالَ النَّفْسُ مُصَابَةٌ وَالْعَيْنُ دَامِعَةٌ وَالْعَهْدُ قَرِيبٌ وَقُولُوا مَا أَرْضَى اللَّهَ وَلَا تَقُولُوا الْهُجْرَ', '', 'رَخَّصَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ فِي الْبُكَاءِ عِنْدَ الْمُصِيبَةِ وَقَالَ النَّفْسُ مُصَابَةٌ وَالْعَيْنُ دَامِعَةٌ وَالْعَهْدُ قَرِيبٌ وَقُولُوا مَا أَرْضَى اللَّهَ وَلَا تَقُولُوا الْهُجْرَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingرخص رسول الله صلي الله عليه واله في البكاء عند المصيبه وقال النفس مصابه والعين دامعه والعهد قريب وقولوا ما ارضي الله ولا تقولوا الهجر', 'رخص رسول الله صلي الله عليه واله في البكاء عند المصيبه وقال النفس مصابه والعين دامعه والعهد قريب وقولوا ما ارضي الله ولا تقولوا الهجر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 71, NULL, 'Let this, then, be your practice — in what you keep hidden and in what you make open alike. As for the accursed voice at a blessing — namely, singing — the noble book I have already named has likewise made clear what is permitted of it at banquets and weddings, so that lawful marriage may be distinguished from fornication and the permitted from the forbidden. These are the words of its author, whose pen has already dried upon them — may Allah sanctify his soul — narrating from the Messenger of Allah that he once passed by the Banu Zurayq, heard music, and said, "What is this?" They said, "O Messenger of Allah, so-and-so has married." He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'let this then be your practice in what you keep hidden and in what you make open alike as for the accursed voice at a blessing namely singing the noble book i have already named has likewise made clear what is permitted of it at banquets and weddings so that lawful marriage may be distinguished from fornication and the permitted from the forbidden these are the words of its author whose pen has already dried upon them may allah sanctify his soul narrating from the messenger of allah that he once passed by the banu zurayq heard music and said what is this they said o messenger of allah so and so has married he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 72, NULL, 'Sayingكَمَّلَ دِينَهُ هَذَا النِّكَاحُ لَا السِّفَاحُ وَلَا يَكُونُ نِكَاحٌ فِي السِّرِّ حَتَّى يُرَى دُخَانٌ أَوْ يُسْمَعَ حِسُّ دَفٍّ', '', 'كَمَّلَ دِينَهُ هَذَا النِّكَاحُ لَا السِّفَاحُ وَلَا يَكُونُ نِكَاحٌ فِي السِّرِّ حَتَّى يُرَى دُخَانٌ أَوْ يُسْمَعَ حِسُّ دَفٍّ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingكمل دينه هذا النكاح لا السفاح ولا يكون نكاح في السر حتي يري دخان او يسمع حس دف', 'كمل دينه هذا النكاح لا السفاح ولا يكون نكاح في السر حتي يري دخان او يسمع حس دف');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 73, NULL, 'His religion is complete. This is lawful marriage, not fornication. There is no marriage in secret, until smoke is seen or the sound of a tambourine is heard.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'his religion is complete this is lawful marriage not fornication there is no marriage in secret until smoke is seen or the sound of a tambourine is heard', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 74, NULL, 'And he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 75, NULL, 'Sayingاَلْفَرْقُ مَا بَيْنَ النِّكَاحِ وَالسِّفَاحِ ضَرْبُ الدُّفِّ', '', 'اَلْفَرْقُ مَا بَيْنَ النِّكَاحِ وَالسِّفَاحِ ضَرْبُ الدُّفِّ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingالفرق ما بين النكاح والسفاح ضرب الدف', 'الفرق ما بين النكاح والسفاح ضرب الدف');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 76, NULL, 'What sets lawful marriage apart from fornication is the beating of the tambourine.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'what sets lawful marriage apart from fornication is the beating of the tambourine', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 77, NULL, 'This, then, is what the sincere believer must hold fast to in each of these matters. Whoever turns away from it toward something else will find only ruin in all his affairs.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'this then is what the sincere believer must hold fast to in each of these matters whoever turns away from it toward something else will find only ruin in all his affairs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 78, NULL, 'Sayingوَأَنَّ فِي ذَلِكَ لَذِكْرَى لِمَنْ كَانَ لَهُ قَلْبٌ أَوْ أَلْقَى السَّمْعَ وَهُوَ شَهِيدٌ وَمَنْ عَمِلَ صَالِحًا فَلِنَفْسِهِ وَمَنْ أَسَاءَ فَعَلَيْهَا وَمَا رَبُّكَ بِظَلَّامٍ لِلْعَبِيدِ', '', 'وَأَنَّ فِي ذَلِكَ لَذِكْرَى لِمَنْ كَانَ لَهُ قَلْبٌ أَوْ أَلْقَى السَّمْعَ وَهُوَ شَهِيدٌ وَمَنْ عَمِلَ صَالِحًا فَلِنَفْسِهِ وَمَنْ أَسَاءَ فَعَلَيْهَا وَمَا رَبُّكَ بِظَلَّامٍ لِلْعَبِيدِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingوان في ذلك لذكري لمن كان له قلب او القي السمع وهو شهيد ومن عمل صالحا فلنفسه ومن اساء فعليها وما ربك بظلام للعبيد', 'وان في ذلك لذكري لمن كان له قلب او القي السمع وهو شهيد ومن عمل صالحا فلنفسه ومن اساء فعليها وما ربك بظلام للعبيد');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 79, NULL, 'In that is a reminder for whoever has a heart, or gives ear while present in mind. Whoever does righteousness does so for himself, and whoever does evil, it is against himself — and your Lord is never unjust to the servants.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'in that is a reminder for whoever has a heart or gives ear while present in mind whoever does righteousness does so for himself and whoever does evil it is against himself and your lord is never unjust to the servants', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 80, NULL, 'And our mawlana, the Commander of the Faithful, Ali ibn Abi Talib (ع), said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'and our mawlana the commander of the faithful ali ibn abi talib ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 81, NULL, 'Sayingوَأْمُرُوا أَهَالِيَكُمْ بِالْقَوْلِ الْحَسَنِ عِنْدَ مَوْتَاكُمْ فَاِنَّ فَاطِمَةَ بِنْتَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهَا لَمَّا قُبِضَ أَبُوهَا صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ أَشْعَرَهَا بَنَاتُ هَاشِمٍ فَقَالَتْ أَكْثِرُوا التِّحْدَادَ وَعَلَيْكُمْ بِالدُّعَاءِ', '', 'وَأْمُرُوا أَهَالِيَكُمْ بِالْقَوْلِ الْحَسَنِ عِنْدَ مَوْتَاكُمْ فَاِنَّ فَاطِمَةَ بِنْتَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهَا لَمَّا قُبِضَ أَبُوهَا صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ أَشْعَرَهَا بَنَاتُ هَاشِمٍ فَقَالَتْ أَكْثِرُوا التِّحْدَادَ وَعَلَيْكُمْ بِالدُّعَاءِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingوامروا اهاليكم بالقول الحسن عند موتاكم فان فاطمه بنت محمد صلي الله عليها لما قبض ابوها صلي الله عليه واله اشعرها بنات هاشم فقالت اكثروا التحداد وعليكم بالدعاء', 'وامروا اهاليكم بالقول الحسن عند موتاكم فان فاطمه بنت محمد صلي الله عليها لما قبض ابوها صلي الله عليه واله اشعرها بنات هاشم فقالت اكثروا التحداد وعليكم بالدعاء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 82, NULL, 'Command your households to speak well over your dead. When Fatimah, the daughter of Muhammad, lost her father, the daughters of Hashim mourned alongside her, and she said, "Grieve with restraint, and hold fast to supplication."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'command your households to speak well over your dead when fatimah the daughter of muhammad lost her father the daughters of hashim mourned alongside her and she said grieve with restraint and hold fast to supplication', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 83, NULL, 'He also said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'he also said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 84, NULL, 'Sayingمَنْ ضَرَبَ عَلَىٰ فَخِذِهِ عِنْدَ الْمُصِيبَةِ فَقَدْ حَبِطَ أَجْرُهُ', '', 'مَنْ ضَرَبَ عَلَىٰ فَخِذِهِ عِنْدَ الْمُصِيبَةِ فَقَدْ حَبِطَ أَجْرُهُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'sayingمن ضرب علي فخذه عند المصيبه فقد حبط اجره', 'من ضرب علي فخذه عند المصيبه فقد حبط اجره');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sickbed and the sound of mourning', '25. The Sickbed and the Sound of Mourning', 85, NULL, 'Whoever strikes his thigh at a calamity forfeits his reward.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 25 the sickbed and the sound of mourning', 'whoever strikes his thigh at a calamity forfeits his reward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 0, NULL, 'I turn now to the washing of the dead and to what belongs with it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'i turn now to the washing of the dead and to what belongs with it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 1, NULL, 'In the book of questions and answers arranged according to the order of the chapters of The Pillars of Islam, the following was asked. Question: what do you say concerning a man who washes the dead? Must he perform the ablution upon them three times together with three washings, or not? Answer: yes, he performs the ablution upon them three times together with three washings; and if he performs their ablution at the last of the washings, that suffices for them, as comes in the Book of Reports. From another place: if a man is wounded and is not moved from his place, and lives an hour, or two hours, or a day, and speaks, he is likewise not washed, because he was not lifted from his place.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'in the book of questions and answers arranged according to the order of the chapters of the pillars of islam the following was asked question what do you say concerning a man who washes the dead must he perform the ablution upon them three times together with three washings or not answer yes he performs the ablution upon them three times together with three washings and if he performs their ablution at the last of the washings that suffices for them as comes in the book of reports from another place if a man is wounded and is not moved from his place and lives an hour or two hours or a day and speaks he is likewise not washed because he was not lifted from his place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 2, NULL, 'Question: concerning one who dies while traveling and no water is to be found; or a man who dies among women with no woman of his own; or a woman who dies with no husband and no woman to be found who may wash her — must the dead in such cases be given tayammum with earth, or not? Answer: it is mentioned that if a man in a state of janabah and a dead person are together, and there is not enough water except for one of them, the man in janabah performs the washing and the dead is given tayammum; and these cases are like that. From another place: if a man dies, the washer washes the dead even while in janabah; and if washing would harm him, he performs tayammum and then washes the dead, and this is permitted when he finds no one else. And if the man in janabah is the more excellent of them, his washing of the dead is permitted.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'question concerning one who dies while traveling and no water is to be found or a man who dies among women with no woman of his own or a woman who dies with no husband and no woman to be found who may wash her must the dead in such cases be given tayammum with earth or not answer it is mentioned that if a man in a state of janabah and a dead person are together and there is not enough water except for one of them the man in janabah performs the washing and the dead is given tayammum and these cases are like that from another place if a man dies the washer washes the dead even while in janabah and if washing would harm him he performs tayammum and then washes the dead and this is permitted when he finds no one else and if the man in janabah is the more excellent of them his washing of the dead is permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 3, NULL, 'It is said in the Mukhtasar of al-Musannif that the nearest of those present to the dead has the best right to wash him. From the same book: if the martyr was in janabah, he is washed on account of the janabah. And if a man is found dead with no mark upon him, he is washed, treated with hanut, and shrouded.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'it is said in the mukhtasar of al musannif that the nearest of those present to the dead has the best right to wash him from the same book if the martyr was in janabah he is washed on account of the janabah and if a man is found dead with no mark upon him he is washed treated with hanut and shrouded', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 4, NULL, 'It is said in the Mukhtasar al-Athar that the drowned and the burned are washed, and so is a limb — when there is found of a man such a part that it is known he could not have lived once it was parted from him. Whatever falls from the dead is washed and placed with him. If his limbs, or any of them, have come apart, they are washed and each limb is set in its own place, and he is shrouded in that condition and buried. It is said in the Mukhtasar of al-Musannif that no hair is to be shaved from the dead and no nail is to be trimmed.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'it is said in the mukhtasar al athar that the drowned and the burned are washed and so is a limb when there is found of a man such a part that it is known he could not have lived once it was parted from him whatever falls from the dead is washed and placed with him if his limbs or any of them have come apart they are washed and each limb is set in its own place and he is shrouded in that condition and buried it is said in the mukhtasar of al musannif that no hair is to be shaved from the dead and no nail is to be trimmed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 5, NULL, 'Our master and lord Jafar, son of our master Sulayman, answered questions put to him by his servant, the author of this book, replying from the island of Yemen to the island of Hind. Among what I asked, I said: what do you say concerning a woman who dies? Is she wrapped in an إزار (izar) and washed as a man is wrapped, or is the end of her wrapper drawn behind her over her private parts and between her thighs until the other end comes round behind her, in the fashion used by the unbelievers and by others among the Muslims? For the Daudi group uses this and denounces whoever does not use it. Is that to be used when she is washed, or not? And is her wrapper to be so arranged in her shrouding, or not? For the Daudi group for the most part uses it in shrouding. They likewise use a ستارة (sitarah) when the dead is washed, screening the body from the women. Is nothing else permitted, or is there no harm in her being washed without a screen over her when she is at a distance from men?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'our master and lord jafar son of our master sulayman answered questions put to him by his servant the author of this book replying from the island of yemen to the island of hind among what i asked i said what do you say concerning a woman who dies is she wrapped in an ازار izar and washed as a man is wrapped or is the end of her wrapper drawn behind her over her private parts and between her thighs until the other end comes round behind her in the fashion used by the unbelievers and by others among the muslims for the daudi group uses this and denounces whoever does not use it is that to be used when she is washed or not and is her wrapper to be so arranged in her shrouding or not for the daudi group for the most part uses it in shrouding they likewise use a ستاره sitarah when the dead is washed screening the body from the women is nothing else permitted or is there no harm in her being washed without a screen over her when she is at a distance from men', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 6, NULL, 'The answer to that: nothing is mentioned in the book of the Pillars except that an إِزَار is placed upon the dead when he is washed, reaching from the navel to the knees, and the water is passed beneath it, and the washer wraps a cloth upon his hand and brings it in under the إِزَار and washes the private parts and the rest of the awrah that lies beneath the إِزَار. Practice rests upon that, and the manner you have described prevents its being done. The shrouding is likewise, and concerning it there has come in the book The Pillars of Islam, from Jafar ibn Muhammad (ع), that he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'the answer to that nothing is mentioned in the book of the pillars except that an ازار is placed upon the dead when he is washed reaching from the navel to the knees and the water is passed beneath it and the washer wraps a cloth upon his hand and brings it in under the ازار and washes the private parts and the rest of the awrah that lies beneath the ازار practice rests upon that and the manner you have described prevents its being done the shrouding is likewise and concerning it there has come in the book the pillars of islam from jafar ibn muhammad ع that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 7, NULL, 'Sayingنِعْمَ الْكَفَنُ ثَلَاثَةُ أَثْوَابٍ قَمِيصٌ غَيْرُ مَزْرُورٍ وَلَا مَكْفُوفٍ وَلِفَافَةٌ وَاِزَارٌ', '', 'نِعْمَ الْكَفَنُ ثَلَاثَةُ أَثْوَابٍ قَمِيصٌ غَيْرُ مَزْرُورٍ وَلَا مَكْفُوفٍ وَلِفَافَةٌ وَاِزَارٌ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'sayingنعم الكفن ثلاثه اثواب قميص غير مزرور ولا مكفوف ولفافه وازار', 'نعم الكفن ثلاثه اثواب قميص غير مزرور ولا مكفوف ولفافه وازار');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 8, NULL, 'The best shroud is three garments: a shirt neither buttoned nor hemmed, a wrapping sheet, and a waist wrapper. Know that. As for the matter of the screen in the washing of the dead — and above all of a woman — the better course is that it be done only within a covering.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'the best shroud is three garments a shirt neither buttoned nor hemmed a wrapping sheet and a waist wrapper know that as for the matter of the screen in the washing of the dead and above all of a woman the better course is that it be done only within a covering', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 9, NULL, 'And of what I asked, I said: what do you say concerning the meaning of the words of our master al-Qadi al-Numan ibn Muhammad in the Book of Purity, at the end of it, in the mention of the washing of the dead, where he says that the woman is bound up and is given the ajrah? What is the meaning of his word وتعجر? The answer to that: the عجرة (جُرْح) known in the lands of the Arabs, spelled with the undotted راء (ra), is the gathering of the shirt, drawing together that part of it which faces the navel down to below the navel over the clothing, and tucking it into the fastening of the إِزَار. That is a mark of difference between men and women, like the head covering which is a mark of difference between men and women. Know that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'and of what i asked i said what do you say concerning the meaning of the words of our master al qadi al numan ibn muhammad in the book of purity at the end of it in the mention of the washing of the dead where he says that the woman is bound up and is given the ajrah what is the meaning of his word وتعجر the answer to that the عجره جرح known in the lands of the arabs spelled with the undotted راء ra is the gathering of the shirt drawing together that part of it which faces the navel down to below the navel over the clothing and tucking it into the fastening of the ازار that is a mark of difference between men and women like the head covering which is a mark of difference between men and women know that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 10, NULL, 'Our lord the Commander of the Faithful, Ali ibn Abi Talib (ع), said in his Four Hundred Counsels:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'our lord the commander of the faithful ali ibn abi talib ع said in his four hundred counsels', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 11, NULL, 'Sayingمَنْ مَسَّ جَسَدَ الْمَيِّتِ بَعْدَ مَا بَرَدَ فَعَلَيْهِ الْغُسْلُ', '', 'مَنْ مَسَّ جَسَدَ الْمَيِّتِ بَعْدَ مَا بَرَدَ فَعَلَيْهِ الْغُسْلُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'sayingمن مس جسد الميت بعد ما برد فعليه الغسل', 'من مس جسد الميت بعد ما برد فعليه الغسل');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 12, NULL, 'Whoever touches the body of الميت after it has grown cold — برد جسد — must perform the washing.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'whoever touches the body of الميت after it has grown cold برد جسد must perform the washing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 13, NULL, 'And he said in it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'and he said in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 14, NULL, 'Sayingمَنْ غَسَّلَ مَيِّتًا فَلْيَغْتَسِلْ بَعْدَ مَا يُلْبِسُهُ الْكَفَنَ وَلَا يَمَسَّهُ بَعْدَ ذَلِكَ فَيَجِبُ عَلَيْهِ الْغُسْلُ', '', 'مَنْ غَسَّلَ مَيِّتًا فَلْيَغْتَسِلْ بَعْدَ مَا يُلْبِسُهُ الْكَفَنَ وَلَا يَمَسَّهُ بَعْدَ ذَلِكَ فَيَجِبُ عَلَيْهِ الْغُسْلُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'sayingمن غسل ميتا فليغتسل بعد ما يلبسه الكفن ولا يمسه بعد ذلك فيجب عليه الغسل', 'من غسل ميتا فليغتسل بعد ما يلبسه الكفن ولا يمسه بعد ذلك فيجب عليه الغسل');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 15, NULL, 'In the book of questions and answers already mentioned, I find this saying explained. Question: what do you say concerning the meaning of the words of the Commander of the Faithful (ع) — that whoever touches the body of the dead after it grows cold is bound to perform the washing? What is the meaning of "after it grows cold"? Answer: it means after his end has come upon him and he has been washed according to the sunnah by whoever washes him, because the body of the dead has become impure; when its moisture reaches a living man it renders him impure, and that is the meaning of the washing being binding upon him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'in the book of questions and answers already mentioned i find this saying explained question what do you say concerning the meaning of the words of the commander of the faithful ع that whoever touches the body of the dead after it grows cold is bound to perform the washing what is the meaning of after it grows cold answer it means after his end has come upon him and he has been washed according to the sunnah by whoever washes him because the body of the dead has become impure when its moisture reaches a living man it renders him impure and that is the meaning of the washing being binding upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 16, NULL, 'In the book of questions sent by certain dignitaries of Hind, answered by certain of our lords the summoners in the Yemeni peninsula, I find it written: you asked about a woman who gave birth to two children joined to one another — what is to be done with them, and if one of them dies, what is to be done with him. God, mighty and exalted, creates what He wills. If their adhesion is such that separation is possible, what lies between them is cut without harm to them and without danger, when the matter is slight; but if it is grave and dangerous, they are left as they are. In that case their death is one death and their life is one life, and God knows best, and He does what He wills. If one of them dies and not the other, whatever adheres to the living one is cut from the dead one, as long as the living one feels no sensation or pain from the cutting, if that is possible; the dead one is buried and the living one is left. But if pain is felt in the body of the other, then their life is but one life and their death but one death, and God knows best.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'in the book of questions sent by certain dignitaries of hind answered by certain of our lords the summoners in the yemeni peninsula i find it written you asked about a woman who gave birth to two children joined to one another what is to be done with them and if one of them dies what is to be done with him god mighty and exalted creates what he wills if their adhesion is such that separation is possible what lies between them is cut without harm to them and without danger when the matter is slight but if it is grave and dangerous they are left as they are in that case their death is one death and their life is one life and god knows best and he does what he wills if one of them dies and not the other whatever adheres to the living one is cut from the dead one as long as the living one feels no sensation or pain from the cutting if that is possible the dead one is buried and the living one is left but if pain is felt in the body of the other then their life is but one life and their death but one death and god knows best', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 17, NULL, 'As for the hanut and the shroud, I find it asked in the same book: what do you say concerning what comes in the Book of Reports — that the first thing taken from the estate of the dead is the shroud and his outfitting, then the debt, then the bequest? O our master, if the debt is greater than his estate, is his outfitting to be taken from it according to his station, even if it is costly? Answer: his shroud and his outfitting must be taken out according to his station.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'as for the hanut and the shroud i find it asked in the same book what do you say concerning what comes in the book of reports that the first thing taken from the estate of the dead is the shroud and his outfitting then the debt then the bequest o our master if the debt is greater than his estate is his outfitting to be taken from it according to his station even if it is costly answer his shroud and his outfitting must be taken out according to his station', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 18, NULL, 'From another place: the hanut is placed upon the places of prostration of the dead, and upon the private parts and the feet, and between the thumb and the forefinger, and upon the navel, the armpits, the breast, the mouth, the eyes, the nose, the forehead, the ears, and the hands at the palms, and the knees. A little oil, wheat, and perfume are put into the water on the third night, and the water is poured upon the grave on the third day. If the dead man is of the people of rank, the Quran is recited over his grave for seven days, and over the graves of others for three days; such has been the practice of our lords, may God lengthen their lives. It has come from our master Hasan ibn Idris that the Quran is recited for the people of rank seven times and for others three times, whether in the mosque, at the graves, in the house, or elsewhere.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'from another place the hanut is placed upon the places of prostration of the dead and upon the private parts and the feet and between the thumb and the forefinger and upon the navel the armpits the breast the mouth the eyes the nose the forehead the ears and the hands at the palms and the knees a little oil wheat and perfume are put into the water on the third night and the water is poured upon the grave on the third day if the dead man is of the people of rank the quran is recited over his grave for seven days and over the graves of others for three days such has been the practice of our lords may god lengthen their lives it has come from our master hasan ibn idris that the quran is recited for the people of rank seven times and for others three times whether in the mosque at the graves in the house or elsewhere', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 19, NULL, 'In the Mukhtasar al-Athar, I find that the hanut is whatever is of perfume, but neither wars nor saffron is put into the hanut of men, while these are put into the hanut of women. In the Book of Purity, I find that the hanut and the camphor are placed upon the forehead and the nose, the insides of the palms, the knees, and the tops of the feet — these being the places of prostration. From the same book: cotton is placed upon the face, under the armpits, and between the knees, the shins, and the feet, if it is to be had.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'in the mukhtasar al athar i find that the hanut is whatever is of perfume but neither wars nor saffron is put into the hanut of men while these are put into the hanut of women in the book of purity i find that the hanut and the camphor are placed upon the forehead and the nose the insides of the palms the knees and the tops of the feet these being the places of prostration from the same book cotton is placed upon the face under the armpits and between the knees the shins and the feet if it is to be had', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 20, NULL, 'In the Tawil al-Daaim, I find that the sunnah concerning the incensing of the dead is this: the dead man himself is not incensed, nor is his bier followed with incense; rather his shroud is incensed, and the place in which he is washed and shrouded — and nothing beyond that. And our lord the Commander of the Faithful, Ali ibn Abi Talib (ع), said in his Four Hundred Counsels:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'in the tawil al daaim i find that the sunnah concerning the incensing of the dead is this the dead man himself is not incensed nor is his bier followed with incense rather his shroud is incensed and the place in which he is washed and shrouded and nothing beyond that and our lord the commander of the faithful ali ibn abi talib ع said in his four hundred counsels', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 21, NULL, 'Sayingوَلَا تُجَمِّرُوا مَوْتَاكُمْ وَلَا تَمَسُّوهُمْ بِالطِّيبِ اِلَّا بِالْكَافُورِ فَاِنَّ الْمَيِّتَ بِمَنْزِلَةِ الْمُحْرِمِ', '', 'وَلَا تُجَمِّرُوا مَوْتَاكُمْ وَلَا تَمَسُّوهُمْ بِالطِّيبِ اِلَّا بِالْكَافُورِ فَاِنَّ الْمَيِّتَ بِمَنْزِلَةِ الْمُحْرِمِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'sayingولا تجمروا موتاكم ولا تمسوهم بالطيب الا بالكافور فان الميت بمنزله المحرم', 'ولا تجمروا موتاكم ولا تمسوهم بالطيب الا بالكافور فان الميت بمنزله المحرم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 22, NULL, 'Do not perfume your dead with incense, and do not touch them with any fragrance except camphor, for the dead man is in the position of one consecrated for pilgrimage.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'do not perfume your dead with incense and do not touch them with any fragrance except camphor for the dead man is in the position of one consecrated for pilgrimage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 23, NULL, 'In a book of legal questions, all of them remarkable, I find another question: what do you say concerning a man who died, whose head and face were not covered and to whom nothing of the hanut was brought near when he died and was shrouded? Answer: that man died as a pilgrim in a state of consecration, so his head and his face are not covered, and nothing of perfume is brought near him, because he is consecrated during days that are numbered.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'in a book of legal questions all of them remarkable i find another question what do you say concerning a man who died whose head and face were not covered and to whom nothing of the hanut was brought near when he died and was shrouded answer that man died as a pilgrim in a state of consecration so his head and his face are not covered and nothing of perfume is brought near him because he is consecrated during days that are numbered', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 24, NULL, 'As for walking with the bier, I find it asked in the same book: what do you say concerning what comes in the law commanding that one walk behind the bier? O our master, does a man sin if he walks before it, or not? Answer: it is mentioned in the Book of Reports that walking is disliked only before the bier of an enemy of the family, because of the angels of wrath that come to it. As for the believers, it matters not where you walk in relation to the bier, since the angels of mercy encompass it. Yet walking behind it is the more excellent. I find it stated in the Book of Reports that they disliked the call to prayer at the bier, and permitted the informing of people of the death without a public call.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'as for walking with the bier i find it asked in the same book what do you say concerning what comes in the law commanding that one walk behind the bier o our master does a man sin if he walks before it or not answer it is mentioned in the book of reports that walking is disliked only before the bier of an enemy of the family because of the angels of wrath that come to it as for the believers it matters not where you walk in relation to the bier since the angels of mercy encompass it yet walking behind it is the more excellent i find it stated in the book of reports that they disliked the call to prayer at the bier and permitted the informing of people of the death without a public call', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 25, NULL, 'In the Tawil al-Daaim, I find that what is required is this: no one should rise for the bier when it passes except one who intends to follow it, and he should not sit down until it has been set at the edge of the grave. From the Mukhtasar al-Athar: when the dead is brought to the burial ground, the bier is set down crosswise, the dead lying upon his back upon it, so that his right side is toward the qibla and his left toward the one who prays.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'in the tawil al daaim i find that what is required is this no one should rise for the bier when it passes except one who intends to follow it and he should not sit down until it has been set at the edge of the grave from the mukhtasar al athar when the dead is brought to the burial ground the bier is set down crosswise the dead lying upon his back upon it so that his right side is toward the qibla and his left toward the one who prays', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 26, NULL, 'From the Tawil al-Daaim, and of that is what is related of the Messenger of God (ع):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'from the tawil al daaim and of that is what is related of the messenger of god ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 27, NULL, 'Sayingنَظَرَ إِلَى النِّسَاءِ يَتْبَعْنَ جَنَازَةً فَوَقَفَ وَقَالَ لَهُنَّ تُصَلِّينَ عَلَيْهَا فِي مَنْ يُصَلِّي قُلْنَ لَا قَالَ فَتَحْمِلْنَهَا فِي مَنْ يَحْمِلُهَا قُلْنَ لَا قَالَ فَتَنْزِلْنَ لَهَا فِي الْقَبْرِ فِي مَنْ يَنْزِلُهَا قُلْنَ لَا قَالَ فَتُوَارِينَهَا فِي مَنْ يُوَارِيهَا قُلْنَ لَا قَالَ فَارْجِعْنَ مَعْذُورَاتٍ غَيْرَ مَأْجُورَاتٍ', '', 'نَظَرَ إِلَى النِّسَاءِ يَتْبَعْنَ جَنَازَةً فَوَقَفَ وَقَالَ لَهُنَّ تُصَلِّينَ عَلَيْهَا فِي مَنْ يُصَلِّي قُلْنَ لَا قَالَ فَتَحْمِلْنَهَا فِي مَنْ يَحْمِلُهَا قُلْنَ لَا قَالَ فَتَنْزِلْنَ لَهَا فِي الْقَبْرِ فِي مَنْ يَنْزِلُهَا قُلْنَ لَا قَالَ فَتُوَارِينَهَا فِي مَنْ يُوَارِيهَا قُلْنَ لَا قَالَ فَارْجِعْنَ مَعْذُورَاتٍ غَيْرَ مَأْجُورَاتٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'sayingنظر الي النساء يتبعن جنازه فوقف وقال لهن تصلين عليها في من يصلي قلن لا قال فتحملنها في من يحملها قلن لا قال فتنزلن لها في القبر في من ينزلها قلن لا قال فتوارينها في من يواريها قلن لا قال فارجعن معذورات غير ماجورات', 'نظر الي النساء يتبعن جنازه فوقف وقال لهن تصلين عليها في من يصلي قلن لا قال فتحملنها في من يحملها قلن لا قال فتنزلن لها في القبر في من ينزلها قلن لا قال فتوارينها في من يواريها قلن لا قال فارجعن معذورات غير ماجورات');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 28, NULL, 'The Mukhtasar al-Athar records that we have transmitted from the Imams of the household of the Messenger of God (ع) that they commanded the following: once the deceased has been shrouded, he is placed upon his bier and laid upon it, when a bier is to be had and this is possible; men carry him on their shoulders, when men can be found. If that is not possible, he is carried on a beast or by whatever other means are available. His shroud is covered from above with a cloth, if one is to be had. A canopy is erected over the bier and it is screened with a cloth; and the deceased is secured if there is fear he may fall from the bier.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'the mukhtasar al athar records that we have transmitted from the imams of the household of the messenger of god ع that they commanded the following once the deceased has been shrouded he is placed upon his bier and laid upon it when a bier is to be had and this is possible men carry him on their shoulders when men can be found if that is not possible he is carried on a beast or by whatever other means are available his shroud is covered from above with a cloth if one is to be had a canopy is erected over the bier and it is screened with a cloth and the deceased is secured if there is fear he may fall from the bier', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 29, NULL, 'On the prayer over the dead, the same book was asked: What do you say concerning a man who dies in a place where no authorized man is present, though an authorized woman is? May she lead the women in the funeral prayer, or should the men pray over him individually and he then be buried? Answer: The prayer of a man is more in keeping with the teaching of the People of the House (عَلَيْهِمُ السَّلَامُ).', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'on the prayer over the dead the same book was asked what do you say concerning a man who dies in a place where no authorized man is present though an authorized woman is may she lead the women in the funeral prayer or should the men pray over him individually and he then be buried answer the prayer of a man is more in keeping with the teaching of the people of the house عليهم السلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 30, NULL, 'Question: What of the prayer over the dead — is it permitted to pray over him after he has been carried from the place where he was prepared, or not until he reaches the burial ground? Answer: He may be prayed over wherever one wishes: in the burial ground, in his house, or anywhere else. Whoever wishes may recite the supplication between the takbirs of the funeral prayer; whoever wishes may leave it and be content with the imam. The funeral prayer is also permitted during the disliked hours and at the time of an eclipse.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'question what of the prayer over the dead is it permitted to pray over him after he has been carried from the place where he was prepared or not until he reaches the burial ground answer he may be prayed over wherever one wishes in the burial ground in his house or anywhere else whoever wishes may recite the supplication between the takbirs of the funeral prayer whoever wishes may leave it and be content with the imam the funeral prayer is also permitted during the disliked hours and at the time of an eclipse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 31, NULL, 'The Majalis al-Bayan states that the funeral prayer is a communal obligation upon every Muslim who knows of it, until one of them has performed it, after which the rest participate as volunteers. The Reports record, on the authority of transmitters from the People of the House (عَلَيْهِمُ السَّلَامُ), that it is recommended to pray over the bier within the appointed prayer times, provided there is no risk of missing the prescribed prayer; if that risk exists, one begins with the prescribed prayer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'the majalis al bayan states that the funeral prayer is a communal obligation upon every muslim who knows of it until one of them has performed it after which the rest participate as volunteers the reports record on the authority of transmitters from the people of the house عليهم السلام that it is recommended to pray over the bier within the appointed prayer times provided there is no risk of missing the prescribed prayer if that risk exists one begins with the prescribed prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 32, NULL, 'The Tawil al-Daaim likewise states: when the imam of the age is absent, whoever has been appointed judge by him, or given charge by him of some affair of the Muslims, has the better right to the prayer over the dead. If a company of those brought near by the imam''s command is present, or of those whom the imam has advanced, the right belongs to the highest among them in station; if only one such person is present, he has a better right to the prayer than the deceased''s guardian, being someone the imam has set up, or set up for some affair of the Muslims. Whoever is appointed to lead the people in prayer, if he is present at the bier, has the better right to pray over it. If none of these persons is present, then the most entitled of the guardians has the best right to pray over it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'the tawil al daaim likewise states when the imam of the age is absent whoever has been appointed judge by him or given charge by him of some affair of the muslims has the better right to the prayer over the dead if a company of those brought near by the imams command is present or of those whom the imam has advanced the right belongs to the highest among them in station if only one such person is present he has a better right to the prayer than the deceaseds guardian being someone the imam has set up or set up for some affair of the muslims whoever is appointed to lead the people in prayer if he is present at the bier has the better right to pray over it if none of these persons is present then the most entitled of the guardians has the best right to pray over it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 33, NULL, 'The Mukhtasar al-Athar further states that the funeral prayer is offered over the martyr, over those who have committed grave sins and offenses, and over one killed in execution of a prescribed punishment or in retaliation. The Mukhtasar of al-Musannif adds that the supplication is recited quietly during a daytime funeral prayer and aloud during a nighttime one, and that the prayer is offered over one who has taken his own life. From the same book: the deceased''s knots are loosened, his right hand is brought out from beneath his side, and his cheek is laid against the earth. If a woman dies carrying a child of six months or more in her womb, the child is taken out if that is possible.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'the mukhtasar al athar further states that the funeral prayer is offered over the martyr over those who have committed grave sins and offenses and over one killed in execution of a prescribed punishment or in retaliation the mukhtasar of al musannif adds that the supplication is recited quietly during a daytime funeral prayer and aloud during a nighttime one and that the prayer is offered over one who has taken his own life from the same book the deceaseds knots are loosened his right hand is brought out from beneath his side and his cheek is laid against the earth if a woman dies carrying a child of six months or more in her womb the child is taken out if that is possible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 34, NULL, 'Our master and lord Jafar ibn Sulayman — in his answers to questions put to him by his servant, the author of this book, replying from the island of Yemen to the island of Hind — answered what I asked when I said: What do you say concerning a bier at which one is present, when the imam has come forward to pray over it? Is his recitation of the supplication in the prayer sufficient, or ought the one who follows him to recite it himself as well, given that it is by day? The answer to that: it has come in the book of legal questions and answers that whoever wishes may recite the supplication between the takbirs of the funeral prayer, and whoever wishes may leave it and be content with the imam''s recitation. Know that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'our master and lord jafar ibn sulayman in his answers to questions put to him by his servant the author of this book replying from the island of yemen to the island of hind answered what i asked when i said what do you say concerning a bier at which one is present when the imam has come forward to pray over it is his recitation of the supplication in the prayer sufficient or ought the one who follows him to recite it himself as well given that it is by day the answer to that it has come in the book of legal questions and answers that whoever wishes may recite the supplication between the takbirs of the funeral prayer and whoever wishes may leave it and be content with the imams recitation know that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 35, NULL, 'As for burial and the graves, it was asked in the same book: What do you say concerning what the law stipulates — that whatever falls from a man while he is alive is to be buried in the earth? O our master, may he bury it wherever he wishes, or only in the burial ground? And if he leaves it and does not bury it, does he sin in that or not? Answer: He buries it wherever he wishes, and there is no blame upon him if it is lost.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'as for burial and the graves it was asked in the same book what do you say concerning what the law stipulates that whatever falls from a man while he is alive is to be buried in the earth o our master may he bury it wherever he wishes or only in the burial ground and if he leaves it and does not bury it does he sin in that or not answer he buries it wherever he wishes and there is no blame upon him if it is lost', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 36, NULL, 'Question: What do you say concerning a man in whose land people have buried their dead without his leave, and who, when he came to know of it, wished to have them removed? Is that permitted to him or not? Answer: It is not permitted that burial be made in his land except with his leave; but since they did that without his consent, he has nothing but the value of the places of the graves, and it is not permitted to him to have them removed.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'question what do you say concerning a man in whose land people have buried their dead without his leave and who when he came to know of it wished to have them removed is that permitted to him or not answer it is not permitted that burial be made in his land except with his leave but since they did that without his consent he has nothing but the value of the places of the graves and it is not permitted to him to have them removed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 37, NULL, 'Question: What do you say concerning what the law commands — the burial of the dead where they fell and the prohibition of moving them? O our master, if the burial ground is far off, how is one to act? Answer: The deceased is buried in the place where he dies, in the burial ground of the people of that town, and he is not to be carried to another town. But if he dies in open wilderness, there is no harm in his being carried to the nearest burial ground.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'question what do you say concerning what the law commands the burial of the dead where they fell and the prohibition of moving them o our master if the burial ground is far off how is one to act answer the deceased is buried in the place where he dies in the burial ground of the people of that town and he is not to be carried to another town but if he dies in open wilderness there is no harm in his being carried to the nearest burial ground', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 38, NULL, 'Question: What do you say concerning a woman who dies when there is not to be found in the town any male relative who may lawfully look upon her? Who shall lower her into the grave? Answer: If a woman dies and no kinsman to whom looking upon her is lawful is present at her grave, then the person nearest to her undertakes the burial; and if such a one is lacking, upright men other than her kin bury her out of necessity.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'question what do you say concerning a woman who dies when there is not to be found in the town any male relative who may lawfully look upon her who shall lower her into the grave answer if a woman dies and no kinsman to whom looking upon her is lawful is present at her grave then the person nearest to her undertakes the burial and if such a one is lacking upright men other than her kin bury her out of necessity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 39, NULL, 'Question: What do you say concerning what comes in the books of the rightly guiding summons — that mud bricks, wood, or whatever else one wishes are placed over the dead, and that if earth is heaped over him it is well? O our master, is it permitted to place over him baked brick, stone, and whatever else is to be found? For the people of the outward sense dislike baked brick. How does the matter stand — may God make us your ransom? Answer: It is permitted to place over him baked brick and whatever else is to be found. Rely upon this and pay no regard to anything else, save what may be done for prudent concealment.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'question what do you say concerning what comes in the books of the rightly guiding summons that mud bricks wood or whatever else one wishes are placed over the dead and that if earth is heaped over him it is well o our master is it permitted to place over him baked brick stone and whatever else is to be found for the people of the outward sense dislike baked brick how does the matter stand may god make us your ransom answer it is permitted to place over him baked brick and whatever else is to be found rely upon this and pay no regard to anything else save what may be done for prudent concealment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 40, NULL, 'And our lord the Commander of the Faithful, Ali ibn Abi Talib (ع), said in his Four Hundred Counsels:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'and our lord the commander of the faithful ali ibn abi talib ع said in his four hundred counsels', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 41, NULL, 'Sayingأَلِمُّوا بِالْقُبُورِ الَّتِي يَلْزَمُكُمْ حَقُّ سُكَّانِهَا وَزُورُوهَا وَاطْلُبُوا الرِّزْقَ عِنْدَهَا فَأِنَّهُمْ يَفْرَحُونَ بِزِيَارَتِكُمْ وَلْيَطْلُبِ الرَّجُلُ الْحَاجَةَ عِنْدَ قَبْرِ أَبِيهِ وَأُمِّهِ بَعْدَ مَا يَدْعُو لَهُمَا', '', 'أَلِمُّوا بِالْقُبُورِ الَّتِي يَلْزَمُكُمْ حَقُّ سُكَّانِهَا وَزُورُوهَا وَاطْلُبُوا الرِّزْقَ عِنْدَهَا فَأِنَّهُمْ يَفْرَحُونَ بِزِيَارَتِكُمْ وَلْيَطْلُبِ الرَّجُلُ الْحَاجَةَ عِنْدَ قَبْرِ أَبِيهِ وَأُمِّهِ بَعْدَ مَا يَدْعُو لَهُمَا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'sayingالموا بالقبور التي يلزمكم حق سكانها وزوروها واطلبوا الرزق عندها فانهم يفرحون بزيارتكم وليطلب الرجل الحاجه عند قبر ابيه وامه بعد ما يدعو لهما', 'الموا بالقبور التي يلزمكم حق سكانها وزوروها واطلبوا الرزق عندها فانهم يفرحون بزيارتكم وليطلب الرجل الحاجه عند قبر ابيه وامه بعد ما يدعو لهما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'washing, shrouding, carrying, burying', '26. Washing, Shrouding, Carrying, Burying', 42, NULL, 'Visit the graves of those who have a claim upon you. Go to them, and seek provision at their graves, for they rejoice at your visiting. Let a man ask for what he needs at the grave of his father and his mother, after he has prayed for them both.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 26 washing shrouding carrying burying', 'visit the graves of those who have a claim upon you go to them and seek provision at their graves for they rejoice at your visiting let a man ask for what he needs at the grave of his father and his mother after he has prayed for them both', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 0, NULL, 'I come now to the Book of Zakat and to what has been handed down concerning the merit of giving zakat and the matters bound up with it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'i come now to the book of zakat and to what has been handed down concerning the merit of giving zakat and the matters bound up with it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 1, NULL, 'Our master Jafar ibn Mansur al-Yaman, may God sanctify him and grant us his intercession and his company, spoke in the book of inward nursing, citing the word of the Messenger of Allah:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'our master jafar ibn mansur al yaman may god sanctify him and grant us his intercession and his company spoke in the book of inward nursing citing the word of the messenger of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 2, NULL, 'Sayingلا تحل الصدقة لي ولا لأهل بيتي', '', 'لا تحل الصدقة لي ولا لأهل بيتي', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'sayingلا تحل الصدقه لي ولا لاهل بيتي', 'لا تحل الصدقه لي ولا لاهل بيتي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 3, NULL, 'Charity is not lawful for me, nor for the people of my house.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'charity is not lawful for me nor for the people of my house', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 4, NULL, 'And he said in it: As for one whose scope in the call, after what is incumbent upon him has been discharged, is that his excellence appear outwardly — in that he has abundance of wealth — he pays from his wealth what he wills, apart from the fitra, of the obligatory rights and of voluntary giving. And he said in it: Whoever pays the khums is thereby excused from paying the tithe, except as a voluntary act; but whoever pays the tithe alone is not thereby excused from paying the khums that is due from him, because the tithe does not encompass the khums as the khums encompasses the tithe. And the Prophet said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'and he said in it as for one whose scope in the call after what is incumbent upon him has been discharged is that his excellence appear outwardly in that he has abundance of wealth he pays from his wealth what he wills apart from the fitra of the obligatory rights and of voluntary giving and he said in it whoever pays the khums is thereby excused from paying the tithe except as a voluntary act but whoever pays the tithe alone is not thereby excused from paying the khums that is due from him because the tithe does not encompass the khums as the khums encompasses the tithe and the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 5, NULL, 'Sayingلَا صَلَاةَ لِمَنْ لَا يُؤَدِّي الزَّكَاةَ', '', 'لَا صَلَاةَ لِمَنْ لَا يُؤَدِّي الزَّكَاةَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'sayingلا صلاه لمن لا يودي الزكاه', 'لا صلاه لمن لا يودي الزكاه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 6, NULL, 'There is no prayer for one who does not pay zakat.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'there is no prayer for one who does not pay zakat', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 7, NULL, 'Our master Zayd ibn Muhammad, may God sanctify him, said in the Hidden Epistle: God Almighty has imposed zakat upon ten things, and they are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'our master zayd ibn muhammad may god sanctify him said in the hidden epistle god almighty has imposed zakat upon ten things and they are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 8, NULL, 'gold silver camels cows sheep dates raisins wheat barley grains', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'gold silver camels cows sheep dates raisins wheat barley grains', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 9, NULL, 'And Mawlana Amir al-Muminin Ali ibn Abi Talib (ع) said in his Four Hundred Counsels:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'and mawlana amir al muminin ali ibn abi talib ع said in his four hundred counsels', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 10, NULL, 'Sayingدَاوُوا مَرْضَاكُمْ بِالصَّدَقَةِ وَحَصِّنُوا أَمْوَالَكُمْ بِالزَّكَاةِ', '', 'دَاوُوا مَرْضَاكُمْ بِالصَّدَقَةِ وَحَصِّنُوا أَمْوَالَكُمْ بِالزَّكَاةِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'sayingداووا مرضاكم بالصدقه وحصنوا اموالكم بالزكاه', 'داووا مرضاكم بالصدقه وحصنوا اموالكم بالزكاه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 11, NULL, 'Treat your sick with charity, and fortify your wealth with zakat.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'treat your sick with charity and fortify your wealth with zakat', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 12, NULL, 'Our master and Mawlana, the author of the Mustansiriyya Councils, (ع), said in the twelfth council of them: You have heard what we recited to you in what came before, of the jurisprudence of guardianship and purity and prayer, by which the sincerity of the testimony is completed — that testimony which is the root of religion and worship, and the first of the causes of mercy and felicity. So listen now to what we recite to you concerning zakat, which is among its rights according to what has already been said. Its sincerity is the knowledge of its noble boundaries, and the fulfilling of its rights is the performance of the seven obligations that are the pillars of Islam, according to the order we have already set out. In zakat likewise there are seven obligations and twelve sunnahs, like the number of the clauses of the testimony and its letters. Zakat must be received by the Imam, and it is taken from seven things:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'our master and mawlana the author of the mustansiriyya councils ع said in the twelfth council of them you have heard what we recited to you in what came before of the jurisprudence of guardianship and purity and prayer by which the sincerity of the testimony is completed that testimony which is the root of religion and worship and the first of the causes of mercy and felicity so listen now to what we recite to you concerning zakat which is among its rights according to what has already been said its sincerity is the knowledge of its noble boundaries and the fulfilling of its rights is the performance of the seven obligations that are the pillars of islam according to the order we have already set out in zakat likewise there are seven obligations and twelve sunnahs like the number of the clauses of the testimony and its letters zakat must be received by the imam and it is taken from seven things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 13, NULL, 'gold silver camels cows sheep crops minerals', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'gold silver camels cows sheep crops minerals', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 14, NULL, 'And it is disbursed to eight who are named, who fall into seven divisions:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'and it is disbursed to eight who are named who fall into seven divisions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 15, NULL, 'the poor and the needy, who are given charity from it those who labor in its collection, who are given from it the wage of collection those whose hearts are to be reconciled, who are paid from it as a bond of protection and in the freeing of necks, by which those under bondage of service are set free from it the debt-burdened, whose debts are discharged from it among the people of allegiance and in the way of God, meaning the struggle that is an obligation of sufficiency and the wayfarer, those cut off from the road of guidance', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'the poor and the needy who are given charity from it those who labor in its collection who are given from it the wage of collection those whose hearts are to be reconciled who are paid from it as a bond of protection and in the freeing of necks by which those under bondage of service are set free from it the debt burdened whose debts are discharged from it among the people of allegiance and in the way of god meaning the struggle that is an obligation of sufficiency and the wayfarer those cut off from the road of guidance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 16, NULL, 'As for its twelve sunnahs:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'as for its twelve sunnahs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 17, NULL, 'that it not be taken until the year has run its course that the nisab of gold is twenty dinars that the nisab of silver is two hundred dirhams that the nisab of camels is five grazing head that the nisab of cows is thirty grazing head that the nisab of sheep is forty head that the zakat is taken from the middling of the livestock, which is what is below the best of them and above the poorest of them that what is separate among them is not joined together, nor is what is joined together divided that the stud animal is not taken from them that the owner of crops gives charity from what has not reached the nisab, which is five awsaq, by the bundle and by the handful, at the time of his harvest, for the saying of God Almighty:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'that it not be taken until the year has run its course that the nisab of gold is twenty dinars that the nisab of silver is two hundred dirhams that the nisab of camels is five grazing head that the nisab of cows is thirty grazing head that the nisab of sheep is forty head that the zakat is taken from the middling of the livestock which is what is below the best of them and above the poorest of them that what is separate among them is not joined together nor is what is joined together divided that the stud animal is not taken from them that the owner of crops gives charity from what has not reached the nisab which is five awsaq by the bundle and by the handful at the time of his harvest for the saying of god almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 18, NULL, 'Al-An''am: 141﴿وَآتُوا حَقَّهُ يَوْمَ حَصَادِهِ﴾', '', '﴿وَآتُوا حَقَّهُ يَوْمَ حَصَادِهِ﴾', 'Al-An''am: 141', 6, 141, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'al anam 141 واتوا حقه يوم حصاده', 'واتوا حقه يوم حصاده');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 19, NULL, 'And give its due on the day of its harvest.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'and give its due on the day of its harvest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 20, NULL, 'that there is no zakat upon dwellings, nor upon ornaments, nor upon anything that is for use.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'that there is no zakat upon dwellings nor upon ornaments nor upon anything that is for use', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 21, NULL, 'Every word of this speech carries abundant meanings and traces of wisdom.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'every word of this speech carries abundant meanings and traces of wisdom', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 22, NULL, 'I set down next what has been said concerning the severity of the matter in the giving of zakat. It is stated in the book of questions and answers already mentioned, which one of its arrangers ordered according to the arrangement of the chapters of the book Daaim al-Islam.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'i set down next what has been said concerning the severity of the matter in the giving of zakat it is stated in the book of questions and answers already mentioned which one of its arrangers ordered according to the arrangement of the chapters of the book daaim al islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 23, NULL, 'Question: What do you say concerning what has come in the Sharia forbidding that a man conceal the zakat of his wealth from his imam? Our master, who is meant by it — the one who withholds zakat, or another? And how does a man conceal zakat from his imam if he is giving it to him openly? Answer: This report concerns one who brings out a part of the zakat. As for the one who withholds it, he has abandoned the obligation altogether.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'question what do you say concerning what has come in the sharia forbidding that a man conceal the zakat of his wealth from his imam our master who is meant by it the one who withholds zakat or another and how does a man conceal zakat from his imam if he is giving it to him openly answer this report concerns one who brings out a part of the zakat as for the one who withholds it he has abandoned the obligation altogether', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 24, NULL, 'Question: What do you say concerning what has come in the book of Daaim, that the Messenger of Allah said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'question what do you say concerning what has come in the book of daaim that the messenger of allah said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 25, NULL, 'Sayingإِنَّا أَهْلَ الْبَيْتِ لَا تَحِلُّ لَنَا الصَّدَقَةُ', '', 'إِنَّا أَهْلَ الْبَيْتِ لَا تَحِلُّ لَنَا الصَّدَقَةُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'sayingانا اهل البيت لا تحل لنا الصدقه', 'انا اهل البيت لا تحل لنا الصدقه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 26, NULL, 'We, the people of the House — charity is not lawful for us.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'we the people of the house charity is not lawful for us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 27, NULL, 'Our master, does this refer to the Imams, or to all his descendants through Fatima (ع)? Answer: It refers to the Imams (عَلَيْهِمُ السَّلَامُ).', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'our master does this refer to the imams or to all his descendants through fatima ع answer it refers to the imams عليهم السلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 28, NULL, 'Question: The book Daaim al-Islam states that charity is not lawful except for five, one of whom is a man who has undertaken a hamala. Our master, what does hamala mean here? Answer: It is either a penalty imposed by a tyrannical ruler, or the bearing of blood money on behalf of the aqila.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'question the book daaim al islam states that charity is not lawful except for five one of whom is a man who has undertaken a hamala our master what does hamala mean here answer it is either a penalty imposed by a tyrannical ruler or the bearing of blood money on behalf of the aqila', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 29, NULL, 'Question: From the book of Daaim, in the covenant that Amir al-Muminin wrote to Muhnaf ibn Sulaym: whoever belongs to the people of our obedience in the territory between the Jazira, Kufa, and the land of Syria, and claims to have paid his charity to the officials of Syria while residing within our domain — held back and encompassed by our horsemen and foot soldiers — that is not permitted to him. Even if the matter is as he claims, he may not dwell in our lands and pay the charity of his wealth to our enemy. What is the ruling here? And does the seizure of the land of India by a ruler through his horsemen and his men make the zakat due to him or not? Answer: The covenant that Amir al-Muminin (ع) wrote to Muhnaf ibn Sulaym — and his statement that whatever territory his horsemen and foot soldiers have not encompassed is not to be assessed for zakat — means that zakat is not demanded from one whom the enemy has seized who is not of the Shia who hold to the allegiance. For it has come down from the people of the House, God''s blessings upon them, in the book of Daaim and elsewhere, that whoever hands over zakat to other than the one whom God — mighty and majestic — commanded it be handed to, it does not suffice him, even if it is later plundered or stolen, until he hands it to the guardian of the affair or to one who receives it by his command.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'question from the book of daaim in the covenant that amir al muminin wrote to muhnaf ibn sulaym whoever belongs to the people of our obedience in the territory between the jazira kufa and the land of syria and claims to have paid his charity to the officials of syria while residing within our domain held back and encompassed by our horsemen and foot soldiers that is not permitted to him even if the matter is as he claims he may not dwell in our lands and pay the charity of his wealth to our enemy what is the ruling here and does the seizure of the land of india by a ruler through his horsemen and his men make the zakat due to him or not answer the covenant that amir al muminin ع wrote to muhnaf ibn sulaym and his statement that whatever territory his horsemen and foot soldiers have not encompassed is not to be assessed for zakat means that zakat is not demanded from one whom the enemy has seized who is not of the shia who hold to the allegiance for it has come down from the people of the house gods blessings upon them in the book of daaim and elsewhere that whoever hands over zakat to other than the one whom god mighty and majestic commanded it be handed to it does not suffice him even if it is later plundered or stolen until he hands it to the guardian of the affair or to one who receives it by his command', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 30, NULL, 'And it is said in the Mustansiriyya Councils: likewise, the one who upholds the outward form of the prayer and believes in its inner reality, yet does not spend from what God has provided him what He has made obligatory upon him — the zakat of his wealth, the khums of his earnings, the purchase of his own self, and the redemption of his pledge — falls short in merit of the one God described in this verse:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'and it is said in the mustansiriyya councils likewise the one who upholds the outward form of the prayer and believes in its inner reality yet does not spend from what god has provided him what he has made obligatory upon him the zakat of his wealth the khums of his earnings the purchase of his own self and the redemption of his pledge falls short in merit of the one god described in this verse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 31, NULL, 'Al-Baqarah: 3﴿وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ﴾', '', '﴿وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ﴾', 'Al-Baqarah: 3', 2, 3, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'al baqarah 3 ومما رزقناهم ينفقون', 'ومما رزقناهم ينفقون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 32, NULL, 'And out of what We have provided them, they spend.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'and out of what we have provided them they spend', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 33, NULL, 'And the Prophet said that there is no prayer for one who does not pay zakat, and he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'and the prophet said that there is no prayer for one who does not pay zakat and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 34, NULL, 'Sayingمَانِعُ الزَّكَاةِ فِي النَّارِ', '', 'مَانِعُ الزَّكَاةِ فِي النَّارِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'sayingمانع الزكاه في النار', 'مانع الزكاه في النار');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the wealth that is not yours', '27. The Wealth That Is Not Yours', 35, NULL, 'The one who withholds zakat is in the Fire.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 27 the wealth that is not yours', 'the one who withholds zakat is in the fire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 0, NULL, 'I turn now to the zakat of gold, silver, and jewels.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'i turn now to the zakat of gold silver and jewels', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 2, NULL, 'He said in the book of questions and answers, arranged according to the order of the chapters of the Pillars of Islam:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in the book of questions and answers arranged according to the order of the chapters of the pillars of islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 3, NULL, 'Question: What do you say about a man who died having appointed two guardians, and one of them — or another of those close to the deceased — feared that the second guardian would block payment of what was owed from the estate: the khums, zakat, Hajj, and the rest? He paid these obligations in secret, without informing the second guardian, out of fear of him. Is anything held against him for that? And what must be paid, given that the deceased fixed nothing and left the matter unspecified, while the state of the kinsfolk is as it is, and it was known of him that he had withheld zakat, had not paid the khums on all his wealth, and had not performed the Hajj?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'question what do you say about a man who died having appointed two guardians and one of them or another of those close to the deceased feared that the second guardian would block payment of what was owed from the estate the khums zakat hajj and the rest he paid these obligations in secret without informing the second guardian out of fear of him is anything held against him for that and what must be paid given that the deceased fixed nothing and left the matter unspecified while the state of the kinsfolk is as it is and it was known of him that he had withheld zakat had not paid the khums on all his wealth and had not performed the hajj', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 4, NULL, 'Answer: If the guardian discharges what lies upon the deceased, there is nothing wrong with it. Zakat is a debt from which release must first be obtained, then the Hajj, then the khums. If the next of kin do not obtain that release, nothing falls upon anyone else, as long as they clear his neck — whether in secret or openly.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'answer if the guardian discharges what lies upon the deceased there is nothing wrong with it zakat is a debt from which release must first be obtained then the hajj then the khums if the next of kin do not obtain that release nothing falls upon anyone else as long as they clear his neck whether in secret or openly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 5, NULL, 'Question: What do you say about a man who does not bring out the zakat of his wealth and does not deliver it to the one appointed to receive it? Is it permissible to eat food in his house?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'question what do you say about a man who does not bring out the zakat of his wealth and does not deliver it to the one appointed to receive it is it permissible to eat food in his house', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 6, NULL, 'Answer: There is nothing wrong with that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'answer there is nothing wrong with that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 7, NULL, 'Question: What do you say about a man who possessed wealth, did not pay its khums, and then died? Must the khums be taken from his entire estate — including the houses, the servants, and the undivided holdings — or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'question what do you say about a man who possessed wealth did not pay its khums and then died must the khums be taken from his entire estate including the houses the servants and the undivided holdings or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 8, NULL, 'Answer: Yes, the khums is taken from his entire estate.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'answer yes the khums is taken from his entire estate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 9, NULL, 'Question: What do you say about a man who owned the nisab and did not pay its zakat, or who did not own the nisab until he died, and then when his estate was assessed — goods and houses together — it was found to have reached the nisab? Must zakat be taken from it? And likewise, what of the Hajj and the other obligations that rested upon his wealth?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'question what do you say about a man who owned the nisab and did not pay its zakat or who did not own the nisab until he died and then when his estate was assessed goods and houses together it was found to have reached the nisab must zakat be taken from it and likewise what of the hajj and the other obligations that rested upon his wealth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 10, NULL, 'Answer: If what he left behind includes trade goods held for selling, buying, and commerce, and those goods reach the nisab, then paying their zakat is obligatory, and the Hajj is discharged after the zakat.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'answer if what he left behind includes trade goods held for selling buying and commerce and those goods reach the nisab then paying their zakat is obligatory and the hajj is discharged after the zakat', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 11, NULL, 'Question: What do you say about a man who died, and when his entire estate was examined it proved sufficient to cover the Hajj and the other obligations — expiation, al-Shurwa, and khums — even though during his lifetime the deceased had owned little beyond his house and its furnishings? Are the Hajj and the other obligations to be discharged while the heirs take what remains?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'question what do you say about a man who died and when his entire estate was examined it proved sufficient to cover the hajj and the other obligations expiation al shurwa and khums even though during his lifetime the deceased had owned little beyond his house and its furnishings are the hajj and the other obligations to be discharged while the heirs take what remains', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 12, NULL, 'Answer: If he leaves wealth, the Hajj takes precedence over the inheritance, because it is a debt, and debt comes before inheritance. The remaining obligatory duties are likewise binding if the wealth is sufficient for them and something is still left for the heir.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'answer if he leaves wealth the hajj takes precedence over the inheritance because it is a debt and debt comes before inheritance the remaining obligatory duties are likewise binding if the wealth is sufficient for them and something is still left for the heir', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 13, NULL, 'Question: The collector of the customs levy takes ten dirhams from every two hundred dirhams paid by polytheists, and five dirhams from every two hundred dirhams paid by Muslims. The collector remitted one or two dirhams for certain Muslims. Now the owner of cloth for whom the collector remitted nothing comes to the man for whom he did remit, so that the goods may be registered in that man''s name, on the condition that whatever remains is divided equally between the two of them. Is it permissible to take that arrangement or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'question the collector of the customs levy takes ten dirhams from every two hundred dirhams paid by polytheists and five dirhams from every two hundred dirhams paid by muslims the collector remitted one or two dirhams for certain muslims now the owner of cloth for whom the collector remitted nothing comes to the man for whom he did remit so that the goods may be registered in that mans name on the condition that whatever remains is divided equally between the two of them is it permissible to take that arrangement or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 14, NULL, 'Answer: Whatever the partners have agreed upon and both know of is permissible.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'answer whatever the partners have agreed upon and both know of is permissible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 15, NULL, 'Question: A man died and left two hundred dinars — or less, or more — and zakat, Hajj, khums, al-Shurwa, and expiation were all owed from his estate. Which of these claims is settled first from the capital?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'question a man died and left two hundred dinars or less or more and zakat hajj khums al shurwa and expiation were all owed from his estate which of these claims is settled first from the capital', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 16, NULL, 'Answer: He begins with the zakat, for it is a debt upon him and is not part of his wealth; then the Hajj, then the khums, then the expiation, then al-Shurwa.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'answer he begins with the zakat for it is a debt upon him and is not part of his wealth then the hajj then the khums then the expiation then al shurwa', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 17, NULL, 'Question: A man died leaving wealth and an heir, and made no bequest at all. Are the khums, al-Shurwa, and the expiation taken from the capital or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'question a man died leaving wealth and an heir and made no bequest at all are the khums al shurwa and the expiation taken from the capital or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 18, NULL, 'Answer: The khums must be brought out of the capital. If the heirs are God-fearing, it is their duty to discharge it on behalf of the one who has passed, and so to purify the wealth. If they refuse, then:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'answer the khums must be brought out of the capital if the heirs are god fearing it is their duty to discharge it on behalf of the one who has passed and so to purify the wealth if they refuse then', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 19, NULL, 'Al-Baqarah: 256لَآ إِكْرَاهَ فِى ٱلدِّينِ', '', 'لَآ إِكْرَاهَ فِى ٱلدِّينِ', 'Al-Baqarah: 256', 2, 256, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'al baqarah 256لا اكراه في الدين', 'لا اكراه في الدين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 20, NULL, 'There is no compulsion in religion.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'there is no compulsion in religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 21, NULL, 'From another source: whoever pays the zakat of two years to the one authorized to receive it before the second year falls due, it is discharged from him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'from another source whoever pays the zakat of two years to the one authorized to receive it before the second year falls due it is discharged from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 22, NULL, 'Question: A man has two hundred mithqals and brings out the zakat at the head of the hawl. He then leaves one hundred in his house — neither selling nor buying with it — while he trades with the remaining hundred. When the second hawl comes round, does he pay zakat on the two hundred or on the one hundred? And likewise, if he buys a commodity and the hawl passes over it while he has not sold it, and the price has fallen: is zakat due on it or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'question a man has two hundred mithqals and brings out the zakat at the head of the hawl he then leaves one hundred in his house neither selling nor buying with it while he trades with the remaining hundred when the second hawl comes round does he pay zakat on the two hundred or on the one hundred and likewise if he buys a commodity and the hawl passes over it while he has not sold it and the price has fallen is zakat due on it or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 23, NULL, 'Answer: Zakat remains obligatory on whatever it fell due on for as long as it stays with its owner — whether he trades with it or hoards it — until what he owns falls below the nisab.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'answer zakat remains obligatory on whatever it fell due on for as long as it stays with its owner whether he trades with it or hoards it until what he owns falls below the nisab', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 24, NULL, 'Question: It appears in al-Masail that al-Shurwa is one hundred and nineteen dirhams, and that those of means owe a dinar. O our master, what is the limit of means, and what is the weight of a dinar, and what is the weight of a dirham?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'question it appears in al masail that al shurwa is one hundred and nineteen dirhams and that those of means owe a dinar o our master what is the limit of means and what is the weight of a dinar and what is the weight of a dirham', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 25, NULL, 'Answer: Our master said: the limit of means, for all, is ownership of wealth on which zakat falls due after the hawl — that is, either two hundred dirhams or twenty gold dinars. Each dirham is fourteen carats of silver and two fifths of a carat; by this reckoning, the weight of two hundred dirhams is eighteen ounces by the weights of the Arabs, which is ninety-five kadiyana and a quarter kadiyana, and a wal and a quarter wal of silver by the weights of Gujarat. One then looks at what this silver is worth in the coinage current at the time. Whoever owns this amount, or more, is counted among those of means.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'answer our master said the limit of means for all is ownership of wealth on which zakat falls due after the hawl that is either two hundred dirhams or twenty gold dinars each dirham is fourteen carats of silver and two fifths of a carat by this reckoning the weight of two hundred dirhams is eighteen ounces by the weights of the arabs which is ninety five kadiyana and a quarter kadiyana and a wal and a quarter wal of silver by the weights of gujarat one then looks at what this silver is worth in the coinage current at the time whoever owns this amount or more is counted among those of means', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 26, NULL, 'As for gold: each dinar is twenty-four carats, and by this reckoning the weight of twenty dinars is three ounces of gold by the weights of the Arabs, which is sixteen kadiyana less a wal and half a wal of gold. Yet here there is a matter to consider, because the price of gold and silver differs in every age according to people''s desire for the one and their lack of desire for the other, and the reverse — so that at times the price of twenty dinars is more than two hundred dirhams, and at other times the opposite. It is therefore fitting for the believer who holds to his religion to reckon by whichever of the two named coinages — gold and silver — is the lesser in price.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'as for gold each dinar is twenty four carats and by this reckoning the weight of twenty dinars is three ounces of gold by the weights of the arabs which is sixteen kadiyana less a wal and half a wal of gold yet here there is a matter to consider because the price of gold and silver differs in every age according to peoples desire for the one and their lack of desire for the other and the reverse so that at times the price of twenty dinars is more than two hundred dirhams and at other times the opposite it is therefore fitting for the believer who holds to his religion to reckon by whichever of the two named coinages gold and silver is the lesser in price', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 27, NULL, 'Question: A man has five hundred tankas and brings out the fifth — one hundred tankas — in the first year, leaving him four hundred tankas. He traded with them and gained three hundred tankas in profit, of which household expenses took two hundred tankas, leaving him one hundred of the profit. Does he bring the khums out of three hundred tankas or out of one hundred?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'question a man has five hundred tankas and brings out the fifth one hundred tankas in the first year leaving him four hundred tankas he traded with them and gained three hundred tankas in profit of which household expenses took two hundred tankas leaving him one hundred of the profit does he bring the khums out of three hundred tankas or out of one hundred', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 28, NULL, 'Answer: If he has already brought out the khums from the capital, then there is no khums on the profit except on what remains in his hand. Paying khums on the whole is a merit, not a binding obligation.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'answer if he has already brought out the khums from the capital then there is no khums on the profit except on what remains in his hand paying khums on the whole is a merit not a binding obligation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 29, NULL, 'This is the answer of our master Idris.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'this is the answer of our master idris', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 30, NULL, 'He said in Mukhtasar al-Musannaf: zakat is obligatory when what is liable to it reaches its nisab unencumbered and the hawl has passed over it. He said in it: as for a deposit, if the one holding it alters it and introduces into it what takes it out of the ruling of a deposit, or consumes it and puts wealth of his own in its place, then zakat on all of that is obligatory upon him. And if the hawl passes over the estate of a dead man after he has died and his heirs have not divided it, zakat is not obligatory on the estate as a whole, but is obligatory upon each of the shares: whoever''s share reaches a nisab must pay zakat on it, and whoever''s share does not reach a nisab — and who has no other wealth besides — owes no zakat on it. If a man has wealth and also owes a debt, and the hawl passes over it, one looks at what he owes and what he has; if his wealth exceeds his debt by a nisab or more, the zakat on the excess over his debt is binding upon him. If a man sells trade goods for the trade goods of another — which he also buys for trade — the second goods are valued at the head of the hawl reckoned from the time he first owned the original goods; and whether he suffered a loss in that or not, he pays what is due from him in zakat.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in mukhtasar al musannaf zakat is obligatory when what is liable to it reaches its nisab unencumbered and the hawl has passed over it he said in it as for a deposit if the one holding it alters it and introduces into it what takes it out of the ruling of a deposit or consumes it and puts wealth of his own in its place then zakat on all of that is obligatory upon him and if the hawl passes over the estate of a dead man after he has died and his heirs have not divided it zakat is not obligatory on the estate as a whole but is obligatory upon each of the shares whoevers share reaches a nisab must pay zakat on it and whoevers share does not reach a nisab and who has no other wealth besides owes no zakat on it if a man has wealth and also owes a debt and the hawl passes over it one looks at what he owes and what he has if his wealth exceeds his debt by a nisab or more the zakat on the excess over his debt is binding upon him if a man sells trade goods for the trade goods of another which he also buys for trade the second goods are valued at the head of the hawl reckoned from the time he first owned the original goods and whether he suffered a loss in that or not he pays what is due from him in zakat', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 31, NULL, 'He said in it: likewise, if he buys trade goods with coin on which zakat is due, the reckoning follows how long the money and the goods stood in his hands; and when the hawl passes over it, he pays the zakat on his wealth.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in it likewise if he buys trade goods with coin on which zakat is due the reckoning follows how long the money and the goods stood in his hands and when the hawl passes over it he pays the zakat on his wealth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 32, NULL, 'He said in al-Akhbar: they narrated that whoever sets aside wealth that is surplus to him and then finds it again pays zakat on it. And from it: the apostate begins his zakat anew and does not pay zakat for what was his during his apostasy. He said: there is no zakat in the wealth of an orphan, nor in the wealth of one who lacks his reason.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in al akhbar they narrated that whoever sets aside wealth that is surplus to him and then finds it again pays zakat on it and from it the apostate begins his zakat anew and does not pay zakat for what was his during his apostasy he said there is no zakat in the wealth of an orphan nor in the wealth of one who lacks his reason', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 33, NULL, 'Tawil al-Daaim said: this means that there is no zakat on that wealth due from the owner who holds it for himself; but whatever of it is held for trade is valued at a price, and zakat is due on it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'tawil al daaim said this means that there is no zakat on that wealth due from the owner who holds it for himself but whatever of it is held for trade is valued at a price and zakat is due on it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 34, NULL, 'He said in Mukhtasar al-Musannaf: in what comes out of a mine there is the khums, and the remainder is for the one who found it; in buried treasure there is the khums; and dinars found bearing the coinage of Islam fall under the ruling of found property.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in mukhtasar al musannaf in what comes out of a mine there is the khums and the remainder is for the one who found it in buried treasure there is the khums and dinars found bearing the coinage of islam fall under the ruling of found property', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 35, NULL, 'Some of the friends of God (عَلَيْهِمُ السَّلَامُ) said: al-Shurwa due from the rich man of means is one hundred and nineteen mithqals of gold, and from the one without means, one hundred and nineteen pieces of silver.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'some of the friends of god عليهم السلام said al shurwa due from the rich man of means is one hundred and nineteen mithqals of gold and from the one without means one hundred and nineteen pieces of silver', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 36, NULL, 'He said in the questions put by our master Sulayman ibn Hasan in his early days, with the answers of our master Daud ibn Ajab: I also asked about one who has paid the khums of the lands of his estate — is the khums then due upon their seed or not?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in the questions put by our master sulayman ibn hasan in his early days with the answers of our master daud ibn ajab i also asked about one who has paid the khums of the lands of his estate is the khums then due upon their seed or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 37, NULL, 'Answer: Yes, may God prolong you; the khums is obligatory upon him in the seed of those lands, as God Almighty said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'answer yes may god prolong you the khums is obligatory upon him in the seed of those lands as god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 38, NULL, 'Al-Anfal: 41وَاعْلَمُوا أَنَّمَا غَنِمْتُم مِّن شَيْءٍ فَأَنَّ لِلَّهِ خُمُسَهُ', '', 'وَاعْلَمُوا أَنَّمَا غَنِمْتُم مِّن شَيْءٍ فَأَنَّ لِلَّهِ خُمُسَهُ', 'Al-Anfal: 41', 8, 41, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'al anfal 41واعلموا انما غنمتم من شيء فان لله خمسه', 'واعلموا انما غنمتم من شيء فان لله خمسه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 39, NULL, 'Know that whatever you take as spoil, a fifth of it belongs to God.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'know that whatever you take as spoil a fifth of it belongs to god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 40, NULL, 'These seeds fall under the word "thing," as our master the Qadi al-Numan ibn Muhammad mentioned and made clear and plain in Kitab al-Himma.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'these seeds fall under the word thing as our master the qadi al numan ibn muhammad mentioned and made clear and plain in kitab al himma', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 41, NULL, 'He said in Tawil al-Sharia: Imam al-Muizz li-Din Allah (ع) was asked about zakat, and he said that it is five dirhams, and that the poor are of five classes, with a dirham for each class. Zakat, he said, is mutual consolation: all people and the whole of creation are as a single soul, and when one limb of the body suffers pain, all the limbs turn to that limb to treat it until its pain is gone. When God tests one of the children of the human kind, it is the duty of the kind to occupy itself with his healing. And a man was mentioned in his presence, and it was said, "There is no defect in him." He (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in tawil al sharia imam al muizz li din allah ع was asked about zakat and he said that it is five dirhams and that the poor are of five classes with a dirham for each class zakat he said is mutual consolation all people and the whole of creation are as a single soul and when one limb of the body suffers pain all the limbs turn to that limb to treat it until its pain is gone when god tests one of the children of the human kind it is the duty of the kind to occupy itself with his healing and a man was mentioned in his presence and it was said there is no defect in him he ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 42, NULL, 'Sayingلَوْ كَانَ أَحَدٌ لَمْ يَمْسَسْهُ عَيْبٌ لَمَا أَدْرَكَهُ الْمَوْتُ', '', 'لَوْ كَانَ أَحَدٌ لَمْ يَمْسَسْهُ عَيْبٌ لَمَا أَدْرَكَهُ الْمَوْتُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'sayingلو كان احد لم يمسسه عيب لما ادركه الموت', 'لو كان احد لم يمسسه عيب لما ادركه الموت');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 43, NULL, 'If there were anyone whom no defect had touched, death would never have reached him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'if there were anyone whom no defect had touched death would never have reached him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 44, NULL, 'Our master, the most exalted summoner, Jafar son of our master Mansur al-Yaman, said at the beginning of the Book of the Inner Nursing: the five prayers are known at five times, and the zakat likewise is five:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'our master the most exalted summoner jafar son of our master mansur al yaman said at the beginning of the book of the inner nursing the five prayers are known at five times and the zakat likewise is five', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 45, NULL, 'The khums of every wealth a man earns through trade, sales, and gain. The zakat of wealth whose khums has already been brought out, which is one dinar from every forty dinars; it is an obligation due to the Hujja, and the khums is for the Imam. The zakat of crops, which is likewise its tenth. The zakat of livestock, which is one head from every forty head. The zakat of the soul, which is what the believer pays for himself: the shurwa for the redemption of his neck, and the fitra of his fast — after these four obligatory zakats.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'the khums of every wealth a man earns through trade sales and gain the zakat of wealth whose khums has already been brought out which is one dinar from every forty dinars it is an obligation due to the hujja and the khums is for the imam the zakat of crops which is likewise its tenth the zakat of livestock which is one head from every forty head the zakat of the soul which is what the believer pays for himself the shurwa for the redemption of his neck and the fitra of his fast after these four obligatory zakats', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 46, NULL, 'Our master Zayd ibn Muhammad said in al-Risala al-Maknuna: whoever owns twenty mithqals of gold owes half a mithqal. Then he said: and upon whoever owns two hundred dirhams there are five dirhams, and the two hundred are two covenants. He said in it: there is no zakat upon one who does not own twenty mithqals, nor upon one who does not own two hundred dirhams. He said in it: whoever owns two hundred dirhams is forbidden to take zakat and charity. He said in it: the owner of gold and silver owes no zakat on his wealth so long as the hawl has not passed over it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'our master zayd ibn muhammad said in al risala al maknuna whoever owns twenty mithqals of gold owes half a mithqal then he said and upon whoever owns two hundred dirhams there are five dirhams and the two hundred are two covenants he said in it there is no zakat upon one who does not own twenty mithqals nor upon one who does not own two hundred dirhams he said in it whoever owns two hundred dirhams is forbidden to take zakat and charity he said in it the owner of gold and silver owes no zakat on his wealth so long as the hawl has not passed over it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 48, NULL, 'He said in Mukhtasar al-Musannaf: there is no zakat on livestock until they are free-grazing and the hawl has passed over them. If they graze during part of the hawl and are fed with fodder during another part, the ruling follows whichever is the greater part.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in mukhtasar al musannaf there is no zakat on livestock until they are free grazing and the hawl has passed over them if they graze during part of the hawl and are fed with fodder during another part the ruling follows whichever is the greater part', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 49, NULL, 'He said in it: if someone owns five camels and fails to pay their zakat for two consecutive hawls, he owes a sheep for the first hawl but nothing for the second, since that second sheep already stands against him as a debt. The same principle applies to all livestock other than camels. If a man''s camels have reached the threshold where camels are themselves the due, and he also owns sheep, then the zakat is taken from his sheep — from animals fit to serve as sacrificial animals — and the same applies to the zakat on sheep. Buffaloes and cows are alike in their zakat, as are sheep and goats.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in it if someone owns five camels and fails to pay their zakat for two consecutive hawls he owes a sheep for the first hawl but nothing for the second since that second sheep already stands against him as a debt the same principle applies to all livestock other than camels if a mans camels have reached the threshold where camels are themselves the due and he also owns sheep then the zakat is taken from his sheep from animals fit to serve as sacrificial animals and the same applies to the zakat on sheep buffaloes and cows are alike in their zakat as are sheep and goats', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 50, NULL, 'He said in Tawil al-Daaim: this applies specifically when zakat has actually fallen due; if nothing has yet become due on them, then no obligation rests on him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in tawil al daaim this applies specifically when zakat has actually fallen due if nothing has yet become due on them then no obligation rests on him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 51, NULL, 'Our master Jafar ibn Mansur al-Yaman stated at the opening of the Book of the Inner Nursing: the zakat on livestock is one head from every forty.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'our master jafar ibn mansur al yaman stated at the opening of the book of the inner nursing the zakat on livestock is one head from every forty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 52, NULL, 'Our master Zayd ibn Muhammad said in al-Risala al-Maknuna: camels are slaughtered by the thrust to the throat and then by the cut. He said in it: no zakat is due on fewer than five camels. He said in it: until the five are complete; and once he owns them, a sheep of the flock is obligatory — one sheep for every five — until they reach twenty, when he pays four sheep. When they reach twenty-five, a bint makhad is due. He said in it: the bint makhad is one whose mother has carried a young one in her belly. He said in it: then with an increase of ten; when they reach thirty-five, a bint labun is due. He said in it: when they reach forty-five, he pays a hiqqa fit to be covered by the stallion. He said in it: then with an increase of fifteen; and when one is added above sixty, a jadha is due. He said in it: above the jadha, nothing further is taken in charity. He said in it: a hiqqa was set at sixty camels because she resembles the stallion and is able to bear what he bears. He said in it: when the camels reach one hundred and twenty, two hiqqas are due, because one hundred and twenty is twice sixty.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'our master zayd ibn muhammad said in al risala al maknuna camels are slaughtered by the thrust to the throat and then by the cut he said in it no zakat is due on fewer than five camels he said in it until the five are complete and once he owns them a sheep of the flock is obligatory one sheep for every five until they reach twenty when he pays four sheep when they reach twenty five a bint makhad is due he said in it the bint makhad is one whose mother has carried a young one in her belly he said in it then with an increase of ten when they reach thirty five a bint labun is due he said in it when they reach forty five he pays a hiqqa fit to be covered by the stallion he said in it then with an increase of fifteen and when one is added above sixty a jadha is due he said in it above the jadha nothing further is taken in charity he said in it a hiqqa was set at sixty camels because she resembles the stallion and is able to bear what he bears he said in it when the camels reach one hundred and twenty two hiqqas are due because one hundred and twenty is twice sixty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 53, NULL, 'He said in it: when cattle reach thirty, a tabi is due. He said in it: when they reach forty, a musinna is due. He said in it: in sixty, two tabis are due. He said in it: in ninety, three yearlings are due. He said in it: when they reach one hundred and twenty, in every forty a musinna is due and in every thirty a tabi.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in it when cattle reach thirty a tabi is due he said in it when they reach forty a musinna is due he said in it in sixty two tabis are due he said in it in ninety three yearlings are due he said in it when they reach one hundred and twenty in every forty a musinna is due and in every thirty a tabi', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 54, NULL, 'He said in it, concerning sheep: when they reach forty, one sheep is due as charity. He said in it: up to one hundred and twenty, one sheep remains due. He said in it: when they reach two hundred, two sheep are due. He said in it: then after that, one sheep for every hundred. He said in it: nothing defective is taken in charity. He said in it: the ram of the flock is not taken in charity unless the collector wishes it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in it concerning sheep when they reach forty one sheep is due as charity he said in it up to one hundred and twenty one sheep remains due he said in it when they reach two hundred two sheep are due he said in it then after that one sheep for every hundred he said in it nothing defective is taken in charity he said in it the ram of the flock is not taken in charity unless the collector wishes it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 56, NULL, 'He said in the book of questions and answers mentioned above:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in the book of questions and answers mentioned above', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 57, NULL, 'Question: The nisab of gold is twenty dinars and of silver two hundred dirhams. How then is the nisab of grains reckoned?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'question the nisab of gold is twenty dinars and of silver two hundred dirhams how then is the nisab of grains reckoned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 58, NULL, 'Answer: It has come in the Pillars that zakat is due from everything the earth brings forth, and upon this rests the practice of our masters, so it is a duty to follow them. They brought out the tenth from little and from much, and in that is merit. And it has come in the Sharia that the nisab in grains is five awsaq, and the wasq is sixty sa.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'answer it has come in the pillars that zakat is due from everything the earth brings forth and upon this rests the practice of our masters so it is a duty to follow them they brought out the tenth from little and from much and in that is merit and it has come in the sharia that the nisab in grains is five awsaq and the wasq is sixty sa', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 59, NULL, 'He said in al-Akhbar: whatever is sold as a standing crop — that is, grain — has zakat due on it; but whatever is sold before it forms its kernel and is then harvested carries no zakat. The same holds for fruits. They also narrated that the owner of the land does not set off against it what he spent upon it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in al akhbar whatever is sold as a standing crop that is grain has zakat due on it but whatever is sold before it forms its kernel and is then harvested carries no zakat the same holds for fruits they also narrated that the owner of the land does not set off against it what he spent upon it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 60, NULL, 'He said in Mukhtasar al-Musannaf: this is obligatory upon the young and the old, the rich and the poor, and upon one who is in debt.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in mukhtasar al musannaf this is obligatory upon the young and the old the rich and the poor and upon one who is in debt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 61, NULL, 'From al-Akhbar: they narrated that the land of the tenth is every tract of Arab land against which the Muslims did not advance with horse or riding beast, and every mountain land that its own people brought into cultivation and which no water from the great rivers overflowed. That is the land of the tenth. They narrated that the land of kharaj is the land of the Sudan and those mountain lands against which the Muslims advanced with horse and riding beast and which they brought under cultivation by force. When the people of war submit while still upon their own territory, that land becomes land of the tenth. They further narrated that if a Muslim buys land of kharaj from a protected non-Muslim and takes possession of it, its ruling is not changed by passing to the Muslim, and it remains land of kharaj as it was; and if a protected non-Muslim buys land of the tenth from a Muslim and takes possession of it, the tenth is still due on what it brings forth, because that obligation attaches to the land''s produce and no account is taken of the owner.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'from al akhbar they narrated that the land of the tenth is every tract of arab land against which the muslims did not advance with horse or riding beast and every mountain land that its own people brought into cultivation and which no water from the great rivers overflowed that is the land of the tenth they narrated that the land of kharaj is the land of the sudan and those mountain lands against which the muslims advanced with horse and riding beast and which they brought under cultivation by force when the people of war submit while still upon their own territory that land becomes land of the tenth they further narrated that if a muslim buys land of kharaj from a protected non muslim and takes possession of it its ruling is not changed by passing to the muslim and it remains land of kharaj as it was and if a protected non muslim buys land of the tenth from a muslim and takes possession of it the tenth is still due on what it brings forth because that obligation attaches to the lands produce and no account is taken of the owner', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 62, NULL, 'He said in Maalim al-Din: zakat is obligatory in all grains that run in the course of wheat and dates, and nothing of that reaches the measure unless it reaches five awsaq.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in maalim al din zakat is obligatory in all grains that run in the course of wheat and dates and nothing of that reaches the measure unless it reaches five awsaq', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 63, NULL, 'He said in al-Muntakhaba: the nisab of the grains we have mentioned is five awsaq, and the wasq is sixty sa.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in al muntakhaba the nisab of the grains we have mentioned is five awsaq and the wasq is sixty sa', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 64, NULL, 'He said in al-Akhbar: if part of a crop is watered by one means and part of it by another, the ruling follows whichever portion is the greater; and if the two are equal, three quarters of the tenth are taken from him. He said in it: one half is not joined to another half among grains and fruits, and there is no zakat in any of them until the half reaches the measure at which zakat becomes obligatory.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in al akhbar if part of a crop is watered by one means and part of it by another the ruling follows whichever portion is the greater and if the two are equal three quarters of the tenth are taken from him he said in it one half is not joined to another half among grains and fruits and there is no zakat in any of them until the half reaches the measure at which zakat becomes obligatory', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 65, NULL, 'He said in Mukhtasar al-Athar: the tenth becomes obligatory in grains only when they form their kernels, and at that point an estimate is made — which is when their soundness becomes apparent — and a just estimate is made upon their owners.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in mukhtasar al athar the tenth becomes obligatory in grains only when they form their kernels and at that point an estimate is made which is when their soundness becomes apparent and a just estimate is made upon their owners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 66, NULL, 'He said in the Book of the Inner Nursing: as for the tenth, it is an outward ruling by which the Messenger of God judged, taken from the believers and from the people of the outward. He said in it: likewise, in the outward, whoever pays the tenth of his earnings in truth has rightly discharged his outward obligation, so long as he has kept back only nine tenths; he has done what he was told to do, even if the ruler over his outward affairs had made no demand of him. And whoever withholds some of his earnings and keeps with himself more than nine tenths has not rightly fulfilled what he intended by paying the tenth that was commanded of him, and has not in truth rendered obedience to the ruler over his outward affairs.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'he said in the book of the inner nursing as for the tenth it is an outward ruling by which the messenger of god judged taken from the believers and from the people of the outward he said in it likewise in the outward whoever pays the tenth of his earnings in truth has rightly discharged his outward obligation so long as he has kept back only nine tenths he has done what he was told to do even if the ruler over his outward affairs had made no demand of him and whoever withholds some of his earnings and keeps with himself more than nine tenths has not rightly fulfilled what he intended by paying the tenth that was commanded of him and has not in truth rendered obedience to the ruler over his outward affairs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 67, NULL, 'Our master Zayd ibn Muhammad said in al-Risala al-Maknuna: these five — meaning dates, raisins, wheat, barley, and grain — when they reach five awsaq, half a wasq of charity is due on them. He said in it: the tenth is obligatory on what the sky waters and what the rivers water; and on what is watered by wheels and by water-carrying beasts, half the tenth is due. He said in it: God imposed the khums on spoils. God Almighty said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'our master zayd ibn muhammad said in al risala al maknuna these five meaning dates raisins wheat barley and grain when they reach five awsaq half a wasq of charity is due on them he said in it the tenth is obligatory on what the sky waters and what the rivers water and on what is watered by wheels and by water carrying beasts half the tenth is due he said in it god imposed the khums on spoils god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 68, NULL, 'Al-Anfal: 41وَاعْلَمُوا أَنَّمَا غَنِمْتُم مِّن شَيْءٍ فَأَنَّ لِلَّهِ خُمُسَهُ وَلِلرَّسُولِ وَلِذِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ', '', 'وَاعْلَمُوا أَنَّمَا غَنِمْتُم مِّن شَيْءٍ فَأَنَّ لِلَّهِ خُمُسَهُ وَلِلرَّسُولِ وَلِذِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ', 'Al-Anfal: 41', 8, 41, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'al anfal 41واعلموا انما غنمتم من شيء فان لله خمسه وللرسول ولذي القربي واليتامي والمساكين وابن السبيل', 'واعلموا انما غنمتم من شيء فان لله خمسه وللرسول ولذي القربي واليتامي والمساكين وابن السبيل');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 69, NULL, 'Know that whatever you take as spoil, a fifth of it belongs to God, and to the Messenger, and to the near of kin, and the orphans, and the needy, and the wayfarer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'know that whatever you take as spoil a fifth of it belongs to god and to the messenger and to the near of kin and the orphans and the needy and the wayfarer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 70, NULL, 'These are five stations to which the khums is directed. He said in it: the khums is taken from mines, from treasures, and from spoils.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'these are five stations to which the khums is directed he said in it the khums is taken from mines from treasures and from spoils', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 71, NULL, 'And from Jafar ibn Muhammad al-Sadiq (ع) it is transmitted that he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'and from jafar ibn muhammad al sadiq ع it is transmitted that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 72, NULL, 'Sayingكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ إِذَا أَتَاهُ الْمَغْنَمُ أَخَذَ نَصِيبَهُ ثُمَّ يَقْسِمُ مَا بَقِيَ بَيْنَ الْقُرْبَى وَالْيَتَامَى وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ', '', 'كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ إِذَا أَتَاهُ الْمَغْنَمُ أَخَذَ نَصِيبَهُ ثُمَّ يَقْسِمُ مَا بَقِيَ بَيْنَ الْقُرْبَى وَالْيَتَامَى وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'sayingكان رسول الله صلي الله عليه واله اذا اتاه المغنم اخذ نصيبه ثم يقسم ما بقي بين القربي واليتامي والمساكين وابن السبيل', 'كان رسول الله صلي الله عليه واله اذا اتاه المغنم اخذ نصيبه ثم يقسم ما بقي بين القربي واليتامي والمساكين وابن السبيل');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'gold, herds, and harvest', '28. Gold, Herds, and Harvest', 73, NULL, 'When spoils came to the Messenger of God, he would take his share and then distribute what remained among the near of kin, the orphans, the needy, and the wayfarer.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 28 gold herds and harvest', 'when spoils came to the messenger of god he would take his share and then distribute what remained among the near of kin the orphans the needy and the wayfarer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 0, NULL, 'I turn now to zakat الْفِطْر.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'i turn now to zakat الفطر', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 1, NULL, 'In the first book of questions and answers — arranged according to the chapter order of the Book of the Pillars of Islam — the following exchange appears. Question: the custom among the Indians when collecting the fitra is to mix four kinds of grain — rice, maize, wheat, and salt — and then take their monetary value, whereas in the radiant Shariah the zakat of Fitr is a sa of dates, raisins, wheat, or barley. Does it suffice a person who gives a sa of barley? Answer: the reliance is on what is stated in the Pillars — that is, a sa of wheat, barley, dates, or raisins.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'in the first book of questions and answers arranged according to the chapter order of the book of the pillars of islam the following exchange appears question the custom among the indians when collecting the fitra is to mix four kinds of grain rice maize wheat and salt and then take their monetary value whereas in the radiant shariah the zakat of fitr is a sa of dates raisins wheat or barley does it suffice a person who gives a sa of barley answer the reliance is on what is stated in the pillars that is a sa of wheat barley dates or raisins', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 2, NULL, 'Sayingوَالْفِطْرَةُ مِنْ أَطْيَبِ مَا تَأْكُلُونَ وَأَزْكَى مَا تَدَّخِرُونَ', '', 'وَالْفِطْرَةُ مِنْ أَطْيَبِ مَا تَأْكُلُونَ وَأَزْكَى مَا تَدَّخِرُونَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'sayingوالفطره من اطيب ما تاكلون وازكي ما تدخرون', 'والفطره من اطيب ما تاكلون وازكي ما تدخرون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 3, NULL, 'The fitra is to be from the best of what you eat and the purest of what you store away.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'the fitra is to be from the best of what you eat and the purest of what you store away', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 4, NULL, 'Whoever mixes the fitra from everything he ate during Ramadan, that suffices him; and whoever ate nothing but barley, that too suffices him. Verify this well.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'whoever mixes the fitra from everything he ate during ramadan that suffices him and whoever ate nothing but barley that too suffices him verify this well', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 5, NULL, 'Question: what is the ruling for a man who wishes to pay his fitra before Ramadan begins, fearing that poverty or travel may prevent him from paying it at its proper time? What does the noble law say on this — does it suffice him or not? The question arises because obligatory duties may not be performed outside their appointed times, nor made up except after those times have passed. And if it does not suffice him, it should be noted that the Book of the Pillars states there is no harm in collecting zakat from those who owe it before its due time, when there is need for that. Please provide the answer on this, and also address the case of one who did this out of ignorance — has it sufficed him? Answer: if he delivers his fitra to someone who has the right to receive it, it has sufficed him. The prohibition in this matter is that a person should not break his fast before delivering his fitra. No fixed time was set for advancing or delaying it; the obligation is simply its delivery.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'question what is the ruling for a man who wishes to pay his fitra before ramadan begins fearing that poverty or travel may prevent him from paying it at its proper time what does the noble law say on this does it suffice him or not the question arises because obligatory duties may not be performed outside their appointed times nor made up except after those times have passed and if it does not suffice him it should be noted that the book of the pillars states there is no harm in collecting zakat from those who owe it before its due time when there is need for that please provide the answer on this and also address the case of one who did this out of ignorance has it sufficed him answer if he delivers his fitra to someone who has the right to receive it it has sufficed him the prohibition in this matter is that a person should not break his fast before delivering his fitra no fixed time was set for advancing or delaying it the obligation is simply its delivery', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 6, NULL, 'He stated in the book Mukhtasar al-Musannaf: a dhimmi who accepts Islam before the break of dawn on the day of Fitr owes the zakat of Fitr; if he accepts Islam after the break of dawn, nothing is due from him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'he stated in the book mukhtasar al musannaf a dhimmi who accepts islam before the break of dawn on the day of fitr owes the zakat of fitr if he accepts islam after the break of dawn nothing is due from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 7, NULL, 'He stated in the reports: they narrated that the zakat of Fitr is paid on behalf of the mukatab. He stated in the Landmarks of Religion: if a child is born before the break of dawn on the day of Fitr, the zakat of Fitr is due on his behalf. He stated in the Book of the Pillars: it has likewise been said that it is paid on behalf of the child still in his mother''s womb, before birth. He stated in the Selected Book: or a sa of dried curd, or half a sa of wheat. He stated in the Landmarks of Religion that the weight of the sa is four and a half ratls by the ratl of Mecca; he stated therein that its weight by the ratl of Medina is five ratls less a third of a ratl; and its weight by the Baghdadi ratl is nine ratls and a tenth of a ratl.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'he stated in the reports they narrated that the zakat of fitr is paid on behalf of the mukatab he stated in the landmarks of religion if a child is born before the break of dawn on the day of fitr the zakat of fitr is due on his behalf he stated in the book of the pillars it has likewise been said that it is paid on behalf of the child still in his mothers womb before birth he stated in the selected book or a sa of dried curd or half a sa of wheat he stated in the landmarks of religion that the weight of the sa is four and a half ratls by the ratl of mecca he stated therein that its weight by the ratl of medina is five ratls less a third of a ratl and its weight by the baghdadi ratl is nine ratls and a tenth of a ratl', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 8, NULL, 'Our master and lord, the author of the Mustansiriyya sessions — peace of God be upon him — stated in the thirteenth session: since we mentioned in the session before this one the zakat that is obligatory upon those who possess wealth, we follow that with the mention of the zakat that is obligatory in every condition, and upon those of small means who give it in charity — and that is the zakat of Fitr. In it are seven obligations and twelve practices of the Sunnah. The obligations are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'our master and lord the author of the mustansiriyya sessions peace of god be upon him stated in the thirteenth session since we mentioned in the session before this one the zakat that is obligatory upon those who possess wealth we follow that with the mention of the zakat that is obligatory in every condition and upon those of small means who give it in charity and that is the zakat of fitr in it are seven obligations and twelve practices of the sunnah the obligations are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 9, NULL, 'that a man pay it on behalf of himself; on behalf of the elder of his household; and the younger of them; and the free among them; and the enslaved among them; and the males among them; and the females among them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'that a man pay it on behalf of himself on behalf of the elder of his household and the younger of them and the free among them and the enslaved among them and the males among them and the females among them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 10, NULL, 'The practices of the Sunnah are that he bring it out from the middle sort of what he eats — a sa of wheat, or a sa of barley, or a sa of dates, or a sa of raisins; half a sa of wheat suffices him, and from anything other than wheat nothing suffices but a full sa; and the sa is four mudds. He should hand it to the Imam (ع), or to whomever the Imam has appointed; it should be brought out before the breaking of the fast; whoever delays bringing it out must make it up; and whoever lacks the food brings out its value in silver or in gold. As for the woman who has no husband with her, she brings it out on behalf of herself and on behalf of those she supports.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'the practices of the sunnah are that he bring it out from the middle sort of what he eats a sa of wheat or a sa of barley or a sa of dates or a sa of raisins half a sa of wheat suffices him and from anything other than wheat nothing suffices but a full sa and the sa is four mudds he should hand it to the imam ع or to whomever the imam has appointed it should be brought out before the breaking of the fast whoever delays bringing it out must make it up and whoever lacks the food brings out its value in silver or in gold as for the woman who has no husband with her she brings it out on behalf of herself and on behalf of those she supports', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 11, NULL, 'He stated in the book of the Inner Nursing, regarding the saying of the Messenger of God:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'he stated in the book of the inner nursing regarding the saying of the messenger of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 12, NULL, 'Sayingاَلْفِطْرَةُ لَا تَحِلُّ لِي وَلَا لِأَهْلِ بَيْتِي', '', 'اَلْفِطْرَةُ لَا تَحِلُّ لِي وَلَا لِأَهْلِ بَيْتِي', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'sayingالفطره لا تحل لي ولا لاهل بيتي', 'الفطره لا تحل لي ولا لاهل بيتي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 13, NULL, 'The fitra is not lawful for me, nor for the people of my house.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'the fitra is not lawful for me nor for the people of my house', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 14, NULL, 'Our master Zayd ibn Muhammad — may God sanctify his spirit — stated in the Concealed Epistle: as for the charity of Fitr, the Messenger of God made it obligatory upon every head among the Muslims to pay his fitra — upon the males and the females, the small and the great, even the infant born on that very day — and it is paid on behalf of the child in his mother''s womb. He made obligatory upon every head a sa of wheat, dates, raisins, barley, or other grains. He stated therein:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'our master zayd ibn muhammad may god sanctify his spirit stated in the concealed epistle as for the charity of fitr the messenger of god made it obligatory upon every head among the muslims to pay his fitra upon the males and the females the small and the great even the infant born on that very day and it is paid on behalf of the child in his mothers womb he made obligatory upon every head a sa of wheat dates raisins barley or other grains he stated therein', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 15, NULL, 'Sayingوَسُمِّيَتْ صَدَقَةُ الْفِطْرِ صَدَقَةَ الرَّأْسِ', '', 'وَسُمِّيَتْ صَدَقَةُ الْفِطْرِ صَدَقَةَ الرَّأْسِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'sayingوسميت صدقه الفطر صدقه الراس', 'وسميت صدقه الفطر صدقه الراس');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 16, NULL, 'The charity of Fitr has been named the charity of the head.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'the charity of fitr has been named the charity of the head', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 17, NULL, 'He stated therein: it is paid before the prayer, and if it is paid before the prayer it is charity. He stated therein: if the child is born after the Fitr, the fitra is paid before the Fitr.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'he stated therein it is paid before the prayer and if it is paid before the prayer it is charity he stated therein if the child is born after the fitr the fitra is paid before the fitr', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 18, NULL, 'He stated in the book Mafatih al-Nima — which belongs to our master the Judge al-Numan ibn Muhammad, may God exalt his sanctity — concerning the fitra:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'he stated in the book mafatih al nima which belongs to our master the judge al numan ibn muhammad may god exalt his sanctity concerning the fitra', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 19, NULL, 'Sayingفَاِنْ أُخْرِجَتْ قَبْلَ طُلُوعِ الشَّمْسِ كَانَتْ فِطْرَةً وَإِذَا أُخْرِجَتْ بَعْدَ طُلُوعِ الشَّمْسِ كَانَتْ صَدَقَةً', '', 'فَاِنْ أُخْرِجَتْ قَبْلَ طُلُوعِ الشَّمْسِ كَانَتْ فِطْرَةً وَإِذَا أُخْرِجَتْ بَعْدَ طُلُوعِ الشَّمْسِ كَانَتْ صَدَقَةً', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'sayingفان اخرجت قبل طلوع الشمس كانت فطره واذا اخرجت بعد طلوع الشمس كانت صدقه', 'فان اخرجت قبل طلوع الشمس كانت فطره واذا اخرجت بعد طلوع الشمس كانت صدقه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 20, NULL, 'If it is brought out before sunrise, it counts as fitra; if it is brought out after sunrise, it is ordinary charity.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'if it is brought out before sunrise it counts as fitra if it is brought out after sunrise it is ordinary charity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 21, NULL, 'He stated, up to his words:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'he stated up to his words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 22, NULL, 'Sayingوَمَعْنَى الْفِطْرَةِ إِخْرَاجُ الْوَاجِبِ لِلَّهِ وَلِوَلِيِّهِ مِنَ الْفِكَاكِ وَالْقُرْبَانِ', '', 'وَمَعْنَى الْفِطْرَةِ إِخْرَاجُ الْوَاجِبِ لِلَّهِ وَلِوَلِيِّهِ مِنَ الْفِكَاكِ وَالْقُرْبَانِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'sayingومعني الفطره اخراج الواجب لله ولوليه من الفكاك والقربان', 'ومعني الفطره اخراج الواجب لله ولوليه من الفكاك والقربان');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 23, NULL, 'The meaning of fitra is the bringing out of what is owed to God and to His appointed guardian, as ransom and as offering.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'the meaning of fitra is the bringing out of what is owed to god and to his appointed guardian as ransom and as offering', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the charity of the head', '29. The Charity of the Head', 24, NULL, 'I turn now to various rulings on zakat, on the one upon whom no zakat falls, and on other matters. In a book of legal questions — each one a marvel — he raised another question: what do you say concerning a man for whom the zakat on his wealth has been made lawful? The answer: in that case he is a man who owns a thousand dinars and owes a thousand dinars, so there is no zakat upon him on it. He stated therein another question: what do you say concerning a man for whom the zakat on his wealth is lawful while he himself is well off? The answer: in that case he is a man among the polytheists who has found no Muslim to whom to hand the zakat of his wealth, so he has more right to it than anyone else.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 29 the charity of the head', 'i turn now to various rulings on zakat on the one upon whom no zakat falls and on other matters in a book of legal questions each one a marvel he raised another question what do you say concerning a man for whom the zakat on his wealth has been made lawful the answer in that case he is a man who owns a thousand dinars and owes a thousand dinars so there is no zakat upon him on it he stated therein another question what do you say concerning a man for whom the zakat on his wealth is lawful while he himself is well off the answer in that case he is a man among the polytheists who has found no muslim to whom to hand the zakat of his wealth so he has more right to it than anyone else', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 0, NULL, 'I turn now to the Book of Fasting, and to the obligation of fasting the month of Ramadan.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'i turn now to the book of fasting and to the obligation of fasting the month of ramadan', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 1, NULL, 'He stated in the book Mukhtasar al-Musannaf: fasting is a shield from the Fire — a shield upon the tongues, the hearing, the eyes, and all the other limbs. It is not a matter of food and drink alone; every limb has its own portion in the fast, and whoever fulfills that portion is truly fasting. Whoever abandons any part of it diminishes the merit of his fast in proportion to what he has left. Fasting the month of Ramadan is an obligation upon every Muslim who is of age, sound of mind, healthy, and resident — and upon every woman likewise. He also stated therein: there is no fasting for one who is a hypocrite, disobedient to God.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'he stated in the book mukhtasar al musannaf fasting is a shield from the fire a shield upon the tongues the hearing the eyes and all the other limbs it is not a matter of food and drink alone every limb has its own portion in the fast and whoever fulfills that portion is truly fasting whoever abandons any part of it diminishes the merit of his fast in proportion to what he has left fasting the month of ramadan is an obligation upon every muslim who is of age sound of mind healthy and resident and upon every woman likewise he also stated therein there is no fasting for one who is a hypocrite disobedient to god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 2, NULL, 'He stated in the book al-Idah: what has come concerning fasting upon the sighting of the crescent, and what is mentioned in this chapter and in the two chapters before it, applies only to one who is absent from the presence of the Imam and does not know the measures of the crescents.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'he stated in the book al idah what has come concerning fasting upon the sighting of the crescent and what is mentioned in this chapter and in the two chapters before it applies only to one who is absent from the presence of the imam and does not know the measures of the crescents', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 3, NULL, 'Our master and Mawlana Jafar ibn Sayyidina Sulayman, may God exalt his sanctity, stated in his noble epistle entitled The Sharpest Sword in Nullifying Innovations, in which he counseled his people and roused those among them who had grown heedless and whose sleep had lengthened — from the people of the island of Yemen, while he dwelt there and settled among them:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'our master and mawlana jafar ibn sayyidina sulayman may god exalt his sanctity stated in his noble epistle entitled the sharpest sword in nullifying innovations in which he counseled his people and roused those among them who had grown heedless and whose sleep had lengthened from the people of the island of yemen while he dwelt there and settled among them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 4, NULL, '"Chapter: Among these matters also is what has been heard and known from most of you: that the honored month of Ramadan is not honored with the honor that God, glorified be He, and His Messenger (ع) have prescribed for it. It is the month of God, the Great, the Generous. That honor lies in placing the word month before it, as God, glorified be He, said concerning it:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'chapter among these matters also is what has been heard and known from most of you that the honored month of ramadan is not honored with the honor that god glorified be he and his messenger ع have prescribed for it it is the month of god the great the generous that honor lies in placing the word month before it as god glorified be he said concerning it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 5, NULL, 'Sayingشَهْرُ رَمَضَانَ', '', 'شَهْرُ رَمَضَانَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'sayingشهر رمضان', 'شهر رمضان');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 6, NULL, 'The month of Ramadan.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'the month of ramadan', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 7, NULL, 'Yet you, when you name it, call it Ramadan alone, and that is never seemly in the judgment of the intellect, nor does it guide in this matter toward right guidance — for a person does not address one who is dear to him among people except with a word he places before his name, according to what is known among you and whose glory and form are recognized, together with what is established by the aforementioned word of God, glorified be He:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'yet you when you name it call it ramadan alone and that is never seemly in the judgment of the intellect nor does it guide in this matter toward right guidance for a person does not address one who is dear to him among people except with a word he places before his name according to what is known among you and whose glory and form are recognized together with what is established by the aforementioned word of god glorified be he', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'a shield against the fire', '30. A Shield Against the Fire', 8, NULL, 'Al-Baqarah: 210وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', '', 'وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 'Al-Baqarah: 210', 2, 210, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'al baqarah 210والي الله ترجع الامور', 'والي الله ترجع الامور');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 9, NULL, 'And to God all matters return.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'and to god all matters return', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 10, NULL, 'Beyond this, it has come concerning it from our master al-Qadi al-Numan ibn Muhammad, may God exalt his sanctity, in the book Mukhtasar al-Athar al-Sharif, that your Mawla the Imam al-Baqir Abu Jafar Muhammad ibn Ali (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'beyond this it has come concerning it from our master al qadi al numan ibn muhammad may god exalt his sanctity in the book mukhtasar al athar al sharif that your mawla the imam al baqir abu jafar muhammad ibn ali ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 11, NULL, 'Sayingلَا تَقُولُونَ رَمَضَانَ وَلَكِنْ قُولُوا كَمَا قَالَ اللَّهُ تَعَالَى شَهْرَ رَمَضَانَ', '', 'لَا تَقُولُونَ رَمَضَانَ وَلَكِنْ قُولُوا كَمَا قَالَ اللَّهُ تَعَالَى شَهْرَ رَمَضَانَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'sayingلا تقولون رمضان ولكن قولوا كما قال الله تعالي شهر رمضان', 'لا تقولون رمضان ولكن قولوا كما قال الله تعالي شهر رمضان');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 12, NULL, 'Do not say Ramadan, but say as God Almighty said: the month of Ramadan.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'do not say ramadan but say as god almighty said the month of ramadan', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 13, NULL, 'So whoever has had God, glorified be He, cause his ear to hear this saying — how can it be permissible for him to oppose it and turn away from it, being of the people of piety and faith? The heedless one who turns away from it after having come to stand upon it makes light of God, glorified be He, and of His noble month mentioned above, and of the weighty saying of the Imam al-Baqir (ع) mentioned above. And the one who speaks by this noble book while turning away from acting upon what is in it enters under the censure contained in the words of God, glorified be He, in the verses of His noble and guarded Book, where He, glorified be He, says:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'so whoever has had god glorified be he cause his ear to hear this saying how can it be permissible for him to oppose it and turn away from it being of the people of piety and faith the heedless one who turns away from it after having come to stand upon it makes light of god glorified be he and of his noble month mentioned above and of the weighty saying of the imam al baqir ع mentioned above and the one who speaks by this noble book while turning away from acting upon what is in it enters under the censure contained in the words of god glorified be he in the verses of his noble and guarded book where he glorified be he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 14, NULL, 'As-Saff: 2يَا أَيُّهَا الَّذِينَ آمَنُوا لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَكَبُرَ مَقْتًا عِندَ اللَّهِ أَن تَقُولُوا مَا لَا تَفْعَلُونَ', '', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ كَبُرَ مَقْتًا عِندَ اللَّهِ أَن تَقُولُوا مَا لَا تَفْعَلُونَ', 'As-Saff: 2', NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'as saff 2يا ايها الذين امنوا لم تقولون ما لا تفعلونكبر مقتا عند الله ان تقولوا ما لا تفعلون', 'يا ايها الذين امنوا لم تقولون ما لا تفعلون كبر مقتا عند الله ان تقولوا ما لا تفعلون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 15, NULL, 'O you who believe, why do you say what you do not do? It is greatly hateful in the sight of God that you say what you do not do."', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'o you who believe why do you say what you do not do it is greatly hateful in the sight of god that you say what you do not do', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 16, NULL, 'He stated in the book Tawil al-Shariah: fasting becomes obligatory upon a boy once he can tell his right hand from his left.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'he stated in the book tawil al shariah fasting becomes obligatory upon a boy once he can tell his right hand from his left', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 17, NULL, 'He stated in the fourteenth majlis of the Mustansiriyya councils, God''s peace be upon its author: what follows is what we recite to you concerning the meaning of fasting, and that it is divided into categories, of which seven are obligatory and twelve are of the practice and commended. The obligatory ones are:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'he stated in the fourteenth majlis of the mustansiriyya councils gods peace be upon its author what follows is what we recite to you concerning the meaning of fasting and that it is divided into categories of which seven are obligatory and twelve are of the practice and commended the obligatory ones are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 18, NULL, 'Fasting the month of Ramadan every year. Fasting two consecutive months for one who deliberately breaks his fast on a day of it and cannot find a slave to free. Fasting two consecutive months for one who kills a believer by mistake, if he likewise cannot find a slave to free, together with paying the blood money to the family. In the expiation of zihar, fasting two consecutive months for one who cannot find a slave to free. In the expiation for breaking an oath, fasting three days for one who can find neither the feeding nor the clothing nor the freeing of a slave. The fast of one who performs tamattu with the lesser pilgrimage up to the pilgrimage, when he cannot find an offering, and it is ten days. The fast of a vow.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'fasting the month of ramadan every year fasting two consecutive months for one who deliberately breaks his fast on a day of it and cannot find a slave to free fasting two consecutive months for one who kills a believer by mistake if he likewise cannot find a slave to free together with paying the blood money to the family in the expiation of zihar fasting two consecutive months for one who cannot find a slave to free in the expiation for breaking an oath fasting three days for one who can find neither the feeding nor the clothing nor the freeing of a slave the fast of one who performs tamattu with the lesser pilgrimage up to the pilgrimage when he cannot find an offering and it is ten days the fast of a vow', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 19, NULL, 'As for the fasts of the practice and the commended:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'as for the fasts of the practice and the commended', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 20, NULL, 'The fast of itikaf. The fast of Shaban. The fast of the first Thursday of every month. The fast of the middle Wednesday of that month. The fast of the last Thursday of that month. The fast of the three white days. The fast of Dawud (ع), which is fasting one day and breaking the fast the next, and it is the most rigorous of fasts. The fast of Friday joined to Thursday or to Saturday, without singling out Friday alone for fasting. The fast of the day of Arafah for one who is not on pilgrimage. The fast of the boy when he reaches seven years. The fast of recompense for game taken in the sacred state, which varies according to what is ruled by the one to whom God has entrusted the ruling in it. The fast for shaving the head on account of harm.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'the fast of itikaf the fast of shaban the fast of the first thursday of every month the fast of the middle wednesday of that month the fast of the last thursday of that month the fast of the three white days the fast of dawud ع which is fasting one day and breaking the fast the next and it is the most rigorous of fasts the fast of friday joined to thursday or to saturday without singling out friday alone for fasting the fast of the day of arafah for one who is not on pilgrimage the fast of the boy when he reaches seven years the fast of recompense for game taken in the sacred state which varies according to what is ruled by the one to whom god has entrusted the ruling in it the fast for shaving the head on account of harm', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 21, NULL, 'Our master Zaid ibn Muhammad, may God sanctify his soul, stated in the Concealed Epistle: God Almighty imposed upon His servants, after the performance of prayer and the giving of zakat, the fasting of the month of Ramadan, and He commanded that one month out of twelve be fasted. He stated therein: just as the fasting of the month of Ramadan is obligatory, it is thirty days.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'our master zaid ibn muhammad may god sanctify his soul stated in the concealed epistle god almighty imposed upon his servants after the performance of prayer and the giving of zakat the fasting of the month of ramadan and he commanded that one month out of twelve be fasted he stated therein just as the fasting of the month of ramadan is obligatory it is thirty days', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 22, NULL, 'Mawlana Amir al-Muminin Ali ibn Abi Talib (ع) stated in his Four Hundred Manners:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'mawlana amir al muminin ali ibn abi talib ع stated in his four hundred manners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 23, NULL, 'Sayingصَوْمُ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَصَوْمُ شَعْبَانَ يُذْهِبُ بِوَسْوَاسِ الصَّدْرِ وَبَلَابِلِ الْقَلْبِ', '', 'صَوْمُ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَصَوْمُ شَعْبَانَ يُذْهِبُ بِوَسْوَاسِ الصَّدْرِ وَبَلَابِلِ الْقَلْبِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'sayingصوم ثلاثه ايام من كل شهر وصوم شعبان يذهب بوسواس الصدر وبلابل القلب', 'صوم ثلاثه ايام من كل شهر وصوم شعبان يذهب بوسواس الصدر وبلابل القلب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'a shield against the fire', '30. A Shield Against the Fire', 24, NULL, 'Fasting three days of every month, and fasting Shaban, drive away the whisperings of the breast and the disquiet of the heart.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 30 a shield against the fire', 'fasting three days of every month and fasting shaban drive away the whisperings of the breast and the disquiet of the heart', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 0, NULL, 'I turn now to the sighting of the crescent moon: what has been said about it, and what runs along the same course.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'i turn now to the sighting of the crescent moon what has been said about it and what runs along the same course', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 1, NULL, 'I find in the Book of Clarification that what has come down concerning fasting by the sighting of the crescent — together with what is mentioned in this chapter and in the two chapters before it — is directed to whoever is absent from the presence of the Imam and does not know the measures of the crescent moons. Our master and mawlana Sulayman ibn Hasan, may God exalt his sanctity in the chambers of the Gardens of Eden, treated this matter at the opening of his noble epistle known as the Ijadiyya, containing the Ahmadi secrets and the golden jewels drawn from the most glorious benefits. After he had spoken there of what is prior and more fitting, and after the restatement of both, he explained that when the moon has traveled twenty-eight stations after parting from the sun, it requires the traversal of the first two stations in order to overtake the sun once more, because during that period the sun has itself advanced two complete stations and a degree of the third. The moon therefore meets the sun at thirty stations, and the reckoners count this as one month.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'i find in the book of clarification that what has come down concerning fasting by the sighting of the crescent together with what is mentioned in this chapter and in the two chapters before it is directed to whoever is absent from the presence of the imam and does not know the measures of the crescent moons our master and mawlana sulayman ibn hasan may god exalt his sanctity in the chambers of the gardens of eden treated this matter at the opening of his noble epistle known as the ijadiyya containing the ahmadi secrets and the golden jewels drawn from the most glorious benefits after he had spoken there of what is prior and more fitting and after the restatement of both he explained that when the moon has traveled twenty eight stations after parting from the sun it requires the traversal of the first two stations in order to overtake the sun once more because during that period the sun has itself advanced two complete stations and a degree of the third the moon therefore meets the sun at thirty stations and the reckoners count this as one month', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 2, NULL, 'Our master and mawlana, the most exalted summoner al-Muayyad fil-Din, may God exalt his sanctity, spoke on this in the forty-second session of the first hundred of his noble Muayyadi sessions — those known as the Wisdom Sessions — in refutation of those among the people who make fasting depend upon the sighting of the crescent.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'our master and mawlana the most exalted summoner al muayyad fil din may god exalt his sanctity spoke on this in the forty second session of the first hundred of his noble muayyadi sessions those known as the wisdom sessions in refutation of those among the people who make fasting depend upon the sighting of the crescent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 3, NULL, 'The claimants have claimed that the month of Ramadan is sometimes complete and sometimes deficient, and that its fast is founded upon the sighting of the crescent. They have argued for this by the saying of the Prophet (ع):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'the claimants have claimed that the month of ramadan is sometimes complete and sometimes deficient and that its fast is founded upon the sighting of the crescent they have argued for this by the saying of the prophet ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 4, NULL, 'Sayingصُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ غُمَّ عَلَيْكُمْ فَأَكْمِلُوا ثَلَاثِينَ', '', 'صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ غُمَّ عَلَيْكُمْ فَأَكْمِلُوا ثَلَاثِينَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'sayingصوموا لرويته وافطروا لرويته فان غم عليكم فاكملوا ثلاثين', 'صوموا لرويته وافطروا لرويته فان غم عليكم فاكملوا ثلاثين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 5, NULL, 'Fast when it is seen and break your fast when it is seen; and if it is hidden from you, then complete thirty.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'fast when it is seen and break your fast when it is seen and if it is hidden from you then complete thirty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 6, NULL, 'This statement of theirs is unsound in several respects, which we shall set out, and we shall establish the proofs that the month of Ramadan is always complete and that no deficiency befalls it in any circumstance whatever.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'this statement of theirs is unsound in several respects which we shall set out and we shall establish the proofs that the month of ramadan is always complete and that no deficiency befalls it in any circumstance whatever', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 7, NULL, 'We begin with the reply to whoever argues from the report "fast when it is seen and break your fast when it is seen." We say to them: you yourselves acknowledge that the sense of this report is that the Messenger of Allah (ع), when he wished to set out on one of the campaigns near the month of Ramadan, was approached by his companions, who gathered to him and said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'we begin with the reply to whoever argues from the report fast when it is seen and break your fast when it is seen we say to them you yourselves acknowledge that the sense of this report is that the messenger of allah ع when he wished to set out on one of the campaigns near the month of ramadan was approached by his companions who gathered to him and said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 8, NULL, 'Sayingيَا رَسُولَ اللَّهِ كُنَّا نَصُومُ بِصَوْمِكَ وَنُفْطِرُ بِإِفْطَارِكَ فَكَيْفَ يَجْرِي حَالُنَا فِي غَيْبَتِكَ', '', 'يَا رَسُولَ اللَّهِ كُنَّا نَصُومُ بِصَوْمِكَ وَنُفْطِرُ بِإِفْطَارِكَ فَكَيْفَ يَجْرِي حَالُنَا فِي غَيْبَتِكَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'sayingيا رسول الله كنا نصوم بصومك ونفطر بافطارك فكيف يجري حالنا في غيبتك', 'يا رسول الله كنا نصوم بصومك ونفطر بافطارك فكيف يجري حالنا في غيبتك');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 9, NULL, 'O Messenger of Allah, we used to fast by your fasting and break our fast by your breaking of the fast; how then shall our case run in your absence?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'o messenger of allah we used to fast by your fasting and break our fast by your breaking of the fast how then shall our case run in your absence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 10, NULL, 'The Messenger of Allah (ع) said: fast when it is seen and break your fast when it is seen. The report thus indicates that fasting is obligatory by the fasting of the Messenger when he is present, or by the fasting of the one who stands in his place when he is absent, and that breaking the fast is obligatory by his breaking of the fast, and that fasting upon the sighting of the crescent belongs to the matters of necessity at the time when the Messenger and the Imam who stands in his place are not present. When the Messenger is present, or the Imam is present, the rule of the obligation is that one fasts by his fasting and breaks the fast by his breaking of it, just as the people said to the Prophet (ع): we used to fast by your fasting and break our fast by your breaking of the fast.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'the messenger of allah ع said fast when it is seen and break your fast when it is seen the report thus indicates that fasting is obligatory by the fasting of the messenger when he is present or by the fasting of the one who stands in his place when he is absent and that breaking the fast is obligatory by his breaking of the fast and that fasting upon the sighting of the crescent belongs to the matters of necessity at the time when the messenger and the imam who stands in his place are not present when the messenger is present or the imam is present the rule of the obligation is that one fasts by his fasting and breaks the fast by his breaking of it just as the people said to the prophet ع we used to fast by your fasting and break our fast by your breaking of the fast', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 11, NULL, 'As for the saying of the one who claims that the Prophet (ع) used to fast by the sighting of the crescent, it is unsound in three respects, two of them legal and one rational.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'as for the saying of the one who claims that the prophet ع used to fast by the sighting of the crescent it is unsound in three respects two of them legal and one rational', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 12, NULL, 'As for the first of the two legal respects: it is well known that the Prophet (ع) used to say — and he is truthful — that the Trustworthy Spirit, Gabriel (ع), came upon him morning and evening with revelation and with the noble Quran. One to whom Gabriel (ع) comes morning and evening with the tidings of heaven has no need to turn his face about seeking the crescent when he has with him one who brings him certain news. Were he to go out toward the sky seeking a crescent, it would nullify his own saying that Gabriel descends upon him, and it would be said to him: why did you not ask him about it? So his independence of any searching is established.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'as for the first of the two legal respects it is well known that the prophet ع used to say and he is truthful that the trustworthy spirit gabriel ع came upon him morning and evening with revelation and with the noble quran one to whom gabriel ع comes morning and evening with the tidings of heaven has no need to turn his face about seeking the crescent when he has with him one who brings him certain news were he to go out toward the sky seeking a crescent it would nullify his own saying that gabriel descends upon him and it would be said to him why did you not ask him about it so his independence of any searching is established', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 13, NULL, 'The other respect is that it is handed down from him (ع) in the reports that he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'the other respect is that it is handed down from him ع in the reports that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 14, NULL, 'Sayingأَنَا بِطُرُقَاتِ السَّمَاءِ أَعْرَفُ مِنْكُمْ بِطُرُقَاتِ الْأَرْضِ', '', 'أَنَا بِطُرُقَاتِ السَّمَاءِ أَعْرَفُ مِنْكُمْ بِطُرُقَاتِ الْأَرْضِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'sayingانا بطرقات السماء اعرف منكم بطرقات الارض', 'انا بطرقات السماء اعرف منكم بطرقات الارض');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 15, NULL, 'Sayingأَنَا أَعْرِفُ مَنَازِلَ السَّمَاءِ أَحْسَنَ مِمَّا تَعْرِفُونَ مَنَازِلَ الْأَرْضِ.', '', 'أَنَا أَعْرِفُ مَنَازِلَ السَّمَاءِ أَحْسَنَ مِمَّا تَعْرِفُونَ مَنَازِلَ الْأَرْضِ.', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'sayingانا اعرف منازل السماء احسن مما تعرفون منازل الارض', 'انا اعرف منازل السماء احسن مما تعرفون منازل الارض');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 16, NULL, 'Had he been observed going out to seek the crescent after saying this, people would rightly have asked him: what then becomes of your words of yesterday — that you know the roads of the sky better than we know the roads of the earth?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'had he been observed going out to seek the crescent after saying this people would rightly have asked him what then becomes of your words of yesterday that you know the roads of the sky better than we know the roads of the earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 17, NULL, 'As for the rational ground: it is well established that the Prophet (ع) stands far above any ignorance of the differences in crescent risings and their degrees — a matter scarcely hidden even from an ordinary astronomer — and that earthly locations differ as well. Some are elevated, making the sighting of the crescent swifter there — such as mountain summits and what runs in their course; others are low-lying, making the sighting slower. Knowing that none of this was hidden from him — and that had it been hidden, it would have been the gravest deficiency, from which he is wholly free — how could reason possibly require that, with full knowledge of these visible differences, he should impose the obligation of fasting, which is bound up with the obligation of pilgrimage, upon all people by a single standard, while knowing that standard cannot hold? One people see the crescent on a given night; another people do not. Nor can it be sound that one and the same day should belong to Shaban where the crescent is not seen and to the month of Ramadan where it is seen. No reasonable person doubts this; only an ignorant man rejects it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'as for the rational ground it is well established that the prophet ع stands far above any ignorance of the differences in crescent risings and their degrees a matter scarcely hidden even from an ordinary astronomer and that earthly locations differ as well some are elevated making the sighting of the crescent swifter there such as mountain summits and what runs in their course others are low lying making the sighting slower knowing that none of this was hidden from him and that had it been hidden it would have been the gravest deficiency from which he is wholly free how could reason possibly require that with full knowledge of these visible differences he should impose the obligation of fasting which is bound up with the obligation of pilgrimage upon all people by a single standard while knowing that standard cannot hold one people see the crescent on a given night another people do not nor can it be sound that one and the same day should belong to shaban where the crescent is not seen and to the month of ramadan where it is seen no reasonable person doubts this only an ignorant man rejects it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 18, NULL, 'Beyond this, God, glory be to Him, has said in the firm text of His Book:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'beyond this god glory be to him has said in the firm text of his book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 19, NULL, 'Al-Baqarah: 183كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', '', 'كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', 'Al-Baqarah: 183', 2, 183, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'al baqarah 183كتب عليكم الصيام كما كتب علي الذين من قبلكم لعلكم تتقون', 'كتب عليكم الصيام كما كتب علي الذين من قبلكم لعلكم تتقون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 20, NULL, 'Fasting is prescribed for you as it was prescribed for those before you, so that you may be mindful of God.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'fasting is prescribed for you as it was prescribed for those before you so that you may be mindful of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 21, NULL, '"Those before you" refers to the Christians, whose fasting is governed not by sighting but by calculation. He then said, confirming that:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'those before you refers to the christians whose fasting is governed not by sighting but by calculation he then said confirming that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 22, NULL, 'Sayingأَيَّامًا مَعْدُودَاتٍ', '', 'أَيَّامًا مَعْدُودَاتٍ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'sayingاياما معدودات', 'اياما معدودات');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 23, NULL, 'for a counted number of days.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'for a counted number of days', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 24, NULL, 'Counted days are days that remain always counted, requiring neither sighting nor observation. Had the month of Ramadan been capable of being thirty days at one time and twenty-nine at another, He would certainly not have said "a counted number of days." It is like saying: this is a reckoned reckoning, and this is a counted dirham.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'counted days are days that remain always counted requiring neither sighting nor observation had the month of ramadan been capable of being thirty days at one time and twenty nine at another he would certainly not have said a counted number of days it is like saying this is a reckoned reckoning and this is a counted dirham', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 25, NULL, 'A further argument is this: since the year is ordered so that six of its months are complete and six deficient, its root and structure must rest on completeness rather than deficiency. The sequence runs as follows:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'a further argument is this since the year is ordered so that six of its months are complete and six deficient its root and structure must rest on completeness rather than deficiency the sequence runs as follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 26, NULL, 'Muharram: complete Safar: deficient Rabi al-Awwal: complete Rabi al-Akhir: deficient Jumada al-Ula: complete Jumada al-Akhira: deficient Rajab: complete Shaban: deficient The month of Ramadan: complete', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'muharram complete safar deficient rabi al awwal complete rabi al akhir deficient jumada al ula complete jumada al akhira deficient rajab complete shaban deficient the month of ramadan complete', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 27, NULL, 'The Prophet (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'the prophet ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 28, NULL, 'Sayingمَا تَمَّ شَعْبَانُ وَلَا نَقَصَ رَمَضَانُ', '', 'مَا تَمَّ شَعْبَانُ وَلَا نَقَصَ رَمَضَانُ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'sayingما تم شعبان ولا نقص رمضان', 'ما تم شعبان ولا نقص رمضان');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 29, NULL, 'Shaban is never complete, and Ramadan is never deficient.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'shaban is never complete and ramadan is never deficient', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 30, NULL, 'The proof of Shaban''s deficiency lies in the night that falls at its midpoint — a true middle night, with no equivalent in Rajab or in Ramadan. The fifteenth night of Shaban is its genuine midpoint: fourteen nights precede it and fourteen follow it, placing it exactly in the center. Ramadan admits no such midpoint. To call its fifteenth night the middle fails, because fifteen days of the month still remain after it. To call its sixteenth night the middle fails equally, because sixteen is not half of thirty.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'the proof of shabans deficiency lies in the night that falls at its midpoint a true middle night with no equivalent in rajab or in ramadan the fifteenth night of shaban is its genuine midpoint fourteen nights precede it and fourteen follow it placing it exactly in the center ramadan admits no such midpoint to call its fifteenth night the middle fails because fifteen days of the month still remain after it to call its sixteenth night the middle fails equally because sixteen is not half of thirty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 31, NULL, 'A further sign of Ramadan''s completeness is the structure of the expiations prescribed for anyone who willfully breaks his fast during it: he must fast two consecutive months as an act of repentance to God — that is, sixty days, like the month of Ramadan — and if he is not able, then the feeding of sixty poor persons. Were it possible for the month of Ramadan to be twenty-nine days, it would be possible for the expiation to be the feeding of sixty poor persons or of fifty-eight poor persons. Praise God, then, O believers, for what He has preserved you from of deficiency in your religion, and for the success He has granted you in fulfilling the conditions of faith by following your masters, the friends of the Merciful.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'a further sign of ramadans completeness is the structure of the expiations prescribed for anyone who willfully breaks his fast during it he must fast two consecutive months as an act of repentance to god that is sixty days like the month of ramadan and if he is not able then the feeding of sixty poor persons were it possible for the month of ramadan to be twenty nine days it would be possible for the expiation to be the feeding of sixty poor persons or of fifty eight poor persons praise god then o believers for what he has preserved you from of deficiency in your religion and for the success he has granted you in fulfilling the conditions of faith by following your masters the friends of the merciful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 32, NULL, 'He, may God exalt his sanctity, spoke of the like of this in the book of his noble life. He relates that he attended upon King Abu Kalijar al-Daylami, lord of Shiraz and of Iraq al-Ajam and its king, and that a sharif from the notables of the Zaydi school was brought before him. Speech passed between the two of them on the matter of fasting and its obligation, and whether it rests upon sighting or upon something other than the known sighting. He says that the aforementioned sharif said to him in this connection: it is related of the Messenger of Allah (ع) that he gathered his five fingers and said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'he may god exalt his sanctity spoke of the like of this in the book of his noble life he relates that he attended upon king abu kalijar al daylami lord of shiraz and of iraq al ajam and its king and that a sharif from the notables of the zaydi school was brought before him speech passed between the two of them on the matter of fasting and its obligation and whether it rests upon sighting or upon something other than the known sighting he says that the aforementioned sharif said to him in this connection it is related of the messenger of allah ع that he gathered his five fingers and said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 33, NULL, 'Sayingنَحْنُ أُمِّيُّونَ لَا نَحْسِبُ الْحِسَابَ الصَّوْمُ مَرَّةً هَكَذَا', '', 'نَحْنُ أُمِّيُّونَ لَا نَحْسِبُ الْحِسَابَ الصَّوْمُ مَرَّةً هَكَذَا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'sayingنحن اميون لا نحسب الحساب الصوم مره هكذا', 'نحن اميون لا نحسب الحساب الصوم مره هكذا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 34, NULL, 'We are unlettered; we do not reckon the reckoning. The fast is once like this.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'we are unlettered we do not reckon the reckoning the fast is once like this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 35, NULL, 'He continued until he had completed the count of thirty in six turns; then he gathered his fingers a second time, and when he came to the last he withheld one finger and said: and once like this.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'he continued until he had completed the count of thirty in six turns then he gathered his fingers a second time and when he came to the last he withheld one finger and said and once like this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 36, NULL, 'Our master al-Muayyad fil-Din, may God sanctify his soul, said to him: God forbid that the Prophet (ع) — whom God honored with the ascension and to whom He revealed what lies beyond the veil — should be charged with such halting speech and such inarticulacy, and should be so unlettered that he could not distinguish thirty from twenty-nine with his tongue, and instead had to gather his fingers and move his hand these many times, in the manner of one who herds cattle and sheep. Moreover, the Prophet (ع) said: I know the roads of the sky better than you know the roads of the earth. Had he — this mighty saying being taken as settled and confined to him — then risen to scan the sky in search of the crescent, the people would have risen to confront him, saying: where does this leave your claim of yesterday, that you know the roads of the sky better than we know the roads of the earth? And besides this, were the seeking of the crescent a thing whose obligation and necessity were established, it would be so for us in particular, while he (ع) would have no need of it, since Gabriel (ع) informs him that the crescent has appeared. His asking Gabriel about that would be more fitting for him than his scanning the sky on his own account, thereby rendering the descent of revelation upon him of no effect. Indeed, if one of us found a way to an angel among the angels to ask for a ruling and for tidings of hidden matters, he would not rely upon himself in searching and striving. This is a thing upon which no proof and no demonstration can stand.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'our master al muayyad fil din may god sanctify his soul said to him god forbid that the prophet ع whom god honored with the ascension and to whom he revealed what lies beyond the veil should be charged with such halting speech and such inarticulacy and should be so unlettered that he could not distinguish thirty from twenty nine with his tongue and instead had to gather his fingers and move his hand these many times in the manner of one who herds cattle and sheep moreover the prophet ع said i know the roads of the sky better than you know the roads of the earth had he this mighty saying being taken as settled and confined to him then risen to scan the sky in search of the crescent the people would have risen to confront him saying where does this leave your claim of yesterday that you know the roads of the sky better than we know the roads of the earth and besides this were the seeking of the crescent a thing whose obligation and necessity were established it would be so for us in particular while he ع would have no need of it since gabriel ع informs him that the crescent has appeared his asking gabriel about that would be more fitting for him than his scanning the sky on his own account thereby rendering the descent of revelation upon him of no effect indeed if one of us found a way to an angel among the angels to ask for a ruling and for tidings of hidden matters he would not rely upon himself in searching and striving this is a thing upon which no proof and no demonstration can stand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 37, NULL, 'The Alid was so shamed by this reply that he rose stumbling in his own robes, until those standing in the outer ranks and the masters began to laugh at him and mock him. Then each of us withdrew to his house.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'the alid was so shamed by this reply that he rose stumbling in his own robes until those standing in the outer ranks and the masters began to laugh at him and mock him then each of us withdrew to his house', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 38, NULL, 'Some of the summoners, may God sanctify their souls, spoke of the like of this in the argument against the opponents, for guidance along the paths, in the form of a question:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'some of the summoners may god sanctify their souls spoke of the like of this in the argument against the opponents for guidance along the paths in the form of a question', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 39, NULL, 'What do the eminent scholars among all the people of Islam say concerning the saying of the Lord of Majesty and Honor:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'what do the eminent scholars among all the people of islam say concerning the saying of the lord of majesty and honor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 40, NULL, 'Sayingيَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ أَيَّامًا مَعْدُودَاتٍ فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ', '', 'يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ أَيَّامًا مَعْدُودَاتٍ فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'sayingيا ايها الذين امنوا كتب عليكم الصيام كما كتب علي الذين من قبلكم لعلكم تتقون اياما معدودات فمن كان منكم مريضا او علي سفر فعده من ايام اخر', 'يا ايها الذين امنوا كتب عليكم الصيام كما كتب علي الذين من قبلكم لعلكم تتقون اياما معدودات فمن كان منكم مريضا او علي سفر فعده من ايام اخر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 41, NULL, '"O you who believe, fasting is prescribed for you as it was prescribed for those before you, so that you may be mindful of God, for a counted number of days; and whoever among you is sick or on a journey, then a number of other days" — up to His saying, mighty and majestic:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'o you who believe fasting is prescribed for you as it was prescribed for those before you so that you may be mindful of god for a counted number of days and whoever among you is sick or on a journey then a number of other days up to his saying mighty and majestic', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 42, NULL, 'Al-Baqarah: 185فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍۢ فَعِدَّةٌۭ مِّنْ أَيَّامٍ أُخَرَ يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ', '', 'فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍۢ فَعِدَّةٌۭ مِّنْ أَيَّامٍ أُخَرَ يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ', 'Al-Baqarah: 185', 2, 185, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'al baqarah 185فمن شهد منكم الشهر فليصمه ومن كان مريضا او علي سفر فعده من ايام اخر يريد الله بكم اليسر ولا يريد بكم العسر ولتكملوا العده ولتكبروا الله علي ما هداكم ولعلكم تشكرون', 'فمن شهد منكم الشهر فليصمه ومن كان مريضا او علي سفر فعده من ايام اخر يريد الله بكم اليسر ولا يريد بكم العسر ولتكملوا العده ولتكبروا الله علي ما هداكم ولعلكم تشكرون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 43, NULL, 'Who, then, did God intend by His words "those before you, so that you may be mindful of God"? Who are "those before"? How many are the counted days? And what is the witnessing of the month?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'who then did god intend by his words those before you so that you may be mindful of god who are those before how many are the counted days and what is the witnessing of the month', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 44, NULL, 'The scholars of the Arabic language have said that الشهر (al-shahr) means the crescent. Others have said that the month is a counted number of days in its entirety, completed when it ends and the next month begins. In the words of God the Exalted:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'the scholars of the arabic language have said that الشهر al shahr means the crescent others have said that the month is a counted number of days in its entirety completed when it ends and the next month begins in the words of god the exalted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 45, NULL, 'Al-Baqarah: 185شَهْرُ رَمَضَانَ ٱلَّذِىٓ أُنزِلَ فِيهِ ٱلْقُرْآنُ', '', 'شَهْرُ رَمَضَانَ ٱلَّذِىٓ أُنزِلَ فِيهِ ٱلْقُرْآنُ', 'Al-Baqarah: 185', 2, 185, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'al baqarah 185شهر رمضان الذي انزل فيه القران', 'شهر رمضان الذي انزل فيه القران');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 46, NULL, 'The month of Ramadan in which the Quran was sent down.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'the month of ramadan in which the quran was sent down', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 47, NULL, 'there is an indication that it was sent down in counted days, not in the crescent. God has declared that the number of months in His reckoning is twelve:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'there is an indication that it was sent down in counted days not in the crescent god has declared that the number of months in his reckoning is twelve', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 48, NULL, 'At-Tawbah: 36إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًۭا فِى كِتَبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَوَتِ وَٱلْأَرْضَ مِنْهَآ أَرْبَعَةٌ حُرُمٌۭ', '', 'إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًۭا فِى كِتَبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَوَتِ وَٱلْأَرْضَ مِنْهَآ أَرْبَعَةٌ حُرُمٌۭ', 'At-Tawbah: 36', 9, 36, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'at tawbah 36ان عده الشهور عند الله اثنا عشر شهرا في كتب الله يوم خلق السموت والارض منها اربعه حرم', 'ان عده الشهور عند الله اثنا عشر شهرا في كتب الله يوم خلق السموت والارض منها اربعه حرم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 49, NULL, 'The number of months with God is twelve months in the Book of God, from the day He created the heavens and the earth; four of them are sacred.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'the number of months with god is twelve months in the book of god from the day he created the heavens and the earth four of them are sacred', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 50, NULL, 'I note that only one crescent is known — one that waxes until it becomes a full moon, then wanes through the remaining days of the month — while the months themselves run from Muharram to Dhu al-Hijja.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'i note that only one crescent is known one that waxes until it becomes a full moon then wanes through the remaining days of the month while the months themselves run from muharram to dhu al hijja', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 51, NULL, 'Some have argued, with regard to His saying "so whoever among you witnesses the month, let him fast it," that it means: when one looks upon the crescent. They further take His saying "and whoever among you is sick or on a journey" to indicate that the witness in view is the resident, as opposed to the absent traveler; and it is the resident who fasts and is granted no dispensation to break it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'some have argued with regard to his saying so whoever among you witnesses the month let him fast it that it means when one looks upon the crescent they further take his saying and whoever among you is sick or on a journey to indicate that the witness in view is the resident as opposed to the absent traveler and it is the resident who fasts and is granted no dispensation to break it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 52, NULL, 'Then there is His saying "and that you complete the count and magnify God for having guided you." What count is meant here, and how much does it amount to? The magnification falls at the festival of breaking the fast, after the fasting is completed. Is the completed count of the month thirty days, or twenty-nine, or twenty-eight? And which of these is the fuller count and the longer span?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'then there is his saying and that you complete the count and magnify god for having guided you what count is meant here and how much does it amount to the magnification falls at the festival of breaking the fast after the fasting is completed is the completed count of the month thirty days or twenty nine or twenty eight and which of these is the fuller count and the longer span', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 53, NULL, 'The Prophet (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'the prophet ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 54, NULL, 'Sayingمَا أَتَاكُمْ عَنِّي فَاعْرِضُوهُ عَلَى كِتَابِ اللَّهِ فَمَا وَافَقَ كِتَابَ اللَّهِ فَأَنَا قُلْتُهُ وَمَا خَالَفَهُ فَلَمْ أَقُلْهُ وَكَيْفَ أُخَالِفُ كِتَابَ اللَّهِ وَعَلَيَّ نَزَلَ"Whatever comes to you from me, set it against the Book of God. Whatever agrees with the Book of God, I said it; and whatever contradicts it, I did not say it. How should I contradict the Book of God when it was sent down upon me?"', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'sayingما اتاكم عني فاعرضوه علي كتاب الله فما وافق كتاب الله فانا قلته وما خالفه فلم اقله وكيف اخالف كتاب الله وعلي نزل whatever comes to you from me set it against the book of god whatever agrees with the book of god i said it and whatever contradicts it i did not say it how should i contradict the book of god when it was sent down upon me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 55, NULL, 'Now, those who fast by the rising of the crescent may fall short of completing the count of thirty. They have related from the Prophet (ع) that he said: fast when it is seen and break your fast when it is seen. Yet this, by their own account, does not accord with the complete count that the noble Book has declared. Surely in that is a reminder for those possessed of understanding.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'now those who fast by the rising of the crescent may fall short of completing the count of thirty they have related from the prophet ع that he said fast when it is seen and break your fast when it is seen yet this by their own account does not accord with the complete count that the noble book has declared surely in that is a reminder for those possessed of understanding', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 56, NULL, 'Then there has come down from the Prophet (ع), in what al-Sadiq Jafar ibn Muhammad (ع) related, that he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'then there has come down from the prophet ع in what al sadiq jafar ibn muhammad ع related that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 57, NULL, 'Sayingمَا تَمَّ شَعْبَانُ وَلَا نَقَصَ شَهْرُ رَمَضَانَ', '', 'مَا تَمَّ شَعْبَانُ وَلَا نَقَصَ شَهْرُ رَمَضَانَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'sayingما تم شعبان ولا نقص شهر رمضان', 'ما تم شعبان ولا نقص شهر رمضان');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 58, NULL, 'Shaban is never complete, and the month of Ramadan is never deficient.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'shaban is never complete and the month of ramadan is never deficient', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 59, NULL, 'This accords with the plain Book, and the completeness of the month''s count at thirty days is thereby established.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'this accords with the plain book and the completeness of the months count at thirty days is thereby established', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 60, NULL, 'We found the saying of the Prophet (ع), "fast when it is seen and break your fast when it is seen," to indicate the anticipation of its sighting. Examining what the scholars of the language have recorded about the uses of the letter ل (اَللَّام), we found this lam to be the lam of anticipation — as one of them recorded in verse:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'we found the saying of the prophet ع fast when it is seen and break your fast when it is seen to indicate the anticipation of its sighting examining what the scholars of the language have recorded about the uses of the letter ل اللام we found this lam to be the lam of anticipation as one of them recorded in verse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 61, NULL, 'Sayingفَلِلْمَوْتِ تَغْذُوا الْوَالِدَاتُ عِيَالَهَا كَمَا لِخَرَابِ الدَّارِ تُبْنَى الْمَسَاكِنَا', '', 'فَلِلْمَوْتِ تَغْذُوا الْوَالِدَاتُ عِيَالَهَا كَمَا لِخَرَابِ الدَّارِ تُبْنَى الْمَسَاكِنَا', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'sayingفللموت تغذوا الوالدات عيالها كما لخراب الدار تبني المساكنا', 'فللموت تغذوا الوالدات عيالها كما لخراب الدار تبني المساكنا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 62, NULL, 'Mothers nourish their children for death, just as dwellings are built for the ruin of the house.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'mothers nourish their children for death just as dwellings are built for the ruin of the house', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 63, NULL, 'And another said: they were born for death, and they built for ruin. Of this same kind is the saying of God the Exalted in the Book:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'and another said they were born for death and they built for ruin of this same kind is the saying of god the exalted in the book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 64, NULL, 'Sad: 53هَذَا مَا تُوعَدُونَ لِيَوْمِ ٱلْحِسَابِ', '', 'هَذَا مَا تُوعَدُونَ لِيَوْمِ ٱلْحِسَابِ', 'Sad: 53', 38, 53, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'sad 53هذا ما توعدون ليوم الحساب', 'هذا ما توعدون ليوم الحساب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 65, NULL, 'This is what you are promised for the Day of Reckoning.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'this is what you are promised for the day of reckoning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 66, NULL, 'God stated the promise first and then said "for the Day of Reckoning," making the lam the lam of outcome (لَامُ الْعَاقِبَةِ); and this agrees with what we have said, and it is the most fitting and correct view. So the saying of the Prophet (ع), "fast when it is seen," means: let it rise while you are fasting; and "break your fast when it is seen" means: let it rise while you are breaking the fast. And God knows best.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'god stated the promise first and then said for the day of reckoning making the lam the lam of outcome لام العاقبه and this agrees with what we have said and it is the most fitting and correct view so the saying of the prophet ع fast when it is seen means let it rise while you are fasting and break your fast when it is seen means let it rise while you are breaking the fast and god knows best', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 67, NULL, 'If you say otherwise, then bring your proof concerning the completeness of the month''s count that the Quran has declared. And why did the Messenger of Allah (ع) not say, fast after seeing it and break your fast after seeing it, so that the matter would be clearer to his community? For it is said: work for a day on which you shall be raised:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'if you say otherwise then bring your proof concerning the completeness of the months count that the quran has declared and why did the messenger of allah ع not say fast after seeing it and break your fast after seeing it so that the matter would be clearer to his community for it is said work for a day on which you shall be raised', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 68, NULL, 'Sayingاِعْمَلُوا لِيَوْمٍ فِيهِ تُبْعَثُونَ وَيَكُونُ لِلْآخِرَةِ مَا تَعْمَلُونَ', '', 'اِعْمَلُوا لِيَوْمٍ فِيهِ تُبْعَثُونَ وَيَكُونُ لِلْآخِرَةِ مَا تَعْمَلُونَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'sayingاعملوا ليوم فيه تبعثون ويكون للاخره ما تعملون', 'اعملوا ليوم فيه تبعثون ويكون للاخره ما تعملون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 69, NULL, 'Work for a day on which you will be raised up, and let what you do be for the hereafter.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'work for a day on which you will be raised up and let what you do be for the hereafter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 70, NULL, 'The revealed Book, then, agrees with the saying of the Prophet who was sent. Bring us the satisfying answer, for we do not walk the road of obstinacy or the rejection of what is plain to the eye. Praise be to God, the High, the Bestower, Lord of bounty, favor, and kindness. May God bless His Messenger to all mankind and jinn, and his family and his companions, who made clear the meanings of the Quran, for as long as night and day alternate and the two ages follow one another; and may He grant them peace, mercy, and honor. God suffices us, and He is the best guardian.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'the revealed book then agrees with the saying of the prophet who was sent bring us the satisfying answer for we do not walk the road of obstinacy or the rejection of what is plain to the eye praise be to god the high the bestower lord of bounty favor and kindness may god bless his messenger to all mankind and jinn and his family and his companions who made clear the meanings of the quran for as long as night and day alternate and the two ages follow one another and may he grant them peace mercy and honor god suffices us and he is the best guardian', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 71, NULL, 'Our master Zayd ibn Muhammad, may God sanctify his soul, said in his epistle known as the Maknuna, concerning the interpretation of the eclipse prayer, that God — blessed and exalted — when He created creation, ordained among them a wondrous ordinance whose beginning confirms its end. He made all that He created in the first age a proof for the people of the last age. He made the eclipse of the moon a veiling for it, and ordained that this veiling should fall when fourteen nights of the month have passed, though it may occur at thirteen nights; yet what is relied upon, and what happens most often, is at fourteen nights. In all of this are causes and proofs of God that stand as witnesses. He further ordained that the moon''s absence and concealment from the world should fall at twenty-eight nights in every month, so that in its concealment it is absent for two days and two nights — forty-eight hours in all — and then rises again after those forty-eight hours.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'our master zayd ibn muhammad may god sanctify his soul said in his epistle known as the maknuna concerning the interpretation of the eclipse prayer that god blessed and exalted when he created creation ordained among them a wondrous ordinance whose beginning confirms its end he made all that he created in the first age a proof for the people of the last age he made the eclipse of the moon a veiling for it and ordained that this veiling should fall when fourteen nights of the month have passed though it may occur at thirteen nights yet what is relied upon and what happens most often is at fourteen nights in all of this are causes and proofs of god that stand as witnesses he further ordained that the moons absence and concealment from the world should fall at twenty eight nights in every month so that in its concealment it is absent for two days and two nights forty eight hours in all and then rises again after those forty eight hours', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the quarrel over the crescent', '31. The Quarrel Over the Crescent', 72, NULL, 'What follows is the blessed epistle on the month of Ramadan, known as al-Lazima, treating the fast of the month of Ramadan and its proper time. It is by our master and mawlana, the most exalted, unique, and brilliant summoner Ahmad Hamid al-Din ibn Abdallah al-Kirmani, may God exalt his sanctity and grant us his intercession and his companionship — the proof of our mawlana al-Hakim bi-Amr Allah, Commander of the Faithful, may God bless him.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 31 the quarrel over the crescent', 'what follows is the blessed epistle on the month of ramadan known as al lazima treating the fast of the month of ramadan and its proper time it is by our master and mawlana the most exalted unique and brilliant summoner ahmad hamid al din ibn abdallah al kirmani may god exalt his sanctity and grant us his intercession and his companionship the proof of our mawlana al hakim bi amr allah commander of the faithful may god bless him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 0, NULL, 'In the name of God, the Merciful, the Compassionate, and in Him I place my trust.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'in the name of god the merciful the compassionate and in him i place my trust', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 1, NULL, 'Praise be to Allah, through whose grace good deeds reach completion, and through obedience to His guardians blessings spread to all. May Allah bless His messenger and servant Muhammad — the finest of mankind and the glory of the noble messengers who came before him — and bless the righteous among his pure progeny, those beacons of guidance and moons of the dark night, and grant them abundant peace.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'praise be to allah through whose grace good deeds reach completion and through obedience to his guardians blessings spread to all may allah bless his messenger and servant muhammad the finest of mankind and the glory of the noble messengers who came before him and bless the righteous among his pure progeny those beacons of guidance and moons of the dark night and grant them abundant peace', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 2, NULL, 'To proceed: my brother, you wrote to me noting that the people of division and disagreement — true to the habits they have long cultivated — have set themselves against the people of truth and concord. Their objections have multiplied in challenge, faulting them in community matters and reproaching them for beginning the fast before the general public. You asked me to clarify the question of entering the fast among the Shia of the Commander of the Faithful (ع), and in particular the fast of the year four hundred, in which commands issued from the Pure Presence made it obligatory to begin the fast two days before the crescent was seen with the eye. You asked me to set out the reason for this with statement, clarification, and proof.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'to proceed my brother you wrote to me noting that the people of division and disagreement true to the habits they have long cultivated have set themselves against the people of truth and concord their objections have multiplied in challenge faulting them in community matters and reproaching them for beginning the fast before the general public you asked me to clarify the question of entering the fast among the shia of the commander of the faithful ع and in particular the fast of the year four hundred in which commands issued from the pure presence made it obligatory to begin the fast two days before the crescent was seen with the eye you asked me to set out the reason for this with statement clarification and proof', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 3, NULL, 'I therefore resolved to compose this epistle, in which I would advance such healing proofs that the eyes of the discerning could graze at ease upon the order of its foundations, while the eyes of the opponents would smart at any attempt to take up its meanings. And so I say, seeking help from Allah and from His guardians upon His earth — (عَلَيْهِمُ السَّلَامُ) — and I have named it the necessary epistle on fasting the month of Ramadan and its time. For what I have placed within it are proofs binding upon the whole body of Muslims, from which they have no escape in the first principle of reason or of sense. Allah is the guardian of right success.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'i therefore resolved to compose this epistle in which i would advance such healing proofs that the eyes of the discerning could graze at ease upon the order of its foundations while the eyes of the opponents would smart at any attempt to take up its meanings and so i say seeking help from allah and from his guardians upon his earth عليهم السلام and i have named it the necessary epistle on fasting the month of ramadan and its time for what i have placed within it are proofs binding upon the whole body of muslims from which they have no escape in the first principle of reason or of sense allah is the guardian of right success', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 4, NULL, 'Know — may Allah preserve you from the disgrace of ignorance and guard you from the affliction of misguidance — that had the opposing party possessed discernment and insight, or had they any share in reason and understanding, the cunning of Satan would have been turned away from them and their aspirations directed toward the truth. They would have been among those whom Allah excepts in His Book when He says:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'know may allah preserve you from the disgrace of ignorance and guard you from the affliction of misguidance that had the opposing party possessed discernment and insight or had they any share in reason and understanding the cunning of satan would have been turned away from them and their aspirations directed toward the truth they would have been among those whom allah excepts in his book when he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 5, NULL, 'Sayingوَلَا يَزَالُونَ مُخْتَلِفِينَ اِلَّا مَنْ رَحِمَ رَبُّكَ"They will not cease to differ, except those upon whom your Lord has mercy."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'sayingولا يزالون مختلفين الا من رحم ربك they will not cease to differ except those upon whom your lord has mercy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 6, NULL, 'But they mounted the steed of caprice, and the causes of mere personal opinion carried them off. Satan made their conduct seem fair to them, and they followed him — all but a company of the believers. So the word of Allah came true of them:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'but they mounted the steed of caprice and the causes of mere personal opinion carried them off satan made their conduct seem fair to them and they followed him all but a company of the believers so the word of allah came true of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 7, NULL, 'Sayingأَفَلَمْ يَسِيرُوا فِي الْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌ يَعْمَلُونَ بِهَا أَوْ آذَانٌ يَسْمَعُونَ بِهَا فَأِنَّهَا لَا تَعْمَى الْأَبْصَارُ وَلَكِنَّ تَعْمَى الْقُلُوبُ الَّتِي فِي الصُّدُورِ"Have they not traveled through the land so that they might have hearts with which to understand, or ears with which to hear? For it is not the eyes that go blind, but the hearts within the breasts that go blind."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'sayingافلم يسيروا في الارض فتكون لهم قلوب يعملون بها او اذان يسمعون بها فانها لا تعمي الابصار ولكن تعمي القلوب التي في الصدور have they not traveled through the land so that they might have hearts with which to understand or ears with which to hear for it is not the eyes that go blind but the hearts within the breasts that go blind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 8, NULL, 'In such a state, they are like cattle — indeed, like the dead — and they do not perceive. As Allah Almighty said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'in such a state they are like cattle indeed like the dead and they do not perceive as allah almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 9, NULL, 'An-Nahl: 21أَمْوَتٌ غَيْرُ أَحْيَآءٍۢ وَمَا يَشْعُرُونَ"Dead, not living, and they do not perceive."', '', NULL, 'An-Nahl: 21', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'an nahl 21اموت غير احياء وما يشعرون dead not living and they do not perceive', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 10, NULL, 'They have died to the knowledge of realities and grown blind to them — blinded by their arrogance toward the people of truth, their insolence, and their willful disagreement. They have become like beasts in their disputes: wavering back and forth, stumbling about in their blindness, devoid of discernment or insight. They fell into this disagreement and separation — which Allah has forbidden — as He declares:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'they have died to the knowledge of realities and grown blind to them blinded by their arrogance toward the people of truth their insolence and their willful disagreement they have become like beasts in their disputes wavering back and forth stumbling about in their blindness devoid of discernment or insight they fell into this disagreement and separation which allah has forbidden as he declares', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 11, NULL, 'Ali ''Imran: 105وَلَا تَكُونُوا۟ كَٱلَّذِينَ تَفَرَّقُوا۟ وَٱخْتَلَفُوا۟"Do not be like those who separated and fell into disagreement."', '', NULL, 'Ali ''Imran: 105', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'ali imran 105ولا تكونوا كالذين تفرقوا واختلفوا do not be like those who separated and fell into disagreement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 12, NULL, 'They fell into it solely through their insolence, their arrogance, their envy, and their disdain for obeying the one whose obedience Allah has made obligatory among those charged with the Command — those to whom Allah Almighty directed that all disputed matters be referred, as He says:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'they fell into it solely through their insolence their arrogance their envy and their disdain for obeying the one whose obedience allah has made obligatory among those charged with the command those to whom allah almighty directed that all disputed matters be referred as he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 13, NULL, 'An-Nisa: 59فَإِن تَنَزَعْتُمْ فِى شَىْءٍۢ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ"If you dispute about anything, refer it to Allah and to the Messenger."', '', NULL, 'An-Nisa: 59', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'an nisa 59فان تنزعتم في شيء فردوه الي الله والرسول if you dispute about anything refer it to allah and to the messenger', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 14, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 15, NULL, 'An-Nisa: 83وَلَوْ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُو۟لِى ٱلْأَمْرِ مِنْهُمْ لَعَلِمَهُ ٱلَّذِينَ يَسْتَنۢبِطُونَهُۥ مِنْهُمْ"Had they referred it to the Messenger and to those charged with authority among them, those among them who draw out conclusions would have known it."', '', NULL, 'An-Nisa: 83', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'an nisa 83ولو ردوه الي الرسول والي اولي الامر منهم لعلمه الذين يستنبطونه منهم had they referred it to the messenger and to those charged with authority among them those among them who draw out conclusions would have known it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 16, NULL, 'Whoever sets aside arrogance, insolence, and envy, and submits to the people of truth, comes to stand upon realities and leaves the company of the people of ignorance. Whoever opposes the people of truth, however, and persists in his current state — wandering in blindness and misguidance — is brought to ruin and to an evil saying; the word of punishment comes true against him, and he earns the sign of chastisement. We seek refuge in Allah from all of that — from division after concord, from tyranny after faith, and from disobedience toward His guardians, may (عَلَيْهِمُ السَّلَامُ), after submission and certainty. We ask Him to place us among those who attain salvation through His mercy and who stand firm in obeying Him and obeying His guardians, for He is the best of those who are asked.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'whoever sets aside arrogance insolence and envy and submits to the people of truth comes to stand upon realities and leaves the company of the people of ignorance whoever opposes the people of truth however and persists in his current state wandering in blindness and misguidance is brought to ruin and to an evil saying the word of punishment comes true against him and he earns the sign of chastisement we seek refuge in allah from all of that from division after concord from tyranny after faith and from disobedience toward his guardians may عليهم السلام after submission and certainty we ask him to place us among those who attain salvation through his mercy and who stand firm in obeying him and obeying his guardians for he is the best of those who are asked', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 17, NULL, 'He then made fasting obligatory upon His servants in the explicit text of His Book, saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'he then made fasting obligatory upon his servants in the explicit text of his book saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 18, NULL, 'Al-Baqarah: 183كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ"Fasting has been prescribed for you as it was prescribed for those before you, so that you may guard yourselves."', '', NULL, 'Al-Baqarah: 183', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'al baqarah 183كتب عليكم الصيام كما كتب علي الذين من قبلكم لعلكم تتقون fasting has been prescribed for you as it was prescribed for those before you so that you may guard yourselves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 19, NULL, 'The Prophet (ع) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'the prophet ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 20, NULL, 'Sayingشَعْبَانُ شَهْرِي وَرَمَضَانُ شَهْرُ اللَّهِ وَصَوْمُهُ فَرِيضَةٌ"Shaban is my month, and Ramadan is the month of Allah, and fasting it is an obligation."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'sayingشعبان شهري ورمضان شهر الله وصومه فريضه shaban is my month and ramadan is the month of allah and fasting it is an obligation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 21, NULL, 'The Imams (عَلَيْهِمُ السَّلَامُ) said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'the imams عليهم السلام said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 22, NULL, 'Sayingصَوْمُ شَهْرِ رَمَضَانَ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ"The fast of the month of Ramadan is an obligation upon every Muslim."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'sayingصوم شهر رمضان فريضه علي كل مسلم the fast of the month of ramadan is an obligation upon every muslim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 23, NULL, 'When Allah Almighty imposed the fast of Ramadan upon His servants, the Prophet (ع) did not leave them blind to the knowledge of its time and season — just as he did not leave them in ignorance of the other obligations, such as the numbers of the prayers and their times when those were prescribed, and the amounts of alms due on various kinds of property when those were made obligatory. So he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'when allah almighty imposed the fast of ramadan upon his servants the prophet ع did not leave them blind to the knowledge of its time and season just as he did not leave them in ignorance of the other obligations such as the numbers of the prayers and their times when those were prescribed and the amounts of alms due on various kinds of property when those were made obligatory so he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 24, NULL, 'Sayingصُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ"Fast at its sighting and break the fast at its sighting."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'sayingصوموا لرويته وافطروا لرويته fast at its sighting and break the fast at its sighting', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 25, NULL, 'Scarcely any disagreement arises over this narration among the sects of the Muslims. It is the pillar upon which the people of the outward rest their argument.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'scarcely any disagreement arises over this narration among the sects of the muslims it is the pillar upon which the people of the outward rest their argument', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 26, NULL, 'I say, then, that Allah Almighty created all things in pairs, so that the One alone in oneness should be He, and nothing should share with Him in it. Allah said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'i say then that allah almighty created all things in pairs so that the one alone in oneness should be he and nothing should share with him in it allah said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 27, NULL, 'Ya-Sin: 36سُبْحَنَ ٱلَّذِى خَلَقَ ٱلْأَزْوَجَ كُلَّهَا"Glory be to the One who created all the pairs."', '', NULL, 'Ya-Sin: 36', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'ya sin 36سبحن الذي خلق الازوج كلها glory be to the one who created all the pairs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 28, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 29, NULL, 'Adh-Dhariyat: 49وَمِن كُلِّ شَىْءٍ خَلَقْنَا زَوْجَيْنِ لَعَلَّكُمْ تَذَكَّرُونَ"Of every thing We created two kinds, so that you might remember."', '', NULL, 'Adh-Dhariyat: 49', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'adh dhariyat 49ومن كل شيء خلقنا زوجين لعلكم تذكرون of every thing we created two kinds so that you might remember', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 30, NULL, 'Since this is so — and since we see all things in pairs and counterparts, such as substance and accident, sky and earth, land and sea, plain and mountain, night and day, good and evil, body and spirit, outward and inward, this world and the next, male and female, and others too many to enumerate — and since we see that the Prophet (ع) made pairing the foundation and governing principle of his law, joining commands and obligations to their counterparts as an indication of what I have said concerning the pure affirmation of the oneness of Allah Almighty, as with:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'since this is so and since we see all things in pairs and counterparts such as substance and accident sky and earth land and sea plain and mountain night and day good and evil body and spirit outward and inward this world and the next male and female and others too many to enumerate and since we see that the prophet ع made pairing the foundation and governing principle of his law joining commands and obligations to their counterparts as an indication of what i have said concerning the pure affirmation of the oneness of allah almighty as with', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 31, NULL, 'the prayer joined to the alms the call to prayer joined to the iqama Hajj joined to Umrah al-Safa joined to al-Marwa the obligatory act joined to the practice of the Sunnah the bowing joined to the prostration the testimony that there is no god but Allah joined to the testimony that Muhammad is the Messenger of Allah', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'the prayer joined to the alms the call to prayer joined to the iqama hajj joined to umrah al safa joined to al marwa the obligatory act joined to the practice of the sunnah the bowing joined to the prostration the testimony that there is no god but allah joined to the testimony that muhammad is the messenger of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 32, NULL, 'and the like, which would take too long to enumerate — I say that sight too is of two kinds, each joined to the other: natural vision and vision of the soul.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'and the like which would take too long to enumerate i say that sight too is of two kinds each joined to the other natural vision and vision of the soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 33, NULL, 'Natural vision is that which occurs by means of the eye. It apprehends colors, such as white, black, red, yellow, and others, and shapes, such as the round, the triangular, the square, the five-sided, and so on. There is no need to argue for it, since it falls under the senses. Vision of the soul is that which occurs by way of knowledge, through the heart and the soul, and it apprehends what natural vision does not apprehend — those causes that are hidden from its perception. Allah said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'natural vision is that which occurs by means of the eye it apprehends colors such as white black red yellow and others and shapes such as the round the triangular the square the five sided and so on there is no need to argue for it since it falls under the senses vision of the soul is that which occurs by way of knowledge through the heart and the soul and it apprehends what natural vision does not apprehend those causes that are hidden from its perception allah said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 34, NULL, 'An-Najm: 11مَا كَذَبَ ٱلْفُؤَادُ مَا رَأَىٰٓ"The heart did not lie about what it saw."', '', NULL, 'An-Najm: 11', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'an najm 11ما كذب الفواد ما راي the heart did not lie about what it saw', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 35, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 36, NULL, 'Sayingألم ترى ربك كيف مد الظل"Have you not seen how your Lord extended the shadow?"', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'sayingالم تري ربك كيف مد الظل have you not seen how your lord extended the shadow', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 37, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 38, NULL, 'Sayingألم ترى كيف فعل ربك بأصحاب الفيل"Have you not seen what your Lord did with the companions of the elephant?"', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'sayingالم تري كيف فعل ربك باصحاب الفيل have you not seen what your lord did with the companions of the elephant', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 39, NULL, 'We know that the Prophet (ع) was not alive in the time of the companions of the elephant and could not have witnessed them with natural sight; what is meant here is the vision of the soul — sight that comes by way of the heart and of knowledge. The same sense underlies the common proverb that a certain person is blind of heart, meaning he is dull and backward in knowing things and in perceiving them when they lie beyond his eyes.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'we know that the prophet ع was not alive in the time of the companions of the elephant and could not have witnessed them with natural sight what is meant here is the vision of the soul sight that comes by way of the heart and of knowledge the same sense underlies the common proverb that a certain person is blind of heart meaning he is dull and backward in knowing things and in perceiving them when they lie beyond his eyes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 40, NULL, 'Since what I have set out is sound — that sight is of two kinds — and since all things are divided into two states and two aspects so that the oneness of Allah may stand pure and nothing may share with Him in that oneness, I say:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'since what i have set out is sound that sight is of two kinds and since all things are divided into two states and two aspects so that the oneness of allah may stand pure and nothing may share with him in that oneness i say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 41, NULL, 'Natural vision, which comes by way of the eye, apprehends of things only what is corporeal and falls under limits and time, such as colors and shapes. Vision of the soul, which comes by way of the heart and of knowledge, apprehends what natural vision does not apprehend and what it is too weak to grasp of all that is hidden from the eyes.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'natural vision which comes by way of the eye apprehends of things only what is corporeal and falls under limits and time such as colors and shapes vision of the soul which comes by way of the heart and of knowledge apprehends what natural vision does not apprehend and what it is too weak to grasp of all that is hidden from the eyes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 42, NULL, 'From this follows the judgment that vision of the soul is more exalted than natural vision, finer and more subtle in its apprehension. Its act is to know things as they truly are — unlike the eye. If a man were to take a single drop from a pool of water, vision of the soul would judge that the quantity of that water had decreased by the measure of the drop, and would see this with a sound seeing, while that decrease would not register for the sense that comes by way of the eye and of sight.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'from this follows the judgment that vision of the soul is more exalted than natural vision finer and more subtle in its apprehension its act is to know things as they truly are unlike the eye if a man were to take a single drop from a pool of water vision of the soul would judge that the quantity of that water had decreased by the measure of the drop and would see this with a sound seeing while that decrease would not register for the sense that comes by way of the eye and of sight', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 43, NULL, 'Since vision of the soul is the prior and the more subtle in apprehension, holding fast to it in fulfilling the obligations of Allah Almighty is more binding and more fitting than holding fast to anything else. To confine oneself to what is not the more excellent when the more excellent is present belongs to the judgments of ignorance, not to the judgment of reason. What truly binds people is to take hold of the more precise and the more excellent — by which I mean the vision of knowledge and of the soul.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'since vision of the soul is the prior and the more subtle in apprehension holding fast to it in fulfilling the obligations of allah almighty is more binding and more fitting than holding fast to anything else to confine oneself to what is not the more excellent when the more excellent is present belongs to the judgments of ignorance not to the judgment of reason what truly binds people is to take hold of the more precise and the more excellent by which i mean the vision of knowledge and of the soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 44, NULL, 'Furthermore, if a man were to know in his heart that the time of a prayer had come, yet had not heard the sound of the call to prayer, that prayer would still be binding upon him. Likewise, if one taking the meal before dawn were to see with his heart and know that the dawn had broken, while his eyesight was barred from seeing it by some barrier that stood in the way, abstaining from food would be binding upon him even though his eye had not seen it. Since this is so, the fast and the abstaining from food are binding upon the one taking that meal because of his knowledge that the dawn has broken, even though his eyesight is barred from seeing it by whatever bars it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'furthermore if a man were to know in his heart that the time of a prayer had come yet had not heard the sound of the call to prayer that prayer would still be binding upon him likewise if one taking the meal before dawn were to see with his heart and know that the dawn had broken while his eyesight was barred from seeing it by some barrier that stood in the way abstaining from food would be binding upon him even though his eye had not seen it since this is so the fast and the abstaining from food are binding upon the one taking that meal because of his knowledge that the dawn has broken even though his eyesight is barred from seeing it by whatever bars it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 45, NULL, 'By the same token, I say that entry into the fast is binding once knowledge is obtained that the cause of the fast — the moon''s separation from the greatest luminary after their conjunction — has come to pass, even if sight is barred from seeing it by any condition whatever, whether light, cloud, dust, or a mountain. It is agreed that when the cause is realized, its effect becomes necessary by its necessity, so that neither precedes the other except in rank. The people of the call, therefore, in their entry into the fast, act by the judgment of the vision of the soul, in which error scarcely occurs, upon clear evidence and knowledge.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'by the same token i say that entry into the fast is binding once knowledge is obtained that the cause of the fast the moons separation from the greatest luminary after their conjunction has come to pass even if sight is barred from seeing it by any condition whatever whether light cloud dust or a mountain it is agreed that when the cause is realized its effect becomes necessary by its necessity so that neither precedes the other except in rank the people of the call therefore in their entry into the fast act by the judgment of the vision of the soul in which error scarcely occurs upon clear evidence and knowledge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 46, NULL, 'Then, since the Messenger (ع) made the fast obligatory in certain months of the year and informed us that Allah Almighty has made the sun and the moon a means to the knowledge of years and months, their times and their crescents, Allah said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'then since the messenger ع made the fast obligatory in certain months of the year and informed us that allah almighty has made the sun and the moon a means to the knowledge of years and months their times and their crescents allah said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 47, NULL, 'Yunus: 5هُوَ ٱلَّذِى جَعَلَ ٱلشَّمْسَ ضِيَآءًۭ وَٱلْقَمَرَ نُورًۭا وَقَدَّرَهُۥ مَنَازِلَ لِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ"He is the One who made the sun a radiance and the moon a light, and determined phases for it so that you might know the number of the years and the reckoning."', '', NULL, 'Yunus: 5', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'yunus 5هو الذي جعل الشمس ضياء والقمر نورا وقدره منازل لتعلموا عدد السنين والحساب he is the one who made the sun a radiance and the moon a light and determined phases for it so that you might know the number of the years and the reckoning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 48, NULL, 'He also said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'he also said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 49, NULL, 'Al-Baqarah: 189ويسألونك عن الأهلة قل هي مواقيت للناس"They ask you about the crescents. Say: they are appointed times for the people."', '', NULL, 'Al-Baqarah: 189', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'al baqarah 189ويسالونك عن الاهله قل هي مواقيت للناس they ask you about the crescents say they are appointed times for the people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 50, NULL, 'The year is twelve months, as Allah said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'the year is twelve months as allah said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 51, NULL, 'At-Tawbah: 36إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًۭا فِى كِتَبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَوَتِ وَٱلْأَرْضَ"The number of the months with Allah is twelve months in the Book of Allah, from the day He created the heavens and the earth."', '', NULL, 'At-Tawbah: 36', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'at tawbah 36ان عده الشهور عند الله اثنا عشر شهرا في كتب الله يوم خلق السموت والارض the number of the months with allah is twelve months in the book of allah from the day he created the heavens and the earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 52, NULL, 'The year is complete only when that full count has passed. A month comes into being — and its days are completed — only through the moon''s travel: from the point where the moon and sun share the same degree and minute of arc, which the people of the stars call the conjunction, all the way around the sphere and back to that same alignment. From this we understand that when the moon''s degree and minute within a zodiacal sign match the degree and minute of the sun within it, the moon has completed its course for the past month; and when it parts from the sun, its course belongs to the coming month. As the moon travels toward conjunction and separation, it passes through states in which the light on the half of its body facing the center — which is the earth — decreases, until at the moment of conjunction the upper half of its body, on the side facing the encompassing sphere, is illuminated, just as the whole of the half facing the center is illuminated on the night of its opposition. Then light appears in half its body at the separation and increases in proportion to its distance, through causes that the eye is too weak to fully apprehend.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'the year is complete only when that full count has passed a month comes into being and its days are completed only through the moons travel from the point where the moon and sun share the same degree and minute of arc which the people of the stars call the conjunction all the way around the sphere and back to that same alignment from this we understand that when the moons degree and minute within a zodiacal sign match the degree and minute of the sun within it the moon has completed its course for the past month and when it parts from the sun its course belongs to the coming month as the moon travels toward conjunction and separation it passes through states in which the light on the half of its body facing the center which is the earth decreases until at the moment of conjunction the upper half of its body on the side facing the encompassing sphere is illuminated just as the whole of the half facing the center is illuminated on the night of its opposition then light appears in half its body at the separation and increases in proportion to its distance through causes that the eye is too weak to fully apprehend', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 53, NULL, 'I say that the eye''s inability to apprehend all these states, and to see the illuminated portion of the moon''s body as it travels toward conjunction at the month''s end and at its separation at the month''s beginning, arises from nothing other than the condition of the sun''s light, which bars the eye from apprehension. In barring the eye from seeing the moon at that time, the sun''s light acts just like the other causes that intervene and prevent the eye from seeing it: cloud, dust, a wall, or a mountain.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'i say that the eyes inability to apprehend all these states and to see the illuminated portion of the moons body as it travels toward conjunction at the months end and at its separation at the months beginning arises from nothing other than the condition of the suns light which bars the eye from apprehension in barring the eye from seeing the moon at that time the suns light acts just like the other causes that intervene and prevent the eye from seeing it cloud dust a wall or a mountain', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 54, NULL, 'Do you not see that the stars are invisible by day because of the sun''s radiance and overpowering brightness, and that when the sun is eclipsed the eye perceives them again, because the eclipse reduces the light? Since it is established that the illuminated measure of the moon''s body at its separation from the sun would be seen by the eye were it not for the sun''s light and rays, then that light is the barrier and the preventer — just like cloud and the turbidity of the air. And since the sun''s light bars the eye from seeing the crescent after its separation from it, the soul, through knowledge, is not barred from seeing it as it truly is. The fast therefore becomes binding by the vision of knowledge, which is the more exalted, as the proofs I have established make clear. By these testimonies, the people of the guiding call are upon truth and right when they enter the fast by the soul''s vision. And if they are upon the right, then whoever opposes them is in error.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'do you not see that the stars are invisible by day because of the suns radiance and overpowering brightness and that when the sun is eclipsed the eye perceives them again because the eclipse reduces the light since it is established that the illuminated measure of the moons body at its separation from the sun would be seen by the eye were it not for the suns light and rays then that light is the barrier and the preventer just like cloud and the turbidity of the air and since the suns light bars the eye from seeing the crescent after its separation from it the soul through knowledge is not barred from seeing it as it truly is the fast therefore becomes binding by the vision of knowledge which is the more exalted as the proofs i have established make clear by these testimonies the people of the guiding call are upon truth and right when they enter the fast by the souls vision and if they are upon the right then whoever opposes them is in error', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 55, NULL, 'Then I say to the hostile party and the rest of the opponents: from where have you made it obligatory that seeing means the seeing of the eye alone, excluding the seeing of the heart and of knowledge, when the proofs stand that seeing is of two kinds — a point none can deny except one who is openly obstinate? If you say that a man knows nothing until his sight falls upon it, and that when he has beheld it the judgment of the vision of knowledge concerning it is established for him, I say that this argument of yours is corrupt and does not hold, from several sides:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'then i say to the hostile party and the rest of the opponents from where have you made it obligatory that seeing means the seeing of the eye alone excluding the seeing of the heart and of knowledge when the proofs stand that seeing is of two kinds a point none can deny except one who is openly obstinate if you say that a man knows nothing until his sight falls upon it and that when he has beheld it the judgment of the vision of knowledge concerning it is established for him i say that this argument of yours is corrupt and does not hold from several sides', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 56, NULL, 'The first: if I ask you, have you seen Allah Almighty, then upon this principle of yours you are bound to say no. So I say: then why have you affirmed Him, when you have laid it down that a man knows nothing until his sight falls upon it, and your sight has not fallen upon Him, exalted and magnified as He is? You are therefore bound to retreat from the doctrine of the eye to the matter of knowledge, and to say: we knew, and it was established for us by proofs, and so we affirmed it. And that is precisely my position and my foundation. The second: the matter of the world and its origination in time. If I were to question you about it, you would be bound to rule upon its origination by the judgment of the vision of knowledge and proof, not by the judgment of the vision of the eye. And that is my position. The third: I say, what do you say concerning a man who broke his fast without having seen the crescent with his eye, because a barrier intervened, when thirty days of the month of Ramadan had passed? Was his breaking of the fast valid or not? If you say it was valid, I say: how so, when he did not behold the crescent with the eye, and the foundation of your school is that fasting and breaking the fast are not permitted except after seeing the crescent with the eye? You are then bound to say: we knew that after thirty days the crescent is seen, and that a barrier merely stood in the way of seeing it. And I say to you: you have abandoned the judgment of the vision of the eye and returned of necessity to the matter of the vision of knowledge — and that is my position. And if you say it was not valid, then what binds you binds you still.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'the first if i ask you have you seen allah almighty then upon this principle of yours you are bound to say no so i say then why have you affirmed him when you have laid it down that a man knows nothing until his sight falls upon it and your sight has not fallen upon him exalted and magnified as he is you are therefore bound to retreat from the doctrine of the eye to the matter of knowledge and to say we knew and it was established for us by proofs and so we affirmed it and that is precisely my position and my foundation the second the matter of the world and its origination in time if i were to question you about it you would be bound to rule upon its origination by the judgment of the vision of knowledge and proof not by the judgment of the vision of the eye and that is my position the third i say what do you say concerning a man who broke his fast without having seen the crescent with his eye because a barrier intervened when thirty days of the month of ramadan had passed was his breaking of the fast valid or not if you say it was valid i say how so when he did not behold the crescent with the eye and the foundation of your school is that fasting and breaking the fast are not permitted except after seeing the crescent with the eye you are then bound to say we knew that after thirty days the crescent is seen and that a barrier merely stood in the way of seeing it and i say to you you have abandoned the judgment of the vision of the eye and returned of necessity to the matter of the vision of knowledge and that is my position and if you say it was not valid then what binds you binds you still', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 57, NULL, 'Beyond this, whatever is known of things only by way of the senses, which include sight and the rest, is no more than the substance of corporeal things in their form and their quality alone. Once the soul has drawn upon the senses in coming to know a thing for the first time, it has no need to draw upon them a second time. The outcome of the senses and their yield is that they become dispensable, since the soul stands by its own essence in their place. For the soul in man is one of the instruments by which he apprehends.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'beyond this whatever is known of things only by way of the senses which include sight and the rest is no more than the substance of corporeal things in their form and their quality alone once the soul has drawn upon the senses in coming to know a thing for the first time it has no need to draw upon them a second time the outcome of the senses and their yield is that they become dispensable since the soul stands by its own essence in their place for the soul in man is one of the instruments by which he apprehends', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 58, NULL, 'Within man the soul stands alongside hearing, sight, smell, taste, and touch as an instrument of perception, and it possesses a capacity that none of the others possesses: after the images of their objects have come to it, it rises above them all and perceives what hearing, sight, smell, taste, and touch do not perceive. Just as hearing perceives what sight, smell, taste, and touch do not perceive, and smell perceives what hearing, sight, taste, and touch do not perceive, so the soul perceives what lies beyond all of them. In the senses there is a wisdom from Allah Almighty: that man be not deprived of anything he cannot otherwise apprehend of what Allah has brought into being in the worlds, and that what one instrument apprehends not be lost to him because another cannot reach it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'within man the soul stands alongside hearing sight smell taste and touch as an instrument of perception and it possesses a capacity that none of the others possesses after the images of their objects have come to it it rises above them all and perceives what hearing sight smell taste and touch do not perceive just as hearing perceives what sight smell taste and touch do not perceive and smell perceives what hearing sight taste and touch do not perceive so the soul perceives what lies beyond all of them in the senses there is a wisdom from allah almighty that man be not deprived of anything he cannot otherwise apprehend of what allah has brought into being in the worlds and that what one instrument apprehends not be lost to him because another cannot reach it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 59, NULL, 'The soul''s perception is therefore of two kinds:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'the souls perception is therefore of two kinds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 60, NULL, 'The first is perception by means of the five senses — such as its perception of colors and shapes by way of sight, of sounds that signify and sounds that do not signify by way of hearing, and whatever else belongs to the remaining senses; and it is from this that the soul draws its inference toward what the senses do not perceive. The second is perception by the soul''s own essence along the path of inference, which stands in place of all that it apprehends by way of the senses — as its perception that the world is originated, after it had first apprehended the world by way of the senses. To what the soul perceives by its own essence along the path of inference, the senses have no road at all.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'the first is perception by means of the five senses such as its perception of colors and shapes by way of sight of sounds that signify and sounds that do not signify by way of hearing and whatever else belongs to the remaining senses and it is from this that the soul draws its inference toward what the senses do not perceive the second is perception by the souls own essence along the path of inference which stands in place of all that it apprehends by way of the senses as its perception that the world is originated after it had first apprehended the world by way of the senses to what the soul perceives by its own essence along the path of inference the senses have no road at all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 61, NULL, 'What the soul perceives by way of the senses it needs them for only in the first instance; it does not need a second perception from their side when it has occasion to know that thing again, for it has received the image of the sensed thing upon its own form at the first apprehension, and that image is present to it within itself whenever it returns to it, without any need to call upon the senses once more. So it is with the image of the planets in themselves and in their quality: once the soul has apprehended them by way of sight, that seeing makes a second seeing unnecessary, since the image is held in the soul and preserved by its having received it. Thereafter the soul stands in the place of the senses by its own essence, as the soul of one whose eyes have gathered the forms of visible things has no need of a second apprehension by the eyes, the image remaining in what belongs properly to the soul, standing upon its form without alteration.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'what the soul perceives by way of the senses it needs them for only in the first instance it does not need a second perception from their side when it has occasion to know that thing again for it has received the image of the sensed thing upon its own form at the first apprehension and that image is present to it within itself whenever it returns to it without any need to call upon the senses once more so it is with the image of the planets in themselves and in their quality once the soul has apprehended them by way of sight that seeing makes a second seeing unnecessary since the image is held in the soul and preserved by its having received it thereafter the soul stands in the place of the senses by its own essence as the soul of one whose eyes have gathered the forms of visible things has no need of a second apprehension by the eyes the image remaining in what belongs properly to the soul standing upon its form without alteration', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 62, NULL, 'What is meant in seeking the crescent and sighting it with the eye every month and every year is not that one should learn its figure in its form, its thinness and its thickness, for the knowledge of that would indeed require sight, which is the instrument for apprehending such things. What is meant in seeking it is to know the fact of its being in the west before the sun after it had been in the east behind her. And the apprehension of this fact of its being in the west belongs to the soul, not to sight, for sight, even when every obstruction is lifted, apprehends nothing but shapes and colors.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'what is meant in seeking the crescent and sighting it with the eye every month and every year is not that one should learn its figure in its form its thinness and its thickness for the knowledge of that would indeed require sight which is the instrument for apprehending such things what is meant in seeking it is to know the fact of its being in the west before the sun after it had been in the east behind her and the apprehension of this fact of its being in the west belongs to the soul not to sight for sight even when every obstruction is lifted apprehends nothing but shapes and colors', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 63, NULL, 'Since sight apprehends nothing but shapes and colors, and the seeking of the crescent is not for knowledge of its color and its shape, the matter is settled. For if it were sought in order to know its color and its shape, it would be absurd to seek it at all, since knowledge of the quality of its form, its figure, and its color is already possessed from earlier seeing by the eye, together with the certainty that it will not fail so long as the heavens and the earth endure, and that its image as apprehended by sight will not change from roundness of shape and the lighting of the edge of its body into squareness of shape and the lighting of the whole of its body. Nor is it sought because the obligation of fasting depends upon a condition of thinness or thickness in the luminous body. For if it were sought in order to know its thinness and its thickness, it would be absurd that the one who sees it should fast when it is thin while the condition is thickness, or fast when it is thick while the condition is thinness. No such condition of shape, color, thinness, or thickness exists in the obligation of fasting. It is therefore void that the obligation of fasting should be attached to apprehending the crescent by sight; and once that is void, it is established that it is attached to the soul''s apprehension of it as being before the sun. For the proof has been given that man knows by way of inference, from what he has apprehended of bodily substances through his senses, what he does not apprehend through them. So the knowledge does not come about by sight, and fasting is attached to the vision of the soul and to nothing else; and the people of the dawah, in taking what the vision of the soul requires when they enter the fast, are upon a sound way and a straight path.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'since sight apprehends nothing but shapes and colors and the seeking of the crescent is not for knowledge of its color and its shape the matter is settled for if it were sought in order to know its color and its shape it would be absurd to seek it at all since knowledge of the quality of its form its figure and its color is already possessed from earlier seeing by the eye together with the certainty that it will not fail so long as the heavens and the earth endure and that its image as apprehended by sight will not change from roundness of shape and the lighting of the edge of its body into squareness of shape and the lighting of the whole of its body nor is it sought because the obligation of fasting depends upon a condition of thinness or thickness in the luminous body for if it were sought in order to know its thinness and its thickness it would be absurd that the one who sees it should fast when it is thin while the condition is thickness or fast when it is thick while the condition is thinness no such condition of shape color thinness or thickness exists in the obligation of fasting it is therefore void that the obligation of fasting should be attached to apprehending the crescent by sight and once that is void it is established that it is attached to the souls apprehension of it as being before the sun for the proof has been given that man knows by way of inference from what he has apprehended of bodily substances through his senses what he does not apprehend through them so the knowledge does not come about by sight and fasting is attached to the vision of the soul and to nothing else and the people of the dawah in taking what the vision of the soul requires when they enter the fast are upon a sound way and a straight path', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 64, NULL, 'Further, the seeing of the eye sometimes falls into error concerning things as they truly are, by reason of what befalls it, so that it sees the large as small and the small as large, the thin as thick and the thick as thin; and sometimes a thing is seen only from near, or only from far. But the seeing of knowledge scarcely errs in what it encompasses. To take, in the discharge of the obligatory duties, that which does not err is worthier in the judgment of those endowed with understanding than to take that which errs. The people of the true call, then, in entering the fast, have taken hold of that which does not err, upon clarity and upon truth.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'further the seeing of the eye sometimes falls into error concerning things as they truly are by reason of what befalls it so that it sees the large as small and the small as large the thin as thick and the thick as thin and sometimes a thing is seen only from near or only from far but the seeing of knowledge scarcely errs in what it encompasses to take in the discharge of the obligatory duties that which does not err is worthier in the judgment of those endowed with understanding than to take that which errs the people of the true call then in entering the fast have taken hold of that which does not err upon clarity and upon truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 65, NULL, 'As for the saying of the Prophet,', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'as for the saying of the prophet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 66, NULL, 'Saying"صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ""Fast for its sighting and break the fast for its sighting,"', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'saying صوموا لرويته وافطروا لرويته fast for its sighting and break the fast for its sighting', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 67, NULL, 'outwardly it does not escape two faces. Either he intended by it that the fasting of the community should begin from the moment the crescent is seen with the eye, as the opponents say, or that the crescent is seen with the eye while the community is already fasting, as we say. If he intended that the fasting of the community begin from the moment of the crescent''s being seen by the eye, then what is the meaning of his saying لرؤيته, and what is the reason for his restricting himself, out of all the modes of expression, to the letter اللام (al-lam) rather than to another of the letters used in expression, he who took pride in his speech and said,', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'outwardly it does not escape two faces either he intended by it that the fasting of the community should begin from the moment the crescent is seen with the eye as the opponents say or that the crescent is seen with the eye while the community is already fasting as we say if he intended that the fasting of the community begin from the moment of the crescents being seen by the eye then what is the meaning of his saying لرويته and what is the reason for his restricting himself out of all the modes of expression to the letter اللام al lam rather than to another of the letters used in expression he who took pride in his speech and said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 68, NULL, 'Saying"أَنَا أَفْصَحُ الْعَرَبِ وَلَا فَخْرَ""I am the most eloquent of the Arabs, and this is no boast"?', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'saying انا افصح العرب ولا فخر i am the most eloquent of the arabs and this is no boast', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 69, NULL, 'Was his use of this lam here — saying لرؤيته rather than omitting it — for any purpose other than that the community should already be fasting when the crescent is seen by the eye? For the sense of lam, as it is used and as it is intended, is that the act must precede that for which it is done. Consider the following:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'was his use of this lam here saying لرويته rather than omitting it for any purpose other than that the community should already be fasting when the crescent is seen by the eye for the sense of lam as it is used and as it is intended is that the act must precede that for which it is done consider the following', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 70, NULL, 'When one says to a company, "Set such a thing in order for the coming of so-and-so," the meaning is that the thing is to be already in order at the time of his arrival. When one says, "Compose for the meeting of so-and-so a poem that you may recite to him," the meaning is that they meet him with the poem already composed and spoken — not that they begin composing it from the moment they meet him. When one says, "Work for the Hereafter," the meaning is that they are to put the work forward before the time of the Hereafter, for it is known that in the Hereafter there is no work.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'when one says to a company set such a thing in order for the coming of so and so the meaning is that the thing is to be already in order at the time of his arrival when one says compose for the meeting of so and so a poem that you may recite to him the meaning is that they meet him with the poem already composed and spoken not that they begin composing it from the moment they meet him when one says work for the hereafter the meaning is that they are to put the work forward before the time of the hereafter for it is known that in the hereafter there is no work', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 71, NULL, 'By these witnesses it is sound that the letter lam was used for nothing other than that the people should already be fasting when the crescent is seen with the eye. And if the intention of the Prophet was that the crescent be seen while the community is fasting, that is what we have said and for which we have established the proof.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'by these witnesses it is sound that the letter lam was used for nothing other than that the people should already be fasting when the crescent is seen with the eye and if the intention of the prophet was that the crescent be seen while the community is fasting that is what we have said and for which we have established the proof', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 72, NULL, 'If an opponent objects and says, "What do you say against the lam in the saying of the Prophet لرؤيته being like the lam in the saying of Allah Almighty,', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'if an opponent objects and says what do you say against the lam in the saying of the prophet لرويته being like the lam in the saying of allah almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'verse', 'two kinds of sight', '32. Two Kinds of Sight', 73, NULL, 'Al-Isra: 78أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمْسِ', '', 'أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمْسِ', 'Al-Isra: 78', 17, 78, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'al isra 78اقم الصلوه لدلوك الشمس', 'اقم الصلوه لدلوك الشمس');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 74, NULL, 'Establish the prayer at the declining of the sun,', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'establish the prayer at the declining of the sun', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 75, NULL, 'so that the fast need not precede the sighting, just as the prayer need not precede the declining of the sun?" we say: the account of the lam in the saying of Allah Almighty is the same as the account of the lam in the saying of the Prophet. For the declining of the sun is its departure from the dome of the sky, as it has been explained, and the apprehension of that departure is of two kinds: an apprehension belonging to the soul and an apprehension belonging to nature. The apprehension belonging to the soul precedes the apprehension belonging to nature, because the sun''s departure in reality from the dome of the sky is perceived only by the vision of the soul, by way of knowledge. Natural vision is too narrow to apprehend it until the sun has parted from the point of the zenith in descent and has come clear of that region in its descending, at the intersection of the line of the circle with the straight line, as we have set forth in the figure: the earth at the center, the east and the west, the meridian line, the circle of elevation, the straight line that cuts across, and the tangent of the circle upon the straight line — with the place of the vision of the soul of the declining marked at the point ب and the place of the sensible vision of the declining marked at the point ج.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'so that the fast need not precede the sighting just as the prayer need not precede the declining of the sun we say the account of the lam in the saying of allah almighty is the same as the account of the lam in the saying of the prophet for the declining of the sun is its departure from the dome of the sky as it has been explained and the apprehension of that departure is of two kinds an apprehension belonging to the soul and an apprehension belonging to nature the apprehension belonging to the soul precedes the apprehension belonging to nature because the suns departure in reality from the dome of the sky is perceived only by the vision of the soul by way of knowledge natural vision is too narrow to apprehend it until the sun has parted from the point of the zenith in descent and has come clear of that region in its descending at the intersection of the line of the circle with the straight line as we have set forth in the figure the earth at the center the east and the west the meridian line the circle of elevation the straight line that cuts across and the tangent of the circle upon the straight line with the place of the vision of the soul of the declining marked at the point ب and the place of the sensible vision of the declining marked at the point ج', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 76, NULL, 'Only then does sense apprehend it. The movement of the sun and of its shadow falls under sense by its rising in the circle when it comes up from the east and by its descending in the circle toward its setting; where there is rising and descending, sense apprehends the shortening and lengthening of the shadow. But when the sun has come to where it has no elevation — while it is at the point of declining and descending — sense grows weary of apprehending its course and its movement, because it has reached the zenith in such a way that its motion is concealed from sense and hidden from it, and one who has no knowledge supposes that it has halted. It is hidden from sense only because the sun has come to stand over the place from which it is at its farthest remove in height, and its motion in its passage through the zenith has become, from the line of the circle, a motion upon a level line, where the plane touches the straight line of the circle. That is from the place of the line أ — the point where the line of the circle and the level line intersect — from the eastern side to the line on the western side. Sense does not discern the shortening and lengthening of the shadow, since that comes about only by elevation in height and by descent, and there the sun has neither elevation nor descent but moves upon a level line.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'only then does sense apprehend it the movement of the sun and of its shadow falls under sense by its rising in the circle when it comes up from the east and by its descending in the circle toward its setting where there is rising and descending sense apprehends the shortening and lengthening of the shadow but when the sun has come to where it has no elevation while it is at the point of declining and descending sense grows weary of apprehending its course and its movement because it has reached the zenith in such a way that its motion is concealed from sense and hidden from it and one who has no knowledge supposes that it has halted it is hidden from sense only because the sun has come to stand over the place from which it is at its farthest remove in height and its motion in its passage through the zenith has become from the line of the circle a motion upon a level line where the plane touches the straight line of the circle that is from the place of the line ا the point where the line of the circle and the level line intersect from the eastern side to the line on the western side sense does not discern the shortening and lengthening of the shadow since that comes about only by elevation in height and by descent and there the sun has neither elevation nor descent but moves upon a level line', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 77, NULL, 'This being so, the true declining by which the prayer becomes obligatory is at the arrival of the sun''s disk from the line of the circle at the line ب, which is seen by the vision of the soul and is the sign of the line of the half of what is cut off by the day — not at its arrival at the line ج, which is seen by natural vision and is more than the half. For at the time it reaches the line ب it has begun to descend, even if sense does not apprehend its shadow or its movement in its place, since it is upon a level line, and this is not made plain to sense until after it has reached the intersection of the line of the circle and the level line. The account of the lam in "at the declining of the sun," then, is the same as the account of the lam in "for its sighting." It follows that when the shadow turns, the one who prays is already within his prayer — just as when the crescent appears and sense apprehends it, the one who fasts is already within his fast — and this is the more careful course in the performance of the obligatory duties. By these witnesses the objection is void.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'this being so the true declining by which the prayer becomes obligatory is at the arrival of the suns disk from the line of the circle at the line ب which is seen by the vision of the soul and is the sign of the line of the half of what is cut off by the day not at its arrival at the line ج which is seen by natural vision and is more than the half for at the time it reaches the line ب it has begun to descend even if sense does not apprehend its shadow or its movement in its place since it is upon a level line and this is not made plain to sense until after it has reached the intersection of the line of the circle and the level line the account of the lam in at the declining of the sun then is the same as the account of the lam in for its sighting it follows that when the shadow turns the one who prays is already within his prayer just as when the crescent appears and sense apprehends it the one who fasts is already within his fast and this is the more careful course in the performance of the obligatory duties by these witnesses the objection is void', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 78, NULL, 'If he then says, "If the matter is as you have described, and fasting is binding by the vision of the soul according to what you have brought forward, what is the meaning of the saying of the Prophet,', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'if he then says if the matter is as you have described and fasting is binding by the vision of the soul according to what you have brought forward what is the meaning of the saying of the prophet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 79, NULL, 'Sayingفَإِنْ غُمَّ عَلَيْكُمْ فَعُدُّوا ثَلَاثِينَ يَوْماً', '', 'فَإِنْ غُمَّ عَلَيْكُمْ فَعُدُّوا ثَلَاثِينَ يَوْماً', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'sayingفان غم عليكم فعدوا ثلاثين يوما', 'فان غم عليكم فعدوا ثلاثين يوما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 80, NULL, 'If it is obscured from you, then count thirty days,', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'if it is obscured from you then count thirty days', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'two kinds of sight', '32. Two Kinds of Sight', 81, NULL, 'and what is that but a requiring of the seeing of the eye?" we say: we have established the vision of the soul by the witnesses we have brought forward, and that it is the nobler of the two.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 32 two kinds of sight', 'and what is that but a requiring of the seeing of the eye we say we have established the vision of the soul by the witnesses we have brought forward and that it is the nobler of the two', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 0, NULL, 'It is the nobler of the two, and the more fitting to be relied upon in the performance of obligatory duties. In saying this, we have not set aside the ruling of the sighting of the eye (رُؤْيَةُ الْعَيْنِ), for these two sightings are both foundations in the performance of obligatory duties — one simply more excellent than the other. The more excellent belongs to the select, those who go before others by their knowledge: they are the possessors of knowledge (أُولُوا الْعِلْم). The other belongs to the generality, whose ignorance obliges them to follow the people of knowledge — those who are bare of understanding. The relation between the two sightings is like the relation between the two times of a prayer, the first of which is more excellent than the second.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'it is the nobler of the two and the more fitting to be relied upon in the performance of obligatory duties in saying this we have not set aside the ruling of the sighting of the eye رويه العين for these two sightings are both foundations in the performance of obligatory duties one simply more excellent than the other the more excellent belongs to the select those who go before others by their knowledge they are the possessors of knowledge اولوا العلم the other belongs to the generality whose ignorance obliges them to follow the people of knowledge those who are bare of understanding the relation between the two sightings is like the relation between the two times of a prayer the first of which is more excellent than the second', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 1, NULL, 'So it is with all matters: they come in two kinds, hidden and apparent. The hidden is known only by the select among the excellent, while the apparent is known by both the select and the generality alike. The select are obliged to carry out what follows from what they have come to know, just as the common people are obliged to carry out what follows from what they have come to know. This being so, what is there to deny in the following: that a learned man, by the excellence of his knowledge, is bound to fast by the hidden vision of the soul (الرُّؤْيَةُ النَّفْسَانِيَّةُ), and that an ignorant man is bound to follow the learned man in that? It is precisely as with the one taking the pre-dawn meal who knows, by his hidden knowledge, that dawn has broken — for whom food, drink, and marital relations become forbidden, and fasting becomes binding — while the one taking the pre-dawn meal who is ignorant of the dawn must follow the learned man in that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'so it is with all matters they come in two kinds hidden and apparent the hidden is known only by the select among the excellent while the apparent is known by both the select and the generality alike the select are obliged to carry out what follows from what they have come to know just as the common people are obliged to carry out what follows from what they have come to know this being so what is there to deny in the following that a learned man by the excellence of his knowledge is bound to fast by the hidden vision of the soul الرويه النفسانيه and that an ignorant man is bound to follow the learned man in that it is precisely as with the one taking the pre dawn meal who knows by his hidden knowledge that dawn has broken for whom food drink and marital relations become forbidden and fasting becomes binding while the one taking the pre dawn meal who is ignorant of the dawn must follow the learned man in that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 2, NULL, 'As for the saying of the Prophet (ع),', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'as for the saying of the prophet ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 3, NULL, 'Sayingفَإِنْ غُمَّ عَلَيْكُمْ فَعُدُّوا ثَلَاثِينَ يَوْماً', '', 'فَإِنْ غُمَّ عَلَيْكُمْ فَعُدُّوا ثَلَاثِينَ يَوْماً', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'sayingفان غم عليكم فعدوا ثلاثين يوما', 'فان غم عليكم فعدوا ثلاثين يوما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 4, NULL, '"If it is obscured from you, then count thirty days" — upon consideration, it can scarcely be held that what he intended by it was the sighting of the eye. For fasting by the sight of the eye, when the impediments of cloud and the like are lifted, can hardly ever yield months of thirty days; a month may well be twenty-nine days. And if that is so, it is not permissible that the Prophet (ع) should bind his community, in one of the commands of Allah Almighty, to a rule in which doubt may arise — making this the cause of an addition to an obligation or a subtraction from it, and leaving his community to perform it as though walking in the dark. Nor is it permissible that he should command his community to fast an added day in one of the deficient months on account of cloud, when, had the cloud not been there, it would have been known that fasting on that day is forbidden and that breaking the fast is required. For fasting is worship of Allah Almighty, and it belongs to the religion by which Allah is served; His servants are commanded to sincerity in it, by the saying of Allah Almighty:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'if it is obscured from you then count thirty days upon consideration it can scarcely be held that what he intended by it was the sighting of the eye for fasting by the sight of the eye when the impediments of cloud and the like are lifted can hardly ever yield months of thirty days a month may well be twenty nine days and if that is so it is not permissible that the prophet ع should bind his community in one of the commands of allah almighty to a rule in which doubt may arise making this the cause of an addition to an obligation or a subtraction from it and leaving his community to perform it as though walking in the dark nor is it permissible that he should command his community to fast an added day in one of the deficient months on account of cloud when had the cloud not been there it would have been known that fasting on that day is forbidden and that breaking the fast is required for fasting is worship of allah almighty and it belongs to the religion by which allah is served his servants are commanded to sincerity in it by the saying of allah almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 5, NULL, 'Al-Bayyinah: 5وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ"They were commanded only to worship Allah, sincere to Him in religion."', '', NULL, 'Al-Bayyinah: 5', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'al bayyinah 5وما امروا الا ليعبدوا الله مخلصين له الدين they were commanded only to worship allah sincere to him in religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 6, NULL, 'Sincerity is other than doubt and confusion. And since sincerity is other than doubt and confusion, and since doubt and confusion have entered into this rule and disturbed it, we say that the Prophet (ع) did not call people to doubt and confusion in the worship of Allah Almighty. And since the Prophet (ع) did not call to doubt and confusion, his restricting the days of the month to the fullest and most complete number — without deficiency and without the lesser count — when by the requirement of the sight of the eye the days of a month may be deficient and doubt may fall upon it, can only have been an indication pointing toward the vision of the soul, whose numbers neither increase nor decrease. It was an urging to take hold of what Allah Almighty called for in the completing of the count, in His saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'sincerity is other than doubt and confusion and since sincerity is other than doubt and confusion and since doubt and confusion have entered into this rule and disturbed it we say that the prophet ع did not call people to doubt and confusion in the worship of allah almighty and since the prophet ع did not call to doubt and confusion his restricting the days of the month to the fullest and most complete number without deficiency and without the lesser count when by the requirement of the sight of the eye the days of a month may be deficient and doubt may fall upon it can only have been an indication pointing toward the vision of the soul whose numbers neither increase nor decrease it was an urging to take hold of what allah almighty called for in the completing of the count in his saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 7, NULL, 'Al-Baqarah: 185وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ"And that you may complete the count."', '', NULL, 'Al-Baqarah: 185', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'al baqarah 185ولتكملوا العده and that you may complete the count', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 8, NULL, 'Then we say: from where comes the assurance of a people whose fast, when cloud and impediment occur, rests upon that rule — the assurance that the day they counted as belonging to Ramadan or to Shaban, under a clouded sky, is indeed as they counted and reckoned it, when that very same day, for another people of their own school in taking the sight of the eye, is otherwise, because the impediments of cloud and the like have been lifted for them? So, for example, there is cloud in Kirman, and their fast differs from the fast of Shiraz, where, say, there is no cloud. And if it were permissible for the time of the fast to differ among the people of a single region — so that fasting becomes obligatory upon one people on a given day and upon another people on the following day — then it would likewise be permissible for the time of prayer to differ among the people of a single town, so that one and the same prayer becomes binding upon one man at one time and upon another man at another time. Since that is not permissible, and since, when the time of a prayer has come, the community is bound to establish it whether a man establishes it or abandons it, so likewise, when the time of the fast has come, the fast is binding upon the community, whether a man fasts or breaks it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'then we say from where comes the assurance of a people whose fast when cloud and impediment occur rests upon that rule the assurance that the day they counted as belonging to ramadan or to shaban under a clouded sky is indeed as they counted and reckoned it when that very same day for another people of their own school in taking the sight of the eye is otherwise because the impediments of cloud and the like have been lifted for them so for example there is cloud in kirman and their fast differs from the fast of shiraz where say there is no cloud and if it were permissible for the time of the fast to differ among the people of a single region so that fasting becomes obligatory upon one people on a given day and upon another people on the following day then it would likewise be permissible for the time of prayer to differ among the people of a single town so that one and the same prayer becomes binding upon one man at one time and upon another man at another time since that is not permissible and since when the time of a prayer has come the community is bound to establish it whether a man establishes it or abandons it so likewise when the time of the fast has come the fast is binding upon the community whether a man fasts or breaks it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 9, NULL, 'This being so, the saying of the Prophet (ع) is an indication given by him — knowing that error may fall in the sighting of the eye — pointing to that in which error does not fall: namely, the vision of the soul, which is knowledge, and its count, which belongs among the matters he commended, that is, the completing of the count. Further, his saying, "If it is obscured from you, then count thirty," requires, for entering the fast, that the counting be from the days of Shaban, and, for leaving it by breaking the fast, that the counting be from the days of Ramadan. Now it is known that counting is not possible except by having something to count and knowing its first day. It is also known that in most cases the crescent is not seen at the beginnings of the months, on account of impediments that prevent the sight from seeing it — especially in places whose air is turbid, such as Tabaristan, the mountain regions, the coasts, and the islands of the sea. And if it is possible that the crescent is not seen by the eye at the beginning of Shaban, and is not seen because of some obstacle that occurs, and its first day is not known, then how is one to count from it? And how is one to count from Ramadan when its first day has not been verified? To carry this report upon the meaning of the sighting of the eye requires that the Prophet (ع) cast his community into disagreement and called them to what lies beyond their capacity — namely, the counting of the days of a month whose beginning is not known and in which the crescent is not seen. Yet Allah Almighty says:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'this being so the saying of the prophet ع is an indication given by him knowing that error may fall in the sighting of the eye pointing to that in which error does not fall namely the vision of the soul which is knowledge and its count which belongs among the matters he commended that is the completing of the count further his saying if it is obscured from you then count thirty requires for entering the fast that the counting be from the days of shaban and for leaving it by breaking the fast that the counting be from the days of ramadan now it is known that counting is not possible except by having something to count and knowing its first day it is also known that in most cases the crescent is not seen at the beginnings of the months on account of impediments that prevent the sight from seeing it especially in places whose air is turbid such as tabaristan the mountain regions the coasts and the islands of the sea and if it is possible that the crescent is not seen by the eye at the beginning of shaban and is not seen because of some obstacle that occurs and its first day is not known then how is one to count from it and how is one to count from ramadan when its first day has not been verified to carry this report upon the meaning of the sighting of the eye requires that the prophet ع cast his community into disagreement and called them to what lies beyond their capacity namely the counting of the days of a month whose beginning is not known and in which the crescent is not seen yet allah almighty says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 10, NULL, 'Al-Baqarah: 286لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا"Allah does not burden a soul beyond its capacity."', '', NULL, 'Al-Baqarah: 286', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'al baqarah 286لا يكلف الله نفسا الا وسعها allah does not burden a soul beyond its capacity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 11, NULL, 'Since such a thing cannot be imagined of the Prophet (ع) — who stands far removed and sanctified above burdening Allah''s servants with what lies beyond them or casting them into disagreement — it must follow that either the report "If it is obscured from you, then count thirty days" is not sound, or that if the Prophet (ع) did say it, it must be taken in the one sense that is sound and that removes what is objectionable, and in no other sense. And since this is necessary, and the testimonies have established that what is sound — and what creation is called to — is the vision of the soul, which is knowledge, we say: the discussion has now made clear that what is intended is other than the sighting of the eye, that the common people, who are limited in knowledge, are bound to follow, and that the objection raised in this matter has been overturned.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'since such a thing cannot be imagined of the prophet ع who stands far removed and sanctified above burdening allahs servants with what lies beyond them or casting them into disagreement it must follow that either the report if it is obscured from you then count thirty days is not sound or that if the prophet ع did say it it must be taken in the one sense that is sound and that removes what is objectionable and in no other sense and since this is necessary and the testimonies have established that what is sound and what creation is called to is the vision of the soul which is knowledge we say the discussion has now made clear that what is intended is other than the sighting of the eye that the common people who are limited in knowledge are bound to follow and that the objection raised in this matter has been overturned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 12, NULL, 'Then we say: which of the pillars of Islam that Muhammad (ع) brought has ever had its affair entrusted to the community — a community that is not preserved from error and that falls into slip and mistake? Prayer? Fasting? Zakat? Hajj? Jihad? That fasting alone should forever be committed to them, in the seeking of the crescent and the knowing of its times? Is not prayer the pillar of religion and the face of Islam, and are not all its acts — the opening takbir, the recitation, the bowing, the prostration, and the salutation — committed to the Imam who stands in the place of the Messenger (ع) in leading the people in prayer, and not to those who follow him? Upon those who follow lies the following of the Imam in these acts, without their own preference being followed in advancing any of its acts or in delaying any of its limits; and whoever among them does this — advancing or delaying — his prayer is deficient (خِدَاج). Is not the collecting of zakat committed to the Imam who stands in the place of the Messenger (ع), so that setting it aside or turning it away from him is not permissible, and the distributing of what comes of it belongs to him among those who respond to him, and not to the community, as it was in the days of the Prophet (ع)? Whoever gives his zakat to one other than him who stands in the place of the Messenger (ع) must render it a second time, just as one who, in the days of the Prophet (ع), gave his zakat to another than him would have been bound to render it to him a second time, because he placed it where it did not belong. Is not the Hajj incomplete except with the Imam who goes before the assembly, so that they are bound to follow him in the rites he performs, and whoever sets himself apart by advancing one rite before another or by delaying it, his Hajj is deficient? Is not the ordering of jihad in the way of Allah committed to the one entrusted with the affair of the Muslims who fight — in preserving their order and all their condition, in leading them forward in battle and in withdrawal, and in seeking what is best in truce and in fighting? Upon the community that fights lies the following of the one who commands among them by the command of Allah, and not the following of their own desires in peace and in war; and whoever does anything of that fighting without his command and sheds blood without his permission is held answerable for it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'then we say which of the pillars of islam that muhammad ع brought has ever had its affair entrusted to the community a community that is not preserved from error and that falls into slip and mistake prayer fasting zakat hajj jihad that fasting alone should forever be committed to them in the seeking of the crescent and the knowing of its times is not prayer the pillar of religion and the face of islam and are not all its acts the opening takbir the recitation the bowing the prostration and the salutation committed to the imam who stands in the place of the messenger ع in leading the people in prayer and not to those who follow him upon those who follow lies the following of the imam in these acts without their own preference being followed in advancing any of its acts or in delaying any of its limits and whoever among them does this advancing or delaying his prayer is deficient خداج is not the collecting of zakat committed to the imam who stands in the place of the messenger ع so that setting it aside or turning it away from him is not permissible and the distributing of what comes of it belongs to him among those who respond to him and not to the community as it was in the days of the prophet ع whoever gives his zakat to one other than him who stands in the place of the messenger ع must render it a second time just as one who in the days of the prophet ع gave his zakat to another than him would have been bound to render it to him a second time because he placed it where it did not belong is not the hajj incomplete except with the imam who goes before the assembly so that they are bound to follow him in the rites he performs and whoever sets himself apart by advancing one rite before another or by delaying it his hajj is deficient is not the ordering of jihad in the way of allah committed to the one entrusted with the affair of the muslims who fight in preserving their order and all their condition in leading them forward in battle and in withdrawal and in seeking what is best in truce and in fighting upon the community that fights lies the following of the one who commands among them by the command of allah and not the following of their own desires in peace and in war and whoever does anything of that fighting without his command and sheds blood without his permission is held answerable for it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 13, NULL, 'This being so, and the foundations of Islam being committed to one who preserves them, the community being obliged to follow him in them, from where has it become permissible for these people to follow their own opinions in the entering of the fast — which is one of those foundations — without following in it the one who stands in the place of the Messenger (ع)? Is this severance of theirs, this entering of the fast by their own ijtihad — which brings them to make obligatory what is not an obligation, to abandon an obligation, or to count it a Sunnah — anything other than presumption against Allah, or a departure from the safeguarding of His command? We seek refuge in Allah from that.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'this being so and the foundations of islam being committed to one who preserves them the community being obliged to follow him in them from where has it become permissible for these people to follow their own opinions in the entering of the fast which is one of those foundations without following in it the one who stands in the place of the messenger ع is this severance of theirs this entering of the fast by their own ijtihad which brings them to make obligatory what is not an obligation to abandon an obligation or to count it a sunnah anything other than presumption against allah or a departure from the safeguarding of his command we seek refuge in allah from that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 14, NULL, 'If he says: "On the principle you have laid down for the entering of the fast, namely conjunction and separation, the day on which conjunction and separation fall must be partly of Shaban and partly of Ramadan, and the fasting of that part becomes binding; and this is a contradiction, which the Prophet (ع) did not command," we say: the Prophet (ع) imposed the obligations on behalf of Allah, and appointed for each obligation two causes by which it becomes due and binding. The first is a preceding cause, by which the second cause is made valid; the second is the cause by which one obligation is distinguished from another. The first is general — it is a cause for this obligation and for others besides it, so that in performing the obligation one does not take hold of it alone but of the second. The second follows upon the general one and is specific — it belongs to that obligation alone, and by it the obligation is set apart from all else.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'if he says on the principle you have laid down for the entering of the fast namely conjunction and separation the day on which conjunction and separation fall must be partly of shaban and partly of ramadan and the fasting of that part becomes binding and this is a contradiction which the prophet ع did not command we say the prophet ع imposed the obligations on behalf of allah and appointed for each obligation two causes by which it becomes due and binding the first is a preceding cause by which the second cause is made valid the second is the cause by which one obligation is distinguished from another the first is general it is a cause for this obligation and for others besides it so that in performing the obligation one does not take hold of it alone but of the second the second follows upon the general one and is specific it belongs to that obligation alone and by it the obligation is set apart from all else', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 15, NULL, 'Prayer: Since this prayer is not obligatory except by day, the day is its preceding general cause — a cause for this prayer and for the other prayers performed by day alike. Then, since this prayer is not obligatory by the mere occurrence of that preceding cause, which is the day, except when the sun declines from the zenith, the declining of the sun is a second cause by which the prayer becomes obligatory and by which one takes hold in performing it; and it is specific. Zakat: Since zakat is not obligatory except upon wealth, wealth is the cause of the obligation of zakat, and it is a preceding general cause. Then, since zakat is not obligatory by the mere occurrence of that preceding cause, which is wealth, except when a year has passed over it, the year is a second cause by which it becomes due and by which one takes hold in performing it; and it is specific. Hajj: Since the Hajj is not obligatory except with ability, ability is its preceding general cause. Then, since a man does not become obligated to perform the Hajj by the mere occurrence of ability — the preceding cause — except on the greatest day at Mecca, that day is a second cause by which one takes hold in fulfilling it; and it is specific. Jihad: Since jihad is not obligatory except with the occurrence of opposition, the raising of the standard of disobedience, and the refusal of obedience, opposition is the preceding general cause. Then, since jihad is not obligatory by the mere existence of opposition and refusal of obedience except through the standing of the one who holds the place of the Messenger (ع) and a head who leads the community into battle, that is a second cause; and it is specific.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'prayer since this prayer is not obligatory except by day the day is its preceding general cause a cause for this prayer and for the other prayers performed by day alike then since this prayer is not obligatory by the mere occurrence of that preceding cause which is the day except when the sun declines from the zenith the declining of the sun is a second cause by which the prayer becomes obligatory and by which one takes hold in performing it and it is specific zakat since zakat is not obligatory except upon wealth wealth is the cause of the obligation of zakat and it is a preceding general cause then since zakat is not obligatory by the mere occurrence of that preceding cause which is wealth except when a year has passed over it the year is a second cause by which it becomes due and by which one takes hold in performing it and it is specific hajj since the hajj is not obligatory except with ability ability is its preceding general cause then since a man does not become obligated to perform the hajj by the mere occurrence of ability the preceding cause except on the greatest day at mecca that day is a second cause by which one takes hold in fulfilling it and it is specific jihad since jihad is not obligatory except with the occurrence of opposition the raising of the standard of disobedience and the refusal of obedience opposition is the preceding general cause then since jihad is not obligatory by the mere existence of opposition and refusal of obedience except through the standing of the one who holds the place of the messenger ع and a head who leads the community into battle that is a second cause and it is specific', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 16, NULL, 'Since that is so, we say that fasting too has two causes. The first is preceding and general: the separation of the moon from the sun. The second is specific: the time of dawn at which entering into the fast becomes obligatory. And just as prayer is not obligatory — though it be day — except at the declining of the sun, and that is its time; nor zakat — though there be wealth — except when a year has passed over it, and that is its time; nor Hajj — though there be ability — except at Mecca on the greatest day, and that is its time; nor jihad — though there be opposition — except through the ordering head who stands in the place of the Lord of the worlds, and he is its support; so likewise fasting is not obligatory — though the moon has separated from the sun — except at the dawn that follows upon that separation, and that is its time. His saying in objection — that part of the day is of Shaban and part of it is of Ramadan and that the fasting of that part is consequently binding — is thus overturned.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'since that is so we say that fasting too has two causes the first is preceding and general the separation of the moon from the sun the second is specific the time of dawn at which entering into the fast becomes obligatory and just as prayer is not obligatory though it be day except at the declining of the sun and that is its time nor zakat though there be wealth except when a year has passed over it and that is its time nor hajj though there be ability except at mecca on the greatest day and that is its time nor jihad though there be opposition except through the ordering head who stands in the place of the lord of the worlds and he is its support so likewise fasting is not obligatory though the moon has separated from the sun except at the dawn that follows upon that separation and that is its time his saying in objection that part of the day is of shaban and part of it is of ramadan and that the fasting of that part is consequently binding is thus overturned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 17, NULL, 'What adds to the certainty of this, along with the proofs already established from the apparent, is the greatest testimony, which speaks to the truthfulness of the Messenger of Allah (ع) in what he brought from Allah Almighty: the balance between what he laid down of the Law and the religious ordinances and what Allah Almighty created and formed in the horizons and in the souls, as stated in the saying of Allah:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'what adds to the certainty of this along with the proofs already established from the apparent is the greatest testimony which speaks to the truthfulness of the messenger of allah ع in what he brought from allah almighty the balance between what he laid down of the law and the religious ordinances and what allah almighty created and formed in the horizons and in the souls as stated in the saying of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 18, NULL, 'Fussilat: 53سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ"We shall show them Our signs in the horizons and in their own souls, until it becomes clear to them that it is the truth."', '', NULL, 'Fussilat: 53', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'fussilat 53سنريهم ايتنا في الافاق وفي انفسهم حتي يتبين لهم انه الحق we shall show them our signs in the horizons and in their own souls until it becomes clear to them that it is the truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 19, NULL, 'No human being has the power to imitate him in such a work, save one whose lineage is in the holy precinct (حَظِيرَةُ الْقُدْسِ) and whose soul has been given readiness and endowment for receiving the revelation of Allah Almighty, when one returns to the interpretation, which is one of the two divisions to which Allah commanded His Prophet (ع) to call His servants in His worship, in His saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'no human being has the power to imitate him in such a work save one whose lineage is in the holy precinct حظيره القدس and whose soul has been given readiness and endowment for receiving the revelation of allah almighty when one returns to the interpretation which is one of the two divisions to which allah commanded his prophet ع to call his servants in his worship in his saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 20, NULL, 'An-Nahl: 125ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ"Call to the way of your Lord with wisdom."', '', NULL, 'An-Nahl: 125', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'an nahl 125ادع الي سبيل ربك بالحكمه call to the way of your lord with wisdom', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 21, NULL, 'This wisdom has two divisions:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'this wisdom has two divisions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 22, NULL, 'The work: the outward, natural worship suited to natural bodies, carried out through the obligations and practices the Prophet (ع) brought, and requiring interpretation — that is, knowledge. The knowledge: the greatest form of worship, the hidden worship of the soul, suited to particular souls. It is attained by holding to the truths concerning how to purify the affirmation of Allah''s oneness, and by so doing it confirms the outward natural worship, which is the work.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'the work the outward natural worship suited to natural bodies carried out through the obligations and practices the prophet ع brought and requiring interpretation that is knowledge the knowledge the greatest form of worship the hidden worship of the soul suited to particular souls it is attained by holding to the truths concerning how to purify the affirmation of allahs oneness and by so doing it confirms the outward natural worship which is the work', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 23, NULL, 'In the interpretive call, the sun — in that it is the noblest and most luminous of bodies, the source of light for all others, the cause of growth among offspring in the world of nature, and the cause to which all the causes of the world are attached — has been made an indication pointing to knowledge of the rank of the Prophet (ع). Just as the sun is the noblest and most luminous of bodies, so the soul of the Speaker is the noblest of souls and the most knowing of them. Just as the sun is the source of light for the other stars, so the soul of the Speaker (ع) is the source for the souls of men in the divine sciences that lead to the pure affirmation of oneness. Just as the sun is the cause of growth among offspring in the world of nature, so the Prophet (ع) is the cause of growth among spiritual offspring in the world of the soul. And just as the sun is the cause to which the causes of the bodily world are attached, so the Prophet (ع) is the cause to which the causes of the world of religion are attached, which is the worship of Allah Almighty. The one is in the body, and the other is in the soul.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'in the interpretive call the sun in that it is the noblest and most luminous of bodies the source of light for all others the cause of growth among offspring in the world of nature and the cause to which all the causes of the world are attached has been made an indication pointing to knowledge of the rank of the prophet ع just as the sun is the noblest and most luminous of bodies so the soul of the speaker is the noblest of souls and the most knowing of them just as the sun is the source of light for the other stars so the soul of the speaker ع is the source for the souls of men in the divine sciences that lead to the pure affirmation of oneness just as the sun is the cause of growth among offspring in the world of nature so the prophet ع is the cause of growth among spiritual offspring in the world of the soul and just as the sun is the cause to which the causes of the bodily world are attached so the prophet ع is the cause to which the causes of the world of religion are attached which is the worship of allah almighty the one is in the body and the other is in the soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 24, NULL, 'As for the moon: its rank falls below the sun; it receives more of the sun''s light than the other stars receive; it gives light in the darkness of the night; and it stands as an intermediary in the growth of offspring between the earth and the sun, both receiving and bestowing. For these reasons, the moon has been made an indication pointing to the rank of the Foundation (الْأَسَاس). Just as the moon''s rank in light falls below the sun, so the rank of the Foundation in receiving the radiance of the world of origination falls below the Prophet (ع).', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'as for the moon its rank falls below the sun it receives more of the suns light than the other stars receive it gives light in the darkness of the night and it stands as an intermediary in the growth of offspring between the earth and the sun both receiving and bestowing for these reasons the moon has been made an indication pointing to the rank of the foundation الاساس just as the moons rank in light falls below the sun so the rank of the foundation in receiving the radiance of the world of origination falls below the prophet ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 25, NULL, 'I have said that the moon receives more of the sun''s light than any other of the wandering bodies; and in just the same way, the Foundation (الْأَسَاس) receives from the Speaker (اَلنَّاطِق) more of the blessings of the affirmation of Allah''s oneness than any other recipient does. Just as the moon gives light in the darkness of the night, so the Foundation makes plain what the Prophet (ع) brought of the sealed symbols, the law set out in its breadth, and the parables that were struck. And just as the moon is the intermediary between the sun and the other bodies in the growth of offspring, so the Foundation is the intermediary between the Speaker and the community in the growth of spiritual offspring in the world of the soul, both conferring benefit and receiving it.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'i have said that the moon receives more of the suns light than any other of the wandering bodies and in just the same way the foundation الاساس receives from the speaker الناطق more of the blessings of the affirmation of allahs oneness than any other recipient does just as the moon gives light in the darkness of the night so the foundation makes plain what the prophet ع brought of the sealed symbols the law set out in its breadth and the parables that were struck and just as the moon is the intermediary between the sun and the other bodies in the growth of offspring so the foundation is the intermediary between the speaker and the community in the growth of spiritual offspring in the world of the soul both conferring benefit and receiving it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 26, NULL, 'Now that the states of the bodily sun and moon in the world of bodies have been set beside the states of the spiritual sun and moon in the world of religion, I say that the moon has several states:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'now that the states of the bodily sun and moon in the world of bodies have been set beside the states of the spiritual sun and moon in the world of religion i say that the moon has several states', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 27, NULL, 'When it comes into conjunction with the sun, the upper half of its body — the half that faces the sun — is illumined. This is what the astronomers mean when they say that a power extends to it, by which everything that is to come into being of events and existing things is brought into being until the second conjunction, by a measure ordained from the Mighty, the All-Knowing. It is like a minister who comes into the presence of the king: the king charges him concerning the affairs of the kingdom with what he is to carry out once he has left the royal presence. So it is with the Prophet (ع) teaching the Foundation (ع) what he wished to teach him, that he might stand in the Prophet''s place in guidance and instruction — the Foundation receiving from him in his days, conferring nothing before that designation. It is for this reason that the Prophet (ع) pointed to Ali ibn Abi Talib (ع) and said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'when it comes into conjunction with the sun the upper half of its body the half that faces the sun is illumined this is what the astronomers mean when they say that a power extends to it by which everything that is to come into being of events and existing things is brought into being until the second conjunction by a measure ordained from the mighty the all knowing it is like a minister who comes into the presence of the king the king charges him concerning the affairs of the kingdom with what he is to carry out once he has left the royal presence so it is with the prophet ع teaching the foundation ع what he wished to teach him that he might stand in the prophets place in guidance and instruction the foundation receiving from him in his days conferring nothing before that designation it is for this reason that the prophet ع pointed to ali ibn abi talib ع and said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 28, NULL, 'Saying"أَنَا مَدِينَةُ الْعِلْمِ وَعَلِيٌّ بَابُهَا فَمَنْ أَرَادَ الْعِلْمَ فَلْيَأْتِ الْبَابَ""I am the city of knowledge and Ali is its gate. Whoever desires knowledge, let him come to the gate."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying انا مدينه العلم وعلي بابها فمن اراد العلم فليات الباب i am the city of knowledge and ali is its gate whoever desires knowledge let him come to the gate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 29, NULL, 'After the parting, the moon falls into hiddenness, lying beneath the light of the sun, concealed from the sight of the generality of people and seen only by those possessed of knowledge. This is like the hiddenness of the affair of the Foundation — his rank and the obligation of obedience to him, established by means of the indications made toward him — hidden from the people of ignorance and from the common people, and disclosed only to those of merit and special standing. When the sun has reached its setting place, the moon appears as a crescent so that the great and the small alike behold it. This is like the manifestation of the Foundation''s affair through what came from the Speaker (ع) in the explicit text concerning him and the imposing of obedience to him, when the time of his own departure from the world drew near, so that the small and the great came to know it. The moon has no light during the day while the disc of the sun stands above the earth, and has light only after the sun has set. This is like the Foundation, who has no affair during the lifetime of the Speaker (ع), and only after his departure from the world. At the beginning of its appearance it is faint, seen only by one whose sight is strong, and people fall into disagreement over the sighting of it. This is like the weakness of the affair of the Foundation at the beginning of its season, the arising of disagreement concerning his Imamate, and the shrinking back of the community from binding themselves to obedience to him, except for one who possessed sincerity and knowledge. Its light increases with the passing of the days. So too the affair of his summons rises and his Imamate spreads among the people with the passing of the years. When fourteen days of it have passed, its light is complete, so that the small and the great see it and no one doubts the sighting of it. This is like the light of his Imamate reaching all the nations at the passing of the seven repetitions (اَلْمَثَانِي السَّبْعَةُ) at the end of the cycle, so that at that time no one doubts his Imamate and his precedence.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'after the parting the moon falls into hiddenness lying beneath the light of the sun concealed from the sight of the generality of people and seen only by those possessed of knowledge this is like the hiddenness of the affair of the foundation his rank and the obligation of obedience to him established by means of the indications made toward him hidden from the people of ignorance and from the common people and disclosed only to those of merit and special standing when the sun has reached its setting place the moon appears as a crescent so that the great and the small alike behold it this is like the manifestation of the foundations affair through what came from the speaker ع in the explicit text concerning him and the imposing of obedience to him when the time of his own departure from the world drew near so that the small and the great came to know it the moon has no light during the day while the disc of the sun stands above the earth and has light only after the sun has set this is like the foundation who has no affair during the lifetime of the speaker ع and only after his departure from the world at the beginning of its appearance it is faint seen only by one whose sight is strong and people fall into disagreement over the sighting of it this is like the weakness of the affair of the foundation at the beginning of its season the arising of disagreement concerning his imamate and the shrinking back of the community from binding themselves to obedience to him except for one who possessed sincerity and knowledge its light increases with the passing of the days so too the affair of his summons rises and his imamate spreads among the people with the passing of the years when fourteen days of it have passed its light is complete so that the small and the great see it and no one doubts the sighting of it this is like the light of his imamate reaching all the nations at the passing of the seven repetitions المثاني السبعه at the end of the cycle so that at that time no one doubts his imamate and his precedence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 30, NULL, 'Then there is the fact that the people of knowledge and faith assign the day that falls within the concealment after the parting to the coming month — just as one of sound faith held himself bound, by what he knew of the indications of the Prophet (ع) given to a few in particular, to obedience to the Commander of the Faithful before the explicit text was given outwardly for all. The people of ignorance and the common people, by contrast, assign that day — whose fast is obligatory — to the month now past, whose fast is not obligatory, through the scantness of their knowledge, and so they fail in fasting it until they see the crescent with the eye. In the same way, they assign to the Foundation — obedience to whom is obligatory — the same standing as any other to whom obedience is not made obligatory, neither by indication nor by explicit text, and they fail in obedience to him out of ignorance of its being binding upon them, until the truth of his Imamate becomes plain to them.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'then there is the fact that the people of knowledge and faith assign the day that falls within the concealment after the parting to the coming month just as one of sound faith held himself bound by what he knew of the indications of the prophet ع given to a few in particular to obedience to the commander of the faithful before the explicit text was given outwardly for all the people of ignorance and the common people by contrast assign that day whose fast is obligatory to the month now past whose fast is not obligatory through the scantness of their knowledge and so they fail in fasting it until they see the crescent with the eye in the same way they assign to the foundation obedience to whom is obligatory the same standing as any other to whom obedience is not made obligatory neither by indication nor by explicit text and they fail in obedience to him out of ignorance of its being binding upon them until the truth of his imamate becomes plain to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 31, NULL, 'The month of Ramadan is, among the months of the year, the noblest of them and the greatest in weight. It stands for the Foundation, who is placed ahead of the rest of the companions, whose rank was ennobled by exposition and interpretation — which is knowledge — who was pointed to by the indications, and who is the gathering place of the knowledge of all that the Prophet (ع) brought from Allah the Exalted. It is for this reason that Allah the Exalted said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'the month of ramadan is among the months of the year the noblest of them and the greatest in weight it stands for the foundation who is placed ahead of the rest of the companions whose rank was ennobled by exposition and interpretation which is knowledge who was pointed to by the indications and who is the gathering place of the knowledge of all that the prophet ع brought from allah the exalted it is for this reason that allah the exalted said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 32, NULL, 'Saying"شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ هُدًى لِلنَّاسِ وَالْبَيِّنَاتِ مِنَ الْهُدَى وَالْفُرْقَانِ""The month of Ramadan, in which the Quran was sent down as guidance for the people, and as clear proofs of guidance and of the criterion."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying شهر رمضان الذي انزل فيه القران هدي للناس والبينات من الهدي والفرقان the month of ramadan in which the quran was sent down as guidance for the people and as clear proofs of guidance and of the criterion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 33, NULL, 'This verse was intended as an indication pointing to him. We know, after all, that the Quran was revealed over twenty-three years — not all at once in the month of Ramadan, but day by day, month by month, and year by year. To read this verse according to its outward sense leads directly to contradiction. Interpretation is therefore necessary, so that the word of Allah the Exalted and the word of the Messenger (ع) may each stand firm, together with the binding character of the fast and its obligation upon the sighting of the crescent: first, on the side of the soul, for the people of knowledge, at the very moment of their sighting; and last, on the side of the senses, for the people of ignorance. The same principle governs the obligation of obedience to the Foundation (ع) — when the Prophet (ع) raised him to this station and pointed to him, he did so first through indications understood by those with knowledge and discernment, and last through explicit text and formal declaration for the common people. The same principle also governs the obligation upon whoever is present to hold back from opening discourse and from teaching, even while the Foundation stands ahead of the assembly. It is for this that Allah the Exalted said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'this verse was intended as an indication pointing to him we know after all that the quran was revealed over twenty three years not all at once in the month of ramadan but day by day month by month and year by year to read this verse according to its outward sense leads directly to contradiction interpretation is therefore necessary so that the word of allah the exalted and the word of the messenger ع may each stand firm together with the binding character of the fast and its obligation upon the sighting of the crescent first on the side of the soul for the people of knowledge at the very moment of their sighting and last on the side of the senses for the people of ignorance the same principle governs the obligation of obedience to the foundation ع when the prophet ع raised him to this station and pointed to him he did so first through indications understood by those with knowledge and discernment and last through explicit text and formal declaration for the common people the same principle also governs the obligation upon whoever is present to hold back from opening discourse and from teaching even while the foundation stands ahead of the assembly it is for this that allah the exalted said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 34, NULL, 'Saying"لَا تَرْفَعُوٓا۟ أَصْوَتَكُمْ فَوْقَ صَوْتِ ٱلنَّبِىِّ""Do not raise your voices above the voice of the Prophet."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying لا ترفعوا اصوتكم فوق صوت النبي do not raise your voices above the voice of the prophet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 35, NULL, 'This forbids the community from overstepping in a way that would drive out the ruling of Allah the Exalted and narrow it rather than widen it — by going ahead of the Messenger in his time, and ahead of the Foundation and whoever stands in their place in their own time — so that the Imam may be distinguished from those who follow him, and the head from those under him. Then He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'this forbids the community from overstepping in a way that would drive out the ruling of allah the exalted and narrow it rather than widen it by going ahead of the messenger in his time and ahead of the foundation and whoever stands in their place in their own time so that the imam may be distinguished from those who follow him and the head from those under him then he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 36, NULL, 'Saying"من شهد منكم الشهر فليصمه""Whoever among you witnesses the month, let him fast it."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying من شهد منكم الشهر فليصمه whoever among you witnesses the month let him fast it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 37, NULL, 'This is an indication from the Speaker to the community that follows him: they are to follow the Foundation and to listen in silence to his speech. The meaning is that whoever attends the assembly of the Foundation in the knowledge of the outward and the inward, let him keep silent — for it is the Foundation who has been honored, who is placed ahead, and to whom the affair of religion is entrusted, and no one else. This is evidence that before obedience to him was made obligatory, the people used to discourse with one another in matters of religion and knowledge however they wished, and were then forbidden from it — just as before the fast and its obligation they used to eat however they liked, and were then forbidden from it by the imposing of the fast. It is like the command of the Prophet (ع) in the matter of marriage, when he said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'this is an indication from the speaker to the community that follows him they are to follow the foundation and to listen in silence to his speech the meaning is that whoever attends the assembly of the foundation in the knowledge of the outward and the inward let him keep silent for it is the foundation who has been honored who is placed ahead and to whom the affair of religion is entrusted and no one else this is evidence that before obedience to him was made obligatory the people used to discourse with one another in matters of religion and knowledge however they wished and were then forbidden from it just as before the fast and its obligation they used to eat however they liked and were then forbidden from it by the imposing of the fast it is like the command of the prophet ع in the matter of marriage when he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 38, NULL, 'Saying"لَا نِكَاحَ إِلَّا بِوَلِيٍّ وَشَاهِدَيْنِ""There is no marriage except with a guardian and two witnesses."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying لا نكاح الا بولي وشاهدين there is no marriage except with a guardian and two witnesses', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 39, NULL, 'This shows that marriage had previously been contracted without a guardian or two witnesses — that is, temporary marriage (اَلْمُتْعَة) — however people wished, in the early days of Islam, and that they were then forbidden from this practice by this ruling.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'this shows that marriage had previously been contracted without a guardian or two witnesses that is temporary marriage المتعه however people wished in the early days of islam and that they were then forbidden from this practice by this ruling', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 40, NULL, 'Then His word:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'then his word', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 41, NULL, 'Saying"وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍۢ فَعِدَّةٌۭ مِّنْ أَيَّامٍ أُخَرَ""And whoever is sick or on a journey, then a number of other days."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying ومن كان مريضا او علي سفر فعده من ايام اخر and whoever is sick or on a journey then a number of other days', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 42, NULL, 'This is an exception that applies to all who witness the month. The meaning is that silence has been made obligatory upon all people when they attend the assembly of interpretation ascribed to the Foundation — except for one whose speech is for the sake of receiving benefit: a man in doubt, or a learner. In such a case, silence again becomes binding upon him afterward according to the rule. For attendance at that assembly is the prayer of the soul and of knowledge, and what is required in the prayer of works must equally be observed within it: the etiquettes, the customary practices, and the upholding of the rulings. I have also set down in the comprehensive treatise a portion concerning the fast, with explanation and clarification, to the measure of the benefits that have reached me from the side of the guardian of Allah (ع).', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'this is an exception that applies to all who witness the month the meaning is that silence has been made obligatory upon all people when they attend the assembly of interpretation ascribed to the foundation except for one whose speech is for the sake of receiving benefit a man in doubt or a learner in such a case silence again becomes binding upon him afterward according to the rule for attendance at that assembly is the prayer of the soul and of knowledge and what is required in the prayer of works must equally be observed within it the etiquettes the customary practices and the upholding of the rulings i have also set down in the comprehensive treatise a portion concerning the fast with explanation and clarification to the measure of the benefits that have reached me from the side of the guardian of allah ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 43, NULL, 'As for the month of Ramadan of the year four hundred — and the agreement of the people of truth to enter its fast two days before the crescent was sighted with the eye — this is a matter that, upon my life, is confusing to all but the people of understanding, given that no more than a single day of difference had ever been known to pass between the fast of the people of truth and the fast of the people of disagreement.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'as for the month of ramadan of the year four hundred and the agreement of the people of truth to enter its fast two days before the crescent was sighted with the eye this is a matter that upon my life is confusing to all but the people of understanding given that no more than a single day of difference had ever been known to pass between the fast of the people of truth and the fast of the people of disagreement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 44, NULL, 'The reason is this: the conjunction that occurred in the month of Ramadan fell on the night of Monday, making Monday its first day. The crescent was not seen on Tuesday night by naked-eye sighting, because the sun''s light overpowered its body. At the time of sunset, the moon stood at six degrees and some minutes from the sun — a distance equal to half the moon''s body — and at such a distance the sight cannot reach it, since it falls beneath the ray that prevents sight from doing its work. It was therefore not permissible, out of propriety, to break the fast on that day, for the moon stood from the sun at the end of the month at a like number of degrees. Had one broken the fast then, what could have been fasted of the month of Ramadan would have amounted to only twenty-nine days — because the conjunction of the sun and the moon for Shawwal fell on the night of Wednesday, at two hours and some minutes into it, making Wednesday the day of the festival, on which fasting is forbidden. A failure in one of the obligatory duties would thus have occurred, since the month of Ramadan is thirty days without deficiency, by the word of our masters (عَلَيْهِمُ السَّلَامُ):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'the reason is this the conjunction that occurred in the month of ramadan fell on the night of monday making monday its first day the crescent was not seen on tuesday night by naked eye sighting because the suns light overpowered its body at the time of sunset the moon stood at six degrees and some minutes from the sun a distance equal to half the moons body and at such a distance the sight cannot reach it since it falls beneath the ray that prevents sight from doing its work it was therefore not permissible out of propriety to break the fast on that day for the moon stood from the sun at the end of the month at a like number of degrees had one broken the fast then what could have been fasted of the month of ramadan would have amounted to only twenty nine days because the conjunction of the sun and the moon for shawwal fell on the night of wednesday at two hours and some minutes into it making wednesday the day of the festival on which fasting is forbidden a failure in one of the obligatory duties would thus have occurred since the month of ramadan is thirty days without deficiency by the word of our masters عليهم السلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 45, NULL, 'Saying"مَا تَمَّ شَعْبَانُ وَلَا نَقَصَ رَمَضَانُ"', '', '" مَا تَمَّ شَعْبَانُ وَلَا نَقَصَ رَمَضَانُ"', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying ما تم شعبان ولا نقص رمضان', 'ما تم شعبان ولا نقص رمضان');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 46, NULL, 'The strongest proof of the soundness of our entering the fast from Monday is the word of the Prophet (ع):', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'the strongest proof of the soundness of our entering the fast from monday is the word of the prophet ع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 47, NULL, 'Saying"يَوْمُ صَوْمِكُمْ يَوْمُ نَحْرِكُمْ""The day of your fasting is the day of your sacrifice."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying يوم صومكم يوم نحركم the day of your fasting is the day of your sacrifice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 48, NULL, 'The sacrifice in the Sacred Precinct fell on Monday, the tenth of Dhu al-Hijjah of the year four hundred — according to what the sighting by knowledge requires — which is the ninth of it according to what the sighting by the eye requires. And the matter holds in this way every year, as he said (ع), without any disagreement arising.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'the sacrifice in the sacred precinct fell on monday the tenth of dhu al hijjah of the year four hundred according to what the sighting by knowledge requires which is the ninth of it according to what the sighting by the eye requires and the matter holds in this way every year as he said ع without any disagreement arising', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 49, NULL, 'If someone should say: what you have brought forward concerning the sun and the moon, the degrees, the distances, and the hours, and on which you have built your argument and your proof, belongs to the science of the stars, and the Prophet (ع) forbade taking it up and looking into it — I say: how is it that inference concerning the establishing of the time of the fast, and knowledge of it by way of the sun and the moon, which are the cause of the months and the years and which cannot be attained except through their motion, their course, their conjunction, and their separation, is forbidden to us, while inference concerning the establishing of the direction of prayer and the times of prayer, and the knowledge of them — which is like the fast in being among the pillars of Islam — by way of the mansions of the moon and the elevation of the sun with the measures we have set up for you, is commanded? Is this anything other than an unjust division (قِسْمَةٌ ضِيزَى)?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'if someone should say what you have brought forward concerning the sun and the moon the degrees the distances and the hours and on which you have built your argument and your proof belongs to the science of the stars and the prophet ع forbade taking it up and looking into it i say how is it that inference concerning the establishing of the time of the fast and knowledge of it by way of the sun and the moon which are the cause of the months and the years and which cannot be attained except through their motion their course their conjunction and their separation is forbidden to us while inference concerning the establishing of the direction of prayer and the times of prayer and the knowledge of them which is like the fast in being among the pillars of islam by way of the mansions of the moon and the elevation of the sun with the measures we have set up for you is commanded is this anything other than an unjust division قسمه ضيزي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 50, NULL, 'The Prophet (ع) forbade it only in a particular respect. It is that whoever begins the pursuit of the sciences by learning the science of the stars, without the divine and revealed sciences preceding it for him, is led by that path to what the followers of Ptolemy hold, and those who ascribe divinity to the heavenly bodies. But when the religious and revealed sciences have preceded it, then knowledge of the manner of the spheres and the stars, and of that for which they were composed, increases the soul in certainty concerning the oneness of Allah the Exalted, and gains for its conception of His unity a firmer faith. So too Allah the Exalted said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'the prophet ع forbade it only in a particular respect it is that whoever begins the pursuit of the sciences by learning the science of the stars without the divine and revealed sciences preceding it for him is led by that path to what the followers of ptolemy hold and those who ascribe divinity to the heavenly bodies but when the religious and revealed sciences have preceded it then knowledge of the manner of the spheres and the stars and of that for which they were composed increases the soul in certainty concerning the oneness of allah the exalted and gains for its conception of his unity a firmer faith so too allah the exalted said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 51, NULL, 'Saying"لَخَلْقُ ٱلسَّمَوَتِ وَٱلْأَرْضِ أَكْبَرُ مِنْ خَلْقِ ٱلنَّاسِ وَلَكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ""The creation of the heavens and the earth is greater than the creation of mankind, but most people do not know."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying لخلق السموت والارض اكبر من خلق الناس ولكن اكثر الناس لا يعلمون the creation of the heavens and the earth is greater than the creation of mankind but most people do not know', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 52, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 53, NULL, 'Saying"سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ""We shall show them Our signs on the horizons and within themselves until it becomes clear to them that it is the truth."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying سنريهم ايتنا في الافاق وفي انفسهم حتي يتبين لهم انه الحق we shall show them our signs on the horizons and within themselves until it becomes clear to them that it is the truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 54, NULL, 'The horizons are nothing other than the heavens and all they contain. Moreover, had the matter been as that objector claimed, Allah the Exalted would not have sworn by the stars, nor would He have described them as indicating His unity in His Book, where He says:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'the horizons are nothing other than the heavens and all they contain moreover had the matter been as that objector claimed allah the exalted would not have sworn by the stars nor would he have described them as indicating his unity in his book where he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 55, NULL, 'Saying"تَبَارَكَ ٱلَّذِى جَعَلَ فِى ٱلسَّمَآءِ بُرُوجًۭا وَجَعَلَ فِيهَا سِرَجًۭا وَقَمَرًۭا مُّنِيرًۭا""Blessed is He who placed constellations in the sky and placed in it a lamp and an illuminating moon."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying تبارك الذي جعل في السماء بروجا وجعل فيها سرجا وقمرا منيرا blessed is he who placed constellations in the sky and placed in it a lamp and an illuminating moon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 56, NULL, 'Nor would He have sworn, saying:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'nor would he have sworn saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 57, NULL, 'Saying"فلا أقسم بمواقع النجوم وأنه قسم لو تعلمون عظيم""So I swear by the settings of the stars, and it is indeed a great oath, if you only knew."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying فلا اقسم بمواقع النجوم وانه قسم لو تعلمون عظيم so i swear by the settings of the stars and it is indeed a great oath if you only knew', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 58, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 59, NULL, 'Saying"فَلَا أُقْسِمُ بِالْخُنَّسِ الْجَوَارِ الْكُنَّسِ""So I swear by the receding stars, that run their course and hide."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying فلا اقسم بالخنس الجوار الكنس so i swear by the receding stars that run their course and hide', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 60, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 61, NULL, 'Saying"فَالْمُدَبِّرَاتِ أَمْرًا""And those that arrange the affair."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying فالمدبرات امرا and those that arrange the affair', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 62, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 63, NULL, 'Saying"وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ""By the sky containing the constellations."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying والسماء ذات البروج by the sky containing the constellations', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 64, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 65, NULL, 'Saying"وَالشَّمْسِ وَضُحَاهَا وَالْقَمَرِ إِذَا تَلَاهَا"', '', '" وَالشَّمْسِ وَضُحَاهَا وَالْقَمَرِ إِذَا تَلَاهَا"', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying والشمس وضحاها والقمر اذا تلاها', 'والشمس وضحاها والقمر اذا تلاها');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 66, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 67, NULL, 'Saying"هُوَ ٱلَّذِى جَعَلَ ٱلشَّمْسَ ضِيَآءًۭ وَٱلْقَمَرَ نُورًۭا وَقَدَّرَهُۥ مَنَازِلَ لِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ""It is He who made the sun a radiance and the moon a light, and determined for it stages, that you might know the number of the years and the reckoning."', '', NULL, 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying هو الذي جعل الشمس ضياء والقمر نورا وقدره منازل لتعلموا عدد السنين والحساب it is he who made the sun a radiance and the moon a light and determined for it stages that you might know the number of the years and the reckoning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 68, NULL, 'What merit, then, is nobler than knowledge of the luminous stars in their circles — their positions at their highest and their lowest — which testify to the soundness of what Allah the Exalted has established of His religion, and bear witness to the truth of what the Prophet (ع) brought from Allah? And what knowledge stands higher, after the affirmation of oneness and the ranks of the hudud (الْحُدُود), than knowledge of what arises through the passage of the stars through their constellations — southward and northward — and through the conjunctions of their lights with one another, in the world of generation and corruption, in the appearance of offspring and in other events that point to the ranks of the friends of Allah?', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'what merit then is nobler than knowledge of the luminous stars in their circles their positions at their highest and their lowest which testify to the soundness of what allah the exalted has established of his religion and bear witness to the truth of what the prophet ع brought from allah and what knowledge stands higher after the affirmation of oneness and the ranks of the hudud الحدود than knowledge of what arises through the passage of the stars through their constellations southward and northward and through the conjunctions of their lights with one another in the world of generation and corruption in the appearance of offspring and in other events that point to the ranks of the friends of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 69, NULL, 'Saying"فَهَلْ يَسْتَوِي الظُّلُمَاتُ وَالنُّورُ أَمْ هَلْ يَسْتَوِي الْأَعْمَى وَالْبَصِيرُ أَمْ هَلْ يَسْتَوِي الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لَا يَعْلَمُونَ إِنَّمَا يَتَذَكَّرُ أُولُوا الْأَلْبَابِ"', '', '" فَهَلْ يَسْتَوِي الظُّلُمَاتُ وَالنُّورُ أَمْ هَلْ يَسْتَوِي الْأَعْمَى وَالْبَصِيرُ أَمْ هَلْ يَسْتَوِي الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لَا يَعْلَمُونَ إِنَّمَا يَتَذَكَّرُ أُولُوا الْأَلْبَابِ"', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'saying فهل يستوي الظلمات والنور ام هل يستوي الاعمي والبصير ام هل يستوي الذين يعلمون والذين لا يعلمون انما يتذكر اولوا الالباب', 'فهل يستوي الظلمات والنور ام هل يستوي الاعمي والبصير ام هل يستوي الذين يعلمون والذين لا يعلمون انما يتذكر اولوا الالباب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 70, NULL, 'Are darkness and light equal? Or are the blind and the seeing equal? Or are those who know and those who do not know equal? Only those of understanding take heed.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'are darkness and light equal or are the blind and the seeing equal or are those who know and those who do not know equal only those of understanding take heed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 71, NULL, 'By the testimonies I have brought forward — outward and inward alike — it is now established that sighting is of two kinds; that choosing the more excellent of the two in fulfilling one''s obligatory duties is the better course; and that when the Prophet (ع) used the letter ل (اَللَّام) in his words لرؤيته, he intended by it the sighting of knowledge — which requires that the people already be fasting when the crescent is sighted with the eye, and not otherwise.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'by the testimonies i have brought forward outward and inward alike it is now established that sighting is of two kinds that choosing the more excellent of the two in fulfilling ones obligatory duties is the better course and that when the prophet ع used the letter ل اللام in his words لرويته he intended by it the sighting of knowledge which requires that the people already be fasting when the crescent is sighted with the eye and not otherwise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 72, NULL, 'Know this, then — and may Allah grant you success in obeying Him and obeying His friends — and take hold of the meanings of what I have set forth. Seek Allah''s help in all your affairs, and draw near to Him through sincerity of intention and of inward purpose, both in your worship of Him and in your obedience to His friends, for He is the best helper toward whatever one seeks to know of the realities. And give thanks to Allah the Exalted for every blessing that reaches you from the side of His trustees.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'know this then and may allah grant you success in obeying him and obeying his friends and take hold of the meanings of what i have set forth seek allahs help in all your affairs and draw near to him through sincerity of intention and of inward purpose both in your worship of him and in your obedience to his friends for he is the best helper toward whatever one seeks to know of the realities and give thanks to allah the exalted for every blessing that reaches you from the side of his trustees', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 73, NULL, 'Here I bring the treatise to its close, and I close it as it began — with praise belonging to Allah and with prayers upon those through whom His guidance reaches us. Nothing I have set down was mine to originate; it was only an ordering of what has been received. The fitting seal upon such a work is thanks, not claim.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'here i bring the treatise to its close and i close it as it began with praise belonging to allah and with prayers upon those through whom his guidance reaches us nothing i have set down was mine to originate it was only an ordering of what has been received the fitting seal upon such a work is thanks not claim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 74, NULL, 'Sayingوَبَعْدُ فَقَدْ خَتَمْتُ الرِّسَالَةَ بِالْحَمْدِ لِلَّهِ الْعَلِيِّ الْأَعْلَى وَبِالصَّلَاةِ عَلَى النَّبِيِّ مُحَمَّدٍ الْمُصْطَفَى وَالْوَلِيِّ عَلِيٍّ الْمُرْتَضَى وَالْأَئِمَّةِ الطَّاهِرِينَ أَقْمَارِ الدُّجَى', '', 'وَبَعْدُ فَقَدْ خَتَمْتُ الرِّسَالَةَ بِالْحَمْدِ لِلَّهِ الْعَلِيِّ الْأَعْلَى وَبِالصَّلَاةِ عَلَى النَّبِيِّ مُحَمَّدٍ الْمُصْطَفَى وَالْوَلِيِّ عَلِيٍّ الْمُرْتَضَى وَالْأَئِمَّةِ الطَّاهِرِينَ أَقْمَارِ الدُّجَى', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'sayingوبعد فقد ختمت الرساله بالحمد لله العلي الاعلي وبالصلاه علي النبي محمد المصطفي والولي علي المرتضي والايمه الطاهرين اقمار الدجي', 'وبعد فقد ختمت الرساله بالحمد لله العلي الاعلي وبالصلاه علي النبي محمد المصطفي والولي علي المرتضي والايمه الطاهرين اقمار الدجي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 75, NULL, 'I have sealed this treatise with praise of Allah, the High, the Most High, and with prayer upon the Prophet Muhammad the Chosen, upon the guardian Ali the Well-Pleasing, and upon the pure Imams, the moons amid the darkness.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'i have sealed this treatise with praise of allah the high the most high and with prayer upon the prophet muhammad the chosen upon the guardian ali the well pleasing and upon the pure imams the moons amid the darkness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 76, NULL, 'That likeness is not an ornament. Just as the moon in the night sky carries a light it has received and gives it to those who travel while others sleep, so the pure Imams stand in the darkness of the age, luminous by what has been entrusted to them and not by what they claim for themselves. The same order continues unbroken in the Imam of our own time.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'that likeness is not an ornament just as the moon in the night sky carries a light it has received and gives it to those who travel while others sleep so the pure imams stand in the darkness of the age luminous by what has been entrusted to them and not by what they claim for themselves the same order continues unbroken in the imam of our own time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 77, NULL, 'Sayingوَإِمَامِ الزَّمَانِ مَوْلَانَا وَهَادِينَا وَوَلِيِّ نِعَمِنَا الْإِمَامِ الْحَاكِمِ بِأَمْرِ اللَّهِ أَمِيرِ الْمُؤْمِنِينَ صَلَوَاتُ اللَّهِ عَلَيْهِ وَعَلَى آبَائِهِ الطَّاهِرِينَ وَأَبْنَائِهِ الْأَكْرَمِينَ الْمُنْتَظَرِينَ إِلَى يَوْمِ الدِّينِ أَفْضَلُ التَّحِيَّاتِ وَالتَّسْلِيمِ', '', 'وَإِمَامِ الزَّمَانِ مَوْلَانَا وَهَادِينَا وَوَلِيِّ نِعَمِنَا الْإِمَامِ الْحَاكِمِ بِأَمْرِ اللَّهِ أَمِيرِ الْمُؤْمِنِينَ صَلَوَاتُ اللَّهِ عَلَيْهِ وَعَلَى آبَائِهِ الطَّاهِرِينَ وَأَبْنَائِهِ الْأَكْرَمِينَ الْمُنْتَظَرِينَ إِلَى يَوْمِ الدِّينِ أَفْضَلُ التَّحِيَّاتِ وَالتَّسْلِيمِ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'sayingوامام الزمان مولانا وهادينا وولي نعمنا الامام الحاكم بامر الله امير المومنين صلوات الله عليه وعلي ابايه الطاهرين وابنايه الاكرمين المنتظرين الي يوم الدين افضل التحيات والتسليم', 'وامام الزمان مولانا وهادينا وولي نعمنا الامام الحاكم بامر الله امير المومنين صلوات الله عليه وعلي ابايه الطاهرين وابنايه الاكرمين المنتظرين الي يوم الدين افضل التحيات والتسليم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 78, NULL, 'Upon the Imam of the age — our master, our guide, and the guardian of our blessings — the Imam who rules by the command of Allah, the Commander of the Faithful: may Allah''s prayers be upon him, upon his pure forefathers, and upon his noble sons who are awaited until the Day of Judgment, the finest of greetings and salutations.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'upon the imam of the age our master our guide and the guardian of our blessings the imam who rules by the command of allah the commander of the faithful may allahs prayers be upon him upon his pure forefathers and upon his noble sons who are awaited until the day of judgment the finest of greetings and salutations', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 79, NULL, 'This is the order I have been tracing throughout: knowledge descends, obedience ascends, and the two meet in the one whom Allah has appointed. Whoever holds to that order is never left groping in the dark, for the light he walks by is not of his own making. And so the only request that remains is the request for steadfastness and for illumination, since neither lies within our power to produce.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'this is the order i have been tracing throughout knowledge descends obedience ascends and the two meet in the one whom allah has appointed whoever holds to that order is never left groping in the dark for the light he walks by is not of his own making and so the only request that remains is the request for steadfastness and for illumination since neither lies within our power to produce', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 80, NULL, 'Sayingوَنَسْأَلُ اللَّهَ أَنْ يُثَبِّتَنَا عَلَى طَاعَتِهِ وَطَاعَةِ أَوْلِيَائِهِ وَيُنَوِّرَ عُقُولَنَا وَبَصَائِرَنَا بِمَنِّهِ وَكَرَمِهِ وَقُدْرَتِهِ إِنَّهُ خَيْرُ مَسْئُولٍ وَأَكْرَمُ مَأْمُولٍ وَحَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ وَنِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ صَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ وَسَلَّمَ', '', 'وَنَسْأَلُ اللَّهَ أَنْ يُثَبِّتَنَا عَلَى طَاعَتِهِ وَطَاعَةِ أَوْلِيَائِهِ وَيُنَوِّرَ عُقُولَنَا وَبَصَائِرَنَا بِمَنِّهِ وَكَرَمِهِ وَقُدْرَتِهِ إِنَّهُ خَيْرُ مَسْئُولٍ وَأَكْرَمُ مَأْمُولٍ وَحَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ وَنِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ صَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ وَسَلَّمَ', 'Saying', NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'sayingونسال الله ان يثبتنا علي طاعته وطاعه اوليايه وينور عقولنا وبصايرنا بمنه وكرمه وقدرته انه خير مسيول واكرم مامول وحسبنا الله ونعم الوكيل ونعم المولي ونعم النصير صلي الله علي سيدنا محمد واله وسلم', 'ونسال الله ان يثبتنا علي طاعته وطاعه اوليايه وينور عقولنا وبصايرنا بمنه وكرمه وقدرته انه خير مسيول واكرم مامول وحسبنا الله ونعم الوكيل ونعم المولي ونعم النصير صلي الله علي سيدنا محمد واله وسلم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('isaf-al-talib', 'chapter', 'the sun, the moon, and the order of obedience', '33. The Sun, the Moon, and the Order of Obedience', 81, NULL, 'We ask Allah to keep us steadfast in obedience to Him and to His friends, and to illumine our minds and our inner sight through His favor, His generosity, and His power. He is the finest of all who are asked and the most generous of all in whom hope is placed. Allah is our sufficiency — the best of guardians, the best of masters, and the best of helpers. May Allah bless our master Muhammad and his family, and grant them peace.', '', NULL, NULL, NULL, NULL, 'isaf al talib fi jami al matalib 33 the sun the moon and the order of obedience', 'we ask allah to keep us steadfast in obedience to him and to his friends and to illumine our minds and our inner sight through his favor his generosity and his power he is the finest of all who are asked and the most generous of all in whom hope is placed allah is our sufficiency the best of guardians the best of masters and the best of helpers may allah bless our master muhammad and his family and grant them peace', '');
